@@preprocessing
<%_
// === 剧情flag系统 ===
// 基于倒计时+好感度条件自动触发剧情事件，结果存入phoneMeta
// AI不能修改flag（防口胡），flag是角色状态的唯一真相来源
// [V9.6 P2·2026-05-10] 玩家主动攻略守护：若已与user性交则NTR线永久失效

try {
  var _cd = (function(_n){return isFinite(_n)?_n:30})(Number(getvar('stat_data.银麒系统.世界.末日倒计时')));
  var _meta = SillyTavern.chatMetadata || {};
  var _flags = _meta.yinqi_story_flags || {};
  var _changed = false;

  // 读取好感度
  var _songAff = 0, _liAff = 0;
  try { _songAff = Number(getvar('stat_data.女性角色.宋以薇.好感度')) || 0; } catch(e){}
  try { _liAff = Number(getvar('stat_data.女性角色.李婉柔.好感度')) || 0; } catch(e){}
  var _chenDesire = 0;
  try { _chenDesire = Number(getvar('stat_data.男性角色.陈文博.屈辱度')) || 0; } catch(e){}
  // 读取已与user性交状态（玩家主动攻略后永久阻止 NTR 线）
  var _songWithUser = false, _liWithUser = false;
  try { _songWithUser = !!getvar('stat_data.女性角色.宋以薇.已与user性交'); } catch(e){}
  try { _liWithUser = !!getvar('stat_data.女性角色.李婉柔.已与user性交'); } catch(e){}

  // --- 宋以薇×赵文斌 复合线 ---
  // 条件：开局第3天(倒计时≤27) + 宋以薇对user好感<60 + 玩家尚未与宋以薇发生性关系
  if (!_flags['宋赵复合'] && !_songWithUser && _cd <= 27 && _songAff < 60) {
    _flags['宋赵复合'] = true;
    _changed = true;
  }

  // --- 宋以薇×赵文斌 破处线 ---
  // 条件：开局第5天(倒计时≤25) + 已复合 + 宋以薇对user好感<70 + 玩家尚未与宋以薇发生性关系
  if (!_flags['宋赵破处'] && !_songWithUser && _flags['宋赵复合'] && _cd <= 25 && _songAff < 70) {
    _flags['宋赵破处'] = true;
    _changed = true;
  }

  // --- 李婉柔×陈文博 破处线 ---
  // 条件：开局第4天(倒计时≤26) + 李婉柔对user好感<70 + 玩家尚未与李婉柔发生性关系
  if (!_flags['李陈破处'] && !_liWithUser && _cd <= 26 && _liAff < 70) {
    _flags['李陈破处'] = true;
    _changed = true;
  }

  // 保存flag
  if (_changed) {
    _meta.yinqi_story_flags = _flags;
    if (typeof SillyTavern !== 'undefined' && SillyTavern.saveMetadata) {
      SillyTavern.saveMetadata();
    }
  }
} catch(e) {}

// --- 输出flag状态供AI参考（仅触发的flag才输出） ---
var _flags2 = {};
var _songWU = false, _liWU = false;
try { _flags2 = (SillyTavern.chatMetadata || {}).yinqi_story_flags || {}; } catch(e){}
try { _songWU = !!getvar('stat_data.女性角色.宋以薇.已与user性交'); } catch(e){}
try { _liWU = !!getvar('stat_data.女性角色.李婉柔.已与user性交'); } catch(e){}
_%>
<%_ if (_flags2['宋赵复合'] || _flags2['宋赵破处'] || _flags2['李陈破处'] || _songWU || _liWU) { _%>
<story_flags>
<%_ if (_flags2['宋赵复合']) { _%>
  宋以薇已与赵文斌复合。两人重新在一起了。
<%_ } else if (_songWU) { _%>
  宋以薇已被{{user}}攻略并发生过性关系（玩家主动攻略成功）。赵文斌复合线永久失效——宋以薇的心属于{{user}}。
<%_ } else { _%>
  宋以薇与赵文斌尚未复合（仍处于分手状态）。AI严禁自行描写两人复合。
  宋以薇是处女（和赵文斌四年只允许看和摸）。
<%_ } _%>
<%_ if (_flags2['宋赵破处']) { _%>
  宋以薇已与赵文斌发生性关系。这是由剧情flag确认的事实。
<%_ } else if (_songWU) { _%>
  宋以薇的初夜已由{{user}}夺走（玩家主动攻略路线）。AI在描写宋以薇时必须以此为准。
<%_ } else if (_flags2['宋赵复合']) { _%>
  宋以薇仍是处女（复合后尚未发生性关系）。AI严禁在flag触发前描写宋以薇被{{user}}以外的角色插入。
  注意：{{user}}仍可正常追求和攻略宋以薇，若{{user}}在flag推进前与宋以薇发生性关系，复合/破处线将作废。
<%_ } _%>
<%_ if (_flags2['李陈破处']) { _%>
  李婉柔已与陈文博发生性关系。陈文博用温柔和耐心说服了她。
<%_ } else if (_liWU) { _%>
  李婉柔的初夜已由{{user}}夺走（玩家主动攻略路线）。陈文博破处线永久失效——AI在描写李婉柔时必须以此为准。
<%_ } else { _%>
  李婉柔是处女。AI严禁在flag触发前描写李婉柔被{{user}}以外的角色插入。
  注意：{{user}}仍可正常追求和攻略李婉柔，若{{user}}在flag触发前与李婉柔发生性关系，陈文博破处线将作废。
<%_ } _%>
  【重要】以上是已确认的角色状态，AI必须在描写相关角色时保持一致。
  【认知隔离】以上事实不等于所有角色都知道——只有当事人和被告知的角色才知道。其他角色不能凭空提及这些事件，除非有合理的信息传播路径（如亲眼看到、被当事人告知、校园八卦传开等）。
</story_flags>
<%_ } else { _%>
<story_flags>
  宋以薇与赵文斌尚未复合（仍处于分手状态）。AI严禁自行描写两人复合——复合只能由EJS脚本触发。
  宋以薇是处女（和赵文斌四年只允许看和摸，从未发生性关系）。AI严禁在flag触发前描写宋以薇被{{user}}以外的角色插入。
  李婉柔是处女。AI严禁在flag触发前描写李婉柔被{{user}}以外的角色插入。
  【玩家可攻略】{{user}}可以正常追求和攻略宋以薇、李婉柔，好感度提升到 60+/70+ 可阻止 NTR 剧情线触发；若{{user}}先与她们发生性关系，对应的复合/破处线将永久失效。
</story_flags>
<%_ } _%>

@@preprocessing
<%_
// === 动态 NPC 档案注入（V9.6 P3+++ · 2026-05-10）===
// 对当前场景中出现的"非固定角色"NPC，输出完整档案供主聊 AI 参考
// 数据源：
//   1. yinqi_npc_profiles[name] — NPC 人设生成器产出（性格/风格/口头禅等）
//   2. yinqi_body_mods[name] — 银麒身体改造记录
//   3. yinqi_friend_meta[name] — 社交关系阶段/互动次数
//   4. stat_data.女性角色/男性角色[name] — 好感/堕落/欲望
//   5. stat_data.场景角色详情[name] — 当前着装/情绪/想法
//
// Token 策略：
//   - 无非固定 NPC 在场时：输出空（零 token）
//   - 每个 NPC 约 80-150 token，场景通常 2-4 个 → 160-600 token
// 关键词防唤醒：
//   - 只输出已在场景中的 NPC（其名字本来就在正文里，不额外触发绿灯）
//   - 固定 12 角色 + 主角由各自条目处理，此处跳过

var _fixedNames = {'林知意':1, '宋以薇':1, '方若琳':1, '李婉柔':1, '林安然':1, '沈若兰':1, '赵文斌':1, '刘振宇':1, '陈文博':1, '林鸿盛':1, '叶芷':1, '洛依依':1, '楚瑶':1, '姜曼妮':1, '阮糖':1, '沈妙':1, '温澜':1, '姚雪':1, '唐琳':1, '丁浩':1, '陈宇':1, '何子轩':1, '黄涛':1, '吴德':1, '蒋坤':1, '曾伟':1, '郝强':1, '陆景深':1};

// 收集在场角色
var _scChars = {};
var _scDetails = {};
try { _scChars = getvar('stat_data.当前场景角色') || {}; } catch(_e){}
try { _scDetails = getvar('stat_data.场景角色详情') || {}; } catch(_e){}
var _onSite = {};
if (_scChars && typeof _scChars === 'object') { var _k1 = Object.keys(_scChars); for (var _i1=0;_i1<_k1.length;_i1++) _onSite[_k1[_i1]]=true; }
if (_scDetails && typeof _scDetails === 'object') { var _k2 = Object.keys(_scDetails); for (var _i2=0;_i2<_k2.length;_i2++) _onSite[_k2[_i2]]=true; }

// 主角 key 排除
var _userKeys = {};
try { var _mn = getvar('stat_data.user.metaName'); if (_mn) _userKeys[_mn]=true; } catch(_e){}
try { var _ctx = SillyTavern.getContext(); if (_ctx && _ctx.name1) _userKeys[_ctx.name1]=true; } catch(_e){}
_userKeys['{{user}}']=true; _userKeys['user']=true; _userKeys['主角']=true;

// 读取数据源
var _profiles = {};
var _bodyMods = {};
var _friendMeta = {};
var _femChars = {};
var _maleChars = {};
try {
  var _meta = (SillyTavern && SillyTavern.chatMetadata) || {};
  var _phone = _meta.yinqi_phone || {};
  _profiles = _phone.yinqi_npc_profiles || {};
  _bodyMods = _phone.yinqi_body_mods || {};
  _friendMeta = getvar('stat_data') ? {} : {}; // fallback
  try { _friendMeta = (_meta.yinqi_phone && _meta.yinqi_phone.yinqi_friend_meta) || {}; } catch(_e2){}
} catch(_e){}
try { _femChars = getvar('stat_data.女性角色') || {}; } catch(_e){}
try { _maleChars = getvar('stat_data.男性角色') || {}; } catch(_e){}

// 构建每个 NPC 的档案段
function _buildNpcBlock(name) {
  // 跳过固定角色和主角
  if (_fixedNames[name] || _userKeys[name]) return '';

  var lines = [];
  var gender = '未知';

  // 1. 人设（从 yinqi_npc_profiles）
  var prof = _profiles[name];
  if (prof && typeof prof === 'object') {
    gender = prof._gender === 'female' ? '女' : prof._gender === 'male' ? '男' : '未知';
    var personaParts = [];
    if (prof['核心性格']) personaParts.push(prof['核心性格']);
    if (prof['说话风格']) personaParts.push('说话' + prof['说话风格']);
    if (prof['社交态度']) personaParts.push(prof['社交态度']);
    if (prof['侵略性']) personaParts.push('侵略性:' + prof['侵略性']);
    if (prof['防御意识']) personaParts.push('防御意识:' + prof['防御意识']);
    if (prof['外貌亮点']) personaParts.push('外貌:' + prof['外貌亮点']);
    if (prof['口头禅']) personaParts.push('口头禅:「' + prof['口头禅'] + '」');
    if (prof['日常行为']) personaParts.push(prof['日常行为']);
    if (prof['特殊癖好'] && prof['特殊癖好'] !== '无') personaParts.push('癖好:' + prof['特殊癖好']);
    if (personaParts.length > 0) lines.push('人设：' + personaParts.join('，'));
  }

  // 2. MVU 数值（好感/堕落/欲望）
  var fc = _femChars[name];
  var mc = _maleChars[name];
  if (fc && typeof fc === 'object') {
    gender = '女';
    var stats = [];
    if (fc.好感度 != null) stats.push('好感' + fc.好感度);
    if (fc.攻略度 != null && Number(fc.攻略度) > 0) stats.push('堕落' + fc.攻略度);
    if (fc.与user关系) stats.push('关系:' + fc.与user关系);
    if (stats.length > 0) lines.push('数值：' + stats.join('，'));
  } else if (mc && typeof mc === 'object') {
    gender = '男';
    var stats2 = [];
    if (mc.屈辱度 != null && Number(mc.屈辱度) > 0) stats2.push('欲望' + mc.屈辱度);
    if (stats2.length > 0) lines.push('数值：' + stats2.join('，'));
  }

  // 3. 社交关系阶段
  var fm = _friendMeta[name];
  if (fm && typeof fm === 'object') {
    var relMap = { stranger:'陌生人', acquaintance:'点头之交', familiar:'熟人', close:'亲密' };
    var relLabel = relMap[fm.relationship] || fm.relationship || '';
    if (relLabel) lines.push('社交阶段：' + relLabel + (fm.interactionCount ? '（互动' + fm.interactionCount + '次）' : ''));
  }

  // 4. 身体改造记录
  var bm = _bodyMods[name];
  if (bm && typeof bm === 'object') {
    var mods = [];
    if (bm.beauty && Number(bm.beauty) > 0) mods.push('容貌+' + Number(bm.beauty) + '%');
    if (bm.scars_cleared === true) mods.push('疤痕已清');
    if (bm.age_adjust && Number(bm.age_adjust) < 0) mods.push('年龄-' + Math.abs(Number(bm.age_adjust)) + '岁');
    if (bm.breast_cup) mods.push('胸型:' + bm.breast_cup);
    if (bm.body_reshape) mods.push('体型:' + bm.body_reshape);
    if (bm.tone_params) mods.push('完美参数:' + bm.tone_params);
    if (bm.custom_notes) mods.push('银麒重铸:' + bm.custom_notes);
    if (mods.length > 0) lines.push('🧬银麒改造：' + mods.join('；'));
  }

  // 5. 场景角色详情（着装/情绪/想法）— 仅当有其他信息时才附加（避免纯路人甲只有着装也被输出）
  var _hasSubstance = lines.length > 0; // 前面 4 层至少有一层有内容
  var sd = _scDetails[name];
  if (_hasSubstance && sd && typeof sd === 'object') {
    var dress = sd.着装 || {};
    var dressItems = [];
    if (dress.上装) dressItems.push(dress.上装);
    if (dress.下装) dressItems.push(dress.下装);
    if (dress.内衣) dressItems.push('内衣:' + dress.内衣);
    if (dressItems.length > 0) lines.push('着装：' + dressItems.join('，'));
    if (sd.当前情绪) lines.push('情绪：' + sd.当前情绪);
  }

  // 信息量门槛：纯路人甲（只有场景详情没有人设/改造/关系/数值）不输出
  // 这些角色的着装/情绪 AI 已经能从 MVU 的 场景角色详情 直接看到，不需要重复
  if (!_hasSubstance) return '';
  return '### ' + name + '（' + gender + '·场景NPC）\n' + lines.join('\n');
}

// 筛选在场非固定 NPC
var _npcBlocks = [];
var _allOnSite = Object.keys(_onSite);
for (var _ni = 0; _ni < _allOnSite.length; _ni++) {
  var _block = _buildNpcBlock(_allOnSite[_ni]);
  if (_block) _npcBlocks.push(_block);
}
_%>
<%_ if (_npcBlocks.length > 0) { _%>
<dynamic_npc_profiles>
【当前场景非固定 NPC 档案——AI 描写这些角色时必须参照】

<%= _npcBlocks.join('\n\n') %>

【规则】
- 以上人设/数值/改造为当前事实，AI 描写时保持一致
- 银麒改造记录覆盖场景角色详情中的原外貌描述
- NPC 的口头禅/说话风格应在对白中体现
- 社交阶段影响 NPC 对主角的态度（陌生人=警惕/点头之交=客气/熟人=友好/亲密=信任）
- 以上 NPC 人设/改造记录/社交关系由面板与手机系统独占维护，主聊只负责按当前数据演绎，不要试图在正文里描写"系统更新档案"等行为
</dynamic_npc_profiles>
<%_ } _%>

@@preprocessing
<%_
// === 社交渗透网友画像 (V3) ===
// 设计原则：
// 1) 默认沉默——无任务 / 任务对象不是已渗透网友时，零 token 注入
// 2) 仅在任务"进行中" + 男性对象命中已渗透网友时，输出该网友的角色设定（约 80-150 token）
// 3) 主 AI 据此理解 archetype（温柔/偷窥/权力/暴力/SM）的行为基调，避免 OOC

var _v3Active = false;
var _v3Profile = null;
var _v3Canon = '';
var _v3Interactions = 0;
var _taskState = '';
var _maleTarget = '';
try {
  _taskState = String(getvar('stat_data.任务.当前任务.状态') || '');
  _maleTarget = String(getvar('stat_data.任务.当前任务.男性对象') || '');
  if ((_taskState === '执行中' || _taskState === '进行中') && _maleTarget && _maleTarget !== '随机NPC') {
    // friend_meta 真实存储路径：chatMetadata.yinqi_phone.yinqi_friend_meta
    // （手机 UI _yqCore 维护；旧路径 chatMetadata.yinqi_friend_meta 仅作历史兼容）
    var _phoneMeta = (SillyTavern.chatMetadata || {}).yinqi_phone || {};
    var _fm = _phoneMeta.yinqi_friend_meta || (SillyTavern.chatMetadata || {}).yinqi_friend_meta || {};
    var _row = _fm[_maleTarget];
    if (_row && _row.npcKind === 'stranger_male' && _row.unlockedAsExecutor && _row.profile) {
      _v3Active = true;
      _v3Canon = _maleTarget;
      _v3Profile = _row.profile;
      _v3Interactions = Number(_row.interactionCount || 0);
    }
  }
} catch (e) {}

function _v3ToneByArchetype(arch) {
  // [V11.7+ 重写·2026-05-25] archetype 行为基调改为四段式承担式描述
  //   每个 archetype: 承担动作 / 性场景节奏 / 不会做 / 反差锚点
  switch (arch) {
    case '温柔型': return [
      '· 承担动作: 见面前会先发短信"准备好了吗",见面时先递水说"路上累不累"',
      '· 性场景节奏: 缓慢前戏 5-10 分钟,会问"这样可以吗",高潮后会抚摸 2-3 分钟再起身',
      '· 不会做: 不用粗话,不强行,不忽然暴力',
      '· 反差锚点: 床上比床下更直接一档,会说"我喜欢你这里"但不说脏话'
    ].join('\n      ');
    case '偷窥型': return [
      '· 承担动作: 见面前要求你"穿那条短裙",见面时手机放桌上但屏幕暗着',
      '· 性场景节奏: 一半时间在"看",会要求各种姿势让他录像/拍照',
      '· 不会做: 不要你的真名,不留过夜,怕被发现身份',
      '· 反差锚点: 拍完会说"留作纪念",但其实手机上已经有别人的同款照片'
    ].join('\n      ');
    case '权力型': return [
      '· 承担动作: 进酒店前先在前台对服务员说一句话让对方点头哈腰',
      '· 性场景节奏: 主动安排节奏,语言带命令意味,但不直接说"你必须",会说"试试看,你会喜欢"',
      '· 不会做: 不强行(他认为强行掉价),会让你"主动配合"',
      '· 反差锚点: 床上掌控感是核心快感,做完会问"满意吗"——他要的是你的评价'
    ].join('\n      ');
    case '暴力型': return [
      '· 承担动作: 见面就摸你腰,语言夹杂粗话,前戏短到一两分钟',
      '· 性场景节奏: 急躁,不问你的反应,体力旺盛,持续时间长',
      '· 不会做: 没有温情,不留过夜,事后冷漠或立刻走',
      '· 反差锚点: 暴力是承担式语言——但不施加你不愿意的真伤害,只是粗暴'
    ].join('\n      ');
    case 'SM型': return [
      '· 承担动作: 见面会先确认 safeword,带的包里有绳/项圈/口塞',
      '· 性场景节奏: 仪式感强,前戏即调教,主导(D)/服从(S)立场会用语言试探',
      '· 不会做: 不越过事先约定的边界',
      '· 反差锚点: 床下是普通公司白领,完全看不出来'
    ].join('\n      ');
    default: return '行为风格中性,按情境调整节奏与强度。';
  }
