<%_
// === 据点交互规则 ===
// 读取据点数据 — 真实存储路径是 chatMetadata.yinqi_phone.yinqi_outposts
// （系统面板 _yqCore.snapshot 同步写入；旧路径 chatMetadata.yinqi_outposts 仅作历史兼容）
var _op = null, _opBase = null, _hasBase = false;
try {
  var _pm = (SillyTavern.chatMetadata || {}).yinqi_phone || {};
  _op = _pm.yinqi_outposts || (SillyTavern.chatMetadata || {}).yinqi_outposts;
  if (_op) _opBase = _op.playerBase;
  _hasBase = !!(_opBase && _opBase.location);
} catch(e) {}

// 读取当前地点
var _curLoc = ''; try { _curLoc = getvar('stat_data.银麒系统.世界.地点') || ''; } catch(e) {}

// 判断玩家是否在自己据点
var _atMyBase = _hasBase && _curLoc.indexOf(_opBase.location) >= 0;

// 判断玩家是否在某个NPC据点
var _atNpc = null, _npcInfo = null;
if (_op && _op.npcData) {
  for (var _nk in _op.npcData) {
    if (_op.npcData.hasOwnProperty(_nk) && _curLoc.indexOf(_nk) >= 0) {
      _atNpc = _nk; _npcInfo = _op.npcData[_nk]; break;
    }
  }
}
var _cd = (function(_n){return isFinite(_n)?_n:30})(Number(getvar('stat_data.银麒系统.世界.末日倒计时')));

// 关系值→档位
function _relLabel(v) { return v < 20 ? '敌对' : v < 40 ? '警惕' : v < 60 ? '中立' : v < 80 ? '友好' : '同盟'; }

// 屏障等级→罗马数字
var _shieldRoman = ['','Ⅰ','Ⅱ','Ⅲ','Ⅳ','Ⅴ','Ⅵ'];

// 玩家据点资源状态强标签：给 AI 一个生活感受结论，避免只看裸数字或末日通用匮乏描写
var _resourceStatusLine = '';
try {
  if (_hasBase && _opBase && _opBase.resources) {
    var _ratio = _cd > 0 ? 0 : (_cd <= -7 ? 1 : Math.abs(_cd) / 7);
    var _cons = { food: 0, water: 0 };
    var _members = Array.isArray(_opBase.members) ? _opBase.members : [];
    function _memberNeed(m) {
      var t = String((m && m.type) || 'member');
      if (t === 'leader' || t === 'core') return { food: 1.5, water: 2.0 };
      if (t === 'member') return { food: 1.2, water: 1.8 };
      if (t === 'worker') return { food: 1.5, water: 2.5 };
      if (t === 'newcomer' || t === 'shelter') return { food: 1.0, water: 1.5 };
      if (t === 'prisoner') return { food: 0.6, water: 1.2 };
      if (t === 'slave') return { food: 0.4, water: 1.0 };
      return { food: 1.0, water: 1.5 };
    }
    _members.forEach(function (m) {
      var n = _memberNeed(m);
      _cons.food += n.food;
      _cons.water += n.water;
    });
    var _needFood = _cons.food * _ratio;
    var _needWater = _cons.water * _ratio;
    var _food = Number(_opBase.resources.food) || 0;
    var _water = Number(_opBase.resources.water) || 0;
    var _foodDays = _needFood > 0 ? Math.floor(_food / Math.max(0.01, _needFood)) : 999;
    var _waterDays = _needWater > 0 ? Math.floor(_water / Math.max(0.01, _needWater)) : 999;
    var _minDays = Math.min(_foodDays, _waterDays);
    if (_ratio === 0) {
      _resourceStatusLine = '【资源充裕】当前为末日前/爆发当天零消耗期，储备无压力；正文不得描写缺粮缺水。';
    } else if (_food === 0 || _water === 0 || _minDays < 3) {
      _resourceStatusLine = '【资源紧急】按当前实际日耗，食物约可维持' + _foodDays + '天，饮水约可维持' + _waterDays + '天；可以描写明显危机。';
    } else if (_minDays < 7) {
      _resourceStatusLine = '【资源偏紧】按当前实际日耗，食物约可维持' + _foodDays + '天，饮水约可维持' + _waterDays + '天；可写节约配给，但不得写已经断粮断水。';
    } else {
      _resourceStatusLine = '【资源充裕】按当前实际日耗，食物约可维持' + _foodDays + '天，饮水约可维持' + _waterDays + '天；正文应体现生活稳定，不得描写缺粮缺水。';
    }
  }
} catch (_resE) {}
_%>
