scripts.content:
/**
 * 银麒系统值守卫 v1.3 — 拦截 AI 对面板独占路径的违规变量补丁
 *
 * 机制：
 *   监听 MVU 的 VARIABLE_UPDATE_ENDED 事件，在 AI 补丁应用后检查关键字段
 *   是否被擅自修改，若是则用旧值回填，并打印警告。
 *
 * 白名单（AI 不得修改，面板/脚本独占）—— v1.3 基线共 27 条独占路径：
 *   ▼ 账户字段（4）：
 *     - 银麒系统.账户.银麒点 / 系统等级 / 当前经验 / 下一级所需
 *   ▼ 任务元数据（9）：
 *     - 任务.当前任务.{状态, 种子ID, 等级, 描述, 执行者, 副执行者,
 *                       男性对象, 参与模式, 最终奖励}
 *   ▼ user 装备/能力（2）：
 *     - user.装备 / user.能力
 *   ▼ Schema 版本（1）：
 *     - _schemaVersion
 *   ▼ V5.§5 变性字段（5，面板独占写入）：
 *     - user.{gender, genderTrueHistory, genderChangedAt, genderSeamless, 魅魔能力激活}
 *   ▼ V3.§2.6 主角脆弱性（2） + V3.§2.11 POV 兼容位（3）：
 *     - user.{hp_max, infected_since, metaName, metaGender}
 *     - 银麒系统.绑定者
 *
 * 另有：
 *   - user.背包：整体回滚（任何子路径变化 → 回滚整个背包）
 *   - 大范围清空保护：女性角色 / 男性角色 / 银麒系统.档案（旧非空 + 新整体空 → 回滚）
 *   - V3.§2.6 脆弱性校验：HP +50 禁 / HP=0 复活禁 / infected 倒退禁 / injuries 凭空清空禁
 *   - V2.§4.9 身边人改造字段保护：`_cp_bonus / _skills / _tasks_completed / _skip_cp_cap`
 *     挂在 user / 角色.林知意 / 女性角色.* / 男性角色.* 下 → 面板独占
 *   - V6.§6 暗攻略字段保护：`unbeknownst_violated / violator / violated_at /
 *     violation_type / violation_count / violation_discovered_by_user /
 *     violation_discovered_at / violation_pregnancy_risk /
 *     violation_marked_by_user / violation_history` 10 后缀
 *     挂在 角色.林知意 / 女性角色.* 下 → 面板独占
 *   - 数组硬上限（v1.3 新）：combat_log ≤ 10 / injuries ≤ 20 / status_effects ≤ 20
 *     超过自动 slice(-cap) 并记录
 *   - violation_history 硬上限（v1.3 新）：林知意 + 女性角色 record 统一 cap=30，
 *     与面板侧 slice(-30) 对齐
 *   - toastr 5 秒限流（v1.3 新）：同一轮多条回滚时 toastr 最多 1 条，console.warn 不限
 *
 * 不拦截（AI 允许修改）：
 *   - 任务.当前任务.进度 / 执行摘要
 *   - user.当前想法 / user.鸡巴状态 / user.着装 / user.状态（健康/轻伤…）
 *   - user.hp / user.infected / user.injuries / user.status_effects / user.combat_log
 *     （有合理性校验但允许剧情推进）
 *   - 角色.林知意.{装备, 状态, 能力, 攻略度, 身心状态}（不含 V6 violation_* 后缀）
 *   - 女性角色.{name}.{好感度, 攻略度, 与user关系, 已与user性交, 姓名, 昵称,
 *                    装备, 状态, 能力}（不含 V2/V6 后缀）
 *   - 男性角色.{name}.{屈辱度, 姓名, 昵称, 装备, 状态, 能力}（不含 V2 后缀）
 *   - 银麒系统.世界.* / 银麒系统.档案.* / 银麒系统.监控.*
 *   - 当前场景角色.* / 场景角色详情.*
 *
 * [V9.6 额外硬约束]:
 *   - `女性角色.林知意` 任意值写入 → 整节点删除（林知意真源是 角色.林知意）
 *   - `角色.林知意.攻略度` / `女性角色.*.攻略度` new < old → 回滚为 old（只增不减）
 *     · 面板 setVar 绕过 MVU 事件，不受此守卫影响（堕落清洗仪仍能正常扣减）
 *     · 例外：Schema clamp 老存档 100+ → 100 不视为违规
 *   - `角色.林知意.已与user性交` / `女性角色.*.已与user性交` old=true 且 new=false → 回滚为 true
 *     · 规则来源：[mvu_update]变量更新规则.yaml:329 "一旦为true不可逆（永久标记）"
 *     · 防止 AI 误判语境把 true 改成 false 导致执行者系数/做爱符号丢失
 *   - `角色.林知意.攻略度` / `女性角色.*.攻略度` AI 上限 90：new > 90 且 old ≤ 90 → 截断为 90
 *     · 规则来源：玩家反馈"分段递减 AI 不遵守"，要求锁死 AI 能写的上限
 *     · 面板 setVar（堕落清洗仪 / 未来道具）绕过 MVU 事件，可突破 90 推到 91-100
 *
 * 与现有机制的关系：
 *   - 面板 setVar 直接写 stat_data，不经 MVU 事件，不受此守卫影响（正常工作）
 *   - 原有 guard.updateSnapshot 仍然负责灾难恢复（MVU 丢失时从快照回填），与本守卫互补
 *   - 对存档无影响：只拦截未来 patch，不修改历史数据
 *
 * 失败安全：
 *   - 全部逻辑 try-catch 包裹
 *   - 初始化失败或事件回调异常只打 console，不抛错
 *   - 即使失败也不影响 AI 生成流程
 *
 * 版本历史：
 *   - v1.0 初版：17 条独占路径 + 背包整体回滚
 *   - v1.1（2026-04-19）：补大范围清空保护
 *   - v1.2（2026-04-20）：V3.§2.6 脆弱性校验 + V2.§4.9 身边人字段保护
 *   - v1.3（2026-04-22）：V5 变性 5 路径扩容 + V6 暗攻略后缀保护 + 数组硬上限 +
 *                           violation_history cap + toastr 5 秒限流
 *   - V6.5.2（2026-04-24）：诊断扩展 —— 守卫内新增环形 buffer（30 条）记录最近
 *                           拦截详情；toastr 文案升级指引玩家走 `_yqGuardReport()`
 *                           父页控制台自助诊断 MVU 模式错配；按路径后缀/前缀自动
 *                           分类（账户独占/V2 身边人/V6 暗攻略/数组上限/脆弱性...）
 */
(async () => {
  try {
    // 等待 MVU 初始化
    if (typeof waitGlobalInitialized === "function") {
      await waitGlobalInitialized("Mvu");
    }

    if (
      typeof eventOn !== "function" ||
      typeof Mvu !== "object" ||
      !Mvu ||
      !Mvu.events
    ) {
      try {
        console.warn(
          "[银麒守卫] 环境不可用（eventOn / Mvu.events 缺失），守卫未启用",
          typeof eventOn,
          typeof Mvu,
        );
      } catch (_e) {}
      return;
    }

    // [V5/§5] 变性字段：面板独占写入
    var V5_GENDER_PATHS = [
      "stat_data.user.gender",
      "stat_data.user.genderTrueHistory",
      "stat_data.user.genderChangedAt",
      "stat_data.user.genderSeamless",
      "stat_data.user.魅魔能力激活",
    ];

    // 面板/EJS脚本独占字段（AI 不得修改）
    var READ_ONLY_PATHS = [
      "stat_data.银麒系统.账户.银麒点",
      "stat_data.银麒系统.账户.系统等级",
      "stat_data.银麒系统.账户.当前经验",
      "stat_data.银麒系统.账户.下一级所需",
      "stat_data.任务.当前任务.状态",
      "stat_data.任务.当前任务.种子ID",
      "stat_data.任务.当前任务.等级",
      "stat_data.任务.当前任务.描述",
      "stat_data.任务.当前任务.执行者",
      "stat_data.任务.当前任务.副执行者",
      "stat_data.任务.当前任务.男性对象",
      "stat_data.任务.当前任务.参与模式",
      "stat_data.任务.当前任务.最终奖励",
      // [V10.2·2026-05-15 P1-7] 执行摘要由面板独占生成（[mvu_update] 文档说 AI 不需要写）
      "stat_data.任务.当前任务.执行摘要",
      "stat_data.user.装备",
      "stat_data.user.能力",
      "stat_data._schemaVersion",
      // [V3.§2.6 / V3.§2.11] 面板独占写入（AI 不得修改）
      "stat_data.user.hp_max",
      "stat_data.user.infected_since",
      "stat_data.银麒系统.绑定者",
      "stat_data.user.metaName",
      "stat_data.user.metaGender",
      // [V7.3.1] 道具.待使用 由面板独占清空，AI 不得修改
      "stat_data.道具.待使用",
      // [V11.9·2026-05-27] user 装备槽改为受 §9.5 装备校验保护(允许 AI patch + 必须背包持有 + 自动扣减)
      // 旧 V10: user._weapon/_armor/_special/_pet 在 READ_ONLY 拦截 — 已废止
      // 新规则: user 享受与 NPC 同等链路 — 玩家正文口令"我装备 X"时,extra 写补丁,守卫扣减背包
      // user._abilities / user._skills 仍是面板独占(能力/技能槽全角色面板独占,见 V2_PROTECTED_SUFFIXES)
      "stat_data.user._abilities",
    ];
    READ_ONLY_PATHS = READ_ONLY_PATHS.concat(V5_GENDER_PATHS);

    // user.背包 的子路径全部拦截（用前缀匹配）
    var BACKPACK_PREFIX = "stat_data.user.背包";

    // [v1.1 新增] 大范围清空保护：这些 record 如果 old 非空但 new 被整体清空 → 回滚
    // 注意：`当前场景角色` / `场景角色详情` 属于可合法清空的路径（场景切换时），不在此列表
    var BULK_PROTECT_PATHS = [
      "stat_data.女性角色",
      "stat_data.男性角色",
      "stat_data.银麒系统.档案",
    ];

    // [v1.2 新增 V3.§2.6] 主角脆弱性校验：防止 AI 凭空回满 HP / 回退感染 / 复活死者
    // - HP 单轮 +50 以上（无外部事件）→ 回滚为 old
    // - infected 从严重状态回退到轻微状态 → 回滚
    // - hp=0 死亡后复活（hp > 0）→ 回滚为 0，同时触发 POV hook
    var INFECTED_ORDER = { clean: 0, latent: 1, acute: 2, turning: 3 };

    // [v2 新增 §4.9] 身边人改造/能力字段——面板独占
    // 保护的后缀（挂在每个角色对象下）
    var V2_PROTECTED_SUFFIXES = [
      "_cp_bonus",
      "_skills",
      "_tasks_completed",
      "_skip_cp_cap",
      // [V9.6 P3·2026-05-10] 任务奖励倍率加成字段：面板独占写入
      "_nsfw_reward_bonus",
