@keyframes slideIn {
    from { transform: translateX(100%); }
    to { transform: translateX(0); }
}

.app-header {
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 15px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(0, 0, 0, 0.1);
    flex-shrink: 0;
}

.back-button {
    background: none;
    border: none;
    cursor: pointer;
    padding: 8px;
    border-radius: 50%;
    transition: background 0.2s ease;
    font-size: 20px;
    color: #2d3748;
}

.back-button:hover {
    background: rgba(0, 0, 0, 0.1);
}

.app-title {
    font-size: 16px;
    font-weight: 600;
    color: #2d3748;
}

.app-body {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 15px;
    background: #f8f9fa;
    color: #1a1a1a;
    transition: opacity 0.2s ease-in-out;
    overscroll-behavior: contain;
}

/* ==================== 列表项样式 ==================== */
.list-item {
    background: #fff;
    border-radius: 12px;
    padding: 15px;
    margin-bottom: 12px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    list-style: none;
    color: #1a1a1a;
}

.list-item-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.list-item-name {
    font-size: 14px;
    font-weight: 600;
    color: #2d3748;
}

.list-item-value {
    font-size: 14px;
    font-weight: 600;
    color: #10b981;
}

.list-item-desc {
    font-size: 12px;
    color: #6b7280;
    line-height: 1.5;
}

/* 好友列表项 hover 效果 */
.friend-item:hover {
    background: #fef3f2 !important;
    box-shadow: 0 4px 12px rgba(236, 72, 153, 0.15) !important;
    transform: translateY(-1px);
}

/* 论坛帖子项 hover 效果 */
.forum-post-item:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.12) !important;
}

.forum-post-item:active {
    transform: translateY(0) !important;
}

.friend-item:active {
    transform: translateY(0);
}

.empty-message {
    text-align: center;
    padding: 40px 20px;
    color: #9ca3af;
    font-size: 14px;
}

/* ==================== 聊天界面样式 ==================== */
.chat-panel {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: #ffffff !important;
    z-index: 200 !important;
    display: none;
    flex-direction: column;
    animation: slideIn 0.3s;
}

.chat-panel.active {
    display: flex;
}

.chat-header {
    height: 44px;
    display: flex;
    align-items: center;
    padding: 0 12px;
    background: #ebebeb;
    border-bottom: 1px solid #d9d9d9;
    flex-shrink: 0;
}

.chat-messages {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    background: #ebebeb;
    overscroll-behavior: contain;
}

.message-item {
    margin-bottom: 2px;
    display: flex;
}

.message-item.mine {
    justify-content: flex-end;
}

.message-item.other {
    justify-content: flex-start;
}

.message-bubble {
    max-width: 70%;
    padding: 8px 12px;
    border-radius: 4px;
    word-wrap: break-word;
}

.message-item.mine .message-bubble {
    background: #95ec69;
    color: #000;
}

.message-item.other .message-bubble {
    background: white;
    color: #2d3748;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.message-sender {
    font-size: 11px;
    color: #9ca3af;
    margin-bottom: 3px;
}

.message-time {
    font-size: 10px;
    opacity: 0.8;
    margin-top: 5px;
    color: inherit;
}

.chat-input-area {
    height: 50px;
    background: #f5f5f5;
    border-top: 1px solid #d9d9d9;
    display: flex;
    align-items: center;
    padding: 8px 10px;
    gap: 8px;
    flex-shrink: 0;
}

.chat-input {
    flex: 1;
    height: 36px;
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 0 10px;
    font-size: 14px;
    outline: none;
    transition: border-color 0.2s;
    background: #ffffff;
    color: #1f2937;
}

.chat-input:focus {
    border-color: #07c160;
    background: #ffffff;
}

.chat-input::placeholder {
    color: #b2b2b2;
    opacity: 1;
}

.chat-send-btn {
    width: 60px;
    height: 36px;
    border-radius: 4px;
    background: #07c160;
    color: white;
    border: none;
    cursor: pointer;
    font-size: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    box-shadow: 0 2px 8px rgba(102, 126, 234, 0.3);
}

.chat-send-btn:hover:not(:disabled) {
    transform: scale(1.1);
}

.chat-send-btn:active:not(:disabled) {
    transform: scale(0.94);
    box-shadow: 0 1px 4px rgba(7, 193, 96, 0.35);
}

/*  发送中状态 - 变暗、变矩形 */
.chat-send-btn:disabled {
    cursor: not-allowed;
    opacity: 0.6 !important;
    background: #6c757d !important; /* 灰色背景 */
    border-radius: 8px !important; /* 变成矩形（圆角矩形） */
    transform: none !important;
    box-shadow: none !important;
}

/* 发送中状态的矩形图标动画 */
.chat-send-btn .fa-stop {
    animation: pulse 1s ease-in-out infinite;
}

@keyframes pulse {
