/* ==================== 通用组件类（高保真复刻基建） ==================== */

/* iOS 风格分组容器 */
#mobile-phone-overlay .yq-list-group {
    background: var(--yq-ios-card);
    border-radius: 12px;
    overflow: hidden;
    margin-bottom: 35px;
}
#mobile-phone-overlay .yq-list-group__header {
    font-size: 13px;
    color: var(--yq-ios-secondary-text);
    text-transform: uppercase;
    padding: 8px 16px 6px;
    letter-spacing: 0.02em;
}
/* 通用列表行 */
#mobile-phone-overlay .yq-list-row {
    display: flex;
    align-items: center;
    min-height: 44px;
    padding: 0 16px;
    background: var(--yq-ios-card);
    position: relative;
    cursor: pointer;
    transition: background 0.15s;
    gap: 12px;
}
#mobile-phone-overlay .yq-list-row:active {
    background: rgba(0,0,0,0.04);
}
#mobile-phone-overlay .yq-list-row + .yq-list-row::before {
    content: '';
    position: absolute;
    top: 0;
    left: 56px;
    right: 0;
    height: 0.5px;
    background: var(--yq-ios-separator);
}
#mobile-phone-overlay .yq-list-row__icon {
    width: 29px;
    height: 29px;
    border-radius: 7px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 15px;
    color: #fff;
}
#mobile-phone-overlay .yq-list-row__body {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
}
#mobile-phone-overlay .yq-list-row__title {
    font-size: 17px;
    color: var(--yq-text);
    line-height: 1.3;
}
#mobile-phone-overlay .yq-list-row__subtitle {
    font-size: 13px;
    color: var(--yq-ios-secondary-text);
    line-height: 1.3;
}
#mobile-phone-overlay .yq-list-row__value {
    font-size: 17px;
    color: var(--yq-ios-secondary-text);
    flex-shrink: 0;
}
#mobile-phone-overlay .yq-list-row__chevron {
    flex-shrink: 0;
    font-size: 14px;
    color: #c7c7cc;
    margin-left: 4px;
}
#mobile-phone-overlay .yq-list-row__chevron::after {
    content: '\\203A';
    font-size: 20px;
    font-weight: 300;
}

/* 头像组件 */
#mobile-phone-overlay .yq-avatar {
    --yq-avatar-size: 40px;
    width: var(--yq-avatar-size);
    height: var(--yq-avatar-size);
    border-radius: 50%;
    object-fit: cover;
    flex-shrink: 0;
    background: #e5e7eb;
}
#mobile-phone-overlay .yq-avatar--square {
    border-radius: calc(var(--yq-avatar-size) * 0.18);
}
#mobile-phone-overlay .yq-avatar--xs { --yq-avatar-size: 28px; }
#mobile-phone-overlay .yq-avatar--sm { --yq-avatar-size: 36px; }
#mobile-phone-overlay .yq-avatar--lg { --yq-avatar-size: 48px; }
#mobile-phone-overlay .yq-avatar--xl { --yq-avatar-size: 56px; }

/* 角标 */
#mobile-phone-overlay .yq-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 9px;
    background: #ef4444;
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
}
#mobile-phone-overlay .yq-badge--dot {
    min-width: 8px;
