#image-viewer .yq-viewer-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 10px 16px;
    margin: 0;
    border: none;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.2;
    cursor: pointer;
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
    transition: opacity 0.15s ease, transform 0.12s ease;
}
#image-viewer .yq-viewer-btn:active {
    opacity: 0.88;
    transform: scale(0.98);
}
#image-viewer .yq-viewer-btn--violet {
    background: rgba(139, 92, 246, 0.88);
    color: #fff;
    box-shadow: 0 2px 10px rgba(124, 58, 237, 0.35);
}
#image-viewer .yq-viewer-btn--danger {
    background: rgba(239, 68, 68, 0.88);
    color: #fff;
    box-shadow: 0 2px 10px rgba(220, 38, 38, 0.35);
}
#image-viewer .yq-viewer-btn--success {
    background: rgba(16, 185, 129, 0.88);
    color: #fff;
    box-shadow: 0 2px 10px rgba(5, 150, 105, 0.3);
}
#image-viewer .yq-viewer-btn--ghost {
    padding: 10px 20px;
    font-size: 16px;
    background: rgba(255, 255, 255, 0.18);
    color: #fff;
    border: 1px solid rgba(255, 255, 255, 0.22);
}
#image-viewer .yq-viewer-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 10;
    width: 40px;
    height: 40px;
    margin: 0;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: 50%;
    font-size: 20px;
    line-height: 1;
    color: #fff;
    cursor: pointer;
    background: rgba(255, 255, 255, 0.15);
    -webkit-tap-highlight-color: transparent;
    transition: opacity 0.15s ease, transform 0.12s ease, background 0.15s ease;
}
#image-viewer .yq-viewer-nav:active {
    opacity: 0.9;
    transform: translateY(-50%) scale(0.96);
    background: rgba(255, 255, 255, 0.22);
}
#image-viewer .yq-viewer-nav--left {
    left: 8px;
}
#image-viewer .yq-viewer-nav--right {
