  if (!cfg.enabled) return { allowed: true, reason: "disabled" };
  var now = Date.now();
  var o = opts || {};
  var runtime = yqGetCharRuntimeStates();
  var st = runtime[cid] || {};
  var live = st.live || null;
  if (
    cfg.livePriority &&
    live &&
    live.isLive &&
    ["chat", "moments", "forum"].indexOf(ch) >= 0
  ) {
    return { allowed: false, reason: "live_active" };
  }
  var lockMap = _yqGetCharChannelLockMap();
  var rec = lockMap[cid] || {};
  var lastAt = Number(rec.lastAt || 0);
  var lastCh = String(rec.lastChannel || "");
  var delta = now - lastAt;
  if (lastAt > 0 && delta >= 0) {
    if (lastCh === ch && delta < Number(cfg.sameChannelWindowMs || 30000)) {
      return { allowed: false, reason: "same_channel_cooldown" };
    }
    if (
      lastCh &&
      lastCh !== ch &&
      delta < Number(cfg.crossChannelWindowMs || 90000)
