  if (liveCount <= 0) return { allowed: true, reason: "ok" };
  if (m === "live") {
    if (cfg.strict === true && liveCount >= 2)
      return { allowed: false, reason: "live_busy_strict_live" };
    if (liveCount >= 3 && Math.random() < 0.6)
      return { allowed: false, reason: "live_busy_soft_live" };
    return { allowed: true, reason: "live_ok" };
