function buildUnifiedCharacterMemoryContext(opts) {
  var o = opts || {};
  var maxChars = Math.max(2, Math.min(10, Number(o.maxChars) || 6));
  var perCharEvents = Math.max(1, Math.min(6, Number(o.perCharEvents) || 3));
  // [V9.7·P2-b·2026-05-11] snippet 长度按 detailLevel 分档，避免长威胁/指令被切半
  //   原固定 60 字 → 现 brief=60 / normal=100 / rich=200（与 wechatHistory 对齐）
  var detailLevel = String(o.detailLevel || "normal");
  var snippetMax =
    detailLevel === "rich" ? 200 : detailLevel === "brief" ? 60 : 100;
  var timeline = yqCharGetTimeline(160);
  if (!timeline.length) return "";
  var grouped = {};
  for (var i = 0; i < timeline.length; i++) {
    var e = timeline[i];
    var cid = _yqNormalizeCharId(e && e.charId);
    if (!cid) continue;
    if (!grouped[cid]) grouped[cid] = [];
    if (grouped[cid].length >= perCharEvents) continue;
    grouped[cid].push(e);
  }
  var charIds = Object.keys(grouped).slice(0, maxChars);
  if (!charIds.length) return "";
  var out = "[角色跨模块近期记忆]\n";
  var runtimeStates = yqGetCharRuntimeStates();
  for (var ci = 0; ci < charIds.length; ci++) {
    var c = charIds[ci];
    out += "- " + c + "：\n";
    var rs = runtimeStates[c] || {};
    if (rs.live && rs.live.isLive) {
      out += "  - [live] 正在直播";
      if (rs.live.roomTitle) out += "《" + String(rs.live.roomTitle) + "》";
      out += "\n";
