    var c = String(canonical || "").trim();
    if (!c) return { ok: false, reason: "invalid" };
    var arr = yqGetFocusedFriends();
    if (arr.indexOf(c) >= 0) return { ok: true, reason: "exists" };
    if (arr.length >= _YQ_FOCUS_LIMIT)
      return { ok: false, reason: "limit", limit: _YQ_FOCUS_LIMIT };
    arr.push(c);
    setPhoneMeta("yinqi_friend_focus", arr);
    return { ok: true };
  } catch (_e) {
    return { ok: false, reason: "exception" };
  }
}

function yqUnfocusFriend(canonical) {
  try {
    var c = String(canonical || "").trim();
    if (!c) return false;
    var arr = yqGetFocusedFriends();
    var idx = arr.indexOf(c);
    if (idx < 0) return false;
    arr.splice(idx, 1);
    setPhoneMeta("yinqi_friend_focus", arr);
    return true;
  } catch (_e) {
    return false;
  }
}

function yqToggleFocusFriend(canonical) {
  try {
    var isFocused = yqIsFriendFocused(canonical);
    if (isFocused) {
      yqUnfocusFriend(canonical);
      return { ok: true, focused: false };
    } else {
      var r = yqFocusFriend(canonical);
      if (r.ok) return { ok: true, focused: true };
      return r;
    }
  } catch (_e) {
    return { ok: false, reason: "exception" };
  }
}

