/**
 * [阶段C] 尝试从 NPC 的聊天消息里抽取自报真名并自动解锁 knownRealName
 *
 * 触发点：storeNpcMessage 收到新的 NPC 私聊消息后
 *
 * 规则：
 *   - 仅对未解锁 knownRealName 的 canonical 生效
 *   - 匹配中文姓名（2-4 汉字），含几种常见自报句式
 *   - 黑名单过滤口语误匹配（很好/好呀/什么等）
 *   - 不处理群聊（避免群员提到别的名字被误认成发言者本人）
 *   - 成功解锁时：upsert realName + realNameSource="chat_selfintro" + knownRealName=true，打印诊断日志
 *
 * @param {string} canonical  NPC 规范键（通常来自 friend_XXX contactId 的 XXX）
 * @param {string} messageText NPC 消息正文
 * @returns {string} 解锁的真名（未命中则返回 ""）
 */
function yqFriendTryUnlockRealNameFromMessage(canonical, messageText) {
  try {
    var c = String(canonical || "").trim();
    if (!c) return "";
    var text = String(messageText || "").trim();
    if (!text) return "";

    // 已解锁就不再处理
    var metaRow = yqFriendGetMeta(c);
    if (metaRow && metaRow.knownRealName === true) return "";

    // 剧情角色（林知意等）默认已解锁，跳过
    if (_yqFriendIsStoryMvuCharacter(c)) return "";

    // 匹配模式（从严到宽；()1 是候选真名）
    // 设计：只认明确的"自报家门"句式，避免"自我介绍一下我是..."这种需上下文的口语误触发
    var patterns = [
      /(?:我真名(?:是|叫))([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
      /(?:我本名(?:是|叫))([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
      /(?:我(?:的)?名字(?:是|叫|就叫))([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
      /我叫([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
      /(?:叫|喊)我([\u4e00-\u9fa5]{2,4})(?:就行|好了|吧|即可)/,
      // 自我介绍 + "我是" —— 跨越「，」需宽松约束，用句末句首锚定
      /(?:正式|自我)介绍[，、：:\s]{0,3}我(?:叫|是|叫做)([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
      /(?:正式|自我)介绍[，、：:\s]{0,3}一下[，,：:\s]{0,3}我(?:叫|是|叫做)([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
      // 名片体："姓名：XX"、"本名：XX"
      /(?:姓名|本名|真名)[：:]\s*([\u4e00-\u9fa5]{2,4})(?![\u4e00-\u9fa5])/,
    ];
    var realName = "";
    for (var i = 0; i < patterns.length; i++) {
      var m = text.match(patterns[i]);
      if (m && m[1]) {
        realName = String(m[1]).trim();
        break;
      }
    }
    if (!realName) return "";

    // 黑名单：常见口语/短语/副词/代词误匹配
    var blacklist = [
      // 口语
      "很好",
      "好呀",
      "好的",
      "好啊",
      "什么",
      "没事",
      "随便",
      "习惯",
      // 副词/代词/时间
      "一下",
      "一会",
      "而已",
      "这里",
      "那边",
      "这边",
      "那里",
      "现在",
      "刚才",
      "等等",
      // 称呼类（不是真名）
      "个屁",
      "大哥",
      "大姐",
      "朋友",
      "兄弟",
      "哥们",
      "姐姐",
      "妹妹",
      "先生",
      "女士",
      "老板",
      "小姐",
      "客人",
      "同学",
      "老师",
      "医生",
      // 不能确认的代词
      "你们",
      "我们",
      "他们",
      "她们",
      "大家",
    ];
    if (blacklist.indexOf(realName) >= 0) return "";
    // 姓氏/名字必须是合理中文姓名——简单校验：至少含 1 个非"我/你/他/她"的字
    if (/^[我你他她它]+$/.test(realName)) return "";
    // 和 canonical 一模一样就没必要写
    if (realName === c) return "";

    // 命中！写入 meta
    yqFriendUpsertProfile(c, {
      realName: realName,
      realNameSource: "chat_selfintro",
      knownRealName: true,
    });
    try {
      console.log("[社交] 通过聊天自报解锁真名:", c, "->", realName);
      if (typeof _yqSocialDiag === "function") {
        _yqSocialDiag("real_name_unlocked_via_chat", {
          canonical: c,
          realName: realName,
        });
      }
    } catch (_eLog) {}
    return realName;
  } catch (e) {
    try {
      console.warn(
        "[社交] yqFriendTryUnlockRealNameFromMessage failed:",
        canonical,
        e,
      );
    } catch (_ignore) {}
    return "";
  }
}

