function yqFriendGetPrimaryDisplayName(canonical) {
  var c = String(canonical || "").trim();
  if (!c) return "";
  var row = yqFriendGetMetaMap()[c] || {};
  var base = c;
  try {
    if (typeof getDisplayName === "function") {
      var gd = getDisplayName(c);
      if (gd) base = String(gd);
    }
  } catch (_e1) {}

  if (_yqFriendIsStoryMvuCharacter(c)) {
    return base;
  }

  var src = String(row.addSource || "");
  var nick = String(row.addSurfaceName || "").trim();
  if (!nick && _yqFriendSourceIsForumOrLive(src)) {
    nick = String(row.lastDisplayName || "").trim();
  }
  if (
    nick &&
    _yqFriendSourceIsForumOrLive(src) &&
    nick !== base &&
    nick !== c
  ) {
