/**
 * 群聊顶栏成员副标题：对每位成员做规范键解析 + 与私聊列表一致的展示名（论坛/直播网友带当时昵称）
 */
function yqFriendFormatMembersLineForUi(membersRaw) {
  var t = String(membersRaw || "");
  try {
    if (typeof replaceUserMacro === "function") t = replaceUserMacro(t);
  } catch (_e0) {}
  var parts = t.split(/[、,，]/);
  var out = [];
  for (var i = 0; i < parts.length; i++) {
    var m = String(parts[i] || "").trim();
    if (!m) continue;
    var canon =
      typeof yqFriendResolveCanonical === "function"
        ? yqFriendResolveCanonical(m)
        : "";
    var key = (canon && String(canon).trim()) || m;
    var disp =
      typeof yqFriendGetPrimaryDisplayName === "function"
        ? yqFriendGetPrimaryDisplayName(key)
        : typeof getDisplayName === "function"
          ? getDisplayName(key)
          : key;
    out.push(disp || m);
  }
  return out.join("、");
}

