/**
 * 多 APP 上下文的昵称记录（phoneMeta.yinqi_friend_meta.{canonical}.apps.{context}）
 */
function yqFriendRecordAppNick(canonical, context, nick) {
  try {
    var c = String(canonical || "").trim();
    var ctx = String(context || "chat").trim();
    var n = String(nick || "").trim();
    if (!c || !n) return;
    if (c === n) return; // nick 和 canonical 相同就不记录
    var meta = yqFriendGetMetaMap();
    var row = meta[c] && typeof meta[c] === "object" ? meta[c] : {};
    row.apps = row.apps && typeof row.apps === "object" ? row.apps : {};
    var appRow =
      row.apps[ctx] && typeof row.apps[ctx] === "object"
        ? row.apps[ctx]
        : { history: [] };
    if (appRow.currentNick !== n) {
      appRow.currentNick = n;
      appRow.history = Array.isArray(appRow.history) ? appRow.history : [];
      if (appRow.history.indexOf(n) < 0) {
        appRow.history.unshift(n);
        while (appRow.history.length > 10) appRow.history.pop();
      }
      appRow.lastSeenAt = Date.now();
    }
    row.apps[ctx] = appRow;
    // 同步到 aliases
    row.aliases = Array.isArray(row.aliases) ? row.aliases : [];
    if (row.aliases.indexOf(n) < 0) {
      row.aliases.unshift(n);
      while (row.aliases.length > 32) row.aliases.pop();
    }
    row.updatedAt = Date.now();
    meta[c] = row;
    yqFriendSetMetaMap(meta);
  } catch (e) {
    try {
      console.warn("[社交] yqFriendRecordAppNick failed:", canonical, e);
    } catch (_ignore) {}
  }
}

