        var fn = _.get(d, "女性角色." + c + ".姓名", "");
        if (fn) return String(fn).trim();
        var mn = _.get(d, "男性角色." + c + ".姓名", "");
        if (mn) return String(mn).trim();
      } catch (_e1) {}
    }
    // 3. 读 phoneMeta.yinqi_friend_meta.{canonical}.realName
    try {
