          var msgs = JSON.parse(localStorage.getItem(k) || "[]");
          if (msgs.length > 0) {
            allNpcMsgs[contactId] = msgs;
            migratedCount++;
          }
        } catch (e) {}
      } else if (k.startsWith("yinqi-chat-") && !k.includes("api-settings")) {
        var chatId = k.replace("yinqi-chat-", "");
        try {
          var hist = JSON.parse(localStorage.getItem(k) || "[]");
          if (hist.length > 0) {
            allChatHist[chatId] = hist;
            migratedCount++;
          }
        } catch (e) {}
      } else if (k.startsWith("yinqi-unread-")) {
        var uid = k.replace("yinqi-unread-", "");
        var val = parseInt(localStorage.getItem(k) || "0");
        if (val > 0) unreads[uid] = val;
      }
    }

    // 迁移特殊未读计数
    var momentsU = parseInt(
      localStorage.getItem("yinqi-moments-unread") || "0",
    );
    var worldU = parseInt(
      localStorage.getItem("yinqi-world-events-unread") || "0",
    );
    var forumU = parseInt(localStorage.getItem("yinqi-forum-unread") || "0");

    // 写入chatMetadata
    setPhoneMetaBig("npc_messages", allNpcMsgs, true);
    setPhoneMetaBig("chat_history", allChatHist, true);
    setPhoneMeta("unreads", unreads, true);
    if (momentsU > 0) setPhoneMeta("moments_unread", momentsU, true);
    if (worldU > 0) setPhoneMeta("world_events_unread", worldU, true);
    if (forumU > 0) setPhoneMeta("forum_unread", forumU, true);
    debounceSavePhoneMeta();

    if (migratedCount > 0) {
      console.log(
        "[手机数据迁移] 已将 " +
          migratedCount +
          " 组消息数据从localStorage迁移到chatMetadata",
      );
    }
  } catch (e) {
    console.warn("[手机数据迁移] 迁移失败:", e);
  }
}

