/**
 * 从MVU数据构建好友列表（银麒赎世版）
 * 好友来源：林知意（固定）、女性角色、场景角色、银麒系统.档案（AI维护的字符串摘要）、chatMetadata持久化
 * 规则：只增不删，脚本自动维护
 */
function buildFriendsList(source) {
  if (source === undefined) source = currentPhoneData;
