  var males = _.get(d, "男性角色", {});
  var npcArchives = _.get(d, "银麒系统.档案", {});
  // [V9.6 #3·2026-05-10] 林知意真源在 stat_data.角色.林知意（非 女性角色.林知意）
  // 预取主角数据和林知意核心数据，用于：(1) 林知意做爱标记 (2) 性别符号选择
  var _lzMainSrc = _.get(d, "角色.林知意", {}) || {};
  var _userSrc = _.get(d, "user", {}) || {};
  var _userGender = String(_userSrc.gender || "male").toLowerCase();
  // [V9.6 补丁3.2·2026-05-10] 显示符号规则（按玩家最终澄清）：
  //   - 所有女性（含林知意）：不显性别符号（默认都是女性），只在已性交后显 💕
  //   - 主角变性/双性显示在其他入口处理，此函数仅服务好友列表（都是女性/男性角色）
  function _yqResolveSexMark(hadSex) {
    return hadSex ? " \u{1F495}" : "";
  }

  /* 从chatMetadata加载已同意好友（不再自动全量入列） */
  var saved = getKnownFriends();
  var savedKeys = Object.keys(saved);
  for (var k = 0; k < savedKeys.length; k++) {
    var sName = savedKeys[k];
    if (sName === "{{user}}") continue;
    var f = { isCore: sName === "林知意", 在场: false, _fromHistory: true };
    if (sName === "林知意") {
      // 林知意：从 角色.林知意 读（真源，数据权威）
      f.好感度 = Number(_lzMainSrc.好感度 != null ? _lzMainSrc.好感度 : 100); // 默认 MAX（女主设定）
      f.攻略度 = Number(_lzMainSrc.攻略度 || 0);
      // [V9.6 补丁3.4·2026-05-10] 林知意永远已性交（女主不存在未性交）
