      var fv = _.get(favor, sName, null);
      if (fv && typeof fv === "object") {
        f.好感度 = fv.好感度 || 0;
        f.攻略度 = fv.攻略度 || 0;
        // [V9.6 #3·2026-05-10] 做爱标记也扩展到其他女性角色
