      // AI 写入的档案是字符串"性别/年龄/身份/外貌/地点"，第 3 段为身份
      var arch = npcArchives[sName];
      if (typeof arch === "string" && arch) {
        var parts = arch.split("/");
        if (parts.length >= 3) f.身份 = String(parts[2] || "").trim();
      }
    }
    friends[sName] = f;
  }

  // [阶段3] 兜底恢复已移除 — 通讯录只显示 known_friends 里玩家已同意的好友
