  //
  // 极端保底：若 friends 完全为空（known_friends 丢失且 bootstrap 未成功），
  //         至少保留林知意（女主）避免通讯录空白
  if (Object.keys(friends).length === 0) {
    try {
      console.warn(
        "[社交·buildFriendsList] known_friends 为空，启用极端保底（只加林知意）",
      );
    } catch (_ignoreEmergency) {}
    friends["林知意"] = {
      isCore: true,
      在场: !!sceneChars["林知意"],
      _fromEmergencyFallback: true,
    };
    // [V9.6 #3·2026-05-10] 保底分支也用 角色.林知意 真源
    friends["林知意"].好感度 = Number(
      _lzMainSrc.好感度 != null ? _lzMainSrc.好感度 : 100,
    );
    friends["林知意"].攻略度 = Number(_lzMainSrc.攻略度 || 0);
    // [V9.6 补丁3.4·2026-05-10] 林知意永远已性交（女主不存在未性交）
    friends["林知意"]._sexMark = _yqResolveSexMark(true);
    friends["林知意"]._hadSex = true;
    // 尝试重新 bootstrap（不依赖幂等锁，强制补齐 MVU 中已有的角色）
    try {
      if (typeof yqBootstrapInitialFriends === "function") {
        setPhoneMeta("yinqi_bootstrap_done", false);
        yqBootstrapInitialFriends();
      }
    } catch (_ignoreReBootstrap) {}
  }

  /* 7. 标记丧尸/死亡状态（实时检测，恢复后自动解除） */
  var _zFlags = getPhoneMeta("yinqi_zombie_flags", {});
  var _allFKeys = Object.keys(friends);
  for (var _zi = 0; _zi < _allFKeys.length; _zi++) {
    var _zn = _allFKeys[_zi];
    var _isInfected = false;
    // 检查phoneMeta丧尸化记录
    var _waves = ["wave1", "wave2", "wave3"];
    for (var _wi = 0; _wi < _waves.length; _wi++) {
      if (
        _zFlags[_waves[_wi]] &&
        _zFlags[_waves[_wi]].results &&
        _zFlags[_waves[_wi]].results[_zn] === "infected"
      ) {
        _isInfected = true;
        break;
      }
    }
    // 检查MVU状态字段（实时，恢复后状态字段不再含"丧尸"则自动解除）
    var _fStatus = "";
    if (_zn === "林知意") _fStatus = _.get(d, "角色.林知意.状态", "");
    else if (_.get(d, "女性角色", {})[_zn])
      _fStatus = _.get(d, "女性角色." + _zn + ".状态", "");
    else if (_.get(d, "男性角色", {})[_zn])
      _fStatus = _.get(d, "男性角色." + _zn + ".状态", "");
    if (_fStatus && _fStatus.indexOf("丧尸") >= 0)
      friends[_zn]._isZombie = true;
    else if (_isInfected) friends[_zn]._isZombie = true;
    if (_fStatus && _fStatus.indexOf("死亡") >= 0) friends[_zn]._isDead = true;
    // 如果MVU状态不含丧尸且phoneMeta标记infected，但角色已被逆转针治愈（状态字段恢复正常），则不标记
    // 逻辑：MVU状态字段是实时的，phoneMeta是历史记录。以MVU为准——如果状态字段正常，说明已恢复
    if (
      _isInfected &&
      _fStatus &&
      _fStatus.indexOf("丧尸") < 0 &&
      _fStatus.indexOf("死亡") < 0 &&
      _fStatus !== ""
    ) {
      friends[_zn]._isZombie = false; // 已恢复
    }
  }

  return friends;
}

