    var _ctxAv = window.SillyTavern && window.SillyTavern.getContext ? window.SillyTavern.getContext() : null;
    var _charAv = _ctxAv && _ctxAv.characters ? _ctxAv.characters[_ctxAv.characterId] : null;
    var _extAv = _charAv && _charAv.data ? _charAv.data.extensions : null;
    var _defaults = _extAv && _extAv.yinqi_default_avatars ? _extAv.yinqi_default_avatars : null;
    if (!_defaults || typeof _defaults !== "object" || !window.phoneImageStore) return 0;
    var _curAvatars = getPhoneMeta("chat_avatars", {});
    var _playerName = (_ctxAv && _ctxAv.name1) ? String(_ctxAv.name1) : "";
    // 玩家级女体默认头像（跨聊天/跨主角名）：
    // 若存在本地缓存，则覆盖默认包里的主角_女体，避免受内置旧图影响。
    var _persistFemale = null;
    try {
      _persistFemale = localStorage.getItem("yinqi_player_female_avatar_dataurl") || null;
      if (
        _persistFemale &&
        typeof _persistFemale === "string" &&
        _persistFemale.indexOf("data:") === 0
      ) {
        _defaults["主角_女体"] = _persistFemale;
      }
    } catch (_) {}
    // 自动补齐玩家性别头像键：若玩家已在当前会话生成并写入主键，且缺少 *_female/*_futanari，则补一份同ID映射
    if (_playerName) {
      var _gNow = (typeof yqGetUserGender === "function") ? yqGetUserGender() : "male";
      if (
        _gNow === "female" &&
        !_curAvatars[_playerName + "_female"] &&
        _curAvatars[_playerName]
      ) {
        _curAvatars[_playerName + "_female"] = _curAvatars[_playerName];
      }
      if (
        _gNow === "futanari" &&
        !_curAvatars[_playerName + "_futanari"] &&
        _curAvatars[_playerName]
      ) {
        _curAvatars[_playerName + "_futanari"] = _curAvatars[_playerName];
      }
      // 自动自愈：主角已变性但没有专属头像时，触发一次自动生成并回写 *_female/*_futanari
      if (
        (_gNow === "female" && !_curAvatars[_playerName + "_female"]) ||
        (_gNow === "futanari" && !_curAvatars[_playerName + "_futanari"])
      ) {
        try {
          var _autoKey = "yinqi_auto_player_avatar_gen_" + _gNow;
          if (!sessionStorage.getItem(_autoKey)) {
            sessionStorage.setItem(_autoKey, "1");
            setTimeout(function () {
              try {
                if (
                  window.PhoneCharacterAppearance &&
                  typeof window.PhoneCharacterAppearance.generateAvatar === "function"
                ) {
                  window.PhoneCharacterAppearance.generateAvatar(_playerName);
                }
              } catch (_) {}
            }, 0);
          }
        } catch (_) {}
      }
    }
    var _missingNames = [];
    var _brokenFemaleDefault =
      typeof _defaults["主角_女体"] === "string" &&
      typeof _defaults["林知意"] === "string" &&
      _defaults["主角_女体"] === _defaults["林知意"];
    // 兼容旧档：默认包若已判定损坏，强制清理历史的主角_女体映射，避免继续误用林知意头像
    if (_brokenFemaleDefault && _curAvatars["主角_女体"]) {
      delete _curAvatars["主角_女体"];
    }
    for (var _dn in _defaults) {
      if (_defaults.hasOwnProperty(_dn) && !_curAvatars[_dn]) {
        if (_brokenFemaleDefault && _dn === "主角_女体") {
          // 避免错误默认图把女体主角显示成林知意
          continue;
        }
        _missingNames.push(_dn);
      }
    }
    if (_missingNames.length === 0) return 0;
    _missingNames.forEach(function (name) {
      var dataUrl = _defaults[name];
      if (!dataUrl || typeof dataUrl !== "string" || dataUrl.indexOf("data:") !== 0) return;
      // 用固定 id 保证 IndexedDB 幂等，跨聊天/多次调用不会占多份
      var imgId = window.phoneImageStore.save(dataUrl, {
        fixedId: "default-avatar-" + name,
        source: "default-avatar",
        description: name + "(内置默认头像)",
        tag: "头像",
        size: { w: 256, h: 256 },
      });
      _curAvatars[name] = imgId;
      if (_playerName && name === "主角_女体" && !_curAvatars[_playerName + "_female"]) {
        _curAvatars[_playerName + "_female"] = imgId;
      }
    });
    setPhoneMeta("chat_avatars", _curAvatars);
    if (typeof debounceSavePhoneMeta === "function") debounceSavePhoneMeta();
    if (_brokenFemaleDefault) {
      try {
        console.warn("[默认头像] 检测到主角_女体与林知意默认图重复，已跳过主角_女体自动注入，等待玩家生成专属女体头像");
      } catch (_) {}
    }
    try {
      console.log("[默认头像] 已为 " + _missingNames.length + " 个角色补齐内置头像: " + _missingNames.join(", "));
    } catch (_) {}
    return _missingNames.length;
  } catch (e) {
    try { console.warn("[默认头像] fallback 异常:", e && e.message); } catch (_) {}
    return 0;
  }
}

