  // 自动调用 saveWorldInfo 把新条目（如 [EJS]社交渗透网友画像）同步进 worldInfo DB。
  // 注意：必须运行在 ST 主页（手机 UI 通过 window.parent 访问 SillyTavern.getContext）。
  try {
    var _wiSyncStarted = Date.now();
    var _stTop = (window.parent && window.parent !== window) ? window.parent : window;
    if (_stTop && _stTop.SillyTavern && typeof _stTop.SillyTavern.getContext === "function") {
      var _ctx = _stTop.SillyTavern.getContext();
      var _charData = _ctx && _ctx.characters && _ctx.characters[_ctx.characterId];
      var _charBook = _charData && _charData.data && _charData.data.character_book;
      if (_charBook && Array.isArray(_charBook.entries) && typeof _ctx.loadWorldInfo === "function") {
        var _bookCount = _charBook.entries.length;
        // 计算 character_book 内容签名（条目数 + 总长度 + 关键 EJS 长度），用于检测内容变更
        var _bookSig = _bookCount + ":" + _charBook.entries.reduce(function (sum, e) {
          return sum + ((e && e.content) ? e.content.length : 0);
        }, 0);
        Promise.resolve(_ctx.loadWorldInfo(_charData.data.name)).then(function (wi) {
          var _wiArr = wi && wi.entries ? Object.values(wi.entries) : [];
          var _wiCount = _wiArr.length;
          var _wiSig = _wiCount + ":" + _wiArr.reduce(function (sum, e) {
            return sum + ((e && e.content) ? e.content.length : 0);
