                setPhoneMeta("yinqi_worldinfo_sync_attempt_sig", _bookSig);
                setPhoneMeta("yinqi_worldinfo_sync_attempt_ts", Date.now());
                if (typeof _yqFlushPhoneMetaPatches === "function") _yqFlushPhoneMetaPatches();
              } catch (_eMobileMeta) {}
              try { yqToast("warning", "检测到世界书需同步；移动端已暂停自动转换，建议在 PC 端热更新或手动同步。", "低内存保护", { timeOut: 8000 }); } catch (_eToast) {}
