            if (_lastAttempt === _bookSig && Date.now() - Number(getPhoneMeta("yinqi_worldinfo_sync_attempt_ts", 0) || 0) < 10 * 60 * 1000) {
              console.warn("[hot-update·同步] 10分钟内已尝试相同签名，跳过防循环：" + _bookSig);
              return;
            }
            try {
              window._yqWorldInfoSyncInFlight = _syncKey;
              try {
                setPhoneMeta("yinqi_worldinfo_sync_attempt_sig", _bookSig);
                setPhoneMeta("yinqi_worldinfo_sync_attempt_ts", Date.now());
                if (typeof _yqFlushPhoneMetaPatches === "function") _yqFlushPhoneMetaPatches();
              } catch (_eAttemptMeta) {}
              // ═════════════════════════════════════════════════════════
              // [V11.4·2026-05-24·关键修复] 差量同步：保留玩家自建条目
              //
              // 历史 BUG（V11.0-11.3）：
              //   convertCharacterBook(_charBook) 整本转换，
              //   saveWorldInfo(name, data, true) 第三参数 true 整本覆盖
              //   → 玩家自建条目（comment 不在 character_book 中的）全部消失
              //   → 自定义角色 / 规则 / 地点条目都被擦回 PNG 初版
              //
              // 修复策略：
              //   1. loadWorldInfo 拿到当前 wi（含玩家自建）
              //   2. 把 character_book 转成新条目数组（_newWiData）
              //   3. 玩家自建条目：comment 不在 character_book.comments 中
              //      → 完整保留（包括 keys/content/enabled/uid 等）
              //   4. 角色卡条目：用 _newWiData 中同 comment 的条目覆盖
              //      → 这样 comment="人物_宋以薇" 的条目按 hot-update 更新
              //   5. 重新分配 uid 避免冲突
              //   6. saveWorldInfo 用合并后的数据
              // ═════════════════════════════════════════════════════════
              var _newWiData = _ctx.convertCharacterBook(_charBook);
              var _newEntries = _newWiData && _newWiData.entries ? _newWiData.entries : {};
              var _bookCommentSet = {};
              for (var _ci = 0; _ci < _charBook.entries.length; _ci++) {
                var _be = _charBook.entries[_ci];
                if (_be && _be.comment) _bookCommentSet[_be.comment] = true;
              }
              // 收集玩家自建条目（comment 不在 character_book 中）
              var _userEntries = [];
              for (var _wk in wi.entries) {
                if (!wi.entries.hasOwnProperty(_wk)) continue;
                var _we = wi.entries[_wk];
