    // 真正的点击逻辑交给按钮自身的 inline onclick（目标阶段）执行
    try {
      var _forumBtnEl = target.closest
        ? target.closest(
            ".phone-forum-generate-btn, .forum-gen-image-btn, .forum-ondemand-gen-btn",
          )
        : null;
      if (_forumBtnEl) {
        // 标记事件为「已由论坛按钮消费」，让其他委托看到后自动 return
        e._yqForumBtnHandled = true;
      }
    } catch (_eFwd) {}

    const classList = target.classList;
    const classArray = Array.from(classList);

    // 检查清空证据按钮
    if (classArray.includes("phone-clear-evidence-btn")) {
      e.preventDefault();
      e.stopPropagation();
      window.phoneClearAllEvidence && window.phoneClearAllEvidence();
      return;
    }

    // phone-forum-generate-btn / forum-gen-image-btn / forum-ondemand-gen-btn
    // 已由 inline onclick（目标阶段）处理，这里不再拦截

    if (classArray.includes("phone-forum-settings-btn")) {
      e.preventDefault();
      e.stopPropagation();
      window.phoneOpenForumSettings && window.phoneOpenForumSettings();
      return;
    }

    if (classArray.includes("phone-forum-save-settings-btn")) {
      e.preventDefault();
      e.stopPropagation();
      window.phoneSaveForumSettings && window.phoneSaveForumSettings();
      return;
    }

    if (classArray.includes("phone-forum-close-settings-btn")) {
      e.preventDefault();
      e.stopPropagation();
      window.phoneCloseForumSettings && window.phoneCloseForumSettings();
      return;
    }

    // 检查论坛Tab切换按钮
    if (classArray.includes("forum-tab-btn")) {
      e.preventDefault();
      e.stopPropagation();
      var tab = target.getAttribute("data-tab");
      if (tab) {
        window._forumPanelTab = tab;
        var panelHtml = generateForumPanel();
