          $("#phone-app-body").html(panelHtml);
          $("#phone-app-title").text("论坛");
          bindPanelButtons();
        }
      }
      return;
    }

    // 检查论坛发帖按钮
    if (classArray.includes("forum-create-post-btn")) {
      e.preventDefault();
      e.stopPropagation();
      window._phoneForumShowCreatePost && window._phoneForumShowCreatePost();
      return;
    }

    // 检查论坛发帖表单按钮
    if (target.id === "forum-create-post-submit") {
      e.preventDefault();
      e.stopPropagation();
      var title = $("#forum-create-post-title").val();
