    // 如果点击的是按钮内的图标、文字或 DIV，向上查找按钮
    if (
      (target.tagName === "I" ||
        target.tagName === "SPAN" ||
        target.tagName === "DIV") &&
      target.parentElement
    ) {
      const parentClasses = Array.from(target.parentElement.classList || []);

