// ==================== 事件绑定 ====================
function bindPhoneEvents() {
  function _refreshMomentsAfterImageGen() {
    if (typeof refreshMomentsPanel === "function") {
      refreshMomentsPanel();
      return;
    }
    var currentTitle = $("#phone-app-title").text();
    if (currentTitle.indexOf("朋友圈") !== -1) {
      $("#phone-app-body").html(generateMomentsPanel());
      bindPanelButtons();
    }
  }
  // 触发按钮点击和拖动
  const $triggerBtn = $("#mobile-trigger-btn");

  // 点击事件（切换手机界面的打开/关闭状态）
  $triggerBtn.on("click", function (e) {
    // 如果刚才拖动过，不触发点击
    if (hasMoved) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }

    //  切换手机界面：如果已打开则关闭，如果已关闭则打开
    const $overlay = $("#mobile-phone-overlay");
    if ($overlay.hasClass("active")) {
      // 手机界面已打开，点击关闭（无论是否置顶）
      closeMobilePhone();
    } else {
      // 手机界面已关闭，点击打开
      openMobilePhone();
    }
  });

  // 使用 Pointer Events（更现代、更可靠）
  const btnElement = $triggerBtn[0];

  btnElement.addEventListener("pointerdown", function (e) {
    // 捕获指针，这样即使鼠标移出按钮也能继续接收事件
    btnElement.setPointerCapture(e.pointerId);

    handleDragStart(e);

    const onPointerMove = function (e) {
      handleDragMove(e);
    };

    const onPointerUp = function (e) {
      handleDragEnd(e);

      // 释放指针捕获
      try {
        btnElement.releasePointerCapture(e.pointerId);
      } catch (err) {
        // 忽略释放失败
      }

      // 移除事件监听
      btnElement.removeEventListener("pointermove", onPointerMove);
      btnElement.removeEventListener("pointerup", onPointerUp);
      btnElement.removeEventListener("pointercancel", onPointerUp);
    };

    // 绑定到按钮本身（因为已经捕获了指针）
    btnElement.addEventListener("pointermove", onPointerMove);
    btnElement.addEventListener("pointerup", onPointerUp);
    btnElement.addEventListener("pointercancel", onPointerUp); // 处理取消事件
  });

  // 触摸事件（移动端支持）
  $triggerBtn.on("touchstart", function (e) {
    handleDragStart(e.originalEvent.touches[0]);

    const onTouchMove = function (e) {
      e.preventDefault();
      handleDragMove(e.originalEvent.touches[0]);
    };

    const onTouchEnd = function (e) {
      handleDragEnd(e);
      $(document).off("touchmove", onTouchMove);
      $(document).off("touchend", onTouchEnd);
    };

    $(document).on("touchmove", onTouchMove);
    $(document).on("touchend", onTouchEnd);
  });

  // 点击遮罩关闭（仅在未置顶时）
  $("#mobile-phone-overlay").on("click", function (e) {
    // 如果正在拖动页面或刚完成拖动，不关闭手机
    if (pageSwipe && (pageSwipe.isDragging || pageSwipe.justFinishedDragging)) {
      return;
    }
    if ($(e.target).attr("id") === "mobile-phone-overlay" && !isPinned) {
      closeMobilePhone();
    }
  });

  // 置顶按钮点击
  $("#phone-pin-btn").on("click", function (e) {
    e.stopPropagation();
