    if (!pool || !pool[postIndex]) return;
    var post = pool[postIndex];
    var ctx = {
      title: post.title || "",
      content: post.content || "",
      time: post.time || "",
      author: post.author || "",
      _authorGender: post.authorGender || "",
    };
    if (post.storyCharName) {
      ctx.involvedChars = [post.storyCharName];
      if (post.storyCharGender) ctx._gender = post.storyCharGender;
    }
    if (!ctx._gender && post.authorGender) {
      ctx._gender = post.authorGender;
    }
    if (typeof window.phoneQueueBtnStateUpdate === "function") {
      window.phoneQueueBtnStateUpdate(function () {
        $btn
          .prop("disabled", true)
          .html('<i class="fas fa-spinner fa-spin"></i> 生成中...');
      });
    } else {
      $btn
        .prop("disabled", true)
        .html('<i class="fas fa-spinner fa-spin"></i> 生成中...');
    }
    window
      .phonePreGenerateTag("forum", ctx)
      .then(function (r) {
        if (r && r.success && r.entryId) {
          post.imageId = r.entryId;
          if (source === "user" && typeof fm.saveUserPosts === "function")
            fm.saveUserPosts();
          else if (
            source === "commented" &&
            typeof fm.saveCommentedPosts === "function"
          )
            fm.saveCommentedPosts();
          else fm.saveForumData();
          var entry = window.phoneImageStore
            ? window.phoneImageStore.getEntry(r.entryId)
            : null;
          if (entry && entry.tag) {
            return window.phoneRenderImage(entry.tag, {
              entryId: r.entryId,
              source: "forum",
              size: entry.size,
            });
          }
        }
        return null;
      })
      .then(function (r2) {
        if (r2 && r2.success) {
          yqToast("success", "论坛配图已生成");
        }
        if (
          window.currentPanel === "forum" &&
