      var touch = e.originalEvent && e.originalEvent.touches && e.originalEvent.touches[0];
      if (timer && touch) {
        var dx = Math.abs((touch.clientX || 0) - (start.x || 0));
        var dy = Math.abs((touch.clientY || 0) - (start.y || 0));
        if (dx > 12 || dy > 12) {
          clearTimeout(timer);
          $bubble.removeData("longpressTimer");
