// ==================== 聊天消息右键菜单 ====================
function _showChatMsgContextMenu($bubble, e) {
  $(".chat-msg-context-menu").remove();
  var msgIdx = $bubble.data("msg-idx");
  var chatId = $bubble.data("chat-id");
  if (typeof msgIdx === "undefined" || !chatId) return;
  var storeSource = String($bubble.data("phone-source") || "");
  var storeKey = String($bubble.data("phone-store-key") || chatId || "");
  var storeIndexRaw = $bubble.data("phone-store-index");
  var storeIndex = storeIndexRaw === "" || storeIndexRaw == null ? NaN : Number(storeIndexRaw);
  var storeMsg = null;
  try {
    var metaKey = storeSource === "npc_messages" ? "npc_messages" : "chat_history";
    var all = getPhoneMeta(metaKey, {});
    var list = all && all[storeKey];
    if (Array.isArray(list) && isFinite(storeIndex)) storeMsg = list[storeIndex] || null;
  } catch (_menuMetaErr) {}
  var canReroll =
    storeSource === "chat_history" &&
    storeMsg &&
    storeMsg.type === "user" &&
    !storeMsg.isImage;

  var posX, posY;
  if (
    e.originalEvent &&
    e.originalEvent.touches &&
    e.originalEvent.touches.length
  ) {
    posX = e.originalEvent.touches[0].clientX;
    posY = e.originalEvent.touches[0].clientY;
  } else {
    posX = e.clientX || e.pageX || 100;
    posY = e.clientY || e.pageY || 100;
  }

  var rerollHtml = canReroll
    ? '<div class="chat-ctx-reroll" data-chat-id="' +
      escapeHtml(chatId) +
      '" data-store-key="' +
      escapeHtml(storeKey) +
      '" data-store-index="' +
      storeIndex +
      '" style="padding:10px 16px;color:#a78bfa;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:6px;border-top:1px solid #334155;transition:background 0.15s;">' +
      '<i class="fas fa-rotate-right"></i> 重Roll此后回复</div>'
    : "";
  var $menu = $(
    '<div class="chat-msg-context-menu" style="' +
      "position:fixed;z-index:999998;" +
      "left:" +
      posX +
      "px;top:" +
      posY +
      "px;" +
      "background:#1e293b;border:1px solid #475569;border-radius:8px;" +
      "box-shadow:0 8px 24px rgba(0,0,0,0.5);overflow:hidden;min-width:120px;" +
      '">' +
      '<div class="chat-ctx-delete" data-chat-id="' +
      escapeHtml(chatId) +
      '" data-msg-idx="' +
      msgIdx +
      '" data-phone-source="' +
      escapeHtml(storeSource) +
      '" data-phone-store-key="' +
      escapeHtml(storeKey) +
      '" data-phone-store-index="' +
      (isFinite(storeIndex) ? storeIndex : "") +
      '" style="padding:10px 16px;color:#f87171;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:6px;transition:background 0.15s;">' +
      '<i class="fas fa-trash-alt"></i> 删除消息</div>' +
      rerollHtml +
      '<div class="chat-ctx-copy" data-chat-id="' +
      escapeHtml(chatId) +
      '" data-msg-idx="' +
      msgIdx +
      '" style="padding:10px 16px;color:#e2e8f0;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:6px;border-top:1px solid #334155;transition:background 0.15s;">' +
      '<i class="fas fa-copy"></i> 复制文字</div>' +
      "</div>",
  );

  // 删除
  $menu.find(".chat-ctx-delete").on("click", function (e2) {
    e2.stopPropagation();
    var cid = $(this).data("chat-id");
    var idx = parseInt($(this).data("msg-idx"));
    var src = String($(this).data("phone-source") || "");
    var key = String($(this).data("phone-store-key") || cid || "");
    var sidxRaw = $(this).data("phone-store-index");
    var sidx = sidxRaw === "" || sidxRaw == null ? NaN : Number(sidxRaw);
    if (!confirm("确定删除这条消息？")) {
      $menu.remove();
      return;
    }
    if (src && key && isFinite(sidx) && typeof window.deletePhoneChatMessage === "function") {
      window.deletePhoneChatMessage(src, key, sidx);
      $menu.remove();
      return;
    }
    if (!src) {
      yqToast("warning", "这条消息来自主聊天历史镜像，不能在手机内删除");
      $menu.remove();
      return;
    }
    var allChat = getPhoneMetaBig("chat_history", {});
    var ch = allChat[cid];
    if (ch && idx >= 0 && idx < ch.length) {
      ch.splice(idx, 1);
      allChat[cid] = ch;
      setPhoneMetaBig("chat_history", allChat);
      if (
        typeof window.renderChatMessages === "function" &&
        typeof window.currentChatContactId !== "undefined" &&
        window.currentChatContactId === cid
      ) {
        window.renderChatMessages._isFirstRender = false;
        window.renderChatMessages(
          window.currentChatContactId,
          typeof window.currentChatIsGroup !== "undefined"
            ? window.currentChatIsGroup
            : false,
        );
      }
      yqToast("success", "消息已删除");
    }
    $menu.remove();
  });

  // 重Roll玩家消息之后的AI回复
  $menu.find(".chat-ctx-reroll").on("click", function (e2) {
    e2.stopPropagation();
    var key = String($(this).data("store-key") || "");
    var idx = Number($(this).data("store-index"));
    if (!key || !isFinite(idx)) {
      yqToast("warning", "无法定位要重Roll的消息");
      $menu.remove();
      return;
    }
    if (!confirm("将删除这条玩家消息之后的手机回复，并重新发送该消息生成新回复。确认重Roll？")) {
      $menu.remove();
      return;
    }
    $menu.remove();
    if (typeof window.rerollPhoneUserMessageFromIndex === "function") {
      window.rerollPhoneUserMessageFromIndex(key, idx);
    } else {
      yqToast("warning", "重Roll函数未加载，请刷新手机UI");
    }
  });

  // 复制
  $menu.find(".chat-ctx-copy").on("click", function (e2) {
    e2.stopPropagation();
    var cid = $(this).data("chat-id");
    var idx = parseInt($(this).data("msg-idx"));
    var allChat = getPhoneMetaBig("chat_history", {});
    var ch = allChat[cid];
    if (ch && idx >= 0 && idx < ch.length) {
      var text = ch[idx].content || "";
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
          yqToast("success", "已复制");
        });
      } else {
        // fallback
        var ta = document.createElement("textarea");
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        yqToast("success", "已复制");
      }
    }
    $menu.remove();
  });

  $("body").append($menu);

  // 确保菜单不超出视口
  setTimeout(function () {
    var rect = $menu[0].getBoundingClientRect();
    if (rect.right > window.innerWidth)
      $menu.css("left", window.innerWidth - rect.width - 8 + "px");
    if (rect.bottom > window.innerHeight)
      $menu.css("top", window.innerHeight - rect.height - 8 + "px");
  }, 0);
}

// ==================== 拖动处理函数 ====================
function handleDragStart(e) {
  isDragging = true;
  hasMoved = false;

  const $btn = $("#mobile-trigger-btn");
  const btnElement = $btn[0];

  //  移除所有模式类
  $btn.removeClass("mobile-mode tablet-mode desktop-mode");

  // 获取按钮当前实际位置（在清除样式前）
  const rect = btnElement.getBoundingClientRect();
  btnStartX = rect.left;
  btnStartY = rect.top;

  //  强制覆盖所有定位属性（使用!important覆盖CSS类）
  btnElement.style.setProperty("left", btnStartX + "px", "important");
  btnElement.style.setProperty("top", btnStartY + "px", "important");
  btnElement.style.setProperty("right", "auto", "important");
  btnElement.style.setProperty("bottom", "auto", "important");
  btnElement.style.setProperty("transform", "none", "important");

  // 记录初始鼠标位置
  dragStartX = e.clientX;
  dragStartY = e.clientY;
}

function handleDragMove(e) {
  if (!isDragging) return;

  // 计算移动距离
  const deltaX = e.clientX - dragStartX;
  const deltaY = e.clientY - dragStartY;

  // 如果移动超过3px，认为是拖动而不是点击
  if (!hasMoved && (Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3)) {
    hasMoved = true;

    // 开始拖动时添加样式
    const $btn = $("#mobile-trigger-btn");
    $btn.addClass("dragging");
  }

  // 只在真正开始拖动后才阻止默认行为和更新位置
  if (!hasMoved) return;

  if (e.preventDefault) {
    e.preventDefault();
  }

  // 计算新位置
  const newX = btnStartX + deltaX;
  const newY = btnStartY + deltaY;

  // 使用工具函数进行边界限制（完全限制在视口内）
  const $btn = $("#mobile-trigger-btn");
  const btnWidth = $btn.outerWidth() || 60;
  const btnHeight = $btn.outerHeight() || 60;

  const bounded = constrainFullyInViewport(newX, newY, btnWidth, btnHeight);

  //  使用 setProperty 强制设置位置（覆盖!important）
  const btnElement = $btn[0];
  btnElement.style.setProperty("left", bounded.x + "px", "important");
  btnElement.style.setProperty("top", bounded.y + "px", "important");
  btnElement.style.setProperty("right", "auto", "important");
  btnElement.style.setProperty("bottom", "auto", "important");
}

function handleDragEnd(e) {
  if (!isDragging) return;

  isDragging = false;
  const $btn = $("#mobile-trigger-btn");
  $btn.removeClass("dragging");

  // 如果移动了，保存位置
  if (hasMoved) {
    // 获取当前位置的多种方式
    const cssLeft = $btn.css("left");
    const cssTop = $btn.css("top");

    // 直接从CSS获取当前设置的值
    const left = parseFloat(cssLeft);
    const top = parseFloat(cssTop);

    // 验证位置是否有效
    if (!isNaN(left) && !isNaN(top) && left >= 0 && top >= 0) {
      try {
        const position = { left: left, top: top };
        localStorage.setItem(
          "mobile-trigger-btn-position",
          JSON.stringify(position),
        );
        //  标记用户已手动拖动，防止resize重置位置
        localStorage.setItem("mobile-trigger-btn-user-dragged", "true");
      } catch (err) {}
    }
  }

  // 延迟重置 hasMoved，让 click 事件能检测到
  setTimeout(() => {
    hasMoved = false;
  }, 10);
}

// 恢复按钮位置（添加重试次数限制）
let restorePositionRetryCount = 0;
const MAX_RESTORE_RETRIES = 5;

function restoreTriggerBtnPosition() {
  try {
    const savedPosition = localStorage.getItem("mobile-trigger-btn-position");

    if (!savedPosition) {
      restorePositionRetryCount = 0;
      return;
    }

    const pos = JSON.parse(savedPosition);

    // 验证保存的位置是否有效
    if (
      typeof pos.left !== "number" ||
      typeof pos.top !== "number" ||
      pos.left < 0 ||
      pos.top < 0 ||
      isNaN(pos.left) ||
      isNaN(pos.top)
    ) {
      localStorage.removeItem("mobile-trigger-btn-position");
      restorePositionRetryCount = 0;
      return;
    }

    const $btn = $("#mobile-trigger-btn");

    //  获取真实的视口宽度（支持DevTools设备模拟和srcdoc iframe）
    let windowWidth =
      window.innerWidth ||
      document.documentElement.clientWidth ||
      $(window).width();
    let windowHeight =
      window.innerHeight ||
      document.documentElement.clientHeight ||
      $(window).height();

    //  在srcdoc iframe中，所有window尺寸都是0，必须使用父窗口尺寸
    if (window.parent !== window) {
      try {
        // 使用父窗口的 innerWidth（支持DevTools设备模拟）
        const parentWidth =
          window.parent.innerWidth ||
          window.parent.document.documentElement.clientWidth ||
          $(window.parent).width();
        const parentHeight =
          window.parent.innerHeight ||
          window.parent.document.documentElement.clientHeight ||
          $(window.parent).height();

        // 如果当前窗口尺寸为0（srcdoc iframe的情况），使用父窗口尺寸
        if (windowWidth === 0 || windowHeight === 0) {
          windowWidth = parentWidth;
          windowHeight = parentHeight;
        }
      } catch (e) {
        // 无法访问父窗口
      }
    }

    const btnWidth = $btn.outerWidth();
    const btnHeight = $btn.outerHeight();

    // 如果窗口尺寸还是0，检查是否超过最大重试次数
    if (windowWidth === 0 || windowHeight === 0) {
      restorePositionRetryCount++;

      if (restorePositionRetryCount >= MAX_RESTORE_RETRIES) {
        restorePositionRetryCount = 0;
        // 使用默认位置
        $btn.css({
          left: "auto",
          top: "auto",
          right: "20px",
          bottom: "20px",
        });
        return;
      }

      setTimeout(() => {
        restoreTriggerBtnPosition();
      }, 500);
      return;
    }

    // 恢复成功，重置计数器
    restorePositionRetryCount = 0;

    //  响应式位置检测：如果是小屏幕，使用默认位置
    const isSmallScreen = windowWidth <= 768;
    const isMobileScreen = windowWidth <= 480;

    //  检查用户是否手动拖动过
    const userDragged =
      localStorage.getItem("mobile-trigger-btn-user-dragged") === "true";

    if (userDragged) {
      // 移除模式类，使用保存的坐标
      $btn.removeClass("mobile-mode tablet-mode desktop-mode");
    } else {
      // 如果是移动端小屏幕，且保存的位置明显是大屏幕的坐标
      if (isMobileScreen && (pos.left > 600 || pos.top > 600)) {
        //  关键修复：移除内联样式并添加CSS类
        $btn[0].style.removeProperty("left");
        $btn[0].style.removeProperty("top");
        $btn[0].style.removeProperty("right");
        $btn[0].style.removeProperty("bottom");
        $btn[0].style.removeProperty("transform");
        $btn.removeClass("tablet-mode desktop-mode").addClass("mobile-mode");
        return;
      }

      // 小屏幕时使用默认位置，避免位置错乱
      if (
        isSmallScreen &&
        (pos.left > windowWidth * 0.8 || pos.top > windowHeight * 0.8)
      ) {
        //  关键修复：移除内联样式并添加CSS类
        $btn[0].style.removeProperty("left");
        $btn[0].style.removeProperty("top");
        $btn[0].style.removeProperty("right");
        $btn[0].style.removeProperty("bottom");
        $btn.removeClass("mobile-mode desktop-mode").addClass("tablet-mode");
        return;
      }

      // 桌面端：移除模式类
      $btn.removeClass("mobile-mode tablet-mode").addClass("desktop-mode");
    }

    // 使用工具函数进行边界限制
    const bounded = constrainFullyInViewport(
      pos.left,
      pos.top,
      btnWidth,
      btnHeight,
    );

    $btn.css({
      left: bounded.x + "px",
      top: bounded.y + "px",
      right: "auto",
      bottom: "auto",
    });
  } catch (e) {
    localStorage.removeItem("mobile-trigger-btn-position");
    restorePositionRetryCount = 0;
  }
}

// ==================== 手动调整按钮位置（调试用） ====================
window.resetMobileButtonPosition = function () {
  let windowWidth =
    window.innerWidth ||
    document.documentElement.clientWidth ||
    $(window).width();

  //  srcdoc iframe中尺寸为0，使用父窗口尺寸
  if (windowWidth === 0 && window.parent !== window) {
    try {
      windowWidth =
        window.parent.innerWidth ||
        window.parent.document.documentElement.clientWidth ||
        $(window.parent).width();
    } catch (e) {
      // 无法访问父窗口
    }
  }

  const $btn = $("#mobile-trigger-btn");
  const btnElement = $btn[0];

  //  移除所有内联定位样式
  btnElement.style.removeProperty("left");
  btnElement.style.removeProperty("top");
  btnElement.style.removeProperty("right");
  btnElement.style.removeProperty("bottom");

  //  根据屏幕宽度强制设置位置（带!important）
  if (windowWidth <= 480) {
    $btn.removeClass("tablet-mode desktop-mode").addClass("mobile-mode");
    //  强制设置内联样式（带!important），右边垂直居中
    btnElement.style.setProperty("left", "auto", "important");
    btnElement.style.setProperty("top", "50%", "important");
    btnElement.style.setProperty("right", "12px", "important");
    btnElement.style.setProperty("bottom", "auto", "important");
    btnElement.style.setProperty("transform", "translateY(-50%)", "important");
  } else if (windowWidth <= 768) {
    $btn.removeClass("mobile-mode desktop-mode").addClass("tablet-mode");
    btnElement.style.setProperty("left", "auto", "important");
    btnElement.style.setProperty("top", "auto", "important");
    btnElement.style.setProperty("right", "15px", "important");
    btnElement.style.setProperty("bottom", "15px", "important");
    btnElement.style.setProperty("transform", "none", "important");
  } else {
    //  桌面端：离右边三分之一距离的垂直中央
    $btn.removeClass("mobile-mode tablet-mode").addClass("desktop-mode");
    btnElement.style.setProperty("left", "auto", "important");
    btnElement.style.setProperty("top", "50%", "important");
    btnElement.style.setProperty("right", "20%", "important");
    btnElement.style.setProperty("bottom", "auto", "important");
    btnElement.style.setProperty("transform", "translateY(-50%)", "important");
  }

  // 清除保存的位置和拖动标记，避免下次加载时恢复错误位置
  localStorage.removeItem("mobile-trigger-btn-position");
  localStorage.removeItem("mobile-trigger-btn-user-dragged");
};

// ==================== 页面滑动功能 ====================
let pageSwipe = {
  currentPageIndex: 0,
  totalPages: 1,
  isDragging: false,
  hasMoved: false, //  是否真正移动过（用于区分点击和滑动）
  startX: 0,
  currentX: 0,
  threshold: 50, // 拖拽阈值
  initialized: false,
  wrapper: null, // 保存wrapper引用
  indicators: null, // 保存indicators引用
  boundHandleMove: null, // 保存绑定的move函数
  boundHandleEnd: null, // 保存绑定的end函数
  justFinishedDragging: false, // 刚完成拖动（防止立即触发click关闭）

  init: function () {
    // 尝试从jQuery和原生DOM两种方式获取
    let wrapper = document.getElementById("app-pages-wrapper");
    let indicators = document.getElementById("page-indicators");

    // 如果原生找不到，尝试jQuery
    if (!wrapper) {
      const $wrapper = $("#mobile-phone-overlay #app-pages-wrapper");
      wrapper = $wrapper.length > 0 ? $wrapper[0] : null;
    }

    if (!indicators) {
      const $indicators = $("#mobile-phone-overlay #page-indicators");
      indicators = $indicators.length > 0 ? $indicators[0] : null;
    }

    if (!wrapper || !indicators) {
      return;
    }

    // 保存引用
    this.wrapper = wrapper;
    this.indicators = indicators;

    // 创建绑定的函数引用（用于后续移除监听器）
    this.boundHandleMove = this.handleMove.bind(this);
    this.boundHandleEnd = this.handleEnd.bind(this);

    // 鼠标事件 (PC端)
    wrapper.addEventListener("mousedown", this.handleStart.bind(this));
    wrapper.addEventListener("mousemove", this.boundHandleMove);
    wrapper.addEventListener("mouseup", this.boundHandleEnd);
    wrapper.addEventListener("mouseleave", this.boundHandleEnd);

    // 触摸事件 (移动端)
    wrapper.addEventListener("touchstart", this.handleStart.bind(this), {
      passive: false,
    });
    wrapper.addEventListener("touchmove", this.handleMove.bind(this), {
      passive: false,
    });
    wrapper.addEventListener("touchend", this.handleEnd.bind(this));

    // 指示器点击事件
    const indicatorElements = indicators.querySelectorAll(".indicator");
    indicatorElements.forEach((indicator, index) => {
      indicator.addEventListener("click", () => {
        this.goToPage(index);
      });
    });
  },

  handleStart: function (e) {
    //  不要立即阻止传播，让点击事件能正常触发
    // 只在真正滑动时（handleMove）才阻止传播

    this.isDragging = true;
    this.hasMoved = false; //  记录是否真的移动了
    this.startX = e.type === "mousedown" ? e.clientX : e.touches[0].clientX;
    this.currentX = this.startX;

    if (this.wrapper) {
      this.wrapper.style.transition = "none";
    }

    // 鼠标事件：在document上监听move和up，防止滑出区域
    if (e.type === "mousedown") {
      document.addEventListener("mousemove", this.boundHandleMove);
      document.addEventListener("mouseup", this.boundHandleEnd);
    }
  },

  handleMove: function (e) {
    if (!this.isDragging) return;

    this.currentX = e.type === "mousemove" ? e.clientX : e.touches[0].clientX;
    const deltaX = this.currentX - this.startX;

    //  只有当移动超过5px时，才认为是真正的滑动
    if (Math.abs(deltaX) > 5) {
      if (!this.hasMoved) {
        this.hasMoved = true;
      }

      // 现在才阻止默认行为和传播
      e.preventDefault();
      e.stopPropagation();

      if (this.wrapper) {
        const translateX =
          -this.currentPageIndex * 100 +
          (deltaX / this.wrapper.offsetWidth) * 100;
        this.wrapper.style.transform = `translateX(${translateX}%)`;
      }
    }
  },

  handleEnd: function (e) {
    if (!this.isDragging) return;

    const deltaX = this.currentX - this.startX;

    //  只有当真正滑动过，才阻止事件传播
    if (this.hasMoved) {
      e.preventDefault();
      e.stopPropagation();
    }

    this.isDragging = false;

    // 移除document上的事件监听器
    document.removeEventListener("mousemove", this.boundHandleMove);
    document.removeEventListener("mouseup", this.boundHandleEnd);

    //  只有真正滑动过，才需要处理页面切换和设置标志
    if (this.hasMoved) {
      // 设置刚完成拖动标志，防止立即触发click关闭手机
      this.justFinishedDragging = true;
      setTimeout(() => {
        this.justFinishedDragging = false;
      }, 100);

      if (this.wrapper) {
        // 恢复过渡效果
        this.wrapper.style.transition = "transform 0.3s ease-out";

        // 判断是否需要切换页面
        if (Math.abs(deltaX) > this.threshold) {
          if (deltaX > 0 && this.currentPageIndex > 0) {
            // 向右滑动，切换到上一页
            this.goToPage(this.currentPageIndex - 1);
          } else if (
            deltaX < 0 &&
            this.currentPageIndex < this.totalPages - 1
          ) {
            // 向左滑动，切换到下一页
            this.goToPage(this.currentPageIndex + 1);
          } else {
            // 回到当前页
            this.goToPage(this.currentPageIndex);
          }
        } else {
          // 回到当前页
          this.goToPage(this.currentPageIndex);
        }
      }
    }
  },

  goToPage: function (pageIndex) {
    if (pageIndex < 0 || pageIndex >= this.totalPages) return;

    this.currentPageIndex = pageIndex;
    if (this.wrapper) {
      this.wrapper.style.transform = `translateX(-${pageIndex * 100}%)`;
    }

    // 更新指示器
    this.updateIndicators();
  },

  updateIndicators: function () {
    if (!this.indicators) return;

    const indicatorElements = this.indicators.querySelectorAll(".indicator");
    indicatorElements.forEach((indicator, index) => {
      if (index === this.currentPageIndex) {
        indicator.classList.add("active");
      } else {
        indicator.classList.remove("active");
      }
    });
  },
};

function initPageSwipe() {
  pageSwipe.init();
}


