      dateStr = _.get(currentPhoneData, "银麒系统.世界.日期", null);
      timeStr = _.get(currentPhoneData, "银麒系统.世界.时刻", null);
    }

    // 降级：从window.mvuGameData读取
    if (!dateStr && window.mvuGameData) {
