      timeStr = _.get(window.mvuGameData, "银麒系统.世界.时刻", null);
    }

    // 组合为兼容格式传给updatePhoneTimeFromMVU
    if (dateStr || timeStr) {
      var combined = (dateStr || "") + " " + (timeStr || "");
      updatePhoneTimeFromMVU(combined.trim());
    }
  } catch (error) {
    /* 静默失败 */
  }
}

/* 从MVU时间字符串解析并更新显示 */
function updatePhoneTimeFromMVU(currentTimeStr) {
  // currentTimeStr 格式: "2024年11月9日 星期六 14:30"
  if (!currentTimeStr) return;

  try {
    // 提取时间部分
    const timeMatch = currentTimeStr.match(/(\d{1,2}:\d{2})$/);
    const timeString = timeMatch ? timeMatch[1] : "14:30";

    // 提取日期部分（年月日）
    const dateMatch = currentTimeStr.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
    // 提取星期
    const weekMatch = currentTimeStr.match(/(星期[一二三四五六日天])/);
    const weekDay = weekMatch ? weekMatch[1] : "";

    let dateString = "9月16日";
    if (dateMatch) {
      const month = dateMatch[2];
      const day = dateMatch[3];
      dateString = month + "月" + day + "日";
    }
    // 组合：星期六 10月24日
    const fullDate = weekDay ? weekDay + " " + dateString : dateString;

    // 更新锁屏时间和日期
    $("#phone-big-time").text(timeString);
    $("#phone-date").text(fullDate);

    // 更新状态栏时间
    $("#phone-status-time").text(timeString);

    // 根据时间推断天气图标和描述
    const hour = timeMatch ? parseInt(timeMatch[1].split(":")[0]) : 14;
    let weatherIcon = "fa-cloud-sun";
    let weatherText = "多云";
    if (hour >= 6 && hour < 9) {
      weatherIcon = "fa-sun";
      weatherText = "晴";
    } else if (hour >= 9 && hour < 17) {
      weatherIcon = "fa-cloud-sun";
      weatherText = "多云";
    } else if (hour >= 17 && hour < 19) {
      weatherIcon = "fa-cloud-sun";
      weatherText = "傍晚";
    } else if (hour >= 19 || hour < 6) {
      weatherIcon = "fa-moon";
      weatherText = "夜间";
    }

    const $weatherIcon = $(".weather-info i");
    const $weatherDesc = $("#phone-weather");
    if ($weatherIcon.length) {
      $weatherIcon.attr("class", "fas " + weatherIcon);
    }
    if ($weatherDesc.length) {
      $weatherDesc.text(weatherText);
    }
  } catch (error) {}
}

