// 初始化手机界面拖动（复用小按钮的拖动逻辑）
function initPhoneDrag() {
  const $dragHandle = $("#phone-drag-handle");
  const $phoneFrame = $(".mobile-phone-frame");

  if ($dragHandle.length === 0 || $phoneFrame.length === 0) {
    return;
  }

  const dragHandle = $dragHandle[0];

  // 阻止拖动手柄上的点击事件冒泡
  $dragHandle.on("click", function (e) {
    e.stopPropagation();
  });

  // 使用原生 Pointer Events（更可靠）
  dragHandle.addEventListener("pointerdown", handlePhoneDragStart);
  dragHandle.addEventListener("pointermove", handlePhoneDragMove);
  dragHandle.addEventListener("pointerup", handlePhoneDragEnd);
  dragHandle.addEventListener("pointercancel", handlePhoneDragEnd);
}

function handlePhoneDragStart(e) {
  // 阻止默认行为和冒泡
  e.preventDefault();
  e.stopPropagation();

  isPhoneDragging = true;

  // 捕获指针，确保后续的 pointermove 和 pointerup 事件能够被触发
  e.target.setPointerCapture(e.pointerId);

  const $phoneFrame = $(".mobile-phone-frame");

  phoneDragStartX = e.clientX;
  phoneDragStartY = e.clientY;

  // 先立即移除过渡和动画，避免在读取 transform 时受过渡影响
  $phoneFrame.css({
    animation: "none",
    transition: "none",
  });

  // 强制浏览器重新计算样式（确保过渡被立即停止）
  $phoneFrame[0].offsetHeight;

  // 读取当前的 transform 值（停止过渡后，这个值是准确的）
  const currentTransform = $phoneFrame.css("transform");
  if (currentTransform && currentTransform !== "none") {
    const matrix = currentTransform.match(/matrix\(([^)]+)\)/);
    if (matrix) {
      const values = matrix[1].split(", ");
      phoneStartX = parseFloat(values[4]) || 0;
      phoneStartY = parseFloat(values[5]) || 0;
    } else {
      phoneStartX = 0;
      phoneStartY = 0;
    }
  } else {
    phoneStartX = 0;
    phoneStartY = 0;
  }
}

function handlePhoneDragMove(e) {
  if (!isPhoneDragging) return;

  e.preventDefault();

  // 计算移动距离
  const deltaX = e.clientX - phoneDragStartX;
  const deltaY = e.clientY - phoneDragStartY;

  // 计算新的 transform 偏移
  const newX = phoneStartX + deltaX;
  const newY = phoneStartY + deltaY;

  // 获取手机框架和视口信息
  const $phoneFrame = $(".mobile-phone-frame");
  const frameRect = $phoneFrame[0].getBoundingClientRect();
  const frameWidth = frameRect.width || 375;
  const frameHeight = frameRect.height || 737;
  const viewport = getViewportSize();

  // 计算手机框架的初始中心位置（无 transform 时的位置）
  // 手机框架通过 flexbox 居中，所以初始位置是视口中心
  const initialCenterX = viewport.width / 2;
  const initialCenterY = viewport.height / 2;

  // 计算应用 transform 后的实际位置
  const actualLeft = initialCenterX - frameWidth / 2 + newX;
  const actualTop = initialCenterY - frameHeight / 2 + newY;

  // 边界限制：确保至少有 minVisible 像素在屏幕内
  const minVisible = 80;
  const minX = -frameWidth + minVisible;
  const maxX = viewport.width - minVisible;
  const minY = -frameHeight + minVisible;
  const maxY = viewport.height - minVisible;

  // 限制实际位置
  const boundedLeft = clamp(actualLeft, minX, maxX);
  const boundedTop = clamp(actualTop, minY, maxY);

  // 反算回 transform 值
  const boundedTransformX = boundedLeft - (initialCenterX - frameWidth / 2);
  const boundedTransformY = boundedTop - (initialCenterY - frameHeight / 2);

  // 应用 transform
  $phoneFrame.css(
    "transform",
    `translate(${boundedTransformX}px, ${boundedTransformY}px)`,
  );
}

function handlePhoneDragEnd(e) {
  if (!isPhoneDragging) return;

  isPhoneDragging = false;

  // 释放指针捕获
  if (e.target.hasPointerCapture && e.target.hasPointerCapture(e.pointerId)) {
    e.target.releasePointerCapture(e.pointerId);
  }
}

/**
 * 删除图片时清理源APP中的引用
 */
function _cleanImageRefFromSource(imageId, entry) {
  var source = entry.source || "";
  if (source === "forum") {
    var manager = window.phoneForumManager;
    if (manager) {
      var pools = [
        manager.loadForumData(),
        manager.loadCommentedPosts(),
        manager.loadUserPosts(),
      ];
      var saveFs = [
        function () {
          manager.saveForumData();
        },
        function () {
          manager.commentedPosts = pools[1];
          manager.saveCommentedPosts();
        },
        function () {
          manager.userPosts = pools[2];
          manager.saveUserPosts();
        },
      ];
      for (var pi = 0; pi < pools.length; pi++) {
        var arr = pools[pi];
        if (!arr) continue;
        for (var fi = 0; fi < arr.length; fi++) {
          if (arr[fi].imageId === imageId) {
            arr[fi].imageId = null;
            saveFs[pi]();
          }
        }
      }
    }
  }
  if (source === "taskEval") {
    var taskHist = getPhoneMeta("yinqi_task_history", []);
    if (taskHist && taskHist.length) {
      var changed = false;
      for (var thi = 0; thi < taskHist.length; thi++) {
        if (taskHist[thi].generatedImageId === imageId) {
          taskHist[thi].generatedImageId = null;
          changed = true;
        }
      }
      if (changed) setPhoneMeta("yinqi_task_history", taskHist);
    }
  }
  if (source === "live") {
    var rooms = getLiveData();
    for (var li = 0; li < rooms.length; li++) {
      if (rooms[li].coverImageId === imageId) rooms[li].coverImageId = null;
      if (rooms[li].currentSceneImageId === imageId)
        rooms[li].currentSceneImageId = null;
    }
    setLiveData(rooms);
  }
  if (source === "surveillance") {
    var loc = entry.location || "";
    if (loc) {
      // v13: cam_images 存 imageId 引用
      var camImages = getPhoneMetaBig("cam_images", {});
      if (camImages[loc]) {
        delete camImages[loc];
        setPhoneMetaBig("cam_images", camImages);
      }
    }
  }
  if (source === "moments") {
    var moments = getPhoneMetaBig("moments", []);
    for (var mi = 0; mi < moments.length; mi++) {
      if (moments[mi].imageId === imageId) moments[mi].imageId = null;
    }
    setPhoneMetaBig("moments", moments);
  }
  if (source === "chat") {
    var allChat = getPhoneMetaBig("chat_history", {});
    var chatKeys = Object.keys(allChat);
    for (var ci = 0; ci < chatKeys.length; ci++) {
      var msgs = allChat[chatKeys[ci]];
      for (var mi2 = 0; mi2 < msgs.length; mi2++) {
        if (msgs[mi2].imageId === imageId) {
          msgs[mi2].imageId = null;
          msgs[mi2].isImage = false;
        }
      }
    }
    setPhoneMetaBig("chat_history", allChat);
  }
}

