    $body
      .find(".ai-awareness-save-btn")
      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var prev =
          typeof window.getAiAwarenessV2Config === "function"
            ? window.getAiAwarenessV2Config()
            : { modules: {}, moduleOrder: [] };
        var settings = {
          enabled: $(".ai-awareness-v2-enabled").is(":checked"),
          tokenBudgetTotal: Number($(".ai-awareness-budget").val()) || 10000,
          tokenEstimator: "char_approx",
          presetMode:
            String(
              $(".ai-awareness-current-preset").attr("data-preset") || "",
            ) || "",
          moduleOrder: [],
          modules: {},
        };
        if ($(".ai-awareness-source-toggle").length > 0) {
          var detail = String(
            $(".ai-awareness-global-detail").val() || "normal",
          );
          var sources = {
            social: $(".ai-awareness-source-toggle[data-source='social']").is(
              ":checked",
            ),
            forum: $(".ai-awareness-source-toggle[data-source='forum']").is(
              ":checked",
            ),
            live: $(".ai-awareness-source-toggle[data-source='live']").is(
              ":checked",
            ),
            memory: $(".ai-awareness-source-toggle[data-source='memory']").is(
              ":checked",
            ),
          };
          function _readLv(src) {
            var v = String(
              $(
                ".ai-awareness-source-level[data-source='" + src + "']",
              ).val() || "",
            );
            if (v === "low" || v === "mid" || v === "high" || v === "unlimited")
              return v;
            // 缺省由全局详细度映射
            if (detail === "brief") return "low";
            if (detail === "rich") return "high";
            return "mid";
          }
          var levels = {
            social: _readLv("social"),
            forum: _readLv("forum"),
            live: _readLv("live"),
            memory: _readLv("memory"),
          };
          settings.uiSimplified = {
            detailLevel: detail,
            sources: sources,
            levels: levels,
          };
          var _srcMap = window.YQ_AW_SOURCE_MODULES || {
            social: ["wechatAuto", "wechatHistory", "moments"],
            forum: ["forumPosts", "forumComments"],
            live: ["liveInteraction", "storyLiveEvents"],
            memory: ["unifiedCharacterMemory"],
          };
          var _lv2Cfg =
            typeof window._yqAwLevelToModuleCfg === "function"
              ? window._yqAwLevelToModuleCfg
              : function (_lv, _n) {
                  return {
                    detailLevel: "normal",
                    maxTokens: 1500,
                    minReserveTokens: 200,
                  };
                };
          // 为每个 source 下的模块写入 (enabled, detailLevel, maxTokens, minReserveTokens)
          Object.keys(_srcMap).forEach(function (srcKey) {
            var mods = _srcMap[srcKey];
            var mCfg = _lv2Cfg(levels[srcKey], mods.length);
            var en = sources[srcKey] !== false;
            // 默认优先级
            var _prioMap = {
              wechatAuto: "mid",
              wechatHistory: "mid",
              moments: "mid",
              forumPosts: "mid",
              forumComments: "mid",
              liveInteraction: "mid",
              storyLiveEvents: "high",
              unifiedCharacterMemory: "high",
            };
            for (var i = 0; i < mods.length; i++) {
              var mk = mods[i];
              settings.modules[mk] = {
                enabled: !!en,
                priority: _prioMap[mk] || "mid",
                detailLevel: mCfg.detailLevel,
                weight: en ? 2 : 0,
                maxTokens: mCfg.maxTokens, // null = 不限
                minReserveTokens: en ? mCfg.minReserveTokens : 0,
              };
            }
          });
          settings.moduleOrder = [
            "wechatAuto",
            "wechatHistory",
            "moments",
            "forumPosts",
            "forumComments",
            "liveInteraction",
            "unifiedCharacterMemory",
            "storyLiveEvents",
          ];
        } else {
          $(".ai-awareness-v2-module-card").each(function () {
            var key = String($(this).data("key") || "");
            if (!key) return;
            settings.moduleOrder.push(key);
            settings.modules[key] = {
              enabled: $(
                ".ai-awareness-v2-module-enabled[data-key='" + key + "']",
              ).is(":checked"),
              priority:
                $(".ai-awareness-v2-priority[data-key='" + key + "']").val() ||
                "mid",
              detailLevel:
                $(".ai-awareness-v2-detail[data-key='" + key + "']").val() ||
                "normal",
              weight:
                Number(
                  $(".ai-awareness-v2-weight[data-key='" + key + "']").val(),
                ) || 1,
              minReserveTokens:
                Number(
                  $(
                    ".ai-awareness-v2-minreserve[data-key='" + key + "']",
                  ).val(),
                ) || 0,
            };
          });
        }
        if (!settings.moduleOrder.length && Array.isArray(prev.moduleOrder)) {
          settings.moduleOrder = prev.moduleOrder.slice();
        }
        if (typeof window.saveAiAwarenessV2Config === "function")
          settings = window.saveAiAwarenessV2Config(settings);
        else setPhoneMeta("ai_awareness_v2", settings);
        // 触发论坛/直播摘要重新生成
        if (typeof triggerForumSummaryOnLeave === "function") {
