      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (!window.PhoneCharacterAppearance) return;
        var allChars = window.PhoneCharacterAppearance.getAll();
        var names = Object.keys(allChars);
        if (names.length === 0) return;
        /* 筛选没有头像的角色 */
        var pending = [];
        for (var ni = 0; ni < names.length; ni++) {
          var av =
            typeof getCharacterAvatar === "function"
              ? getCharacterAvatar(names[ni])
              : null;
          if (!av) pending.push(names[ni]);
        }
        if (pending.length === 0) {
          yqToast("info", "所有角色都已有头像");
          return;
        }
        if (
          !confirm(
            "为 " +
              pending.length +
              " 个角色批量生成头像？\n（已有头像的角色会跳过）",
          )
        )
          return;
        var $btn = $(this);
        $btn
          .prop("disabled", true)
          .html('<i class="fas fa-spinner fa-spin"></i> 生成中...');
        var success = 0,
          fail = 0,
          idx = 0;
        function doNext() {
          if (idx >= pending.length) {
            $btn
              .prop("disabled", false)
              .html('<i class="fas fa-camera"></i> 批量头像');
            yqToast(
              "success",
              "批量头像完成：成功 " + success + " / 失败 " + fail,
            );
            $("#phone-app-body").html(generateCharacterAppPanel());
            bindPanelButtons();
            return;
          }
          var cn = pending[idx];
          idx++;
          $btn.html(
            '<i class="fas fa-spinner fa-spin"></i> ' +
              idx +
              "/" +
              pending.length,
          );
          window.PhoneCharacterAppearance.generateAvatar(cn)
            .then(function (r) {
              if (r.success) {
                success++;
                // 局部刷新：立即更新该角色的头像显示
                var avatarUrl =
                  typeof getCharacterAvatar === "function"
                    ? getCharacterAvatar(cn)
                    : null;
                if (avatarUrl) {
                  var $wrap = $(
                    '.char-avatar-wrap[data-name="' +
                      cn.replace(/"/g, '\\"') +
                      '"]',
                  );
                  if ($wrap.length) {
                    $wrap.html(
                      '<img src="' +
                        avatarUrl +
                        '" style="width:40px;height:40px;border-radius:6px;object-fit:cover;">',
                    );
                  }
                }
              } else fail++;
              doNext();
            })
            .catch(function () {
              fail++;
              doNext();
            });
        }
        doNext();
      });

