        if (!confirm("确定删除服装「" + (outfit.nameCN || outfitId) + "」？"))
          return;
        window.PhoneWardrobe.remove(outfitId);
        yqToast("success", "已删除");
        $("#phone-app-body").html(generateCharacterAppPanel());
        bindPanelButtons();
      });

    /* 衣柜——添加服装 */
    $body
      .find(".char-wardrobe-add")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        if (!window.PhoneWardrobe) return;
        var nameCN = prompt("服装中文名：");
        if (!nameCN || !nameCN.trim()) return;
        var nameEN = prompt("服装英文名（用于生图tag）：");
        if (!nameEN || !nameEN.trim()) return;
        var upper = prompt(
          "上半身tag（英文，如 white blouse, lace trim）：",
          "",
        );
        var full = prompt(
          "下半身/全身tag（英文，如 black skirt, high heels）：",
          "",
        );
        var newOutfit = {
          id: window.PhoneWardrobe._genId(),
          nameCN: nameCN.trim(),
          nameEN: nameEN.trim(),
          gender: nameCN.trim().indexOf("-男") !== -1 ? "male" : "female",
          upperBody: (upper || "").trim(),
          upperBodyBack: "",
          fullBody: (full || "").trim(),
          fullBodyBack: "",
          imageId: "",
          createdAt: Date.now(),
        };
        window.PhoneWardrobe.save(newOutfit);
        yqToast("success", "已添加「" + nameCN.trim() + "」");
        $("#phone-app-body").html(generateCharacterAppPanel());
        bindPanelButtons();
      });

    /* 衣柜——重置为预设 */
    $body
      .find(".char-wardrobe-reset")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        if (!window.PhoneWardrobe) return;
        if (!confirm("确定重置衣柜为预设服装？\n当前所有自定义服装将被清除。"))
          return;
        setPhoneMeta(window.PhoneWardrobe._storageKey, {});
        debounceSavePhoneMeta();
        window.PhoneWardrobe.initDefaults();
        yqToast("success", "衣柜已重置为预设");
        $("#phone-app-body").html(generateCharacterAppPanel());
        bindPanelButtons();
      });

    /* 论坛帖子举报/删除按钮（列表页） */
    $body
      .find(".forum-post-report-btn")
      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var pi = parseInt($(this).data("post-index"));
        var ps = $(this).data("source") || "auto";
        var isOwn = ps === "user";
        var msg = isOwn
          ? "确定要删除这条帖子吗？"
          : "确定要举报（封禁）这条帖子吗？";
        if (!confirm(msg)) return;
        if (window.phoneForumDeletePost) window.phoneForumDeletePost(pi, ps);
      });

    /* 直播间列表举报/删除按钮 */
    $body
      .find(".live-room-report-btn")
      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var roomId = $(this).data("room-id");
        if (!roomId) return;
        if (window.phoneLiveDeleteRoom) window.phoneLiveDeleteRoom(roomId);
      });

    /* 监控——安装摄像头按钮 */
    $body
      .find(".phone-cam-install-btn")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        if ($(this).prop("disabled")) return;
        if (window.phoneInstallCamera) window.phoneInstallCamera();
      });

    /* 监控——入侵手机按钮 */
    $body
      .find(".phone-cam-hack-btn")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        if ($(this).prop("disabled")) return;
        if (window.phoneHackPhone) window.phoneHackPhone();
      });

    /* 监控——拆除摄像头按钮（旧系统，保留兼容） */
    $body
      .find(".phone-cam-delete-btn")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        var loc = $(this).data("location");
        var type = $(this).data("type");
        if (!loc) return;
        if (type === "phone") {
          if (window.phoneRemoveBackdoor) window.phoneRemoveBackdoor(loc);
        } else {
          if (window.phoneRemoveCamera) window.phoneRemoveCamera(loc);
        }
      });

    /* 纳米监控——移除监控目标 */
    $body
      .find(".surv-remove-btn")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        var name = $(this).data("name");
        if (!name) return;
        if (!confirm("确定移除对「" + name + "」的监控？道具不会恢复。"))
          return;
        var targets = getPhoneMeta("yinqi_surveillance_targets", []);
        targets = targets.filter(function (t) {
          return (t.name || t) !== name;
        });
        setPhoneMeta("yinqi_surveillance_targets", targets);
        // 清除MVU中的监控数据
        try {
          var tw = window.parent || window;
          if (tw.SillyTavern && tw.SillyTavern.getContext) {
            var ctx = tw.SillyTavern.getContext();
            if (ctx && ctx.setVariable) {
              ctx.setVariable("stat_data.银麒系统.监控." + name, undefined);
            }
          }
        } catch (e2) {}
        // 清除扩写历史和图片
        var camHist = getPhoneMetaBig("cam_history", {});
        delete camHist["surv_" + name];
        setPhoneMetaBig("cam_history", camHist);
        var camImages = getPhoneMetaBig("cam_images", {});
        var _imgA = camImages["surv_" + name];
        var _imgB = camImages[name];
        if (_imgA && window.phoneImageStore)
          window.phoneImageStore.remove(_imgA);
        if (_imgB && _imgB !== _imgA && window.phoneImageStore)
          window.phoneImageStore.remove(_imgB);
        delete camImages["surv_" + name];
        delete camImages[name];
        setPhoneMetaBig("cam_images", camImages);
        yqToast("info", "已移除对「" + name + "」的监控");
        fetchLatestMvuData(true);
        $("#phone-app-body").html(generateSurveillancePanel(currentPhoneData));
        bindPanelButtons();
      });

    /* 纳米监控——扩写画面 */
    $body
      .find(".surv-expand-btn")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        var name = $(this).data("name");
        if (!name) return;
        var $btn = $(this);
        $btn.prop("disabled", true).text("⏳ 扩写中...");
        _expandSurveillanceDetail(name).finally(function () {
          $btn.prop("disabled", false).text("🔍 扩写画面");
        });
      });

    /* 纳米监控——生成图片 */
    $body
      .find(".surv-image-btn")
      .off("click")
      .on("click", function (e) {
        e.stopPropagation();
        var name = $(this).data("name");
        if (!name) return;
        var $btn = $(this);
        $btn.prop("disabled", true).text("⏳ 生图中...");
        _generateSurveillanceImage(name).finally(function () {
          $btn.prop("disabled", false).text("🎨 生成图片");
        });
      });

    /* 相册——导出相册 */
    $body
      .find(".gallery-export-btn")
      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (window.phoneExportGallery) window.phoneExportGallery();
      });

    /* 相册——导入相册 */
    $body
      .find(".gallery-import-btn")
      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        $body.find(".gallery-import-file").click();
      });
    $body
      .find(".gallery-import-file")
      .off("change")
      .on("change", function (e) {
        var file = e.target.files[0];
        if (!file) return;
        // 大文件（>30MB）直接传File对象给流式导入，避免readAsText OOM
        if (file.size > 30 * 1024 * 1024) {
          if (window.phoneImportGallery) window.phoneImportGallery(file);
        } else {
          var reader = new FileReader();
          reader.onload = function (ev) {
            if (window.phoneImportGallery)
              window.phoneImportGallery(ev.target.result);
          };
          reader.readAsText(file);
        }
        $(this).val("");
      });

    /* 相册——批量删除模式 */
    $body
      .find(".gallery-batch-delete-btn")
      .off("click")
      .on("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var $thumbs = $body.find(".gallery-thumb");
        if ($thumbs.length === 0) {
          yqToast("warning", "当前没有图片");
          return;
        }
        // 检查是否已在选择模式
        var $bar = $("#phone-app-body").find(".gallery-batch-bar");
        if ($bar.length > 0) {
          $bar.remove();
          $body.find(".gallery-select-check").remove();
          return;
        }
        // 进入选择模式：给每个缩略图加checkbox覆盖层
        $thumbs.each(function () {
          var imgId = $(this).data("image-id");
          $(this).append(
            '<div class="gallery-select-check" data-sel-id="' +
              imgId +
              '" style="position:absolute;top:2px;left:2px;width:20px;height:20px;' +
              "background:rgba(0,0,0,0.6);border:2px solid #6366f1;border-radius:4px;" +
              'cursor:pointer;display:flex;align-items:center;justify-content:center;z-index:5;font-size:12px;color:white;"></div>',
          );
        });
        // 底部操作栏
        var barHtml =
          '<div class="gallery-batch-bar" style="position:sticky;bottom:0;padding:8px;' +
          "background:#1e293b;border-top:2px solid #6366f1;" +
          'display:flex;gap:6px;align-items:center;justify-content:center;z-index:10;">';
        barHtml +=
          '<button type="button" class="gallery-sel-all-btn yq-btn yq-btn--indigo yq-btn--xs">全选</button>';
        barHtml +=
          '<button type="button" class="gallery-sel-none-btn yq-btn yq-btn--surface-600 yq-btn--xs">取消全选</button>';
        barHtml +=
          '<span class="gallery-sel-count" style="font-size:11px;color:#9ca3af;">已选 0</span>';
        barHtml +=
          '<button type="button" class="gallery-sel-delete-btn yq-btn yq-btn-danger yq-btn--xs">删除</button>';
        barHtml +=
          '<button type="button" class="gallery-sel-cancel-btn yq-btn yq-btn--surface-800 yq-btn--xs">退出</button>';
        barHtml += "</div>";
        $("#phone-app-body").append(barHtml);

        // 直接绑定底部操作栏按钮事件（不依赖document委托）
        var $newBar = $("#phone-app-body").find(".gallery-batch-bar");
        $newBar.find(".gallery-sel-all-btn").on("click", function (ev) {
          ev.preventDefault();
          ev.stopPropagation();
          $(".gallery-select-check").each(function () {
            $(this)
              .data("selected", true)
              .html("✓")
              .css("border-color", "#10b981");
          });
          $(".gallery-sel-count").text(
            "已选 " + $(".gallery-select-check").length,
          );
        });
        $newBar.find(".gallery-sel-none-btn").on("click", function (ev) {
          ev.preventDefault();
          ev.stopPropagation();
          $(".gallery-select-check").each(function () {
            $(this)
              .data("selected", false)
              .html("")
              .css("border-color", "#6366f1");
          });
          $(".gallery-sel-count").text("已选 0");
        });
        $newBar.find(".gallery-sel-delete-btn").on("click", function (ev) {
          ev.preventDefault();
          ev.stopPropagation();
          var ids = [];
          $(".gallery-select-check").each(function () {
            if ($(this).data("selected")) ids.push($(this).data("sel-id"));
          });
          if (ids.length === 0) {
            yqToast("warning", "请先选择要删除的图片");
            return;
          }
          if (
            !confirm(
              "确定删除选中的 " + ids.length + " 张图片？此操作不可撤销。",
            )
          )
            return;
          var store = window.phoneImageStore;
          if (!store) return;
          var idSet = {};
          for (var di = 0; di < ids.length; di++) {
            idSet[ids[di]] = true;
            delete store._cache[ids[di]];
            store._dbDelete(ids[di]);
            try {
              localStorage.removeItem(store.STORAGE_PREFIX + ids[di]);
            } catch (ex) {}
          }
          var idx = getPhoneMetaBig("image_index", []);
          setPhoneMetaBig(
            "image_index",
            idx.filter(function (item) {
              return !idSet[item.id];
            }),
          );
          debounceSavePhoneMeta();
          yqToast("success", "已删除 " + ids.length + " 张图片");
          if (currentPanel === "gallery") {
            $("#phone-app-body").html(generateGalleryPanel());
            bindPanelButtons();
          }
        });
        $newBar.find(".gallery-sel-cancel-btn").on("click", function (ev) {
          ev.preventDefault();
          ev.stopPropagation();
          $(".gallery-batch-bar").remove();
          $(".gallery-select-check").remove();
        });
      });

    // 银麒任务/商城/背包事件绑定已移除（功能迁移到系统面板）

    // === 聊天消息容器中的按钮绑定 ===
    // 聊天消息在#chat-messages中，不在#phone-app-body中，需要单独绑定
    var $chat = $("#chat-messages");
    if ($chat.length > 0) {
      // 聊天消息 - AI描述生图按钮
      $chat
        .find(".chat-gen-desc-img-btn")
        .off("click")
        .on("click", function (e) {
          e.stopPropagation();
          e.preventDefault();
          var desc = $(this).data("desc");
          var sender = $(this).data("sender");
          var chatId = $(this).data("chat-id");
          var msgTs = parseInt($(this).data("msg-ts")) || 0;
          if (!desc) return;
          var $btn = $(this);
          $btn
            .prop("disabled", true)
            .html('<i class="fas fa-spinner fa-spin"></i> 生成中...');
          var _chatImgCtxChat =
            typeof window.buildChatImageGenContext === "function"
              ? window.buildChatImageGenContext(desc, sender, chatId, "")
              : { description: desc, chatContext: "" };
          window
            .phoneGenerateImage("chat", _chatImgCtxChat)
            .then(function (r) {
              if (r && r.success) {
                try {
                  var ac = window.getPhoneMetaBig("chat_history", {});
                  var ch = ac[chatId] || [];
                  var found = false;
                  for (var ci = ch.length - 1; ci >= 0; ci--) {
                    if (ch[ci].imageDesc === desc && !ch[ci].imageId) {
                      if (
                        msgTs &&
                        ch[ci].time &&
                        Math.abs(ch[ci].time - msgTs) < 5000
                      ) {
                        ch[ci].isImage = true;
                        ch[ci].imageId = r.imageId || r.entryId;
                        found = true;
                        break;
                      } else if (!msgTs) {
                        ch[ci].isImage = true;
                        ch[ci].imageId = r.imageId || r.entryId;
                        found = true;
                        break;
                      }
                    }
                  }
                  if (!found) {
                    for (var ci2 = ch.length - 1; ci2 >= 0; ci2--) {
                      if (ch[ci2].imageDesc === desc && !ch[ci2].imageId) {
                        ch[ci2].isImage = true;
                        ch[ci2].imageId = r.imageId || r.entryId;
                        found = true;
                        break;
                      }
                    }
                  }
                  if (found) {
                    ac[chatId] = ch;
                    window.setPhoneMetaBig("chat_history", ac);
                  }
                } catch (e) {}
                if (window.currentChatContactId === chatId) {
                  window.renderChatMessages._isFirstRender = true;
                  window.renderChatMessages(
                    window.currentChatContactId,
                    window.currentChatIsGroup,
                  );
                }
                yqToast("success", "图片已生成");
              } else {
                $btn
                  .prop("disabled", false)
                  .html('<i class="fas fa-paint-brush"></i> 🎨 生成图片');
                yqToast("error", "生成失败: " + ((r && r.error) || ""));
              }
            })
            .catch(function (err) {
              $btn
                .prop("disabled", false)
                .html('<i class="fas fa-paint-brush"></i> 🎨 生成图片');
            });
        });

      // 聊天消息 - 待生成图片按钮
      $chat
        .find(".chat-gen-pending-img-btn")
        .off("click")
        .on("click", function (e) {
          e.stopPropagation();
          e.preventDefault();
          var imageId = $(this).data("image-id");
          var $btn = $(this);
          if (!imageId || !window.phoneImageStore) return;
          var entry = window.phoneImageStore.getEntry(imageId);
          if (!entry || !entry.tag) {
            yqToast("warning", "tag未就绪");
            return;
          }
          $btn
            .prop("disabled", true)
            .html('<i class="fas fa-spinner fa-spin"></i> 生成中...');
          window
            .phoneRenderImage(entry.tag, {
              entryId: imageId,
              source: "chat",
              size: entry.size,
            })
            .then(function (r) {
              if (r && r.success) {
                yqToast("success", "图片已生成");
                if (window.currentChatContactId) {
                  window.renderChatMessages._isFirstRender = true;
                  window.renderChatMessages(
                    window.currentChatContactId,
                    window.currentChatIsGroup,
                  );
                }
              } else {
                $btn
                  .prop("disabled", false)
                  .html('<i class="fas fa-paint-brush"></i> 🎨 生成图片');
                yqToast("error", "生成失败: " + ((r && r.error) || ""));
              }
            })
            .catch(function () {
              $btn
                .prop("disabled", false)
                .html('<i class="fas fa-paint-brush"></i> 🎨 生成图片');
            });
        });

      // 聊天消息 - 重Roll按钮
      $chat
        .find(".chat-reroll-btn")
        .off("click")
        .on("click", function (e) {
          e.stopPropagation();
          e.preventDefault();
          var imageId = $(this).data("image-id");
          if (!imageId) return;
          var $btn = $(this);
          $btn.prop("disabled", true).text("⏳");
          yqToast("info", "正在重Roll...", "", { timeOut: 1500 });
          window
            .phoneRerollImage(imageId)
            .then(function (r) {
              $btn.prop("disabled", false).text("🔄");
              if (r && r.success) {
                if (window.currentChatContactId) {
                  window.renderChatMessages._isFirstRender = true;
                  window.renderChatMessages(
                    window.currentChatContactId,
                    window.currentChatIsGroup,
                  );
                }
                yqToast("success", "重Roll完成");
              } else {
                yqToast("error", "重Roll失败: " + ((r && r.error) || ""));
              }
            })
            .catch(function () {
              $btn.prop("disabled", false).text("🔄");
            });
        });
    }
  }, 0);
}

function openAppPanel(appName, isRestoringFromClose = false) {
  // 触发论坛/直播摘要生成（如果从论坛/直播切到其他App）
  if (typeof triggerForumSummaryOnLeave === "function") {
    triggerForumSummaryOnLeave();
  }
  if (typeof triggerLiveSummaryOnLeave === "function") {
    triggerLiveSummaryOnLeave();
  }

  // 检查数据
  if (!currentPhoneData) {
    const loaded = loadInitialMvuData();

    if (!loaded) {
      yqToast("warning", "未找到数据\n请先初始化MVU变量或发送一条消息");
      return;
    }
  }

  // 清空导航栈，因为这是一个新的应用
  navigationStack = [];

  currentPanel = appName;
  window.currentPanel = currentPanel;
  let title = "";
  let content = "";

  //  添加异常处理，避免生成函数出错导致整个面板空白
  try {
    switch (appName) {
      case "messages":
        title = "聊天";
        content = generateMessagesPanel(currentPhoneData);
        break;
      case "surveillance":
        title = "📹 监控";
        fetchLatestMvuData(true);
        content = generateSurveillancePanel(currentPhoneData);
        break;
      case "forum":
        title = "🌐 暗网论坛";
        content = generateForumPanel();
        break;
      case "world-events":
        title = "⚡ 世界动态";
        fetchLatestMvuData(true);
        content = generateWorldEventsPanel();
        break;
      case "wallpaper":
        title = "🎨 壁纸";
        loadedCategories.clear();
        content = generateSettingsPanel(currentPhoneData);
        break;
      case "character":
        title = "🎭 形象";
        content = generateCharacterAppPanel();
        break;
      case "ai-awareness":
        title = "📡 AI感知";
        content = generateAIAwarenessPanel();
        break;
      case "settings":
        title = "⚙️ 设置";
        content =
          typeof generateSizeSettingsPanel === "function"
            ? generateSizeSettingsPanel()
            : generateSettingsPanel(currentPhoneData);
        break;
      case "gallery":
        title = "📸 相册";
        content = generateGalleryPanel();
        break;
      case "live":
        title = "📺 直播";
        // 停止之前的自动生成
        if (typeof stopLiveAutoGeneration === "function")
          stopLiveAutoGeneration();
        // 清除直播未读红点
        if (window.npcMsgGen) window.npcMsgGen.clearLiveUnread();
        content = generateLiveListPanel();
        break;
      case "yinqi-task":
      case "yinqi-shop":
      case "yinqi-inventory":
        title = "已迁移";
        content =
          '<div class="empty-message">此功能已迁移到消息底部的银麒系统面板</div>';
        break;
      default:
        title = "未知应用";
        content = '<div class="empty-message">应用不存在</div>';
        break;
    }
  } catch (error) {
    //  捕获异常，显示错误信息而不是空白
    title = title || `⚠ ${appName}`;
    // 转义避免标题/错误文本里的 <、&、" 破坏 HTML/属性
    var _escHtml = function (s) {
      return String(s || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    };
    // 写入全局快照供点击按钮时读取，避免拼接进 onclick 属性
    try {
      window.__yqLastPanelError = {
        appName: String(appName || ""),
        message: String((error && error.message) || "未知错误"),
        stack: String((error && error.stack) || ""),
      };
    } catch (_ignore) {}
    content =
      '<div class="empty-message">' +
      '<i class="fas fa-exclamation-triangle" style="font-size: 48px; margin-bottom: 16px; opacity: 0.3; color: #ef4444;"></i>' +
      '<div style="color: #ef4444; font-weight: 600;">加载面板时出错</div>' +
      '<div style="font-size: 12px; color: #9ca3af; margin-top: 10px;">' +
      _escHtml(error && error.message ? error.message : "未知错误") +
      "</div>" +
