        _yqFlushBeforeReRenderSizeSettings();
        try {
          $("#phone-app-body").html(generateSizeSettingsPanel());
          bindPanelButtons();
        } catch (_e6) {}
      });

      // 监控API事件绑定已移除（迁移到各App独立设置面板）

      // 聊天API事件绑定已移除（迁移到各App独立设置面板）

      // 重置所有手机数据按钮
      $appBody.on("click.resetdata", "#phone-reset-all-data-btn", function (e) {
