function closeAppPanel() {
  // 先保存当前直播间ID（stopLiveAutoGeneration会清除它）
  var _savedLiveRoomId =
    typeof _liveCurrentRoomId !== "undefined" ? _liveCurrentRoomId : null;
  // 停止直播自动生成（如果正在直播间内）
  if (typeof stopLiveAutoGeneration === "function") stopLiveAutoGeneration();
  // 触发直播摘要生成（使用保存的roomId）
  if (typeof triggerLiveSummaryOnLeave === "function") {
    triggerLiveSummaryOnLeave(_savedLiveRoomId);
  }

  // 检查是否有导航历史
  if (navigationStack.length > 0) {
    const previousPage = navigationStack.pop();

    //  如果从好友详情页返回到好友列表，保留 lastViewedFriend 以便下次恢复
    const isReturningToFriendsList =
      previousPage.title && previousPage.title.includes("好友列表");
    if (isReturningToFriendsList) {
      // 保留 lastViewedFriend 不清除
    }

    // 恢复上一级页面
    $("#phone-app-title").text(previousPage.title);

    // 如果当前在论坛面板且从帖子详情返回，重新渲染论坛面板（因为回帖可能导致帖子迁移）
    // 同时触发论坛摘要生成
    if (typeof triggerForumSummaryOnLeave === "function") {
      triggerForumSummaryOnLeave();
    }
    if (
      currentPanel === "forum" &&
      previousPage.title &&
      previousPage.title.indexOf("论坛") !== -1
    ) {
      $("#phone-app-body").html(generateForumPanel());
      bindPanelButtons();
    } else if (
      currentPanel === "gallery" &&
      previousPage.title &&
      previousPage.title.indexOf("生图设置") !== -1
    ) {
      // 从API设置返回相册设置时，重新生成面板确保显示最新保存的设置
      $("#phone-app-body").html(generateGallerySettingsPanel());
    } else if (
      currentPanel === "gallery" &&
      previousPage.title &&
      (previousPage.title.indexOf("相册") !== -1 ||
        previousPage.title.indexOf("📸") !== -1)
    ) {
      // 从设置返回相册时，重新生成面板确保显示最新图片
      $("#phone-app-body").html(generateGalleryPanel());
    } else if (
      currentPanel === "surveillance" &&
      previousPage.title &&
      previousPage.title.indexOf("监控") !== -1
    ) {
      // 从详情返回监控概览时，重新读取MVU实时数据刷新面板
      fetchLatestMvuData(true);
      $("#phone-app-body").html(generateSurveillancePanel(currentPhoneData));
    } else {
      $("#phone-app-body").html(previousPage.content);
    }

    // 清理可能残留的API设置事件
    $("#phone-app-body").off("click.apich change.apich");

    /* 恢复深色/浅色背景 - 检查返回目标页面是否为API设置（浅色主题） */
    var isReturningToAPISettings =
      previousPage.title && previousPage.title.indexOf("API设置") !== -1;
    if (isReturningToAPISettings) {
      $("#phone-app-body").css({ background: "", color: "", padding: "" });
    } else if (currentPanel === "live") {
      $("#phone-app-body").css({
        background: "#0f0a1e",
        color: "#e2e8f0",
        padding: "0",
      });
    } else if (currentPanel === "gallery") {
      $("#phone-app-body").css({
        background: "#0f172a",
        color: "#e2e8f0",
        padding: "12px",
      });
    } else {
      $("#phone-app-body").css({ background: "", color: "", padding: "" });
    }

    // 恢复页面后重新绑定按钮事件
    bindPanelButtons();

    // 如果恢复到消息面板，需要重新绑定消息面板事件
    if (currentPanel === "messages") {
      bindMessagePanelEvents();
    }

    //  恢复滚动位置（如果有保存）- 多种方式尝试，确保iframe兼容
    if (previousPage.scrollPosition !== undefined || lastViewedFriend) {
      setTimeout(() => {
        let appBodyElement = document.getElementById("phone-app-body");

        // 如果原生方式找不到，尝试使用 jQuery
        if (!appBodyElement) {
          const $appBody = $("#phone-app-body");
          if ($appBody.length > 0) {
            appBodyElement = $appBody[0];
          }
        }

        if (appBodyElement) {
          //  优先使用元素定位恢复位置
          if (lastViewedFriend) {
            const $friendItem = $(
              `.friend-item[data-friend-name="${lastViewedFriend}"]`,
            );
            if ($friendItem.length > 0) {
              const targetPosition =
                $friendItem.position().top + appBodyElement.scrollTop;
              appBodyElement.scrollTop = targetPosition;
              return;
            }
          }

          // 备选：使用保存的滚动位置
          if (previousPage.scrollPosition > 0) {
            appBodyElement.scrollTop = previousPage.scrollPosition;
            const actualPosition = appBodyElement.scrollTop;

            // 如果实际位置和目标位置不一致，可能是DOM还没完全渲染，再试一次
            if (actualPosition < previousPage.scrollPosition - 10) {
              setTimeout(() => {
                appBodyElement.scrollTop = previousPage.scrollPosition;
              }, 150);
            }
          }
        }
      }, 150); // 增加延迟确保DOM已完全渲染
    }
  } else {
    // 没有历史记录，关闭整个面板
    $("#phone-detail-panel").removeClass("active");
    $("#phone-forum-floating-create-btn").remove();
    // 重置app-body背景（直播/相册可能改过）
    $("#phone-app-body").css({ background: "", color: "", padding: "" });
    // 恢复标题栏和状态栏默认样式（直播可能改过）
    $(".app-header").css({ background: "", borderBottom: "" });
    $(".app-header .app-title").css("color", "");
    $(".app-header .back-button").css("color", "");
    $(".mobile-status-bar").css({ background: "" });
    $(".mobile-status-bar .status-left .time").css("color", "");
    $(".mobile-status-bar .battery").css("color", "");
    $(".mobile-status-bar .pin-btn").css("color", "");
    currentPanel = null;
    window.currentPanel = null;

    //  不清除 lastViewedFriend 和 friendsListScrollPosition，以便下次打开时恢复
    // 只有当用户完全关闭手机界面时才清除

    // 清除保存的面板状态
    try {
      localStorage.setItem("mobile-last-panel", "");
    } catch (e) {}
  }
}

