// ==================== 纳米监控扩写与生图 ====================
function _hasSurveillanceCapability() {
  try {
    fetchLatestMvuData(true);
    var d = currentPhoneData || {};
    // 旧版：别墅摄像头 / 手机后门
    var cams = _.get(d, "user.监控设施.已安装摄像头", {});
    var backdoors = _.get(d, "user.监控设施.已植入后门", {});
    if (
      Object.keys(cams || {}).length > 0 ||
      Object.keys(backdoors || {}).length > 0
    ) {
      return true;
    }
    // 纳米监控：背包植入后写入 phoneMeta，概要在 银麒系统.监控.*
    var targets = getPhoneMeta("yinqi_surveillance_targets", []);
    if (Array.isArray(targets) && targets.length > 0) return true;
    var surv = _.get(d, "银麒系统.监控", {});
    if (surv && typeof surv === "object" && Object.keys(surv).length > 0) {
      return true;
    }
    return false;
  } catch (_e) {
    return false;
  }
}
window.hasSurveillanceCapability = _hasSurveillanceCapability;
var _survExpandInflight = {};
var _survImageInflight = {};

async function _expandSurveillanceDetail(name, silent) {
  try {
    var k = String(name || "");
    if (_survExpandInflight[k]) return;
    _survExpandInflight[k] = true;
    if (!_hasSurveillanceCapability()) {
      if (!silent) yqToast("info", "未检测到监控设施，已跳过扩写");
      return;
    }
    var api = window.phoneAPI && window.phoneAPI.surveillance;
    if (!api) api = window.phoneAPI && window.phoneAPI.chat;
    if (!api || !api.isAvailable()) {
      if (!silent) yqToast("warning", "请先配置监控API或聊天API");
      return;
    }
    fetchLatestMvuData(true);
    var d = currentPhoneData || {};
    var summary = _.get(d, "银麒系统.监控." + name, "");
    if (!summary || summary === "刚被植入纳米监控，等待数据同步...") {
      if (!silent) yqToast("info", "等待主AI更新监控动态后再扩写");
      return;
    }
    var curTime =
      _.get(d, "银麒系统.世界.日期", "") +
      " " +
      _.get(d, "银麒系统.世界.时刻", "");
    var prompt =
      "你是纳米监控画面描述器。根据以下一句话摘要，扩写为50-150字的监控画面描述。\n\n";
    prompt += "被监控角色：" + name + "\n";
    prompt += "当前时间：" + curTime + "\n";
    prompt += "一句话摘要：" + summary + "\n\n";
    prompt +=
      "要求：\n- 有画面感，像真实监控记录\n- 客观简洁，第三人称\n- 描写角色的着装、动作、表情、环境细节\n- 如果涉及其他角色，描写互动细节\n- 不要添加时间标记，直接描述画面\n- 不要使用markdown格式\n- 50-150字";
    var result = await api.callChatAPI("", prompt, {
      skipCustomPrompt: true,
      triggerSource: "surveillance:expand",
    });
    if (result) {
      // [V10.6 BUG FIX] 只剥代码块围栏，保留内容
      //   旧逻辑会把 AI 整段包在 ``` 里的扩写内容全删（chat-reply #5 同源 BUG）
      result = result
        .replace(/```(?:json|javascript|js|html|md)?\s*/gi, "")
        .replace(/^["']|["']$/g, "")
        .trim();
      // 存储扩写结果（追加到历史，保留最近5条）
      var camHist = getPhoneMetaBig("cam_history", {});
      var _survRecords = camHist["surv_" + name] || [];
      _survRecords.unshift({
        content: result,
        time: curTime,
        timestamp: Date.now(),
        _sourceSummary: summary,
      });
      if (_survRecords.length > 5) _survRecords = _survRecords.slice(0, 5);
      camHist["surv_" + name] = _survRecords;
      camHist[name] = _survRecords;
      setPhoneMetaBig("cam_history", camHist);
      if (!silent) yqToast("success", name + " 画面已扩写");

      // [修复] 扩写完成后，如果自动生图已启用，自动触发生图
      try {
        var imgSettings =
          typeof getImageGenSettings === "function"
            ? getImageGenSettings()
            : {};
        if (
          typeof isImageSceneAutoEnabled === "function"
            ? isImageSceneAutoEnabled("autoSurveillance", imgSettings)
            : imgSettings.enabled && imgSettings.autoSurveillance === true
        ) {
          console.log("[纳米监控] 扩写完成，触发自动生图: " + name);
          // 延迟100ms确保扩写内容已保存
          setTimeout(function () {
            _generateSurveillanceImage(name, true).catch(function (e) {
              console.warn("[纳米监控] 扩写后自动生图失败:", e);
            });
          }, 100);
        }
      } catch (autoImgErr) {
        console.warn("[纳米监控] 扩写后自动生图检查失败:", autoImgErr);
      }

      // 刷新面板
      if (currentPanel === "surveillance") {
        fetchLatestMvuData(true);
        $("#phone-app-body").html(generateSurveillancePanel(currentPhoneData));
        bindPanelButtons();
      }
    }
  } catch (e) {
    console.warn("[纳米监控] 扩写失败:", e);
    if (!silent) yqToast("error", "扩写失败: " + (e.message || ""));
  } finally {
    delete _survExpandInflight[String(name || "")];
  }
}

async function _generateSurveillanceImage(name, silent) {
  try {
    var k2 = String(name || "");
    if (_survImageInflight[k2]) return;
    _survImageInflight[k2] = true;
    if (!_hasSurveillanceCapability()) {
      if (!silent) yqToast("info", "未检测到监控设施，已跳过生图");
      return;
    }
    var imgSettings =
      typeof getImageGenSettings === "function" ? getImageGenSettings() : {};
    if (!imgSettings.enabled) {
      if (!silent) yqToast("warning", "请先在设置中启用生图功能");
      return;
    }
    // 获取扩写内容作为生图描述
    var camHist = getPhoneMetaBig("cam_history", {});
    var records = camHist["surv_" + name] || camHist[name] || [];
    var sceneText = records.length > 0 ? records[0].content || "" : "";
    if (!sceneText) {
      // 没有扩写内容，用MVU摘要
      fetchLatestMvuData(true);
      var d = currentPhoneData || {};
      sceneText = _.get(d, "银麒系统.监控." + name, "");
    }
    if (!sceneText) {
      if (!silent) yqToast("info", "没有可用的画面描述，请先扩写");
      return;
    }
    var ctx;
    // [V10.6] 优先用统一 ctx 构造函数（修复 BUG 1-6）
    if (typeof window.buildSurveillanceImageGenContext === "function") {
      ctx = window.buildSurveillanceImageGenContext(name, sceneText, {
        primaryType: "character",
        auto: !!silent,
      });
    } else {
      // fallback（不应发生，理论上 _npc_generator.js 已加载并 export）
      ctx = {
        hostName: name,
        sceneText: sceneText,
        _gender: "",
        _auto: !!silent,
      };
      // 推断性别（旧逻辑兜底）
      var d2 = currentPhoneData || {};
      var femChars = _.get(d2, "女性角色", {});
      if (femChars[name] || name === "林知意") ctx._gender = "female";
      else ctx._gender = "male";
    }
    var genFn = window.phoneGenerateImage;
    if (!genFn) {
      if (!silent) yqToast("warning", "生图功能未就绪");
      return;
    }
    var result = await genFn("surveillance", ctx);
    if (result && result.success) {
      var camImages = getPhoneMetaBig("cam_images", {});
      var _oldImageId = camImages["surv_" + name] || camImages[name] || "";
      if (_oldImageId && window.phoneImageStore) {
        window.phoneImageStore.remove(_oldImageId);
      }
      camImages["surv_" + name] = result.imageId || result.entryId;
      camImages[name] = result.imageId || result.entryId;
      setPhoneMetaBig("cam_images", camImages);
      if (!silent) yqToast("success", name + " 监控图片已生成");
      if (currentPanel === "surveillance") {
        fetchLatestMvuData(true);
        $("#phone-app-body").html(generateSurveillancePanel(currentPhoneData));
        bindPanelButtons();
      }
    }
  } catch (e) {
    console.warn("[纳米监控] 生图失败:", e);
    if (!silent) yqToast("error", "生图失败: " + (e.message || ""));
  } finally {
    delete _survImageInflight[String(name || "")];
  }
}

// ==================== 消息文本清理工具（去除EJS/变量/指令标签） ====================

/** SillyTavern 楼层 mes 可能是 string 或多模态数组，统一成纯文本再注入手机 API */
function _coerceStMessageMesToString(mes) {
  if (mes == null) return "";
  if (typeof mes === "string") return mes;
  if (Array.isArray(mes)) {
    var parts = [];
    for (var i = 0; i < mes.length; i++) {
      var p = mes[i];
      if (!p) continue;
      if (typeof p === "string") parts.push(p);
      else if (p.type === "text" && p.text != null) parts.push(String(p.text));
      else if (p.type === "image_url" || p.type === "input_image")
        parts.push("[图片]");
    }
    return parts.join("\n");
  }
  if (typeof mes === "object") {
    try {
      return JSON.stringify(mes);
    } catch (e) {
      return "";
    }
  }
  return String(mes);
}

/**
 * cleanMessageText - 清理消息文本中的EJS模板标签、变量更新块、指令标签等非故事内容
 * 用于手机内置API读取聊天记录时，防止EJS脚本和元数据污染AI上下文
 * @param {string} text - 原始消息文本
 * @returns {string} 清理后的纯故事文本
 */
function cleanMessageText(text) {
  if (typeof text !== "string") text = _coerceStMessageMesToString(text);
  if (!text) return "";
  var cleaned = text;
  // 0. [V10.6] 移除推理标签：覆盖 think/thinking/thought/reasoning/analysis/reflection/deliberation 等多种变体
  //    优先用增强版 stripThinkingTags（覆盖大小写、带属性、未闭合、HTML 注释）
  if (typeof stripThinkingTags === "function") {
    cleaned = stripThinkingTags(cleaned);
  } else {
    cleaned = cleaned.replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi, "");
  }
  // 1. 移除EJS标签: <% ... %>, <%= ... %>, <%- ... %>
  cleaned = cleaned.replace(/<%[\s\S]*?%>/g, "");
  // 2. 移除变量更新块: <UpdateVariable>...</UpdateVariable>（含不闭合标签）
  cleaned = cleaned.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, "");
  cleaned = cleaned.replace(/<UpdateVariable>[\s\S]*/g, "");
  cleaned = cleaned.replace(/<\/UpdateVariable>/g, "");
  // 3. 移除AI指令标签: <ai_instruction>...</ai_instruction>（含不闭合标签）
  cleaned = cleaned.replace(/<ai_instruction>[\s\S]*?<\/ai_instruction>/g, "");
  cleaned = cleaned.replace(/<ai_instruction>[\s\S]*/g, "");
  cleaned = cleaned.replace(/<\/ai_instruction>/g, "");
  // 4. 移除状态栏占位符: <StatusPlaceHolderImpl/> 及其变体
  cleaned = cleaned.replace(/<StatusPlaceHolderImpl\s*\/?>/g, "");
  // 5. 移除文生图标签: <image>...</image>（含不闭合标签）
  cleaned = cleaned.replace(/<image>[\s\S]*?<\/image>/g, "");
  cleaned = cleaned.replace(/<image>[\s\S]*/g, "");
  // 6. 移除其他常见泄露标签（不闭合的XML标签残留）
  cleaned = cleaned.replace(/<huatu>[\s\S]*?<\/huatu>/g, "");
  cleaned = cleaned.replace(/<huatu>[\s\S]*/g, "");
  cleaned = cleaned.replace(/<imgthink>[\s\S]*?<\/imgthink>/g, "");
  cleaned = cleaned.replace(/<imgthink>[\s\S]*/g, "");
  cleaned = cleaned.replace(/<WorldEvent>[\s\S]*?<\/WorldEvent>/g, "");
  cleaned = cleaned.replace(/<WorldEvent>[\s\S]*/g, "");
  cleaned = cleaned.replace(
    /<SurveillanceInstallEvent>[\s\S]*?<\/SurveillanceInstallEvent>/g,
    "",
  );
  cleaned = cleaned.replace(/<SurveillanceInstallEvent>[\s\S]*/g, "");
  // 7. 移除手机消息格式标签（模板提示词残留）
  cleaned = cleaned.replace(
    /\[对方消息\|角色名字\|号码\|消息类型\|消息内容\]/g,
    "",
  );
  cleaned = cleaned.replace(/\[我方消息\|我\|号码\|消息类型\|消息内容\]/g, "");
  cleaned = cleaned.replace(
    /\[群聊消息\|群号\|发送者名字\|消息类型\|消息内容\]/g,
    "",
  );
  cleaned = cleaned.replace(/\[群聊\|群名\|群号\|成员列表\]/g, "");
  cleaned = cleaned.replace(/\[创建群聊\|群号\|群名\|成员列表\]/g, "");
  // 8. 移除响应格式要求模板残留
  cleaned = cleaned.replace(
    /群聊消息响应格式要求[\s\S]*?可以有多个角色回复，每个角色一条消息/g,
    "",
  );
  cleaned = cleaned.replace(
    /私聊消息响应格式要求[\s\S]*?可以回复多条消息/g,
    "",
  );
  // 9. 清理多余空行（连续3个以上换行合并为2个）
  cleaned = cleaned.replace(/\n{3,}/g, "\n\n");
  return cleaned.trim();
}

/**
 * [V10.6] 剥离 LLM 各种推理/思考标签
 * 覆盖：<think>、<thinking>、<thought>、<reasoning>、<analysis>、<reflection>、<deliberation>
 * 大小写不敏感、支持带属性、支持未闭合（截断时）
 */
function stripThinkingTags(text) {
  if (!text) return "";
  var s = String(text);
  s = s.replace(
    /<(think|thinking|thought|reasoning|analysis|reflection|deliberation)\b[^>]*>[\s\S]*?<\/\1\s*>/gi,
    "",
  );
  s = s.replace(
    /<(think|thinking|thought|reasoning|analysis|reflection|deliberation)\b[^>]*>[\s\S]*$/gi,
    "",
  );
  s = s.replace(
    /<!--\s*(?:think|thinking|reasoning|analysis)\s*:[\s\S]*?-->/gi,
    "",
  );
  return s;
}

/**
 * [V10.6] 鲁棒 JSON 提取：用配对栈找第一个完整 {...}
 * 跳过字符串内 / 注释里的 {}，避免 thinking 块内的 {{user}} 干扰
 */
function extractJsonRobust(text) {
  if (!text) return null;
  var s = String(text);
  var depth = 0;
  var start = -1;
  var inStr = false;
  var strCh = "";
  var escaped = false;
  for (var i = 0; i < s.length; i++) {
    var ch = s[i];
    if (inStr) {
      if (escaped) escaped = false;
      else if (ch === "\\") escaped = true;
      else if (ch === strCh) inStr = false;
      continue;
    }
    if (ch === '"' || ch === "'") {
      inStr = true;
      strCh = ch;
      continue;
    }
    if (ch === "{") {
      if (depth === 0) start = i;
      depth++;
    } else if (ch === "}") {
      if (depth > 0) {
        depth--;
        if (depth === 0 && start >= 0) return s.substring(start, i + 1);
      }
    }
  }
  var firstBrace = s.indexOf("{");
  return firstBrace >= 0 ? s.substring(firstBrace) : null;
}

/**
 * stripJsonCodeBlock - 清理LLM返回中的markdown代码块包裹
 * LLM经常返回 ```json ... ``` 包裹的JSON，导致正则提取失败
 * @param {string} text - LLM原始返回文本
 * @returns {string} 去除代码块包裹后的文本
 */
function stripJsonCodeBlock(text) {
  if (!text) return "";
  // [V10.6] 用增强版 stripThinkingTags，覆盖更多变体（thought/reasoning/analysis 等）
  var cleaned = stripThinkingTags(text);
  cleaned = cleaned.replace(/```(?:json|JSON)?\s*/gi, "").trim();
  // [V10.6] 兜底：如果剥离 thinking 后内容为空（AI 把 JSON 也写在 thinking 里）
  //   或剥离后没有 { / [，则返回原始文本，让调用方的正则能从原始 raw 中匹配
  if (!cleaned || (cleaned.indexOf("{") < 0 && cleaned.indexOf("[") < 0)) {
    return text.replace(/```(?:json|JSON)?\s*/gi, "").trim();
  }
  return cleaned;
}


// ======== 银麒赎世_角色卡/当前版本/作品展开/phone/_api_channels.js ========
// ==================== 公共上下文函数（4个API通道共享） ====================

// 获取最近聊天上下文
function getSharedChatContext(floorCount) {
  var count = floorCount || 10;
  var context = [];
  try {
    var tw = window.parent || window;
    if (tw.SillyTavern && tw.SillyTavern.getContext) {
      var sc = tw.SillyTavern.getContext();
      var chat = sc.chat || [];
      for (var i = Math.max(0, chat.length - count); i < chat.length; i++) {
        var msg = chat[i];
        if (msg && msg.mes) {
          var mesLine = cleanMessageText(
            _coerceStMessageMesToString(msg.mes),
          ).substring(0, 2000);
          if (!mesLine.trim()) continue;
          context.push({
            role: msg.is_user ? "user" : "assistant",
            // 不传 name：部分 Gemini 兼容代理对 message.name 转译会生成异常 parts，触发 400
            content: mesLine,
          });
        }
      }
    }
  } catch (e) {}
  // 注意：手机消息摘要已通过 injectNpcSummaryToContext() 注入到主AI的 extensionPrompt 中，
  // 此处不再重复注入，避免手机AI上下文中出现两份相同的摘要浪费token。
  return context;
}

// ==================== 银麒赎世世界观（动态版，从世界书EJS渲染+MVU变量组合） ====================
async function getBuiltinWorldContext() {
  var w = "";
  var d = currentPhoneData || {};
  var sceneChars = _.get(d, "当前场景角色", {});
  var sceneDetails = _.get(d, "场景角色详情", {});

  // --- 辅助：读取世界书条目并EJS渲染 ---
  async function renderEntry(comment) {
    try {
      var tw = window.parent || window;
      var ctx =
        tw.SillyTavern && tw.SillyTavern.getContext
          ? tw.SillyTavern.getContext()
          : null;
      if (!ctx) return null;
      // 从角色世界书中查找条目
      var entries = [];
      if (ctx.characters && ctx.characters[ctx.characterId]) {
        var charData = ctx.characters[ctx.characterId];
        if (
          charData.data &&
          charData.data.character_book &&
          charData.data.character_book.entries
        ) {
          entries = charData.data.character_book.entries;
        }
      }
      // 也尝试从chat_metadata的world_info读取
      if (
        entries.length === 0 &&
        ctx.chat_metadata &&
        ctx.chat_metadata.world_info
      ) {
        var wi = ctx.chat_metadata.world_info;
        if (wi.entries) entries = Object.values(wi.entries);
      }
      // 查找匹配的条目
      for (var i = 0; i < entries.length; i++) {
        var e = entries[i];
        if (
          e &&
          (e.comment === comment ||
            (e.comment && e.comment.indexOf(comment) !== -1))
        ) {
          if (!e.content) return null;
          // 尝试EJS渲染
          if (
            e.content.indexOf("<%") !== -1 &&
            tw.EjsTemplate &&
            typeof tw.EjsTemplate.evalTemplate === "function"
          ) {
            try {
              var rendered = await tw.EjsTemplate.evalTemplate(e.content);
              return rendered || null;
            } catch (ejsErr) {
              console.warn("[世界观注入] EJS渲染失败:", comment, ejsErr);
              return e.content; // 回退到原始内容
            }
          }
          return e.content;
        }
      }
    } catch (err) {
      console.warn("[世界观注入] 读取条目失败:", comment, err);
    }
    return null;
  }

  // --- 辅助：格式化MVU变量 ---
  function fmtOutfit(outfit, keys) {
    if (!outfit || typeof outfit !== "object") return "";
    var parts = [];
    for (var ki = 0; ki < keys.length; ki++) {
      var v = _.get(outfit, keys[ki], "");
      if (v) parts.push(keys[ki] + ":" + v);
    }
    return parts.length > 0 ? parts.join(" | ") : "";
  }

  // ═══════════════════════════════════════
  // 1. 世界状态
  // ═══════════════════════════════════════
  w += "═══ 世界状态 ═══\n";
  var bgContent = await renderEntry("背景设定");
  if (bgContent) w += bgContent + "\n";
  var doomContent = await renderEntry("[EJS]末日世界观");
  if (doomContent) w += doomContent + "\n";

  // MVU世界变量
  var world = _.get(d, "银麒系统.世界", {});
  var acc = _.get(d, "银麒系统.账户", {});
  w +=
    "【当前状态】日期:" +
    _.get(world, "日期", "---") +
    " 时刻:" +
    _.get(world, "时刻", "---") +
    " 地点:" +
    _.get(world, "地点", "---") +
    "\n";
  w +=
    "末日倒计时:" +
    _.get(world, "末日倒计时", 29) +
    "天 末日已爆发:" +
    _.get(world, "末日已爆发", false) +
    "\n";
  w +=
    "系统等级:LV" +
    _.get(acc, "系统等级", 1) +
    " 银麒点:" +
    _.get(acc, "银麒点", 0) +
    " 经验:" +
    _.get(acc, "当前经验", 0) +
    "/" +
    _.get(acc, "下一级所需", 10) +
    "\n";

  // 任务状态
  var task = _.get(d, "任务.当前任务", {});
  if (_.get(task, "状态", "无任务") !== "无任务") {
    w +=
      "当前任务:" +
      _.get(task, "等级", "") +
      " " +
      _.get(task, "描述", "").substring(0, 50) +
      " 状态:" +
      _.get(task, "状态", "") +
      " 奖励:" +
      _.get(task, "最终奖励", 0) +
      "点\n";
  }
  w += "\n";

  // ═══════════════════════════════════════
  // 2. 系统规则
  // ═══════════════════════════════════════
  var rulesContent = await renderEntry("银麒系统_交互规则");
  if (rulesContent) {
    w += "═══ 系统规则 ═══\n";
    w += rulesContent + "\n\n";
  }

  // ═══════════════════════════════════════
  // 3. 主角状态
  // ═══════════════════════════════════════
  w += "═══ 主角状态 ═══\n";
  var userContent = await renderEntry("玩家角色_{{user}}");
  if (userContent) w += userContent + "\n";
  var user = _.get(d, "user", {});
  w += "【实时】想法:" + _.get(user, "当前想法", "---") + "\n";
  w +=
    "着装:" +
    fmtOutfit(_.get(user, "着装", {}), ["上装", "下装", "内裤", "鞋子"]) +
    "\n";
  w += "鸡巴:" + _.get(user, "鸡巴状态", "---") + "\n\n";

  // ═══════════════════════════════════════
  // 4. 女主状态
