/** 将 message.content 规范为纯文本，避免非字符串/多模态残留传入 chat/completions 导致上游 400 */
function _phoneCoerceApiMessageContent(raw) {
  if (raw == null) return "";
  if (typeof raw === "string") return raw;
  if (Array.isArray(raw)) {
    var chunks = [];
    for (var i = 0; i < raw.length; i++) {
      var p = raw[i];
      if (!p) continue;
      if (typeof p === "string") chunks.push(p);
      else if (p.type === "text" && p.text != null) chunks.push(String(p.text));
      else if (p.type === "image_url" || p.type === "input_image")
        chunks.push("[图片]");
    }
    return chunks.join("\n");
  }
  if (typeof raw === "object") {
    try {
      return JSON.stringify(raw);
    } catch (e) {
      return "";
    }
  }
  return String(raw);
}

/** 规范化即将发往 OpenAI 兼容接口的 messages */
// [V6.5.12 qtwx-mcp-3 综合·参考 mcp-6 P2-13] 硬截长度可通过 opts.maxMessageLen 覆盖
//   默认 120000 字符，对齐绝大多数模型的上下文上限（约 150k tokens）
//   某些超长上下文模型（Claude/Gemini 等）可通过调用点传 opts 覆盖
function _phoneSanitizeChatMessages(messages, opts) {
  if (!Array.isArray(messages)) return [];
  var _maxLen = 120000;
  try {
    if (
      opts &&
      typeof opts.maxMessageLen === "number" &&
      opts.maxMessageLen > 0
    ) {
      _maxLen = opts.maxMessageLen;
    }
  } catch (_e) {}
  var out = [];
  for (var i = 0; i < messages.length; i++) {
    var m = messages[i];
    if (!m || !m.role) continue;
    var text = _phoneCoerceApiMessageContent(m.content);
    text = String(text).trim();
    if (!text) continue;
    out.push({ role: m.role, content: text.substring(0, _maxLen) });
  }
  return out;
}

