  var limit = Math.max(1, Math.min(12, Number(maxConcurrent) || 2));
  if (!_phoneApiConcurrencyPools[key]) {
    _phoneApiConcurrencyPools[key] = { active: 0, queue: [] };
  }
  var pool = _phoneApiConcurrencyPools[key];

  return new Promise(function (resolve, reject) {
    var enqueueAt = Date.now();
    var task = function () {
      pool.active++;
      _phoneApiPoolStats.peakActive = Math.max(
        _phoneApiPoolStats.peakActive || 0,
        pool.active,
      );
      var waitMs = Math.max(0, Date.now() - enqueueAt);
      if (waitMs > 200 || pool.active > 1) {
        _phoneApiDiagPool("start", {
          channel: (meta && meta.channel) || "",
          poolKey: key.substring(0, 60),
          active: pool.active,
          queue: pool.queue.length,
          maxConcurrent: limit,
          waitMs: waitMs,
        });
      }
      var startAt = Date.now();
      Promise.resolve()
        .then(runner)
        .then(resolve, reject)
        .finally(function () {
          var costMs = Date.now() - startAt;
          pool.active = Math.max(0, pool.active - 1);
          if (costMs > 1500 || pool.queue.length > 0) {
