              channel: (meta && meta.channel) || "",
              poolKey: key.substring(0, 60),
              active: pool.active,
              queue: pool.queue.length,
              maxConcurrent: limit,
              costMs: costMs,
            });
          }
          if (pool.queue.length > 0 && pool.active < limit) {
            var next = pool.queue.shift();
            next();
          }
        });
    };

    if (pool.active < limit) task();
    else {
      pool.queue.push(task);
      _phoneApiPoolStats.peakQueue = Math.max(
        _phoneApiPoolStats.peakQueue || 0,
        pool.queue.length,
      );
