    if (!this.isAvailable()) throw new Error(this.channelKey + " API未配置");
    var url = _phoneBuildApiUrl(this.settings.apiUrl, "chat/completions");
    if (!url) throw new Error("请先填写API URL");
    var maxT =
      (options && options.maxTokens) ||
      this.settings.maxTokens ||
      yqGetPhoneApiDefaultMaxTokens(this.channelKey);
    var temp =
      options && options.temperature != null
        ? options.temperature
        : this.settings.temperature;
    var maxRetries = (options && options.maxRetries) || 3;
    var lastError = null;
    var timeoutMs = (options && options.timeout) || 60000; // 默认60秒超时
    var maxConcurrent =
      (options && options.maxConcurrent) || this.settings.maxConcurrent || 2;
    var poolKey = _phoneBuildApiPoolKey(this.settings);
    var requestId =
      (options && options.requestId) ||
      this.channelKey +
        "-" +
        Date.now() +
        "-" +
        Math.floor(Math.random() * 1000);
    var triggerSource = (options && options.triggerSource) || "unspecified";
    var reqStartedAt = Date.now();
    for (var attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        var payloadMessages = _phoneSanitizeChatMessages(messages);
        if (payloadMessages.length === 0)
          payloadMessages.push({
            role: "user",
            content: ".",
          });
        var settingsRef = this.settings;
        // [V13·2026-06-01] maxTokensRaw：调用侧（如摘要）指定跳过阶梯压缩，直接用 maxT。
        //   仍受 isTokenErr 降级保护：若模型报 token 超限，catch 里会降 maxT 后重试。
        var requestMaxTokens =
          options && options.maxTokensRaw
            ? maxT
            : yqReducePhoneApiMaxTokens(maxT);
        var resp = await _phoneWithApiPool(
          poolKey,
          maxConcurrent,
          function () {
            var controller = new AbortController();
            var timeoutId = setTimeout(function () {
              controller.abort();
            }, timeoutMs);
            return fetch(url, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: "Bearer " + settingsRef.apiKey,
              },
              body: JSON.stringify({
                model: settingsRef.model,
                messages: payloadMessages,
                max_tokens: requestMaxTokens,
                temperature: temp != null ? temp : 0.85,
              }),
              signal: controller.signal,
            }).finally(function () {
              clearTimeout(timeoutId);
            });
          },
          { channel: this.channelKey },
        );
        if (!resp.ok) {
          var errText = "";
          try {
            errText = await resp.text();
          } catch (e) {}
          throw new Error(
            "HTTP " +
              resp.status +
              (errText ? ": " + errText.substring(0, 200) : ""),
          );
        }
        var data = await resp.json();
        _phoneApiDiagRequest("ok", {
          requestId: requestId,
          channel: this.channelKey,
          triggerSource: triggerSource,
          attempt: attempt,
          maxRetries: maxRetries,
          elapsedMs: Date.now() - reqStartedAt,
        });
        var _msg =
          (data.choices && data.choices[0] && data.choices[0].message) || {};
        var _content = _msg.content || "";
        // [V13·2026-06-01] thinking 模型兜底：部分 reasoning 模型（含某些 flash）
        //   把输出全写进 reasoning 字段，content 为空。content 空时回退读 reasoning，
        //   调用侧的 JSON 解析器（_yqParseLlmJson）能从中提取 JSON。取不到也只是回到原 ""。
        //   [仅在调用侧显式 allowReasoningFallback 时生效] 避免聊天/论坛通道把思考过程当正文返回。
        if (
          options &&
          options.allowReasoningFallback &&
          (!_content || !String(_content).trim())
        ) {
          var _reasoning =
            _msg.reasoning_content ||
            _msg.reasoning ||
            _msg.thinking ||
            (_msg.thinking_blocks &&
              Array.isArray(_msg.thinking_blocks) &&
              _msg.thinking_blocks
                .map(function (b) {
                  return (b && (b.thinking || b.text)) || "";
                })
                .join("\n")) ||
            "";
          if (_reasoning && String(_reasoning).trim()) {
            try {
              console.warn(
                "[" +
                  this.channelKey +
                  "] content 为空，回退使用 reasoning 字段（thinking 模型）",
              );
            } catch (_eW) {}
            return String(_reasoning);
          }
        }
        return _content || "";
      } catch (err) {
        lastError = err;
        var em = (err && err.message) || "";
        var is429 = /429|rate\s*limit|rate_limit|capacity/i.test(em);
        var isTokenErr = yqIsPhoneApiTokenError(em);
        console.warn(
          "[" +
            this.channelKey +
            "] API调用失败(第" +
            attempt +
            "/" +
            maxRetries +
            "次):",
          err.message,
        );
        _phoneApiDiagRequest("retry", {
          requestId: requestId,
          channel: this.channelKey,
          triggerSource: triggerSource,
          attempt: attempt,
          maxRetries: maxRetries,
          is429: is429,
          isTokenErr: isTokenErr,
          err: em.substring(0, 200),
        });
        if (isTokenErr && attempt < maxRetries) {
          var reducedMaxT = yqReducePhoneApiMaxTokens(maxT);
          if (reducedMaxT < maxT) {
            maxT = reducedMaxT;
            try {
              console.warn(
                "[" +
                  this.channelKey +
                  "] token参数异常，降级max_tokens后重试:",
                maxT,
              );
            } catch (_tokWarn) {}
          }
        }
        if (attempt < maxRetries) {
          var delayMs = is429
            ? Math.min(30000, 1500 * Math.pow(2, attempt - 1))
            : Math.min(12000, 1000 * Math.pow(2, attempt - 1));
          var jitter = Math.floor(
            Math.random() * Math.max(300, Math.floor(delayMs * 0.3)),
          );
          delayMs += jitter;
          await new Promise(function (r) {
            setTimeout(r, delayMs);
          });
        }
      }
    }
    _phoneApiDiagRequest("fail", {
      requestId: requestId,
      channel: this.channelKey,
      triggerSource: triggerSource,
      maxRetries: maxRetries,
      elapsedMs: Date.now() - reqStartedAt,
      err: ((lastError && lastError.message) || "").substring(0, 300),
    });
    throw (
      lastError ||
      new Error(this.channelKey + " API调用失败（已重试" + maxRetries + "次）")
    );
  }

  // 高级API调用：自动注入上下文（世界书+MVU+聊天记录）
  // 可通过 options 精细控制注入范围，避免某些场景（如论坛路人视角）过度获取上下文
  async callChatAPI(systemPrompt, userMessage, options) {
    var messages = [];
    var includeMVU = !(options && options.includeMVU === false);
    var includeBuiltinWorld = !(
      options && options.includeBuiltinWorld === false
    );
    var includeChatContext = !(options && options.includeChatContext === false);
    // 1. 破限提示词
    var bp = this.settings.breakPrompt || this.getDefaultBreakPrompt();
    if (bp) messages.push({ role: "system", content: bp });
    // 2. 自定义提示词（聊天消息发送时跳过，避免干扰格式指令）
    if (!(options && options.skipCustomPrompt)) {
      var cp = this.getActiveCustomPrompt();
      if (cp) messages.push({ role: "system", content: cp });
    }
    // 3. MVU变量（默认注入，可按场景关闭）
    if (includeMVU) {
      var mvuCtx = getSharedMVUContext();
      if (mvuCtx) messages.push({ role: "system", content: mvuCtx });
    }
    // 4. 内置世界观（默认注入，可按场景关闭）
    if (includeBuiltinWorld) {
      var builtinWorld = await getBuiltinWorldContext();
      if (builtinWorld)
        messages.push({ role: "system", content: builtinWorld });
    }
    // 5. 聊天上下文
    var floors =
      options && options.contextFloors != null
        ? options.contextFloors
        : this.settings.contextFloors;
    if (
      this.channelKey === "chat" &&
      !(options && options.contextFloors != null)
    ) {
      floors = Math.max(Number(floors) || 0, 8);
    }
    if (includeChatContext && floors > 0) {
      if (options && options._phoneChatContextPreamble) {
        messages.push({
          role: "system",
          content: options._phoneChatContextPreamble,
        });
      }
      var chatCtx = getSharedChatContext(floors);
      for (var ci = 0; ci < chatCtx.length; ci++) {
        messages.push(chatCtx[ci]);
      }
    }
    if (this.channelKey === "chat" && includeChatContext) {
      messages.push({
        role: "system",
        content:
          "【手机聊天与正文剧情的关系——最高优先级】\n" +
          "手机聊天是正文剧情的延伸，不是独立故事。回复必须遵守以下原则：\n" +
          "① 角色回复内容必须与最近正文中发生的事件一致（刚吵架→不会突然卖萌；刚做爱→可以撒娇回味；刚上课→回复可能延迟简短）\n" +
          "② 角色不能在聊天中提到正文中还没发生的事\n" +
          "③ 如果正文中角色当前正在做某事（上课/约会/执行任务），聊天回复应体现其当前状态（忙碌/心不在焉/事后感想）\n" +
          "④ 若手机线程与主线场景冲突，以主线为准，手机内容只能作为口吻与关系延续参考\n" +
          "⑤ 手机私聊/群聊历史只代表线上异步交流，不代表当面互动",
      });
    }
    // 6. 用户传入的system prompt
    if (systemPrompt) messages.push({ role: "system", content: systemPrompt });
    // 7. 用户消息
    if (userMessage) messages.push({ role: "user", content: userMessage });
    var callOpts = Object.assign({}, options || {});
    if (!callOpts.triggerSource)
      callOpts.triggerSource = this.channelKey + ":chatapi";
    return await this.callAPI(messages, callOpts);
  }
}

