          yqToast("success", "AI已生成提示词，可修改后保存");
        }
      } catch (err) {
        yqToast("error", "生成失败: " + err.message);
      }
      $btn.prop("disabled", false).html(origH);
    });

    // 保存为预设
    $body.on("click.apich", ".api-ch-save-style-btn", function (e) {
      e.preventDefault();
      var promptText = $("#api-ch-custom-prompt").val().trim();
      if (!promptText) {
        yqToast("warning", "请先输入或生成提示词");
        return;
      }
      var styleName = prompt("请输入预设名称：");
      if (!styleName) return;
      if (!ch.settings.customStyles) ch.settings.customStyles = [];
      var exists = false;
      for (var i = 0; i < ch.settings.customStyles.length; i++) {
        if (ch.settings.customStyles[i].name === styleName) {
          ch.settings.customStyles[i].prompt = promptText;
          exists = true;
          break;
        }
      }
      if (!exists)
        ch.settings.customStyles.push({ name: styleName, prompt: promptText });
      ch.settings.activeStyle = styleName;
      ch.saveSettings();
      // 动态刷新下拉框
      var $select = $("#api-ch-style-select");
      if ($select.length) {
        // 检查是否已有该option
        var optionExists = false;
        $select.find("option").each(function () {
          if ($(this).val() === styleName) {
            optionExists = true;
            $(this).prop("selected", true);
          }
        });
        if (!optionExists) {
          $select.append(
            '<option value="' +
              escapeHtml(styleName) +
              '" selected>' +
              escapeHtml(styleName) +
              "</option>",
          );
        }
      }
      yqToast("success", "预设「" + styleName + "」已保存");
    });

    // 风格切换
    $body.on("change.apich", "#api-ch-style-select", function () {
      var selected = $(this).val();
      ch.settings.activeStyle = selected;
      if (selected) {
        var styles = ch.settings.customStyles || [];
        for (var i = 0; i < styles.length; i++) {
          if (styles[i].name === selected) {
            $("#api-ch-custom-prompt").val(styles[i].prompt);
            break;
          }
        }
      } else {
        // 选择"默认"时恢复默认提示词
        $("#api-ch-custom-prompt").val(
          ch.settings.customPrompt || ch.getDefaultCustomPrompt(),
        );
      }
    });

    // 保存所有设置
    $body.on("click.apich", ".api-ch-save-btn", function (e) {
      e.preventDefault();
      ch.settings.enabled = $("#api-ch-enabled").is(":checked");
      ch.settings.apiUrl = $("#api-ch-url").val().trim();
      ch.settings.apiKey = $("#api-ch-key").val().trim();
      ch.settings.model = $("#api-ch-model").val() || "";
      ch.settings.maxTokens = yqNormalizePhoneApiMaxTokens(
        channelKey,
