      ch.settings.temperature =
        parseFloat($("#api-ch-temperature").val()) || 0.85;
      ch.settings.maxConcurrent =
        parseInt($("#api-ch-max-concurrent").val()) || 2;
      ch.settings.contextFloors = parseInt($("#api-ch-context").val()) || 6;
      ch.settings.breakPrompt =
        $("#api-ch-break-prompt").val() || ch.getDefaultBreakPrompt();
      ch.settings.customPrompt = $("#api-ch-custom-prompt").val() || "";
      // imageGen通道不需要自动生成设置
      if (channelKey !== "imageGen") {
        ch.settings.autoGen = {
          enabled: $("#api-ch-autogen").is(":checked"),
          interval: parseInt($("#api-ch-interval").val()) || _defaultInterval,
          showToast: $("#api-ch-toast").is(":checked"),
        };
      }
      ch.saveSettings();
      // 论坛专属：保存论坛风格设置
      if (channelKey === "forum" && window.phoneForumManager) {
        var forumStyle = $("#api-ch-forum-style").val();
        if (forumStyle)
          window.phoneForumManager.settings.forumStyle = forumStyle;
        var forumPostCount = parseInt($("#api-ch-forum-post-count").val()) || 3;
        window.phoneForumManager.settings.postCount = forumPostCount;
        window.phoneForumManager.saveSettings();
      }
      // 平行事件专属：保存事件风格设置
      if (channelKey === "worldEvents") {
        var eventStyle = $("#api-ch-event-style").val();
        if (eventStyle) {
          if (!ch.settings._eventStyleSettings)
            ch.settings._eventStyleSettings = {};
          ch.settings._eventStyleSettings.eventStyle = eventStyle;
          ch.saveSettings();
        }
      }
      // 直播专属：保存直播风格设置
      if (channelKey === "live") {
        var liveStyle = $("#api-ch-live-style").val();
