          parseInt($("#api-ch-live-image-interval").val()) || 10;
        ch.saveSettings();
      }
      yqToast("success", appTitle + " API设置已保存");
    });

    // 返回
    $body.on("click.apich", ".api-ch-back-btn", function (e) {
      e.preventDefault();
      $body.off("click.apich change.apich");
