/**
 * 收集某NPC的已知信息（档案+场景详情+最近出场上下文）
 */
function _collectNpcKnownInfo(name) {
  var parts = [];
  try {
    var d = (typeof currentPhoneData !== "undefined" && currentPhoneData) || {};
    // 档案摘要
    var archive = _.get(d, "银麒系统.档案." + name, "");
    if (archive && typeof archive === "string") parts.push("档案：" + archive);
    // 场景详情
    var sceneDetail = _.get(d, "场景角色详情." + name, null);
    if (sceneDetail && typeof sceneDetail === "object") {
      var dress = sceneDetail.着装 || {};
      var dressStr = Object.entries(dress)
        .filter(function (e) {
          return e[1];
        })
        .map(function (e) {
          return e[0] + ":" + e[1];
        })
        .join(",");
      if (dressStr) parts.push("着装：" + dressStr);
      if (sceneDetail.当前情绪) parts.push("情绪：" + sceneDetail.当前情绪);
      if (sceneDetail.当前想法) parts.push("想法：" + sceneDetail.当前想法);
    }
    // 女性角色数值
    var fem = _.get(d, "女性角色." + name, null);
    if (fem && typeof fem === "object") {
      parts.push("性别：女");
      if (fem.与user关系) parts.push("与主角关系：" + fem.与user关系);
    }
    // 男性角色数值
    var male = _.get(d, "男性角色." + name, null);
    if (male && typeof male === "object") {
      parts.push("性别：男");
    }
    // 好友元数据
    var friendMeta = getPhoneMeta ? getPhoneMeta("yinqi_friend_meta", {}) : {};
    var fm = friendMeta[name];
    if (fm && typeof fm === "object") {
      if (fm.relationship) parts.push("关系阶段：" + fm.relationship);
      if (fm.gender) parts.push("性别：" + fm.gender);
    }
  } catch (_e) {}
  return parts.length > 0
    ? parts.join("；")
    : "姓名：" + name + "（无额外信息）";
}

/**
 * 判断NPC性别
 */
function _inferNpcGender(name) {
  try {
    var d = (typeof currentPhoneData !== "undefined" && currentPhoneData) || {};
    if (_.get(d, "女性角色." + name)) return "female";
    if (_.get(d, "男性角色." + name)) return "male";
    if (name === "林知意") return "female";
    var friendMeta = getPhoneMeta ? getPhoneMeta("yinqi_friend_meta", {}) : {};
    var fm = friendMeta[name];
    if (fm && fm.gender) return fm.gender;
  } catch (_e) {}
  return "unknown";
}

/**
 * 解析YAML格式的人设回复
 */
function _parsePersonaResponse(text) {
  var result = {};
  try {
    var yamlMatch = text.match(/```(?:yaml)?\s*([\s\S]*?)```/);
    var yamlStr = yamlMatch ? yamlMatch[1] : text;
    var lines = yamlStr.split("\n");
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (!line || line.startsWith("#")) continue;
      var colonIdx = line.indexOf(":");
      if (colonIdx <= 0) continue;
      var key = line.substring(0, colonIdx).trim();
      var val = line.substring(colonIdx + 1).trim();
      if (key && val) result[key] = val;
    }
  } catch (_e) {}
  return result;
}

/**
 * 将人设转为一行摘要（用于 _getCharProfile 消费）
 *
 * [V11.7+ 兼容新旧字段]
 *   优先读新字段(基础锚点/日常话头/...);旧字段(核心性格/说话风格/...)作 fallback
 *   保证老存档已有的 yinqi_npc_profiles 数据仍能产出 summary,不破坏玩家已积累的 NPC
 */
function _personaToSummary(persona) {
  if (!persona || typeof persona !== "object") return "";
  var parts = [];
  // [V11.7+ 新字段优先]
  if (persona["基础锚点"]) parts.push(persona["基础锚点"]);
  if (persona["日常话头"]) parts.push("话头:" + persona["日常话头"]);
  if (persona["小动作"]) parts.push("动作:" + persona["小动作"]);
  if (persona["对陌生女性反应阶梯"])
    parts.push("反应:" + persona["对陌生女性反应阶梯"]);
  if (persona["对陌生男性反应阶梯"])
    parts.push("反应:" + persona["对陌生男性反应阶梯"]);
  if (persona["口头禅"]) parts.push("常说「" + persona["口头禅"] + "」");
  if (persona["对玩家的称呼"])
    parts.push("称呼玩家:" + persona["对玩家的称呼"]);
  if (persona["反差锚点"]) parts.push("反差:" + persona["反差锚点"]);
  if (persona["潜在特征"]) parts.push("潜在:" + persona["潜在特征"]);
  if (persona["不会做什么"]) parts.push("边界:" + persona["不会做什么"]);
  // 如果新字段命中至少 1 个就用新字段产出 summary
  if (parts.length > 0) return parts.join(" / ");
  // [V11.4 及之前 旧字段 fallback]
  if (persona["核心性格"]) parts.push(persona["核心性格"]);
  if (persona["说话风格"]) parts.push("说话" + persona["说话风格"]);
  if (persona["口头禅"]) parts.push("常说「" + persona["口头禅"] + "」");
  if (persona["社交态度"]) parts.push(persona["社交态度"]);
  if (persona["外貌亮点"]) parts.push(persona["外貌亮点"]);
  if (persona["侵略性"]) parts.push("侵略性" + persona["侵略性"]);
  if (persona["防御意识"]) parts.push("防御意识" + persona["防御意识"]);
  return parts.join(",");
}

/**
 * 为指定NPC生成人设（加入队列）
 */
function queueNpcProfileGeneration(name, gender) {
  if (!name) return;
  // 核心13人已有硬编码人设，跳过
  if (_chatCharProfiles[name]) return;
  // 已有丰富人设，跳过
  var profiles = getPhoneMeta ? getPhoneMeta("yinqi_npc_profiles", {}) : {};
  if (profiles[name]) return;

  // 检查是否已在队列中
  for (var i = 0; i < _npcPersonaQueue.length; i++) {
    if (_npcPersonaQueue[i].name === name) return;
  }

  _npcPersonaQueue.push({
    name: name,
    gender: gender || _inferNpcGender(name),
  });
  _processPersonaQueue();
}

/**
 * 处理人设生成队列
 */
function _processPersonaQueue() {
  if (_npcPersonaProcessing || _npcPersonaQueue.length === 0) return;

  var now = Date.now();
  if (now - _npcPersonaLastGen < _NPC_PERSONA_COOLDOWN) {
    setTimeout(
      _processPersonaQueue,
      _NPC_PERSONA_COOLDOWN - (now - _npcPersonaLastGen),
    );
    return;
  }

  _npcPersonaProcessing = true;
  var item = _npcPersonaQueue.shift();
  _npcPersonaLastGen = now;

  _generateNpcPersona(item.name, item.gender);
}

/**
 * 调用API生成NPC人设
