function _getCharProfile(name) {
  var base = _chatCharProfiles[name];
  var profileText = null;
  if (base) {
    var phase = _getCharPhase(name);
    profileText = phase ? base + " [" + phase + "]" : base;
  }
  // 优先从丰富人设中读取（由NPC人设自动生成系统产生）
  if (!profileText) {
    try {
      var profiles =
        typeof getPhoneMeta === "function"
          ? getPhoneMeta("yinqi_npc_profiles", {})
          : {};
      var persona = profiles[name];
      if (persona && typeof persona === "object") {
        var summary =
          typeof _npcPersonaToSummary === "function"
            ? _npcPersonaToSummary(persona)
            : "";
        if (summary) {
          var phase2 = _getCharPhase(name);
          profileText = phase2 ? summary + " [" + phase2 + "]" : summary;
        }
      }
    } catch (_eProf) {}
  }
  // fallback: 从MVU银麒系统.档案读取（新角色50字摘要）
  if (!profileText) {
    try {
      var d =
        (typeof currentPhoneData !== "undefined" && currentPhoneData) || {};
      var archive = _.get(d, "银麒系统.档案." + name, null);
      if (archive && typeof archive === "string" && archive.length > 2) {
        var phase3 = _getCharPhase(name);
        profileText = phase3 ? archive + " [" + phase3 + "]" : archive;
      }
    } catch (e) {}
  }
  // 如果没有任何人设信息，触发异步生成
  if (!profileText) {
    try {
      if (typeof queueNpcProfileGeneration === "function") {
        queueNpcProfileGeneration(name);
      }
    } catch (_eQ) {}
    return null;
  }
  // [V9.6 P3++·2026-05-10] 附加银麒身体改造记录（所有 profile 来源通用）
  try {
    var ctxBM = (window.parent || window).SillyTavern.getContext();
    var bm =
      (ctxBM &&
        ctxBM.chatMetadata &&
        ctxBM.chatMetadata.yinqi_phone &&
        ctxBM.chatMetadata.yinqi_phone.yinqi_body_mods &&
        ctxBM.chatMetadata.yinqi_phone.yinqi_body_mods[name]) ||
      null;
    if (bm && typeof bm === "object") {
      var mods = [];
      if (bm.beauty && Number(bm.beauty) > 0)
        mods.push("容貌+" + Number(bm.beauty) + "%");
      if (bm.scars_cleared === true) mods.push("疤痕已清");
      if (bm.age_adjust && Number(bm.age_adjust) < 0)
        mods.push("年龄-" + Math.abs(Number(bm.age_adjust)) + "岁");
      if (bm.breast_cup) mods.push("胸型:" + bm.breast_cup);
      if (bm.body_reshape) mods.push("体型:" + bm.body_reshape);
      if (bm.tone_params) mods.push("完美参数:" + bm.tone_params);
      if (bm.custom_notes) mods.push("银麒重铸:" + bm.custom_notes);
      if (mods.length > 0) {
        profileText += " | 🧬银麒改造: " + mods.join("；");
      }
    }
  } catch (_eBMP) {}
  return profileText;
}

