// [V11.8 NTL·2026-05-25] NTL 接触冷处理 helper
//   女角色与{{user}}以外的男性发生超出社交的接触后,触发短期不回复 + 后续语气反应
//   男角色按性格分: 内向型不炫耀(暗自珍藏) / 外向型可能炫耀给{{user}}/室友 / 父辈装作无事
//
// 数据源:
//   1. 任务历史(yinqi_task_history): 最近一条非失败任务,executor/副executor/男性对象
//   2. MVU 字段: 女性角色.X.{侵犯次数, 暗攻略标记, 当前情绪}, 男性角色.X.屈辱度
//   3. 任务 historyEntry.id 是 "TASK-" + Date.now(),可反解时间戳

/**
 * [V11.8 NTL] 检查角色最近是否参与过 NTR 任务(执行者/副执行者/男性对象)
 * 返回 { participated: bool, role: 'executor'|'subExecutor'|'maleTarget', taskLevel, taskId, ageMinutes }
 * 在最近 N 分钟内才计入(默认 30 分钟,期间为"刚发生 NTR 接触"窗口)
 */
function _yqGetRecentNtrInvolvement(name, options) {
  options = options || {};
  var WINDOW_MIN = options.windowMinutes || 30;
  try {
    var ctx =
      typeof SillyTavern !== "undefined" && SillyTavern.getContext
        ? SillyTavern.getContext()
        : null;
    if (!ctx || !ctx.chatMetadata) return null;
    var pm = ctx.chatMetadata.yinqi_phone || {};
    var history = pm.yinqi_task_history || [];
    if (!Array.isArray(history) || history.length === 0) return null;

    var now = Date.now();
    var windowMs = WINDOW_MIN * 60 * 1000;
    for (var i = 0; i < history.length; i++) {
      var h = history[i];
      if (!h || h.grade === "失败") continue;
      // 反解时间戳
      var match = String(h.id || "").match(/TASK-(\d+)/);
      var ts = match ? Number(match[1]) : 0;
      if (!ts || now - ts > windowMs) {
        // 比窗口外更早,因为 history 倒序排列(最新在前),后续都是更老的
        if (history[0] !== h) break;
        continue;
      }
      // 检查 name 是否参与
      var role = null;
      if (h.executor === name) role = "executor";
      else if (h.subExecutor === name) role = "subExecutor";
      else if (h.target === name || h.targetNpcName === name)
        role = "maleTarget";
      if (role) {
        return {
          participated: true,
          role: role,
          taskLevel: h.level || "",
          taskId: h.id || "",
          ageMinutes: Math.floor((now - ts) / 60000),
          targetNpcName: h.targetNpcName || "",
        };
      }
    }
  } catch (_e) {}
  return null;
}

