  // 存储NPC主动消息到chatMetadata
  // [V8.2+ Round-6] 加写入锁防止并发 async 生成器交错导致消息丢失
  storeNpcMessage(contactId, senderName, content, isGroup) {
    if (this._npcMsgWriteLock) {
      // 排队等待
      this._npcMsgWriteQueue = this._npcMsgWriteQueue || [];
      this._npcMsgWriteQueue.push({ contactId, senderName, content, isGroup });
      return;
    }
    this._npcMsgWriteLock = true;
    try {
      this._doStoreNpcMessage(contactId, senderName, content, isGroup);
    } finally {
      this._npcMsgWriteLock = false;
      // 处理排队的写入
      if (this._npcMsgWriteQueue && this._npcMsgWriteQueue.length > 0) {
        var next = this._npcMsgWriteQueue.shift();
        this.storeNpcMessage(
          next.contactId,
          next.senderName,
          next.content,
          next.isGroup,
        );
      }
    }
  }

