      result = stripJsonCodeBlock(result);
      var jsonMatch = result.match(/\[[\s\S]*\]/);
      if (!jsonMatch) return;
      var msgs = JSON.parse(jsonMatch[0]);
      if (!Array.isArray(msgs)) return;

      for (var m = 0; m < msgs.length; m++) {
        var msg = msgs[m];
        // [V11.2] 处理 silent 状态：AI 标记 responded:false 或 state
        if (msg.sender && msg.responded === false) {
          var _silentState = String(msg.state || "asleep");
          var _silentReason = String(msg.reason || "");
          _markNpcSilent(msg.sender, _silentState, _silentReason, {
            isGroup: false,
          });
          this.setCooldown(msg.sender);
          if (typeof window.yqMarkAutoEmitChar === "function") {
            window.yqMarkAutoEmitChar(msg.sender, "chat");
          }
          continue;
        }
        if (msg.sender && msg.content) {
          if (typeof window.yqCanAutoEmitChar === "function") {
            var _msgGuard = window.yqCanAutoEmitChar(msg.sender, "chat", {
              allowGroupChatFamily: true,
            });
            if (!_msgGuard || _msgGuard.allowed !== true) continue;
          }
          // [V11.2] AI 正常回复 → 清除可能存在的旧 silent 状态
          _clearNpcSilent(msg.sender);
          var contactId = "friend_" + msg.sender;
          this.storeNpcMessage(contactId, msg.sender, msg.content, false);
          this.setCooldown(msg.sender);
          if (typeof window.yqMarkAutoEmitChar === "function") {
            window.yqMarkAutoEmitChar(msg.sender, "chat");
          }
        }
      }
    } catch (e) {
      console.warn("[NPC私聊] 生成失败:", e);
    }
  }

