        try {
          var singleEvent = JSON.parse(jsonObjMatch[0]);
          if (singleEvent.summary) events = [singleEvent];
        } catch (e) {
          // JSON被截断恢复：尝试从原始文本中提取字段
          try {
            var raw = jsonObjMatch[0];
            // 提取type字段
            var typeMatch = raw.match(/"type"\s*:\s*"([^"]*)"/);
            var locMatch = raw.match(/"location"\s*:\s*"([^"]*)"/);
            // 提取summary字段（可能很长且被截断）
            var summaryMatch = raw.match(/"summary"\s*:\s*"([\s\S]*)/);
            if (summaryMatch) {
              var summaryRaw = summaryMatch[1];
              // 找到summary值的结束位置：最后一个有效的引号
              // 先尝试找到正常结束的 "} 或 ",
              var summaryEnd = -1;
              var inEscape = false;
              for (var si = 0; si < summaryRaw.length; si++) {
                if (inEscape) {
                  inEscape = false;
                  continue;
                }
                if (summaryRaw[si] === "\\") {
                  inEscape = true;
                  continue;
                }
                if (summaryRaw[si] === '"') {
                  summaryEnd = si;
                  break;
                }
              }
              var summaryText;
              if (summaryEnd > 0) {
                summaryText = summaryRaw.substring(0, summaryEnd);
              } else {
                // 完全截断，没有结束引号，取全部内容
                summaryText = summaryRaw.replace(/["\s}]*$/, "");
              }
              // 反转义JSON字符串
              try {
                summaryText = JSON.parse('"' + summaryText + '"');
              } catch (pe) {
                // 手动处理常见转义
                summaryText = summaryText
                  .replace(/\\n/g, "\n")
                  .replace(/\\"/g, '"')
                  .replace(/\\\\/g, "\\");
              }
              if (summaryText && summaryText.length > 50) {
                console.log(
                  "[世界动态] JSON被截断，已恢复 " +
                    summaryText.length +
                    " 字内容",
                );
                events = [
                  {
                    type: typeMatch ? typeMatch[1] : "推测",
                    location: locMatch ? locMatch[1] : "",
                    summary: summaryText,
                  },
                ];
              }
            }
          } catch (re) {
            console.warn("[世界动态] 截断恢复也失败:", re);
          }
        }
      }
      // 最后兜底：如果JSON完全无法解析，尝试直接从原始文本提取summary
      if (
        (!Array.isArray(events) || events.length === 0) &&
        result &&
        result.length > 100
      ) {
        try {
          var rawSummaryMatch = result.match(/"summary"\s*:\s*"([\s\S]{50,})/);
          if (rawSummaryMatch) {
            var rawText = rawSummaryMatch[1];
            // 去掉末尾可能的JSON残留
            var endQuote = -1;
            var esc = false;
            for (var ri = 0; ri < rawText.length; ri++) {
              if (esc) {
                esc = false;
                continue;
              }
              if (rawText[ri] === "\\") {
                esc = true;
                continue;
              }
              if (rawText[ri] === '"') {
                endQuote = ri;
                break;
              }
            }
            var extracted =
              endQuote > 0
                ? rawText.substring(0, endQuote)
                : rawText.replace(/["\s}]*$/, "");
            try {
              extracted = JSON.parse('"' + extracted + '"');
            } catch (pe2) {
              extracted = extracted
                .replace(/\\n/g, "\n")
                .replace(/\\"/g, '"')
                .replace(/\\\\/g, "\\");
            }
            if (extracted && extracted.length > 50) {
              var tM = result.match(/"type"\s*:\s*"([^"]*)"/);
              var lM = result.match(/"location"\s*:\s*"([^"]*)"/);
              console.log(
                "[世界动态] 兜底恢复成功，" + extracted.length + " 字",
              );
              events = [
                {
                  type: tM ? tM[1] : "推测",
                  location: lM ? lM[1] : "",
                  summary: extracted,
                },
              ];
            }
          }
        } catch (fe) {}
      }
      // 终极兜底：如果所有JSON解析都失败，但result有足够长的文本，直接使用
      if (
        (!Array.isArray(events) || events.length === 0) &&
        result &&
        result.length > 200
      ) {
        // 去掉可能的markdown代码块包裹和JSON残留
        var plainText = result
          .replace(/^```[\s\S]*?\n/, "")
          .replace(/\n```\s*$/, "")
          .replace(/^\s*\{[\s\S]{0,50}?"summary"\s*:\s*"?/, "")
          .replace(/["\s}\]]*$/, "")
          .trim();
        // 反转义
        plainText = plainText
          .replace(/\\n/g, "\n")
          .replace(/\\"/g, '"')
          .replace(/\\\\/g, "\\");
        if (plainText.length > 100) {
          console.log(
            "[世界动态] 终极兜底：直接使用原始文本，" +
              plainText.length +
              " 字",
          );
          events = [
            {
              type: "推测",
              location: "",
              summary: plainText,
            },
          ];
        }
      }
      if (!Array.isArray(events) || events.length === 0) return null;

      // 不再存储到localStorage，直接返回事件供调用方插入楼层
      var ev = events[0];
      if (ev && ev.summary) {
        return {
          type: ev.type || "推测",
          location: ev.location || "",
          summary: ev.summary,
          time:
            curTime ||
            new Date().toLocaleTimeString("zh-CN", {
              hour: "2-digit",
              minute: "2-digit",
            }),
          timestamp: Date.now(),
        };
      }
      return null;
    } catch (e) {
      console.warn("[世界动态] 生成失败:", e);
      return null;
    }
  }

