  var fullMatch = s.match(
    /(\d{4})年(\d{1,2})月(\d{1,2})日\s*(\d{1,2}):(\d{2})/,
  );
  if (fullMatch) {
    var y = +fullMatch[1],
      mo = +fullMatch[2],
      d = +fullMatch[3];
    var h = +fullMatch[4],
      mi = +fullMatch[5];
    return ((y - 2024) * 365 + (mo - 1) * 31 + d) * 1440 + h * 60 + mi;
  }
  // 短格式 "M月D日 HH:MM" → 用当前 MVU 年补齐
  var shortMatch = s.match(/(\d{1,2})月(\d{1,2})日\s*(\d{1,2}):(\d{2})/);
  if (shortMatch) {
    try {
      var curD =
        typeof currentPhoneData !== "undefined" && currentPhoneData
          ? currentPhoneData
          : {};
      var curDate = String(_.get(curD, "银麒系统.世界.日期", ""));
      var curYearMatch = curDate.match(/(\d{4})年/);
      var curYear = curYearMatch ? +curYearMatch[1] : 2026;
      var mo2 = +shortMatch[1],
        d2 = +shortMatch[2];
      var h2 = +shortMatch[3],
        mi2 = +shortMatch[4];
      return (
        ((curYear - 2024) * 365 + (mo2 - 1) * 31 + d2) * 1440 + h2 * 60 + mi2
      );
    } catch (_e) {
      return null;
    }
  }
  // "HH:MM" 仅时分（旧数据）→ 无法可靠跨天比较，返回 null
  return null;
}

