  } catch (_e3) {}
  try {
    allNpc = getPhoneMetaBig("npc_messages", {}) || {};
  } catch (_e4) {}

  // 3. 遍历每个群，筛选符合条件的群
  var groupRecords = {};

  Object.keys(allGroups).forEach(function (gid) {
    var g = allGroups[gid];
    if (!g) return;
    // 排除当前群
    if (
      currentGid &&
      typeof _yqGroupIdsMatch === "function" &&
      _yqGroupIdsMatch(gid, currentGid)
    )
      return;
    var members =
      typeof _yqSplitGroupMembers === "function"
        ? _yqSplitGroupMembers(g.members || "")
        : [];
    if (members.length === 0) return;

    // 哪些 NPC 参与方在该群（隔离铁律）
    var visibleTo = participants.filter(function (n) {
      return members.indexOf(n) !== -1;
    });
    if (visibleTo.length === 0) return;

    // 合并 chat_history + npc_messages
    var bareGid =
      typeof _yqBareGroupId === "function" ? _yqBareGroupId(gid) : gid;
    var groupKey = "group_" + bareGid;
    var hist1 = allChat[groupKey] || [];
    var hist2 = allNpc[groupKey] || [];
    var merged = [];
    hist1.forEach(function (m) {
      if (!m || !m.content) return;
      merged.push({
        who: m.type === "user" ? "我" : m.sender || "?",
        text: String(m.content).slice(0, 200),
        time: m.time || 0,
        mvuTime: m.gameTime || "",
      });
    });
    hist2.forEach(function (m) {
      if (!m || !m.content) return;
      merged.push({
        who: m.sender || "?",
        text: String(m.content).slice(0, 200),
        time: m.time || 0,
        mvuTime: m.timeStr || "",
      });
    });
    if (merged.length === 0) return;

    // 按现实时间戳排序（time 比 mvuTime 更稳定）
    merged.sort(function (a, b) {
      return (a.time || 0) - (b.time || 0);
    });
    var recent = merged.slice(-cfg.perGroupMsgs);

    // 用最新消息的 MVU 时间作为群级时间锚点
    var latestMsg = recent[recent.length - 1];
    var latestMvuMins = _yqParseMvuTime(latestMsg.mvuTime);
    if (latestMvuMins == null) return; // 历史消息无完整 MVU 时间 → 整群跳过
    var diffMins = nowMins - latestMvuMins;
    if (diffMins < 0) diffMins = 0;
    if (diffMins > cfg.hardCutMins) return; // 超过硬截断（2 天 / 4 天）

    groupRecords[bareGid] = {
      groupId: bareGid,
      groupName: g.name || bareGid,
      visibleTo: visibleTo,
      latestMins: latestMvuMins,
      diffMins: diffMins,
      relativeLabel: _yqFormatMvuRelative(latestMsg.mvuTime, nowMvuTime),
      msgs: recent,
    };
  });

  // 4. 按最新消息时间倒序排，截取前 maxGroups 个
  var sortedGroups = Object.keys(groupRecords).map(function (k) {
    return groupRecords[k];
  });
  sortedGroups.sort(function (a, b) {
    return b.latestMins - a.latestMins;
  });
  sortedGroups = sortedGroups.slice(0, cfg.maxGroups);
  if (sortedGroups.length === 0) return "";

  // 5. 按总预算切分群级预算
  var perGroupBudget = Math.floor(cfg.totalBudget / sortedGroups.length);
  if (perGroupBudget < 200) perGroupBudget = 200;

  // 6. 拼接提示词
  var out =
    "\n【其他群聊最近动态——参考此处了解相关角色最近在其他群里说过的话】\n\n";

  sortedGroups.forEach(function (rec) {
    var visTag =
      rec.visibleTo.length === participants.length
        ? "全员可见"
        : rec.visibleTo.join("/") + " 可见";
    var groupHeader =
      "[「" +
      rec.groupName +
      "」· " +
      rec.relativeLabel +
      " — " +
      visTag +
      "]\n";

    var msgLines = rec.msgs.map(function (m) {
      return "  " + m.who + ": " + m.text;
    });
    var combined = groupHeader + msgLines.join("\n") + "\n\n";
    // 超出预算从最旧消息开始截断
    while (combined.length > perGroupBudget && msgLines.length > 1) {
      msgLines.shift();
      combined = groupHeader + msgLines.join("\n") + "\n\n";
    }
    out += combined;
  });

  // 7. 使用规则
  out += "【使用规则】\n";
  out += '- 每段头部标注"XX 可见"——只有标注的角色才知道该群里的事\n';
  out += "- 严禁让一个角色引用自己不在的群里的内容（即使玩家在那个群说过话）\n";
  out += "- 自然延续话题或情绪，**不要直接复述群消息内容**\n";
  out +=
    '- 群消息有时间标签——超过 1 天的消息只能作为"早些时候"提及，不能当"刚才"用\n\n';

  return out;
}

