                      );
                    }
                  }
                })
                .catch(function (e) {
                  console.warn("[群聊配图] 自动生图失败:", e);
                });
            })(imgMarkers2[im2]);
          }
        }
      }
    } catch (e) {
      console.warn("[群聊配图] 处理失败:", e);
    }
  }

  // 解析AI回复中的消息格式标签
  parseAIReply(reply) {
    var results = [];
    if (!reply) return results;
    // 先清理AI回复中的干扰内容
    var cleaned = reply;
    // [V10.6] 移除推理标签：覆盖 think/thinking/thought/reasoning 等多种变体
    if (typeof stripThinkingTags === "function") {
      cleaned = stripThinkingTags(cleaned);
    } else {
      cleaned = cleaned.replace(
        /<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi,
        "",
      );
    }
    // 移除markdown格式标记
    cleaned = cleaned.replace(/\*\*([^*]*)\*\*/g, "$1");
    cleaned = cleaned.replace(/\*([^*]*)\*/g, "$1");
    cleaned = cleaned.replace(/~~([^~]*)~~/g, "$1");
    cleaned = cleaned.replace(/^#+\s+/gm, "");
    // [V10.6 BUG FIX] 只移除代码块围栏标记 ```，保留内容
    //   旧逻辑 /```[\s\S]*?```/g 会删除整个代码块包括内容，
    //   AI 把回复整段包在 ```...``` 里时格式标签会被一起删
    cleaned = cleaned.replace(/```(?:json|javascript|js|html|md)?\s*/gi, "");
    cleaned = cleaned.replace(/```\s*/g, ""); // 剥尾部孤立围栏，保持 fallback 路径干净
    cleaned = cleaned.replace(/`([^`]*)`/g, "$1");

    // 匹配私聊: [对方消息|名字|号码|类型|内容]
    // 内容中可能包含[发图:描述]等嵌套方括号，使用支持嵌套的正则
    var privateRe =
      /\[对方消息\|([^|]*)\|([^|]*)\|([^|]*)\|((?:[^\[\]]|\[[^\]]*\])*)\]/g;
    var match;
    while ((match = privateRe.exec(cleaned)) !== null) {
      results.push({
        sender: match[1].trim(),
        content: this.cleanMessageContent(match[4]),
      });
    }
    // 匹配群聊: [群聊消息|群号|发送者|类型|内容]
    var groupRe =
      /\[群聊消息\|([^|]*)\|([^|]*)\|([^|]*)\|((?:[^\[\]]|\[[^\]]*\])*)\]/g;
    while ((match = groupRe.exec(cleaned)) !== null) {
      results.push({
        groupId: match[1].trim(),
        sender: match[2].trim(),
        content: this.cleanMessageContent(match[4]),
      });
    }
    // 如果没有匹配到格式标签，把整个回复当作一条消息
    if (results.length === 0 && cleaned.trim()) {
      // 清理可能的格式前缀和分析性文字
      var fallback = cleaned.replace(/^\s*\[.*?\]\s*/g, "").trim();
      // 移除开头的分析性文字（如"好的，我来模拟..."等）
      fallback = fallback.replace(
        /^(好的|嗯|OK|了解|明白|收到)[，,。.！!]?\s*(我来|让我|下面|以下)[\s\S]{0,50}?(：|:|\n)/i,
        "",
      );
      fallback = this.cleanMessageContent(fallback);
      if (fallback) {
        // 群聊 fallback 必须可见。未按格式返回时无法安全归属具体成员，
        // 因此作为系统消息落库，避免被群成员白名单再次过滤成“无回复”。
        var fallbackSender = this.isGroup
          ? "系统"
          : this.currentFriendName || "对方";
        results.push({
          sender: fallbackSender,
          content: fallback,
          _formatFallback: true,
        });
      }
    }
    return results;
  }

  // 清理消息内容中的干扰符号
  cleanMessageContent(text) {
    if (!text) return "";
    var c = text;
    // [V10.5] 移除 emoji 整段剥离 — 让 AI 用真实 emoji 表达情绪
    // emoji 不会与格式分隔符 | 冲突，正则 [^|]+? 仍正常匹配
    // 仅保留 markdown 残留剥离（避免渲染异常）
    c = c.replace(/\*\*([^*]*)\*\*/g, "$1");
    c = c.replace(/\*([^*]*)\*/g, "$1");
    // [V12·2026-05-30 问题1] AI 有时不按提示词输出真 emoji，而输出文字描述
    //   （「笑哭」「[微笑]」「(害羞)」等），渲染层不认 → 表情包变文字。
    //   这里做代码层兜底归一：把常见“文字情绪词 / 微信表情码”替换成真实 emoji。
    c = _yqNormalizeTextEmoji(c);
    return c.trim();
  }

