  async waitForAIResponse(onMessageUpdate = null) {
    var chatAPI = window.phoneAPI.chat;
    if (chatAPI && chatAPI.isAvailable()) return Promise.resolve();
    return new Promise((resolve) => {
      let tw = window;
      if (window.parent && window.parent !== window) {
        try {
          if (window.parent.SillyTavern) tw = window.parent;
        } catch (e) {}
      }
      if (!tw.SillyTavern || !tw.SillyTavern.getContext) {
        setTimeout(resolve, 5000);
        return;
      }
      const ctx = tw.SillyTavern.getContext();
      const initCount = ctx.chat ? ctx.chat.length : 0;
      let ck = 0,
        lmc = "",
        sc = 0,
        lc = initCount;
      const ci = setInterval(() => {
        ck++;
        try {
          const cc = tw.SillyTavern.getContext();
          const cn = cc.chat ? cc.chat.length : 0;
          if (cn > initCount) {
            if (cn > lc && onMessageUpdate) {
              onMessageUpdate();
              lc = cn;
              sc = 0;
            }
            const lm = cc.chat[cc.chat.length - 1];
            const mc = lm?.mes || "";
            if (mc !== lmc) {
              lmc = mc;
              sc = 0;
            } else {
              sc++;
              if (sc >= 10) {
                clearInterval(ci);
                if (onMessageUpdate) onMessageUpdate();
                setTimeout(resolve, 500);
                return;
              }
            }
          }
          if (ck >= 300) {
            clearInterval(ci);
            resolve();
          }
        } catch (e) {
          clearInterval(ci);
          resolve();
        }
      }, 100);
    });
  }

  async buildAndSendMessage(message, uiElements = null) {
    if (!this.currentFriendId || !this.currentFriendName)
      throw new Error("未设置当前聊天对象");
    var snapTargetName = this.currentFriendName;
    const lines = message.split("\n").filter((l) => l.trim());
    if (lines.length === 0) throw new Error("消息内容不能为空");

    var chatAPI = window.phoneAPI.chat;
    if (chatAPI && chatAPI.isAvailable()) {
      var ok = await this.sendToChat(lines.join("\n"));
      if (ok)
        this.showSendSuccessToast(
          snapTargetName,
          lines.length > 1 ? lines.length + "条消息" : lines[0],
        );
      return ok;
    }

    /* 未配置独立API时不再回退到SillyTavern主楼，直接提示 */
    yqToast("warning", "请先在消息⚙️设置中配置聊天API", "💬 未配置API");
    return false;
  }

  showSendSuccessToast(targetName, msg) {
    var safeTarget =
      targetName != null && String(targetName).trim()
        ? String(targetName).trim()
        : "当前会话";
    yqToast(
      "success",
      "发送给: " +
        safeTarget +
        "\n" +
        (msg.length > 20 ? msg.substring(0, 20) + "..." : msg),
    );
  }
  showSendErrorToast(err) {
    yqToast("error", "发送失败: " + err);
  }

  async sendMessage(message, uiElements = null) {
    if (!message.trim()) {
      this.showSendErrorToast("消息内容不能为空");
      return false;
    }
    if (!this.currentFriendId) {
      this.showSendErrorToast("请选择一个聊天对象");
      return false;
    }
    // 禁用发送按钮，防止重复发送
    if (uiElements && uiElements.button) {
      uiElements.button.prop("disabled", true);
      if (uiElements.icon) {
        uiElements.icon
          .removeClass("fa-paper-plane")
          .addClass("fa-spinner fa-spin");
      }
    }
    try {
      var ok = await this.buildAndSendMessage(message, uiElements);
      if (!ok) this.showSendErrorToast("发送失败");
      return ok;
    } catch (e) {
      this.showSendErrorToast(e.message || "发送失败");
      return false;
    } finally {
      // 恢复发送按钮状态
      if (uiElements && uiElements.button) {
        uiElements.button.prop("disabled", false);
        if (uiElements.icon) {
          uiElements.icon
            .removeClass("fa-spinner fa-spin")
            .addClass("fa-paper-plane");
        }
      }
    }
  }

  clearCurrentChat() {
    this.currentFriendId = null;
    this.currentFriendName = null;
    this.isGroup = false;
