  /**
   * 获取当前群聊的成员列表
   * 参考 mobile-master/app/message-sender.js 的实现
   */
  getCurrentGroupMembers() {
    if (!this.isGroup || !this.currentFriendId) {
      return [];
    }
    try {
      var savedGroupInfo = _yqGetSavedGroupByAnyId(this.currentFriendId);
      if (
        savedGroupInfo &&
        savedGroupInfo.data &&
        savedGroupInfo.data.members
      ) {
        return _yqSplitGroupMembers(savedGroupInfo.data.members);
      }
    } catch (_savedGroupErr) {}

    try {
      // 方法1: 从聊天记录中查找最新的群聊信息
      var targetWindow = window;
      if (window.parent && window.parent !== window) {
        try {
          if (window.parent.SillyTavern) targetWindow = window.parent;
        } catch (e) {}
      }
      if (!targetWindow.SillyTavern || !targetWindow.SillyTavern.getContext) {
        return [];
      }

      const context = targetWindow.SillyTavern.getContext();
      const messages = context.chat || [];
      let latestGroupInfo = null;

      // 创建正则表达式匹配该群的信息（不限制群号，后面再筛选）
      // 格式1: [群聊|群名|群号|成员列表]
      const groupRegex1 = /\[群聊\|([^\|]+)\|([^\|]+)\|([^\]]+)\]/g;
      // 格式2: [创建群聊|群号|群名|成员列表]
      const groupRegex2 = /\[创建群聊\|([^\|]+)\|([^\|]+)\|([^\]]+)\]/g;

      // 从最新消息开始查找
      for (let i = messages.length - 1; i >= 0; i--) {
        let messageText = messages[i].mes || "";

        // 清理EJS模板标签和变量更新块，防止脚本内容干扰消息解析
        messageText = messageText.replace(/<%[\s\S]*?%>/g, "");
        messageText = messageText.replace(
          /<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g,
          "",
        );
        messageText = messageText.replace(
          /<ai_instruction>[\s\S]*?<\/ai_instruction>/g,
          "",
        );
        messageText = messageText.replace(/<StatusPlaceHolderImpl\s*\/?>/g, "");

        //  清理提示词模板：从消息文本中删除模板部分，保留真实内容
        // 删除包含"群聊消息响应格式要求"到"可以有多个角色回复"之间的所有内容
        messageText = messageText.replace(
          /群聊消息响应格式要求[\s\S]*?可以有多个角色回复，每个角色一条消息/g,
          "",
        );
        messageText = messageText.replace(
          /私聊消息响应格式要求[\s\S]*?可以回复多条消息/g,
          "",
        );

        // 删除包含字面量的示例格式
        messageText = messageText.replace(
          /\[群聊消息\|群号\|发送者名字\|消息类型\|消息内容\]/g,
          "",
        );
        messageText = messageText.replace(
          /\[对方消息\|角色名字\|号码\|消息类型\|消息内容\]/g,
          "",
        );
        messageText = messageText.replace(
          /\[我方消息\|我\|号码\|消息类型\|消息内容\]/g,
          "",
        );
        messageText = messageText.replace(
          /\[群聊\|群名\|群号\|成员列表\]/g,
          "",
        );
        messageText = messageText.replace(
          /\[创建群聊\|群号\|群名\|成员列表\]/g,
          "",
        );

        // 如果清理后的消息为空，跳过
        if (!messageText.trim()) {
          continue;
        }

        // 重置正则表达式索引
        groupRegex1.lastIndex = 0;
        groupRegex2.lastIndex = 0;

        // 尝试匹配第一种格式：[群聊|群名|群号|成员列表]
        let match = groupRegex1.exec(messageText);
        if (match) {
          const groupName = match[1];
          const groupId = match[2];
          const members = match[3];

          // 检查群号是否匹配（使用字符串比较）
          if (_yqGroupIdsMatch(groupId, this.currentFriendId)) {
            latestGroupInfo = {
              groupName: groupName,
              members: members,
            };
            break;
          }
        }

        // 尝试匹配第二种格式：[创建群聊|群号|群名|成员列表]
        match = groupRegex2.exec(messageText);
        if (match) {
          const groupId = match[1];
          const groupName = match[2];
          const members = match[3];

          // 检查群号是否匹配（使用字符串比较）
          if (_yqGroupIdsMatch(groupId, this.currentFriendId)) {
            latestGroupInfo = {
              groupName: groupName,
              members: members,
            };
            break;
          }
        }
      }

      if (latestGroupInfo) {
        // 解析成员列表
        const members = latestGroupInfo.members
          .split(/[、,，]/)
          .map((name) => name.trim())
          .filter((name) => name);

        return members;
      }

      // 方法2: 如果没找到定义，尝试从群聊消息中提取成员
      const membersSet = new Set();
      const groupIdPattern = _yqEscapeRegex(
        _yqBareGroupId(this.currentFriendId),
      );
      const groupMessageRegex = new RegExp(
        `\\[群聊消息\\|(?:${groupIdPattern}|group_${groupIdPattern})\\|([^\\|]+)\\|`,
        "g",
      );

      messages.forEach((msg) => {
        const messageText = msg.mes || "";
        groupMessageRegex.lastIndex = 0;
        let match;
        while ((match = groupMessageRegex.exec(messageText)) !== null) {
          const senderName = match[1];
          if (senderName && senderName !== "我") {
            membersSet.add(senderName);
          }
        }
      });

      // 如果我发送过消息，添加"我"
      const myGroupMessageRegex = new RegExp(
        `\\[我方群聊消息\\|我\\|(?:${groupIdPattern}|group_${groupIdPattern})\\|`,
        "g",
      );
      const hasMyMessage = messages.some((msg) => {
        const messageText = msg.mes || "";
        myGroupMessageRegex.lastIndex = 0;
        return myGroupMessageRegex.test(messageText);
      });

      if (hasMyMessage) {
        membersSet.add("我");
      }

      const members = Array.from(membersSet);
      if (members.length > 0) {
        return members;
      }

      return [];
    } catch (error) {
      return [];
    }
  }
}

