/**
 * 从聊天记录中提取与指定联系人的消息
 */
function extractMessagesForContact(contactId, isGroup = false) {
  const messages = [];
  const messageSet = new Set(); // 用于去重

  // [V10.12·2026-05-19] 整个游戏世界的时间锚点是 MVU 时间——现实时间在游戏内无意义。
  //   消息显示策略：
  //     - 每条消息在发出时已存了当时的 MVU 时间（chatMsg.gameTime / nMsg.timeStr）
  //     - 直接显示消息自带的 MVU 时间——这是消息发出的真实时间，永远不变
  //     - V10.11 前的历史消息可能没存 MVU 时间，显示为空（不冒用现实时间或当前 MVU）
  //   不再使用 _displayTime 兜底——因为兜底任何"当前时间"都是欺骗性的（消息可能是历史的）
  var _groupAllowSet = isGroup
    ? _yqBuildGroupMemberAllowSet(contactId, [])
    : null;

  try {
    let chatMessages = [];

    let targetWindow = window;
    if (window.parent && window.parent !== window) {
      try {
        if (window.parent.SillyTavern) {
          targetWindow = window.parent;
        }
      } catch (e) {
        void e;
      }
    }

    if (targetWindow.SillyTavern && targetWindow.SillyTavern.getContext) {
      const context = targetWindow.SillyTavern.getContext();
      chatMessages = context.chat || [];
    }

    chatMessages.forEach((msg, index) => {
      if (!msg.mes) return;
      let text = msg.mes;

      // 清理EJS模板标签和变量更新块，防止脚本内容干扰消息解析
      text = text.replace(/<%[\s\S]*?%>/g, "");
      text = text.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, "");
      text = text.replace(/<ai_instruction>[\s\S]*?<\/ai_instruction>/g, "");
      text = text.replace(/<StatusPlaceHolderImpl\s*\/?>/g, "");

      //  清理提示词模板：从消息文本中删除模板部分，保留真实内容
      text = text.replace(
        /群聊消息响应格式要求[\s\S]*?可以有多个角色回复，每个角色一条消息/g,
        "",
      );
      text = text.replace(/私聊消息响应格式要求[\s\S]*?可以回复多条消息/g, "");
      text = text.replace(
        /\[群聊消息\|群号\|发送者名字\|消息类型\|消息内容\]/g,
        "",
      );
      text = text.replace(
        /\[对方消息\|角色名字\|号码\|消息类型\|消息内容\]/g,
        "",
      );
      text = text.replace(/\[我方消息\|我\|号码\|消息类型\|消息内容\]/g, "");
      text = text.replace(/\[群聊\|群名\|群号\|成员列表\]/g, "");
      text = text.replace(/\[创建群聊\|群号\|群名\|成员列表\]/g, "");

      // 如果清理后的消息为空，跳过
      if (!text.trim()) return;

      // 如果是群聊，记录包含群聊消息的文本
      // if (isGroup && text.includes('[群聊消息|')) {
      // }

      // 匹配私聊消息: [我方消息|我|号码|类型|内容] 或 [对方消息|名字|号码|类型|内容]
      const privateRegex =
        /\[(我方消息|对方消息)\|([^|]*)\|([^|]*)\|([^|]*)\|([^\]]*)\]/g;
      // 匹配群聊消息: [群聊消息|群号|发送者|类型|内容]
      const groupRegex = /\[群聊消息\|([^|]*)\|([^|]*)\|([^|]*)\|([^\]]*)\]/g;
      //  新增：匹配我方群聊消息: [我方群聊消息|我|群号|类型|内容]
      const myGroupRegex = /\[我方群聊消息\|我\|([^|]*)\|([^|]*)\|([^\]]*)\]/g;

      let match;

      if (isGroup) {
        groupRegex.lastIndex = 0;
        while ((match = groupRegex.exec(text)) !== null) {
          const groupId = match[1].trim();
          const sender = match[2].trim();
          const msgType = match[3].trim();
          const content = match[4];

          //  过滤模板消息：如果内容仅为"内容"或"消息内容"，跳过
          if (content.trim() === "内容" || content.trim() === "消息内容") {
            continue;
          }

          if (_yqGroupIdsMatch(groupId, contactId)) {
            // 归一化sender：user/{{user}}都视为"我"
            var normalizedSender = sender;
            if (
              normalizedSender === "user" ||
              normalizedSender === "{{user}}" ||
              normalizedSender === "User"
            )
              normalizedSender = "我";
            if (
              normalizedSender !== "我" &&
              !_yqIsAllowedGroupSender(normalizedSender, _groupAllowSet)
            ) {
              continue;
            }
            const messageKey = normalizedSender + "|" + msgType + "|" + content;

            if (!messageSet.has(messageKey)) {
              messageSet.add(messageKey);
              messages.push({
                isMine: normalizedSender === "我",
                sender: normalizedSender,
                type: msgType,
                content: content,
                time: "",
              });
            }
          }
        }

        myGroupRegex.lastIndex = 0;
        while ((match = myGroupRegex.exec(text)) !== null) {
          const groupId = match[1].trim();
          const msgType = match[2].trim();
          const content = match[3];

          //  过滤模板消息：如果内容仅为"内容"或"消息内容"，跳过
