          var nMsg = npcMsgs[nm];
          if (
            isGroup &&
            !_yqIsAllowedGroupSender(nMsg.sender || "", _groupAllowSet)
          ) {
            continue;
          }
          var nKey =
            "npc|" +
            (nMsg.sender || "") +
            "|" +
            (nMsg.content || "") +
            "|" +
            (nMsg.time || "");
          if (!messageSet.has(nKey)) {
            messageSet.add(nKey);
            messages.push({
              isMine: false,
              sender: nMsg.sender || "未知",
              type: nMsg.type || "文字",
              content: nMsg.content || "",
              // [V10.12·2026-05-19] 直接显示消息自带的 MVU 时间（发出时存的当时主线时间）。
              //   缺失则显示空字符串——绝不用现实时间或当前 MVU 时间冒充。
              time: nMsg.timeStr || "",
