            messages.push({
              isMine: chatMsg.type === "user",
              sender:
                chatMsg.type === "user"
                  ? "我"
                  : chatMsg.sender || contactId || "对方",
              type: chatMsg.type === "system" ? "系统" : "文字",
              _isSystemTip: chatMsg.type === "system" || !!chatMsg._silentTip,
              content: chatMsg.content || "",
              // [V10.12·2026-05-19] 直接显示消息自带的 MVU 时间（发出时存的当时主线时间）。
              //   缺失则显示空字符串——绝不用现实时间或当前 MVU 时间冒充。
              time: (chatMsg.gameTime && chatMsg.gameTime.trim()) || "",
              _timestamp: chatMsg.time || 0,
              isImage: chatMsg.isImage || false,
              imageId: chatMsg.imageId || undefined,
              imageDesc: chatMsg.imageDesc || undefined,
              _formatFallback: !!chatMsg._formatFallback,
              _phoneSource: "chat_history",
              _phoneStoreKey: contactId,
              _phoneStoreIndex: ch,
            });
          }
        }
