    try {
      var gen = window.npcMsgGen;
      if (gen && typeof gen.getNpcMessages === "function") {
        var nk = isGroup ? "group_" + contactId : contactId;
        var arr = gen.getNpcMessages(nk);
        npcCount = Array.isArray(arr) ? arr.length : 0;
      }
    } catch (_e1) {}
    try {
      var sender = window.messageSender;
      if (sender && typeof sender.getChatHistory === "function") {
        var h = sender.getChatHistory(contactId);
        localCount = Array.isArray(h) ? h.length : 0;
      }
    } catch (_e2) {}
    var friendRev = Number(window._yqFriendUiDisplayRev || 0);
    return [
      String(contactId || ""),
      isGroup ? "g" : "p",
      String(chat.length),
      lastMsgSig,
      String(npcCount),
      String(localCount),
      String(friendRev),
    ].join("|");
  } catch (_e) {
    return "fallback|" + String(contactId || "");
  }
}

/**
 * 聊天面板打开时的轮询：签名不变则跳过重绘（供 openChatPanel / 重开手机共用）
 */
function tickChatPanelAutoRefresh() {
  try {
    window._yqPerfStats = window._yqPerfStats || {};
    window._yqPerfStats.chatAutoRefreshTicks =
      (window._yqPerfStats.chatAutoRefreshTicks || 0) + 1;
  } catch (_e0) {}
  var $mobileOverlay = $("#mobile-phone-overlay");
  if (!$mobileOverlay.hasClass("active")) return;
  if (typeof document !== "undefined" && document.hidden) return;
  var $chatPanel = $("#phone-chat-panel");
  if (!$chatPanel.hasClass("active")) return;
  var cid = window.currentChatContactId;
  var isGrp = window.currentChatIsGroup;
  if (cid === undefined || cid === null) return;
  var pollStamp = _getChatPollStamp(cid, isGrp);
  if (renderChatMessages._lastPollStamp === pollStamp) return;
  renderChatMessages._lastPollStamp = pollStamp;
  var pollMessages = extractMessagesForContact(cid, isGrp);
  var pollSignature = buildChatRenderSignature(pollMessages);
  if (renderChatMessages._lastPollSignature === pollSignature) return;
  renderChatMessages._lastPollSignature = pollSignature;
  renderChatMessages(cid, isGrp, {
    messages: pollMessages,
    signature: pollSignature,
    skipIfUnchanged: true,
  });
}
window.tickChatPanelAutoRefresh = tickChatPanelAutoRefresh;

/**
 * 打开聊天界面
 */
function openChatPanel(contactId, contactName, isGroup = false, members = "") {
  // 检查是否被拉黑
  if (!isGroup) {
    var blocked = getBlockedFriends();
    var _cand =
      (typeof window.yqFriendCanonicalFromFriendContactId === "function"
        ? window.yqFriendCanonicalFromFriendContactId(String(contactId))
        : "") || String(contactName || "");
    var _blkCanon =
      typeof window.yqFriendResolveCanonical === "function"
        ? window.yqFriendResolveCanonical(_cand)
        : _cand;
    if (
      blocked[_blkCanon] ||
      blocked[_cand] ||
      blocked[String(contactName || "")]
    ) {
      var _blkLabel =
        typeof window.yqFriendPrivateChatTitle === "function"
          ? window.yqFriendPrivateChatTitle(contactId, contactName)
          : String(contactName || "");
      yqToast("warning", "「" + _blkLabel + "」已被拉黑，无法发起聊天");
      return;
    }
  }

  // 保存当前聊天信息（用于恢复定时器）
  currentChatContactId = contactId != null ? String(contactId) : contactId;
  window.currentChatContactId = currentChatContactId;
  currentChatContactName = contactName;
  currentChatIsGroup = isGroup;
  window.currentChatIsGroup = currentChatIsGroup;

  // 清除该联系人的未读消息
  try {
    var gen = window.npcMsgGen;
    if (gen) {
      // 群聊的NPC消息和未读存储在 "group_" + id 下
      var unreadKey = isGroup ? "group_" + contactId : contactId;
      gen.clearUnread(unreadKey);
      gen.updateTotalUnreadBadge();
      // 刷新消息App图标角标
      updateMsgAppBadge();
    }
  } catch (e) {}

  // 设置当前聊天对象
  window.messageSender.setCurrentChat(contactId, contactName, isGroup);

  // 更新聊天标题（微信风格：主标题简洁，群聊附副标题）
  let title = isGroup
    ? String(contactName || "群聊")
    : `${
        typeof window.yqFriendPrivateChatTitle === "function"
          ? window.yqFriendPrivateChatTitle(contactId, contactName)
          : typeof getDisplayName === "function"
            ? getDisplayName(contactName)
            : contactName
      }`;

  //  如果是群聊，显示成员信息
  if (isGroup && members) {
    var displayMembers =
      typeof window.yqFriendFormatMembersLineForUi === "function"
        ? window.yqFriendFormatMembersLineForUi(members)
        : replaceUserMacro(members);
    const memberCount = displayMembers
      .split(/[、,，]/)
      .filter((m) => m.trim()).length;
    title += ` (${memberCount}人)`;
    $("#chat-title").html(`
            <div style="display:flex;align-items:center;justify-content:center;flex-direction:column;min-width:0;">
                <div style="font-size:17px;font-weight:600;color:#000;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${title}</div>
                <div style="font-size:11px;color:#8e8e93;margin-top:2px;max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${displayMembers}</div>
            </div>
        `);
  } else {
    $("#chat-title").text(title);
  }

  //  群聊删除按钮已移至消息面板左滑操作中
  const $rightActions = $("#chat-right-actions");
  // P2.4: 角色头像生成按钮（非群聊时显示）
  if (!isGroup) {
    $rightActions.html(
      '<button id="chat-gen-avatar-btn" data-contact="' +
        escapeHtml(contactName) +
        '" title="生成AI头像" style="background:none;border:none;color:#8b5cf6;font-size:16px;cursor:pointer;padding:4px 8px;"><i class="fas fa-palette"></i></button>',
    );
  } else {
    $rightActions.html(
      '<button id="chat-group-manage-btn" data-group-id="' +
        escapeHtml(String(contactId)) +
        '" title="管理群成员" style="background:none;border:none;color:#60a5fa;font-size:16px;cursor:pointer;padding:4px 8px;"><i class="fas fa-users-cog"></i></button>',
    );
  }

  // 渲染消息列表
  renderChatMessages._isFirstRender = true;
  renderChatMessages._savedScroll = undefined;
  renderChatMessages._lastPollSignature = undefined;
  renderChatMessages(contactId, isGroup);

  // 显示聊天面板
  $("#phone-chat-panel").addClass("active");

  // 清空输入框
  $("#chat-input").val("");

  // 直接绑定聊天发图按钮和头像生成按钮和群管理按钮（确保可靠响应）
  setTimeout(function () {
    // 群成员管理按钮
    $("#chat-group-manage-btn")
      .off("click.grpmgr")
      .on("click.grpmgr", function (e) {
        e.stopPropagation();
        var gid = String($(this).data("group-id") || "");
        if (!gid) return;
        _showGroupManageModal(gid);
      });
    $("#chat-camera-btn")
      .off("click.chatimg")
      .on("click.chatimg", function (e) {
        e.stopPropagation();
        e.preventDefault();
        phoneOpenSendImageDialog();
      });
    $("#chat-gen-avatar-btn")
      .off("click.chatavatar")
      .on("click.chatavatar", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var cn = $(this).data("contact");
        if (!cn) return;
        var check = isImageGenReady();
        if (!check.ready) {
          $(this).css("color", "#ef4444");
          var self = this;
          setTimeout(function () {
            $(self).css("color", "#8b5cf6");
          }, 2000);
          yqToast("warning", check.reason, "🎨 头像生成");
          return;
        }
        var $btn = $(this);
        $btn
          .prop("disabled", true)
          .html('<i class="fas fa-spinner fa-spin"></i>');
        phoneGenerateAvatar(cn).finally(function () {
          $btn.prop("disabled", false).html('<i class="fas fa-palette"></i>');
        });
      });
  }, 50);

  //  启动自动刷新（动态间隔：前台快、后台慢，且可见性实时生效）
  startChatAutoRefreshLoop();
}

/**
 * 群成员管理弹窗
 */
function _showGroupManageModal(groupId) {
