    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 10px;margin-bottom:4px;background:rgba(255,255,255,0.03);border-radius:6px">';
    html +=
      '<span style="font-size:13px;color:#e2e8f0">' +
      escapeHtml(displayName) +
