  html +=
    '<button type="button" id="grp-add-btn" class="yq-btn yq-btn--info-outline yq-btn--block" style="min-height:40px;font-size:13px;">➕ 添加成员</button>';
  html += "</div>";

  html +=
    '<div style="margin-top:8px"><button type="button" id="grp-manage-close" class="yq-btn yq-btn--ghost-dark yq-btn--block" style="min-height:38px;font-size:12px;">关闭</button></div>';
  html += "</div></div>";

  $("#grp-manage-modal").remove();
  $("body").append(html);

  // 关闭
  $("#grp-manage-close, #grp-manage-modal").on("click", function (e) {
    if (e.target === this) $("#grp-manage-modal").remove();
  });

  // 踢出
  $(".grp-kick-btn").on("click", function (e) {
    e.stopPropagation();
    var kickName = String($(this).data("name") || "");
    if (!kickName) return;
    var grps = getSavedGroups();
    var grp = grps[String(groupId)];
    if (!grp) return;
    var mList = (grp.members || "")
      .split(/[、,，]/)
      .map(function (s) {
        return s.trim();
      })
      .filter(Boolean);
    mList = mList.filter(function (m) {
      return m !== kickName;
    });
    grp.members = mList.join("、");
    grps[String(groupId)] = grp;
    setSavedGroups(grps);
    debounceSavePhoneMeta();
    // 插入群聊系统消息
    try {
      var gen = window.npcMsgGen;
      if (gen)
        gen.storeNpcMessage(
          "group_" + String(groupId),
          "系统消息",
          "「" + kickName + "」被移出了群聊",
          true,
        );
    } catch (e) {}
    yqToast("info", "已将「" + kickName + "」踢出群聊");
    $("#grp-manage-modal").remove();
    _refreshGroupTitle(groupId, grp);
    // 刷新聊天消息显示
    if (currentChatContactId === String(groupId))
      renderChatMessages(String(groupId), true);
  });

  // 添加成员
  $("#grp-add-btn").on("click", function (e) {
    e.stopPropagation();
    _showGroupAddModal(groupId);
  });
}

function _showGroupAddModal(groupId) {
  var groups = getSavedGroups();
  var g = groups[String(groupId)];
  if (!g) return;
  var currentMembers = (g.members || "")
    .split(/[、,，]/)
    .map(function (s) {
      return s.trim();
    })
    .filter(Boolean);

  // 获取所有已知好友
  var known = getKnownFriends();
  var candidates = Object.keys(known).filter(function (name) {
    return currentMembers.indexOf(name) < 0 && name !== "{{user}}";
  });

  var html =
    '<div id="grp-add-modal" style="position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:100000;display:flex;align-items:center;justify-content:center">';
  html +=
    '<div style="background:#1a1a2e;border:1px solid rgba(255,255,255,0.1);border-radius:12px;max-width:320px;width:85%;padding:16px;max-height:60vh;overflow-y:auto">';
  html +=
    '<div style="font-size:14px;font-weight:700;color:#e2e8f0;margin-bottom:10px">➕ 选择要添加的成员</div>';

  if (candidates.length === 0) {
    html +=
      '<div style="text-align:center;padding:20px;color:#666;font-size:12px">没有可添加的角色</div>';
  } else {
    for (var ci = 0; ci < candidates.length; ci++) {
      html +=
        '<button type="button" class="grp-add-pick" data-name="' +
        escapeHtml(candidates[ci]) +
        '" style="display:block;width:100%;text-align:left;padding:10px 12px;margin-bottom:4px;font-size:13px;color:#e2e8f0;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:6px;cursor:pointer">' +
        escapeHtml(candidates[ci]) +
        "</button>";
    }
  }

  html +=
    '<div style="margin-top:8px"><button type="button" id="grp-add-close" class="yq-btn yq-btn--ghost-dark yq-btn--block" style="min-height:38px;font-size:12px;">取消</button></div>';
  html += "</div></div>";

  $("#grp-add-modal").remove();
  $("body").append(html);

  $("#grp-add-close, #grp-add-modal").on("click", function (e) {
    if (e.target === this) $("#grp-add-modal").remove();
  });

  $(".grp-add-pick").on("click", function (e) {
    e.stopPropagation();
    var addName = $(this).data("name");
    if (!addName) return;
    addName = String(addName);
    var grps = getSavedGroups();
    var grp = grps[String(groupId)];
    if (!grp) return;
    var mList = (grp.members || "")
      .split(/[、,，]/)
      .map(function (s) {
        return s.trim();
      })
      .filter(Boolean);
    if (mList.indexOf(addName) >= 0) return; // 已在群中
    mList.push(addName);
    grp.members = mList.join("、");
    grps[String(groupId)] = grp;
    setSavedGroups(grps);
    debounceSavePhoneMeta();
    // 插入群聊系统消息
    try {
      var gen = window.npcMsgGen;
      if (gen)
        gen.storeNpcMessage(
          "group_" + String(groupId),
          "系统消息",
          "「" + addName + "」加入了群聊",
          true,
        );
    } catch (e) {}
    yqToast("success", "已将「" + addName + "」加入群聊");
    $("#grp-add-modal").remove();
    $("#grp-manage-modal").remove();
    // 刷新聊天标题
    _refreshGroupTitle(groupId, grp);
    // 刷新聊天消息显示
    if (currentChatContactId === String(groupId))
      renderChatMessages(String(groupId), true);
  });
}

function _refreshGroupTitle(groupId, grp) {
  var displayMembers =
    typeof window.yqFriendFormatMembersLineForUi === "function"
      ? window.yqFriendFormatMembersLineForUi(grp.members || "")
      : replaceUserMacro(grp.members || "");
  var memberCount = displayMembers.split(/[、,，]/).filter(function (m) {
    return m.trim();
  }).length;
  var _esc =
    typeof escapeHtml === "function"
      ? escapeHtml
      : function (s) {
          return String(s || "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
