/**
 * 渲染聊天消息（微信风格）
 */
function renderChatMessages(contactId, isGroup = false, options = {}) {
  var messages =
    options.messages || extractMessagesForContact(contactId, isGroup);
  if (isGroup && messages && messages.length > 0) {
    var _renderGroupAllow = _yqBuildGroupMemberAllowSet(contactId, []);
    messages = messages.filter(function (msg) {
      return (
        msg.isMine ||
        msg._formatFallback ||
        _yqIsAllowedGroupSender(msg.sender || "", _renderGroupAllow)
      );
    });
  }
  var chatKey = (isGroup ? "group:" : "dm:") + String(contactId);
  var signature = options.signature || buildChatRenderSignature(messages);
  // [V10.1 FIX] 每次渲染前清理超时的 pending 状态，防止按钮永久 disabled
  if (typeof _cleanStalePendingEntries === "function")
    _cleanStalePendingEntries();
  var _pendingStore = window._phoneManualImagePending || {};
  if (!renderChatMessages._lastRenderedSignatureByChat) {
    renderChatMessages._lastRenderedSignatureByChat = {};
  }
  if (
    options.skipIfUnchanged &&
    renderChatMessages._lastRenderedSignatureByChat[chatKey] === signature
  ) {
    return;
  }
  var $container = $("#chat-messages");

  // 保存当前滚动位置（在html被替换前）
  var prevScrollTop = 0;
  var wasNearBottom = true;
  if ($container[0]) {
    prevScrollTop = $container[0].scrollTop || 0;
    var prevMaxScrollTop = Math.max(
      0,
      $container[0].scrollHeight - $container[0].clientHeight,
    );
    var distanceFromBottom = prevMaxScrollTop - prevScrollTop;
    wasNearBottom = distanceFromBottom <= 40;
    renderChatMessages._savedScroll = prevScrollTop;
  }

  if (messages.length === 0) {
    $container.html(
      '<div style="text-align:center;padding:40px 20px;color:#b2b2b2;font-size:13px;">暂无消息</div>',
    );
    return;
  }

  var html = "";
  for (var mi = 0; mi < messages.length; mi++) {
    var msg = messages[mi];

    // [V11.2·2026-05-19] 系统消息（silent tip）独立渲染样式：居中淡灰条
    if (msg._isSystemTip) {
      html +=
        '<div style="text-align:center;padding:8px 12px;margin:6px 0;color:#9ca3af;font-size:11px;line-height:1.4;background:transparent;">' +
        '<span style="background:rgba(156,163,175,0.12);padding:4px 10px;border-radius:10px;display:inline-block;max-width:80%;">💤 ' +
        escapeHtml(msg.content || "对方暂时未查看消息") +
        "</span></div>";
      continue;
    }

    var isMe = msg.isMine;
    var canDeletePhoneMsg =
      msg._phoneSource === "chat_history" ||
      msg._phoneSource === "npc_messages";
    var canRerollPhoneMsg =
      canDeletePhoneMsg &&
      msg._phoneSource === "chat_history" &&
      isMe &&
      !msg.isImage;
    var actionHtml = "";
    if (canDeletePhoneMsg || canRerollPhoneMsg) {
      actionHtml +=
        '<div style="display:flex;gap:4px;margin-top:3px;align-items:center;' +
        (isMe ? "justify-content:flex-end" : "justify-content:flex-start") +
        '">';
      if (canRerollPhoneMsg) {
        actionHtml +=
          '<button type="button" class="chat-reroll-user-msg-btn" data-chat-source="' +
          escapeHtml(msg._phoneSource || "") +
          '" data-store-key="' +
          escapeHtml(msg._phoneStoreKey || "") +
          '" data-store-index="' +
          Number(msg._phoneStoreIndex || 0) +
          '" title="删除这条及之后的手机回复，并重新生成对方回复" style="border:none;background:transparent;color:#8b5cf6;font-size:10px;cursor:pointer;padding:1px 4px;">重Roll</button>';
      }
      if (canDeletePhoneMsg) {
        actionHtml +=
          '<button type="button" class="chat-delete-msg-btn" data-chat-source="' +
          escapeHtml(msg._phoneSource || "") +
          '" data-store-key="' +
          escapeHtml(msg._phoneStoreKey || "") +
          '" data-store-index="' +
          Number(msg._phoneStoreIndex || 0) +
          '" title="仅删除手机APP内这条消息，不删除SillyTavern主聊天楼层" style="border:none;background:transparent;color:#9ca3af;font-size:10px;cursor:pointer;padding:1px 4px;">删除</button>';
      }
      actionHtml += "</div>";
    }

    // 获取发送者头像
    var avatarHtml = "";
    if (!isMe) {
      var senderName = msg.sender || contactId;
      var initial = senderName ? String(senderName).charAt(0) : "?";
      var avatarUrl = getCharacterAvatar(senderName);
      if (avatarUrl) {
        avatarHtml =
          '<img src="' +
          avatarUrl +
          '" style="width:40px;height:40px;border-radius:6px;object-fit:cover;flex-shrink:0;" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'">' +
