  }

  $container.html(html);
  renderChatMessages._lastRenderedSignatureByChat[chatKey] = signature;

  // 高频轮询场景下，绑定做轻节流，减少重复委托绑定成本
  try {
    var _bindNow = Date.now();
    if (
      !renderChatMessages._lastBindAt ||
      _bindNow - renderChatMessages._lastBindAt > 400
    ) {
      bindPanelButtons();
      renderChatMessages._lastBindAt = _bindNow;
    }
  } catch (_bindErr) {
    bindPanelButtons();
  }

  // 智能滚动：保留用户的滚动位置，只有首次打开时才滚到底部
  setTimeout(function () {
    if ($container[0]) {
      var el = $container[0];
      var shouldStickToBottom =
        renderChatMessages._isFirstRender ||
        !!options.forceScrollBottom ||
        wasNearBottom;
      if (shouldStickToBottom) {
        el.scrollTop = el.scrollHeight;
        renderChatMessages._isFirstRender = false;
      } else {
        // 恢复之前保存的滚动位置（允许为0，避免顶部被“拉回去”）
        var restoreTop =
          typeof renderChatMessages._savedScroll === "number"
            ? renderChatMessages._savedScroll
            : 0;
        var maxScrollTop = Math.max(0, el.scrollHeight - el.clientHeight);
        el.scrollTop = Math.max(0, Math.min(restoreTop, maxScrollTop));
      }
    }
  }, 50);
}
