// ==================== 图片处理功能 ====================
/**
 * 处理消息内容中的图片标签
 * @param {string} content - 原始消息内容
 * @returns {string} - 处理后的HTML内容
 */
function processMessageImages(content) {
  if (!content) return "";

  // 使用正则替换 <pic>...</pic> 为图片HTML
  const imageRegex = /<pic>(.*?)<\/pic>/gi;

  const processedContent = content.replace(imageRegex, (match, imagePath) => {
    const imageUrl = imagePath.trim();
    // 使用data属性存储URL，通过事件委托处理点击
    return `<div class="message-image-container" style="margin: 8px 0;">
            <img src="${imageUrl}"
                 class="message-image clickable-image"
                 data-image-url="${imageUrl}"
                 style="max-width: 200px; max-height: 200px; border-radius: 8px; cursor: pointer; display: block;"
                 onerror="this.style.display='none'; this.insertAdjacentHTML('afterend', '<div class=\'image-error\' style=\'color:#999;font-size:12px;padding:8px;\'>📷 图片加载失败</div>');" />
        </div>`;
  });

  return processedContent;
}

/**
 * 查看完整图片（大图模式），支持左右翻页
 * @param {string} imageUrl - 图片URL
 * @param {string|null} imageId - 图片ID（用于壁纸/删除）
 * @param {Array|null} imageList - 图片列表 [{url, id}]，传入时支持翻页
 * @param {number} currentIndex - 当前图片在列表中的索引
 */
function viewFullImage(imageUrl, imageId, imageList, currentIndex) {
  // 移除已存在的查看器
  $("#image-viewer").remove();

  var _list = imageList || null;
  var _idx = typeof currentIndex === "number" ? currentIndex : -1;

  // 创建全屏图片查看器
  const viewer = $("<div>", {
    id: "image-viewer",
    css: {
      position: "fixed",
      top: 0,
      left: 0,
      width: "100%",
      height: "100%",
      backgroundColor: "rgba(0, 0, 0, 0.9)",
      zIndex: 999999,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      flexDirection: "column",
    },
  });

  // 顶部按钮栏
  var btnBar = $(
    '<div style="position:absolute;top:20px;right:20px;display:flex;gap:8px;z-index:10;"></div>',
  );

  // 页码指示器
  var pageIndicator = null;
  if (_list && _list.length > 1) {
    pageIndicator = $(
      '<div style="position:absolute;top:24px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,0.7);font-size:13px;z-index:10;"></div>',
    );
    pageIndicator.text(_idx + 1 + " / " + _list.length);
  }

  // 设为壁纸按钮（仅当有imageId时显示）
  if (imageId) {
    var wallpaperBtn = $("<button>", {
      type: "button",
      class: "yq-viewer-btn yq-viewer-btn--violet",
      html: "🖼 设为壁纸",
    }).on("click", function (e) {
      e.stopPropagation();
      var curUrl =
        $("#image-viewer img.viewer-main-img").attr("src") || imageUrl;
      if (typeof setWallpaper === "function") {
        setWallpaper(curUrl);
      } else {
        try {
          localStorage.setItem("moshen-phone-wallpaper", curUrl);
        } catch (ex) {}
        yqToast("success", "已设为壁纸");
      }
    });
    btnBar.append(wallpaperBtn);

    // 删除按钮
    var deleteBtn = $("<button>", {
      type: "button",
      class: "yq-viewer-btn yq-viewer-btn--danger",
      html: "🗑 删除",
    }).on("click", function (e) {
      e.stopPropagation();
      var curId = $("#image-viewer").data("current-id") || imageId;
      if (!curId) return;
      if (!confirm("确定删除这张图片？")) return;
      var entry = window.phoneImageStore
        ? window.phoneImageStore.getEntry(curId)
        : null;
      if (window.phoneImageStore) window.phoneImageStore.remove(curId);
      if (entry && typeof _cleanImageRefFromSource === "function") {
        try {
          _cleanImageRefFromSource(curId, entry);
        } catch (e2) {}
      }
      // 从列表中移除并显示下一张，或关闭
      if (_list && _list.length > 1) {
        for (var ri = _list.length - 1; ri >= 0; ri--) {
          if (_list[ri].id === curId) {
            _list.splice(ri, 1);
            break;
          }
        }
        if (_list.length === 0) {
          $("#image-viewer").remove();
        } else {
          var newIdx = _idx >= _list.length ? _list.length - 1 : _idx;
          $("#image-viewer").remove();
          viewFullImage(_list[newIdx].url, _list[newIdx].id, _list, newIdx);
        }
      } else {
        $("#image-viewer").remove();
      }
      yqToast("success", "已删除");
      if (typeof currentPanel !== "undefined" && currentPanel === "gallery") {
        $("#phone-app-body").html(generateGalleryPanel());
        if (typeof bindPanelButtons === "function") bindPanelButtons();
      }
    });
    btnBar.append(deleteBtn);
  }

  // 保存到本地按钮（所有图片都可保存）
  var saveBtn = $("<button>", {
    type: "button",
    class: "yq-viewer-btn yq-viewer-btn--success",
    html: "💾 保存",
  }).on("click", function (e) {
    e.stopPropagation();
    var curUrl = $("#image-viewer img.viewer-main-img").attr("src") || imageUrl;
    if (!curUrl) return;
    try {
      var a = document.createElement("a");
      a.href = curUrl;
      a.download = "phone_image_" + Date.now() + ".png";
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      yqToast("success", "已开始下载");
    } catch (ex) {
      // fallback: 新窗口打开
      window.open(curUrl, "_blank");
    }
  });
  btnBar.append(saveBtn);

  // 关闭按钮
  var closeBtn = $("<button>", {
    type: "button",
    class: "yq-viewer-btn yq-viewer-btn--ghost",
    text: "✕ 关闭",
  }).on("click", function () {
    $("#image-viewer").remove();
  });
  btnBar.append(closeBtn);

  // 翻页函数
  function navigateTo(newIdx) {
    if (!_list || newIdx < 0 || newIdx >= _list.length) return;
    $("#image-viewer").remove();
    viewFullImage(_list[newIdx].url, _list[newIdx].id, _list, newIdx);
  }

  // 左箭头
  if (_list && _list.length > 1 && _idx > 0) {
    var leftArrow = $(
      '<button type="button" class="yq-viewer-nav yq-viewer-nav--left">‹</button>',
    );
    leftArrow.on("click", function (e) {
      e.stopPropagation();
      navigateTo(_idx - 1);
    });
    viewer.append(leftArrow);
  }
  // 右箭头
  if (_list && _list.length > 1 && _idx < _list.length - 1) {
    var rightArrow = $(
      '<button type="button" class="yq-viewer-nav yq-viewer-nav--right">›</button>',
    );
    rightArrow.on("click", function (e) {
      e.stopPropagation();
      navigateTo(_idx + 1);
    });
    viewer.append(rightArrow);
  }

  // 图片元素
  const img = $("<img>", {
    src: imageUrl,
    class: "viewer-main-img",
    css: {
      maxWidth: "90%",
      maxHeight: "90%",
      objectFit: "contain",
    },
  });

  viewer.append(btnBar);
  if (pageIndicator) viewer.append(pageIndicator);
  viewer.append(img);
  viewer.data("current-id", imageId);

  // 点击背景关闭
  viewer.on("click", function (e) {
    if (e.target === this) {
      $(this).remove();
    }
  });

  // 键盘左右翻页
  if (_list && _list.length > 1) {
    $(document)
      .off("keydown.imageviewer")
      .on("keydown.imageviewer", function (e) {
        if (!$("#image-viewer").length) {
          $(document).off("keydown.imageviewer");
          return;
        }
        if (e.key === "ArrowLeft" && _idx > 0) navigateTo(_idx - 1);
        else if (e.key === "ArrowRight" && _idx < _list.length - 1)
          navigateTo(_idx + 1);
        else if (e.key === "Escape") {
          $("#image-viewer").remove();
          $(document).off("keydown.imageviewer");
        }
      });
  }

  // 触摸滑动翻页
  if (_list && _list.length > 1) {
    var touchStartX = 0;
    viewer[0].addEventListener(
      "touchstart",
      function (e) {
        touchStartX = e.touches[0].clientX;
      },
      { passive: true },
    );
    viewer[0].addEventListener(
      "touchend",
      function (e) {
        var dx = e.changedTouches[0].clientX - touchStartX;
        if (Math.abs(dx) > 50) {
          if (dx > 0 && _idx > 0) navigateTo(_idx - 1);
          else if (dx < 0 && _idx < _list.length - 1) navigateTo(_idx + 1);
        }
      },
      { passive: true },
    );
  }

  $("body").append(viewer);
}

/**
 * 发送聊天消息
 */
async function sendChatMessage() {
  const $input = $("#chat-input");
  const $sendBtn = $("#chat-send-btn");
  const $sendIcon = $sendBtn.find("i");
  const message = $input.val().trim();

  if (!message) return;

  // [V6.5.1 · 信息通道修复 · Fix #5] 失联/丧尸/永久被俘 NPC 发送前置 guard
  // 数据源：面板 _yqSyncNpcStatusToPhone 写入的 phoneMeta.yinqi_apoc_hidden_contacts
  // 规则：仅私聊做 guard；群聊不拦（群里多人共存，单个失联不阻止发送）
  if (!currentChatIsGroup) {
    try {
      var _cidRaw = String(currentChatContactId || "");
      var _cidClean = _cidRaw.replace(/^friend_/, "");
      var _apocMap = getPhoneMeta("yinqi_apoc_hidden_contacts", {}) || {};
      var _apocHit = _apocMap[_cidClean] || _apocMap[_cidRaw];
      if (_apocHit) {
        var _reason =
          (_apocHit.reason === "zombie" && "已丧尸化") ||
          (_apocHit.reason === "permanent_lost" && "永久失联") ||
          (_apocHit.reason === "hp_zero" && "已死亡") ||
          (_apocHit.reason === "apex_concubine" && "被 Ⅶ 级觉醒者带走") ||
          "已失联";
        if (typeof yqToast === "function") {
          yqToast("warning", "该联系人" + _reason + "，无法联系");
        } else if (typeof toastr !== "undefined") {
          toastr.warning("该联系人" + _reason + "，无法联系");
        }
        return;
      }
    } catch (_eApocGuard) {}
  }

  // 清空输入框
  $input.val("");

  try {
    //  传递按钮引用，让 MessageSender 控制按钮状态
    const success = await window.messageSender.sendMessage(message, {
      button: $sendBtn,
      icon: $sendIcon,
      input: $input,
    });

    if (success) {
      try {
        if (typeof window.yqCharAppendEvent === "function") {
          var _targetName =
            currentChatContactName ||
            String(currentChatContactId || "")
              .replace(/^friend_/, "")
              .replace(/^group_/, "");
          var _evtMsg = window.yqCharAppendEvent({
            charId: _targetName || "群聊",
            source: "chat",
            channel: currentChatIsGroup ? "group" : "chat",
            action: "player_message_sent",
            payload: {
              contactId: currentChatContactId || "",
              content: message,
            },
          });
          if (_evtMsg && typeof window.yqApplyLinkRulesByEvent === "function") {
            window.yqApplyLinkRulesByEvent(_evtMsg);
          }
        }
      } catch (_sendEvtErr) {}
      // [V3 网友渗透] 玩家私聊文字 +1 互动 + sharedLocation / hintedDesire 关键词探测
      if (!currentChatIsGroup && currentChatContactId) {
        try {
          var _v3CanMsg = "";
          if (
            typeof window.yqFriendCanonicalFromFriendContactId === "function"
          ) {
            _v3CanMsg =
              window.yqFriendCanonicalFromFriendContactId(currentChatContactId);
          }
          if (!_v3CanMsg)
            _v3CanMsg = String(currentChatContactName || "").trim();
          if (
            _v3CanMsg &&
            typeof window.yqFriendBumpInteraction === "function"
          ) {
            window.yqFriendBumpInteraction(_v3CanMsg, 1);
          }
          // [V3-B3] sharedLocation / hintedDesire 自动标记（仅 stranger_male 生效，由 yqMarkCloseProgressFlag 内部把关）
          if (
            _v3CanMsg &&
            typeof window.yqMarkCloseProgressFlag === "function"
          ) {
            try {
              var _v3MsgText = String(message || "");
              if (_v3MsgText) {
                // 位置暗示：玩家透露自己/女角色的具体居住或活动场所
                var _v3LocPat =
                  /(我(家|宿舍|房间|卧室|浴室)|她(家|宿舍|房间|卧室)|地址(发|给|是)|过来玩|来我这|床上等|刚(洗完|洗过)澡|正在洗澡|宿舍号|房间号)/;
                if (_v3LocPat.test(_v3MsgText)) {
                  window.yqMarkCloseProgressFlag(_v3CanMsg, "sharedLocation");
                }
                // 欲望暗示：明显的 NTL 话术（"今晚来/约不约/求帮拍/想看 + 女角色"等）
                var _v3DesPat =
                  /(好想[你他她TA]|今晚.{0,3}(来|约|过来)|约不约|求[你他她TA].{0,8}(帮|看|拍|偷|做)|忍不住.{0,5}(想|要|看)|湿了|硬了|想[操干上肏]|偷拍|内衣[照视]|裸照)/;
                if (_v3DesPat.test(_v3MsgText)) {
                  window.yqMarkCloseProgressFlag(_v3CanMsg, "hintedDesire");
                }
              }
            } catch (_v3FlagErr) {}
          }
        } catch (_v3MsgBumpErr) {}
      }
      // 立即刷新聊天界面，显示刚发送的消息
      if (currentChatContactId) {
        renderChatMessages._isFirstRender = true;
        renderChatMessages(currentChatContactId, currentChatIsGroup);
      }
    }
  } catch (error) {
    yqToast("error", "消息发送失败: " + (error.message || "请检查聊天API配置"));
  }
}

