/**
 * 执行玩家发图：生成tag → 生图 → 存为聊天消息
 */
async function phoneExecuteSendImage(description) {
  if (!description || !description.trim()) {
    yqToast("warning", "请输入图片描述");
    return;
  }

  var snapChatId = currentChatContactId;
  var snapChatName = currentChatContactName;
  if (!snapChatId) return;

  // 关闭弹窗
  $("#chat-send-image-overlay").remove();

  // 显示loading状态在聊天界面
  var loadingId = "img-loading-" + Date.now();
  var $msgs = $("#chat-messages");
  $msgs.append(
    '<div id="' +
      loadingId +
      '" style="display:flex;justify-content:flex-end;padding:4px 12px;">' +
      '<div style="background:linear-gradient(135deg,#f97316,#ea580c);color:white;padding:10px 16px;border-radius:12px;font-size:12px;display:flex;align-items:center;gap:8px;box-shadow:0 2px 8px rgba(234,88,12,0.35);">' +
      '<i class="fas fa-spinner fa-spin"></i> 正在生成图片...' +
      '<button type="button" class="cancel-img-gen yq-btn yq-btn--on-img-pill">取消</button>' +
      "</div></div>",
  );
  $msgs.scrollTop($msgs[0].scrollHeight);

  // 取消按钮
  var cancelled = false;
  $("#" + loadingId + " .cancel-img-gen").on("click", function () {
    cancelled = true;
    $("#" + loadingId).remove();
    yqToast("info", "已取消生图");
  });

  try {
    // 收集聊天上下文
    var chatContext = "";
    try {
      var allChat = getPhoneMetaBig("chat_history", {});
      var chatHist = allChat[snapChatId] || [];
      if (chatHist.length > 0) {
        var recent = chatHist.slice(-5);
        for (var i = 0; i < recent.length; i++) {
          var who =
            recent[i].type === "user" ? "我" : recent[i].sender || snapChatName;
          chatContext +=
            who + ": " + (recent[i].content || "").substring(0, 50) + "\n";
        }
      }
    } catch (e) {}

    if (cancelled) return;

    // 调用统一生图函数（带发送者，避免无 DNA 提示时画错人）
    var _playerNm = getPlayerName();
    var result = await window.phoneGenerateImage(
      "chat",
      typeof window.buildChatImageGenContext === "function"
        ? window.buildChatImageGenContext(
            description.trim(),
            _playerNm,
            snapChatId,
            chatContext,
          )
        : {
            description: description.trim(),
            chatContext: chatContext,
            time: new Date().toLocaleString(),
          },
    );

    // 移除loading
    $("#" + loadingId).remove();

    if (cancelled) return;

    if (!result || !result.success) {
      yqToast(
        "error",
        "图片生成失败: " + ((result && result.error) || "未知错误"),
      );
      return;
    }

    // 存储为玩家发出的图片消息
    // [V10.12·2026-05-19] gameTime 改为完整 MVU 时间，与 _message_sender 一致
    var _gt = "";
    try {
      _gt = _getGameTimeCompat() || "";
    } catch (e) {}

    var allChat = getPhoneMetaBig("chat_history", {});
    var h = allChat[snapChatId] || [];
    h.push({
      type: "user",
      content: "[玩家发送了一张图片：" + description.trim() + "]",
      time: Date.now(),
      gameTime: _gt,
      isImage: true,
      imageId: result.imageId,
      imageDesc: description.trim(),
    });
    if (h.length > 100) h = h.slice(-100);
    allChat[snapChatId] = h;
    setPhoneMetaBig("chat_history", allChat);
    try {
      if (typeof window.yqCharAppendEvent === "function") {
        var _imgTarget =
          snapChatName ||
          String(snapChatId || "")
            .replace(/^friend_/, "")
            .replace(/^group_/, "");
        var _imgEvt = window.yqCharAppendEvent({
          charId: _imgTarget || "群聊",
          source: "chat",
          channel: currentChatIsGroup ? "group" : "chat",
          action: "player_image_sent",
          payload: {
            contactId: snapChatId || "",
            content: description.trim(),
            imageId: result.imageId || "",
          },
        });
        if (_imgEvt && typeof window.yqApplyLinkRulesByEvent === "function") {
          window.yqApplyLinkRulesByEvent(_imgEvt);
        }
      }
    } catch (_imgEvtErr) {}

    // [V3 网友渗透] 玩家发图 +2 互动；若描述含女角色名 → sharedPhoto=true 推进 close 进度
    if (!currentChatIsGroup && snapChatId) {
      try {
        var _v3CanImg = "";
        if (typeof window.yqFriendCanonicalFromFriendContactId === "function") {
          _v3CanImg = window.yqFriendCanonicalFromFriendContactId(snapChatId);
        }
        if (!_v3CanImg) _v3CanImg = String(snapChatName || "").trim();
        if (_v3CanImg) {
          if (typeof window.yqFriendBumpInteraction === "function") {
            window.yqFriendBumpInteraction(_v3CanImg, 2);
          }
          var _v3ImgDesc = String(description || "").trim();
          if (
            _v3ImgDesc &&
            typeof window.yqMarkCloseProgressFlag === "function"
          ) {
            var _v3FemNames = ["林知意"];
            try {
              var _d =
                (typeof currentPhoneData !== "undefined" && currentPhoneData) ||
                {};
              var _fchars = _.get(_d, "女性角色", {}) || {};
              var _fkeys = Object.keys(_fchars);
              for (var _fi = 0; _fi < _fkeys.length; _fi++)
                _v3FemNames.push(_fkeys[_fi]);
            } catch (_v3FemErr) {}
            for (var _fi2 = 0; _fi2 < _v3FemNames.length; _fi2++) {
              if (
                _v3FemNames[_fi2] &&
                _v3ImgDesc.indexOf(_v3FemNames[_fi2]) >= 0
              ) {
                window.yqMarkCloseProgressFlag(_v3CanImg, "sharedPhoto");
                break;
              }
            }
            // [V3-B3] 图片描述含具体场所/居所词 → sharedLocation
            var _v3LocImgPat =
              /(宿舍|卧室|浴室|床上|教室|图书馆|食堂|更衣室|厕所|淋浴|寝室|私人空间)/;
            if (_v3LocImgPat.test(_v3ImgDesc)) {
              window.yqMarkCloseProgressFlag(_v3CanImg, "sharedLocation");
            }
          }
        }
      } catch (_v3ImgBumpErr) {}
    }

    // 刷新聊天界面
    if (currentChatContactId === snapChatId) {
      renderChatMessages._isFirstRender = true;
      renderChatMessages(currentChatContactId, currentChatIsGroup);
    }

    yqToast("success", "图片已发送");

    // 注入主AI上下文
    injectNpcSummaryToContext();

    // 触发AI自动回复（玩家发图后对方应该有反应）
    try {
      var chatAPI = window.phoneAPI.chat;
      if (chatAPI && chatAPI.isAvailable() && window.messageSender) {
        var sender = window.messageSender;
        // [V9.6 P2 hotfix·2026-05-10] snapIsGroup 未声明导致 ReferenceError
        //   原：triggerSource 拼接时使用 (snapIsGroup ? "group:" : "private:")
        //   根因：函数只快照了 snapChatId/snapChatName，漏了 currentChatIsGroup
        //         → 引用未声明变量抛 ReferenceError，被外层 catch (aiErr) 吞掉
        //         → 玩家发图后看不到任何错误、AI 回复静默失败
        //   修：补 snapIsGroup 快照，与 snapChatId/Name 对齐，并在 triggerSource 使用此快照
        var snapIsGroup = currentChatIsGroup;
        // 确保sender的当前聊天对象与发图时一致
        var prevId = sender.currentFriendId;
        var prevName = sender.currentFriendName;
        var prevGroup = sender.isGroup;
        sender.setCurrentChat(snapChatId, snapChatName, snapIsGroup);
        // 发送图片描述作为消息触发AI回复
        var imgMsg = "[玩家发送了一张图片：" + description.trim() + "]";
        var sys;
        var playerName = getPlayerName();
        if (snapIsGroup) {
          var gm = sender.getCurrentGroupMembers
            ? sender.getCurrentGroupMembers()
            : [];
          var membersText = gm.length > 0 ? gm.join("、") : "";
          sys =
            "（以下为最高优先级元指令，暂停故事演绎，你现在是微信群聊消息模拟器）\n" +
            "玩家「" +
            playerName +
            "」在群聊中发送了一张图片。\n" +
            "图片描述：" +
            description.trim() +
            "\n" +
            "请模拟群内角色对这张图片的反应。\n" +
            "【输出格式】[群聊消息|" +
            snapChatId +
            "|发送者名字|文字|消息内容]\n" +
            (membersText ? "群内角色有：" + membersText + "\n" : "") +
            "角色想回图片时，在消息内容中加 [发图:图片描述] 标记。\n" +
            "回复要像真实微信聊天，简短口语化。严禁输出非格式标签内容。";
        } else {
          // [V3.3] 注入聊天对象人设
          var _photoProfile = _getCharProfile(snapChatName);
          var _photoCtx = "";
          if (_photoProfile)
            _photoCtx +=
              "聊天对象「" + snapChatName + "」人设：" + _photoProfile + "\n";
          try {
            var _liveHint = _buildLivePersonaHintForPrivateChat(
              snapChatId,
              snapChatName,
            );
            if (_liveHint) _photoCtx += _liveHint;
            var _pd = currentPhoneData || {};
            var _pf = _.get(_pd, "女性角色." + snapChatName, null);
            if (_pf && typeof _pf === "object")
              _photoCtx +=
                snapChatName +
                "：好感" +
                (_pf.好感度 || 0) +
                "/堕落" +
                (_pf.攻略度 || 0) +
                "\n";
            var _pm = _.get(_pd, "男性角色." + snapChatName, null);
            if (_pm && typeof _pm === "object")
              _photoCtx += snapChatName + "：欲望" + (_pm.屈辱度 || 0) + "\n";
          } catch (_pe) {}
          sys =
            "（以下为最高优先级元指令，暂停故事演绎，你现在是微信私聊消息模拟器）\n" +
            "玩家「" +
            playerName +
            "」在私聊中发送了一张图片。\n" +
            "图片描述：" +
            description.trim() +
            "\n" +
            "请模拟「" +
            snapChatName +
            "」对这张图片的反应。\n" +
            (_photoCtx ? _photoCtx : "") +
            "【输出格式】[对方消息|" +
            snapChatName +
            "|" +
            snapChatId +
            "|文字|消息内容]\n" +
            "角色想回图片时，在消息内容中加 [发图:图片描述] 标记。\n" +
            "回复要像真实微信聊天，简短口语化。严禁输出非格式标签内容。";
        }
        var reply = await chatAPI.callChatAPI("", sys, {
          skipCustomPrompt: true,
          triggerSource:
            "phone_image_reply:" +
            (snapIsGroup ? "group:" : "private:") +
            snapChatId,
        });
        sender.storeAIReplyOnly(snapChatId, reply);
        // 恢复sender状态
        sender.setCurrentChat(prevId, prevName, prevGroup);
        // 判断用户是否仍在查看这个聊天
        var _imgChatOpen = $("#phone-chat-panel").hasClass("active");
        var _imgStillViewing =
          _imgChatOpen && currentChatContactId === snapChatId;
        if (_imgStillViewing) {
          renderChatMessages._isFirstRender = true;
          renderChatMessages(currentChatContactId, snapIsGroup);
        } else {
          try {
            var _imgGen = window.npcMsgGen;
            if (_imgGen) {
              // 群聊未读 key 必须带 group_ 前缀，与 badge 展示/清除侧一致
              var _imgUnreadKey = snapIsGroup
                ? "group_" + String(snapChatId).replace(/^group_/, "")
                : snapChatId;
              _imgGen.incrementUnread(_imgUnreadKey);
            }
          } catch (e) {}
        }
        injectNpcSummaryToContext();
      }
    } catch (aiErr) {
      console.warn("[玩家发图] AI回复生成失败:", aiErr);
    }
  } catch (e) {
    $("#" + loadingId).remove();
    yqToast("error", "发图失败: " + (e.message || ""));
    console.warn("[玩家发图] 失败:", e);
  }
}

// ==================== P2.4: 角色头像生成 ====================
/**
 * 为指定联系人生成AI头像
 * @param {string} contactName - 联系人名称
 */
async function phoneGenerateAvatar(contactName) {
  if (!contactName) return;
  var check = isImageGenReady();
  if (!check.ready) {
    yqToast("warning", check.reason);
    return;
  }

  yqToast("info", "正在生成「" + contactName + "」的头像...", "🎨", {
    timeOut: 3000,
  });

  try {
    var result = await window.phoneGenerateImage("avatar", {
      characterName: contactName,
      time: new Date().toLocaleString(),
    });

    if (!result || !result.success) {
      yqToast(
        "error",
        "头像生成失败: " + ((result && result.error) || "未知错误"),
      );
      return;
    }

    // 存储头像映射到chatMetadata
    var avatars = getPhoneMeta("chat_avatars", {});
    // [V6.1 FIX BUG-2·2026-04-22] 若生成的是变性后主角头像，同时存入性别后缀 key
    // 这样变回男性时能 fallback 回原男性头像，再次变女时能拿到生成过的女体头像
    try {
      if (typeof yqIsPlayerName === "function" && yqIsPlayerName(contactName)) {
        var _cUG =
          typeof yqGetUserGender === "function" ? yqGetUserGender() : "male";
        if (_cUG === "female") {
          avatars[contactName + "_female"] = result.imageId;
        } else if (_cUG === "futanari") {
          avatars[contactName + "_futanari"] = result.imageId;
        }
      }
    } catch (_eSX) {}
    avatars[contactName] = result.imageId;
    setPhoneMeta("chat_avatars", avatars);

    // 刷新聊天界面显示新头像
    if (currentChatContactId) {
      // 头像刷新不应影响用户浏览位置
      renderChatMessages._isFirstRender = false;
      renderChatMessages(currentChatContactId, currentChatIsGroup);
    }

    // 刷新联系人列表中的头像（导航栈中的消息面板 + 当前面板）
    _refreshContactListAvatars();

    yqToast("success", "「" + contactName + "」的头像已生成");
  } catch (e) {
    yqToast("error", "头像生成失败: " + (e.message || ""));
    console.warn("[头像生成] 失败:", e);
  }
}

/**
 * 批量为所有联系人生成AI头像（跳过已有头像的）
 */
async function phoneGenerateBatchAvatars() {
  var check = isImageGenReady();
  if (!check.ready) {
    yqToast("warning", check.reason, "🎨 批量头像");
    return;
  }

  var friends = buildFriendsList();
  var avatars = getPhoneMeta("chat_avatars", {});
  var pending = [];
  var names = Object.keys(friends);
  for (var i = 0; i < names.length; i++) {
    if (!avatars[names[i]]) pending.push(names[i]);
  }

  // 也为玩家（主角）生成头像
  var playerName = getPlayerName();
  if (
    playerName &&
    !avatars[playerName] &&
    pending.indexOf(playerName) === -1
  ) {
    pending.unshift(playerName); // 主角优先生成
  }

  if (pending.length === 0) {
    yqToast("info", "所有联系人都已有头像", "🎨");
    return;
  }

  yqToast("info", "开始批量生成 " + pending.length + " 个头像...", "🎨", {
    timeOut: 5000,
  });

  var success = 0,
    fail = 0;
  for (var j = 0; j < pending.length; j++) {
    try {
      // 为没有外观缓存的剧情角色先生成缓存（默认角色已有，跳过）
      var pca = window.PhoneCharacterAppearance;
      if (pca && pca.isEnabled() && pca.needsGeneration(pending[j])) {
        yqToast("info", "🎭 正在为「" + pending[j] + "」生成外观缓存...", "", {
          timeOut: 3000,
        });
        await pca.generateAndCache(pending[j], {});
      }
      await phoneGenerateAvatar(pending[j]);
      success++;
    } catch (e) {
      fail++;
      console.warn("[批量头像] " + pending[j] + " 失败:", e);
    }
  }

  yqToast(
    "success",
    "批量头像完成：成功 " +
      success +
      " 个" +
      (fail > 0 ? "，失败 " + fail + " 个" : ""),
    "🎨",
  );

  // 批量完成后刷新联系人列表
  _refreshContactListAvatars();
}

