// ==================== 辅助函数：从聊天记录中提取信息 ====================
/**
 * 从SillyTavern聊天记录中提取好友信息
 */
function extractFriendsFromChat() {
  const friends = new Map();
  // [V10.12·2026-05-19] 时间锚点必须是 MVU——绝不用现实时间冒充
  //   MVU 不可用时显示空字符串，不冒用现实时间
  var _efDisplayTime = "";
  try {
    _efDisplayTime = _getGameTimeCompat() || "";
  } catch (e) {}

  try {
    //  尝试获取 SillyTavern 的聊天消息（支持 iframe）
    let messages = [];
    const targetWindow = window.parent || window;

    if (
      targetWindow.SillyTavern &&
      typeof targetWindow.SillyTavern.getContext === "function"
    ) {
      const context = targetWindow.SillyTavern.getContext();
      messages = context.chat || [];
    } else {
      return friends;
    }

    messages.forEach((msg) => {
      if (!msg.mes) return;
      var text = msg.mes;
      // 清理EJS模板标签，防止脚本内容干扰好友信息提取
      text = text.replace(/<%[\s\S]*?%>/g, "");
      text = text.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, "");

      // 提取好友: [好友id|名字|号码]
      const friendRegex = /\[好友id\|([^|]+)\|(\d+)\]/g;
      let match;
      while ((match = friendRegex.exec(text)) !== null) {
        const name = match[1];
        const id = match[2];
        if (!friends.has(id)) {
          friends.set(id, {
            name,
            id,
            isGroup: false,
            lastMessage: "",
            time: _efDisplayTime,
          });
        }
      }
    });
  } catch (error) {}

  return friends;
}

/**
 * 从SillyTavern聊天记录中提取群聊信息
 * 参考 mobile-master/app/friend-renderer.js 的实现
 * 支持从群聊定义和群聊消息中提取
 */
function extractGroupsFromChat() {
  const groupsMap = new Map();

  try {
    //  尝试获取 SillyTavern 的聊天消息（支持 iframe）
    let messages = [];
    const targetWindow = window.parent || window;

    if (
      targetWindow.SillyTavern &&
      typeof targetWindow.SillyTavern.getContext === "function"
    ) {
      const context = targetWindow.SillyTavern.getContext();
      messages = context.chat || [];
    } else {
      return groupsMap;
    }

    // 定义正则表达式
    const groupPattern = /\[群聊\|([^|]+)\|([^|]+)\|([^\]]+)\]/g; // [群聊|群名|群号|成员]
    async function createGroup() {
      var groupName = $("#group-name-input").val().trim();
      var groupId = $("#group-id-input").val().trim();
      var $checkboxes = $(".friend-checkbox:checked");

      if (!groupName) {
        yqToast("error", "请输入群聊名称");
        return;
      }
      if (!groupId || !/^\d+$/.test(groupId)) {
        yqToast("error", "请输入有效的群聊ID（纯数字）");
        return;
      }
      if ($checkboxes.length === 0) {
        yqToast("error", "请至少选择一个群成员");
        return;
      }

      var members = ["我"];
      $checkboxes.each(function () {
        var $item = $(this).closest(".friend-selection-item");
        var friendName = $item.data("friend-name");
        members.push(friendName);
      });

      var membersStr = members.join("、");

      try {
        /* 保存到chatMetadata */
        var groups = getSavedGroups();
        groups[groupId] = {
          name: groupName,
          members: membersStr,
          isDefault: false,
        };
        setSavedGroups(groups);

        yqToast("success", '群聊 "' + groupName + '" 创建成功！');

        setTimeout(function () {
          closeAppPanel();
          if (currentPhoneData) {
            var content = generateMessagesPanel(currentPhoneData);
            $("#phone-app-body").html(content);
          }
        }, 500);
      } catch (error) {
        yqToast("error", "创建群聊失败: " + error.message);
      }
    } // [创建群聊|群号|群名|成员]
    const groupMessagePattern =
      /\[群聊消息\|([^|]+)\|([^|]+)\|([^|]+)\|([^\]]+)\]/g; // [群聊消息|群ID|发送者|类型|内容]
    const myGroupMessagePattern =
      /\[我方群聊消息\|我\|([^|]+)\|([^|]+)\|([^\]]+)\]/g; // [我方群聊消息|我|群ID|类型|内容]

    messages.forEach((msg, index) => {
      if (!msg.mes) return;
      let text = msg.mes;

      // 清理EJS模板标签和变量更新块，防止脚本内容干扰消息解析
      text = text.replace(/<%[\s\S]*?%>/g, "");
      text = text.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, "");
      text = text.replace(/<ai_instruction>[\s\S]*?<\/ai_instruction>/g, "");
      text = text.replace(/<StatusPlaceHolderImpl\s*\/?>/g, "");

      //  清理提示词模板：从消息文本中删除模板部分，保留真实内容
      text = text.replace(
        /群聊消息响应格式要求[\s\S]*?可以有多个角色回复，每个角色一条消息/g,
        "",
      );
      text = text.replace(/私聊消息响应格式要求[\s\S]*?可以回复多条消息/g, "");
      text = text.replace(
        /\[群聊消息\|群号\|发送者名字\|消息类型\|消息内容\]/g,
        "",
      );
      text = text.replace(
        /\[对方消息\|角色名字\|号码\|消息类型\|消息内容\]/g,
        "",
      );
      text = text.replace(/\[我方消息\|我\|号码\|消息类型\|消息内容\]/g, "");
      text = text.replace(/\[群聊\|群名\|群号\|成员列表\]/g, "");
      text = text.replace(/\[创建群聊\|群号\|群名\|成员列表\]/g, "");

      // 如果清理后的消息为空，跳过
      if (!text.trim()) return;

      // 如果消息包含群聊相关内容，记录日志
      // if (text.includes('[群聊') || text.includes('[创建群聊')) {
      // }

      // 1. 提取群聊定义格式: [群聊|群名|群号|成员]
      let match;
      groupPattern.lastIndex = 0; //  重置正则索引
      while ((match = groupPattern.exec(text)) !== null) {
        const groupName = match[1];
        const groupId = match[2];
        const groupMembers = match[3];
        const groupKey = `group_${groupId}`; // 使用群ID作为唯一标识

        if (!groupsMap.has(groupKey)) {
          groupsMap.set(groupKey, {
            name: groupName,
            id: groupId,
            isGroup: true,
            members: groupMembers,
            memberCount: groupMembers.split(/[、,，]/).filter((m) => m.trim())
              .length,
            messageIndex: index,
            lastMessage: "",
            time: msg.send_date || Date.now(),
          });
        }
      }

      // 2. 提取创建群聊格式: [创建群聊|群号|群名|成员]
      createGroupPattern.lastIndex = 0;
      while ((match = createGroupPattern.exec(text)) !== null) {
        const groupId = match[1];
        const groupName = match[2];
        const groupMembers = match[3];
        const groupKey = `group_${groupId}`;

        if (!groupsMap.has(groupKey)) {
          groupsMap.set(groupKey, {
            name: groupName,
            id: groupId,
            isGroup: true,
            members: groupMembers,
            memberCount: groupMembers.split(/[、,，]/).filter((m) => m.trim())
              .length,
            messageIndex: index,
            lastMessage: "",
            time: msg.send_date || Date.now(),
          });
        }
      }

      // 3. 从群聊消息中提取: [群聊消息|群ID|发送者|类型|内容]
      groupMessagePattern.lastIndex = 0;
      while ((match = groupMessagePattern.exec(text)) !== null) {
        const groupId = match[1];
        const senderName = match[2];
        const messageType = match[3];
        const messageContent = match[4];
        const groupKey = `group_${groupId}`;

        if (!groupsMap.has(groupKey)) {
          // 如果群聊不存在，创建一个基于消息的群聊记录
          groupsMap.set(groupKey, {
            name: `群聊${groupId}`,
            id: groupId,
            isGroup: true,
            members: senderName,
            memberCount: 1,
            messageIndex: index,
            lastMessage: messageContent.substring(0, 20),
            time: msg.send_date || Date.now(),
          });
        } else {
          // 如果已存在，更新成员列表和最新消息索引
          const existingGroup = groupsMap.get(groupKey);
          if (
            existingGroup.members &&
            !existingGroup.members.includes(senderName)
          ) {
            existingGroup.members += `、${senderName}`;
            existingGroup.memberCount = existingGroup.members
              .split(/[、,，]/)
              .filter((m) => m.trim()).length;
          }
          if (existingGroup.messageIndex < index) {
            existingGroup.messageIndex = index;
            existingGroup.lastMessage = messageContent.substring(0, 20);
            existingGroup.time = msg.send_date || Date.now();
          }
        }
      }

      // 4. 从我方群聊消息中提取: [我方群聊消息|我|群ID|类型|内容]
      myGroupMessagePattern.lastIndex = 0;
      while ((match = myGroupMessagePattern.exec(text)) !== null) {
        const groupId = match[1];
        const messageType = match[2];
        const messageContent = match[3];
        const groupKey = `group_${groupId}`;

        if (!groupsMap.has(groupKey)) {
          // 如果群聊不存在，创建一个基于消息的群聊记录
          groupsMap.set(groupKey, {
            name: `群聊${groupId}`,
            id: groupId,
            isGroup: true,
            members: "我",
            memberCount: 1,
            messageIndex: index,
            lastMessage: messageContent.substring(0, 20),
            time: msg.send_date || Date.now(),
          });
        } else {
          // 如果已存在，更新最新消息索引
          const existingGroup = groupsMap.get(groupKey);
          if (!existingGroup.members.includes("我")) {
            existingGroup.members += "、我";
            existingGroup.memberCount = existingGroup.members
              .split(/[、,，]/)
              .filter((m) => m.trim()).length;
          }
          if (existingGroup.messageIndex < index) {
            existingGroup.messageIndex = index;
            existingGroup.lastMessage = messageContent.substring(0, 20);
            existingGroup.time = msg.send_date || Date.now();
          }
        }
      }
    });
  } catch (error) {
    void error;
  }

  return groupsMap;
}

