/**
 * 格式化监控画面描述
 * 将【时间段】和〖房间/角度〗标记转换为带颜色的HTML
 * @param {string} text - 原始监控描述文本
 * @returns {string} - 格式化后的HTML
 */
function formatSurveillanceDesc(text) {
  if (!text) return "";
  var escaped = escapeHtml(text);
  // 高亮【时间段】标记 - 亮黄色
  escaped = escaped.replace(
    /【([^】]+)】/g,
    '<div style="margin-top:10px;margin-bottom:4px;padding:3px 8px;background:#92400e;color:#fbbf24;border-radius:4px;font-weight:bold;font-size:12px;display:inline-block;">🕐 $1</div><br>',
  );
  // 高亮〖房间/角度〗标记 - 亮青色
  escaped = escaped.replace(
    /〖([^〗]+)〗/g,
    '<div style="margin-top:8px;margin-bottom:2px;padding:2px 6px;background:#164e63;color:#22d3ee;border-radius:3px;font-weight:600;font-size:11px;display:inline-block;">📹 $1</div><br>',
  );
  // 空行转为段落间距
  escaped = escaped.replace(/\n\s*\n/g, '<div style="margin-top:8px;"></div>');
  // 普通换行
  escaped = escaped.replace(/\n/g, "<br>");
  return escaped;
}

