function generateWorldPanel(data) {
  var d = data || {};
  var world = _.get(d, "世界", {});
  var html = "";

  // 当前循环信息
  var cycleNum = _.get(world, "当前循环次数", 1);
  var phase = _.get(world, "当前事件阶段", 1);
  html +=
    '<div class="list-item" style="background:linear-gradient(135deg,#ecfdf5,#d1fae5);">';
  html +=
    '<div class="list-item-header"><span class="list-item-name">🔄 第 ' +
    cycleNum +
    " 次循环</span></div>";
  // 循环描述（API生成，按 ST chatId 隔离缓存在 localStorage）
  var _worldCacheScope = "global";
  try {
    var _tw = window.parent || window;
    _worldCacheScope = String(
      (_tw.SillyTavern &&
        _tw.SillyTavern.getCurrentChatId &&
        _tw.SillyTavern.getCurrentChatId()) ||
        (_tw.SillyTavern &&
          _tw.SillyTavern.getContext &&
          _tw.SillyTavern.getContext().chatId) ||
        "global",
    );
  } catch (_scopeErr) {}
  var cycleCacheKey = "yinqi-cycle-desc-" + _worldCacheScope + "-" + cycleNum;
  var cycleDesc = "";
  try {
    cycleDesc =
      localStorage.getItem(cycleCacheKey) ||
      localStorage.getItem("yinqi-cycle-desc-" + cycleNum) ||
      "";
  } catch (e) {}
  html +=
    '<div style="margin-top:6px;font-size:12px;color:#374151;line-height:1.5;">';
