    html += escapeHtml(cycleDesc);
  } else {
    html +=
      '<span style="color:#9ca3af;font-style:italic;">循环概要将在对话中自动生成</span>';
  }
  html += "</div>";
  html += "</div>";

  // 当前阶段信息
  html +=
    '<div class="list-item" style="background:linear-gradient(135deg,#eff6ff,#dbeafe);">';
  html +=
    '<div class="list-item-header"><span class="list-item-name">📍 当前阶段 ' +
    phase +
    "</span></div>";
  // 阶段描述
  var phaseCacheKey =
    "yinqi-phase-desc-" + _worldCacheScope + "-" + cycleNum + "-" + phase;
  var phaseDesc = "";
  try {
    phaseDesc =
      localStorage.getItem(phaseCacheKey) ||
      localStorage.getItem("yinqi-phase-desc-" + cycleNum + "-" + phase) ||
      "";
  } catch (e) {}
  html +=
    '<div style="margin-top:6px;font-size:12px;color:#374151;line-height:1.5;">';
  if (phaseDesc) {
    html += escapeHtml(phaseDesc);
  } else {
    html +=
      '<span style="color:#9ca3af;font-style:italic;">阶段描述将在对话中自动生成</span>';
  }
  html += "</div>";
  // 下一阶段提示
  var nextPhaseCacheKey =
    "yinqi-next-phase-hint-" + _worldCacheScope + "-" + cycleNum + "-" + phase;
  var nextPhaseHint = "";
  try {
    nextPhaseHint =
      localStorage.getItem(nextPhaseCacheKey) ||
      localStorage.getItem("yinqi-next-phase-hint-" + cycleNum + "-" + phase) ||
      "";
  } catch (e) {}
  if (nextPhaseHint) {
    html +=
      '<div style="margin-top:8px;padding:6px 10px;background:#fef3c7;border:1px solid #fde68a;border-radius:6px;font-size:11px;color:#92400e;line-height:1.5;">';
    html += "💡 " + escapeHtml(nextPhaseHint);
    html += "</div>";
