    '<button type="button" class="phone-world-desc-refresh-btn yq-btn yq-btn--send yq-btn--xs"><i class="fas fa-sync-alt"></i> 刷新描述</button>';
  html += "</div>";
  html += "</div>";

  // 固定剧情进度
  // 银麒赎世剧情flag（从phoneMeta读取）
  var plotList = [];
  try {
    var _tw = window.parent || window;
    var _meta =
      _tw.SillyTavern && _tw.SillyTavern.getContext
        ? _tw.SillyTavern.getContext().chatMetadata || {}
        : {};
    var _flags = _meta.yinqi_story_flags || {};
    if (_flags["宋赵复合"])
      plotList.push({ name: "宋赵复合", status: "已触发" });
    if (_flags["宋赵破处"])
      plotList.push({ name: "宋赵破处", status: "已触发" });
    if (_flags["李陈破处"])
      plotList.push({ name: "李陈破处", status: "已触发" });
  } catch (e) {}

  html += '<div class="list-item">';
  html +=
    '<div class="list-item-header"><span class="list-item-name">📖 剧情进度</span></div>';
