      plotColor +
      ';font-size:12px;width:16px;text-align:center;"></i>';
    html +=
      '<span style="font-size:13px;color:#374151;flex:1;">' +
      p.name +
      "</span>";
    html +=
      '<span style="font-size:11px;color:' +
      plotColor +
      ';font-weight:500;">' +
      plotStatus +
      "</span>";
    html += "</div>";
  }
  html += "</div></div>";

  // 历史角色
  var history = _.get(world, "历史角色", {});
  var histKeys = Object.keys(history);
  if (histKeys.length > 0) {
    html += '<div class="list-item">';
    html +=
      '<div class="list-item-header"><span class="list-item-name">📜 历史角色</span></div>';
    html += '<div style="margin-top:8px;">';
    for (var j = 0; j < histKeys.length; j++) {
      var hName = histKeys[j];
      var hData = history[hName];
      var hIdentity = _.get(hData, "身份", "");
      var hEnding = _.get(hData, "结局", "");
      html += '<div style="padding:6px 0;border-bottom:1px solid #f3f4f6;">';
      html +=
        '<div style="font-size:13px;font-weight:600;color:#374151;">' +
        escapeHtml(hName) +
        "</div>";
      if (hIdentity)
        html +=
          '<div style="font-size:11px;color:#6b7280;">' +
          escapeHtml(hIdentity) +
          "</div>";
      if (hEnding)
        html +=
          '<div style="font-size:11px;color:#9ca3af;">结局: ' +
          escapeHtml(hEnding) +
          "</div>";
      html += "</div>";
    }
    html += "</div></div>";
  }

  return html;
}

