// ==================== 平行事件面板（浅色卡片 + 点击展开全文；索引级展开状态存 window._worldEventsExpandedIds） ====================
function generateWorldEventsPanel() {
  // 清除平行快报未读
  var gen = window.npcMsgGen;
  if (gen) gen.clearWorldEventsUnread();

  if (!window._worldEventsExpandedIds) window._worldEventsExpandedIds = {};

  var html = "";
  var events = [];

  // 从聊天历史中扫描 <WorldEvent> 标签
  try {
    var tw = window.parent || window;
    var sc = tw.SillyTavern.getContext();
    var chat = sc.chat || [];
    for (var i = 0; i < chat.length; i++) {
      var msg = chat[i];
      if (!msg || !msg.mes) continue;
      var weMatch = msg.mes.match(/<WorldEvent>([\s\S]*?)<\/WorldEvent>/i);
      if (weMatch) {
        var raw = weMatch[1].trim();
        // 解析标题（⚡ 平行事件 【地点】（时间））
        var titleMatch = raw.match(
          /⚡\s*平行事件\s*(?:【([^】]*)】)?\s*(?:（([^）]*)）)?/,
        );
        var location = titleMatch ? titleMatch[1] || "" : "";
        var time = titleMatch ? titleMatch[2] || "" : "";
        // 内容：去掉标题行
        var contentLines = raw.replace(/^⚡.*$/m, "").trim();
        var preview =
          contentLines.length > 50
            ? contentLines.substring(0, 50) + "..."
            : contentLines;
        events.push({
          chatIndex: i,
          location: location,
          time: time,
          preview: preview,
          raw: raw,
        });
      }
    }
  } catch (e) {}

  // 最新在前
  events.reverse();
  // 缓存事件数据供点击时使用
  window._worldEventsCache = events;

  html +=
    '<div class="phone-world-events-bulletin" style="min-height:100%;background:#eef2f7;display:flex;flex-direction:column;">';
  html +=
    '<div style="display:flex;justify-content:space-between;align-items:center;padding:12px 12px 10px;flex-shrink:0;background:linear-gradient(180deg,#ffffff 0%,#f8fafc 100%);border-bottom:1px solid #e2e8f0;">';
  html += '<div style="min-width:0;">';
  html +=
    '<div style="font-size:15px;font-weight:600;color:var(--SmartThemeBodyColor, #1e293b);">⚡ 平行事件</div>';
  html +=
    '<div style="font-size:11px;color:var(--SmartThemeBodyColor, #94a3af);opacity:0.65;margin-top:2px;">点击条目展开或收起正文</div></div>';
  html +=
    '<div style="display:flex;gap:8px;align-items:center;flex-shrink:0;">';
  html +=
    '<button type="button" class="phone-world-events-refresh-btn" style="padding:4px 12px;background:#10b981;color:white;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:500;"><i class="fas fa-sync"></i> 刷新</button>';
  html +=
    '<button type="button" class="phone-autogen-settings-btn" data-key="worldEvents" data-title="⚡ 平行事件" data-panel="world-events" style="padding:4px 12px;background:#2196F3;color:white;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:500;"><i class="fas fa-cog"></i></button>';
  html += "</div></div>";

  if (events.length === 0) {
    html +=
      '<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 20px;color:var(--SmartThemeBodyColor, #94a3af);opacity:0.7;text-align:center;">' +
      '<i class="fas fa-bolt" style="font-size:40px;margin-bottom:12px;opacity:0.35;"></i>' +
      '<div style="font-size:15px;font-weight:600;color:var(--SmartThemeBodyColor, #64748b);margin-bottom:6px;">暂无平行事件</div>' +
      '<div style="font-size:12px;line-height:1.5;max-width:260px;">点击「刷新」手动生成，或等待剧情内自动触发</div>' +
      "</div>";
    html += "</div>";
    return html;
  }

  html +=
    '<div class="phone-world-events-list" style="padding:10px 10px 14px;overflow-y:auto;flex:1;min-height:0;">';
  for (var idx = 0; idx < events.length; idx++) {
    var ev = events[idx];
    var seqNum = events.length - idx;
    var titleText = ev.location ? "【" + ev.location + "】" : "平行事件";
    if (ev.time) titleText += " · " + ev.time;
    var fullContent = ev.raw || ev.preview || "";
    fullContent = fullContent.replace(/^⚡\s*平行事件.*$/m, "").trim();
    var expanded = !!window._worldEventsExpandedIds[String(idx)];
    var _rankColor =
      seqNum <= 1
        ? "#ef4444"
        : seqNum <= 2
          ? "#f97316"
          : seqNum <= 3
            ? "#f59e0b"
            : "#94a3b8";
    var _accentSolid =
      seqNum <= 1
        ? "#ef4444"
        : seqNum <= 2
          ? "#f97316"
          : seqNum <= 3
            ? "#f59e0b"
            : "#cbd5e1";
    html +=
      '<div class="phone-world-event-card" data-we-idx="' +
      idx +
      '" style="margin-bottom:12px;background:#fff;border:1px solid #e2e8f0;border-radius:14px;box-shadow:0 2px 10px rgba(15,23,42,0.06);overflow:hidden;cursor:pointer;">';
    html +=
      '<div style="display:flex;gap:12px;padding:14px 14px 10px 12px;align-items:flex-start;border-left:4px solid ' +
      _accentSolid +
      ';">';
    html +=
      '<div style="width:28px;flex-shrink:0;text-align:center;font-size:15px;font-weight:800;color:' +
