/**
 * 论坛帖子点赞
 * @param {number} postIndex - 帖子在对应数据池中的索引
 * @param {string} source - 数据来源："auto"（forum_data）/ "commented"（forum_commented）/ "user"（forum_user_posts），默认 "auto"
 */
function phoneForumLikePost(postIndex, source) {
  if (!source) source = "auto";
  var manager = window.phoneForumManager;
  if (!manager) return;

  // 根据 source 从对应数据池读取帖子
  var sourceArray;
  if (source === "auto") {
    sourceArray = manager.loadForumData();
  } else if (source === "commented") {
    sourceArray = manager.loadCommentedPosts();
  } else if (source === "user") {
    sourceArray = manager.loadUserPosts();
  } else {
    sourceArray = manager.loadForumData();
  }
  if (!sourceArray || postIndex < 0 || postIndex >= sourceArray.length) return;

  var post = sourceArray[postIndex];
  // 检查是否已点赞（用_likedByPlayer标记）
  if (post._likedByPlayer) {
    yqToast("info", "你已经点过赞了");
    return;
  }
  post.likes = (post.likes || 0) + 1;
  post._likedByPlayer = true;

  // 保存到对应数据池（点赞不触发任何帖子迁移行为）
  if (source === "auto") {
    manager.saveForumData();
  } else if (source === "commented") {
    manager.commentedPosts = sourceArray;
    manager.saveCommentedPosts();
  } else if (source === "user") {
    manager.userPosts = sourceArray;
    manager.saveUserPosts();
  } else {
    manager.saveForumData();
  }

  // 局部更新点赞按钮，避免页面跳到顶部
  var $btn = $(
    ".forum-post-like-btn[data-post-index='" +
      postIndex +
      "'][data-source='" +
      source +
      "']",
  );
  if (!$btn.length) {
    // 兼容旧版没有 data-source 的按钮
    $btn = $(".forum-post-like-btn[data-post-index='" + postIndex + "']");
  }
  if ($btn.length) {
    $btn.html(
      '<i class="fas fa-thumbs-up" style="color:#3b82f6;"></i> ' +
        post.likes +
        " 赞",
    );
    $btn.css("color", "#3b82f6");
  }
  yqToast("success", "已点赞 👍");
  try {
    if (typeof window.yqCharAppendEvent === "function") {
      window.yqCharAppendEvent({
        charId: post.author || "匿名",
        source: "forum",
        channel: "forum",
        action: "forum_post_liked",
        payload: {
          postId: post.id || "",
          title: post.title || "",
          liker: getForumNickname() || "我",
        },
      });
    }
  } catch (_forumLikeEvtErr) {}
}

/**
 * 论坛回复功能（玩家回复 + AI自动互动）
 * @param {number} postIndex - 帖子在对应数据池中的索引
 * @param {string} replyText - 回复内容
 * @param {string} source - 数据来源："auto"（forum_data）/ "commented"（forum_commented）/ "user"（forum_user_posts），默认 "auto"
 */
async function phoneForumReply(postIndex, replyText, source, imageId) {
  if (!source) source = "auto";
  var manager = window.phoneForumManager;
  if (!manager) return;

  // 根据 source 从对应数据池获取帖子
  var post = null;
  var sourceArray = null;

  if (source === "auto") {
    sourceArray = manager.loadForumData();
    if (!sourceArray || postIndex < 0 || postIndex >= sourceArray.length)
      return;
    post = sourceArray[postIndex];
  } else if (source === "commented") {
    sourceArray = manager.loadCommentedPosts();
    if (!sourceArray || postIndex < 0 || postIndex >= sourceArray.length)
      return;
    post = sourceArray[postIndex];
  } else if (source === "user") {
    sourceArray = manager.loadUserPosts();
    if (!sourceArray || postIndex < 0 || postIndex >= sourceArray.length)
      return;
    post = sourceArray[postIndex];
  } else {
    return;
  }

  if (!Array.isArray(post.replies)) post.replies = [];

  // 获取游戏时间
  var _replyGameTime = "刚刚";
  try {
    var _rt = _getGameTimeCompat();
    if (_rt) {
      var _rm = _rt.match(/(\d{1,2}:\d{2})$/);
      if (_rm) _replyGameTime = _rm[1];
    }
  } catch (e) {}

  // 添加玩家回复
  var nextFloor =
    post.replies.length > 0
      ? (post.replies[post.replies.length - 1].floor ||
          post.replies.length + 1) + 1
      : 2;
  post.replies.push({
    floor: nextFloor,
    author: getForumNickname(),
    content: replyText,
    likes: 0,
    time: _replyGameTime,
    imageId: imageId || undefined,
  });
  try {
    if (typeof window.yqCharAppendEvent === "function") {
      var _replyEvt = window.yqCharAppendEvent({
        charId: getForumNickname() || "我",
        source: "forum",
        channel: "forum",
        action: "forum_reply_sent",
        payload: {
          postId: post.id || "",
          title: post.title || "",
          content: replyText || "",
        },
      });
      if (_replyEvt && typeof window.yqApplyLinkRulesByEvent === "function") {
        window.yqApplyLinkRulesByEvent(_replyEvt);
      }
    }
