      name: context.name1 || "玩家",
      is_user: true,
      is_system: false,
      mes: content,
      extra: {},
      send_date: Date.now(),
    };
    _yqSetInsertFloor(true);
    try {
      chat.push(newMessage);

      if (typeof context.saveChat === "function") context.saveChat();
      if (typeof context.addOneMessage === "function") {
        context.addOneMessage(newMessage, { scroll: false });
      } else if (typeof context.printMessages === "function") {
        context.printMessages();
      }
    } finally {
      _yqSetInsertFloor(false);
    }

    console.log("[论坛见面] 已插入楼层，对方：" + md.inviterNick);
  } catch (e) {
    _yqSetInsertFloor(false);
    console.warn("[论坛见面] 插入楼层失败:", e);
  }
}

/** 辅助：根据source获取帖子 */
function _getForumPost(postIndex, source) {
  var manager = window.phoneForumManager;
  if (!manager) return null;
  var arr = null;
  if (source === "auto") arr = manager.loadForumData();
  else if (source === "commented") arr = manager.loadCommentedPosts();
  else if (source === "user") arr = manager.loadUserPosts();
  if (!arr || postIndex < 0 || postIndex >= arr.length) return null;
  return arr[postIndex];
}

/** 辅助：根据source保存帖子 */
function _saveForumPostBySource(source, manager) {
  if (source === "auto") manager.saveForumData();
  else if (source === "commented") manager.saveCommentedPosts();
  else if (source === "user") manager.saveUserPosts();
}

