      '<input type="file" class="gallery-wallpaper-file" accept="image/*" style="display:none;">';
    html += "</div>";
    // 壁纸分类
    for (var wCat in wallpaperCategories) {
      if (!wallpaperCategories.hasOwnProperty(wCat)) continue;
      var wImgs = wallpaperCategories[wCat];
      var wLoaded = loadedCategories.has(wCat);
      html +=
        '<div class="wallpaper-category" data-category="' +
        wCat +
        '" style="margin-bottom:8px;">';
      html +=
        '<div class="wallpaper-category-header" data-category="' +
        wCat +
        '" style="padding:10px 12px;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;box-shadow:0 1px 2px rgba(0,0,0,0.04);">';
      html +=
        '<span style="font-size:12px;color:#111827;font-weight:600;"><i class="fas fa-image" style="margin-right:6px;color:#9C27B0;"></i>' +
        wCat +
        "</span>";
      html +=
        '<i class="fas fa-chevron-' +
        (wLoaded ? "up" : "down") +
        '" style="color:#6b7280;font-size:10px;"></i>';
      html += "</div>";
      html +=
        '<div class="wallpaper-category-images" data-category="' +
        wCat +
        '" style="display:' +
        (wLoaded ? "block" : "none") +
        ';padding:8px 0;">';
      if (wLoaded && wImgs) {
        html +=
          '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:4px;">';
        for (var wi = 0; wi < wImgs.length; wi++) {
          html +=
            '<div class="wallpaper-item" data-wallpaper-url="' +
            wImgs[wi] +
            '" style="cursor:pointer;position:relative;aspect-ratio:9/16;border-radius:6px;overflow:hidden;border:1px solid #334155;">';
          html +=
            '<img src="' +
            wImgs[wi] +
            '" style="width:100%;height:100%;object-fit:cover;" onerror="this.parentElement.innerHTML=\'<div style=padding:10px;text-align:center;color:#6b7280;font-size:10px;>加载失败</div>\'" />';
