      }
      html += "</div></div>";
    }
    // 如果没有壁纸分类
    if (Object.keys(wallpaperCategories).length === 0) {
      html +=
        '<div class="empty-message"><i class="fas fa-image" style="font-size:36px;margin-bottom:12px;opacity:0.3;"></i><div>暂无预设壁纸</div><div style="font-size:11px;color:#9ca3af;margin-top:6px;">可以上传自定义壁纸或将相册图片设为壁纸</div></div>';
    }
    html += "</div>";
    return html;
  }

  // === 构建图片列表 ===
  var displayItems = [];
  var phoneImages = store
    ? store.getIndex(subTab === "all" ? null : subTab)
    : [];
  for (var pi = 0; pi < phoneImages.length; pi++) {
    var pe = phoneImages[pi];
    if (!pe.hasImage) continue;
    var pLabel =
      {
        surveillance: "📹",
        moments: "📷",
        chat: "💬",
        forum: "📰",
        taskEval: "🎯",
        live: "📺",
        avatar: "👤",
        recovered: "🔄",
      }[pe.source] || "📸";
    // [Bug1修复] 全部使用lazy模式，不在HTML拼接阶段嵌入base64，防止几百张图片导致Invalid string length
    displayItems.push({
      id: pe.id,
      imgSrc: "",
      sourceLabel: pLabel,
      timestamp: pe.timestamp || 0,
      lazy: true,
    });
  }

  // 按时间倒序排列
  displayItems.sort(function (a, b) {
    return (b.timestamp || 0) - (a.timestamp || 0);
  });

  // === 渲染图片网格（分页 + 全量lazy） ===
  var GALLERY_PAGE_SIZE = 36;
  var _galleryPage = window._galleryPage || 0;
  var totalPages = Math.ceil(displayItems.length / GALLERY_PAGE_SIZE);
  if (_galleryPage >= totalPages) _galleryPage = Math.max(0, totalPages - 1);
  var pageStart = _galleryPage * GALLERY_PAGE_SIZE;
  var pageEnd = Math.min(pageStart + GALLERY_PAGE_SIZE, displayItems.length);
  var pageItems = displayItems.slice(pageStart, pageEnd);
  var pageLazyIds = [];
  for (var _pli = pageStart; _pli < pageEnd; _pli++) {
    pageLazyIds.push(displayItems[_pli].id);
  }

  if (displayItems.length === 0) {
    html += '<div class="empty-message">';
    if (!settings.enabled) {
      html +=
        '<i class="fas fa-camera-retro" style="font-size:36px;margin-bottom:12px;opacity:0.3;"></i>';
      html += "<div>生图功能未开启</div>";
      html +=
        '<div style="font-size:11px;color:#9ca3af;margin-top:6px;">开启上方 ☑ 开关启用生图，点击右上角 <i class="fas fa-cog"></i> 进入详细设置</div>';
