      html +=
        '<div style="font-size:11px;color:#9ca3af;margin-top:6px;">使用各APP的生图功能后，图片将出现在这里</div>';
    }
    html += "</div>";
  } else {
    // 分页导航（仅多页时显示）
    if (totalPages > 1) {
      html +=
        '<div style="display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:8px;">';
      html +=
        '<button type="button" class="gallery-page-btn" data-page="' +
        Math.max(0, _galleryPage - 1) +
        '" style="padding:4px 10px;background:' +
        (_galleryPage === 0 ? "#e5e7eb" : "#6366f1") +
        ";color:" +
        (_galleryPage === 0 ? "#9ca3af" : "white") +
        ';border:none;border-radius:6px;font-size:10px;cursor:pointer;"' +
        (_galleryPage === 0 ? " disabled" : "") +
        ">◀</button>";
      html +=
        '<span style="font-size:10px;color:#4b5563;">' +
        (_galleryPage + 1) +
        "/" +
        totalPages +
        " (" +
        displayItems.length +
        "张)</span>";
      html +=
        '<button type="button" class="gallery-page-btn" data-page="' +
        Math.min(totalPages - 1, _galleryPage + 1) +
        '" style="padding:4px 10px;background:' +
        (_galleryPage >= totalPages - 1 ? "#e5e7eb" : "#6366f1") +
        ";color:" +
        (_galleryPage >= totalPages - 1 ? "#9ca3af" : "white") +
        ';border:none;border-radius:6px;font-size:10px;cursor:pointer;"' +
        (_galleryPage >= totalPages - 1 ? " disabled" : "") +
        ">▶</button>";
      html += "</div>";
    }
    html +=
      '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:4px;">';
    for (var gi = 0; gi < pageItems.length; gi++) {
      var item = pageItems[gi];
      html +=
        '<div class="gallery-thumb" data-image-id="' +
        escapeHtml(item.id) +
        '" style="position:relative;aspect-ratio:1;border-radius:8px;overflow:hidden;cursor:pointer;border:1px solid #e5e7eb;background:#fafafa;">';
      // [Bug1] 全部使用lazy占位，异步加载
      html +=
        '<img data-lazy-id="' +
        escapeHtml(item.id) +
        '" src="" style="width:100%;height:100%;object-fit:contain;background:#f5f5f5;display:none;" />';
      html +=
        '<div class="gallery-lazy-placeholder" style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:#f3f4f6;color:#9ca3af;font-size:18px;"><i class="fas fa-spinner fa-spin"></i></div>';
      html +=
        '<div style="position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent,rgba(0,0,0,0.7));padding:2px 4px;font-size:9px;color:white;">' +
        item.sourceLabel +
        "</div>";
      html += "</div>";
    }
    html += "</div>";
  }

  // 异步加载当前页的图片（分批加载，每批10张）
  if (pageLazyIds.length > 0 && store) {
    setTimeout(function () {
      var batchSize = 10;
      var batches = [];
      for (var bi = 0; bi < pageLazyIds.length; bi += batchSize) {
        batches.push(pageLazyIds.slice(bi, bi + batchSize));
      }
      function loadBatch(idx) {
        if (idx >= batches.length) return;
        store.preload(batches[idx]).then(function () {
          for (var li = 0; li < batches[idx].length; li++) {
            var lid = batches[idx][li];
            var imgData = store.load(lid);
            if (imgData) {
              var $img = $('[data-lazy-id="' + lid + '"]');
              if ($img.length) {
                $img.attr("src", imgData).show();
                $img.siblings(".gallery-lazy-placeholder").hide();
              }
            }
          }
          // 加载下一批
          setTimeout(function () {
            loadBatch(idx + 1);
          }, 30);
        });
      }
      loadBatch(0);
    }, 50);
  }

  return html;
}

