  html +=
    '<input type="file" class="gallery-import-file" accept=".json" style="display:none;">';
  html +=
    '<button type="button" class="gallery-clear-all yq-btn yq-btn-danger yq-btn--block" style="font-size:12px;border-radius:8px;"><i class="fas fa-trash"></i> 清除所有图片</button>';
  html += "</div>";
  html += "</div>";

  // 保存+返回
  html += '<div style="display:flex;gap:10px;margin-top:16px;">';
  html +=
    '<button type="button" class="gallery-save-settings yq-btn yq-btn--success yq-btn--flex-1" style="min-height:46px;border-radius:10px;font-size:14px;"><i class="fas fa-save"></i> 保存</button>';
