  html += "</label></div>";

  // Tab切换栏
  var _charTab = window._charAppTab || "characters";
  html +=
    '<div style="display:flex;margin-bottom:12px;background:#f3f4f6;border-radius:12px;padding:4px;">';
  html +=
    '<button type="button" class="char-app-tab yq-btn yq-btn--flex-1' +
    (_charTab === "characters" ? " yq-char-tab--on" : " yq-char-tab--off") +
    '" data-tab="characters" style="min-height:40px;padding:9px 6px;border-radius:9px;font-size:13px;">角色 (' +
    charKeys.length +
    ")</button>";
  var _wCount = window.PhoneWardrobe
    ? Object.keys(window.PhoneWardrobe.getAll()).length
    : 0;
  html +=
    '<button type="button" class="char-app-tab yq-btn yq-btn--flex-1' +
    (_charTab === "wardrobe" ? " yq-char-tab--on" : " yq-char-tab--off") +
    '" data-tab="wardrobe" style="min-height:40px;padding:9px 6px;border-radius:9px;font-size:13px;">衣柜 (' +
    _wCount +
    ")</button>";
  html += "</div>";

  if (_charTab === "characters") {
    // ===== 角色Tab内容 =====

    // 统计
    html +=
      '<div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:12px;padding:0 4px;">已缓存 ' +
      charKeys.length +
      " 个角色外观 · 插件已配置 ";
    var pluginCount = Chatu8Bridge.isAvailable()
      ? Chatu8Bridge.getAllCharacterNames().length / 2
      : 0;
    html += Math.floor(pluginCount) + " 个角色</div>";

    // 角色列表
    if (charKeys.length === 0) {
      html += '<div class="empty-message" style="padding:40px 0;">';
      html +=
        '<i class="fas fa-user-circle" style="font-size:36px;margin-bottom:12px;opacity:0.3;"></i>';
      html += "<div>暂无缓存角色</div>";
      html +=
        '<div style="font-size:11px;color:#9ca3af;margin-top:6px;">当生图遇到未在插件中配置的角色时，系统会自动生成并缓存其外观</div>';
      html += "</div>";
    } else {
      html += '<div style="max-height:400px;overflow-y:auto;">';
      for (var i = 0; i < charKeys.length; i++) {
        var cName = charKeys[i];
        var cData = allChars[cName];
        /* 获取头像 */
        var _avatarUrl =
          typeof getCharacterAvatar === "function"
            ? getCharacterAvatar(cName)
            : null;
        html +=
          '<div class="char-card" style="margin-bottom:8px;padding:12px 14px;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">';
        /* 第一行：头像 + 名字信息 + 编辑/重生成 */
        html +=
          '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;">';
        /* 头像区域（单击查看大图，双击重新生成） */
        html +=
          '<div class="char-avatar-wrap" data-name="' +
          escapeHtml(cName) +
          '" style="position:relative;width:40px;height:40px;flex-shrink:0;cursor:pointer;">';
        if (_avatarUrl) {
          html +=
            '<img src="' +
            _avatarUrl +
            '" style="width:40px;height:40px;border-radius:6px;object-fit:cover;" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';">';
          html +=
            '<div style="display:none;width:40px;height:40px;border-radius:6px;background:' +
            getUserAvatarColor(cName) +
            ';align-items:center;justify-content:center;color:white;font-weight:bold;font-size:16px;">' +
            escapeHtml(cName)[0] +
            "</div>";
        } else {
          html +=
            '<div style="width:40px;height:40px;border-radius:6px;background:' +
            getUserAvatarColor(cName) +
            ';display:flex;align-items:center;justify-content:center;color:white;font-weight:bold;font-size:16px;">' +
            escapeHtml(cName)[0] +
            "</div>";
          html +=
            '<div style="position:absolute;bottom:-2px;right:-2px;width:14px;height:14px;background:#3b82f6;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:8px;color:white;">📷</div>';
        }
        html += "</div>";
        /* 名字+英文名 */
        html += '<div style="flex:1;min-width:0;">';
        html +=
          '<div style="font-size:14px;font-weight:700;color:#111827;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
          escapeHtml(cName);
        if (cData.nameCN && cData.nameCN !== cName)
          html +=
            ' <span style="font-size:10px;color:#f59e0b;">(' +
            escapeHtml(cData.nameCN) +
            ")</span>";
        html +=
          ' <span style="font-size:10px;">' +
          (cData.gender === "male" ? "♂️" : "♀️") +
          "</span>";
        html += "</div>";
        if (cData.nameEN)
          html +=
            '<div style="font-size:10px;color:#6b7280;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
            escapeHtml(cData.nameEN) +
            "</div>";
        html += "</div>";
        /* 右侧按钮第一组 */
        html += '<div style="display:flex;gap:3px;flex-shrink:0;">';
        html +=
          '<button class="char-app-edit" data-name="' +
          escapeHtml(cName) +
          '" style="padding:3px 6px;background:#06b6d4;color:white;border:none;border-radius:4px;cursor:pointer;font-size:10px;">编辑</button>';
        html +=
          '<button class="char-app-regen" data-name="' +
          escapeHtml(cName) +
          '" style="padding:3px 6px;background:#f59e0b;color:white;border:none;border-radius:4px;cursor:pointer;font-size:10px;">重生成</button>';
        html += "</div>";
        html += "</div>";
        /* 第二行：特征预览 + 重置/删除 */
        html +=
          '<div style="display:flex;align-items:center;justify-content:space-between;margin-left:50px;">';
        html += '<div style="flex:1;min-width:0;overflow:hidden;">';
        if (cData.characterTraits) {
          html +=
            '<div style="font-size:10px;color:#636366;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
            escapeHtml(cData.characterTraits) +
            "</div>";
        }
        if (cData.facialFeatures) {
          html +=
            '<div style="font-size:10px;color:#8e8e93;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
            escapeHtml(cData.facialFeatures).substring(0, 50) +
            "...</div>";
        }
        html += "</div>";
        html +=
          '<div style="display:flex;gap:3px;flex-shrink:0;margin-left:4px;">';
        html +=
          '<button type="button" class="char-app-reset yq-btn yq-btn--violet yq-btn--xs" data-name="' +
          escapeHtml(cName) +
          '" style="min-height:0;padding:3px 6px;border-radius:4px;font-size:10px;">重置</button>';
        html +=
          '<button type="button" class="char-app-delete yq-btn yq-btn-danger yq-btn--xs" data-name="' +
          escapeHtml(cName) +
          '" style="min-height:0;padding:3px 6px;border-radius:4px;font-size:10px;">删除</button>';
        html += "</div>";
        html += "</div>";
        /* 第三行：初始服装显示 + 更换按钮 */
        var _curOutfitId = cData.initialOutfit || "";
        var _curOutfit =
          _curOutfitId && window.PhoneWardrobe
            ? window.PhoneWardrobe.get(_curOutfitId)
            : null;
        html +=
          '<div style="display:flex;align-items:center;gap:6px;margin-left:50px;margin-top:4px;">';
        html += '<span style="font-size:10px;color:#8e8e93;">👗</span>';
        if (_curOutfit) {
          html +=
            '<span style="font-size:10px;color:#7c3aed;font-weight:600;">' +
            escapeHtml(_curOutfit.nameCN || _curOutfitId) +
            "</span>";
        } else {
          html +=
            '<span style="font-size:10px;color:#aeaeb2;font-style:italic;">未指定服装</span>';
        }
        html +=
          '<button class="char-outfit-change" data-name="' +
          escapeHtml(cName) +
          '" style="padding:3px 8px;background:#f2f2f7;color:#007aff;border:1px solid #d1d1d6;border-radius:6px;cursor:pointer;font-size:10px;font-weight:600;margin-left:auto;">更换</button>';
        html += "</div>";
        html += "</div>";
      }
      html += "</div>";
    }

    /* 发现新角色：好友列表中有但角色形象中没有的角色 */
    var _newChars = [];
    try {
      var _fl = buildFriendsList();
      var _flKeys = Object.keys(_fl);
      var _existingLower = {};
      for (var _ei = 0; _ei < charKeys.length; _ei++) {
        _existingLower[charKeys[_ei]] = true;
      }
      /* 也检查别名（用户缓存中的 _aliasOf 条目） */
      var _userCache = getPhoneMeta(
        pca ? pca._storageKey : "phone_char_appearance",
        {},
      );
      for (var _ak in _userCache) {
        if (_userCache.hasOwnProperty(_ak)) _existingLower[_ak] = true;
      }
      for (var _fi = 0; _fi < _flKeys.length; _fi++) {
        var _fn = _flKeys[_fi];
        if (_fn === "{{user}}") continue;
        if (_existingLower[_fn]) continue;
        /* 跳过受影响男性"未知" */
        if (_fn === "未知") continue;
        _newChars.push(_fn);
      }
    } catch (_e) {}
    if (_newChars.length > 0) {
      html +=
        '<div style="margin-top:12px;padding:12px 14px;background:#fff;border:1px solid #e5e5ea;border-radius:12px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">';
      html +=
        '<div class="char-app-new-toggle" style="display:flex;align-items:center;justify-content:space-between;cursor:pointer;user-select:none;">';
      html +=
        '<span style="font-size:12px;color:#636366;font-weight:600;">🆕 发现 ' +
        _newChars.length +
        " 个新角色（好友列表中无形象缓存）</span>";
      html +=
        '<i class="fas fa-chevron-down char-app-new-arrow" style="font-size:10px;color:#8e8e93;transition:transform 0.2s;"></i>';
      html += "</div>";
      html +=
        '<div class="char-app-new-list" style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;">';
      for (var _ni = 0; _ni < _newChars.length; _ni++) {
        html +=
          '<button class="char-app-gen-new" data-name="' +
          escapeHtml(_newChars[_ni]) +
          '" style="padding:6px 12px;background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;border-radius:8px;cursor:pointer;font-size:11px;font-weight:600;">' +
          escapeHtml(_newChars[_ni]) +
          ' <i class="fas fa-plus" style="font-size:9px;margin-left:2px;"></i></button>';
      }
      html += "</div></div>";
    }

    // ===== 角色Tab底部操作栏 =====
    /* 隐藏的头像上传input */
    html +=
      '<input type="file" id="char-avatar-upload-input" accept="image/*" style="display:none;">';

    // 底部操作栏
    html += '<div style="display:flex;gap:6px;margin-top:12px;">';
    html +=
      '<button type="button" class="char-app-batch-avatar yq-btn yq-btn--info yq-btn--flex-1" style="min-height:42px;border-radius:8px;font-size:12px;' +
      (charKeys.length === 0 ? "opacity:0.5;" : "") +
      '"><i class="fas fa-camera"></i> 批量头像</button>';
    html +=
      '<button type="button" class="char-app-export yq-btn yq-btn--indigo yq-btn--flex-1" style="min-height:42px;border-radius:8px;font-size:12px;' +
      (charKeys.length === 0 ? "opacity:0.5;" : "") +
      '"><i class="fas fa-download"></i> 导出</button>';
    html +=
      '<button type="button" class="char-app-clear yq-btn yq-btn-danger yq-btn--flex-1" style="min-height:42px;border-radius:8px;font-size:12px;' +
      (charKeys.length === 0 ? "opacity:0.5;" : "") +
      '"><i class="fas fa-trash"></i> 清空</button>';
    html += "</div>";
  } else {
    // ===== 衣柜Tab内容 =====
    html += generateWardrobePanel();
  }

  html += "</div>";
  return html;
}

// ==================== 衣柜独立面板 ====================
function generateWardrobePanel() {
  var html = '<div style="padding:0 0 4px 0;">';
  var wardrobeAll = window.PhoneWardrobe ? window.PhoneWardrobe.getAll() : {};
  var wardrobeKeys = Object.keys(wardrobeAll);

  html +=
    '<div style="font-size:11px;color:#636366;font-weight:600;margin-bottom:10px;padding:0 4px;">共 ' +
    wardrobeKeys.length +
    " 套服装</div>";

  var pca = window.PhoneCharacterAppearance;
  var allChars = pca ? pca.getAll() : {};
  var charKeys = Object.keys(allChars);
  var outfitCharMap = {};
  var instanceAll =
    window.PhoneWardrobe && window.PhoneWardrobe.getAllInstances
      ? window.PhoneWardrobe.getAllInstances()
      : {};
  for (var ci = 0; ci < charKeys.length; ci++) {
    var cData = allChars[charKeys[ci]];
    if (cData && cData.initialOutfit) {
      var _refId = cData.initialOutfit;
      var _ins = instanceAll[_refId];
      var _srcId = _ins && _ins.sourceCatalogId ? _ins.sourceCatalogId : _refId;
      if (!outfitCharMap[_srcId]) outfitCharMap[_srcId] = [];
      outfitCharMap[_srcId].push(charKeys[ci]);
    }
  }

  if (wardrobeKeys.length === 0) {
    html +=
      '<div class="empty-message" style="padding:36px 0;background:transparent;">';
    html +=
      '<i class="fas fa-tshirt" style="font-size:40px;margin-bottom:12px;opacity:0.25;color:#aeaeb2;"></i>';
    html += '<div style="color:#111827;font-weight:700;">衣柜为空</div>';
    html +=
      '<div style="font-size:12px;color:#8e8e93;margin-top:8px;line-height:1.5;">点击下方添加服装，或重置为预设套装</div>';
    html += "</div>";
  } else {
    for (var wi = 0; wi < wardrobeKeys.length; wi++) {
      var wk = wardrobeKeys[wi];
      var wItem = wardrobeAll[wk];
      var wAssigned = outfitCharMap[wk] || [];
      html +=
        '<div style="margin-bottom:10px;padding:12px 14px;background:#fff;border:1px solid #e5e5ea;border-radius:12px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">';
      html +=
        '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;">';
      html += '<div style="flex:1;min-width:0;">';
      html +=
        '<div style="font-size:14px;color:#111827;font-weight:700;">' +
        escapeHtml(wItem.nameCN || wk) +
        "</div>";
      if (wItem.nameEN) {
        html +=
          '<div style="font-size:11px;color:#8e8e93;margin-top:2px;">' +
          escapeHtml(wItem.nameEN) +
          "</div>";
      }
      html += "</div>";
      html += '<div style="display:flex;gap:6px;flex-shrink:0;">';
      html +=
        '<button type="button" class="char-wardrobe-assign yq-btn yq-btn--ios-blue yq-btn--xs" data-outfit="' +
        escapeHtml(wk) +
        '">授予</button>';
      html +=
        '<button type="button" class="char-wardrobe-delete yq-btn yq-btn--outline-red-light yq-btn--xs" data-outfit="' +
        escapeHtml(wk) +
        '">删除</button>';
      html += "</div></div>";
      if (wItem.upperBody || wItem.fullBody) {
        html +=
          '<div style="margin-top:8px;padding:8px 10px;background:#f2f2f7;border-radius:8px;border:1px solid #e5e5ea;">';
        if (wItem.upperBody)
          html +=
            '<div style="font-size:11px;color:#475569;"><span style="color:#8e8e93;font-weight:600;">上身</span> ' +
            escapeHtml(wItem.upperBody) +
            "</div>";
        if (wItem.fullBody)
          html +=
            '<div style="font-size:11px;color:#475569;margin-top:4px;"><span style="color:#8e8e93;font-weight:600;">下身</span> ' +
            escapeHtml(wItem.fullBody) +
            "</div>";
        html += "</div>";
      }
      var _outfitGender = wItem.gender || "female";
      var _gLabel = _outfitGender === "male" ? "男性" : "女性";
      html +=
        '<div style="margin-top:8px;font-size:11px;color:#636366;line-height:1.45;">👤 目录 · ' +
        _gLabel;
      if (wAssigned.length > 0) {
        html +=
          " · 已授予 " +
          wAssigned
            .map(function (n) {
              return escapeHtml(n);
            })
            .join("、");
      }
      html += "</div>";
      html += "</div>";
    }
  }

  html += '<div style="display:flex;gap:8px;margin-top:14px;">';
  html +=
    '<button type="button" class="char-wardrobe-add yq-btn yq-btn--send yq-btn--flex-1" style="min-height:44px;font-size:13px;border-radius:10px;"><i class="fas fa-plus"></i> 添加服装</button>';
  html +=
    '<button type="button" class="char-wardrobe-reset yq-btn yq-btn--light-outline" style="min-height:44px;padding:11px 14px;font-size:13px;border-radius:10px;">重置预设</button>';
  html += "</div>";
  html += "</div>";
  return html;
}

// ==================== [社交化加好友 阶段2] 模态框渲染函数 ====================

/**
 * 格式化好友申请来源（友好显示）
 */
function _yqFormatFriendSource(src) {
  var map = {
    forum: "论坛",
    forum_reply: "论坛回复",
    live: "直播间",
    live_comment: "直播评论",
    player_active_forum: "你主动（论坛）",
    player_active_forum_reply: "你主动（论坛回复）",
    player_active_live: "你主动（直播）",
    player_active_contacts_add: "你主动（通讯录）",
    player_manual: "你主动添加",
    interaction: "社交互动",
    story: "剧情",
  };
  return map[String(src || "")] || src || "未知";
}

/**
 * 渲染"添加好友"候选列表模态框（支持 Tab 分类 / 搜索 / 翻页）
 * 状态保存在 window._yqAddFriendState = { page, keyword, category }
 * category: 'real'（现实） | 'netImportant'（网络重要） | 'netCasual'（网络路人）
 */
function _yqRenderAddFriendCandidatesPanel() {
  var state = window._yqAddFriendState || {
    page: 0,
    keyword: "",
    category: "real",
  };
  if (!state.category) state.category = "real";
  var keyword = String(state.keyword || "")
    .trim()
    .toLowerCase();
  var pageSize = 10;

  var candidates = [];
  try {
    candidates =
      typeof yqGetPendingCandidates === "function"
        ? yqGetPendingCandidates()
        : [];
  } catch (_e) {}

  // 按分类计数
  var catCounts = { real: 0, netImportant: 0, netCasual: 0 };
  for (var ci = 0; ci < candidates.length; ci++) {
    var cat = String(candidates[ci].category || "netCasual");
    if (!(cat in catCounts)) cat = "netCasual";
    catCounts[cat]++;
  }

  // 按当前 activeCategory 过滤
  var filtered = candidates.filter(function (c) {
    return String(c.category || "netCasual") === state.category;
  });
  // 再按 keyword 过滤
  if (keyword) {
    filtered = filtered.filter(function (c) {
      return (
        String(c.name || "")
          .toLowerCase()
          .indexOf(keyword) >= 0
      );
    });
  }

  var totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  var page = Math.max(0, Math.min(state.page || 0, totalPages - 1));
  state.page = page;
  window._yqAddFriendState = state;

  var pageStart = page * pageSize;
  var pageItems = filtered.slice(pageStart, pageStart + pageSize);

  var html =
    '<div class="yq-social-modal" style="display:flex;flex-direction:column;height:100%;background:#ededed;">';

  // 顶部栏（微信风）
  html +=
    '<div style="display:flex;align-items:center;padding:10px 12px;background:#fff;border-bottom:1px solid #e5e7eb;flex-shrink:0;">';
  html +=
    '<button type="button" class="yq-social-modal-close" style="background:transparent;border:none;color:#07c160;font-size:14px;cursor:pointer;padding:0;">← 返回</button>';
  html +=
    '<span style="flex:1;text-align:center;font-size:15px;font-weight:600;color:#2d3748;">添加好友</span>';
  html += '<span style="width:48px;"></span>';
  html += "</div>";

  // Tab 栏（分类）— 微信风，2 字对齐
  var tabs = [
    { id: "real", label: "熟人", icon: "👥", count: catCounts.real },
    {
      id: "netImportant",
      label: "博主",
      icon: "⭐",
      count: catCounts.netImportant,
    },
    { id: "netCasual", label: "网友", icon: "💬", count: catCounts.netCasual },
  ];
  html +=
    '<div style="display:flex;background:#fff;border-bottom:1px solid #e5e7eb;flex-shrink:0;">';
  for (var ti = 0; ti < tabs.length; ti++) {
    var t = tabs[ti];
    var isActive = state.category === t.id;
    var tabColor = isActive ? "color:#07c160;" : "color:#6b7280;";
    var tabBorder = isActive
      ? "border-bottom:2px solid #07c160;"
      : "border-bottom:2px solid transparent;";
    html +=
      '<button type="button" class="yq-candidates-tab" data-cat="' +
      t.id +
      '" style="flex:1;padding:12px 6px;background:#fff;border:none;font-size:13px;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;' +
      tabColor +
      tabBorder +
      '">' +
      '<div style="display:flex;align-items:center;justify-content:center;gap:4px;"><span style="font-size:14px;">' +
      t.icon +
      '</span><span style="font-weight:500;">' +
      t.label +
      "</span></div>" +
      '<span style="font-size:10px;color:' +
      (isActive ? "#07c160" : "#9ca3af") +
      ';font-weight:400;">' +
      (t.count > 0 ? t.count + " 人" : "暂无") +
      "</span></button>";
  }
  html += "</div>";

  // 搜索框
  html +=
    '<div style="padding:10px 12px;background:#fff;border-bottom:1px solid #e5e7eb;flex-shrink:0;">';
  html +=
    '<input type="text" class="yq-social-candidates-search" placeholder="在当前分类中搜索昵称..." value="' +
    escapeHtml(state.keyword || "") +
    '" style="width:100%;padding:8px 12px;border:1px solid #e5e7eb;border-radius:6px;font-size:13px;box-sizing:border-box;outline:none;background:#f5f5f5;" />';
  html += "</div>";

  // [V3 网友渗透] 在"博主/网友" tab 顶部加一个机制提示横幅，让玩家发现"加好友 → 渗透 → 进任务"链路
  if (state.category === "netCasual" || state.category === "netImportant") {
    html += '<div style="padding:8px 12px 0;flex-shrink:0;">';
    html +=
      '<div style="background:linear-gradient(135deg,rgba(139,92,246,0.10),rgba(124,58,237,0.06));border:1px solid rgba(139,92,246,0.18);border-radius:8px;padding:8px 10px;font-size:11px;line-height:1.6;color:#6d28d9;">';
    html +=
      '<div style="font-weight:600;margin-bottom:2px;">🎭 网络渗透机制</div>';
    html +=
      '<div style="color:#475569;">加为好友后，男性陌生人会自动生成<b style="color:#7c3aed;">渗透档案</b>（年龄/职业/性格/类型）。私聊互动 ≥ 20 次 + 发图含女角色名（自动 sharedPhoto），即可解锁为任务执行者（×1.3 系数）。</div>';
    html += "</div></div>";
  }

  // 列表内容
  html += '<div style="flex:1;overflow-y:auto;padding:8px 12px;min-height:0;">';

  if (filtered.length === 0) {
    html +=
      '<div style="text-align:center;padding:40px 16px;color:#9ca3af;font-size:13px;">';
    if (keyword) {
      html += '没有匹配 "' + escapeHtml(state.keyword) + '" 的联系人';
    } else if (state.category === "real") {
      html +=
        '暂无可添加的熟人<br/><span style="font-size:11px;margin-top:6px;display:inline-block;">AI 在正文中提到新 NPC 后会出现在这里</span>';
    } else if (state.category === "netImportant") {
      html +=
        '暂无博主<br/><span style="font-size:11px;margin-top:6px;display:inline-block;">论坛帖子作者、朋友圈作者、主播会出现在这里</span>';
    } else {
      html +=
        '暂无网友<br/><span style="font-size:11px;margin-top:6px;display:inline-block;">论坛回复者、直播评论者会出现在这里</span>';
    }
    html += "</div>";
  } else {
    // 分类对应不同的 avatar 色彩
    var gradient =
      state.category === "real"
        ? "linear-gradient(135deg,#07c160,#10b981)"
        : state.category === "netImportant"
          ? "linear-gradient(135deg,#3b82f6,#6366f1)"
          : "linear-gradient(135deg,#94a3b8,#64748b)";
    for (var i = 0; i < pageItems.length; i++) {
      var c = pageItems[i] || {};
      // 显示用原 name（保留论坛昵称等），加好友用 canonical（规范化内部标识）
      var canonicalName = c.canonical || c.name || "";
      // [阶段B++] 候选列表显示用 smart（真名+昵称）
      var displayName;
      if (typeof yqFriendGetDisplayNameSmart === "function") {
        displayName = yqFriendGetDisplayNameSmart(canonicalName, {
          context: "contacts",
        });
      } else {
        displayName = c.name || "";
      }
      var avatar = String(displayName || "?").charAt(0);
      html +=
        '<div style="display:flex;align-items:center;padding:10px;background:#fff;border-radius:8px;margin-bottom:6px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">';
      html +=
        '<div style="width:40px;height:40px;border-radius:6px;background:' +
        gradient +
        ';color:#fff;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:600;flex-shrink:0;">' +
        escapeHtml(avatar) +
        "</div>";
      html += '<div style="flex:1;margin-left:12px;min-width:0;">';
      html +=
        '<div style="font-size:14px;font-weight:500;color:#2d3748;">' +
        escapeHtml(displayName) +
        "</div>";
      var subtitle = c.isStoryRole
        ? "剧情角色"
        : state.category === "netImportant"
          ? "博主"
          : state.category === "netCasual"
            ? "网友"
            : "陌生人";
      var subColor = c.isStoryRole ? "#07c160" : "#9ca3af";
      html +=
        '<div style="font-size:11px;color:' +
        subColor +
        ';margin-top:2px;">' +
        escapeHtml(subtitle) +
        "</div>";
      html += "</div>";
      // 复用已有 .social-add-friend-btn handler；data-name 用 canonical（防止别名导致重复加）
      html +=
        '<button type="button" class="social-add-friend-btn yq-social-modal-refresh-after" data-name="' +
        escapeHtml(canonicalName) +
        '" data-source="contacts_add" style="padding:6px 14px;background:#07c160;color:#fff;border:none;border-radius:4px;font-size:12px;cursor:pointer;flex-shrink:0;">+ 添加</button>';
      html += "</div>";
    }
  }

  html += "</div>";

  // 底部翻页栏
  if (totalPages > 1) {
    html +=
      '<div style="display:flex;justify-content:center;align-items:center;padding:10px;background:#fff;border-top:1px solid #e5e7eb;flex-shrink:0;gap:8px;">';
    var prevDisabled =
      page === 0 ? "opacity:0.4;cursor:not-allowed;" : "cursor:pointer;";
    var nextDisabled =
      page >= totalPages - 1
        ? "opacity:0.4;cursor:not-allowed;"
        : "cursor:pointer;";
    html +=
      '<button type="button" class="yq-social-candidates-page" data-dir="prev" style="padding:6px 12px;background:#f5f5f5;border:1px solid #e5e7eb;border-radius:4px;font-size:12px;' +
      prevDisabled +
      '">上一页</button>';
    html +=
      '<span style="font-size:12px;color:#666;">' +
      (page + 1) +
      " / " +
      totalPages +
      " 页（共 " +
      filtered.length +
      " 人）</span>";
    html +=
      '<button type="button" class="yq-social-candidates-page" data-dir="next" style="padding:6px 12px;background:#f5f5f5;border:1px solid #e5e7eb;border-radius:4px;font-size:12px;' +
      nextDisabled +
      '">下一页</button>';
    html += "</div>";
  }

  html += "</div>";
  return html;
}

/**
 * 渲染"全部好友申请"模态框（支持翻页）
 * 状态保存在 window._yqAllRequestsState = { page }
 */
function _yqRenderAllFriendRequestsPanel() {
