      }
      html +=
        '<div style="font-size:14px;font-weight:500;color:#2d3748;">' +
        escapeHtml(_reqDisp) +
        "</div>";
      html +=
        '<div style="font-size:12px;color:#666;margin-top:4px;">' +
        escapeHtml(r.reason || "") +
        "</div>";
      html +=
        '<div style="font-size:10px;color:#a0aec0;margin-top:4px;">来源：' +
        escapeHtml(_yqFormatFriendSource(r.fromSource)) +
        "</div>";
      html += "</div></div>";
