        '<div style="display:flex;gap:8px;margin-top:10px;justify-content:flex-end;">';
      html +=
        '<button type="button" class="social-fr-accept-btn yq-social-modal-refresh-after" data-id="' +
        escapeHtml(String(r.id || "")) +
        '" style="padding:6px 16px;background:#07c160;color:#fff;border:none;border-radius:4px;font-size:12px;cursor:pointer;">同意</button>';
      html +=
        '<button type="button" class="social-fr-reject-btn yq-social-modal-refresh-after" data-id="' +
        escapeHtml(String(r.id || "")) +
        '" style="padding:6px 16px;background:transparent;color:#6b7280;border:1px solid #d1d5db;border-radius:4px;font-size:12px;cursor:pointer;">拒绝</button>';
      html += "</div></div>";
    }
  }

  html += "</div>";

  if (totalPages > 1) {
    html +=
      '<div style="display:flex;justify-content:center;align-items:center;padding:10px;background:#fff;border-top:1px solid #e5e7eb;flex-shrink:0;gap:8px;">';
    var prevDisabled2 =
      page === 0 ? "opacity:0.4;cursor:not-allowed;" : "cursor:pointer;";
    var nextDisabled2 =
      page >= totalPages - 1
        ? "opacity:0.4;cursor:not-allowed;"
        : "cursor:pointer;";
    html +=
      '<button type="button" class="yq-all-requests-page" data-dir="prev" style="padding:6px 12px;background:#f5f5f5;border:1px solid #e5e7eb;border-radius:4px;font-size:12px;' +
