// ======== 银麒赎世_角色卡/当前版本/作品展开/phone/_imagegen.js ========
// ==================== 文生图系统 ====================
// PhoneImageBridge + PhoneImageStore + 统一生图函数 + 提示词模板
// + 智绘姬(st-chatu8)角色预设桥接

// ==================== 0. 智绘姬角色预设桥接 ====================
// 读取智绘姬插件的角色/服装预设数据，注入到生图提示词中
// 数据来源: extension_settings['st-chatu8'].characterPresets
// ─────────────────────────────────────────────────────────────────
var Chatu8Bridge = {
  _extName: "st-chatu8",

  /** 获取extension_settings（兼容iframe环境） */
  _getExtSettings: function () {
    if (typeof extension_settings !== "undefined") return extension_settings;
    if (
      window.parent &&
      typeof window.parent.extension_settings !== "undefined"
    )
      return window.parent.extension_settings;
    return null;
  },

  /** 检测智绘姬插件是否已加载 */
  isAvailable: function () {
    try {
      var es = this._getExtSettings();
      return !!es && !!es[this._extName];
    } catch (e) {
      return false;
    }
  },

  /** 获取当前激活的角色预设 */
  getCurrentCharacterPreset: function () {
    if (!this.isAvailable()) return null;
    var ext = this._getExtSettings()[this._extName];
    var activeId = ext.currentCharacterPreset;
    if (!activeId || !ext.characterPresets || !ext.characterPresets[activeId])
      return null;
    return { id: activeId, data: ext.characterPresets[activeId] };
  },

  /** 获取所有角色预设列表 (id -> name) */
  getCharacterPresetList: function () {
    if (!this.isAvailable()) return {};
    var ext = this._getExtSettings()[this._extName];
    var presets = ext.characterPresets || {};
    var list = {};
    for (var id in presets) {
      if (presets.hasOwnProperty(id)) {
        list[id] = presets[id].name || presets[id].nameEN || id;
      }
    }
    return list;
  },

  /** 获取指定角色预设的详细数据 */
  getCharacterPresetById: function (presetId) {
    if (!this.isAvailable()) return null;
    var ext = this._getExtSettings()[this._extName];
    if (!ext.characterPresets || !ext.characterPresets[presetId]) return null;
    return ext.characterPresets[presetId];
  },

  /** 构建角色DNA文本块（用于注入到LLM提示词） */
  buildCharacterText: function (preset) {
    if (!preset) return "";
    var lines = ["<角色外观DNA>"];
    if (preset.name) lines.push("角色名称: " + preset.name);
    if (preset.nameEN) lines.push("英文名称: " + preset.nameEN);
    if (preset.facialFeatures) lines.push("面部特征: " + preset.facialFeatures);
    if (preset.facialFeaturesBack)
      lines.push("面部特征背面: " + preset.facialFeaturesBack);
    if (preset.upperBodySFW) lines.push("上半身SFW: " + preset.upperBodySFW);
    if (preset.upperBodySFWBack)
      lines.push("上半身SFW背面: " + preset.upperBodySFWBack);
    if (preset.fullBodySFW) lines.push("下半身SFW: " + preset.fullBodySFW);
    if (preset.fullBodySFWBack)
      lines.push("下半身SFW背面: " + preset.fullBodySFWBack);
    if (preset.upperBodyNSFW) lines.push("上半身NSFW: " + preset.upperBodyNSFW);
    if (preset.upperBodyNSFWBack)
      lines.push("上半身NSFW背面: " + preset.upperBodyNSFWBack);
    if (preset.fullBodyNSFW) lines.push("下半身NSFW: " + preset.fullBodyNSFW);
    if (preset.fullBodyNSFWBack)
      lines.push("下半身NSFW背面: " + preset.fullBodyNSFWBack);
    lines.push("</角色外观DNA>");
    return lines.join("\n");
  },

  /** 构建服装预设文本块 */
  buildOutfitsText: function (preset) {
    if (!this.isAvailable()) return "";
    var ext = this._getExtSettings()[this._extName];
    var outfitIds = (preset && preset.outfits) || [];
    if (!outfitIds.length) return "";
    var outfitPresets = ext.outfitPresets || {};
    var lines = ["<服装预设列表>"];
    for (var i = 0; i < outfitIds.length; i++) {
      var oid = outfitIds[i];
      var outfit = outfitPresets[oid];
      if (outfit) {
        lines.push("<服装>");
        lines.push("服装名称: " + oid);
        if (outfit.nameEN) lines.push("英文名称: " + outfit.nameEN);
        if (outfit.upperBody) lines.push("上半身: " + outfit.upperBody);
        if (outfit.upperBodyBack)
          lines.push("上半身背面: " + outfit.upperBodyBack);
        if (outfit.fullBody) lines.push("下半身: " + outfit.fullBody);
        if (outfit.fullBodyBack)
          lines.push("下半身背面: " + outfit.fullBodyBack);
        lines.push("</服装>");
      } else {
        lines.push("<服装>");
        lines.push("服装名称: " + oid);
        lines.push("(找不到该服装预设)");
        lines.push("</服装>");
      }
    }
    lines.push("</服装预设列表>");
    return lines.join("\n");
  },

  /** 一键获取当前角色+服装的完整DNA文本 */
  getFullCharacterDNA: function () {
    var preset = this.getCurrentCharacterPreset();
    if (!preset) return "";
    var parts = [];
    var charText = this.buildCharacterText(preset.data);
    if (charText) parts.push(charText);
    var outfitText = this.buildOutfitsText(preset.data);
    if (outfitText) parts.push(outfitText);
    return parts.join("\n\n");
  },

  /** 获取所有已配置角色的中英文名称集合（用于匹配判断） */
  getAllCharacterNames: function () {
    if (!this.isAvailable()) return [];
    var ext = this._getExtSettings()[this._extName];
    var presets = ext.characterPresets || {};
    var names = [];
    for (var id in presets) {
      if (presets.hasOwnProperty(id)) {
        var p = presets[id];
        if (p.name) names.push(p.name);
        if (p.nameEN) names.push(p.nameEN);
      }
    }
    return names;
  },

  /** 判断一个名字是否匹配已配置的角色（模糊匹配） */
  isKnownCharacter: function (name) {
    if (!name) return false;
    var allNames = this.getAllCharacterNames();
    var lower = name.toLowerCase().trim();
    for (var i = 0; i < allNames.length; i++) {
      var cn = allNames[i].toLowerCase().trim();
      if (!cn) continue;
      // 完全匹配或包含匹配
      if (lower === cn || lower.indexOf(cn) !== -1 || cn.indexOf(lower) !== -1)
        return true;
    }
    return false;
  },

  /** 获取角色预设中可用的服装名称列表 */
  getAvailableOutfitNames: function (presetData) {
    if (!this.isAvailable() || !presetData) return [];
    var ext = this._getExtSettings()[this._extName];
    var outfitIds = presetData.outfits || [];
    var outfitPresets = ext.outfitPresets || {};
    var names = [];
    for (var i = 0; i < outfitIds.length; i++) {
      var oid = outfitIds[i];
      var outfit = outfitPresets[oid];
      if (outfit) {
        names.push(outfit.nameEN || oid);
      }
    }
    return names;
  },

  /** 通过智绘姬事件系统请求角色展示提示词（异步，需要插件响应） */
  requestCharacterDisplayPrompt: function (requestData) {
    return new Promise(function (resolve, reject) {
      if (typeof eventEmit !== "function" || typeof eventOn !== "function") {
        reject(new Error("事件系统不可用"));
        return;
      }
      var rid =
        "chardna-" + Date.now() + "-" + Math.random().toString(36).substr(2, 6);
      var done = false;
      var timeout = setTimeout(function () {
        if (!done) {
          done = true;
          reject(new Error("角色DNA请求超时"));
        }
      }, 30000);
      var handler = function (response) {
        if (!response || response.id !== rid || done) return;
        done = true;
        clearTimeout(timeout);
        if (response.success) {
          resolve(response.prompt || response.result || "");
        } else {
          reject(new Error(response.error || "角色DNA请求失败"));
        }
      };
      eventOn("LLM_CHAR_DISPLAY_RESPONSE", handler);
      eventEmit("LLM_CHAR_DISPLAY_REQUEST", {
        id: rid,
        data: requestData || {},
      });
    });
  },
};
// ==================== 0.5 智绘姬图片缓存读取桥接 ====================
// 读取智绘姬插件已生成并缓存的图片数据
// 三个来源：chat消息lockedTags、服务器存储(jiuguanStorage)、IndexedDB
// ─────────────────────────────────────────────────────────────────
var Chatu8ImageReader = {
  _extName: "st-chatu8",
  _dbRef: null, // 运行时探测到的IndexedDB引用
  _dbName: null,
  _storeName: null,

  /** 获取指定聊天消息中关联的图片UUID列表 */
  getChatMessageImageUUIDs: function (msgIndex) {
    try {
      var ctx =
        typeof SillyTavern !== "undefined" && SillyTavern.getContext
          ? SillyTavern.getContext()
          : typeof getContext === "function"
            ? getContext()
            : null;
      if (!ctx || !ctx.chat || !ctx.chat[msgIndex]) return [];
      var extra = ctx.chat[msgIndex].extra;
      if (!extra || !extra.lockedTags) return [];
      var tags = extra.lockedTags;
      if (!Array.isArray(tags)) return [];
      // lockedTags 可能是 uuid字符串数组 或 {uuid, line} 对象数组
      return tags
        .map(function (t) {
          return typeof t === "string" ? t : t && t.uuid ? t.uuid : null;
        })
        .filter(Boolean);
    } catch (e) {
      console.warn("[Chatu8ImageReader] getChatMessageImageUUIDs error:", e);
      return [];
    }
  },

  /** 获取服务器存储(jiuguanStorage)中的图片元数据列表 */
  getServerStoredImages: function (characterKey) {
    try {
      // 在iframe环境中，extension_settings可能在parent窗口
      var ext_settings =
        typeof extension_settings !== "undefined"
          ? extension_settings
          : window.parent &&
              typeof window.parent.extension_settings !== "undefined"
            ? window.parent.extension_settings
            : null;
      if (!ext_settings) return null;
      var ext = ext_settings[this._extName];
      if (!ext) return null;
      // jiuguanStorage 的完整key名被混淆，尝试常见模式
      var storage = null;
      for (var key in ext) {
        if (key.indexOf("jiuguanSto") === 0) {
          storage = ext[key];
          break;
        }
      }
      if (!storage) return null;
      if (characterKey) {
        var charData = storage[characterKey];
        return charData && charData.images ? charData : null;
      }
      // 返回所有角色的图片数据
      return storage;
    } catch (e) {
      console.warn("[Chatu8ImageReader] getServerStoredImages error:", e);
      return null;
    }
  },

  /** 获取jiuguanStorage的完整key名 */
  _getJiuguanStorageKey: function () {
    try {
      var ext_settings =
        typeof extension_settings !== "undefined"
          ? extension_settings
          : window.parent &&
              typeof window.parent.extension_settings !== "undefined"
            ? window.parent.extension_settings
            : null;
      if (!ext_settings) return null;
      var ext = ext_settings[this._extName];
      if (!ext) return null;
      for (var key in ext) {
        if (key.indexOf("jiuguanSto") === 0) return key;
      }
    } catch (e) {}
    return null;
  },

  /** 从服务器存储中按UUID查找图片base64数据 */
  getServerImageByUUID: function (uuid) {
    try {
      var storage = this.getServerStoredImages();
      if (!storage) return null;
      for (var charKey in storage) {
        if (!storage.hasOwnProperty(charKey)) continue;
        var charData = storage[charKey];
        if (!charData || !charData.images) continue;
        for (var i = 0; i < charData.images.length; i++) {
          var img = charData.images[i];
          if (img && img.uuid === uuid && img.path) {
            return img.path; // path字段存储base64数据
          }
        }
      }
    } catch (e) {
      console.warn("[Chatu8ImageReader] getServerImageByUUID error:", e);
    }
    return null;
  },

  /** 运行时探测IndexedDB数据库名和store名 */
  _probeIndexedDB: function () {
    var self = this;
    return new Promise(function (resolve) {
      if (self._dbRef) {
        resolve(true);
        return;
      }
      try {
        // 尝试通过 indexedDB.databases() 列出所有数据库
        if (indexedDB.databases) {
          indexedDB
            .databases()
            .then(function (dbs) {
              for (var i = 0; i < dbs.length; i++) {
                var name = dbs[i].name || "";
                // 智绘姬的数据库名可能包含 chatu8 或 st-chatu8
                if (
                  name.indexOf("chatu8") !== -1 ||
                  name.indexOf("st-chatu") !== -1
                ) {
                  self._dbName = name;
                  console.log("[Chatu8ImageReader] Found DB:", name);
                  // 打开数据库获取store名
                  var req = indexedDB.open(name);
                  req.onsuccess = function (e) {
                    var db = e.target.result;
                    var storeNames = Array.from(db.objectStoreNames);
                    if (storeNames.length > 0) {
                      self._storeName = storeNames[0]; // 通常只有一个store
                      self._dbRef = db;
                      console.log(
                        "[Chatu8ImageReader] Store:",
                        self._storeName,
                      );
                      resolve(true);
                    } else {
                      db.close();
                      resolve(false);
                    }
                  };
                  req.onerror = function () {
                    resolve(false);
                  };
                  return;
                }
              }
              resolve(false);
            })
            .catch(function () {
              resolve(false);
            });
        } else {
          resolve(false);
        }
      } catch (e) {
        resolve(false);
      }
    });
  },

  /** 从IndexedDB中按UUID获取图片数据 */
  getDBImageByUUID: function (uuid) {
    var self = this;
    return new Promise(function (resolve) {
      if (!self._dbRef || !self._storeName) {
        self._probeIndexedDB().then(function (ok) {
          if (!ok) {
            resolve(null);
            return;
          }
          self._readFromDB(uuid).then(resolve);
        });
        return;
      }
      self._readFromDB(uuid).then(resolve);
    });
  },

  _readFromDB: function (uuid) {
    var self = this;
    return new Promise(function (resolve) {
      try {
        if (!self._dbRef || !self._storeName) {
          resolve(null);
          return;
        }
        var tx = self._dbRef.transaction(self._storeName, "readonly");
        var store = tx.objectStore(self._storeName);
        var req = store.get(uuid);
        req.onsuccess = function () {
          var result = req.result;
          if (!result) {
            resolve(null);
            return;
          }
          // 结果可能是 {id, data(ArrayBuffer/base64), ...} 或直接是数据
          if (result.data) {
            if (result.data instanceof ArrayBuffer) {
              // 转为base64
              var bytes = new Uint8Array(result.data);
              var binary = "";
              for (var i = 0; i < bytes.length; i++) {
                binary += String.fromCharCode(bytes[i]);
              }
              resolve("data:image/png;base64," + window.btoa(binary));
            } else if (typeof result.data === "string") {
              resolve(result.data);
            } else {
              resolve(null);
            }
          } else if (typeof result === "string") {
            resolve(result);
          } else {
            resolve(null);
          }
        };
        req.onerror = function () {
          resolve(null);
        };
      } catch (e) {
        console.warn("[Chatu8ImageReader] _readFromDB error:", e);
        resolve(null);
      }
    });
  },

  /** 综合查找：先查服务器存储，再查IndexedDB */
  getImageByUUID: function (uuid) {
    var self = this;
    return new Promise(function (resolve) {
      // 1. 先查服务器存储（同步，快）
      var serverImg = self.getServerImageByUUID(uuid);
      if (serverImg) {
        resolve(serverImg);
        return;
      }
      // 2. 再查IndexedDB（异步）
      self.getDBImageByUUID(uuid).then(function (dbImg) {
        resolve(dbImg); // 可能为null
      });
    });
  },

  /** 限流的 Promise 池：同时并发最多 N 个，避免 IndexedDB/网络被打爆 */
  _mapWithLimit: function (items, limit, mapper) {
    limit = Math.max(1, Number(limit) || 3);
    var results = new Array(items.length);
    var idx = 0;
    function next() {
      if (idx >= items.length) return Promise.resolve();
      var cur = idx++;
      return Promise.resolve(mapper(items[cur], cur))
        .then(function (r) {
          results[cur] = r;
        })
        .catch(function (err) {
          results[cur] = { _error: err };
        })
        .then(next);
    }
    var workers = [];
    for (var i = 0; i < Math.min(limit, items.length); i++)
      workers.push(next());
    return Promise.all(workers).then(function () {
      return results;
    });
  },

  /** 获取指定聊天消息的所有图片（返回Promise<Array<{uuid, data}>>） */
  getChatMessageImages: function (msgIndex) {
    var self = this;
    var uuids = this.getChatMessageImageUUIDs(msgIndex);
    if (!uuids.length) return Promise.resolve([]);
    return this._mapWithLimit(uuids, 3, function (uuid) {
      return self.getImageByUUID(uuid).then(function (data) {
        return { uuid: uuid, data: data };
      });
    });
  },

  /** 获取最近N条消息中的所有图片（用于手机相册展示） */
  getRecentImages: function (count) {
    count = count || 20;
    try {
      var ctx =
        typeof SillyTavern !== "undefined" && SillyTavern.getContext
          ? SillyTavern.getContext()
          : typeof getContext === "function"
            ? getContext()
            : null;
      if (!ctx || !ctx.chat) return Promise.resolve([]);
      var results = [];
      var chatLen = ctx.chat.length;
      var start = Math.max(0, chatLen - count);
      for (var i = chatLen - 1; i >= start; i--) {
        var extra = ctx.chat[i].extra;
        if (!extra || !extra.lockedTags) continue;
        var tags = extra.lockedTags;
        if (!Array.isArray(tags)) continue;
        for (var j = 0; j < tags.length; j++) {
          var t = tags[j];
          var uuid = typeof t === "string" ? t : t && t.uuid ? t.uuid : null;
          if (uuid) results.push({ uuid: uuid, msgIndex: i });
        }
      }
      if (!results.length) return Promise.resolve([]);
      var self = this;
      return this._mapWithLimit(results, 3, function (item) {
        return self.getImageByUUID(item.uuid).then(function (data) {
          return { uuid: item.uuid, msgIndex: item.msgIndex, data: data };
        });
      });
    } catch (e) {
      console.warn("[Chatu8ImageReader] getRecentImages error:", e);
      return Promise.resolve([]);
    }
  },

  /** 获取服务器存储中所有角色的图片统计 */
  getStorageStats: function () {
    var storage = this.getServerStoredImages();
    if (!storage) return { total: 0, characters: {} };
    var stats = { total: 0, characters: {} };
    for (var charKey in storage) {
      if (!storage.hasOwnProperty(charKey)) continue;
      var charData = storage[charKey];
      var count = charData && charData.images ? charData.images.length : 0;
      stats.characters[charKey] = count;
      stats.total += count;
    }
    return stats;
  },

  /** 获取插件存储的所有图片的统一索引（用于相册展示）
   *  返回数组: [{uuid, date, source:'plugin', characterKey, hasData}]
   */
  getPluginImageIndex: function () {
    var results = [];
    var storage = this.getServerStoredImages();
    if (!storage) return results;
    for (var charKey in storage) {
      if (!storage.hasOwnProperty(charKey)) continue;
      var charData = storage[charKey];
      if (!charData || !charData.images) continue;
      for (var i = 0; i < charData.images.length; i++) {
        var img = charData.images[i];
        if (!img) continue;
        results.push({
          uuid: img.uuid || "plugin-" + charKey + "-" + i,
          date: img.date || 0,
          source: "plugin",
          characterKey: charKey,
          hasData: !!img.path,
          isVideo: !!img.isVideo,
        });
      }
    }
    // 按时间倒序
    results.sort(function (a, b) {
      return (b.date || 0) - (a.date || 0);
    });
    return results;
  },

  /** 加载插件图片的base64数据（同步，仅服务器存储） */
  loadPluginImage: function (uuid) {
    return this.getServerImageByUUID(uuid);
  },

  /** 获取所有角色名列表（从jiuguanStorage的key中提取） */
  getCharacterKeys: function () {
    var storage = this.getServerStoredImages();
    if (!storage) return [];
    var keys = [];
    for (var k in storage) {
      if (storage.hasOwnProperty(k)) keys.push(k);
    }
    return keys;
  },
};
