// ==================== 1. 插件通信桥接 ====================
class PhoneImageBridge {
  constructor() {
    this._timeout = 150000; // 150s
  }
  isAvailable() {
    return typeof eventEmit === "function" && typeof eventOn === "function";
  }
  async generate(prompt, options) {
    if (!this.isAvailable())
      return { success: false, error: "文生图插件未连接" };
    var rid =
      "img-" + Date.now() + "-" + Math.random().toString(36).substr(2, 9);
    var o = options || {};
    var req = {
      id: rid,
      prompt: prompt,
      change: o.change || "",
      width: o.width || null,
      height: o.height || null,
    };
    return new Promise(function (resolve) {
      var done = false,
        stop = null;
      var t = setTimeout(function () {
        if (!done) {
          done = true;
          if (stop) stop();
          resolve({ success: false, error: "生图超时150s" });
        }
      }, 150000);
      var h = function (r) {
        if (!r || r.id !== rid || done) return;
        done = true;
        clearTimeout(t);
        if (stop) stop();
        _yinqiImgGenDiag("bridge.response", {
          requestId: rid,
          success: !!(r && r.success),
          error: r && r.error ? String(r.error) : "",
          imageDataLen: r && r.imageData ? String(r.imageData).length : 0,
          responseKeys: r ? Object.keys(r) : [],
        });
        // 调试：仅在开启诊断开关时打印插件返回的字段/截断 response
        try {
          if (typeof window._yqDbg === "function") {
            window._yqDbg("[PhoneImageBridge] 插件返回字段:", Object.keys(r));
            window._yqDbg(
              "[PhoneImageBridge] 完整response(≤500):",
              JSON.stringify(r).substring(0, 500),
            );
          }
        } catch (_dbgErr) {}
        resolve({
          success: !!r.success,
          imageData: r.imageData || "",
          error: r.error || "",
          _raw: r, // 保留原始response供后续分析
        });
      };
      var ret = eventOn("generate-image-response", h);
      stop =
        ret && typeof ret.stop === "function"
          ? function () {
              ret.stop();
            }
          : function () {
              if (typeof eventRemoveListener === "function")
                eventRemoveListener("generate-image-response", h);
            };
      _yinqiImgGenDiag("bridge.request", {
        requestId: rid,
        prompt: String(prompt || ""),
        promptLen: (prompt || "").length,
        change: String(o.change || ""),
        width: req.width,
        height: req.height,
      });
      eventEmit("generate-image-request", req);
    });
  }
}
window.phoneImageBridge = new PhoneImageBridge();

// ==================== 2. 图片存储管理器 ====================
// v12: 图片数据存储在 IndexedDB (yinqi_phone_images)，不再膨胀 chatMetadata
// 索引(元数据)仍存 chatMetadata.yinqi_phone.image_index（很小，每条~200字节）
// 内存缓存层：load()同步返回缓存命中，loadAsync()异步加载
class PhoneImageStore {
  constructor() {
    this.STORAGE_PREFIX = "yinqi-img-";
    this.DB_NAME = "yinqi_phone_images";
    this.STORE_NAME = "images";
    this.DB_VERSION = 1;
    this._db = null;
    this._dbReady = null; // Promise
    this._cache = {}; // 内存缓存: imageId → base64
    this._migrated = false;
    this._onImageLoaded = null; // 异步加载完成回调
    this._initDB();
  }

  /** 初始化 IndexedDB */
  _initDB() {
    var self = this;
    this._dbReady = new Promise(function (resolve) {
      try {
        var req = indexedDB.open(self.DB_NAME, self.DB_VERSION);
        req.onupgradeneeded = function (e) {
          var db = e.target.result;
          if (!db.objectStoreNames.contains(self.STORE_NAME)) {
            db.createObjectStore(self.STORE_NAME);
          }
        };
        req.onsuccess = function (e) {
          self._db = e.target.result;
          console.log("[PhoneImageStore] IndexedDB 就绪");
          resolve(true);
          // 初始化后自动迁移旧数据
          self._migrateOldData();
        };
        req.onerror = function () {
          console.warn(
            "[PhoneImageStore] IndexedDB 打开失败，回退到chatMetadata",
          );
          resolve(false);
        };
      } catch (e) {
        console.warn("[PhoneImageStore] IndexedDB 不可用:", e);
        resolve(false);
      }
    });
  }

  /** 写入 IndexedDB */
  _dbPut(id, data) {
    var self = this;
    return new Promise(function (resolve) {
      if (!self._db) {
        resolve(false);
        return;
      }
      try {
        var tx = self._db.transaction(self.STORE_NAME, "readwrite");
        var store = tx.objectStore(self.STORE_NAME);
        store.put(data, id);
        tx.oncomplete = function () {
          resolve(true);
        };
        tx.onerror = function () {
          resolve(false);
        };
      } catch (e) {
        resolve(false);
      }
    });
  }

  /** 从 IndexedDB 读取 */
  _dbGet(id) {
    var self = this;
    return new Promise(function (resolve) {
      if (!self._db) {
        resolve(null);
        return;
      }
      try {
        var tx = self._db.transaction(self.STORE_NAME, "readonly");
        var store = tx.objectStore(self.STORE_NAME);
        var req = store.get(id);
        req.onsuccess = function () {
          resolve(req.result || null);
        };
        req.onerror = function () {
          resolve(null);
        };
      } catch (e) {
        resolve(null);
      }
    });
  }

  /** 从 IndexedDB 删除 */
  _dbDelete(id) {
    var self = this;
    return new Promise(function (resolve) {
      if (!self._db) {
        resolve(false);
        return;
      }
      try {
        var tx = self._db.transaction(self.STORE_NAME, "readwrite");
        var store = tx.objectStore(self.STORE_NAME);
        store.delete(id);
        tx.oncomplete = function () {
          resolve(true);
        };
        tx.onerror = function () {
          resolve(false);
        };
      } catch (e) {
        resolve(false);
      }
    });
  }

  /** 清空 IndexedDB */
  _dbClear() {
    var self = this;
    return new Promise(function (resolve) {
      if (!self._db) {
        resolve(false);
        return;
      }
      try {
        var tx = self._db.transaction(self.STORE_NAME, "readwrite");
        var store = tx.objectStore(self.STORE_NAME);
        store.clear();
        tx.oncomplete = function () {
          resolve(true);
        };
        tx.onerror = function () {
          resolve(false);
        };
      } catch (e) {
        resolve(false);
      }
    });
  }

  /** 从旧存储(chatMetadata + localStorage)迁移到IndexedDB */
  _migrateOldData() {
    if (this._migrated) return;
    this._migrated = true;
    var self = this;
    try {
      var oldData = getPhoneMeta("image_data", {});
      var keys = Object.keys(oldData);
      if (keys.length === 0) return;
      console.log(
        "[PhoneImageStore] 发现 " +
          keys.length +
          " 张旧图片，开始迁移到IndexedDB...",
      );
      var migrated = 0;
      var doNext = function (i) {
        if (i >= keys.length) {
          if (migrated > 0) {
            // 清除chatMetadata中的image_data
            setPhoneMeta("image_data", {});
            console.log(
              "[PhoneImageStore] 迁移完成: " +
                migrated +
                "/" +
                keys.length +
                " 张图片已转移到IndexedDB",
            );
            yqToast(
              "success",
              "已将 " + migrated + " 张图片迁移到本地数据库，角色卡数据已瘦身",
            );
          }
          return;
        }
        var id = keys[i];
        var imgData = oldData[id];
        if (!imgData) {
          doNext(i + 1);
          return;
        }
        self._dbPut(id, imgData).then(function (ok) {
          if (ok) {
            self._cache[id] = imgData; // 同时填充内存缓存
            migrated++;
          }
          doNext(i + 1);
        });
      };
      doNext(0);
    } catch (e) {
      console.warn("[PhoneImageStore] 迁移失败:", e);
    }
    // 同时清理旧localStorage残留
    try {
      var idx = getPhoneMetaBig("image_index", []);
      for (var i = 0; i < idx.length; i++) {
        var old = localStorage.getItem(this.STORAGE_PREFIX + idx[i].id);
        if (old) {
          this._dbPut(idx[i].id, old);
          this._cache[idx[i].id] = old;
          localStorage.removeItem(this.STORAGE_PREFIX + idx[i].id);
        }
      }
    } catch (e2) {}

    // v13: 迁移 cam_images 中的旧 base64 数据到 IndexedDB
    // 旧格式: {locationName: base64Data}  →  新格式: {locationName: imageId}
    try {
      var camImages = getPhoneMetaBig("cam_images", {});
      var camKeys = Object.keys(camImages);
      var camMigrated = 0;
      for (var ci = 0; ci < camKeys.length; ci++) {
        var camLoc = camKeys[ci];
        var camVal = camImages[camLoc];
        // 判断是否为旧的 base64 数据（以 data: 开头）而非 imageId 引用
        if (
          camVal &&
          typeof camVal === "string" &&
          camVal.indexOf("data:") === 0
        ) {
          // 存入 IndexedDB 并替换为 imageId
          var camImgId =
            "cam-" + Date.now() + "-" + Math.random().toString(36).substr(2, 6);
          self._cache[camImgId] = camVal;
          self._dbPut(camImgId, camVal);
          // 同时写入 image_index
          var camIndex = getPhoneMetaBig("image_index", []);
          camIndex.unshift({
            id: camImgId,
            source: "surveillance",
            location: camLoc,
            description: camLoc + " 监控画面（迁移）",
            time: new Date().toLocaleString(),
            tag: "监控",
            size: { w: 1024, h: 1024 },
            timestamp: Date.now(),
            hasImage: true,
          });
          setPhoneMetaBig("image_index", camIndex);
          // 替换为 imageId 引用
          camImages[camLoc] = camImgId;
          camMigrated++;
        }
      }
      if (camMigrated > 0) {
        setPhoneMetaBig("cam_images", camImages);
        console.log(
          "[PhoneImageStore] cam_images 迁移完成: " +
            camMigrated +
            " 张监控图片已转移到IndexedDB",
        );
        yqToast(
          "success",
          "已将 " + camMigrated + " 张监控图片迁移到本地数据库",
        );
      }
    } catch (e3) {
      console.warn("[PhoneImageStore] cam_images 迁移失败:", e3);
    }
  }

  /** 保存图片 — 写入IndexedDB + 内存缓存，索引写入chatMetadata
   *  [V6.1 FIX·2026-04-22] meta.fixedId 支持固定 id（幂等，不重复注入索引）
   *   - 用于默认头像等"全局唯一"的图片，避免每次切聊天都生成新 id 占 IndexedDB
   *   - 如果 fixedId 已存在（内存/索引），直接返回它，不再 put 数据不再写索引
   */
  save(imageData, meta) {
    var m = meta || {};
    var id;
    if (m.fixedId) {
      id = String(m.fixedId);
      // 幂等：已有缓存直接返回
      if (this._cache[id]) {
        return id;
      }
      // 索引里已有也返回
      try {
        var _idx = getPhoneMetaBig("image_index", []);
        for (var _ii = 0; _ii < _idx.length; _ii++) {
          if (_idx[_ii] && _idx[_ii].id === id) {
            // 索引已存在，仅补内存缓存，不再写索引
            this._cache[id] = imageData;
            this._dbPut(id, imageData); // 异步确保 IDB 有
            return id;
          }
        }
      } catch (_) {}
    } else {
      id = "img-" + Date.now() + "-" + Math.random().toString(36).substr(2, 6);
    }
    // 写入内存缓存（立即可用）
    this._cache[id] = imageData;
    // 异步写入IndexedDB
    this._dbPut(id, imageData);
    // 索引写入chatMetadata（很小）
    var index = getPhoneMetaBig("image_index", []);
    index.unshift({
      id: id,
      source: m.source || "unknown",
      location: m.location || "",
      description: m.description || "",
      time: m.time || new Date().toLocaleString(),
      tag: m.tag || "",
      size: m.size || { w: 1024, h: 1024 },
      timestamp: Date.now(),
      hasImage: true,
    });
    // 统一索引容量门（含自动生图路径），并做内存缓存裁剪
    this._capAndPersistIndex(index);
    this._trimMemoryCache();
    return id;
  }

  /** 同步加载 — 仅从内存缓存读取，未命中返回null
   *  如果未命中且autoFetch为true，会异步加载并触发回调 */
  load(imageId, autoFetch) {
    if (!imageId) return null;
    if (this._cache[imageId]) return this._cache[imageId];
    // 回退：检查旧chatMetadata（迁移期间可能还有）
    var oldData = getPhoneMeta("image_data", {});
    if (oldData[imageId]) {
      this._cache[imageId] = oldData[imageId];
      // 顺便迁移到IndexedDB
      this._dbPut(imageId, oldData[imageId]);
      return oldData[imageId];
    }
    // 自动异步加载（不阻塞）
    if (autoFetch !== false) {
      var self = this;
      this.loadAsync(imageId).then(function (data) {
        if (data && self._onImageLoaded) self._onImageLoaded(imageId, data);
      });
    }
    return null;
  }

  /** 异步加载 — 先查缓存，再查IndexedDB */
  loadAsync(imageId) {
    var self = this;
    if (!imageId) return Promise.resolve(null);
    // 1. 内存缓存
    if (this._cache[imageId]) return Promise.resolve(this._cache[imageId]);
    // 2. 旧chatMetadata回退
    var oldData = getPhoneMeta("image_data", {});
    if (oldData[imageId]) {
      this._cache[imageId] = oldData[imageId];
      this._dbPut(imageId, oldData[imageId]);
      return Promise.resolve(oldData[imageId]);
    }
    // 3. IndexedDB
    return this._dbReady
      .then(function () {
        return self._dbGet(imageId);
      })
      .then(function (data) {
        if (data) self._cache[imageId] = data;
        return data;
      });
  }

  /** 预加载一批图片到内存缓存（用于面板打开时） */
  preload(imageIds) {
    var self = this;
    var toLoad = [];
    for (var i = 0; i < imageIds.length; i++) {
      if (imageIds[i] && !this._cache[imageIds[i]]) toLoad.push(imageIds[i]);
    }
    if (toLoad.length === 0) return Promise.resolve();
    return this._dbReady.then(function () {
      var promises = toLoad.map(function (id) {
        return self._dbGet(id).then(function (data) {
          if (data) self._cache[id] = data;
        });
      });
      return Promise.all(promises);
    });
  }

  getIndex(source) {
    var idx = getPhoneMetaBig("image_index", []);
    return source
      ? idx.filter(function (i) {
          return i.source === source;
        })
      : idx;
  }

  getEntry(imageId) {
    var idx = getPhoneMetaBig("image_index", []);
    for (var i = 0; i < idx.length; i++) {
      if (idx[i].id === imageId) return idx[i];
    }
    return null;
  }

  update(imageId, newData, extraMeta) {
    if (!imageId) return false;
    // 更新内存缓存 + IndexedDB
    this._cache[imageId] = newData;
    this._dbPut(imageId, newData);
    if (extraMeta) {
      var idx = getPhoneMetaBig("image_index", []);
      for (var i = 0; i < idx.length; i++) {
        if (idx[i].id === imageId) {
          for (var k in extraMeta) {
            if (extraMeta.hasOwnProperty(k)) idx[i][k] = extraMeta[k];
          }
          idx[i].timestamp = Date.now();
          setPhoneMetaBig("image_index", idx, true);
          break;
        }
      }
    }
    debounceSavePhoneMeta();
    return true;
  }

  remove(imageId) {
    // 清除内存缓存
    delete this._cache[imageId];
    // 清除IndexedDB
    this._dbDelete(imageId);
    // 清除旧存储残留
    var oldData = getPhoneMeta("image_data", {});
    if (oldData[imageId]) {
      delete oldData[imageId];
      setPhoneMeta("image_data", oldData, true);
    }
    try {
      localStorage.removeItem(this.STORAGE_PREFIX + imageId);
    } catch (e) {}
    // 更新索引
    var idx = getPhoneMetaBig("image_index", []);
    setPhoneMeta(
      "image_index",
      idx.filter(function (i) {
        return i.id !== imageId;
      }),
    );
  }

  getUsage() {
    return { count: getPhoneMetaBig("image_index", []).length };
  }

  clearAll() {
    // 清空内存缓存
    this._cache = {};
    // 清空IndexedDB
    this._dbClear();
    // 清空旧存储
    var idx = getPhoneMetaBig("image_index", []);
    for (var i = 0; i < idx.length; i++) {
      try {
        localStorage.removeItem(this.STORAGE_PREFIX + idx[i].id);
      } catch (e) {}
    }
    setPhoneMetaBig("image_index", []);
    setPhoneMeta("image_data", {});
  }

  _evict(count) {
    var idx = getPhoneMetaBig("image_index", []);
    var n = 0;
    while (idx.length > 0 && n < count) {
      var old = idx.pop();
      delete this._cache[old.id];
      this._dbDelete(old.id);
      n++;
    }
    try {
      if (
        window.phoneImageStore &&
        typeof window.phoneImageStore._capAndPersistIndex === "function"
      ) {
        window.phoneImageStore._capAndPersistIndex(idx);
      } else {
        setPhoneMetaBig("image_index", idx);
      }
    } catch (_idxCapErr) {
      setPhoneMetaBig("image_index", idx);
    }
  }
  _capAndPersistIndex(index) {
    try {
      var _imgMax =
        (typeof window !== "undefined" && Number(window.YQ_IMAGE_INDEX_MAX)) ||
        400;
      var idx = Array.isArray(index)
        ? index
        : getPhoneMetaBig("image_index", []);
      if (idx.length > _imgMax) {
        var overflow = idx.length - _imgMax;
        var evicted = idx.splice(idx.length - overflow, overflow);
        for (var ei = 0; ei < evicted.length; ei++) {
          var old = evicted[ei];
          if (!old || !old.id) continue;
          delete this._cache[old.id];
          this._dbDelete(old.id);
        }
      }
      setPhoneMetaBig("image_index", idx);
    } catch (_capErr) {
      setPhoneMetaBig("image_index", Array.isArray(index) ? index : []);
    }
  }
  _trimMemoryCache() {
    try {
      var cacheKeys = Object.keys(this._cache || {});
      var maxCache =
        (typeof window !== "undefined" && Number(window.YQ_IMAGE_CACHE_MAX)) ||
        120;
      if (cacheKeys.length <= maxCache) return;
      var keepSet = {};
      var idx = getPhoneMetaBig("image_index", []);
      for (var i = 0; i < idx.length && i < maxCache; i++) {
        if (idx[i] && idx[i].id) keepSet[idx[i].id] = true;
      }
      for (var ci = 0; ci < cacheKeys.length; ci++) {
        var k = cacheKeys[ci];
        if (!keepSet[k]) delete this._cache[k];
      }
    } catch (_trimErr) {}
  }

  /** 注册异步加载完成回调 */
  onImageLoaded(callback) {
    this._onImageLoaded = callback;
  }

  /** 获取IndexedDB中所有key（用于重建索引） */
  getAllKeys() {
    var self = this;
    return this._dbReady.then(function () {
      if (!self._db) return [];
      return new Promise(function (resolve) {
        try {
          var tx = self._db.transaction(self.STORE_NAME, "readonly");
          var store = tx.objectStore(self.STORE_NAME);
          var req = store.getAllKeys();
          req.onsuccess = function () {
            resolve(req.result || []);
          };
          req.onerror = function () {
            resolve([]);
          };
        } catch (e) {
          resolve([]);
        }
      });
    });
  }
}
window.phoneImageStore = new PhoneImageStore();

// 注册异步图片加载回调：当IndexedDB中的图片加载到内存后，自动更新DOM
window.phoneImageStore.onImageLoaded(function (imageId, data) {
