    } else {
      // 已有数据：执行旧命名迁移
      this._migrateNames(all);
      // 补充缺失的预置服装（角色initialOutfit引用的但衣柜中不存在的）
      var chars = PhoneCharacterAppearance.getAll();
      var changed = false;
      for (var ck in chars) {
        if (chars.hasOwnProperty(ck) && chars[ck].initialOutfit) {
          var oid = chars[ck].initialOutfit;
          if (!all[oid] && this._presets[oid]) {
            all[oid] = Object.assign({}, this._presets[oid]);
            all[oid].createdAt = Date.now();
            all[oid].kind = "catalog";
            changed = true;
          }
        }
      }
      if (changed) {
        setPhoneMeta(this._storageKey, all);
        debounceSavePhoneMeta();
      }
    }
    this._migrateToOwnerInstances();
    this._normalizeAllNames();
  },

  _diagPush: function (eventName, extra) {
    try {
      if (window._yinqiDiagPush) {
        window._yinqiDiagPush({
          src: "phone-wardrobe",
          level: "info",
          messages: [String(eventName || "wardrobe_event")],
          extra: extra || {},
        });
      }
    } catch (_e) {}
  },

  _diagCount: function (field, inc) {
    try {
      var stats = getPhoneMeta(this._diagStatsKey, {});
      if (!stats || typeof stats !== "object") stats = {};
      var delta = Number(inc || 1);
      stats[field] = Number(stats[field] || 0) + delta;
      stats.updatedAt = Date.now();
      setPhoneMeta(this._diagStatsKey, stats);
      debounceSavePhoneMeta();
    } catch (_e) {}
  },

  _getCatalogAll: function () {
    var all = getPhoneMeta(this._storageKey, {});
    if (!all || typeof all !== "object") return {};
    return all;
  },

  _getInstanceAll: function () {
    var all = getPhoneMeta(this._instanceKey, {});
    if (!all || typeof all !== "object") return {};
    return all;
  },

  getAllInstances: function () {
    return this._getInstanceAll();
  },

  getOwnerInstances: function (charId) {
    if (!charId) return [];
    var all = this._getInstanceAll();
    var keys = Object.keys(all);
    var out = [];
    for (var i = 0; i < keys.length; i++) {
      var x = all[keys[i]];
      if (x && x.ownerCharId === charId) out.push(x);
    }
    out.sort(function (a, b) {
      return (
        Number(b.updatedAt || b.createdAt || 0) -
        Number(a.updatedAt || a.createdAt || 0)
      );
    });
    return out;
  },

  normalizeOutfitDisplayName: function (name) {
    var out = String(name || "").trim();
    if (!out) return "未命名服装";
    out = out
      .replace(/\(([^)]*)(专属|私有|所有者|owner)([^)]*)\)/gi, "")
      .replace(/\[[^\]]*(专属|私有|所有者|owner)[^\]]*\]/gi, "")
      .replace(/(^|[-_])[^-_]{1,12}(专属|同款|衣柜)([-_]|$)/g, "$1")
      .replace(/\s{2,}/g, " ")
      .replace(/(^[-_\s]+|[-_\s]+$)/g, "")
      .trim();
    try {
      var allChars =
        window.PhoneCharacterAppearance &&
        window.PhoneCharacterAppearance.getAll
          ? window.PhoneCharacterAppearance.getAll()
          : {};
      var names = Object.keys(allChars || {}).sort(function (a, b) {
        return b.length - a.length;
      });
      for (var i = 0; i < names.length; i++) {
        var nm = String(names[i] || "").trim();
        if (!nm) continue;
        var escaped = nm.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        out = out
          .replace(new RegExp("^" + escaped + "[-_：:\\s]+", "g"), "")
          .replace(new RegExp("[-_：:\\s]+" + escaped + "$", "g"), "")
          .replace(new RegExp("\\(" + escaped + "\\)", "g"), "")
          .replace(new RegExp("\\[" + escaped + "\\]", "g"), "");
      }
      out = out.replace(/\s{2,}/g, " ").trim();
    } catch (_e) {}
    return out || "未命名服装";
  },

  _normalizeOutfitObjName: function (outfit) {
    if (!outfit || typeof outfit !== "object") return outfit;
    outfit.nameCN = this.normalizeOutfitDisplayName(outfit.nameCN || "");
    return outfit;
  },

  _normalizeAllNames: function () {
    var catalogChanged = false;
    var catalog = this._getCatalogAll();
    var cKeys = Object.keys(catalog);
    for (var i = 0; i < cKeys.length; i++) {
      var c = catalog[cKeys[i]];
      if (!c) continue;
      var oldName = c.nameCN || "";
      var newName = this.normalizeOutfitDisplayName(oldName);
      if (newName !== oldName) {
        c.nameCN = newName;
        catalogChanged = true;
      }
    }
    if (catalogChanged) {
      setPhoneMeta(this._storageKey, catalog);
    }
    var instanceChanged = false;
    var inst = this._getInstanceAll();
    var iKeys = Object.keys(inst);
    for (var j = 0; j < iKeys.length; j++) {
      var it = inst[iKeys[j]];
      if (!it) continue;
      var oldN = it.nameCN || "";
      var newN = this.normalizeOutfitDisplayName(oldN);
      if (newN !== oldN) {
        it.nameCN = newN;
        instanceChanged = true;
      }
    }
    if (instanceChanged) setPhoneMeta(this._instanceKey, inst);
    if (catalogChanged || instanceChanged) debounceSavePhoneMeta();
  },

  _migrateToOwnerInstances: function () {
    var ver = Number(getPhoneMeta(this._schemaKey, 0) || 0);
    if (ver >= this._schemaVersion) return;
    var pca = window.PhoneCharacterAppearance;
    if (!pca || !pca.getAll || !pca.get || !pca.save) return;
    var chars = pca.getAll();
    var charKeys = Object.keys(chars || {});
    var catalog = this._getCatalogAll();
    var instances = this._getInstanceAll();
    if (!getPhoneMeta(this._legacyBackupKey, null)) {
      setPhoneMeta(this._legacyBackupKey, {
        at: new Date().toISOString(),
        schemaVersion: ver,
        phone_wardrobe: catalog,
        phone_wardrobe_instances: instances,
      });
    }
    var refCounter = {};
    for (var i = 0; i < charKeys.length; i++) {
      var cn = charKeys[i];
      var cData = pca.get(cn);
      if (!cData || !cData.initialOutfit) continue;
      refCounter[cData.initialOutfit] =
        Number(refCounter[cData.initialOutfit] || 0) + 1;
      var nextId = this.ensureOwnedOutfitInstance(cn, cData.initialOutfit, {
        silentDiag: true,
        skipNormalize: true,
      });
      if (nextId && nextId !== cData.initialOutfit) {
        cData.initialOutfit = nextId;
        pca.save(cn, cData);
      }
    }
    var splitCount = 0;
    var splitRefs = [];
    var rKeys = Object.keys(refCounter);
    for (var j = 0; j < rKeys.length; j++) {
      if (refCounter[rKeys[j]] > 1) {
        splitCount += refCounter[rKeys[j]];
        splitRefs.push(rKeys[j]);
      }
    }
    setPhoneMeta(this._schemaKey, this._schemaVersion);
    debounceSavePhoneMeta();
    this._diagCount("migrateSplitCount", splitCount);
    this._diagPush("wardrobe_migrate_split", {
      splitCount: splitCount,
      splitRefs: splitRefs.slice(0, 20),
      charCount: charKeys.length,
      schemaVersion: this._schemaVersion,
    });
  },

  /** 迁移旧命名到新命名 */
  _migrateNames: function (all) {
    var changed = false;
    for (var id in all) {
      if (!all.hasOwnProperty(id)) continue;
      var o = all[id];
      if (o.nameCN && this._nameMigration[o.nameCN]) {
        o.nameCN = this._nameMigration[o.nameCN];
        changed = true;
      }
      // 补充缺失的gender字段
      if (!o.gender) {
        o.gender =
          o.nameCN && o.nameCN.indexOf("-男") !== -1 ? "male" : "female";
        changed = true;
      }
    }
    if (changed) {
      setPhoneMeta(this._storageKey, all);
      debounceSavePhoneMeta();
    }
  },

  /** 获取所有服装 */
  getAll: function () {
    return this._getCatalogAll();
  },

  /** 获取指定服装 */
  get: function (id) {
    if (!id) return null;
    var instances = this._getInstanceAll();
    if (instances[id]) return instances[id];
    var all = this._getCatalogAll();
    return all[id] || null;
  },

  /** 保存/更新服装 */
  save: function (outfit) {
    if (!outfit || !outfit.id) return false;
    var all = this._getCatalogAll();
    outfit = this._normalizeOutfitObjName(Object.assign({}, outfit));
    outfit.kind = "catalog";
    outfit.updatedAt = Date.now();
    all[outfit.id] = outfit;
    setPhoneMeta(this._storageKey, all);
    debounceSavePhoneMeta();
    return true;
  },

  saveInstance: function (outfit) {
    if (!outfit || !outfit.id) return false;
    var all = this._getInstanceAll();
    outfit = this._normalizeOutfitObjName(Object.assign({}, outfit));
    outfit.kind = "instance";
    outfit.instanceId = outfit.instanceId || outfit.id;
    outfit.updatedAt = Date.now();
    all[outfit.id] = outfit;
    setPhoneMeta(this._instanceKey, all);
    debounceSavePhoneMeta();
    return true;
  },

  _genInstanceId: function (charId) {
    return (
      "outfit_inst_" +
      String(charId || "unknown").replace(/[^a-zA-Z0-9\u4e00-\u9fff]/g, "") +
      "_" +
      Date.now() +
      "_" +
      Math.random().toString(36).substr(2, 3)
    );
  },

  _buildInstanceFromTemplate: function (ownerCharId, sourceOutfit) {
    if (!ownerCharId || !sourceOutfit) return null;
    var baseId = sourceOutfit.sourceCatalogId || sourceOutfit.id || "";
    return {
      id: this._genInstanceId(ownerCharId),
      instanceId: "",
      ownerCharId: ownerCharId,
      sourceCatalogId: baseId,
      nameCN: sourceOutfit.nameCN || sourceOutfit.nameEN || "未命名服装",
      nameEN: sourceOutfit.nameEN || "",
      gender: sourceOutfit.gender || "female",
      upperBody: sourceOutfit.upperBody || "",
      upperBodyBack: sourceOutfit.upperBodyBack || "",
      fullBody: sourceOutfit.fullBody || "",
      fullBodyBack: sourceOutfit.fullBodyBack || "",
      imageId: sourceOutfit.imageId || "",
      appearancePayload: {
        upperBody: sourceOutfit.upperBody || "",
        upperBodyBack: sourceOutfit.upperBodyBack || "",
        fullBody: sourceOutfit.fullBody || "",
        fullBodyBack: sourceOutfit.fullBodyBack || "",
      },
      createdAt: Date.now(),
      updatedAt: Date.now(),
      kind: "instance",
    };
  },

  ensureOwnedOutfitInstance: function (charId, refId, opts) {
    if (!charId || !refId) return "";
    opts = opts || {};
    var instances = this._getInstanceAll();
    var existing = instances[refId];
    if (existing && existing.ownerCharId === charId) return refId;
    if (existing && existing.ownerCharId !== charId) {
      this._diagCount("ownerMismatchBlocked", 1);
      if (!opts.silentDiag) {
        this._diagPush("wardrobe_owner_mismatch_blocked", {
          ownerCharId: charId,
          oldOwnerCharId: existing.ownerCharId || "",
          refId: refId,
        });
      }
    }
    var src = existing || this.get(refId);
    if (!src) return "";
    var inst = this._buildInstanceFromTemplate(charId, src);
    if (!inst) return "";
    this.saveInstance(inst);
    this._diagCount("copyOnUseCreated", 1);
    if (!opts.silentDiag) {
      this._diagPush("wardrobe_copy_on_use_created", {
        ownerCharId: charId,
        sourceRefId: refId,
        newInstanceId: inst.id,
      });
    }
    return inst.id;
  },

  assignInitialOutfit: function (charName, refId) {
    if (!charName) return false;
    if (
      !window.PhoneCharacterAppearance ||
      !window.PhoneCharacterAppearance.get
    )
      return false;
    var cData = window.PhoneCharacterAppearance.get(charName);
    if (!cData) return false;
    if (!refId) {
      cData.initialOutfit = "";
      window.PhoneCharacterAppearance.save(charName, cData);
      return true;
    }
    var ownerId = this.ensureOwnedOutfitInstance(charName, refId);
    if (!ownerId) return false;
    cData.initialOutfit = ownerId;
    window.PhoneCharacterAppearance.save(charName, cData);
    return true;
  },

  /** 删除服装 */
  remove: function (id) {
    if (!id) return false;
    var catalog = this._getCatalogAll();
    var instances = this._getInstanceAll();
    var found = false;
    if (instances[id]) {
      found = true;
      delete instances[id];
      setPhoneMeta(this._instanceKey, instances);
      // 清除引用该实例的角色 initialOutfit
      var chars1 = PhoneCharacterAppearance.getAll();
      for (var ck1 in chars1) {
        if (chars1.hasOwnProperty(ck1) && chars1[ck1].initialOutfit === id) {
          var cData1 = PhoneCharacterAppearance.get(ck1);
          if (cData1) {
            cData1.initialOutfit = "";
            PhoneCharacterAppearance.save(ck1, cData1);
          }
        }
      }
    } else if (catalog[id]) {
      found = true;
      delete catalog[id];
      setPhoneMeta(this._storageKey, catalog);
      // 删除目录项时，不主动修改角色当前实例，只清理直接引用旧ID的历史数据
      var chars = PhoneCharacterAppearance.getAll();
      for (var ck in chars) {
        if (chars.hasOwnProperty(ck) && chars[ck].initialOutfit === id) {
          var cData = PhoneCharacterAppearance.get(ck);
          if (cData) {
            cData.initialOutfit = "";
            PhoneCharacterAppearance.save(ck, cData);
          }
        }
      }
    }
    if (found) {
      debounceSavePhoneMeta();
      return true;
    }
    return false;
  },

  /** 通过中文名查找服装（支持模糊匹配） */
  findByName: function (name) {
    if (!name) return null;
    var all = this._getCatalogAll();
    var instances = this._getInstanceAll();
    var merge = Object.assign({}, all);
    var instKeys = Object.keys(instances);
    for (var ii = 0; ii < instKeys.length; ii++) {
      var ik = instKeys[ii];
      if (!merge[ik]) merge[ik] = instances[ik];
    }
    all = merge;
    var keys = Object.keys(all);
    // 1. 精确匹配 nameCN
    for (var i = 0; i < keys.length; i++) {
      if (all[keys[i]].nameCN === name) return all[keys[i]];
    }
    // 2. 旧命名映射
    var migrated = this._nameMigration[name];
    if (migrated) {
      for (var j = 0; j < keys.length; j++) {
        if (all[keys[j]].nameCN === migrated) return all[keys[j]];
      }
    }
    // 3. 去分隔符匹配
    var nameClean = name.replace(/-/g, "");
    for (var k = 0; k < keys.length; k++) {
      if (
        all[keys[k]].nameCN &&
        all[keys[k]].nameCN.replace(/-/g, "") === nameClean
      )
        return all[keys[k]];
    }
    // 4. 关键词交集匹配（阈值50%）
    var inputKw = name.replace(/-/g, " ").split(/\s+/).filter(Boolean);
    var bestMatch = null,
      bestScore = 0;
    for (var m = 0; m < keys.length; m++) {
      var cn = all[keys[m]].nameCN || "";
      var outfitKw = cn.replace(/-/g, " ").split(/\s+/).filter(Boolean);
      if (outfitKw.length === 0) continue;
      var hits = 0;
      for (var n = 0; n < inputKw.length; n++) {
        for (var p = 0; p < outfitKw.length; p++) {
          if (
            inputKw[n] === outfitKw[p] ||
            outfitKw[p].indexOf(inputKw[n]) !== -1 ||
            inputKw[n].indexOf(outfitKw[p]) !== -1
          ) {
            hits++;
            break;
          }
        }
      }
      var score = hits / Math.max(inputKw.length, outfitKw.length);
      if (score > bestScore) {
        bestScore = score;
        bestMatch = all[keys[m]];
      }
    }
    return bestScore >= 0.5 ? bestMatch : null;
  },

  /** 提取服装名中的主色调中文 */
  _extractMainColor: function (nameCN) {
    if (!nameCN) return "";
    var parts = nameCN.split("-");
    // 第二段是主色调
    return parts.length >= 2 ? parts[1] : "";
  },

  /** 颜色替换：将服装tag中的主色调替换为目标颜色 */
  replaceOutfitColor: function (tags, outfit, targetColorEN) {
    if (!tags || !targetColorEN || !outfit) return tags;
    var mainColorCN = this._extractMainColor(outfit.nameCN);
    if (!mainColorCN) return tags;
    var mainColorEN = this._colorMap[mainColorCN];
    if (!mainColorEN || mainColorEN === targetColorEN) return tags;
    // 复合色（如 purple-black, dark green）语义不明确，跳过替换
    if (mainColorEN.indexOf("-") !== -1 || mainColorEN.indexOf(" ") !== -1)
      return tags;
    // 全局替换主色调英文词（单词边界）
    var escaped = mainColorEN.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    var re = new RegExp("\\b" + escaped + "\\b", "gi");
    return tags.replace(re, targetColorEN);
  },

  /** 生成新服装ID */
  _genId: function () {
    return (
      "outfit_" + Date.now() + "_" + Math.random().toString(36).substr(2, 4)
    );
  },

  /** 获取服装数量 */
  count: function () {
    return Object.keys(this._getCatalogAll()).length;
  },

  ensureInitialOutfitForCharacter: function (charName, charData) {
    if (!charName || !charData) return "";
    if (charData.initialOutfit) {
      var fixed = this.ensureOwnedOutfitInstance(
        charName,
        charData.initialOutfit,
        {
          silentDiag: true,
        },
      );
      if (fixed && fixed !== charData.initialOutfit) {
        charData.initialOutfit = fixed;
        if (
          window.PhoneCharacterAppearance &&
          window.PhoneCharacterAppearance.save
        ) {
          window.PhoneCharacterAppearance.save(charName, charData);
        }
      }
      return charData.initialOutfit || fixed || "";
    }
    var all = this._getCatalogAll();
    var keys = Object.keys(all);
    var gender = (charData.gender || "female").toLowerCase();
    var picked = "";
    for (var i = 0; i < keys.length; i++) {
      var item = all[keys[i]];
      if (!item) continue;
      if (!item.gender || String(item.gender).toLowerCase() === gender) {
        picked = keys[i];
        break;
      }
    }
    if (!picked) {
      var fallback = {
        id:
          "outfit_auto_" +
          Date.now() +
          "_" +
          Math.random().toString(36).substr(2, 3),
        nameCN:
          gender === "male"
            ? "简约-深色-棉质-T恤长裤-日常-男"
            : "简约-浅色-棉质-衬衫半裙-日常-女",
        nameEN:
          gender === "male"
            ? "minimal dark cotton t-shirt trousers daily male"
            : "minimal light cotton blouse skirt daily female",
        gender: gender === "male" ? "male" : "female",
        upperBody:
          gender === "male"
            ? "dark t-shirt, clean casual fit"
            : "light blouse, clean casual fit",
        upperBodyBack:
          gender === "male"
            ? "dark t-shirt back view"
            : "light blouse back view",
        fullBody:
          gender === "male"
            ? "long trousers, sneakers"
            : "mid skirt, flat shoes",
        fullBodyBack:
          gender === "male"
            ? "trousers back view, sneakers"
            : "mid skirt back view, flat shoes",
        imageId: "",
        createdAt: Date.now(),
      };
      this.save(fallback);
      picked = fallback.id;
    }
    var instId = this.ensureOwnedOutfitInstance(charName, picked, {
      silentDiag: true,
    });
    if (instId) {
      charData.initialOutfit = instId;
      if (
        window.PhoneCharacterAppearance &&
        window.PhoneCharacterAppearance.save
      ) {
        window.PhoneCharacterAppearance.save(charName, charData);
      }
    }
    return instId || "";
  },

  /** 构建服装生成prompt */
  _buildOutfitPrompt: function (description) {
    return (
      "你是服装设计师。请为以下服装生成详细的英文tag，用于AI绘图（NovelAI/Stable Diffusion风格）。\n\n" +
      "服装描述：" +
      description +
      "\n\n" +
      "输出要求：严格按以下JSON格式输出，所有tag必须是英文，逗号分隔：\n\n" +
      "```json\n{\n" +
      '  "nameCN": "按格式命名：风格气质-主色调-材质-服装类型-适用场景-性别（如\'干练高冷-黑色-西装面料-修身西装套裙-职场办公-女\'）",\n' +
      '  "nameEN": "简短英文名（如\'cold elite black fitted business suit skirt female\'）",\n' +
      '  "gender": "male 或 female",\n' +
      '  "upperBody": "上半身正面衣物tag（材质、颜色、款式、配饰，不含身体特征）",\n' +
      '  "upperBodyBack": "上半身背面衣物tag",\n' +
      '  "fullBody": "下半身正面衣物tag（裙裤、鞋袜、腿部配饰）",\n' +
      '  "fullBodyBack": "下半身背面衣物tag"\n' +
      "}\n```\n\n" +
      "规则：\n" +
      "1. 只描述衣物本身，不要包含任何身体特征（如breasts, waist, legs等）\n" +
      "2. 不要包含角色名\n" +
      "3. tag要具体到材质和细节（silk, lace, leather, button-up, zipper等）\n" +
      "4. 只输出JSON，不要其他文字\n"
    );
  },

  /** 异步生成服装（调用LLM） */
  generateOutfit: async function (description) {
    if (!description) return { success: false, error: "描述为空" };
    var api = window.phoneAPI && window.phoneAPI.imageGen;
    if (!api || !api.isAvailable())
      return { success: false, error: "生图API未配置" };
    var prompt = this._buildOutfitPrompt(description);
    var messages = [
      { role: "system", content: "你是服装设计师，只输出JSON格式的服装数据。" },
      { role: "user", content: prompt },
    ];
    var res = null;
    for (var a = 1; a <= 2; a++) {
      res = await api.callAPI(messages);
      if (res && res.indexOf("{") !== -1) break;
      if (a < 2)
        await new Promise(function (r) {
          setTimeout(r, 2000);
        });
    }
    if (!res) return { success: false, error: "LLM无响应" };
    // 解析JSON
    var parsed = this._parseResponse(res);
    if (!parsed) return { success: false, error: "JSON解析失败", raw: res };
    var outfit = {
      id: this._genId(),
      nameCN: parsed.nameCN || description.substring(0, 10),
      nameEN: parsed.nameEN || "",
      gender:
        parsed.gender ||
        (parsed.nameCN && parsed.nameCN.indexOf("-男") !== -1
          ? "male"
          : "female"),
      upperBody: parsed.upperBody || "",
      upperBodyBack: parsed.upperBodyBack || "",
      fullBody: parsed.fullBody || "",
      fullBodyBack: parsed.fullBodyBack || "",
      imageId: "",
      createdAt: Date.now(),
    };
    this.save(outfit);
    return { success: true, data: outfit };
  },

  /** 解析LLM返回的JSON */
  _parseResponse: function (text) {
