    if (this.isDefaultCharacter(name)) return false;
    // 缓存已有 → 不需要
    if (this.get(name)) return false;
    // 插件已配置 → 不需要（无论开关状态，插件角色不主动生成手机缓存）
    if (Chatu8Bridge.isAvailable() && Chatu8Bridge.isKnownCharacter(name))
