  /** 构建角色外观tag文本（按插件的字段选择逻辑组装） */
  buildAppearanceTags: function (name, opts) {
    var data = this.get(name);
    if (!data) return "";
    opts = opts || {};
    var angle = opts.angle || "from front";
    var isBack = /behind|back/i.test(angle);
    var upperNSFW = opts.upperNSFW || false;
    var lowerNSFW = opts.lowerNSFW || false;
    var tags = [];
    // 面部
    var face = isBack ? data.facialFeaturesBack : data.facialFeatures;
    if (face) tags.push(face);
    // 上半身
    if (upperNSFW) {
      tags.push(
        isBack ? data.upperBodyNSFWBack || "" : data.upperBodyNSFW || "",
      );
    } else {
      tags.push(isBack ? data.upperBodySFWBack || "" : data.upperBodySFW || "");
    }
    // 下半身
    if (lowerNSFW) {
      tags.push(isBack ? data.fullBodyNSFWBack || "" : data.fullBodyNSFW || "");
    } else {
      tags.push(isBack ? data.fullBodySFWBack || "" : data.fullBodySFW || "");
    }
    // 服装由LLM根据衣柜信息和场景上下文自主选择，不再自动追加initialOutfit的tag
    return tags.filter(Boolean).join(", ");
  },

  /** 解析占位符并替换为缓存的外观tag（模仿插件的$角色名$替换机制）
   *  角色格式: $英文名-镜头角度-sfw/nsfw-upperBody-sfw/nsfw-lowerBody$
   *  服装格式: $outfit:服装中文名$ 或 $outfit:服装中文名:颜色$
   *  只替换缓存角色，插件角色的占位符留给插件处理 */
  replacePlaceholders: function (tagText) {
    if (!tagText) return tagText;
    var self = this;
    var lastAngle = "from front"; // 记住最近一次角色占位符的角度
    return tagText.replace(/\$([^$]+)\$/g, function (match, inner) {
      // === 服装占位符: $outfit:服装名$ 或 $outfit:服装名:颜色$ ===
      if (inner.indexOf("outfit:") === 0) {
        var outfitParts = inner.substring(7).split(":");
        var outfitName = outfitParts[0].trim();
        var colorOverride = outfitParts[1] ? outfitParts[1].trim() : "";
        if (!outfitName) return match;
        var outfit = PhoneWardrobe.findByName(outfitName);
        if (!outfit) return match; // 找不到就保留原文
        var isBack = lastAngle === "from behind" || lastAngle === "from back";
        var upper = isBack
          ? outfit.upperBodyBack || outfit.upperBody || ""
          : outfit.upperBody || "";
        var lower = isBack
          ? outfit.fullBodyBack || outfit.fullBody || ""
          : outfit.fullBody || "";
        var outfitTags = [upper, lower].filter(Boolean).join(", ");
        // 颜色替换
        if (colorOverride && outfitTags) {
          outfitTags = PhoneWardrobe.replaceOutfitColor(
            outfitTags,
            outfit,
            colorOverride,
          );
        }
        return outfitTags || match;
      }
      // === 角色占位符: $英文名-角度-...$ ===
      var parts = inner.split("-").map(function (s) {
        return s.trim();
      });
      if (parts.length < 2) return match;
      var angleKeywords = [
        "from above",
        "from below",
        "from side",
        "from behind",
        "from front",
        "from back",
      ];
      var nameEN = "";
      var angleStr = "from front";
      var innerLower = inner.toLowerCase();
      var angleIdx = -1;
      for (var ai = 0; ai < angleKeywords.length; ai++) {
        var idx = innerLower.indexOf(angleKeywords[ai]);
        if (idx !== -1) {
          nameEN = inner.substring(0, idx).replace(/-\s*$/, "").trim();
          angleStr = angleKeywords[ai];
          var afterAngle = inner
            .substring(idx + angleKeywords[ai].length)
            .replace(/^\s*-\s*/, "");
          var restParts = afterAngle
            .split("-")
            .map(function (s) {
              return s.trim();
            })
            .filter(Boolean);
          angleIdx = idx;
          break;
        }
      }
      if (angleIdx === -1) return match; // 没找到角度关键词，留给插件
      if (!nameEN) return match;
      lastAngle = angleStr; // 更新最近角度，供后续服装占位符使用
      // 检查是否是缓存角色（通过英文名匹配）
      var cached = null;
      var allCached = self.getAll();
      for (var k in allCached) {
        if (!allCached.hasOwnProperty(k)) continue;
        if (
          allCached[k].nameEN &&
          allCached[k].nameEN.toLowerCase() === nameEN.toLowerCase()
        ) {
          cached = allCached[k];
          break;
        }
      }
      if (!cached) return match; // 不是缓存角色，留给插件
      // 解析 sfw/nsfw
      var upperNSFW = false,
        lowerNSFW = false;
      for (var ri = 0; ri < restParts.length; ri++) {
        var rp = restParts[ri].toLowerCase();
        if (rp === "nsfw") {
          var nextP = restParts[ri + 1] ? restParts[ri + 1].toLowerCase() : "";
          if (nextP.indexOf("upper") !== -1) upperNSFW = true;
          else if (
            nextP.indexOf("lower") !== -1 ||
            nextP.indexOf("full") !== -1
          )
            lowerNSFW = true;
        }
      }
      var tags = self.buildAppearanceTags(cached.nameCN || nameEN, {
        angle: angleStr,
        upperNSFW: upperNSFW,
        lowerNSFW: lowerNSFW,
      });
      return tags || match;
    });
  },

