 * 规则：
 * 1) 生图总开关 enabled 必须为 true
 * 2) mode=manual 时强制关闭所有 auto* 场景
 * 3) 对应场景键（如 autoLive/autoSurveillance）必须为 true
 */
function isImageSceneAutoEnabled(sceneKey, settings) {
  var s = settings || getImageGenSettings();
  if (!s || !s.enabled) return false;
  if (String(s.mode || "manual").toLowerCase() === "manual") return false;
  return s[sceneKey] === true;
