function saveImageGenSettings(s) {
  setPhoneMeta("imageGen_settings", s);
}

function normalizeImageWardrobeMode(mode) {
  var wm = String(mode || "full").toLowerCase();
  return wm === "scoped" ? "scoped" : "full";
}

function collectImageGenSettingsFromPanel() {
  var s = getImageGenSettings();
  s.enabled = $("#ig-enabled").is(":checked");
  s.promptScheme = $("#ig-prompt-scheme").val() || "v1";
  s.autoImageSoftBudgetPerMin =
    parseInt($("#ig-auto-budget-per-min").val(), 10) || 3;
  s.wardrobeMode = normalizeImageWardrobeMode($("#ig-wardrobe-mode").val());
  $(".ig-scene-toggle").each(function () {
    var key = $(this).data("key");
    if (key) s[key] = $(this).is(":checked");
  });
  /* mode 字段保留兼容：任一场景打勾即视为有auto场景 */
  var hasAuto =
    s.autoSurveillance ||
    s.autoMoments ||
    s.autoForum ||
    s.autoChatAI ||
    s.autoLive ||
    s.autoTaskEval;
  s.mode = hasAuto ? "auto" : "manual";
  return s;
}

function persistImageGenSettingsFromPanel(showToast) {
  var s = collectImageGenSettingsFromPanel();
  saveImageGenSettings(s);
  try {
    SillyTavern.saveMetadata();
  } catch (e2) {}
  if (showToast) yqToast("success", "生图设置已保存");
  return s;
}

function isImageGenReady() {
  var s = getImageGenSettings();
  if (!s.enabled) return { ready: false, reason: "生图功能未开启" };
  if (!window.phoneImageBridge || !window.phoneImageBridge.isAvailable())
    return { ready: false, reason: "文生图插件未连接" };
  var api = window.phoneAPI && window.phoneAPI.imageGen;
  if (!api || !api.isAvailable())
    return { ready: false, reason: "生图API未配置" };
  return { ready: true };
}

