var _imageGenHeap = [];
var _imageGenProcessing = false;
var _imageGenCurrentBatch = null; // 当前正在处理的批次ID
var _imageGenSeq = 0;
function _imageGenPriorityScore(priority) {
  var p = String(priority || "").toLowerCase();
  if (p === "high") return 3;
  if (p === "medium") return 2;
  return 1;
}
function _imageGenHeapLess(a, b) {
  if ((a.priorityScore || 0) !== (b.priorityScore || 0))
    return (a.priorityScore || 0) > (b.priorityScore || 0);
  return (a.seq || 0) < (b.seq || 0);
}
function _imageGenHeapSwap(i, j) {
  var t = _imageGenHeap[i];
  _imageGenHeap[i] = _imageGenHeap[j];
  _imageGenHeap[j] = t;
}
function _imageGenHeapPush(task) {
  _imageGenHeap.push(task);
  var i = _imageGenHeap.length - 1;
  while (i > 0) {
    var p = Math.floor((i - 1) / 2);
    if (_imageGenHeapLess(_imageGenHeap[p], _imageGenHeap[i])) break;
    _imageGenHeapSwap(i, p);
    i = p;
  }
}
function _imageGenHeapPop() {
  if (!_imageGenHeap.length) return null;
  var top = _imageGenHeap[0];
  var tail = _imageGenHeap.pop();
  if (_imageGenHeap.length && tail) {
    _imageGenHeap[0] = tail;
    var i = 0;
    while (true) {
      var l = i * 2 + 1;
      var r = i * 2 + 2;
      var best = i;
      if (
        l < _imageGenHeap.length &&
        _imageGenHeapLess(_imageGenHeap[l], _imageGenHeap[best])
      )
        best = l;
      if (
        r < _imageGenHeap.length &&
        _imageGenHeapLess(_imageGenHeap[r], _imageGenHeap[best])
      )
        best = r;
      if (best === i) break;
      _imageGenHeapSwap(i, best);
      i = best;
    }
  }
  return top;
}
async function _processImageGenQueue() {
  if (_imageGenProcessing) return;
  _imageGenProcessing = true;
  while (_imageGenHeap.length > 0) {
    var task = _imageGenHeapPop();
    if (!task) break;
    _imageGenCurrentBatch = task.batchId || null;
    try {
      task.resolve(await task.fn());
    } catch (e) {
      task.reject(e);
    }
  }
  _imageGenCurrentBatch = null;
  _imageGenProcessing = false;
}
function enqueueImageGen(fn, batchId, priority) {
  return new Promise(function (resolve, reject) {
    _imageGenHeapPush({
      fn: fn,
      resolve: resolve,
      reject: reject,
      batchId: batchId || null,
      priority: priority || "low",
      priorityScore: _imageGenPriorityScore(priority || "low"),
      seq: ++_imageGenSeq,
    });
    _processImageGenQueue();
  });
}

