/** 双击重Roll */
window.phoneRerollImage = async function (imageId) {
  var e = window.phoneImageStore.getEntry(imageId);
  if (!e || !e.tag) return { success: false, error: "找不到tag缓存" };
  var b = window.phoneImageBridge;
  if (!b || !b.isAvailable()) return { success: false, error: "插件未连接" };
  var sz = e.size || { w: 1024, h: 1024 };
  var r = await b.generate(e.tag, { width: sz.w, height: sz.h });
  if (!r.success || !r.imageData)
    return { success: false, error: r.error || "重Roll失败" };
  window.phoneImageStore.update(imageId, r.imageData);
  return { success: true, imageData: r.imageData, imageId: imageId };
};


