  async callSillyTavernAPIFallback(prompt) {
    const targetWindow = window.parent || window;
    const messageSender = targetWindow.messageSender;

    if (!messageSender) {
      throw new Error("消息发送器不可用，且 TavernHelper API 也不可用");
    }

    const success = await messageSender.sendToChat(prompt);

    if (!success) {
      throw new Error("发送消息失败，请检查 SillyTavern 是否正常工作");
    }

    const maxWaitTime = 30000;
    const checkInterval = 500;
    const startTime = Date.now();
    let lastMessageCount = 0;

    const getMessageCount = () => {
      try {
        const context = targetWindow.SillyTavern?.getContext();
        return context?.chat?.length || 0;
      } catch (e) {
        return 0;
      }
    };

    lastMessageCount = getMessageCount();

    return new Promise((resolve, reject) => {
      const checkForReply = () => {
        const currentCount = getMessageCount();
        const elapsedTime = Date.now() - startTime;

        if (currentCount > lastMessageCount) {
          try {
            const context = targetWindow.SillyTavern.getContext();
            const messages = context.chat || [];
            const latestMessage = messages[messages.length - 1];

            resolve(latestMessage.mes || "");
          } catch (e) {
            reject(new Error("获取AI回复失败"));
          }
          return;
        }

        if (elapsedTime > maxWaitTime) {
          reject(new Error("等待AI回复超时（30秒）"));
          return;
        }

        setTimeout(checkForReply, checkInterval);
      };

      setTimeout(checkForReply, checkInterval);
    });
  }

  parseForumContent(content) {
    try {
      // 先记录原始内容的前200字符用于错误报告
      const contentPreview = content.substring(0, 200);

      let cleanContent = content.trim();
      // [V10.6] 移除推理标签：覆盖 think/thinking/thought/reasoning 等多种变体
      if (typeof stripThinkingTags === "function") {
        cleanContent = stripThinkingTags(cleanContent);
      } else {
        cleanContent = cleanContent.replace(
          /<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi,
          "",
        );
      }
      cleanContent = cleanContent.replace(/^\|+\s*/, "").replace(/\s*\|+$/, "");
      cleanContent = cleanContent.trim();

      // 检查是否包含 <redit> 标签，匹配所有出现的标签
      const reditMatches = [
        ...cleanContent.matchAll(/<redit>([\s\S]*?)<\/redit>/g),
      ];

      if (reditMatches.length > 0) {
        console.log(`[论坛解析] 找到 ${reditMatches.length} 个 <redit> 标签`);

        // 找到文本量最长且包含JSON格式的
        let bestMatch = null;
        let maxLength = 0;

        for (const match of reditMatches) {
          const extractedContent = match[1].trim();
          // 检查是否包含JSON数组格式
          if (
            extractedContent.includes("[") &&
            extractedContent.includes("]")
          ) {
            if (extractedContent.length > maxLength) {
              maxLength = extractedContent.length;
              bestMatch = extractedContent;
            }
          }
        }

        if (bestMatch) {
          console.log(
            `[论坛解析] 使用最长的包含JSON的标签内容，长度: ${maxLength}`,
          );
          cleanContent = bestMatch;
        } else {
          console.log("[论坛解析] 所有标签都不包含JSON格式，使用原内容");
        }
      } else {
        console.log("[论坛解析] 未找到 <redit> 标签");
      }

      // 查找JSON数组的开始
      const startIndex = cleanContent.indexOf("[");
      if (startIndex === -1) {
        const errorMsg = ` 格式错误，可能被截断 "["\n\n收到的内容预览：\n${contentPreview}...`;
        throw new Error(errorMsg);
      }

      // 查找匹配的结束括号
      let bracketCount = 0;
      let endIndex = -1;
      let inString = false;
      let escapeNext = false;

      for (let i = startIndex; i < cleanContent.length; i++) {
        const char = cleanContent[i];

        if (escapeNext) {
          escapeNext = false;
          continue;
        }

        if (char === "\\") {
          escapeNext = true;
          continue;
        }

        if (char === '"') {
          inString = !inString;
          continue;
        }

        if (inString) continue;

        if (char === "[") {
          bracketCount++;
        } else if (char === "]") {
          bracketCount--;
          if (bracketCount === 0) {
            endIndex = i;
            break;
          }
        }
      }

      if (endIndex === -1) {
        // 截断恢复：尝试找到最后一个完整的JSON对象并关闭数组
        var recoveryContent = cleanContent.substring(startIndex);
        // 找到最后一个完整的 } 位置
        var lastCompleteObj = -1;
        var tempBracket = 0;
        var tempInStr = false;
        var tempEsc = false;
        for (var ri = 0; ri < recoveryContent.length; ri++) {
          var rc = recoveryContent[ri];
          if (tempEsc) {
            tempEsc = false;
            continue;
          }
          if (rc === "\\") {
            tempEsc = true;
            continue;
          }
          if (rc === '"') {
            tempInStr = !tempInStr;
            continue;
          }
          if (tempInStr) continue;
          if (rc === "{") tempBracket++;
          else if (rc === "}") {
            tempBracket--;
            if (tempBracket === 1) lastCompleteObj = ri; // 数组内的顶层对象闭合
          }
        }
        if (lastCompleteObj > 0) {
          // 截取到最后一个完整对象，手动关闭数组
          var truncated =
            recoveryContent.substring(0, lastCompleteObj + 1) + "]";
          console.warn("[论坛解析] JSON被截断，尝试恢复到最后一个完整对象");
          cleanContent = truncated;
          // 重新查找endIndex
          endIndex = cleanContent.length - 1;
        } else {
          const errorMsg =
            ' 格式错误：未找到JSON数组结束符号 "]"（数组不完整，且无法恢复）\n\n收到的内容预览：\n' +
            contentPreview +
            "...";
          throw new Error(errorMsg);
        }
      }

      // 提取JSON字符串并解析
      let jsonString = cleanContent.substring(startIndex, endIndex + 1);

      // 清理字符串值中的控制字符（但保留已转义的）
      // 移除字符串值中未转义的换行符、制表符等控制字符
      jsonString = jsonString.replace(/("(?:[^"\\]|\\.)*")/g, (match) => {
        // 只处理字符串值，将未转义的控制字符替换为空格
        return match.replace(/[\x00-\x1F\x7F]/g, " ");
      });

      let parsed;
      try {
        parsed = JSON.parse(jsonString);
      } catch (jsonError) {
        const errorMsg = ` JSON解析失败：${jsonError.message}\n\nJSON内容预览：\n${jsonString.substring(0, 300)}...`;
        throw new Error(errorMsg);
      }

      // 验证解析结果
      if (!Array.isArray(parsed)) {
        const errorMsg = ` 格式错误：解析结果不是数组，而是 ${typeof parsed}`;
        throw new Error(errorMsg);
      }

      if (parsed.length === 0) {
        const errorMsg = ` 格式错误：解析成功但数组为空（没有帖子数据）`;
        throw new Error(errorMsg);
      }

      // 验证数据格式
      const invalidPosts = parsed.filter(
        (post) => !post.title || !post.author || !post.content,
      );
      if (invalidPosts.length > 0) {
        const errorMsg = ` 格式错误：有 ${invalidPosts.length} 个帖子缺少必需字段（title/author/content）`;
        throw new Error(errorMsg);
      }

      return parsed;
    } catch (e) {
      //  重要：将错误向上抛出，让调用者知道解析失败
      throw new Error(`论坛内容解析失败：${e.message}`);
    }
  }

