// ==================== 论坛/直播叙事摘要系统 ====================
// 追踪当前查看的帖子（用于离开时触发摘要生成）
var _forumCurrentViewPost = null; // { postIndex, source, postId }
var _forumSummaryGenerating = false;

/** 设置当前查看的帖子（进入帖子详情时调用） */
function setForumCurrentViewPost(postIndex, source, post) {
  if (post && typeof postIndex === "number") {
    _forumCurrentViewPost = {
      postIndex: postIndex,
      source: source || "auto",
      postId: post.id || null,
      hasPlayerInteraction:
        source === "user" ||
        source === "commented" ||
        (post._playerReplyCount && post._playerReplyCount > 0),
    };
  } else {
    _forumCurrentViewPost = null;
  }
}

/** 离开帖子时触发摘要生成（fire-and-forget） */
function triggerForumSummaryOnLeave() {
  if (!_forumCurrentViewPost) return;
  if (!_forumCurrentViewPost.hasPlayerInteraction) {
    _forumCurrentViewPost = null;
    return;
  }
  var awarenessSettings = getPhoneMeta("ai_awareness_settings", {});
  var postLevel = awarenessSettings.forumPosts || "low";
  var commentLevel = awarenessSettings.forumComments || "low";
  if (postLevel === "off" && commentLevel === "off") {
    _forumCurrentViewPost = null;
    return;
  }
  var viewInfo = _forumCurrentViewPost;
  _forumCurrentViewPost = null;
  // 获取帖子完整数据
  var manager = window.phoneForumManager;
  if (!manager) return;
  var post = _getForumPostByView(manager, viewInfo);
  if (!post) return;
  // 检查是否需要更新（对比互动数量）
  var summaryKey =
    viewInfo.source === "user"
      ? "forum_summary_user"
      : "forum_summary_commented";
  var existing = getPhoneMeta(summaryKey, []);
  var existingEntry = null;
  for (var i = 0; i < existing.length; i++) {
    if (existing[i].postId === (post.id || viewInfo.postId)) {
      existingEntry = existing[i];
      break;
    }
  }
  var replyCount = (post.replies && post.replies.length) || 0;
  if (existingEntry && existingEntry._replyCount === replyCount) {
    return; // 内容未变化，不重复生成
  }
  // 异步生成摘要
  _generateForumSummaryAsync(post, viewInfo.source, summaryKey);
}

function _getForumPostByView(manager, viewInfo) {
  var arr = null;
  if (viewInfo.source === "user") arr = manager.loadUserPosts();
  else if (viewInfo.source === "commented") arr = manager.loadCommentedPosts();
  else arr = manager.loadForumData();
  if (!arr) return null;
  // 优先按postId查找（因为index可能变化）
  if (viewInfo.postId) {
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].id === viewInfo.postId) return arr[i];
    }
  }
  // 回退到index
  if (viewInfo.postIndex >= 0 && viewInfo.postIndex < arr.length)
    return arr[viewInfo.postIndex];
  return null;
}

async function _generateForumSummaryAsync(post, source, summaryKey) {
  if (_forumSummaryGenerating) return;
  _forumSummaryGenerating = true;
  var chatAPI = window.phoneAPI && window.phoneAPI.chat;
  if (!chatAPI || !chatAPI.isAvailable()) {
    _forumSummaryGenerating = false;
    return;
  }
  yqToast("info", "正在生成论坛互动摘要...", "📝", { timeOut: 2000 });
  try {
    var repliesText = "";
    if (post.replies && post.replies.length > 0) {
      for (var i = 0; i < post.replies.length; i++) {
        var r = post.replies[i];
        repliesText +=
          (r.floor || i + 2) +
          "楼 " +
          (r.author || "匿名") +
          ": " +
          (r.content || "") +
          "\n";
      }
    }
    var prompt =
      "你是叙事摘要生成器。将以下论坛互动总结为一段简洁的叙事摘要。\n\n" +
      "帖子标题：" +
      (post.title || "无标题") +
      "\n" +
      "帖子作者：" +
      (post.author || "匿名") +
      "\n" +
      "帖子内容：" +
      (post.content || "").substring(0, 500) +
      "\n" +
      "全部评论（按时间）：\n" +
      repliesText.substring(0, 1500) +
      "\n\n" +
      "要求：\n" +
      "1. 第三人称描述{{user}}的论坛互动过程\n" +
      "2. 概括帖子核心话题和讨论走向\n" +
      "3. 描述{{user}}的立场/态度\n" +
      "4. 描述其他用户对{{user}}的反应\n" +
      "5. 如涉及剧情角色，指出可能的关系影响\n" +
      "6. 控制在100-150字\n" +
      "7. 只输出摘要文本，不要标题或格式标记\n";
    // [V6.5.9 qtwx-mcp-3/4 联合] 注入主角性别硬约束（影响摘要里对 {{user}} 的代词）
    try {
      if (typeof yqBuildUserGenderPromptBlock === "function")
        prompt += yqBuildUserGenderPromptBlock();
    } catch (_eUGfs) {}
    var result = await chatAPI.callChatAPI("", prompt);
    if (result && result.trim()) {
      var summaryText = result.trim().substring(0, 300);
      var summaries = getPhoneMeta(summaryKey, []);
      // 按postId去重覆盖
      var found = false;
      for (var j = 0; j < summaries.length; j++) {
        if (summaries[j].postId === post.id) {
          summaries[j].summary = summaryText;
          summaries[j].timestamp = Date.now();
          summaries[j]._replyCount = (post.replies && post.replies.length) || 0;
          found = true;
          break;
        }
      }
      if (!found) {
        summaries.unshift({
          postId: post.id,
          title: post.title || "",
          source: source,
          summary: summaryText,
          timestamp: Date.now(),
          _replyCount: (post.replies && post.replies.length) || 0,
        });
      }
      // 只保留最新2条
      if (summaries.length > 2) summaries = summaries.slice(0, 2);
      setPhoneMeta(summaryKey, summaries);
      debounceSavePhoneMeta();
      injectNpcSummaryToContext();
      yqToast("success", "论坛摘要已更新", "📝", { timeOut: 2000 });
    }
  } catch (e) {
    console.warn("[论坛摘要] 生成失败:", e);
    yqToast("warning", "摘要生成失败，将使用原始数据", "📝", {
      timeOut: 2000,
    });
  }
  _forumSummaryGenerating = false;
}

/** 删除指定帖子的摘要（线下触发时调用） */
function removeForumSummary(postId) {
  if (!postId) return;
  var keys = ["forum_summary_user", "forum_summary_commented"];
  for (var k = 0; k < keys.length; k++) {
    var arr = getPhoneMeta(keys[k], []);
    var changed = false;
    for (var i = arr.length - 1; i >= 0; i--) {
      if (arr[i].postId === postId) {
        arr.splice(i, 1);
        changed = true;
      }
    }
    if (changed) {
      setPhoneMeta(keys[k], arr);
    }
  }
  if (changed) debounceSavePhoneMeta();
}
window.removeForumSummary = removeForumSummary;
window.triggerForumSummaryOnLeave = triggerForumSummaryOnLeave;
window.setForumCurrentViewPost = setForumCurrentViewPost;

