// ==================== 论坛帖子举报/删除 ====================
/** 删除（举报封禁）指定帖子，清理关联图片资源 */
window.phoneForumDeletePost = function (postIndex, source) {
  var manager = window.phoneForumManager;
  if (!manager) return;
  var sourceArray = null;
  var saveMethod = null;
  if (source === "auto") {
    sourceArray = manager.loadForumData();
    saveMethod = function () {
      manager.saveForumData();
    };
  } else if (source === "user") {
    sourceArray = manager.loadUserPosts();
    saveMethod = function () {
      manager.saveUserPosts();
    };
  } else if (source === "commented") {
    sourceArray = manager.loadCommentedPosts();
    saveMethod = function () {
      manager.saveCommentedPosts();
    };
  }
  if (!sourceArray || postIndex < 0 || postIndex >= sourceArray.length) return;
  var post = sourceArray[postIndex];
  // 任务帖子特殊处理：同时从yinqi_forum_tasks中移除（否则loadUserPosts会重新合并回来）
  if (post._isTaskPost && post.id) {
    var taskPosts = getPhoneMeta("yinqi_forum_tasks", []);
    var filtered = taskPosts.filter(function (tp) {
      return tp.id !== post.id;
    });
    if (filtered.length !== taskPosts.length) {
      setPhoneMeta("yinqi_forum_tasks", filtered);
    }
  }
  // 清理帖子关联的图片
  if (post.imageId && window.phoneImageStore) {
    window.phoneImageStore.remove(post.imageId);
  }
  // 清理回复中的图片
  if (Array.isArray(post.replies)) {
    for (var ri = 0; ri < post.replies.length; ri++) {
      if (post.replies[ri].imageId && window.phoneImageStore) {
        window.phoneImageStore.remove(post.replies[ri].imageId);
      }
    }
  }
  sourceArray.splice(postIndex, 1);
  saveMethod();
  yqToast("success", source === "user" ? "帖子已删除" : "帖子已举报封禁");
  // 刷新论坛面板
  renderForumPanelIfChanged();
};

// ==================== 发帖函数 ====================
async function phoneForumCreatePost(title, content, imageDesc) {
  var manager = window.phoneForumManager;
  if (!manager) return;

  // 校验标题和内容非空（空字符串或纯空白）
  if (!title || !title.trim()) {
    yqToast("warning", "请输入帖子标题");
    return;
  }
  if (!content || !content.trim()) {
    yqToast("warning", "请输入帖子内容");
    return;
  }

  // 创建帖子对象
  var forum_user_posts = manager.loadUserPosts();
  // 获取游戏时间
  var _forumGameTime = "刚刚";
  try {
    var _ft = _getGameTimeCompat();
    if (_ft) {
      var _fm = _ft.match(/(\d{1,2}:\d{2})$/);
      if (_fm) _forumGameTime = _fm[1];
    }
  } catch (e) {}
  var newPost = {
    id: Date.now(),
    author: getForumNickname(),
    title: title,
    content: content,
    likes: 0,
    time: _forumGameTime,
    replies: [],
    _postTime: Date.now(),
    _likedByPlayer: false,
    _playerReplyCount: 0,
    _meetInviteState: "none",
    _meetData: null,
  };

  // 插入到数组头部
  forum_user_posts.unshift(newPost);
  manager.saveUserPosts();

  // 如果有图片描述，触发图片生成
  if (imageDesc) {
    var imgSettings = getImageGenSettings();
    if (imgSettings.enabled) {
      var imgCtx = {
        description: imageDesc,
        title: title,
        author: getForumNickname(),
      };
      var genFn = imgSettings.autoForum
        ? window.phoneGenerateImage
        : window.phonePreGenerateTag;
      if (genFn) {
        try {
          yqToast("info", "正在生成配图...", "📷");
          var imgResult = await genFn("forum", imgCtx);
          if (imgResult && imgResult.success) {
            // 重新获取帖子引用（可能已被其他操作更新）
            var freshPosts = manager.loadUserPosts();
            for (var fp = 0; fp < freshPosts.length; fp++) {
              if (freshPosts[fp].id === newPost.id) {
                freshPosts[fp].imageId = imgResult.imageId || imgResult.entryId;
                break;
              }
            }
            manager.saveUserPosts();
            yqToast("success", "配图生成成功");
          }
        } catch (imgErr) {
          console.warn("[论坛发帖] 配图生成失败:", imgErr);
        }
      }
    } else {
      // 生图关闭：将图片描述存到帖子上，用文字替代显示
      newPost.imageDesc = imageDesc;
      // 重新保存（newPost已在数组中）
      manager.saveUserPosts();
    }
  }

  // 切换到"我的互动" Tab 并刷新面板
  window._forumPanelTab = "myInteraction";
  renderForumPanelIfChanged();
  $("#phone-app-title").text("论坛");

  yqToast("success", "发帖成功");
  try {
    if (typeof window.yqCharAppendEvent === "function") {
      var _forumPostEvt = window.yqCharAppendEvent({
        charId: getForumNickname() || "我",
        source: "forum",
        channel: "forum",
        action: "forum_post_created",
        payload: {
          postId: newPost.id,
          title: title,
          content: content,
        },
      });
      if (
        _forumPostEvt &&
        typeof window.yqApplyLinkRulesByEvent === "function"
      ) {
        window.yqApplyLinkRulesByEvent(_forumPostEvt);
      }
    }
  } catch (_forumEvtErr) {}

  // 异步 AI 回复生成
  var chatAPI = window.phoneAPI.chat;
  if (!chatAPI || !chatAPI.isAvailable()) {
    yqToast("info", "配置聊天API后可获得AI互动回复", "论坛");
    return;
  }

  yqToast("info", "AI正在生成网友回复...", "论坛互动");

  // 保存帖子ID，用于AI回复后重新定位帖子（因为generateForumPanel会重建数组引用）
  var newPostId = newPost.id;

  try {
    var prompt =
      "你是论坛互动模拟器。以下是一个玩家刚发布的论坛帖子，请模拟2-3个论坛用户对这个帖子的回复。\n\n" +
      "帖子标题：" +
      title +
      "\n" +
      "楼主（我）：" +
      content +
      "\n\n" +
      "规则：\n- 回复者是随机路人网友，不是故事角色\n- 回复要自然真实，有个性和情绪\n- 可以赞同、反驳、补充、吐槽、调侃\n- 至少有1个回复者表现出对楼主的兴趣，主动搭话、追问细节、暗示想进一步了解，有发展成线下见面的潜力\n- 回复风格参考成人社区/贴吧，语气可以暧昧、老司机、开车\n- 简体中文\n" +
      '输出JSON数组：[{"author":"网名","content":"回复内容"}]\n只输出JSON。';
    // [V6.5.9 qtwx-mcp-3/4 联合] 注入主角性别硬约束（影响网友对楼主的称呼）
    try {
      if (typeof yqBuildUserGenderPromptBlock === "function")
        prompt += yqBuildUserGenderPromptBlock();
    } catch (_eUGf) {}

    var result = await chatAPI.callChatAPI("", prompt);
    result = stripJsonCodeBlock(result);
    var jsonMatch = result.match(/\[[\s\S]*\]/);
    if (jsonMatch) {
      var aiReplies = JSON.parse(jsonMatch[0]);
      if (Array.isArray(aiReplies)) {
        // 重新从当前数据中找到帖子（避免引用失效）
        var currentUserPosts = manager.loadUserPosts();
        var targetPost = null;
        for (var pi = 0; pi < currentUserPosts.length; pi++) {
          if (currentUserPosts[pi].id === newPostId) {
            targetPost = currentUserPosts[pi];
            break;
          }
        }
        if (targetPost) {
          if (!Array.isArray(targetPost.replies)) targetPost.replies = [];
          var floor = targetPost.replies.length;
          for (var a = 0; a < aiReplies.length; a++) {
            if (aiReplies[a].author && aiReplies[a].content) {
              if (typeof window.yqCanAutoEmitChar === "function") {
                var _forumAutoGuard = window.yqCanAutoEmitChar(
                  aiReplies[a].author,
                  "forum",
                  { allowGroupChatFamily: true },
                );
                if (!_forumAutoGuard || _forumAutoGuard.allowed !== true)
                  continue;
              }
              floor++;
              targetPost.replies.push({
                floor: floor + 1,
                author: aiReplies[a].author,
                content: aiReplies[a].content,
                likes: Math.floor(Math.random() * 10),
                time: _forumGameTime,
              });
            }
          }
          manager.saveUserPosts();
          yqToast("success", "网友已回复你的帖子");
          try {
            if (typeof window.yqCharAppendEvent === "function") {
              for (var _ar = 0; _ar < aiReplies.length; _ar++) {
                if (!aiReplies[_ar] || !aiReplies[_ar].author) continue;
                var _forumReplyEvt = window.yqCharAppendEvent({
                  charId: aiReplies[_ar].author,
                  source: "forum",
                  channel: "forum",
                  action: "forum_reply_posted",
                  payload: {
                    postId: newPostId,
                    title: title,
                    content: aiReplies[_ar].content || "",
                  },
                });
                if (
                  _forumReplyEvt &&
                  typeof window.yqApplyLinkRulesByEvent === "function"
                ) {
                  window.yqApplyLinkRulesByEvent(_forumReplyEvt);
                }
                if (typeof window.yqMarkAutoEmitChar === "function") {
                  window.yqMarkAutoEmitChar(aiReplies[_ar].author, "forum");
                }
              }
            }
          } catch (_forumReplyEvtErr) {}
        }
      }
    }
  } catch (e) {
    console.warn("[论坛AI互动] 发帖回复生成失败:", e);
    yqToast("error", "AI互动生成失败: " + (e.message || ""));
  }

  // 刷新面板显示AI回复
  renderForumPanelIfChanged();

  // 将论坛数据注入主AI上下文
  injectNpcSummaryToContext();
}

