function setWallpaper(imageUrl) {
  const $screen = $("#mobile-phone-overlay .mobile-phone-screen");

  if ($screen.length === 0) {
    return;
  }

  // 使用 setProperty 和 important 标记来覆盖样式表中的 !important
  const screenElement = $screen[0];
  screenElement.style.setProperty(
    "background-image",
    `url(${imageUrl})`,
    "important",
  );
  screenElement.style.setProperty("background-size", "cover", "important");
  screenElement.style.setProperty("background-position", "center", "important");
  screenElement.style.setProperty(
    "background-repeat",
    "no-repeat",
    "important",
  );

  // 保存到localStorage
  try {
    localStorage.setItem("moshen-phone-wallpaper", imageUrl);
  } catch (e) {}

  // 显示提示
  if (typeof toastr !== "undefined") {
    yqToast("success", "壁纸已更换");
  }
}

// 恢复壁纸
function restoreWallpaper() {
  try {
    var savedWallpaper = localStorage.getItem("moshen-phone-wallpaper");

    // 验证保存的壁纸URL是否有效（支持http URL和data: base64）
    if (
      !savedWallpaper ||
      savedWallpaper.trim() === "" ||
      (!savedWallpaper.startsWith("http") &&
        !savedWallpaper.startsWith("data:"))
    ) {
      return; // 无有效壁纸，使用CSS默认样式
    }

    var $screen = $("#mobile-phone-overlay .mobile-phone-screen");
    if ($screen.length > 0) {
      var screenElement = $screen[0];
      screenElement.style.setProperty(
        "background-image",
        "url(" + savedWallpaper + ")",
        "important",
      );
      screenElement.style.setProperty("background-size", "cover", "important");
      screenElement.style.setProperty(
        "background-position",
        "center",
        "important",
      );
      screenElement.style.setProperty(
        "background-repeat",
        "no-repeat",
        "important",
      );
    }
  } catch (e) {
    console.error("恢复壁纸失败:", e);
  }
}

// 上传自定义壁纸
function uploadCustomWallpaper(file) {
  // 验证文件类型
  if (!file.type.startsWith("image/")) {
    if (typeof toastr !== "undefined") {
      yqToast("error", "请选择图片文件");
    }
    return;
  }

  // 验证文件大小（限制为10MB）
  var maxSize = 10 * 1024 * 1024;
  if (file.size > maxSize) {
    if (typeof toastr !== "undefined") {
      yqToast("error", "图片文件大小不能超过10MB");
    }
    return;
  }

  // 使用FileReader读取图片
  var reader = new FileReader();

  reader.onload = function (e) {
    var imageDataUrl = e.target.result;

    // 创建Image对象验证并压缩图片
    var img = new Image();
    img.onload = function () {
      // 压缩图片以适应localStorage（目标<500KB）
      var canvas = document.createElement("canvas");
      var maxW = 800;
      var maxH = 1200;
      var w = img.width;
      var h = img.height;
      if (w > maxW || h > maxH) {
        var ratio = Math.min(maxW / w, maxH / h);
        w = Math.round(w * ratio);
        h = Math.round(h * ratio);
      }
      canvas.width = w;
      canvas.height = h;
      var ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, w, h);
      var compressed = canvas.toDataURL("image/jpeg", 0.7);

      // 设置为壁纸
      setWallpaper(compressed);

      if (typeof toastr !== "undefined") {
        yqToast("success", "自定义壁纸已上传");
      }

      // 重置文件输入框
      $("#wallpaper-upload-input").val("");
    };

    img.onerror = function () {
      if (typeof toastr !== "undefined") {
        yqToast("error", "图片加载失败，请选择有效的图片文件");
      }
      $("#wallpaper-upload-input").val("");
    };

    img.src = imageDataUrl;
  };

  reader.onerror = function () {
    if (typeof toastr !== "undefined") {
      yqToast("error", "文件读取失败");
    }
    $("#wallpaper-upload-input").val("");
  };

  reader.readAsDataURL(file);
}

