/**
 * 导出手机数据为JSON文件
 * @param {boolean} includeImages - 是否包含图片（含图片文件会很大）
 */
function phoneExportData(includeImages) {
  try {
    yqToast("info", "正在收集数据...", "📦 导出");
    var exportObj = {
      _version: "14",
      _exportTime: new Date().toISOString(),
      _type: "full",
    };
    // 收集所有phoneMeta键
    var metaKeys = [
      "known_friends",
      "yinqi_friend_alias",
      "yinqi_friend_alias_norm",
      "yinqi_friend_meta",
      "yinqi_friend_graph_version",
      "yinqi_friend_ui_migrate_v1",
      "friend_requests",
      "friend_request_history",
      "blocked_friends",
      "pinned_friends",
      "groups",
      "group_invites",
      "social_seed_state",
      "yinqi_social_config",
      "moments",
      "hidden_friends",
      "forum_data",
      "forum_commented",
      "forum_user_posts",
      "cam_history",
      "npc_messages",
      "chat_history",
      "unreads",
      "moments_unread",
      "world_events_unread",
      "forum_unread",
      "image_index",
      "cam_tag_cache",
      "cam_images",
      "imageGen_settings",
      "live_rooms",
      "live_unread",
      "live_interactions",
      "chat_avatars",
      "ai_awareness_settings",
      "ai_awareness_v2",
      "ui_theme_config_v1",
      "character_appearances",
      "char_appearance_enabled",
      "phone_wardrobe",
      "phone_wardrobe_instances",
      "phone_wardrobe_schema_version",
      "phone_wardrobe_legacy_backup",
      "phone_wardrobe_diag_stats",
      "forum_nickname",
      "live_nickname",
      "phone_story_live_events",
      "forum_summary_user",
      "forum_summary_commented",
      "live_summary",
      "operation_log",
      "perf_mode",
      "perf_cache",
      "yinqi_char_timeline",
      "yinqi_char_facts",
      "yinqi_char_runtime_state",
      "yinqi_consistency_guard",
      "yinqi_char_channel_lock",
      "yinqi_link_rules",
      "yinqi_cross_feed",
      "yinqi_task_history",
      "yinqi_surveillance_targets",
      "yinqi_plot_task",
      "yinqi_outposts",
      "yinqi_forum_tasks",
    ];
    exportObj.phoneMeta = {};
    for (var i = 0; i < metaKeys.length; i++) {
      exportObj.phoneMeta[metaKeys[i]] = getPhoneMeta(metaKeys[i], null);
    }
    // 收集localStorage项
    exportObj.localStorage = {};
    for (var j = 0; j < localStorage.length; j++) {
      var k = localStorage.key(j);
      if (
        k &&
        (k.startsWith("yinqi-") ||
          k.startsWith("moshen-") ||
          k === "forum_auto_generate" ||
          k.startsWith("mobile-phone-") ||
          k.startsWith("mobile-last-") ||
          k.startsWith("mobile-trigger-btn-"))
      ) {
        exportObj.localStorage[k] = localStorage.getItem(k);
      }
    }
    if (!includeImages) {
      _triggerDownload(exportObj, "phone-data-no-img");
      return;
    }
    // 含图片：从IndexedDB读取所有图片
    var imgIndex = getPhoneMetaBig("image_index", []);
    var imgIds = imgIndex.map(function (e) {
      return e.id;
    });
    // 也收集cam_images中的imageId
    var camImgs = getPhoneMetaBig("cam_images", {});
    var camVals = Object.values(camImgs);
    for (var ci = 0; ci < camVals.length; ci++) {
      if (
        camVals[ci] &&
        typeof camVals[ci] === "string" &&
        camVals[ci].indexOf("data:") !== 0 &&
        imgIds.indexOf(camVals[ci]) === -1
      ) {
        imgIds.push(camVals[ci]);
      }
    }
    if (imgIds.length === 0 || !window.phoneImageStore) {
      _triggerDownload(exportObj, "phone-data-full");
      return;
    }
    // 流式写入图片，逐张加载后立即写入chunk并释放内存
    var total = imgIds.length;
    var loaded = 0;
    var failed = 0;
    yqToast("info", "正在导出 " + total + " 张图片...", "📦 导出");
    var headerJson = JSON.stringify(exportObj);
    // 在末尾的 } 前插入 ,"images":{
    var chunks = [headerJson.slice(0, -1) + ',"images":{'];
    headerJson = null;
    exportObj = null; // 释放引用
    var isFirst = true;
    var doLoad = function (idx) {
      if (idx >= total) {
        chunks.push("}}");
        var blob = new Blob(chunks, { type: "application/json" });
        chunks = null;
        _triggerDownloadBlob(blob, "phone-data-full");
        if (failed > 0)
          yqToast("warning", failed + " 张图片加载失败已跳过", "📦 导出");
        return;
      }
      window.phoneImageStore
        .loadAsync(imgIds[idx])
        .then(function (data) {
          if (data) {
            var prefix = isFirst ? "" : ",";
            chunks.push(
              prefix + JSON.stringify(imgIds[idx]) + ":" + JSON.stringify(data),
            );
            isFirst = false;
            delete window.phoneImageStore._cache[imgIds[idx]];
          } else {
            failed++;
          }
          loaded++;
          if (loaded % 10 === 0)
            yqToast(
              "info",
              "已处理 " + loaded + "/" + total + " 张...",
              "📦 导出",
            );
          setTimeout(function () {
            doLoad(idx + 1);
          }, 0);
        })
        .catch(function () {
          failed++;
          loaded++;
          setTimeout(function () {
            doLoad(idx + 1);
          }, 0);
        });
    };
    doLoad(0);
  } catch (e) {
    console.error("[导出] 失败:", e);
    yqToast("error", "导出失败: " + e.message);
  }
}

/**
 * 仅导出相册数据（image_index + 图片）
 * v14: 流式写入，逐张加载图片后立即写入Blob chunk并释放内存，防止大量图片OOM
 */
function phoneExportGallery() {
  try {
    yqToast("info", "正在收集相册数据...", "💾 相册导出");
    var imageIndex = getPhoneMetaBig("image_index", []);
    if (imageIndex.length === 0) {
      yqToast("warning", "相册为空，无需导出");
      return;
    }
    var imgIds = imageIndex.map(function (e) {
      return e.id;
    });
    // 也包含cam_images引用的图片
    var camImgs = getPhoneMetaBig("cam_images", {});
    var camVals = Object.values(camImgs);
    for (var ci = 0; ci < camVals.length; ci++) {
      if (
        camVals[ci] &&
        typeof camVals[ci] === "string" &&
        camVals[ci].indexOf("data:") !== 0 &&
        imgIds.indexOf(camVals[ci]) === -1
      ) {
        imgIds.push(camVals[ci]);
      }
    }
    // 构建头部JSON（不含images），流式拼接images
    var header = {
      _version: "14",
      _exportTime: new Date().toISOString(),
      _type: "gallery",
      image_index: imageIndex,
      cam_images: camImgs,
    };
    if (!window.phoneImageStore || imgIds.length === 0) {
      header.images = {};
      _triggerDownload(header, "phone-gallery");
      return;
    }
    var total = imgIds.length;
    var loaded = 0;
    var failed = 0;
    yqToast("info", "正在导出 " + total + " 张图片...", "💾 相册导出");
    // 流式写入：先写header（去掉末尾的}），逐张追加图片，最后闭合
    var headerJson = JSON.stringify(header);
    // 在末尾的 } 前插入 ,"images":{
    var chunks = [headerJson.slice(0, -1) + ',"images":{'];
    var isFirst = true;
    var doLoad = function (idx) {
      if (idx >= total) {
        // 闭合 images 对象和根对象
        chunks.push("}}");
        var blob = new Blob(chunks, { type: "application/json" });
        // 释放chunks引用
        chunks = null;
        _triggerDownloadBlob(blob, "phone-gallery");
        if (failed > 0)
          yqToast("warning", failed + " 张图片加载失败已跳过", "💾 相册导出");
        return;
      }
      window.phoneImageStore
        .loadAsync(imgIds[idx])
        .then(function (data) {
          if (data) {
            var prefix = isFirst ? "" : ",";
            chunks.push(
              prefix + JSON.stringify(imgIds[idx]) + ":" + JSON.stringify(data),
            );
            isFirst = false;
            // 从内存缓存中移除已写入的图片，释放内存
            delete window.phoneImageStore._cache[imgIds[idx]];
          } else {
            failed++;
          }
          loaded++;
          if (loaded % 10 === 0)
            yqToast(
              "info",
              "已处理 " + loaded + "/" + total + " 张...",
              "💾 相册导出",
            );
          // 让出主线程，防止长时间阻塞UI
          setTimeout(function () {
            doLoad(idx + 1);
          }, 0);
        })
        .catch(function () {
          failed++;
          loaded++;
          setTimeout(function () {
            doLoad(idx + 1);
          }, 0);
        });
    };
    doLoad(0);
  } catch (e) {
    console.error("[相册导出] 失败:", e);
    yqToast("error", "相册导出失败: " + e.message);
  }
}

/**
 * 触发浏览器下载JSON文件（从对象）
 */
function _triggerDownload(obj, prefix) {
  try {
    var json = JSON.stringify(obj);
    var blob = new Blob([json], { type: "application/json" });
    json = null; // 释放字符串内存
    _triggerDownloadBlob(blob, prefix);
  } catch (e) {
    console.error("[下载] 失败:", e);
    yqToast("error", "下载失败: " + e.message);
  }
}

/**
 * 触发浏览器下载（从Blob，用于流式导出）
 */
function _triggerDownloadBlob(blob, prefix) {
  try {
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    var ts = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
    a.href = url;
    a.download = prefix + "_" + ts + ".json";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () {
      URL.revokeObjectURL(url);
    }, 1000);
    var sizeMB = (blob.size / 1024 / 1024).toFixed(1);
    yqToast("success", "导出完成 (" + sizeMB + "MB)", "📦 导出");
  } catch (e) {
    console.error("[下载] 失败:", e);
    yqToast("error", "下载失败: " + e.message);
  }
}

/**
 * 导入手机数据（完整导入）
 * @param {string} jsonStr - JSON字符串
 */
function phoneImportData(jsonStr) {
  try {
    var data = JSON.parse(jsonStr);
    if (!data._type || !data._version) {
      yqToast("error", "无效的导出文件");
      return;
    }
    if (data._type === "gallery") {
      // 已解析的gallery数据直接传对象，避免二次解析
      _doImportGalleryParsed(data);
      return;
    }
    if (
      !confirm(
        "确定导入手机数据吗？\n当前所有手机数据将被覆盖。\n\n导出时间: " +
          (data._exportTime || "未知"),
      )
    )
      return;
    yqToast("info", "正在导入...", "📥 导入");
    // 恢复phoneMeta
    if (data.phoneMeta) {
      var keys = Object.keys(data.phoneMeta);
      for (var i = 0; i < keys.length; i++) {
        if (
          data.phoneMeta[keys[i]] !== null &&
          data.phoneMeta[keys[i]] !== undefined
        ) {
          setPhoneMeta(keys[i], data.phoneMeta[keys[i]]);
        }
      }
      debounceSavePhoneMeta();
    }
    // 恢复localStorage
    if (data.localStorage) {
      var lsKeys = Object.keys(data.localStorage);
      for (var j = 0; j < lsKeys.length; j++) {
        localStorage.setItem(lsKeys[j], data.localStorage[lsKeys[j]]);
      }
    }
    // 恢复图片到IndexedDB
    if (data.images && window.phoneImageStore) {
      var imgKeys = Object.keys(data.images);
      var restored = 0;
      var doRestore = function (idx) {
        if (idx >= imgKeys.length) {
          data.images = null;
          yqToast(
            "success",
            "导入完成！已恢复 " + restored + " 张图片\n请刷新手机界面查看",
            "📥 导入",
          );
          // 刷新当前面板
          try {
            if (currentPanel) {
              $("#phone-app-body").html(generateSizeSettingsPanel());
              bindPanelButtons();
            }
          } catch (e2) {}
          return;
        }
        var id = imgKeys[idx];
        var imgData = data.images[id];
        delete data.images[id]; // 写入后释放内存
        if (!imgData) {
          doRestore(idx + 1);
          return;
        }
        window.phoneImageStore._cache[id] = imgData;
        window.phoneImageStore._dbPut(id, imgData).then(function () {
          restored++;
          if (restored % 20 === 0)
            yqToast(
              "info",
              "已恢复 " + restored + "/" + imgKeys.length + " 张...",
              "📥 导入",
            );
          setTimeout(function () {
            doRestore(idx + 1);
          }, 0);
        });
      };
      doRestore(0);
    } else {
      yqToast("success", "导入完成！请刷新手机界面查看", "📥 导入");
      try {
        if (currentPanel) {
          $("#phone-app-body").html(generateSizeSettingsPanel());
          bindPanelButtons();
        }
      } catch (e2) {}
    }
  } catch (e) {
    console.error("[导入] 失败:", e);
    yqToast("error", "导入失败: " + e.message);
  }
}

/**
 * 导入相册数据（合并模式，不覆盖现有数据）
 * v14: 支持流式解析大文件——先提取header（image_index/cam_images），再逐个提取images
 * @param {string|Blob|File} input - JSON字符串或File/Blob对象
 */
function phoneImportGallery(input) {
  try {
    // 如果传入的是字符串且不太大（<50MB），直接JSON.parse
    if (typeof input === "string" && input.length < 50 * 1024 * 1024) {
      _doImportGalleryParsed(JSON.parse(input));
      return;
    }
    // 大文件或Blob/File：流式解析
    var blob = typeof input === "string" ? new Blob([input]) : input;
    yqToast("info", "正在解析大文件...", "📥 相册导入");
    // 用Response.json()比JSON.parse更高效（浏览器原生流式解析）
    new Response(blob)
      .json()
      .then(function (data) {
        _doImportGalleryParsed(data);
      })
      .catch(function (e) {
        console.error("[相册导入] JSON解析失败，尝试修复:", e);
        // 可能是文件末尾截断，尝试读取文本后手动修复
        new Response(blob)
          .text()
          .then(function (text) {
            // 检查是否末尾缺少闭合括号
            var trimmed = text.trimEnd();
            if (
              trimmed.charAt(trimmed.length - 1) !== "}" &&
              trimmed.indexOf('"images"') !== -1
            ) {
              // 尝试补全闭合括号
              var fixed = trimmed + "}}";
              try {
                var data2 = JSON.parse(fixed);
                yqToast("warning", "文件末尾不完整，已自动修复", "📥 相册导入");
                _doImportGalleryParsed(data2);
                return;
              } catch (e2) {}
            }
            yqToast(
              "error",
              "相册文件格式损坏，无法导入: " + e.message,
              "📥 相册导入",
            );
          })
          .catch(function () {
            yqToast("error", "文件读取失败", "📥 相册导入");
          });
      });
  } catch (e) {
    console.error("[相册导入] 失败:", e);
    yqToast("error", "相册导入失败: " + e.message);
  }
}

/**
 * 实际执行相册导入（已解析的数据对象）
 */
function _doImportGalleryParsed(data) {
  try {
    if (!data || !data.image_index) {
      yqToast("error", "无效的相册导出文件");
      return;
    }
    var newCount = data.image_index.length;
    if (
      !confirm(
        "确定导入相册吗？\n将合并 " +
          newCount +
          " 条图片记录到当前相册。\n已有的同ID图片不会重复导入。",
      )
    )
      return;
    yqToast("info", "正在导入相册...", "📥 相册导入");
    // 合并image_index（去重）
    var currentIdx = getPhoneMetaBig("image_index", []);
    var existingIds = {};
    for (var i = 0; i < currentIdx.length; i++)
      existingIds[currentIdx[i].id] = true;
    var added = 0;
    for (var j = 0; j < data.image_index.length; j++) {
      if (!existingIds[data.image_index[j].id]) {
        currentIdx.push(data.image_index[j]);
        added++;
      }
    }
    // 按时间戳排序（新的在前）
    currentIdx.sort(function (a, b) {
      return (b.timestamp || 0) - (a.timestamp || 0);
    });
    setPhoneMetaBig("image_index", currentIdx);
    // 合并cam_images
    if (data.cam_images) {
      var curCam = getPhoneMetaBig("cam_images", {});
      var camKeys = Object.keys(data.cam_images);
      for (var ck = 0; ck < camKeys.length; ck++) {
        if (!curCam[camKeys[ck]])
          curCam[camKeys[ck]] = data.cam_images[camKeys[ck]];
      }
      setPhoneMetaBig("cam_images", curCam);
    }
    debounceSavePhoneMeta();
    // 恢复图片到IndexedDB（逐张写入后释放内存）
    if (data.images && window.phoneImageStore) {
      var imgKeys = Object.keys(data.images);
      var restored = 0;
      var doRestore = function (idx) {
        if (idx >= imgKeys.length) {
          // 释放images引用，让GC回收
          data.images = null;
          data = null;
          yqToast(
            "success",
            "相册导入完成！新增 " +
              added +
              " 条记录，恢复 " +
              restored +
              " 张图片",
            "📥 相册导入",
          );
          return;
        }
        var id = imgKeys[idx];
        var imgData = data.images[id];
        // 写入后立即从data中删除，释放内存
        delete data.images[id];
        if (!imgData) {
          doRestore(idx + 1);
          return;
        }
        window.phoneImageStore._cache[id] = imgData;
        window.phoneImageStore._dbPut(id, imgData).then(function () {
          restored++;
          if (restored % 20 === 0)
            yqToast(
              "info",
              "已恢复 " + restored + "/" + imgKeys.length + " 张...",
              "📥 相册导入",
            );
          // 让出主线程
          setTimeout(function () {
            doRestore(idx + 1);
          }, 0);
        });
      };
      doRestore(0);
    } else {
      yqToast(
        "success",
        "相册索引导入完成！新增 " + added + " 条记录（无图片数据）",
        "📥 相册导入",
      );
    }
  } catch (e) {
    console.error("[相册导入] 失败:", e);
    yqToast("error", "相册导入失败: " + e.message);
  }
}

/**
 * 重建相册索引 — 扫描IndexedDB中所有残留图片，重新生成image_index
 * 用于删除聊天后恢复孤立图片的访问
 */
function phoneRebuildImageIndex() {
  if (!window.phoneImageStore) {
    yqToast("error", "图片存储未初始化");
    return;
  }
  yqToast("info", "正在扫描本地图片数据库...", "🔄 重建索引");
  window.phoneImageStore.getAllKeys().then(function (allKeys) {
    if (!allKeys || allKeys.length === 0) {
      yqToast("warning", "本地数据库中没有找到任何图片");
      return;
    }
    // 获取当前索引，找出已有的ID
    var currentIdx = getPhoneMetaBig("image_index", []);
    var existingIds = {};
    for (var i = 0; i < currentIdx.length; i++)
      existingIds[currentIdx[i].id] = true;
    // 找出孤立图片（在DB中但不在索引中）
    var orphanKeys = [];
    for (var j = 0; j < allKeys.length; j++) {
      if (!existingIds[allKeys[j]]) orphanKeys.push(allKeys[j]);
    }
    if (orphanKeys.length === 0) {
      yqToast(
        "info",
        "所有图片都已有索引，无需重建（共 " + currentIdx.length + " 条）",
      );
      return;
    }
    // 为孤立图片创建索引记录
    var added = 0;
    for (var k = 0; k < orphanKeys.length; k++) {
      var id = orphanKeys[k];
      var source = "recovered";
      var tag = "恢复";
      if (id.indexOf("cam-") === 0) {
        source = "surveillance";
        tag = "监控";
      }
      currentIdx.push({
        id: id,
        source: source,
        location: "",
        description: "（索引重建恢复）",
        time: new Date().toLocaleString(),
        tag: tag,
        size: { w: 1024, h: 1024 },
        timestamp: Date.now() - (orphanKeys.length - k),
        hasImage: true,
      });
      added++;
    }
    // 按时间戳排序
    currentIdx.sort(function (a, b) {
      return (b.timestamp || 0) - (a.timestamp || 0);
    });
    setPhoneMetaBig("image_index", currentIdx);
    debounceSavePhoneMeta();
    // 预加载到内存缓存
    window.phoneImageStore.preload(orphanKeys);
    yqToast(
      "success",
      "重建完成！恢复了 " +
        added +
        " 张孤立图片\n原有索引 " +
        Object.keys(existingIds).length +
        " 条保留",
      "🔄 重建索引",
    );
  });
}

