  /** 执行骰子判定并返回结果 */
  function _performDiceCheck(dc, modifier) {
    var roll = _rollD20();
    var total = roll + modifier;
    var success = false;
    var resultLabel = "";
    if (roll === 20) {
      success = true;
      resultLabel = "大成功（自然20）";
    } else if (roll === 1) {
      success = false;
      resultLabel = "大失败（自然1）";
    } else if (total >= dc + 5) {
      success = true;
      resultLabel = "大成功";
    } else if (total >= dc) {
      success = true;
      resultLabel = "成功";
    } else if (total <= dc - 5) {
      success = false;
      resultLabel = "大失败";
    } else {
      success = false;
      resultLabel = "失败";
    }
    return {
      roll: roll,
      total: total,
      success: success,
      resultLabel: resultLabel,
    };
  }

  /** 将安装成功的设备写入MVU — [V8.2+ Round-6] 改用 commitMvuPatch 增量写入，不再整体替换 */
  function _writeSurveillanceToMvu(action, target) {
    try {
      var d = fetchLatestMvuData(false);
      if (!d) {
        console.warn("[监控系统] 无法获取MVU数据");
        return false;
      }
      var curTime = _getGameTimeCompat() || "未知时间";
      var patch = {};

      if (action === "camera") {
        var cams = _.cloneDeep(_.get(d, "user.监控设施.已安装摄像头", {}));
        cams[target] = {
          具体位置: target,
          安装时间: curTime,
          状态: "正常运行",
        };
        patch["user.监控设施.已安装摄像头"] = cams;
      } else {
        var bds = _.cloneDeep(_.get(d, "user.监控设施.已植入后门", {}));
        bds[target + "手机"] = {
          所有者: target,
          设备类型: "手机后门",
          植入时间: curTime,
          可用功能:
            "远程开启麦克风、读取聊天记录和通话记录、实时定位追踪、截取屏幕内容",
        };
        patch["user.监控设施.已植入后门"] = bds;
        // 同时添加对应的手机后门摄像头条目
        var cams2 = _.cloneDeep(_.get(d, "user.监控设施.已安装摄像头", {}));
        cams2["手机后门:" + target] = {
          具体位置: target + "手机全景摄像头",
          安装时间: curTime,
          状态: "正常运行",
        };
        patch["user.监控设施.已安装摄像头"] = cams2;
      }

      return commitMvuPatch(patch, { source: "surveillance_" + action });
    } catch (e) {
      console.warn("[监控系统] MVU写入失败:", e);
      return false;
    }
  }

  /** 从MVU中删除监控设备 */
  function _removeSurveillanceFromMvu(key, type) {
    try {
      var rawData = fetchRawMvuData();
      if (!rawData || !rawData.stat_data) return false;
      var d = rawData.stat_data;
      if (type === "phone") {
        // 删除后门：需要从摄像头key反推后门key
        var bds = _.get(d, "user.监控设施.已植入后门", {});
        var bdKeys = Object.keys(bds);
        var foundBdKey = null;
        for (var i = 0; i < bdKeys.length; i++) {
          var owner = bds[bdKeys[i]].所有者 || "";
          // 匹配逻辑：摄像头key可能是 "手机后门" / "手机后门:林知意" / "林知意手机" 等
          if (bdKeys[i] === key) {
            foundBdKey = bdKeys[i];
            break;
          }
          // 摄像头key包含后门owner名（如 "手机后门:林知意" 包含 "林知意"）
          if (owner && key.indexOf(owner) >= 0) {
            foundBdKey = bdKeys[i];
            break;
          }
          // "手机后门:林知意" → 提取"林知意"匹配后门owner
          var extracted = key.replace("手机后门:", "").replace("手机后门", "");
          if (
            extracted &&
            owner &&
            key.indexOf("手机后门") >= 0 &&
            owner.indexOf(extracted) >= 0
          ) {
            foundBdKey = bdKeys[i];
            break;
          }
          // 旧格式兼容：摄像头key是"手机后门"（无冒号），通过摄像头具体位置反查owner
          if (key === "手机后门" && owner) {
            var camEntry = _.get(d, "user.监控设施.已安装摄像头." + key, {});
            var camPos = camEntry.具体位置 || "";
            if (camPos.indexOf(owner) >= 0) {
              foundBdKey = bdKeys[i];
              break;
            }
          }
        }
        // 最终兜底：如果key是"手机后门"且只有一个后门，直接匹配
        if (!foundBdKey && key === "手机后门" && bdKeys.length === 1) {
          foundBdKey = bdKeys[0];
        }
        var deletedOwner = foundBdKey
          ? (bds[foundBdKey] || {}).所有者 || foundBdKey
          : key;
        if (foundBdKey) delete bds[foundBdKey];
        _.set(d, "user.监控设施.已植入后门", bds);
        // 删除对应的摄像头条目
        var cams = _.get(d, "user.监控设施.已安装摄像头", {});
        // 直接匹配
        if (cams[key]) delete cams[key];
        // 模糊匹配：所有含"手机后门"的key，且与被删后门的owner相关
        var camKeys = Object.keys(cams);
        for (var j = 0; j < camKeys.length; j++) {
          if (camKeys[j].indexOf("手机后门") >= 0) {
            // 如果摄像头key包含owner名，或者就是"手机后门"（旧格式）
            if (
              camKeys[j] === key ||
              camKeys[j].indexOf(deletedOwner.replace("手机", "")) >= 0
            ) {
              delete cams[camKeys[j]];
            }
          }
        }
        _.set(d, "user.监控设施.已安装摄像头", cams);
      } else {
        // 删除摄像头
        var cams3 = _.get(d, "user.监控设施.已安装摄像头", {});
        delete cams3[key];
        _.set(d, "user.监控设施.已安装摄像头", cams3);
      }
      rawData.stat_data = d;
      if (typeof Mvu !== "undefined" && Mvu.replaceMvuData) {
        Mvu.replaceMvuData(rawData, { type: "message", message_id: "latest" });
      }
      return true;
    } catch (e) {
      console.warn("[监控系统] MVU删除失败:", e);
      return false;
    }
  }

