  window.phoneInstallCamera = function () {
    var d = currentPhoneData || {};
    var cams = _.get(d, "user.监控设施.已安装摄像头", {});
    var camCount = Object.keys(cams).length;
    if (camCount >= CAM_MAX) {
      yqToast("warning", "摄像头已达上限（" + CAM_MAX + "个）");
      return;
    }
    if (_checkPerTurnLimit()) {
      yqToast("warning", "本轮已使用过安装/入侵机会，请等待AI回复后再试");
      return;
    }

    // 构建选择弹窗
    var rooms = _getVillaRoomPresets();
    var installed = Object.keys(cams);
    // 过滤已安装的
    var available = [];
    for (var i = 0; i < rooms.length; i++) {
      var alreadyInstalled = false;
      for (var j = 0; j < installed.length; j++) {
        if (installed[j] === rooms[i] || installed[j].indexOf(rooms[i]) >= 0) {
          alreadyInstalled = true;
          break;
        }
      }
      if (!alreadyInstalled) available.push(rooms[i]);
    }

    var options = "";
    for (var k = 0; k < available.length; k++) {
      options += available[k] + "\n";
    }
    var msg = "📷 选择安装位置（输入序号或自定义位置名）\n\n";
    msg += "── 可选安装位置 ──\n";
    for (var m = 0; m < available.length; m++) {
      msg += m + 1 + ". " + available[m] + "\n";
    }
    msg += "\n输入序号选择，或直接输入自定义位置名：";

    var input = prompt(msg);
    if (!input || !input.trim()) return;
    input = input.trim();

    var target = "";
    var num = parseInt(input);
    if (!isNaN(num) && num >= 1 && num <= available.length) {
      target = available[num - 1];
    } else {
      target = input;
      // 验证自定义目标
      if (!_validateCustomTarget(target, "camera")) {
        yqToast(
          "error",
          "无法识别的位置「" + target + "」，请输入已知地点名称",
        );
        return;
      }
      // 检查是否已安装
      for (var c = 0; c < installed.length; c++) {
        if (
          installed[c] === target ||
          installed[c].indexOf(target) >= 0 ||
          target.indexOf(installed[c]) >= 0
        ) {
          yqToast("warning", "该位置已安装摄像头");
          return;
        }
      }
    }

    // 执行骰子检定
    var modifier = 3; // 监控技术操作 +3
    var dc = _calculateDC("camera");
    var result = _performDiceCheck(dc, modifier);

    // 标记本轮已使用
    _markPerTurnUsed();

    // 构建结果提示
    var toastMsg =
      "🎲 D20=" +
      result.roll +
      "+" +
      modifier +
      "=" +
      result.total +
      " vs DC" +
      dc +
      " → " +
      result.resultLabel;
    if (result.success) {
      // 写入MVU
      var written = _writeSurveillanceToMvu("camera", target);
      if (written) {
        yqToast(
          "success",
          toastMsg + "\n📷 已在「" + target + "」成功安装摄像头",
        );
      } else {
        yqToast("warning", toastMsg + "\n安装成功但数据写入失败，请重试");
        return;
      }
    } else {
      yqToast("error", toastMsg + "\n📷 在「" + target + "」安装摄像头失败");
    }

    // 插入事件楼层
    var floorContent = _buildSurveillanceEventContent(
      "camera",
      target,
      result.success,
      result.roll,
      dc,
      modifier,
      result.total,
      result.resultLabel,
    );
    _insertSurveillanceFloor(floorContent);

    // 刷新面板
    setTimeout(function () {
      refreshPhoneData();
      renderPhonePanelIfChanged(
        "surveillance",
        generateSurveillancePanel(currentPhoneData),
