    // 获取监控详情文字：优先实时摘要，其次回退最新扩写
    var sceneText = _yqGetSurveillanceRealtimeSummary(locationName);
    // 第二优先：如果摘要中有匹配，尝试用cam_history的扩写版本（内容更丰富）
