    if (sceneText) {
      var camHistory = getPhoneMetaBig("cam_history", {});
      var records = camHistory[locationName] || [];
      if (records.length > 0 && records[0].content) {
        sceneText = records[0].content;
      }
    } else {
      // 摘要中没找到，回退到cam_history
      var camHistory = getPhoneMetaBig("cam_history", {});
      var records = camHistory[locationName] || [];
      if (records.length > 0) {
        sceneText = records[0].content || "";
      }
