        .prop("disabled", true)
        .css({ background: "#374151", cursor: "not-allowed" });
      $imgBtn.find(".cam-genimg-text").text("生成中...");
    }
    var $imgArea = _isViewingThisDetail ? $(".cam-detail-image-area") : $([]);

    try {
      var result;
      if (cachedEntry && cachedEntry.tag) {
        // 有缓存tag，直接生成图片（手动模式快速出图）
        if ($imgArea.length > 0) {
          $imgArea.html(
            '<div style="text-align:center;padding:20px;"><i class="fas fa-spinner fa-spin" style="font-size:24px;color:#10b981;"></i><div style="color:#9ca3af;font-size:11px;margin-top:8px;">插件正在生成图片...</div></div>',
