        delete camTagCache[locationName];
        setPhoneMeta("cam_tag_cache", camTagCache);
      } else {
        // 无缓存，完整流程（tag + 图片）
        if ($imgArea.length > 0) {
          $imgArea.html(
            '<div style="text-align:center;padding:20px;"><i class="fas fa-spinner fa-spin" style="font-size:24px;color:#3b82f6;"></i><div style="color:#9ca3af;font-size:11px;margin-top:8px;">LLM正在生成tag...</div></div>',
          );
        }
        // [V10.6] 优先用统一 ctx 构造函数（修复 BUG 1）
        var _survCtxB =
          typeof window.buildSurveillanceImageGenContext === "function"
            ? window.buildSurveillanceImageGenContext(locationName, sceneText, {
                primaryType: "location",
              })
            : { location: locationName, sceneText: sceneText };
        _survCtxB.time = new Date().toLocaleString();
        result = await window.phoneGenerateImage("surveillance", _survCtxB);
      }

      if (result.success && result.imageData) {
        // v13: cam_images 存 imageId 引用，不再存 base64
        var camImages = getPhoneMetaBig("cam_images", {});
        camImages[locationName] = result.imageId || "";
        setPhoneMetaBig("cam_images", camImages);

        // 显示图片（支持双击重Roll）
        var imgId = result.imageId || "";
        if ($imgArea.length > 0) {
          $imgArea.html(
            '<div style="text-align:center;">' +
              '<img src="' +
              result.imageData +
              '" data-image-id="' +
              escapeHtml(imgId) +
              '" ' +
              'style="max-width:100%;border-radius:8px;border:1px solid #334155;cursor:pointer;" ' +
              'class="cam-detail-viewable-img" ' +
              "onerror=\"this.parentElement.innerHTML='<div style=color:#ef4444;padding:12px;>图片加载失败</div>'\" />" +
              '<div style="font-size:10px;color:#6b7280;margin-top:6px;">🎨 ' +
              escapeHtml(locationName) +
              ' 监控画面 <span style="color:#4b5563;">(双击重Roll)</span></div>' +
              "</div>",
          );
          // 绑定双击重Roll
          $imgArea
            .find("img[data-image-id]")
            .off("dblclick")
            .on("dblclick", function (e) {
              e.preventDefault();
              e.stopPropagation();
              var iid = $(this).data("image-id");
              if (!iid) return;
              var $img = $(this);
              $img.css("opacity", "0.5");
              yqToast("info", "正在重Roll...", "🎨 监控");
              window.phoneRerollImage(iid).then(function (rr) {
                if (rr.success && rr.imageData) {
                  $img.attr("src", rr.imageData).css("opacity", "1");
                  // v13: cam_images 存 imageId 引用
                  var newId = rr.imageId || iid;
                  var ci = getPhoneMetaBig("cam_images", {});
                  ci[locationName] = newId;
                  setPhoneMetaBig("cam_images", ci);
                  yqToast("success", "重Roll完成", "🎨 监控");
                } else {
                  $img.css("opacity", "1");
                  yqToast("error", rr.error || "重Roll失败", "🎨 监控");
                }
              });
            });
        }
        yqToast("success", "监控画面已生成", "🎨 " + locationName);
        // 生图完成后重绘详情页与监控概览，避免必须退出重进才能看到更新
        if (_isViewingThisDetail) {
          var _sumAfterImg = _yqGetSurveillanceRealtimeSummary(locationName);
          window.phoneOpenCamDetail(locationName, _sumAfterImg || "");
          if (navigationStack.length > 1) navigationStack.pop();
        }
        _yqSyncSurveillanceStackSnapshot();
      } else {
        throw new Error(result.error || "生图失败");
      }
    } catch (error) {
      console.error("[监控生图] 失败:", error);
      if ($imgArea.length > 0) {
        $imgArea.html(
          '<div style="color:#ef4444;padding:12px;font-size:12px;text-align:center;"><i class="fas fa-exclamation-triangle"></i> 生图失败: ' +
            escapeHtml(error.message || "未知错误") +
            "</div>",
        );
      }
      yqToast("error", "生图失败: " + (error.message || ""), "🎨 监控生图");
    } finally {
      var _isStillViewing =
        ($("#phone-app-title").text() || "").indexOf(locationName) >= 0;
      if (_isStillViewing) {
        var $imgBtn2 = $(".cam-detail-genimg-btn");
        if ($imgBtn2.length > 0) {
          $imgBtn2
            .prop("disabled", false)
            .css({ background: "#7c3aed", cursor: "pointer" });
          $imgBtn2.find(".cam-genimg-text").text("生成画面");
        }
      }
