  window.phonePreGenSurveillanceTag = async function (locationName) {
    var check = isImageGenReady();
    if (!check.ready) return;
    var settings = getImageGenSettings();
    if (!settings.enabled) return;

    var camHistory = getPhoneMetaBig("cam_history", {});
    var records = camHistory[locationName] || [];
    var sceneText = records.length > 0 ? records[0].content || "" : "";
    /* 回退到MVU摘要 */
    if (!sceneText) {
      fetchLatestMvuData(true);
      var _d = currentPhoneData || {};
      var _raw = ""; /* 银麒赎世监控画面由phoneMeta管理 */
      if (_raw) {
        var _pts = _raw.split("|");
        for (var _i = 0; _i < _pts.length; _i++) {
          var _pt = _pts[_i].trim();
          var _ci = _pt.indexOf(":");
          if (_ci > 0 && _pt.substring(0, _ci).trim() === locationName) {
            var _desc = _pt.substring(_ci + 1).trim();
            if (_desc && !/^无人/.test(_desc)) sceneText = _desc;
            break;
          }
        }
      }
    }
    if (!sceneText) return;

    try {
      var tagResult = await window.phonePreGenerateTag("surveillance", {
        location: locationName,
        sceneText: sceneText,
        time: new Date().toLocaleString(),
      });
