          tag: tagResult.tag,
          entryId: tagResult.entryId,
          timestamp: Date.now(),
        };
        setPhoneMeta("cam_tag_cache", cache);
        console.log("[监控生图] tag预缓存完成: " + locationName);
      }
    } catch (e) {
      console.warn("[监控生图] tag预生成失败: " + locationName, e);
    }
  };

  /* 清理cam_images中不在当前活跃地点列表中的旧图片引用 */
  function _cleanStaleCamImages(activeTasks) {
    try {
      var camImages = getPhoneMetaBig("cam_images", {});
      var currentLocs = {};
      for (var ci = 0; ci < activeTasks.length; ci++)
        currentLocs[activeTasks[ci].loc] = true;
      var imgKeys = Object.keys(camImages);
      var cleaned = false;
      for (var ik = 0; ik < imgKeys.length; ik++) {
        if (!currentLocs[imgKeys[ik]]) {
          delete camImages[imgKeys[ik]];
          cleaned = true;
        }
