      if (cleaned) setPhoneMetaBig("cam_images", camImages, true);
    } catch (e) {}
  }

  // ==================== 每回合自动扩写监控详情 ====================
  var _camExpandRunning = false; // [修复] 防止并发扩写冲突
  window.phoneAutoExpandCameras = async function () {
    if (_camExpandRunning) {
      console.log("[监控自动扩写] 上一轮扩写仍在进行中，跳过本次");
      return;
    }
    _camExpandRunning = true;
    try {
      var api = window.phoneAPI.surveillance;
      if (!api || !api.isAvailable()) return;
      fetchLatestMvuData(true);
      var d = currentPhoneData || {};
      var rawSummary = ""; /* 银麒赎世监控画面由phoneMeta管理 */
      if (!rawSummary) return;
      var curTime = _getGameTimeCompat() || "未知时间";
      var invaded = false; /* 银麒赎世无监控入侵机制 */

      // 收集需要扩写的摄像头
      var cameras = _.get(d, "user.监控设施.已安装摄像头", {});
      var tasks = [];
      var parts = rawSummary.split("|");
      for (var i = 0; i < parts.length; i++) {
        var part = parts[i].trim();
        if (!part) continue;
        var colonIdx = part.indexOf(":");
        if (colonIdx <= 0) continue;
        var loc = part.substring(0, colonIdx).trim();
        var desc = part.substring(colonIdx + 1).trim();
        if (!desc || /^无人/.test(desc)) continue;
        var camPos = _.get(cameras, loc + ".具体位置", loc);
        tasks.push({ loc: loc, desc: desc, camPos: camPos });
      }

      // [Bug10] 确保手机后门设备也被包含在tasks中
      // 即使主AI的监控画面变量中没有提到手机后门，也要为其生成内容
      var taskLocs = {};
      for (var _tl = 0; _tl < tasks.length; _tl++) {
        taskLocs[tasks[_tl].loc] = true;
      }
      var camKeys = Object.keys(cameras);
      for (var _ck = 0; _ck < camKeys.length; _ck++) {
        var _camKey = camKeys[_ck];
        if (_camKey.indexOf("手机后门:") === 0 && !taskLocs[_camKey]) {
          var _camDetail = cameras[_camKey];
          var _camPos = _.get(_camDetail, "具体位置", _camKey);
          tasks.push({
            loc: _camKey,
            desc: "手机后门监控中",
            camPos: _camPos,
          });
        }
      }

      // 清理扩写结果的通用函数
      function cleanExpandResult(text) {
        if (!text) return "";
        text = cleanMessageText(text);
        return text
          .replace(/\*\*([^*]*)\*\*/g, "$1")
          .replace(/\*([^*]*)\*/g, "$1")
          .replace(/^#+\s+/gm, "")
          .trim();
      }

      // 保存单个摄像头的扩写结果到cam_history
      function saveExpandResult(loc, content) {
        var camHistory = getPhoneMetaBig("cam_history", {});
        camHistory[loc] = [
          {
            content: content,
            time: curTime,
            timestamp: Date.now(),
          },
        ];
        setPhoneMetaBig("cam_history", camHistory, true);
        try {
          localStorage.setItem("yinqi-cam-expand-" + loc, content);
        } catch (e) {}
      }

      // ===== 第一级：批量模式（1次API调用） =====
      async function expandBatch(taskList) {
        var locList = [];
        for (var bi = 0; bi < taskList.length; bi++) {
          var label = taskList[bi].loc;
          if (taskList[bi].camPos && taskList[bi].camPos !== taskList[bi].loc) {
            label += "（" + taskList[bi].camPos + "）";
          }
          locList.push("- " + label + ": " + taskList[bi].desc);
        }
        var batchPrompt;
        if (invaded) {
          batchPrompt =
            "你是监控画面描述器。时间：" +
            curTime +
            "。监控系统已被入侵，为以下每个位置生成一段伪造的正常画面描述。\n" +
            locList.join("\n") +
            "\n\n" +
            "要求：每个位置50-150字，客观简洁，有画面感。不要以时间开头，直接描述画面内容。不要使用markdown格式。\n" +
            "【生成约束】描述的活动必须符合" +
            curTime +
            "这个时间段的合理性。伪造画面要看起来自然可信。\n" +
            '返回纯JSON对象，key为位置名，value为扩写内容。例如：{"客厅":"扩写内容...","主卧":"扩写内容..."}';
        } else {
          batchPrompt =
            "你是监控画面描述器。时间：" +
            curTime +
            "。请根据以下每个位置的画面摘要分别扩写成50-150字的监控画面描述。\n" +
            locList.join("\n") +
            "\n\n" +
            "要求：客观简洁，像真实监控记录。不要以时间开头，直接描述画面内容。不要使用markdown格式。\n" +
            "【生成约束】描述的活动必须符合" +
            curTime +
            "这个时间段的合理性。角色只能出现在其当前位置。画面中的人物服装、环境光线要与时间和地点一致。\n" +
            '返回纯JSON对象，key为位置名，value为扩写内容。例如：{"客厅":"扩写内容...","主卧":"扩写内容..."}';
        }
        var rawResult = await api.callChatAPI("", batchPrompt, {
          contextFloors: 2,
        });
        if (!rawResult) throw new Error("API返回空结果");
        rawResult = cleanMessageText(rawResult);
        // 提取JSON
        rawResult = rawResult
          .replace(/```json\s*/gi, "")
          .replace(/```\s*/g, "")
          .trim();
        var parsed = JSON.parse(rawResult);
        var successLocs = [];
        for (var pk = 0; pk < taskList.length; pk++) {
          var tLoc = taskList[pk].loc;
          var tContent = parsed[tLoc];
          if (
            tContent &&
            typeof tContent === "string" &&
            tContent.length > 10
          ) {
            saveExpandResult(tLoc, tContent.trim());
            successLocs.push(tLoc);
          }
        }
        return successLocs;
      }

      // ===== 第二级：并发模式（N次API并发调用） =====
      async function expandConcurrent(taskList) {
        var promises = taskList.map(function (task) {
          return expandOne(task)
            .then(function (ok) {
              return { task: task, ok: ok };
            })
            .catch(function (e) {
              console.warn("[监控并发扩写] " + task.loc + " 失败:", e);
              return { task: task, ok: false };
            });
        });
        var results = await Promise.allSettled(promises);
        var failedTasks = [];
        for (var ri = 0; ri < results.length; ri++) {
          var val = results[ri].value || results[ri].reason;
          if (val && !val.ok) failedTasks.push(val.task);
        }
        return failedTasks;
      }

      // ===== 第三级：串行模式（逐个调用） =====
      async function expandSerial(taskList) {
        for (var si = 0; si < taskList.length; si++) {
