      // 单个摄像头扩写函数（第二/三级使用）
      async function expandOne(task) {
        var locLabel = task.loc;
        if (task.camPos && task.camPos !== task.loc) {
          locLabel += "（" + task.camPos + "）";
        }
        var prompt;
        if (invaded) {
          prompt =
            "你是监控画面描述器。位置：" +
            locLabel +
            "。时间：" +
            curTime +
            "。监控系统已被入侵，生成一段伪造的正常画面描述。50-150字，客观简洁，有画面感。不要以时间开头，直接描述画面内容。不要使用markdown格式。\n" +
            "【生成约束】描述的活动必须符合" +
            curTime +
            "这个时间段的合理性。伪造画面要看起来自然可信。画面中的人物服装、环境光线要与时间一致。";
        } else {
          prompt =
            "你是监控画面描述器。位置：" +
            locLabel +
            "。时间：" +
            curTime +
            "。当前画面摘要：" +
            task.desc +
            "。请根据摘要扩写成50-150字的监控画面描述，客观简洁，像真实监控记录。不要以时间开头，直接描述画面内容。不要使用markdown格式。\n" +
