/**
 * 设置消息事件监听器
 * 参考 mobile-master/app/message-app.js 的实现
 */
function setupMessageEventListener() {
  if (isEventListening) {
    return;
  }

  // 多种检测方法（参考 mobile-master）
  const detectionMethods = [
    // 方法1: SillyTavern.getContext()
    () => {
      if (
        window.SillyTavern &&
        typeof window.SillyTavern.getContext === "function"
      ) {
        const context = window.SillyTavern.getContext();
        if (
          context &&
          context.eventSource &&
          typeof context.eventSource.on === "function" &&
          context.event_types
        ) {
          return {
            eventSource: context.eventSource,
            event_types: context.event_types,
            foundIn: "SillyTavern.getContext()",
          };
        }
      }
      return null;
    },

    // 方法2: 全局 eventOn 函数
    () => {
      if (
        typeof eventOn === "function" &&
        typeof tavern_events !== "undefined" &&
        tavern_events.MESSAGE_RECEIVED
      ) {
        return {
          eventSource: {
            on: eventOn,
            off: typeof eventOff === "function" ? eventOff : null,
          },
          event_types: tavern_events,
          foundIn: "global eventOn",
        };
      }
      return null;
    },

    // 方法3: 父窗口 eventSource
    () => {
      if (
        window.parent &&
        window.parent.eventSource &&
        typeof window.parent.eventSource.on === "function"
      ) {
        if (
          window.parent.event_types &&
          window.parent.event_types.MESSAGE_RECEIVED
        ) {
          return {
            eventSource: window.parent.eventSource,
            event_types: window.parent.event_types,
            foundIn: "parent.eventSource",
          };
        }
      }
      return null;
    },
  ];

  // 尝试各种检测方法
  for (let i = 0; i < detectionMethods.length; i++) {
    try {
      const result = detectionMethods[i]();
      if (result && result.eventSource && result.event_types) {
        // 绑定消息接收事件（驱动自动生成计数）
        if (result.event_types.MESSAGE_RECEIVED) {
          // 先移除旧监听器（防止重复注册）
          if (result.eventSource.off) {
            try {
              result.eventSource.off(
                result.event_types.MESSAGE_RECEIVED,
                onMessageReceived,
              );
            } catch (e) {}
          } else if (result.eventSource.removeListener) {
            try {
              result.eventSource.removeListener(
                result.event_types.MESSAGE_RECEIVED,
                onMessageReceived,
              );
            } catch (e) {}
          }
          result.eventSource.on(
            result.event_types.MESSAGE_RECEIVED,
            onMessageReceived,
          );
          // 保存引用以便stopRefreshMechanism正确移除
          window._phoneEventSource = result.eventSource;
          window._phoneEventType = result.event_types.MESSAGE_RECEIVED;
          isEventListening = true;
          console.log("[自动生成] 事件监听器绑定成功，来源:", result.foundIn);

          // 初始化消息计数
          updateMessageCount();

          // 初始化自动生成计数器
          autoGenCounters = {};

          return;
        }
      }
    } catch (error) {
      console.error("[自动生成] 检测方法", i, "失败:", error);
    }
  }

  // 如果所有方法都失败，启动轮询作为降级方案
  console.log("[自动生成] 所有事件检测方法失败，启动轮询方案");
  startRefreshPolling();
}

