    console.log("[自动生成] 串行模式连续稳定，自动恢复并发模式");
  }
}

async function _processAutoGenQueue() {
  if (_autoGenRunning) return;
  _autoGenRunning = true;
  var _hitRateLimit = false;

  if (_autoGenConcurrentMode && _autoGenQueue.length > 1) {
    // 并发模式：小并发池（避免一次性压满API）
    var tasks = _autoGenQueue.splice(0);
    var poolSize = Math.max(2, Number(window.YQ_AUTOGEN_POOL_SIZE) || 2);
    var taskIdx = 0;
    var results = [];
    async function _worker() {
      while (taskIdx < tasks.length) {
        var idx = taskIdx++;
        var task = tasks[idx];
        try {
          await task.fn();
          results[idx] = { status: "fulfilled" };
        } catch (err) {
          results[idx] = { status: "rejected", reason: err };
        }
      }
    }
    var workers = [];
    for (var wi = 0; wi < Math.min(poolSize, tasks.length); wi++) {
      workers.push(_worker());
    }
    await Promise.all(workers);
    // 检查是否有429/限流错误，有则降级
    var hasRateLimit = false;
    for (var ri = 0; ri < results.length; ri++) {
      if (results[ri].status === "rejected") {
        var errMsg = String(
          (results[ri].reason && results[ri].reason.message) ||
            results[ri].reason ||
            "",
        );
        if (/429|rate.?limit|too.?many|quota|throttl/i.test(errMsg)) {
          hasRateLimit = true;
          break;
        }
      }
    }
    if (hasRateLimit) _hitRateLimit = true;
  } else {
    // 串行模式：逐个执行
    while (_autoGenQueue.length > 0) {
      var task = _autoShiftTask();
      if (!task || typeof task.fn !== "function") continue;
      try {
        await task.fn();
      } catch (e) {
        console.warn("[自动生成队列] 任务失败:", e);
        var _em = String((e && e.message) || e || "");
        if (/429|rate.?limit|too.?many|quota|throttl/i.test(_em))
          _hitRateLimit = true;
      }
      await new Promise(function (r) {
        setTimeout(r, 500);
      });
    }
  }

  _autoUpdateConcurrentModeByHealth(_hitRateLimit);
  _autoGenRunning = false;
  // 队列完成后更新消息计数，防止手机插入的楼层被误计为新消息
  try {
    lastMessageCount = getCurrentMessageCount();
  } catch (e) {}
  // 如果执行期间有新任务被加入队列，继续处理（防止孤儿任务）
  if (_autoGenQueue.length > 0) {
    _processAutoGenQueue();
    return;
  }
  // 队列满载时累计的轮次补偿：在空闲时补跑一次触发检查
  if (_autoGenPendingReplayRounds > 0) {
    _autoGenPendingReplayRounds = Math.max(0, _autoGenPendingReplayRounds - 1);
    _autoEnqueueTriggeredTasks();
    if (_autoGenQueue.length > 0) _processAutoGenQueue();
  }
}

function onMessageReceived(messageId) {
  try {
    // 手机自己插的楼不计数（世界事件/见面事件等）
    if (window._phoneInsertingFloor) {
      console.log("[自动生成] 手机插楼消息，跳过计数");
      lastMessageCount = getCurrentMessageCount();
      return;
    }
    var currentCount = getCurrentMessageCount();
    // 面板通知的删楼同步（面板2秒定时器检测到删楼后设置此值）
    var _syncParent = window.parent || window;
    if (
      _syncParent._yqMsgCountSync != null &&
      _syncParent._yqMsgCountSync < lastMessageCount
    ) {
      console.log(
        "[自动生成] 面板通知删楼同步: " +
          lastMessageCount +
          " → " +
          _syncParent._yqMsgCountSync,
      );
      lastMessageCount = _syncParent._yqMsgCountSync;
      _syncParent._yqMsgCountSync = null;
    }
    // 删楼后lastMessageCount可能大于currentCount，必须同步
    // 否则删楼后的新消息永远不会触发自动生成
    if (currentCount < lastMessageCount) {
