      }
      // 跳过轮次检查
      // [V10.4·2026-05-13] 修复问题8：不再全局 return，而是 per-key 过滤
      //   全局 _autoGenSkipRounds 仍然保留（向后兼容），但优先走 per-key 判断
      if (_autoGenSkipRounds > 0) {
        _autoGenSkipRounds--;
        console.log(
          "[自动生成] 全局跳轮模式（剩余" + _autoGenSkipRounds + "轮）",
        );
        // 仍然递减 per-key 计数（防止卡死）
        _decrementAutoGenSkipByKey();
        return;
      }
      // per-key 递减：每个完整回合递减所有 per-key 计数一次
      _decrementAutoGenSkipByKey();
      // 队列长度限制
      if (_autoGenQueue.length >= 20) {
        _autoGenPendingReplayRounds = Math.min(
          10,
          Number(_autoGenPendingReplayRounds || 0) + 1,
        );
        console.warn(
          "[自动生成队列] 队列已满(" +
            _autoGenQueue.length +
            ")，延迟补偿轮次+" +
