      _cleanupCharRefLiveRooms();
      _processAutoGenQueue();
    }
  } catch (error) {
    console.error("[自动生成] onMessageReceived错误:", error);
  }
}

// ==================== 统一自动生成管理器（递增计数器方案） ====================
var autoGenCounters = {};

function getAutoGenSettings(key) {
  var defaultInterval =
    { chat: 2, surveillance: 1, forum: 3, worldEvents: 4, live: 1 }[key] || 2;
  var defaultContextFloors = key === "chat" ? 8 : 6;
  var ch = window.phoneAPI && window.phoneAPI[key];
  if (ch) {
    // [V9.6 P2 hotfix·2026-05-10] channelKey 未定义导致 ReferenceError
    //   原：contextFloors: channelKey === "chat" ? 8 : 6
    //   根因：函数参数是 key，channelKey 在此处未定义，每次 autoGenChat/Forum/WorldEvents/Live
    //         首行 getAutoGenSettings(...) 都抛 ReferenceError，被队列 catch 吞掉，
    //         导致所有 APP 自动生成全面静默失败；phoneOpenAutoGenSettings UI 同理无法打开
    //   修：改用函数参数 key 判断，并兜底处理 ch.settings.contextFloors 可能为 undefined
    var cfLocal =
      ch && ch.settings && ch.settings.contextFloors != null
        ? ch.settings.contextFloors
        : defaultContextFloors;
    var agLocal = (ch && ch.settings && ch.settings.autoGen) || {};
    return Object.assign(
      {
        enabled: false,
        interval: defaultInterval,
        contextFloors: defaultContextFloors,
        showToast: true,
      },
      agLocal,
      { contextFloors: cfLocal },
    );
  }
  return {
    enabled: false,
    interval: defaultInterval,
    contextFloors: defaultContextFloors,
    showToast: true,
  };
}

function saveAutoGenSettings(key, settings) {
  var ch = window.phoneAPI && window.phoneAPI[key];
  if (!ch) return;
  // [V10.12·2026-05-19] 把 crossGroupLevel 也持久化（仅 chat 用）
  var _autoGenPatch = {
    enabled: settings.enabled,
    interval: settings.interval,
    showToast: settings.showToast,
  };
  if (settings.crossGroupLevel != null) {
    _autoGenPatch.crossGroupLevel = settings.crossGroupLevel;
  }
  ch.settings.autoGen = Object.assign({}, ch.settings.autoGen, _autoGenPatch);
  if (settings.contextFloors != null)
    ch.settings.contextFloors = settings.contextFloors;
  ch.saveSettings();
}

/**
 * 获取当前AI楼层数（非用户消息的总数）
 * 参考魔数据库方案：用绝对楼层数代替易失的计数器，彻底防止重复触发
 */
/**
 * 检查是否应触发自动生成（递增计数器方案，回归原始可靠方案）
 * 每次onMessageReceived计数+1，达到interval时触发并归零
 */
function checkAutoGenTrigger(key) {
  var ch = window.phoneAPI && window.phoneAPI[key];
  if (!ch || !ch.isAvailable()) return false;
  var s = ch.settings.autoGen || {};
  var defInterval =
    { chat: 2, surveillance: 1, forum: 3, worldEvents: 4, live: 1 }[key] || 2;
  if (!s.enabled || (s.interval || defInterval) <= 0) return false;
  autoGenCounters[key] = (autoGenCounters[key] || 0) + 1;
  if (autoGenCounters[key] >= (s.interval || defInterval)) {
    autoGenCounters[key] = 0;
    return true;
  }
  return false;
}

// 自动生成：聊天（NPC私聊+群聊+朋友圈）
async function autoGenChat() {
  var gen = window.npcMsgGen;
  if (!gen || gen.isGenerating) return;
  var chatAPI = window.phoneAPI.chat;
  if (!chatAPI || !chatAPI.isAvailable()) return;
  var agSettings = getAutoGenSettings("chat");
  if (agSettings.showToast !== false && typeof toastr !== "undefined") {
    yqToast("info", "正在自动生成聊天消息...", "💬 聊天", { timeOut: 1500 });
  }
  try {
    fetchLatestMvuData(true);
    var d = currentPhoneData || {};
    gen.isGenerating = true;
    var availability = gen.buildCharacterAvailability(d);
    // 三种消息类型独立概率触发：私聊50%、群聊25%、朋友圈25%，保底至少一个
    var doPrivate = Math.random() < 0.5;
    var doGroup = Math.random() < 0.25;
    var doMoments = Math.random() < 0.25;
    // 保底：全部未命中时随机选一个
    if (!doPrivate && !doGroup && !doMoments) {
      var r = Math.random();
      if (r < 0.5) doPrivate = true;
      else if (r < 0.75) doGroup = true;
      else doMoments = true;
    }
    var tasks = [];
    if (doPrivate)
      tasks.push(gen.generateNpcPrivateMessages(d, availability, chatAPI));
    if (doGroup)
      tasks.push(gen.generateNpcGroupMessages(d, availability, chatAPI));
    if (doMoments) tasks.push(gen.generateMoments(d, availability, chatAPI));
    await Promise.allSettled(tasks);
    gen.isGenerating = false;
    setTimeout(function () {
      updateMsgAppBadge();
      injectNpcSummaryToContext();
    }, 1000);
  } catch (e) {
    gen.isGenerating = false;
    if (typeof toastr !== "undefined")
      yqToast("error", "自动聊天生成失败: " + (e.message || ""), "💬 聊天");
    console.warn("[自动聊天] 失败:", e);
  }
