// ==================== 直播自动生成（每回合触发检查） ====================
var _liveSkipCounter = 0;

/** 获取直播设置 */
function getLiveAutoSettings() {
  var ch = window.phoneAPI && window.phoneAPI.live;
  if (!ch) return { skipThreshold: 3 };
  return {
    skipThreshold: ch.settings._liveSkipThreshold || 3,
  };
}

/**
 * 检查是否需要自动生成直播间
 * 每回合调用，检查最新对话是否有直播相关内容或攻略度≥80的未出场女性
 * 连续失败N次后第N+1次强制生成
 */
function checkLiveAutoTrigger() {
  var ch = window.phoneAPI && window.phoneAPI.live;
  if (!ch || !ch.isAvailable()) return false;
  var ag = ch.settings.autoGen || {};
  if (ag.enabled === false) return false;

  var liveSettings = getLiveAutoSettings();
  var skipThreshold = liveSettings.skipThreshold;

  // 检查最新对话是否有直播相关内容
  var hasLiveContent = _checkLatestDialogueForLive();
  // 检查是否有攻略度≥80的未出场女性
  var hasCorruptFemale = _checkCorruptFemalesForLive();

  if (hasLiveContent || hasCorruptFemale) {
    _liveSkipCounter = 0;
    console.log(
      "[直播自动生成] 触发条件满足:",
      hasLiveContent ? "对话相关" : "堕落角色",
    );
    return true;
  }

  // 条件不满足，增加跳过计数
  _liveSkipCounter++;
  console.log(
    "[直播自动生成] 条件不满足，跳过计数:",
    _liveSkipCounter,
    "/",
    skipThreshold + 1,
  );

  // 连续失败N次后，第N+1次强制生成
  if (_liveSkipCounter > skipThreshold) {
    _liveSkipCounter = 0;
    console.log("[直播自动生成] 达到强制生成阈值，强制触发");
    return true;
  }

  return false;
}

/** 检查最新一轮对话是否包含直播相关关键词 */
function _checkLatestDialogueForLive() {
  try {
    var targetWindow = window;
    if (window.parent && window.parent !== window) {
      try {
        if (window.parent.SillyTavern) targetWindow = window.parent;
      } catch (e) {}
    }
    if (!targetWindow.SillyTavern || !targetWindow.SillyTavern.getContext)
      return false;
    var context = targetWindow.SillyTavern.getContext();
    if (!context.chat || context.chat.length === 0) return false;

    // 取最新2条消息（一轮对话）
    var recentMsgs = context.chat.slice(-2);
    var liveKeywords = [
      "直播",
      "主播",
      "开播",
      "斗瘾",
      "弹幕",
      "打赏",
      "礼物",
      "直播间",
      "观众",
      "粉丝",
    ];
    for (var i = 0; i < recentMsgs.length; i++) {
      var msg = recentMsgs[i];
      var text = msg.mes || msg.message || "";
      // 排除 <LiveMeetEvent>/<ForumMeetEvent>/<SurveillanceInstallEvent> 标签内的内容，避免约线下楼层触发直播生成（必须在substring之前）
      text = text.replace(/<LiveMeetEvent>[\s\S]*?<\/LiveMeetEvent>/gi, "");
      text = text.replace(/<ForumMeetEvent>[\s\S]*?<\/ForumMeetEvent>/gi, "");
      text = text.replace(
        /<SurveillanceInstallEvent>[\s\S]*?<\/SurveillanceInstallEvent>/gi,
        "",
      );
      text = text.substring(0, 500);
      if (!text.trim()) continue;
      for (var k = 0; k < liveKeywords.length; k++) {
        if (text.indexOf(liveKeywords[k]) !== -1) return true;
      }
    }
  } catch (e) {}
  return false;
}

/** 检查是否有攻略度≥80且未在直播中、不在主角身边的女性角色 */
function _checkCorruptFemalesForLive() {
  try {
    fetchLatestMvuData(true);
    var d = currentPhoneData || {};
    var existingRooms = getPhoneMetaBig("live_rooms", []) || [];
    var existingHosts = {};
    for (var i = 0; i < existingRooms.length; i++) {
      if (existingRooms[i].hostName)
        existingHosts[existingRooms[i].hostName] = true;
    }
    var sceneChars = _.get(d, "当前场景角色", {});

    // 检查女性角色
    var femChars = _.get(d, "女性角色", {});
    var femKeys = Object.keys(femChars);
    for (var fi = 0; fi < femKeys.length; fi++) {
      var fcName = femKeys[fi];
      var fcData = femChars[fcName];
      if (typeof fcData !== "object" || !fcData) continue;
      var fcCorrupt = parseInt(fcData.攻略度 || 0) || 0;
      if (fcCorrupt < 80) continue;
      if (existingHosts[fcName]) continue;
      if (sceneChars[fcName]) continue;
      return true;
    }
    // 林知意单独检查
    var yqxCorrupt = parseInt(_.get(d, "角色.林知意.奉献度", 0)) || 0;
    if (yqxCorrupt >= 80 && !existingHosts["林知意"] && !sceneChars["林知意"]) {
      return true;
    }
  } catch (e) {}
  return false;
}

