/**
 * 启动轮询刷新（降级方案 — 当事件绑定失败时使用）
 * 通过检测消息数增加≥2来判断一个完整回合（用户消息+AI回复）
 */
function _getAutoPollingIntervalMs() {
  var factor =
    typeof getPhonePerfFactor === "function" ? getPhonePerfFactor() : 1;
  try {
    var overlayActive = $("#mobile-phone-overlay").hasClass("active");
    if (typeof document !== "undefined" && document.hidden)
      return Math.round(12000 * factor);
    return Math.round((overlayActive ? 5000 : 9000) * factor);
  } catch (_e) {
    return Math.round(7000 * factor);
  }
}

function startRefreshPolling() {
  // 清除旧的轮询
  if (refreshPollingInterval) {
    clearTimeout(refreshPollingInterval);
    clearInterval(refreshPollingInterval);
  }

  console.log("[自动生成] 启动轮询刷新（降级方案，动态间隔）");
  var _pollLastCount = getCurrentMessageCount();
  var _pollTick = function () {
    const currentCount = getCurrentMessageCount();
    const diff = currentCount - _pollLastCount;

    if (diff >= 2) {
      // 消息数增加≥2，说明至少完成了一个回合（用户+AI）
      var rounds = Math.floor(diff / 2);
      console.log("[自动生成] 轮询检测到" + rounds + "个完整回合");
      _pollLastCount = currentCount;
      lastMessageCount = currentCount;
      refreshMessagesPanel();

      // 每个回合触发一次计数器
      for (var ri = 0; ri < rounds; ri++) {
        if (checkAutoGenTrigger("chat")) _autoEnqueueTask("chat", autoGenChat);
        if (checkAutoGenTrigger("forum"))
          _autoEnqueueTask("forum", autoGenForum);
        if (checkAutoGenTrigger("worldEvents"))
          _autoEnqueueTask("worldEvents", autoGenWorldEvents);
        if (checkAutoGenTrigger("surveillance"))
          _autoEnqueueTask("surveillance", autoGenSurveillance);
        if (checkLiveAutoTrigger()) _autoEnqueueTask("live", autoGenLive);
        _cleanupCharRefLiveRooms();
      }
      _processAutoGenQueue();
    } else if (diff === 1) {
      // 只增加了1条（可能是用户刚发送），只刷新面板不触发计数
      _pollLastCount = currentCount;
      lastMessageCount = currentCount;
      refreshMessagesPanel();
    } else if (diff < 0) {
      // 删楼兜底：轮询路径也要同步计数，但删楼本身不触发自动生成
      console.log(
        "[自动生成] 轮询检测到删楼，同步计数: " +
          _pollLastCount +
          " → " +
          currentCount,
      );
      _pollLastCount = currentCount;
      lastMessageCount = currentCount;
      refreshMessagesPanel();
    }
    refreshPollingInterval = setTimeout(_pollTick, _getAutoPollingIntervalMs());
  };
  if (typeof window.phoneScheduleTask === "function") {
    window.phoneScheduleTask(
      "autogen:poll",
      _pollTick,
      _getAutoPollingIntervalMs,
    );
  } else {
    refreshPollingInterval = setTimeout(_pollTick, _getAutoPollingIntervalMs());
  }
}

/**
 * 停止刷新机制
 */
/**
 * 仅停止UI相关定时器（关闭手机时调用）
 * 不移除MESSAGE_RECEIVED事件监听，保持自动生成在后台运行
 */
function stopUIRefreshTimers() {
  // 清除轮询
  if (refreshPollingInterval) {
    clearTimeout(refreshPollingInterval);
    clearInterval(refreshPollingInterval);
    refreshPollingInterval = null;
  }
  if (typeof window.phoneUnscheduleTask === "function") {
    window.phoneUnscheduleTask("autogen:poll");
  }

  // 清除聊天刷新
  if (chatPanelRefreshInterval) {
    clearInterval(chatPanelRefreshInterval);
    chatPanelRefreshInterval = null;
  }
  // 统一反注册 phoneScheduler 上的 chat:autoRefresh，避免关手机后仍周期性空转
  if (typeof window.phoneUnscheduleTask === "function") {
    try {
      window.phoneUnscheduleTask("chat:autoRefresh");
    } catch (_unErr) {}
  }
}

/**
 * 完全停止刷新机制（页面卸载/角色卡切换时调用）
 * 包括移除事件监听器
 */
function stopRefreshMechanism() {
  // 先清除UI定时器
  stopUIRefreshTimers();

  // 移除事件监听器（防止重复注册导致泄漏）
  if (window._phoneEventSource && window._phoneEventType) {
    try {
      if (window._phoneEventSource.off) {
        window._phoneEventSource.off(window._phoneEventType, onMessageReceived);
      } else if (window._phoneEventSource.removeListener) {
        window._phoneEventSource.removeListener(
          window._phoneEventType,
          onMessageReceived,
        );
      }
    } catch (e) {}
  }

  // 标记停止监听
  isEventListening = false;
}

/**
 * 绑定信息面板事件
 */
function bindMessagePanelEvents() {
  var $body = $("#phone-app-body");

  // 绑定联系人点击事件（在swipe-content上）
  $body
    .find(".contact-item")
    .off("click.contact")
    .on("click.contact", function () {
      var contactType = $(this).data("type");
      var contactId = $(this).data("id");
      var contactName = $(this).data("name");
      var isGroup = contactType === "group";
      var members = $(this).data("members") || "";
      openChatPanel(contactId, contactName, isGroup, members);
    });

  // ===== 左滑手势 =====
  var swipeState = { el: null, startX: 0, startY: 0, current: null };

  function closeAllSwipes() {
    $body.find(".contact-swipe-content").css("transform", "translateX(0)");
    $body.find(".contact-swipe-actions").css("transform", "translateX(100%)");
    swipeState.current = null;
  }

  $body
    .off("touchstart.cswipe mousedown.cswipe")
    .on(
      "touchstart.cswipe mousedown.cswipe",
      ".contact-swipe-content",
      function (e) {
        var ev = e.originalEvent.touches ? e.originalEvent.touches[0] : e;
        swipeState.el = $(this);
        swipeState.startX = ev.clientX;
        swipeState.startY = ev.clientY;
      },
    );

  $body
    .off("touchmove.cswipe mousemove.cswipe")
    .on(
      "touchmove.cswipe mousemove.cswipe",
      ".contact-swipe-content",
      function (e) {
        if (!swipeState.el) return;
        var ev = e.originalEvent.touches ? e.originalEvent.touches[0] : e;
        var dx = swipeState.startX - ev.clientX;
        var dy = Math.abs(ev.clientY - swipeState.startY);
        if (dy > Math.abs(dx)) {
          swipeState.el = null;
          return;
        }
        if (dx > 10) {
          e.preventDefault();
          var offset = Math.min(dx, 180);
          swipeState.el.css("transform", "translateX(-" + offset + "px)");
          swipeState.el
            .siblings(".contact-swipe-actions")
            .css("transform", "translateX(calc(100% - " + offset + "px))");
        }
      },
    );

  $body
    .off("touchend.cswipe mouseup.cswipe")
    .on(
      "touchend.cswipe mouseup.cswipe",
      ".contact-swipe-content",
      function (e) {
        if (!swipeState.el) return;
        var el = swipeState.el;
        var ev = e.originalEvent.changedTouches
          ? e.originalEvent.changedTouches[0]
          : e;
        var dx = swipeState.startX - ev.clientX;
        swipeState.el = null;
        if (dx > 50) {
          closeAllSwipes();
          el.css("transform", "translateX(-168px)");
          el.siblings(".contact-swipe-actions").css(
            "transform",
            "translateX(0)",
          );
          swipeState.current = el;
        } else {
          el.css("transform", "translateX(0)");
          el.siblings(".contact-swipe-actions").css(
            "transform",
            "translateX(100%)",
          );
        }
      },
    );

  // 点击空白关闭滑动
  $body.off("click.cswipe-close").on("click.cswipe-close", function (e) {
    if (!$(e.target).closest(".contact-swipe-wrapper").length) closeAllSwipes();
  });

  // [V10.4·2026-05-13] 特别关心按钮（滑动操作区）
  $body
    .off("click.cfocus")
    .on("click.cfocus", ".contact-action-focus", function (e) {
      e.stopPropagation();
      var name = $(this).data("name");
      if (typeof window.yqToggleFocusFriend === "function") {
        var r = window.yqToggleFocusFriend(name) || {};
        if (r.ok) {
          debounceSavePhoneMeta();
          yqToast("success", r.focused ? "已设为特别关心 ❤" : "已取消特别关心");
        } else if (r.reason === "limit") {
          yqToast("warning", "特别关心已达上限 " + (r.limit || 8) + " 人");
        }
      }
      // [V10.1 FIX] 关闭滑动面板 + 延迟刷新确保 DOM 更新可见
      try {
        closeAllSwipes();
      } catch (_) {}
      setTimeout(function () {
        try {
          fetchLatestMvuData(true);
          $("#phone-app-body").html(generateMessagesPanel(currentPhoneData));
          bindMessagePanelEvents();
          bindPanelButtons();
        } catch (_refreshErr) {}
      }, 50);
    });

  // 置顶按钮
  $body.off("click.cpin").on("click.cpin", ".contact-action-pin", function (e) {
    e.stopPropagation();
    var name = $(this).data("name");
    var pinned = getPinnedFriends();
    if (pinned[name]) {
      delete pinned[name];
    } else {
      pinned[name] = true;
    }
    setPinnedFriends(pinned);
    debounceSavePhoneMeta();
    if (typeof toastr !== "undefined")
      yqToast("success", pinned[name] ? "已置顶" : "已取消置顶");
    fetchLatestMvuData(true);
    $("#phone-app-body").html(generateMessagesPanel(currentPhoneData));
    bindMessagePanelEvents();
    bindPanelButtons();
