  // 拉黑按钮
  $body
    .off("click.cblock")
    .on("click.cblock", ".contact-action-block", function (e) {
      e.stopPropagation();
      var name = $(this).data("name");
      var blocked = getBlockedFriends();
      blocked[name] = true;
      setBlockedFriends(blocked);
      debounceSavePhoneMeta();
      // 清理被拉黑角色的消息数据
      try {
        var allNpcMsgs = getPhoneMetaBig("npc_messages", {});
        var allChatHist = getPhoneMetaBig("chat_history", {});
        var unreads = getPhoneMeta("unreads", {});
        var cleanedCount = 0;
        var nKeys = Object.keys(allNpcMsgs);
        for (var ki = 0; ki < nKeys.length; ki++) {
          if (nKeys[ki].indexOf(name) !== -1) {
            delete allNpcMsgs[nKeys[ki]];
            cleanedCount++;
          }
        }
        var cKeys = Object.keys(allChatHist);
        for (var kj = 0; kj < cKeys.length; kj++) {
          if (cKeys[kj].indexOf(name) !== -1) {
            delete allChatHist[cKeys[kj]];
            cleanedCount++;
          }
        }
        var uKeys = Object.keys(unreads);
        for (var kk = 0; kk < uKeys.length; kk++) {
          if (uKeys[kk].indexOf(name) !== -1) {
            delete unreads[uKeys[kk]];
            cleanedCount++;
          }
        }
        setPhoneMetaBig("npc_messages", allNpcMsgs, true);
        setPhoneMetaBig("chat_history", allChatHist, true);
        setPhoneMeta("unreads", unreads);
        if (cleanedCount > 0)
          console.log(
            "[拉黑] 已清理「" + name + "」的 " + cleanedCount + " 条消息数据",
          );
