      if (typeof toastr !== "undefined")
        yqToast("success", "已拉黑「" + name + "」并清理消息数据");
      fetchLatestMvuData(true);
      $("#phone-app-body").html(generateMessagesPanel(currentPhoneData));
      bindMessagePanelEvents();
      bindPanelButtons();
    });

  // 群聊删除按钮
  $body
    .off("click.cgdel")
    .on("click.cgdel", ".contact-action-delete-group", async function (e) {
      e.stopPropagation();
      var groupId = $(this).data("id");
      var groupName = $(this).data("name");
      await deleteGroup(groupId, groupName);
    });

  // 清除所有未读红点按钮
  $body
    .off("click.cclearunread")
    .on("click.cclearunread", ".phone-clear-all-unread-btn", function (e) {
      e.stopPropagation();
      try {
        // 清除所有未读计数
        setPhoneMeta("unreads", {});
        // 清除朋友圈、论坛、平行事件、直播未读
        setPhoneMeta("moments_unread", 0);
        setPhoneMeta("world_events_unread", 0);
        setPhoneMeta("forum_unread", 0);
        setPhoneMeta("live_unread", 0);
        // 刷新角标
        var gen = window.npcMsgGen;
        if (gen) gen.updateTotalUnreadBadge();
        yqToast("success", "已清除所有未读红点");
        // 仅在消息面板时刷新
        if (currentPanel === "messages") {
          fetchLatestMvuData(true);
          $("#phone-app-body").html(generateMessagesPanel(currentPhoneData));
          bindMessagePanelEvents();
          bindPanelButtons();
        }
      } catch (e) {
        yqToast("error", "清除失败");
      }
    });

  /* [废弃] 管理头像按钮已从聊天主页移除，保留绑定避免报错 */
