// ==================== 剧情任务AI生成 ====================
// [V6.5.7 P1-5·2026-04-24] _plotTaskLastFloor 持久化到 phoneMeta
//   原：内存变量，页面刷新即重置为 0 → 下轮 onMessageReceived 可能重复触发生成
//   改：getPhoneMeta('yinqi_plot_task_last_floor', 0) / setPhoneMeta 持久化
//   保留 var _plotTaskLastFloor 作为内存缓存，读写同步 phoneMeta
var _plotTaskLastFloor = 0;
(function () {
  try {
    if (typeof getPhoneMeta === "function") {
      _plotTaskLastFloor =
        Number(getPhoneMeta("yinqi_plot_task_last_floor", 0)) || 0;
    }
  } catch (_e) {}
})();

/**
 * 生成剧情任务（手动或自动调用）
 * @param {Function} callback - 生成完成后的回调
 * @param {boolean} force - 强制生成（跳过楼层防重复检查，手动触发时使用）
 */
function _generatePlotTask(callback, force) {
  try {
    var api = window.phoneAPI;
    if (!api) {
      if (callback) callback();
      return;
    }
    // 检查是否有任务进行中
    fetchLatestMvuData(true);
    var d = currentPhoneData || {};
    var taskStatus = _.get(d, "任务.当前任务.状态", "无任务");
    if (taskStatus === "执行中") {
      console.log("[剧情任务] 跳过：有任务进行中");
      // [V10.4·2026-05-13] 手动触发时给玩家反馈（修复玩家反馈：按钮点击无响应）
      //   force=true 表示玩家手动点击而非自动轮询触发，此时必须提示
      if (force) {
        try {
          if (typeof yqToast === "function") {
            yqToast("warning", "当前任务执行中，无法生成剧情任务", "📋", {
              duration: 3500,
            });
          }
        } catch (_eT) {}
      }
      if (callback) callback();
      return;
    }
    // 防重复（自动模式用，手动模式跳过）
    var curFloor = getCurrentMessageCount();
