function _parsePlotTaskResponse(text) {
  try {
    // [V10.6] 先剥离 thinking 标签（plotTask 的 breakPrompt 主动诱导 AI 写 <thinking>）
    //   plotTask breakPrompt 明确写"先在 <thinking> 标签内完成推理"
    //   如果不剥离，AI 在 thinking 里写的伪 JSON / 说明性 { 会被匹配到
    var cleaned = (text || "")
      .replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi, "")
      .replace(/```(?:json)?\s*/gi, "")
      .replace(/```\s*/g, "")
      .trim();
    var jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    // [V10.6] 兜底：剥离后找不到 → 从原始 text 找（处理 thinking 未闭合的情况）
    if (!jsonMatch) {
      jsonMatch = (text || "").match(/\{[\s\S]*\}/);
    }
    if (!jsonMatch) {
      // [V10.6 方案 C] 旧路径完全失败 → 用增强 helper 兜底（覆盖 thought/reasoning/analysis 等变体）
      if (
        typeof stripThinkingTags === "function" &&
        typeof extractJsonRobust === "function"
      ) {
        var _ptCleaned = stripThinkingTags(text || "")
          .replace(/```(?:json)?\s*/gi, "")
          .replace(/```\s*/g, "")
          .trim();
        var _ptJson =
          extractJsonRobust(_ptCleaned) || extractJsonRobust(text || "");
        if (_ptJson) {
          try {
            var _ptObj = JSON.parse(_ptJson);
            if (_ptObj && _ptObj.desc) {
              setPhoneMeta("yinqi_plot_task", {
                level: _ptObj.level || "D级",
                desc: _ptObj.desc,
                reward: Number(_ptObj.reward) || 0,
                suggestedExecutor: _ptObj.suggestedExecutor || "",
                suggestedMc: Number(_ptObj.suggestedMc) || 1,
                generatedAt: Date.now(),
              });
              console.log(
                "[剧情任务·兜底] 已生成: " +
                  (_ptObj.level || "") +
                  " " +
                  (_ptObj.desc || "").substring(0, 50),
              );
              if (typeof toastr !== "undefined")
                yqToast("success", "剧情任务已生成", "🎭", { timeOut: 3000 });
              return;
            }
          } catch (_ptE) {}
        }
      }
      return;
    }
    var obj;
    try {
      obj = JSON.parse(jsonMatch[0]);
    } catch (e) {
      var fixed = jsonMatch[0].replace(/,\s*([}\]])/g, "$1");
      try {
        obj = JSON.parse(fixed);
      } catch (e2) {
        // [V10.6 方案 C] 双重 JSON.parse 失败 → 新 helper 兜底
        if (
          typeof stripThinkingTags === "function" &&
          typeof extractJsonRobust === "function"
        ) {
          var _ptCleaned2 = stripThinkingTags(text || "")
            .replace(/```(?:json)?\s*/gi, "")
            .replace(/```\s*/g, "")
            .trim();
          var _ptJson2 =
            extractJsonRobust(_ptCleaned2) || extractJsonRobust(text || "");
          if (_ptJson2) {
            try {
              obj = JSON.parse(_ptJson2);
            } catch (_e3) {}
          }
        }
        if (!obj) {
          console.warn("[剧情任务] JSON解析失败:", e2.message);
          return;
        }
      }
    }
    if (!obj || !obj.desc) {
      // [V10.6] 玩家手动触发时无反馈是 plotTask 的另一个 bug，加日志便于诊断
      console.warn(
        "[剧情任务] AI 返回了 JSON 但缺少 desc 字段:",
        JSON.stringify(obj).substring(0, 200),
      );
      return;
    }
    // 存储剧情任务
    setPhoneMeta("yinqi_plot_task", {
      level: obj.level || "D级",
      desc: obj.desc,
      reward: Number(obj.reward) || 0,
      suggestedExecutor: obj.suggestedExecutor || "",
      suggestedMc: Number(obj.suggestedMc) || 1,
      generatedAt: Date.now(),
