  var lv = Math.max(1, Math.min(6, Number(coreLevel) || 1));
  var caps = {
    1: { food: 300, water: 300, medical: 100, parts: 100 },
    2: { food: 800, water: 800, medical: 250, parts: 250 },
    3: { food: 2000, water: 2000, medical: 600, parts: 600 },
    4: { food: 5000, water: 5000, medical: 1500, parts: 1500 },
    5: { food: 15000, water: 15000, medical: 4500, parts: 4500 },
    6: { food: Infinity, water: Infinity, medical: Infinity, parts: Infinity },
  };
  return caps[lv] || caps[1];
}

function _phoneOutpostApplyResourceDelta(resources, coreLevel, delta) {
  resources = resources || {};
  delta = delta || {};
  var caps = _phoneOutpostResourceCaps(coreLevel);
  ["food", "water", "medical", "parts"].forEach(function (k) {
    if (delta[k] === undefined) return;
    var cur = Number(resources[k]) || 0;
    var next = cur + (Number(delta[k]) || 0);
    if (next < 0) next = 0;
    var cap = caps[k];
    resources[k] = cap === Infinity ? next : Math.min(cap, next);
  });
  return resources;
}

