              console.log("[据点同步] API返回，长度=" + (r || "").length);
              var _syncResult = _parseOutpostSyncFromPhone(r, op);
              if (_syncResult && _syncResult.parsed) {
                // [V10.6 FIX] hasChanges=true 但无字段落地 → 视为"无变化"而非"失败"
                // 原逻辑：换通道重试 → 4通道全部"失败" → toast报错
                // 新逻辑：AI正确解析了正文但判断无实质变化 → 标记楼层已同步，不报错
                _markOutpostSyncFloor(curFloor);
                if (_syncResult.changed) {
                  console.log("[据点同步] 同步成功，有数据变化");
                } else if (_syncResult.hasChanges) {
                  console.log(
                    "[据点同步] AI声明有变化但无字段落地，视为无实质变化，标记已同步",
                  );
                } else {
