            })
            .catch(function (e) {
              _recordOutpostSyncFailure(curFloor, e);
              console.warn(
                "[据点同步] 通道 " + chKey + " 失败: " + (e && e.message),
                "→ 尝试下一通道",
              );
              // 失败 → 试下一个通道
              _tryNextSync(ci + 1);
            });
          return; // 已发起调用（异步），让 .catch 接管下一步
        }
      }
      // 所有通道都试过或不可用
      console.warn("[据点同步] 所有API通道均失败或不可用");
      _recordOutpostSyncFailure(curFloor, "所有API通道均失败或不可用");
      if (typeof toastr !== "undefined")
        yqToast("error", "据点同步API全部通道失败，请检查网络/配置", "🏰", {
          timeOut: 5000,
        });
    }
    _tryNextSync(0);
  } catch (e) {
    try {
      _recordOutpostSyncFailure(getCurrentMessageCount(), e);
    } catch (_eFail) {}
    console.warn("[据点同步] 错误:", e.message);
  }
}

function _parseOutpostSyncFromPhone(text, op) {
  try {
    console.log("[据点同步] 解析AI返回:", (text || "").substring(0, 200));
    // [V10.6 FIX] 使用增强版 stripThinkingTags（覆盖 think/thinking/thought/reasoning/analysis 等变体 + 未闭合）
    // 配合 extractJsonRobust 用配对栈提取 JSON，避免 thinking 块内 {{user}} 等花括号干扰
    var cleaned = (
      typeof stripThinkingTags === "function"
        ? stripThinkingTags(text || "")
        : (text || "").replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi, "")
    )
      .replace(/```(?:json)?\s*/gi, "")
      .replace(/```\s*/g, "")
      .trim();
    var jsonText =
      typeof extractJsonRobust === "function"
        ? extractJsonRobust(cleaned)
        : null;
    if (!jsonText) {
      // 兜底 1：原始 text 配对栈
      jsonText =
        typeof extractJsonRobust === "function"
          ? extractJsonRobust(text || "")
          : null;
    }
    if (!jsonText) {
      // 兜底 2：贪婪匹配（旧逻辑，应对极端情况）
      var jsonMatch =
        cleaned.match(/\{[\s\S]*\}/) || (text || "").match(/\{[\s\S]*\}/);
      if (jsonMatch) jsonText = jsonMatch[0];
    }
    if (!jsonText) return { parsed: false, changed: false };
    var obj;
    try {
      obj = JSON.parse(jsonText);
    } catch (e) {
      // 宽松修复：去除尾逗号
      var fixed = jsonText.replace(/,\s*([}\]])/g, "$1");
      try {
        obj = JSON.parse(fixed);
      } catch (e2) {
        // 尝试补全截断的JSON（补闭合括号）
        var truncated = fixed;
        var opens = (truncated.match(/\{/g) || []).length;
        var closes = (truncated.match(/\}/g) || []).length;
        for (var _fi = 0; _fi < opens - closes; _fi++) truncated += "}";
        var openB = (truncated.match(/\[/g) || []).length;
        var closeB = (truncated.match(/\]/g) || []).length;
        for (var _fi2 = 0; _fi2 < openB - closeB; _fi2++) truncated += "]";
        try {
          obj = JSON.parse(truncated);
          console.log("[据点同步] JSON补全成功");
        } catch (e3) {
          console.warn(
            "[据点同步] JSON解析失败，原文:",
            jsonText.substring(0, 200),
          );
          return { parsed: false, changed: false };
        }
      }
    }
    if (!obj) return { parsed: false, changed: false };
    if (!obj.hasChanges)
      return { parsed: true, changed: false, hasChanges: false };
    var changed = false;
    // 玩家据点更新
    if (obj.playerBase && op.playerBase) {
      var pb = op.playerBase;
      if (
        obj.playerBase.populationDelta != null &&
        obj.playerBase.populationDelta !== 0
      ) {
        var delta = Math.max(-20, Math.min(20, obj.playerBase.populationDelta));
        if (pb.backgroundPop)
          pb.backgroundPop.total = Math.max(
            0,
            (pb.backgroundPop.total || 0) + delta,
          );
        changed = true;
      }
      if (obj.playerBase.resources) {
        var _resDelta = {};
        ["food", "water", "medical", "parts"].forEach(function (k) {
          if (
            obj.playerBase.resources[k] != null &&
            obj.playerBase.resources[k] !== 0
          ) {
            var cur = Number((pb.resources || {})[k]) || 0;
            var maxRel = Math.max(5, Math.abs(cur) * 0.1);
            _resDelta[k] = Math.max(
              -maxRel,
              Math.min(maxRel, obj.playerBase.resources[k]),
            );
            changed = true;
          }
        });
        if (Object.keys(_resDelta).length > 0) {
          pb.resources = _phoneOutpostApplyResourceDelta(
            pb.resources || {},
            pb.coreLevel || 1,
            _resDelta,
          );
        }
      }
      if (
        obj.playerBase.newMembers &&
        Array.isArray(obj.playerBase.newMembers)
      ) {
        obj.playerBase.newMembers.forEach(function (m) {
          // 支持字符串或对象格式
          var mName = typeof m === "string" ? m : m.name || "";
          var mType = typeof m === "object" ? m.type || "shelter" : "shelter";
          var mJob = typeof m === "object" ? m.job || "无" : "无";
          if (!mName) return;
          // 处理批量格式如"幸存者*5"
          var batchMatch = mName.match(/^(.+?)[*×x](\d+)$/);
          if (batchMatch) {
            // 批量→加到背景人口
            var batchCount = parseInt(batchMatch[2]) || 1;
            if (!pb.backgroundPop)
              pb.backgroundPop = {
                total: 0,
                male: 0,
                female: 0,
                workers: 0,
                prisoners: 0,
                slaves: 0,
              };
            pb.backgroundPop.total += batchCount;
            pb.backgroundPop.female += Math.floor(batchCount * 0.4);
            pb.backgroundPop.male += batchCount - Math.floor(batchCount * 0.4);
            changed = true;
            return;
          }
          // 重复检查
          pb.members = pb.members || [];
          var exists = pb.members.some(function (em) {
            return em.name === mName;
          });
          if (exists) return;
          if (pb.members.length >= 50) return;
          pb.members.push({ name: mName, type: mType, job: mJob, desc: "" });
          changed = true;
        });
      }
      if (
        obj.playerBase.removedMembers &&
        Array.isArray(obj.playerBase.removedMembers)
      ) {
        obj.playerBase.removedMembers.forEach(function (rn) {
          var rmName = typeof rn === "string" ? rn : rn.name || rn;
          pb.members = (pb.members || []).filter(function (m) {
            return m.name !== rmName;
          });
          changed = true;
        });
      }
    }
    // NPC据点更新
    if (obj.npcOutposts) {
      for (var nm in obj.npcOutposts) {
        if (!obj.npcOutposts.hasOwnProperty(nm)) continue;
        var upd = obj.npcOutposts[nm];
        if (op.npcData && op.npcData[nm]) {
          var nd = op.npcData[nm];
          if (upd.relationDelta) {
            var _oldRel = Number(nd.relation);
            if (!isFinite(_oldRel)) _oldRel = 50;
            nd.relation = Math.max(
              0,
              Math.min(
                100,
                _oldRel + Math.max(-20, Math.min(20, upd.relationDelta)),
              ),
            );
            changed = true;
          }
          if (upd.populationDelta) {
            nd.population = Math.max(
              0,
              (nd.population || 0) +
                Math.max(-20, Math.min(20, upd.populationDelta)),
            );
            changed = true;
          }
          // [V3.3] 女性人口变化
          if (upd.femaleDelta) {
            nd.femaleCount = Math.max(
              0,
              (nd.femaleCount || 0) +
                Math.max(-20, Math.min(20, upd.femaleDelta)),
            );
            changed = true;
          }
          if (upd.discovered && !(op.discovered || {})[nm]) {
            if (!op.discovered) op.discovered = {};
            op.discovered[nm] = {
              day: Number(
                _.get(currentPhoneData, "银麒系统.世界.末日倒计时", 0),
              ),
              source: "正文发现",
            };
            changed = true;
            if (typeof toastr !== "undefined")
              yqToast("success", "发现新据点：" + nm, "🏰", { timeOut: 4000 });
          }
          if (upd.awakenersAware && !nd.awakenersAware) {
            nd.awakenersAware = true;
            changed = true;
          }
          // [V3.3] 写入eventLog（API同步的变化也记录）
          if (changed) {
            if (!nd.eventLog) nd.eventLog = [];
            var _syncDay = Math.abs(
              Number(_.get(currentPhoneData, "银麒系统.世界.末日倒计时", 0)),
            );
            var _logParts = [];
            if (upd.relationDelta)
              _logParts.push(
                "关系" + (upd.relationDelta > 0 ? "+" : "") + upd.relationDelta,
              );
            if (upd.populationDelta)
              _logParts.push(
                "人口" +
                  (upd.populationDelta > 0 ? "+" : "") +
                  upd.populationDelta,
              );
            if (upd.femaleDelta)
              _logParts.push(
                "女性" + (upd.femaleDelta > 0 ? "+" : "") + upd.femaleDelta,
              );
            if (upd.notes) _logParts.push(upd.notes.substring(0, 30));
            if (_logParts.length > 0) {
              nd.eventLog.push(
                "D+" + _syncDay + " [同步] " + _logParts.join("，"),
              );
              if (nd.eventLog.length > 10) nd.eventLog = nd.eventLog.slice(-10);
            }
          }
        }
      }
    }
    // 觉醒者变化
    if (obj.awakeners) {
      for (var awn in obj.awakeners) {
        if (
          !obj.awakeners.hasOwnProperty(awn) ||
          !op.npcData ||
          !op.npcData[awn]
        )
          continue;
        var awnd = op.npcData[awn];
        var awChanges = obj.awakeners[awn].changes || [];
        for (var aci = 0; aci < awChanges.length; aci++) {
          var awc = awChanges[aci];
          if (!awc.name || !awc.event) continue;
          var awArr = awnd.awakeners || [];
          if (awc.event === "死亡") {
            awnd.awakeners = awArr.filter(function (a) {
              return a.name !== awc.name;
            });
            changed = true;
          }
          // [V3.3] 觉醒者事件写入eventLog
          if (!awnd.eventLog) awnd.eventLog = [];
          var _awkSyncDay = Math.abs(
            Number(_.get(currentPhoneData, "银麒系统.世界.末日倒计时", 0)),
          );
          awnd.eventLog.push(
            "D+" + _awkSyncDay + " [同步] 觉醒者" + awc.name + "死亡",
          );
          if (awnd.eventLog.length > 10)
            awnd.eventLog = awnd.eventLog.slice(-10);
          else if (awc.event === "转移") {
            awnd.awakeners = awArr.filter(function (a) {
              return a.name !== awc.name;
            });
            changed = true;
          }
        }
      }
    }
    if (changed) {
      setPhoneMeta("yinqi_outposts", op);
      console.log("[据点同步] 数据已更新");
      if (typeof toastr !== "undefined")
        yqToast("success", "据点数据已同步更新", "🏰", { timeOut: 3000 });
    }
    return { parsed: true, changed: changed, hasChanges: true };
  } catch (e) {
    console.warn("[据点同步] 解析失败:", e.message);
    return { parsed: false, changed: false, error: e.message };
  }
}


