/** 生成老板池（常驻送礼观众，支持自定义数量） */
function _generateBossPool(customCount) {
  var count = customCount || 3 + Math.floor(Math.random() * 3); // 默认3-5个
  var pool = [];
  var usedNicks = {};
  for (var i = 0; i < count; i++) {
    var nick;
    do {
      var r = Math.random();
      if (r < 0.4) {
        nick =
          _bossNickParts.prefix[
            Math.floor(Math.random() * _bossNickParts.prefix.length)
          ] +
          _bossNickParts.mid[
            Math.floor(Math.random() * _bossNickParts.mid.length)
          ];
      } else if (r < 0.7) {
        nick =
          _bossNickParts.mid[
            Math.floor(Math.random() * _bossNickParts.mid.length)
          ] +
          _bossNickParts.suffix[
            Math.floor(Math.random() * _bossNickParts.suffix.length)
          ];
      } else {
        nick =
          _bossNickParts.prefix[
            Math.floor(Math.random() * _bossNickParts.prefix.length)
          ] +
          _bossNickParts.mid[
            Math.floor(Math.random() * _bossNickParts.mid.length)
          ] +
          _bossNickParts.suffix[
            Math.floor(Math.random() * _bossNickParts.suffix.length)
          ];
      }
    } while (usedNicks[nick]);
    usedNicks[nick] = true;
    // 生成真名
    var realName =
      _bossNickParts.realSurnames[
        Math.floor(Math.random() * _bossNickParts.realSurnames.length)
      ] +
      _bossNickParts.realNames[
        Math.floor(Math.random() * _bossNickParts.realNames.length)
      ];
    if (Math.random() < 0.4) {
      realName +=
        _bossNickParts.realNames[
          Math.floor(Math.random() * _bossNickParts.realNames.length)
        ];
    }
    // 性别：70%男，30%女
    var gender = Math.random() < 0.7 ? "male" : "female";
    pool.push({ nick: nick, realName: realName, gender: gender });
  }
  // 随机指定1个狂热粉（送礼权重5倍）
  if (pool.length > 0) {
    var fanaticIdx = Math.floor(Math.random() * pool.length);
    pool[fanaticIdx].isFanatic = true;
  }
  return pool;
}

/** 计算线下见面阈值 */
function _calcMeetThreshold(room) {
  var mainChars = ["林知意", "苏曼", "林安然"];
  if (room.characterRef && mainChars.indexOf(room.characterRef) !== -1)
    return 1000000; // 主角100w不变
  if (room.hostGender === "male")
    return 200000 + Math.floor(Math.random() * 300001); // 20w-50w
  if (room.characterRef)
    // 剧情女性
    return 200000 + Math.floor(Math.random() * 600001); // 20w-80w
  return 200000 + Math.floor(Math.random() * 300001); // 20w-50w（随机女）
}

/** 判断是否热门房间 */
function _isHotRoom(room) {
  if (room.hostGender === "female") return true;
  if (room.involvedChars && room.involvedChars.length > 0) return true;
  if (/偷拍|深夜|福利|换装/.test(room.style || "")) return true;
  return false;
}

/** 根据阈值计算老板池数量 */
function _calcBossPoolSize(meetThreshold) {
  if (meetThreshold >= 800000) return 6 + Math.floor(Math.random() * 3); // 6-8
  if (meetThreshold >= 500000) return 5 + Math.floor(Math.random() * 2); // 5-6
  if (meetThreshold >= 300000) return 4 + Math.floor(Math.random() * 2); // 4-5
  if (meetThreshold >= 150000) return 3 + Math.floor(Math.random() * 2); // 3-4
  return 2 + Math.floor(Math.random() * 2); // 2-3
}

