      // 剧情角色直播间：生成时标记清理倒计轮数，下一轮AI回复后消失
      // 值为1表示"再经过1轮AI回复后清理"，0表示本轮可清理
      r._cleanupAfterRound = r.characterRef ? 1 : 0;
      // 老板池：数量根据阈值动态计算
      var _roomThreshold = _calcMeetThreshold(r);
      r.bossPool = _generateBossPool(_calcBossPoolSize(_roomThreshold));
      // 观众（老板）礼物累计 { "观众名": { total: 金额, realName: "真名", gender: "male"|"female" } }
      r.viewerGiftTotals = {};
      r.lastViewerGiftTime = 0;
      // 线下见面阈值 + 攻略度要求
      var _mainChars = ["林知意", "苏曼", "林安然"];
      if (r.characterRef && _mainChars.indexOf(r.characterRef) !== -1) {
        r.meetThreshold = 1000000;
        r.meetRequiresCorrupt = true;
        r.meetCorruptThreshold = 90;
      } else if (r.characterRef && r.hostGender === "female") {
        r.meetThreshold = _roomThreshold;
        r.meetRequiresCorrupt = true;
        r.meetCorruptThreshold = 80;
      } else {
        r.meetThreshold = _roomThreshold;
        r.meetRequiresCorrupt = false;
        r.meetCorruptThreshold = 0;
      }
    }

    // 追加到现有列表（新的在前面）
    var allRooms = rooms.concat(existingRooms);
    setLiveData(allRooms);

    // 自动生图模式下，为每个新直播间生成封面（串行：每个房间tag+渲染完成后再处理下一个）
    try {
      var imgSettings = getImageGenSettings();
      if (
        typeof isImageSceneAutoEnabled === "function"
          ? isImageSceneAutoEnabled("autoLive", imgSettings)
          : imgSettings.enabled && imgSettings.autoLive === true
      ) {
        // 使用串行异步循环，避免所有tag排队后才开始渲染
        (async function () {
          for (var cvi = 0; cvi < rooms.length; cvi++) {
            try {
              var coverRoom = rooms[cvi];
              var coverCtx = {
                hostName: coverRoom.hostName,
                style: coverRoom.style,
                sceneText: coverRoom.coverText || coverRoom.title || "",
                _gender: coverRoom.hostGender || "female",
                _auto: true,
                _priority: "high",
              };
              // involvedChars性别映射
              if (
                coverRoom.involvedChars &&
                coverRoom.involvedChars.length > 0
              ) {
                coverCtx.involvedChars = coverRoom.involvedChars;
                var _civGenders = {};
                for (
                  var _cigi = 0;
                  _cigi < coverRoom.involvedChars.length;
                  _cigi++
                ) {
                  _civGenders[coverRoom.involvedChars[_cigi]] =
                    coverRoom.hostGender === "male" ? "female" : "";
                }
                coverCtx._involvedGenders = _civGenders;
              }
              var cr = await window.phoneGenerateImage("live", coverCtx);
              if (cr && cr.success) {
                coverRoom.coverImageId = cr.imageId || cr.entryId;
                saveLiveRoom(coverRoom);
                // 每生成一张封面就刷新一次列表（用户能逐步看到封面出现）
                var $liveRefresh = $(".live-refresh-btn");
                if ($liveRefresh.length > 0 && !_liveCurrentRoomId) {
                  _renderLiveListPanelThrottled();
                }
              }
            } catch (e) {
              console.warn("[直播] 封面生成失败:", rooms[cvi].hostName, e);
            }
          }
        })();
      }
    } catch (coverErr) {
      console.warn("[直播] 封面生成失败:", coverErr);
    }

    // 有角色关联的直播间时，增加直播未读红点（但用户已在直播页面时不设置）
    var hasCharRef = false;
    for (var bi = 0; bi < rooms.length; bi++) {
      if (rooms[bi].characterRef) {
        hasCharRef = true;
        break;
      }
    }
    if (hasCharRef) {
      // 检查用户是否已在直播页面（有刷新按钮说明在直播列表页）
      var isOnLivePage =
        $(".live-refresh-btn").length > 0 || _liveCurrentRoomId;
      if (!isOnLivePage) {
        var gen = window.npcMsgGen;
        if (gen) {
          gen.setLiveUnread(1);
          gen.updateTotalUnreadBadge();
        }
      }
      if (typeof toastr !== "undefined")
        yqToast("warning", "有认识的人在直播...", "📺", { timeOut: 4000 });
    }

    yqToast("success", "直播间已生成");

    // #11: 为每个直播间生成首批观众互动
    for (var initI = 0; initI < rooms.length; initI++) {
      (function (initRoom) {
        _triggerHostResponse(initRoom, "auto", "").catch(function (e) {
          console.warn("[直播] 首批互动生成失败:", e);
        });
      })(rooms[initI]);
    }

    return rooms;
  } catch (e) {
    if (typeof toastr !== "undefined")
      yqToast("error", "直播间生成失败: " + (e.message || ""));
    console.warn("[直播] 生成失败:", e);
    return null;
  }
}
