function _renderLiveComments(comments) {
  if (!comments || comments.length === 0) {
    return '<div style="text-align:center;color:#64748b;font-size:13px;padding:28px 16px;line-height:1.6;background:rgba(255,255,255,0.04);border-radius:12px;border:1px dashed rgba(255,255,255,0.12);margin:4px 0;">欢迎来到直播间<br><span style="font-size:11px;color:#475569;">发条评论和主播互动吧</span></div>';
  }
  // 检查当前直播间是否有榜一玩家
  var _topBadge = "";
  if (_liveCurrentRoomId) {
    var _curRoom = getLiveRoom(_liveCurrentRoomId);
    if (_curRoom && _curRoom.playerIsTop) _topBadge = "🏆";
  }
  var playerNick = getLiveNickname();
  var html = "";
  var start = Math.max(0, comments.length - 30);
  for (var i = start; i < comments.length; i++) {
    var c = comments[i];
    var isGift = c.type === "gift";
    var isSystem = c.type === "system";
    var isPlayer = c.isPlayer;
    var isHost = c.type === "host";
    // 玩家榜一称号
    var displayName = c.author || "系统";
    if (isPlayer && _topBadge) {
      displayName = _topBadge + " " + displayName;
    }

    if (isGift) {
      // 礼物消息特效样式：带背景渐变和emoji
      html +=
        '<div style="margin-bottom:4px;padding:5px 8px;border-radius:8px;background:linear-gradient(90deg,rgba(251,191,36,0.15),rgba(239,68,68,0.1));border:1px solid rgba(251,191,36,0.3);font-size:12px;line-height:1.42;">';
      html +=
        '<span style="font-size:14px;margin-right:4px;">' +
        (c.giftEmoji || "🎁") +
        "</span>";
      html +=
        '<span style="color:#fbbf24;font-weight:600;">' +
        escapeHtml(c.content || "") +
        "</span>";
      html += "</div>";
    } else {
      var nameColor = isPlayer
        ? "#fbbf24"
        : isHost
          ? "#fda4af"
          : isSystem
            ? "#c4b5fd"
            : "#94a3b8";
      var contentColor = isHost ? "#ffe4e6" : isSystem ? "#e9d5ff" : "#e2e8f0";
      var nameBold = isPlayer || isHost ? "700" : "600";
      html +=
        '<div style="margin-bottom:5px;padding:6px 8px;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);border-radius:10px;font-size:12px;line-height:1.45;">';
      html +=
        '<div style="color:' +
        nameColor +
        ";font-weight:" +
        nameBold +
        ';font-size:11px;margin-bottom:2px;">' +
        escapeHtml(displayName) +
        "</div>";
      html +=
        '<div style="color:' +
        contentColor +
        ';">' +
        escapeHtml(c.content || "") +
        "</div>";
      html += "</div>";
    }
  }
  return html;
}

function _getLiveCommentsSignature(comments) {
  if (!Array.isArray(comments) || comments.length === 0) return "0";
  var start = Math.max(0, comments.length - 8);
  var topFlag = "0";
  try {
    if (_liveCurrentRoomId) {
      var _cr = getLiveRoom(_liveCurrentRoomId);
      if (_cr && _cr.playerIsTop) topFlag = "1";
    }
  } catch (eTop) {}
  var parts = [
    String(_liveCurrentRoomId || ""),
    String(comments.length),
    "top:" + topFlag,
  ];
  for (var i = start; i < comments.length; i++) {
    var c = comments[i] || {};
    parts.push(
      [
        String(c.type || ""),
        String(c.author || ""),
        String(c.time || c.ts || ""),
        String(c.content || ""),
        c.isPlayer ? "1" : "0",
        String(c.giftEmoji || ""),
      ].join("#"),
    );
  }
  return parts.join("|");
}

function _updateLiveCommentsView(comments) {
  var $comments = $("#live-comments");
  var _wasNearBottom = true;
  try {
    if ($comments[0]) {
      var _el = $comments[0];
      var _maxTop = Math.max(0, _el.scrollHeight - _el.clientHeight);
      _wasNearBottom = _maxTop - (_el.scrollTop || 0) <= 28;
    }
  } catch (_scrollErr) {}
  var signature = _getLiveCommentsSignature(comments);
  if (_updateLiveCommentsView._lastSignature === signature) return;
  _updateLiveCommentsView._lastSignature = signature;
  $comments.html(_renderLiveComments(comments));
  try {
    if ($comments[0] && _wasNearBottom) {
      $comments[0].scrollTop = $comments[0].scrollHeight;
      $("#live-comments-new-tip").remove();
      _updateLiveCommentsView._hasUnreadHint = false;
    } else if ($comments.length && !_wasNearBottom) {
      _updateLiveCommentsView._hasUnreadHint = true;
      if ($("#live-comments-new-tip").length === 0) {
        var $tip = $(
          '<button id="live-comments-new-tip" type="button" style="position:absolute;right:10px;bottom:56px;z-index:60;padding:4px 8px;border:1px solid #4c3d8f;border-radius:999px;background:#2d2654;color:#e2e8f0;font-size:11px;cursor:pointer;">有新评论，点此查看</button>',
        );
        $comments.parent().append($tip);
        $tip.on("click", function () {
          try {
            _liveScrollToBottomIfNear($comments);
          } catch (_tipErr) {}
          _updateLiveCommentsView._hasUnreadHint = false;
          $("#live-comments-new-tip").remove();
        });
      }
    }
  } catch (_hintErr) {}
}
function _liveScrollToBottomIfNear($target, force) {
  try {
    if (!$target || !$target[0]) return;
    var el = $target[0];
    var maxTop = Math.max(0, el.scrollHeight - el.clientHeight);
    var near = maxTop - (el.scrollTop || 0) <= 28;
    if (force || near) el.scrollTop = el.scrollHeight;
  } catch (_scrErr) {}
}
// ==================== 5. 弹幕系统 ====================
function _addDanmaku(text, isGift, expectedRoomId) {
  if (!_liveDanmakuEnabled) return;
  if (expectedRoomId && !_liveIsCurrentRoom(expectedRoomId)) return;
  var $layer = $("#live-danmaku-layer");
  if ($layer.length === 0) return;
  // 获取弹幕层宽度，fallback到父容器宽度或固定值
  var layerW = $layer.width();
  if (!layerW || layerW <= 0) {
    layerW = $layer.parent().width() || $layer.closest("[id]").width() || 300;
  }
  // 使用固定轨道避免重叠，增大行距
  var _danmakuTrackCount = 6;
  if (!window._danmakuNextTrack) window._danmakuNextTrack = 0;
  var trackIdx = window._danmakuNextTrack % _danmakuTrackCount;
  window._danmakuNextTrack++;
  var top = 5 + trackIdx * 15; // 每轨道间隔15%，共6轨道覆盖5%-80%
  var duration = 6 + Math.random() * 4;
  var colorStyle = isGift
    ? "color:#fbbf24;font-size:14px;font-weight:700;text-shadow:0 0 8px rgba(251,191,36,0.6),1px 1px 2px rgba(0,0,0,0.8);"
    : "color:white;font-size:12px;text-shadow:1px 1px 2px rgba(0,0,0,0.8);";
  // 使用CSS transition替代jQuery animate（在srcdoc iframe中更可靠）
  var $d = $(
    '<div style="position:absolute;top:' +
      top +
      "%;white-space:nowrap;pointer-events:none;" +
      colorStyle +
      "left:" +
      layerW +
      "px;transition:transform " +
      duration +
      's linear;will-change:transform;"></div>',
  );
  $d.text(text);
  $layer.append($d);
  // 延迟一帧启动CSS transition动画
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      var textW = $d.outerWidth() || 200;
      var moveDistance = layerW + textW + 40;
      $d.css("transform", "translateX(-" + moveDistance + "px)");
      // 动画结束后移除DOM
      setTimeout(
        function () {
          $d.remove();
        },
        duration * 1000 + 500,
      );
    });
  });
}

