    involved: { name: "#c084fc", text: "#e9d5ff" },
    other: { name: "#60a5fa", text: "#bfdbfe" },
  };
  // 构建多行台词HTML
  var linesHtml = "";
  for (var _dli = 0; _dli < textOrDialogues.length; _dli++) {
    var _dl = textOrDialogues[_dli];
    var _dlRole = _dl.role || "other";
    var _dlColors = _roleColors[_dlRole] || _roleColors.other;
