      (_dli > 0 ? "" : "margin-bottom:3px;") +
      '">' +
      '<span style="font-size:12px;">🎤</span>' +
      '<span style="font-size:10px;color:' +
      _dlColors.name +
      ';font-weight:700;letter-spacing:0.5px;">' +
      escapeHtml(_dlSpeaker) +
      "</span>" +
      "</div>" +
      '<div style="font-size:12px;color:' +
      _dlColors.text +
      ';line-height:1.5;font-style:italic;text-shadow:0 1px 2px rgba(0,0,0,0.5);">' +
      "「" +
      escapeHtml(_dlContent) +
      "」" +
      "</div>";
  }
  var $overlay = $(
    '<div class="live-host-dialogue-overlay" style="' +
      "position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);" +
      "z-index:8;max-width:85%;padding:10px 16px;" +
      "background:rgba(0,0,0,0.65);backdrop-filter:blur(4px);" +
      "border:1px solid rgba(168,85,247,0.4);border-radius:10px;" +
      "animation:liveDialogueFadeIn 0.4s ease;" +
      "pointer-events:none;max-height:60%;overflow-y:auto;" +
      '">' +
      linesHtml +
      "</div>",
  );
  $sceneParent.append($overlay);
  // 6秒后淡出消失
  setTimeout(function () {
    $overlay.css({ animation: "liveDialogueFadeAway 1s ease forwards" });
