// ==================== 7. 直播间互动逻辑 ====================
async function liveSendComment(text) {
  if (!text || !text.trim() || !_liveCurrentRoomId) return;
  var room = getLiveRoom(_liveCurrentRoomId);
  if (!room) return;

  if (room.isPlayerHosted) {
    // 玩家主播房间：输入作为主播动作/发言
    room.comments.push({
      author: room.hostName,
      content: text.trim(),
      type: "host",
      time: Date.now(),
    });
    saveLiveRoom(room);
    _addDanmaku(room.hostName + ": " + text.trim(), false, room.id);

    // 刷新评论
    _updateLiveCommentsView(room.comments);
    var $cc = $("#live-comments");
    _liveScrollToBottomIfNear($cc);

    // 触发AI生成观众反应 + 画面描述
    _triggerHostResponse(room, "playerAction", text.trim());
    try {
      if (typeof window.yqCharAppendEvent === "function") {
        var _evtHost = window.yqCharAppendEvent({
          charId: room.hostName || "主播",
          source: "live",
          channel: "live",
          action: "live_host_action",
          payload: {
            roomId: room.id || "",
            content: text.trim(),
          },
        });
        if (_evtHost && typeof window.yqApplyLinkRulesByEvent === "function") {
          window.yqApplyLinkRulesByEvent(_evtHost);
        }
      }
    } catch (_liveHostEvtErr) {}
    return;
  }

  // 普通房间：作为观众弹幕
  room.comments.push({
    author: getLiveNickname(),
    content: text.trim(),
    isPlayer: true,
    time: Date.now(),
  });
  room._playerCommentCount = (room._playerCommentCount || 0) + 1;
  try {
    var _yqSocC = window.getYqSocialConfig();
    if (
      room.hostName &&
      typeof window.yqMaybeTriggerFriendRequest === "function" &&
      (room._playerCommentCount >= _yqSocC.liveCommentFriendRequestMinCount ||
        (room.playerGiftTotal || 0) >=
          _yqSocC.liveCommentFriendRequestMinGiftTotal)
    ) {
      window.yqMaybeTriggerFriendRequest(room.hostName, {
        fromSource: "live_comment",
        reason: _yqSocC.liveFriendRequestReasonComment,
      });
    }
  } catch (_liveCommentReqErr) {}
  saveLiveRoom(room);
  _addDanmaku(text.trim(), false, room.id);

  // 刷新评论
  _updateLiveCommentsView(room.comments);
  var $cc2 = $("#live-comments");
  _liveScrollToBottomIfNear($cc2);

  // 触发主播回应
  _triggerHostResponse(room, "comment", text.trim());

  // 注入主AI上下文（玩家评论了）
  _injectLiveAwareness(room, "comment", text.trim());
  try {
    if (typeof window.yqCharAppendEvent === "function") {
      var _evtComment = window.yqCharAppendEvent({
        charId: room.hostName || "主播",
        source: "live",
        channel: "live",
        action: "live_player_comment",
        payload: {
          roomId: room.id || "",
          content: text.trim(),
          playerNick: getLiveNickname(),
        },
      });
      if (_evtComment && typeof window.yqApplyLinkRulesByEvent === "function") {
        window.yqApplyLinkRulesByEvent(_evtComment);
      }
    }
  } catch (_liveCommentEvtErr) {}
}

async function liveSendGift(giftKey) {
  if (!_liveCurrentRoomId) return;
  var room = getLiveRoom(_liveCurrentRoomId);
  if (!room) return;
  var gift = _getGiftConfig()[giftKey];
  if (!gift) return;

  // 银麒点消耗：正常1点，加速10点
  var _yqCost = room._speedupActive ? 10 : 1;
  try {
    var _tw = window.parent || window;
    var _spender = _tw._yqSpendSilverPoints || window._yqSpendSilverPoints;
    if (typeof _spender !== "function") {
      yqToast("error", "系统面板未就绪，无法扣减银麒点");
      return;
    }
    var _spRet = _spender(_yqCost, "live:gift");
    if (!_spRet || _spRet.ok !== true) {
      var _curPts = Number(_spRet && _spRet.pts) || 0;
      yqToast(
        "warning",
        "银麒点不足（需要" + _yqCost + "点，当前" + _curPts + "点）",
      );
      return;
    }
  } catch (e) {
    yqToast("error", "银麒点扣减失败");
    return;
  }

  // 累计本直播间银麒点消耗（退出时通知AI）
  room._yqPointsSpent = (room._yqPointsSpent || 0) + _yqCost;

  // 从礼物面板输入框读取附带消息
  var giftMessage = ($("#live-gift-message").val() || "").trim();

  // 记录礼物
  room.gifts.total += gift.price;
  room.gifts[giftKey] = (room.gifts[giftKey] || 0) + 1;
  // 累计玩家赠送金额（仅玩家礼物，不含AI观众礼物）
  room.playerGiftTotal = (room.playerGiftTotal || 0) + gift.price;
  try {
    var _yqSocG = window.getYqSocialConfig();
    if (
      room.hostName &&
      typeof window.yqMaybeTriggerFriendRequest === "function" &&
      (room.playerGiftTotal >= _yqSocG.liveGiftFriendRequestMinTotal ||
        (room._playerCommentCount || 0) >=
          _yqSocG.liveGiftFriendRequestMinComments)
    ) {
      window.yqMaybeTriggerFriendRequest(room.hostName, {
        fromSource: "live",
        reason: _yqSocG.liveFriendRequestReasonGift,
      });
    }
    if (
      room.hostName &&
      typeof window.yqMaybeTriggerGroupInvite === "function" &&
      room.playerGiftTotal >= _yqSocG.liveGroupInviteMinGiftTotal
    ) {
      window.yqMaybeTriggerGroupInvite(room.hostName, {
        groupId: "live_fans_" + String(room.id || room.hostName),
        groupName: (room.hostName || "主播") + "粉丝群",
      });
    }
  } catch (_liveSocialReqErr) {}

  // 系统消息（礼物特效样式）
  var giftText = getLiveNickname() + " 送出了 " + gift.name + "！";
  if (giftMessage) giftText += " 并说：「" + giftMessage + "」";
  room.comments.push({
    author: "系统",
    content: giftText,
    type: "gift",
    giftEmoji: gift.emoji,
    giftName: gift.name,
    time: Date.now(),
  });

  // 如果有附带消息，也添加为玩家评论
  if (giftMessage) {
    room.comments.push({
      author: getLiveNickname(),
      content: giftMessage,
      isPlayer: true,
      time: Date.now(),
    });
  }

  saveLiveRoom(room);
  // 礼物弹幕用特效样式
  _addDanmaku("🎁 " + getLiveNickname() + " 送出 " + gift.name, true, room.id);
  if (giftMessage) _addDanmaku(giftMessage, false, room.id);

  // 播放礼物全屏特效
  _showGiftEffect(gift, getLiveNickname(), room.id);

  // 清空附带消息输入框（面板保持打开，便于连续送礼）
  $("#live-gift-message").val("");

  // 刷新评论
  _updateLiveCommentsView(room.comments);
  var $cc = $("#live-comments");
  _liveScrollToBottomIfNear($cc);

  yqToast("success", "已送出 " + gift.name);

  // 触发主播回应（带礼物权重和附带消息）
  _triggerHostResponse(
    room,
    "gift",
    giftKey + (giftMessage ? "|" + giftMessage : ""),
  );

  // 注入主AI上下文（玩家互动了）
  _injectLiveAwareness(
    room,
    "gift",
    gift.name + (giftMessage ? "：" + giftMessage : ""),
  );
  try {
    if (typeof window.yqCharAppendEvent === "function") {
      var _evtGift = window.yqCharAppendEvent({
        charId: room.hostName || "主播",
        source: "live",
        channel: "live",
        action: "live_player_gift",
        payload: {
          roomId: room.id || "",
          giftKey: giftKey,
          giftName: gift.name,
          message: giftMessage || "",
          amount: Number(gift.price || 0),
        },
      });
      if (_evtGift && typeof window.yqApplyLinkRulesByEvent === "function") {
        window.yqApplyLinkRulesByEvent(_evtGift);
      }
    }
  } catch (_liveGiftEvtErr) {}

  // 动态检查是否达到线下见面条件，实时显示按钮
  _checkAndShowMeetButton(room);
}

/** 礼物全屏特效动画 */
function _showGiftEffect(gift, senderName, expectedRoomId) {
  if (expectedRoomId && !_liveIsCurrentRoom(expectedRoomId)) return;
  var $container = $("#live-detail-container");
  if ($container.length === 0) return;
  var displayName = senderName || getPlayerName();
  // 根据礼物等级确定缩放和粒子参数
  var scale, particleCount, fallTime;
  if (gift.multi >= 10) {
    scale = 0.7;
    particleCount = 12;
    fallTime = 1800;
  } else if (gift.multi >= 5) {
    scale = 0.7;
    particleCount = 8;
    fallTime = 1500;
  } else if (gift.weight >= 5) {
    scale = 0.7;
    particleCount = 5;
    fallTime = 1500;
  } else if (gift.weight >= 3) {
    scale = 0.55;
    particleCount = 3;
    fallTime = 1500;
  } else {
    scale = 0.4;
    particleCount = 2;
    fallTime = 1200;
  }
  // 显示名称（五连/十连加标识）
  var giftDisplayName = gift.name;
  if (gift.multi) giftDisplayName = gift.emoji + "×" + gift.multi;
  // 全屏礼物横幅
  var bgColor =
    gift.weight >= 5
      ? "linear-gradient(90deg,rgba(239,68,68,0.9),rgba(251,191,36,0.9),rgba(239,68,68,0.9))"
      : gift.weight >= 3
        ? "linear-gradient(90deg,rgba(124,58,237,0.85),rgba(99,102,241,0.85))"
        : "linear-gradient(90deg,rgba(59,130,246,0.8),rgba(99,102,241,0.8))";
  var bannerFontSize = Math.round(36 * scale);
  var bannerTextSize = Math.round(14 * scale);
  var $banner = $(
    '<div style="position:absolute;top:30%;left:0;right:0;z-index:100;text-align:center;padding:' +
      Math.round(16 * scale) +
      "px " +
      Math.round(12 * scale) +
      "px;" +
      "background:" +
      bgColor +
      ";pointer-events:none;opacity:0;transform:scale(" +
      scale +
      ');">' +
      '<div style="font-size:' +
      bannerFontSize +
      'px;margin-bottom:4px;">' +
      gift.emoji +
      (gift.multi
        ? '<span style="font-size:' +
          Math.round(bannerFontSize * 0.6) +
          'px;vertical-align:super;">×' +
          gift.multi +
          "</span>"
        : "") +
      "</div>" +
      '<div style="color:white;font-size:' +
      bannerTextSize +
      'px;font-weight:700;text-shadow:0 2px 4px rgba(0,0,0,0.5);">' +
      escapeHtml(displayName) +
      " 送出 " +
      escapeHtml(giftDisplayName) +
      "</div></div>",
  );
  $container.append($banner);
  $banner
    .animate({ opacity: 1 }, 200)
    .promise()
    .then(function () {
      $banner.css("transform", "scale(1)");
      setTimeout(function () {
        $banner.animate({ opacity: 0 }, 500, function () {
          $banner.remove();
        });
      }, 1500);
    });
  // 飘落emoji粒子
  for (var pi = 0; pi < particleCount; pi++) {
    (function (idx) {
      setTimeout(function () {
        var left = Math.random() * 90 + 5;
        var pSize = Math.round((16 + Math.random() * 12) * scale);
        var $p = $(
          '<div style="position:absolute;top:-30px;left:' +
            left +
            "%;font-size:" +
            pSize +
            'px;pointer-events:none;z-index:99;">' +
            gift.emoji +
            "</div>",
        );
        $container.append($p);
        $p.animate(
          { top: "100%", opacity: 0 },
          fallTime + Math.random() * 500,
          "linear",
          function () {
            $p.remove();
          },
        );
      }, idx * 100);
    })(pi);
  }
}

