      prompt +=
        "当主播决定不再忍受、准备结束直播时 → offlineTrigger=true，offlineReason填写原因。\n";
      prompt +=
        "注意：不是出现了出格弹幕就下播，而是主播内心真正忍无可忍时才触发。\n";
    }

    // 根据是否注入了下播规则决定JSON输出格式
    var _hasInvolvedForDialogues =
      room.involvedChars && room.involvedChars.length > 0;
    var _dialoguesField = _hasInvolvedForDialogues
      ? ',"dialogues":[{"speaker":"说话人名字","role":"host或involved","content":"台词"}]'
      : "";
    var _jsonFormat = _offlineRulesInjected
      ? '{"hostAction":"主播行为描述(50-150字)","hostReply":"主播说的话","sceneDialogue":"主播配合当前动作说的一句简短台词(带语气词,像真实直播中边做动作边说的话,15-30字)"' +
        _dialoguesField +
        ',"comments":[{"author":"网名","content":"弹幕内容"}],"offlineTrigger":"根据上述下播规则判定true或false","offlineReason":"如果offlineTrigger为true则填写原因，否则留空"}'
      : '{"hostAction":"主播行为描述(50-150字)","hostReply":"主播说的话","sceneDialogue":"主播配合当前动作说的一句简短台词(带语气词,像真实直播中边做动作边说的话,15-30字)"' +
        _dialoguesField +
        ',"comments":[{"author":"网名","content":"弹幕内容"}]}';
    prompt += "\n输出JSON：" + _jsonFormat + "\n只输出JSON。";

    var result = await liveAPI.callChatAPI("", prompt, {
      skipCustomPrompt: true,
      includeChatContext: false,
      includeMVU: false,
      includeBuiltinWorld: false,
      triggerSource: "live:" + _roomId + ":" + String(triggerType || "unknown"),
    });
    if (!_liveIsRoomJobCurrent(room, _roomId, "_liveHostJobSeq", _hostJobSeq))
      return;
    result = stripJsonCodeBlock(result);
    var jsonMatch = result.match(/\{[\s\S]*\}/);
    if (!jsonMatch) return;
    var data = JSON.parse(jsonMatch[0]);

    // 更新场景文字
    if (data.hostAction) {
      room.currentSceneText = data.hostAction;
      room.currentSceneDialogue = data.sceneDialogue || "";
      room.sceneHistory.push({
        text: data.hostAction,
        time: Date.now(),
        trigger: triggerType,
      });
      if (room.sceneHistory.length > 10)
        room.sceneHistory = room.sceneHistory.slice(-10);
    }

    // 主播回复（自动模式下50%概率回复，玩家互动时必定回复）
    if (data.hostReply) {
      var shouldHostReply = triggerType !== "auto" || Math.random() < 0.5;
      if (shouldHostReply) {
        room.comments.push({
          author: room.hostName,
          content: data.hostReply,
          type: "host",
          time: Date.now(),
        });
        _addDanmaku(room.hostName + ": " + data.hostReply, false, _roomId);
      }
    }

    // 观众弹幕（含礼物特效）
    if (data.comments && Array.isArray(data.comments)) {
      for (var ci = 0; ci < data.comments.length; ci++) {
        var c = data.comments[ci];
        if (c.author && c.content) {
          // 普通弹幕（gift字段已从AI prompt中移除）
          room.comments.push({
            author: c.author,
            content: c.content,
            time: Date.now() + ci,
          });
          _addDanmaku(c.content, false, _roomId);
        }
      }
      // 客户端随机触发老板送礼（新系统：热门/普通分档，老板只送火箭，路人送跑车/游轮）
      var _hot = _isHotRoom(room);
      var _giftProb = _hot ? 0.3 : 0.2;
      var _giftCooldown = _hot ? 45000 : 75000;
      var _lastGift = room.lastViewerGiftTime || 0;
      var _bossPool = room.bossPool || [];
      if (
        triggerType === "auto" &&
        _bossPool.length > 0 &&
        Math.random() < _giftProb &&
        Date.now() - _lastGift > _giftCooldown &&
        !room._viewerMeetTriggered
      ) {
        // 加权随机选老板（狂热粉权重5倍）
        var _bWeights = [];
        var _bTotalW = 0;
        for (var _bwi = 0; _bwi < _bossPool.length; _bwi++) {
          var _bw = _bossPool[_bwi].isFanatic ? 5 : 1;
          _bWeights.push(_bw);
          _bTotalW += _bw;
        }
        var _bRoll = Math.random() * _bTotalW;
        var _bBossIdx = 0;
        for (var _bwi2 = 0; _bwi2 < _bWeights.length; _bwi2++) {
          _bRoll -= _bWeights[_bwi2];
          if (_bRoll <= 0) {
            _bBossIdx = _bwi2;
            break;
          }
        }
        var boss = _bossPool[_bBossIdx];
        var bossNick = boss.nick;
        // 老板只送火箭级别
        var _bgRoll = Math.random();
        var _bgKey, _bgChance5, _bgChance10;
        if (_hot) {
          _bgChance5 = 0.3;
          _bgChance10 = 0.1;
        } else {
          _bgChance5 = 0.2;
          _bgChance10 = 0.05;
        }
        if (_bgRoll < 1 - _bgChance5 - _bgChance10) _bgKey = "rocket";
        else if (_bgRoll < 1 - _bgChance10) _bgKey = "rocket5";
        else _bgKey = "rocket10";
        var aiGift = _getGiftConfig()[_bgKey];
        room.gifts.total += aiGift.price;
        room.gifts[_bgKey] = (room.gifts[_bgKey] || 0) + 1;
        room.lastViewerGiftTime = Date.now();
        // 累计该老板的送礼金额
        if (!room.viewerGiftTotals) room.viewerGiftTotals = {};
        if (!room.viewerGiftTotals[bossNick]) {
          room.viewerGiftTotals[bossNick] = {
            total: 0,
            realName: boss.realName,
            gender: boss.gender || "male",
          };
        }
        room.viewerGiftTotals[bossNick].total += aiGift.price;
        var _bgDisplayName = aiGift.multi
          ? aiGift.emoji + "×" + aiGift.multi
          : aiGift.name;
        room.comments.push({
          author: "系统",
          content: bossNick + " 送出了 " + _bgDisplayName + "！",
          type: "gift",
          giftEmoji: aiGift.emoji,
          giftName: aiGift.name,
          time: Date.now() + 100,
        });
        _addDanmaku(
          "🎁 " + bossNick + " 送出 " + _bgDisplayName,
          true,
          _roomId,
        );
        _showGiftEffect(aiGift, bossNick, _roomId);
        // 检查该老板是否达到线下见面阈值（玩家榜一时锁定）
        if (!room.playerIsTop) {
          var _bossTotal = room.viewerGiftTotals[bossNick].total;
          var _bMeetThreshold = room.meetThreshold || 999999999;
          var _bCanMeet = false;
          if (_bossTotal >= _bMeetThreshold) {
            if (room.meetRequiresCorrupt) {
              try {
                fetchLatestMvuData(true);
                var _bmd = currentPhoneData || {};
                var _bCharRef = room.characterRef || "";
                var _bCorrupt = 0;
                if (_bCharRef === "林知意") {
                  _bCorrupt =
                    parseInt(_.get(_bmd, "角色.林知意.奉献度", 0)) || 0;
                } else if (_bCharRef) {
                  _bCorrupt =
                    parseInt(
                      _.get(_bmd, "女性角色." + _bCharRef + ".攻略度", 0),
                    ) || 0;
                }
                var _bReqCorrupt = room.meetCorruptThreshold || 80;
                if (_bCorrupt >= _bReqCorrupt) _bCanMeet = true;
              } catch (e) {}
            } else {
              _bCanMeet = true;
            }
          }
          if (_bCanMeet) {
            room._viewerMeetTriggered = true;
            room._meetTriggeredBy = bossNick;
            room._meetTriggeredByReal = boss.realName;
            saveLiveRoom(room);
            // 延迟触发线下见面流程
            setTimeout(function () {
              _handleViewerMeet(
                room,
                bossNick,
                boss.realName,
                boss.gender || "male",
              );
            }, 2000);
          }
        }
      }
      // 路人送礼（纯氛围，不累计，独立于老板送礼）
      if (triggerType === "auto" && Math.random() < 0.4) {
        var _casualNick =
          _bossNickParts.prefix[
            Math.floor(Math.random() * _bossNickParts.prefix.length)
          ] +
          "路人" +
          Math.floor(Math.random() * 999);
        var _casualGift =
          Math.random() < 0.7 ? _liveGiftConfig.car : _liveGiftConfig.yacht;
        room.comments.push({
          author: "系统",
          content: _casualNick + " 送出了 " + _casualGift.name + "！",
          type: "gift",
          giftEmoji: _casualGift.emoji,
          giftName: _casualGift.name,
          time: Date.now() + 150,
        });
        _addDanmaku(
          "🎁 " + _casualNick + " 送出 " + _casualGift.name,
          true,
          _roomId,
        );
        _showGiftEffect(_casualGift, _casualNick, _roomId);
      }
    }

    saveLiveRoom(room);

    // ===== 模块D：剧情角色直播内容通知主AI（独立于AI感知） =====
    _injectStoryCharLiveContent(room, data);

    // ===== offlineTrigger 下播处理 =====
    var _offlineTriggered =
      data.offlineTrigger === true || data.offlineTrigger === "true";
    if (_offlineTriggered) {
      // 停止自动循环
      if (_liveCurrentRoomId === room.id) {
        _liveAutoLoopRunning = false;
        if (_liveAutoTimer) {
          clearTimeout(_liveAutoTimer);
          _liveAutoTimer = null;
        }
        if (_liveCommentTimer) {
          clearTimeout(_liveCommentTimer);
          _liveCommentTimer = null;
        }
        if (_liveImageTimer) {
          clearTimeout(_liveImageTimer);
          _liveImageTimer = null;
        }
      }
      // 先刷新当前回复到UI，再执行下播序列
      if (_liveCurrentRoomId === room.id) {
        _updateLiveCommentsView(room.comments);
        var $ccOff = $("#live-comments");
        _liveScrollToBottomIfNear($ccOff);
      }
      await _generateOfflineSequence(room, data.offlineReason || "直播被中断");
      return; // 下播后不再执行后续UI刷新
    }

    // 刷新UI
    if (_liveCurrentRoomId === room.id) {
      // 更新场景文字（仅当没有图片显示时才用文字覆盖）
      var $scene = $("#live-scene-area");
      if (
        $scene.length > 0 &&
        data.hostAction &&
        !room.currentSceneImageId &&
        $scene.find("img").length === 0
      ) {
        var _sceneHtml =
          '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0f0a1e,#1e1b4b);padding:16px;position:relative;"><div style="font-size:13px;color:#a78bfa;text-align:center;line-height:1.6;">' +
          escapeHtml(data.hostAction) +
          "</div></div>";
        $scene.html(_sceneHtml);
        // A路径：没开文生图时，sceneDialogue跟文字画面一起显示
        var _imgS = getImageGenSettings();
        if (!_imgS.enabled) {
          if (
            data.dialogues &&
            Array.isArray(data.dialogues) &&
            data.dialogues.length > 0
          ) {
            _showSceneDialogue(data.dialogues, room.hostName);
          } else if (data.sceneDialogue) {
            _showSceneDialogue(data.sceneDialogue, room.hostName);
          }
        }
      }
      // 刷新评论
      _updateLiveCommentsView(room.comments);
      var $cc = $("#live-comments");
      _liveScrollToBottomIfNear($cc);
    }

    // 画面生成已独立到 _triggerLiveImageGen / _maybeTriggerLiveImage
    // 此处不再自动触发生图
  } catch (e) {
    console.warn("[直播互动] 失败:", e);
  } finally {
    if (_autoHostLock && room) room._autoHostInflight = false;
  }
}

// ==================== 7.5 下播序列生成 ====================
/**
 * 生成下播对话序列（模块A需求5）
 * 不是直接关闭，而是生成3-5条主播口吻的告别回复后下播
 */
async function _generateOfflineSequence(room, reason) {
  try {
    var liveAPI = window.phoneAPI.live;
    if (!liveAPI || !liveAPI.isAvailable()) {
      // API不可用时直接下播
      _executeOffline(room, reason);
      return;
    }
    var offPrompt =
      "主播「" +
      room.hostName +
      "」（" +
      (room.hostGender === "male" ? "男" : "女") +
      "）的直播即将因为以下原因结束：" +
      reason +
      "\n";
    offPrompt += _liveBuildRoomPromptContext(room);
    offPrompt += "当前场景：" + (room.currentSceneText || "直播中") + "\n";
    if (room.hostGender === "male") {
      offPrompt += "该主播是男性，必须使用男性口吻。\n";
    }
    offPrompt += "请生成主播下播前的3-5条回复（符合主播口吻和当前情境）。\n";
    offPrompt +=
      "最后一条必须是告别/结束语。如果是被迫中断（被发现/被阻止），回复应体现慌张/恐惧/愤怒等情绪。\n";
    offPrompt += '输出JSON数组：[{"content":"主播说的话"}]\n只输出JSON。';

    var offResult = await liveAPI.callChatAPI("", offPrompt, {
      skipCustomPrompt: true,
      includeChatContext: false,
      includeMVU: false,
      includeBuiltinWorld: false,
      triggerSource: "live:" + String(room.id || "") + ":offline",
    });
    if (offResult) {
      offResult = offResult.replace(/```json\s*/gi, "").replace(/```\s*/g, "");
      var offMatch = offResult.match(/\[[\s\S]*\]/);
      if (offMatch) {
        var offData = JSON.parse(offMatch[0]);
        if (Array.isArray(offData)) {
          // 逐条添加到评论区
          for (var oi = 0; oi < offData.length; oi++) {
            if (offData[oi].content) {
              room.comments.push({
                author: room.hostName,
                content: offData[oi].content,
                type: "host",
                time: Date.now() + (oi + 1) * 500,
              });
            }
          }
        }
      }
    }
  } catch (offErr) {
    console.warn("[下播序列] 生成失败:", offErr);
  }
  _executeOffline(room, reason);
}

/**
 * 执行下播操作（设置状态、添加系统消息、刷新UI）
 */
function _executeOffline(room, reason) {
  // 添加系统消息
  room.comments.push({
    author: "系统",
    content: "🔴 " + room.hostName + " 的直播已结束",
    type: "system",
    time: Date.now() + 5000,
  });
  room.isLive = false;
  room._offlineReason = "interrupted";
  room._offlineTime = Date.now();
  room._offlineSummary = reason;
  if (!room.isFavorited) {
    room._offlineCleanupRound = 1;
  }
  saveLiveRoom(room);

  // 更新模块D的事件状态为已下播
  try {
    var _offEvents = getPhoneMeta("phone_story_live_events", {});
    var _offKeys = Object.keys(_offEvents);
    for (var _oi = 0; _oi < _offKeys.length; _oi++) {
      if (_offEvents[_offKeys[_oi]].roomId === room.id) {
        _offEvents[_offKeys[_oi]].isLive = false;
        _offEvents[_offKeys[_oi]].time = Date.now(); // 重置过期计时
      }
    }
    setPhoneMeta("phone_story_live_events", _offEvents);
  } catch (_oe) {}

  // 刷新UI（如果玩家正在观看）
  if (_liveCurrentRoomId === room.id) {
    // 刷新评论区
    _updateLiveCommentsView(room.comments);
    var $ccOff2 = $("#live-comments");
    _liveScrollToBottomIfNear($ccOff2);
    // 画面切换为"直播已结束"
    var $sceneOff = $("#live-scene-area");
    if ($sceneOff.length > 0) {
      $sceneOff.html(
        '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:#1a1a2e;">' +
          '<div style="text-align:center;color:#6b7280;">' +
          '<div style="font-size:48px;margin-bottom:12px;">📺</div>' +
          '<div style="font-size:16px;font-weight:600;">直播已结束</div>' +
          '<div style="font-size:12px;margin-top:6px;color:#4b5563;">' +
          escapeHtml(reason) +
          "</div>" +
          "</div></div>",
      );
    }
    // 隐藏送礼/评论输入框
    $("#live-comment-input")
      .prop("disabled", true)
      .attr("placeholder", "直播已结束");
    $("#live-send-comment-btn").prop("disabled", true);
    $(".live-gift-btn").prop("disabled", true);
  }
  console.log("[直播下播] " + room.hostName + " 已下播，原因：" + reason);
}

// ==================== 7.6 剧情角色直播内容通知主AI（模块D） ====================
/**
 * 当直播间涉及女性剧情角色时，将互动内容注入主AI上下文
 * 独立于AI感知设置，始终生效
 */
function _injectStoryCharLiveContent(room, responseData) {
  try {
    // 收集涉及的剧情角色（包括男性和女性）
    var storyChars = [];
    fetchLatestMvuData(true);
    var _dM = currentPhoneData || {};

    // 检查 characterRef（剧情角色开播，不限性别）
    if (room.characterRef) {
      var _crData =
        room.characterRef === "林知意"
          ? _.get(_dM, "林知意", null)
          : _.get(_dM, "女性角色." + room.characterRef, null);
      // 男性角色：从男性角色record中获取
      if (!_crData && room.hostGender === "male") {
        _crData = _.get(_dM, "男性角色." + room.characterRef, null);
      }
      if (_crData) storyChars.push(room.characterRef);
    }
    // 检查 involvedChars（被涉及的剧情角色）
    if (room.involvedChars && room.involvedChars.length > 0) {
      for (var _mi = 0; _mi < room.involvedChars.length; _mi++) {
        var _mName = room.involvedChars[_mi];
        if (storyChars.indexOf(_mName) !== -1) continue;
        var _mData =
          _mName === "林知意"
            ? _.get(_dM, "林知意", null)
            : _.get(_dM, "女性角色." + _mName, null);
        if (_mData) storyChars.push(_mName);
      }
    }
    if (storyChars.length === 0) return;

    // 构建注入内容
    var events = getPhoneMeta("phone_story_live_events", {});
    var sceneText = (room.currentSceneText || "").substring(0, 120);
    var hostReply =
      responseData && responseData.hostReply
        ? responseData.hostReply.substring(0, 60)
        : "";
    // 提取最近2条玩家互动
    var playerInteractions = "";
    if (room.comments && room.comments.length > 0) {
      var _pComments = [];
      for (
        var _pi = room.comments.length - 1;
        _pi >= 0 && _pComments.length < 2;
        _pi--
      ) {
        if (room.comments[_pi].isPlayer) _pComments.unshift(room.comments[_pi]);
      }
      if (_pComments.length > 0) {
        playerInteractions = _pComments
          .map(function (c) {
            return c.content.substring(0, 40);
          })
          .join("；");
      }
    }

    for (var _si = 0; _si < storyChars.length; _si++) {
      var charName = storyChars[_si];
      var entry = "直播间「" + room.hostName + "」涉及「" + charName + "」：";
      entry += sceneText;
      if (hostReply) entry += "｜主播：" + hostReply;
      if (playerInteractions) entry += "｜{{user}}互动：" + playerInteractions;
      // 每个角色只保留最新一条（覆盖旧的）
      events[charName] = {
        content: entry,
        roomId: room.id,
        hostName: room.hostName,
        time: Date.now(),
        isLive: room.isLive !== false,
        remainingRounds: 2, // 保留2轮AI回复后删除
      };
    }
    setPhoneMeta("phone_story_live_events", events);
    // 触发注入
    injectNpcSummaryToContext();
  } catch (e) {
    console.warn("[剧情角色直播通知] 失败:", e);
  }
}

// ==================== 7.5 直播间举报/删除 ====================
/** 安全删除直播间：停止循环 → 等待in-flight操作 → 删除 → 刷新 */
window.phoneLiveDeleteRoom = function (roomId) {
  var room = getLiveRoom(roomId);
  if (!room) return;
  var isOwn = room.isPlayerHosted;
  var msg = isOwn
    ? "确定要删除自己的直播间吗？"
    : "确定要举报（封禁）该直播间吗？";
  if (!confirm(msg)) return;
  // 停止自动循环
  if (_liveCurrentRoomId === roomId) {
    stopLiveAutoGeneration();
  }
  // 延迟500ms等待可能的in-flight异步操作完成后再删除
  setTimeout(function () {
    _removeLiveRoom(roomId);
    if (typeof toastr !== "undefined") {
      yqToast("success", isOwn ? "直播间已删除" : "直播间已举报封禁");
    }
    // 刷新直播列表
    if (typeof openAppPanel === "function") {
      openAppPanel("live");
    }
  }, 500);
};

/** 直播间内举报彩蛋：AI生成主播反应后删除 */
async function _handleLiveReport(roomId) {
  var room = getLiveRoom(roomId);
  if (!room) return;
  // 玩家自己的直播间：直接删除，无彩蛋
  if (room.isPlayerHosted) {
    window.phoneLiveDeleteRoom(roomId);
    return;
  }
  if (!confirm("确定要举报该直播间？主播可能会有反应...")) return;
  // 停止自动循环
  if (_liveCurrentRoomId === roomId) {
    _liveAutoLoopRunning = false;
    if (_liveAutoTimer) {
      clearTimeout(_liveAutoTimer);
      _liveAutoTimer = null;
    }
    if (_liveCommentTimer) {
      clearTimeout(_liveCommentTimer);
      _liveCommentTimer = null;
    }
    if (_liveImageTimer) {
      clearTimeout(_liveImageTimer);
      _liveImageTimer = null;
    }
  }
  // 禁用所有操作
  $("#live-comment-input")
    .prop("disabled", true)
    .attr("placeholder", "举报处理中...");
  $(
    "#live-send-comment-btn,#live-gift-btn,#live-like-btn,#live-genimg-btn,#live-report-btn",
  )
    .prop("disabled", true)
    .css("opacity", "0.4");
  // 添加系统消息
