// ==================== 8. 自动循环生成（对话5s + 画面3min分离） ====================
var _liveAutoLoopRunning = false;
var _liveImageTimer = null;

function startLiveAutoGeneration(roomId) {
  stopLiveAutoGeneration();
  _liveCurrentRoomId = roomId;
  _liveAutoLoopRunning = true;

  // 启动对话链式循环：每次生成完成后等5s再生成下一次
  _liveAutoLoopNext(roomId);
  // 启动画面自动循环：生图成功后10秒触发下一次
  _liveImageAutoLoop(roomId);
}

function stopLiveAutoGeneration() {
  _liveAutoLoopRunning = false;
  if (_liveAutoTimer) {
    clearTimeout(_liveAutoTimer);
    _liveAutoTimer = null;
  }
  if (_liveCommentTimer) {
    clearTimeout(_liveCommentTimer);
