/**
 * 清理剧情角色直播间（每轮AI回复后调用）
 * 有characterRef的直播间在下一轮AI回复后自动消失（不可收藏保护）
 */
function _cleanupCharRefLiveRooms() {
  try {
    var rooms = getLiveData() || [];
    var changed = false;
    var newRooms = [];
    for (var i = 0; i < rooms.length; i++) {
      var r = rooms[i];
      // 已下播的直播间（线下见面等导致isLive=false）：基于倒计轮数清理
      if (r.isLive === false) {
        // 收藏的直播间下播后保留（灰色显示），不清理
        if (r.isFavorited) {
          newRooms.push(r);
          continue;
        }
        // 如果有倒计轮数且大于0，倒计一轮，保留
        if (
          typeof r._offlineCleanupRound === "number" &&
          r._offlineCleanupRound > 0
        ) {
          r._offlineCleanupRound--;
          changed = true;
          newRooms.push(r);
          continue;
        }
        // 如果玩家正在观看这个直播间，暂不清理
        if (_liveCurrentRoomId === r.id) {
          newRooms.push(r);
          continue;
        }
        // 清理图片资源
        if (r.coverImageId && window.phoneImageStore)
          window.phoneImageStore.remove(r.coverImageId);
        if (r.currentSceneImageId && window.phoneImageStore)
          window.phoneImageStore.remove(r.currentSceneImageId);
        changed = true;
        console.log("[直播清理] 已下播直播间已移除：" + r.hostName);
        continue;
      }
      // 剧情角色直播间：基于倒计轮数清理
      // 兼容旧版 _pendingCleanup 字段：迁移为 _cleanupAfterRound = 0（立即可清理）
      if (
        r.characterRef &&
        r._pendingCleanup &&
        typeof r._cleanupAfterRound !== "number"
      ) {
        r._cleanupAfterRound = 0;
      }
      if (r.characterRef && typeof r._cleanupAfterRound === "number") {
        if (r._cleanupAfterRound > 0) {
          // 还没到清理时机，倒计一轮，保留
          r._cleanupAfterRound--;
          changed = true; // 需要保存倒计后的值
          newRooms.push(r);
          continue;
        }
        // _cleanupAfterRound === 0，本轮可清理
        // 收藏的剧情角色直播间：不删除，改为下播状态等待复播
        if (r.isFavorited) {
          r.isLive = false;
          r._offlineReason = r._offlineReason || "auto"; // 自然下播
          r._offlineTime = Date.now();
          r._offlineSummary = r._offlineSummary || "主播自然结束了直播。";
          changed = true;
          newRooms.push(r);
          console.log(
            "[直播清理] 收藏的剧情角色直播间已下播（保留）：" + r.hostName,
          );
          continue;
        }
        // 如果玩家正在观看这个直播间，暂不清理
        if (_liveCurrentRoomId === r.id) {
          newRooms.push(r);
          continue;
        }
        // 清理图片资源
        if (r.coverImageId && window.phoneImageStore)
          window.phoneImageStore.remove(r.coverImageId);
        if (r.currentSceneImageId && window.phoneImageStore)
          window.phoneImageStore.remove(r.currentSceneImageId);
        changed = true;
        console.log(
          "[直播清理] 剧情角色直播间已移除：" +
            r.hostName +
            "（" +
            r.characterRef +
            "）",
        );
        continue;
      }
      newRooms.push(r);
    }
    if (changed) {
      setLiveData(newRooms);
      // 如果当前在直播列表页，刷新显示
      if (
        typeof currentPanel !== "undefined" &&
        currentPanel === "live" &&
        !_liveCurrentRoomId
      ) {
        $("#phone-app-body").html(generateLiveListPanel());
        if (typeof bindPanelButtons === "function") bindPanelButtons();
      }
    }

    // 模块D：剧情角色直播事件倒计清理（每轮AI回复-1，到0删除）
    try {
      var _slEvents = getPhoneMeta("phone_story_live_events", {});
      var _slKeys = Object.keys(_slEvents);
      var _slChanged = false;
      for (var _sli = _slKeys.length - 1; _sli >= 0; _sli--) {
        var _slEvt = _slEvents[_slKeys[_sli]];
        if (!_slEvt) continue;
        // 直播仍在进行中的事件：检查对应直播间是否还存在且在播
        if (_slEvt.isLive) {
          var _slRoom = null;
          for (var _slri = 0; _slri < newRooms.length; _slri++) {
            if (newRooms[_slri].id === _slEvt.roomId) {
              _slRoom = newRooms[_slri];
              break;
            }
          }
          // 直播间已不存在或已下播 → 直接删除事件
          if (!_slRoom || _slRoom.isLive === false) {
            delete _slEvents[_slKeys[_sli]];
            _slChanged = true;
          }
          continue;
        }
        // 已下播的事件：倒计
        if (typeof _slEvt.remainingRounds === "number") {
          _slEvt.remainingRounds--;
          if (_slEvt.remainingRounds <= 0) {
            delete _slEvents[_slKeys[_sli]];
          }
          _slChanged = true;
        }
      }
      if (_slChanged) setPhoneMeta("phone_story_live_events", _slEvents);
    } catch (_slErr) {}
  } catch (e) {
    console.warn("[直播清理] 剧情角色直播间清理失败:", e);
  }
}

/** 对话链式循环：生成完成 → 等N秒 → 再生成 */
function _normalizeLiveLoopIntervalMs(baseSec) {
  var sec = Number(baseSec || 5);
  if (!(sec > 0)) sec = 5;
  var factor =
    typeof getPhonePerfFactor === "function" ? getPhonePerfFactor() : 1;
  var ms = sec * 1000 * factor;
  try {
    if (typeof document !== "undefined" && document.hidden)
      return Math.max(ms, 12000);
    if (!$("#mobile-phone-overlay").hasClass("active"))
      return Math.max(ms, 10000);
  } catch (_e) {}
  return ms;
}
function _liveAutoLoopNext(roomId) {
  if (!_liveAutoLoopRunning || _liveCurrentRoomId !== roomId) return;
  var room = getLiveRoom(roomId);
  if (!room) return;

  // 从设置读取观众刷新间隔
  var ch = window.phoneAPI && window.phoneAPI.live;
  var commentInterval = (ch && ch.settings._liveCommentInterval) || 5;
  var intervalMs = _normalizeLiveLoopIntervalMs(commentInterval);

  _triggerHostResponse(room, "auto", "", { skipImage: true })
    .then(function () {
      if (_liveAutoLoopRunning && _liveCurrentRoomId === roomId) {
        _liveAutoTimer = setTimeout(function () {
          _liveAutoLoopNext(roomId);
        }, intervalMs);
      }
    })
    .catch(function (e) {
      console.warn("[直播自动循环] 对话生成失败:", e);
      if (_liveAutoLoopRunning && _liveCurrentRoomId === roomId) {
        _liveAutoTimer = setTimeout(function () {
          _liveAutoLoopNext(roomId);
        }, intervalMs);
      }
    });
}

/** 画面自动循环：生图成功后等10秒再触发下一次 */
function _liveImageAutoLoop(roomId) {
  if (!_liveAutoLoopRunning || _liveCurrentRoomId !== roomId) return;
  var room = getLiveRoom(roomId);
  if (!room) return;
  // 首次进入时立即触发一次生图
  _triggerLiveImageGen(room, "auto");
}

/** 触发直播画面生成（独立于对话，后台静默生成，成功后直接切换画面） */
function _triggerLiveImageGen(room, trigger) {
  try {
    if (room && room._liveImageInflight) return;
    var imgSettings = getImageGenSettings();
    if (
      !(typeof isImageSceneAutoEnabled === "function"
        ? isImageSceneAutoEnabled("autoLive", imgSettings)
        : imgSettings.enabled && imgSettings.autoLive === true)
    )
      return;
    var _imgRoomId = _liveRoomId(room);
    if (!_imgRoomId) return;
    var _imgJobSeq = _liveStartRoomJob(room, "_liveImageJobSeq");
    if (room) room._liveImageInflight = true;
    // 从设置读取画面刷新间隔
    var ch = window.phoneAPI && window.phoneAPI.live;
    var imageInterval = (ch && ch.settings._liveImageInterval) || 10;
    var imageIntervalMs = _normalizeLiveLoopIntervalMs(imageInterval);
    var ctx = {
      roomId: _imgRoomId,
      jobId: _imgJobSeq,
      hostName: room.hostName,
      style: room.style,
      sceneText: room.currentSceneText || room.coverText || room.title,
      _gender: room.hostGender || "female",
      _auto: trigger === "auto",
      _priority: "high",
    };
    // 场景历史：保持画面连续性（最近3条）
    if (room.sceneHistory && room.sceneHistory.length > 0) {
      var recentScenes = room.sceneHistory.slice(-3);
      var sceneHistoryText = recentScenes
        .map(function (s) {
          return s.text.substring(0, 80);
        })
        .join(" → ");
      ctx.sceneHistory = sceneHistoryText;
    }
    // 高优先级互动内容提取：玩家评论 > 主播回复 > 礼物要求 > 普通弹幕
    if (room.comments && room.comments.length > 0) {
      var recent = room.comments.slice(-15);
      var playerComments = [];
      var hostReplies = [];
      var giftMessages = [];
      var otherComments = [];
      for (var ci = 0; ci < recent.length; ci++) {
        var c = recent[ci];
        if (c.isPlayer) playerComments.push(c);
        else if (c.type === "host") hostReplies.push(c);
        else if (c.type === "gift") giftMessages.push(c);
        else if (c.type !== "system") otherComments.push(c);
      }
      // 按优先级组装：玩家→主播→礼物→其他，总共最多8条
      var prioritized = [];
      var _pushN = function (arr, n) {
        for (var i = Math.max(0, arr.length - n); i < arr.length; i++)
          prioritized.push(arr[i]);
      };
      _pushN(playerComments, 3);
      _pushN(hostReplies, 3);
      _pushN(giftMessages, 2);
      if (prioritized.length < 5) _pushN(otherComments, 5 - prioritized.length);
      var commentText = prioritized
        .map(function (c) {
          var prefix = c.isPlayer
            ? "【玩家】"
            : c.type === "host"
              ? "【主播】"
              : c.type === "gift"
                ? "【礼物】"
                : "";
          return (
            prefix +
            (c.author || "") +
            ": " +
            (c.content || "").substring(0, 60)
          );
        })
        .join("\n");
      ctx.recentComments = commentText;
    }
    // 角色一致性：传递characterRef
    if (room.characterRef) {
      ctx.characterRef = room.characterRef;
    }
    // 涉及的其他角色（如男主播偷拍/展示的女性）
    if (room.involvedChars && room.involvedChars.length > 0) {
      ctx.involvedChars = room.involvedChars;
      // 构建involvedChars的性别映射，供角色外观生成使用
      var _ivGenders = {};
      for (var _igi = 0; _igi < room.involvedChars.length; _igi++) {
        // 男主播涉及的角色通常是女性（偷拍/展示对象）
        _ivGenders[room.involvedChars[_igi]] =
          room.hostGender === "male" ? "female" : "";
      }
      ctx._involvedGenders = _ivGenders;
    }
    var genFn = window.phoneGenerateImage;
    // 后台静默生成，不显示loading文字，成功后直接切换画面
    genFn("live", ctx)
      .then(function (r) {
        if (
          !_liveIsRoomJobCurrent(
            room,
            _imgRoomId,
            "_liveImageJobSeq",
            _imgJobSeq,
          )
        )
          return;
        if (r && r.success) {
          room.currentSceneImageId = r.imageId || r.entryId;
          // #10: 同步更新封面
          room.coverImageId = room.currentSceneImageId;
          saveLiveRoom(room);
          // 仅当用户仍在该直播间时才更新画面
          if (_liveIsCurrentRoom(_imgRoomId)) {
            var imgData = r.imageData;
            if (!imgData && window.phoneImageStore) {
              imgData = window.phoneImageStore.load(room.currentSceneImageId);
            }
            if (imgData) {
              $("#live-scene-area").html(
                '<img src="' +
                  imgData +
                  '" style="width:100%;height:100%;object-fit:contain;background:#000;">',
              );
              // B路径：生图完成后显示配套台词浮层
              if (r.liveLine) {
                _showSceneDialogue(r.liveLine, room.hostName);
              }
            }
          }
          if (typeof toastr !== "undefined" && trigger !== "auto") {
            yqToast("success", "直播画面已更新", "📺");
          }
        }
        // #8: 生图完成后（无论成功失败），N秒后触发下一次自动生图
        if (
          trigger === "auto" &&
          _liveAutoLoopRunning &&
          _liveIsCurrentRoom(_imgRoomId)
        ) {
          _liveImageTimer = setTimeout(function () {
            if (_liveAutoLoopRunning && _liveIsCurrentRoom(_imgRoomId)) {
              var freshRoom = getLiveRoom(_imgRoomId);
              if (freshRoom) _triggerLiveImageGen(freshRoom, "auto");
            }
          }, imageIntervalMs);
        }
      })
      .catch(function () {
        if (
          !_liveIsRoomJobCurrent(
            room,
            _imgRoomId,
            "_liveImageJobSeq",
            _imgJobSeq,
          )
        )
          return;
        // 失败也要继续循环
        if (
          trigger === "auto" &&
          _liveAutoLoopRunning &&
          _liveIsCurrentRoom(_imgRoomId)
        ) {
          _liveImageTimer = setTimeout(function () {
            if (_liveAutoLoopRunning && _liveIsCurrentRoom(_imgRoomId)) {
              var freshRoom = getLiveRoom(_imgRoomId);
              if (freshRoom) _triggerLiveImageGen(freshRoom, "auto");
            }
          }, imageIntervalMs);
        }
      })
      .finally(function () {
        if (room) room._liveImageInflight = false;
      });
  } catch (imgErr) {
    if (room) room._liveImageInflight = false;
    console.warn("[直播画面] 生图失败:", imgErr);
  }
}

