async function _autoGenerateComment(roomId) {
  var liveAPI = window.phoneAPI.live;
  if (!liveAPI || !liveAPI.isAvailable()) return;
  var room = getLiveRoom(roomId);
  if (!room) return;

  try {
    var prompt =
      "生成2条直播间观众弹幕评论。主播：" +
      room.hostName +
      "，风格：" +
      (room.style || "综合") +
      "\n";
