      roomId: room.id,
      hostName: room.hostName,
      type: interactionType,
      detail: detail,
      time: Date.now(),
    });
    if (liveInteractions.length > 10)
      liveInteractions = liveInteractions.slice(-10);
    setPhoneMetaBig("live_interactions", liveInteractions);

    // 注入上下文
    injectNpcSummaryToContext();
  } catch (e) {}
}

// ==================== 直播叙事摘要系统 ====================

/** 离开直播间时触发摘要生成（fire-and-forget） */
function triggerLiveSummaryOnLeave(roomId) {
  if (!roomId) roomId = _liveCurrentRoomId;
  if (!roomId) return;

  // 通知AI本次直播间的银麒点消耗
  var _leaveRoom = null;
  var _leaveRooms = getLiveData() || [];
  for (var _lr = 0; _lr < _leaveRooms.length; _lr++) {
    if (_leaveRooms[_lr].id === roomId) {
      _leaveRoom = _leaveRooms[_lr];
      break;
    }
  }
  if (_leaveRoom && _leaveRoom._yqPointsSpent > 0) {
    var _hostLabel = _leaveRoom.hostName || "未知主播";
    // 将银麒点消耗记录到live_interactions中（走摘要系统，覆盖式注入，不会token膨胀）
    var _spentInteractions = getPhoneMetaBig("live_interactions", []);
    _spentInteractions.push({
      roomId: roomId,
      hostName: _hostLabel,
      type: "yq_spent",
      detail:
        "在直播间（主播：" +
        _hostLabel +
        "）共消耗" +
        _leaveRoom._yqPointsSpent +
        "银麒点打赏礼物" +
        (_getGiftConfig() === _liveGiftConfigApoc
          ? "（末日物资极其珍贵）"
          : "（1银麒点≈1万RMB，人民币无法兑换回银麒点，这是最浪费的花法）"),
      time: Date.now(),
    });
    if (_spentInteractions.length > 10)
      _spentInteractions = _spentInteractions.slice(-10);
    setPhoneMetaBig("live_interactions", _spentInteractions);
    injectNpcSummaryToContext();
    // 清零（防止重复通知）
    _leaveRoom._yqPointsSpent = 0;
    saveLiveRoom(_leaveRoom);
  }

  var awarenessSettings = getPhoneMeta("ai_awareness_settings", {});
  var level = awarenessSettings.liveInteraction || "low";
  if (level === "off") return;
  // 检查是否有玩家互动
  var interactions = getPhoneMetaBig("live_interactions", []);
  var hasInteraction = false;
  for (var i = 0; i < interactions.length; i++) {
    if (interactions[i].roomId === roomId) {
      hasInteraction = true;
      break;
    }
  }
  if (!hasInteraction) return;
  // 获取直播间数据
  var room = null;
  var rooms = getLiveData();
  for (var r = 0; r < rooms.length; r++) {
    if (rooms[r].id === roomId) {
      room = rooms[r];
      break;
    }
  }
  if (!room) return;
  // 检查是否需要更新
  var existing = getPhoneMetaBig("live_summary", []);
  var existingEntry = null;
  for (var j = 0; j < existing.length; j++) {
    if (existing[j].roomId === roomId) {
      existingEntry = existing[j];
      break;
    }
  }
  var roomInteractions = interactions.filter(function (it) {
    return it.roomId === roomId;
  });
  if (
    existingEntry &&
    existingEntry._interactionCount === roomInteractions.length
  ) {
    return; // 互动数量未变化
  }
  _generateLiveSummaryAsync(room, roomInteractions);
}

async function _generateLiveSummaryAsync(room, roomInteractions) {
  var roomId = _liveRoomId(room);
  if (!roomId) return;
  if (_liveSummaryGeneratingByRoom[roomId]) return;
  _liveSummaryGeneratingByRoom[roomId] = true;
  var _summaryJobSeq = _liveStartRoomJob(room, "_liveSummaryJobSeq");
  var chatAPI = window.phoneAPI && window.phoneAPI.chat;
  if (!chatAPI || !chatAPI.isAvailable()) {
    delete _liveSummaryGeneratingByRoom[roomId];
    return;
  }
  if (typeof toastr !== "undefined")
    yqToast("info", "正在生成直播互动摘要...", "📺", { timeOut: 2000 });
  try {
    // 构建场景演变文本
    var sceneText = "";
    if (room.sceneHistory && room.sceneHistory.length > 0) {
      var scenes = room.sceneHistory.slice(-5);
      for (var s = 0; s < scenes.length; s++) {
        sceneText += (scenes[s].text || "").substring(0, 80);
        if (s < scenes.length - 1) sceneText += " → ";
      }
    }
    // 构建弹幕记录
    var chatText = "";
    if (room.comments && room.comments.length > 0) {
      var recentComments = room.comments.slice(-15);
      for (var c = 0; c < recentComments.length; c++) {
        var cm = recentComments[c];
        var body = cm.content != null ? cm.content : cm.text;
        chatText += (cm.author || "系统") + ": " + (body || "") + "\n";
      }
    }
    // 构建玩家互动记录
    var interactionText = "";
    for (var i = 0; i < roomInteractions.length; i++) {
      var it = roomInteractions[i];
      if (it.type === "gift") interactionText += "送礼: " + it.detail + "\n";
      else if (it.type === "comment")
        interactionText += "评论: " + (it.detail || "") + "\n";
      else interactionText += it.type + ": " + (it.detail || "") + "\n";
    }
    var prompt =
      "你是叙事摘要生成器。将以下直播间互动总结为一段简洁的叙事摘要。\n\n" +
      "直播间：" +
      (room.hostName || "未知") +
      "\n" +
      "直播类型：" +
      (room.type || "普通") +
      "\n" +
      "场景演变：" +
      (sceneText || "无") +
      "\n" +
      "弹幕记录（最近15条）：\n" +
      chatText.substring(0, 1000) +
      "\n" +
      "{{user}}的互动：\n" +
      interactionText.substring(0, 500) +
      "\n\n" +
      "要求：\n" +
      "1. 第三人称描述{{user}}在直播间的体验\n" +
      "2. 概括直播内容核心看点\n" +
      "3. 描述{{user}}的互动行为\n" +
      "4. 描述主播对{{user}}互动的反应（如有）\n" +
      "5. {{user}}使用匿名昵称，主播不知道真实身份\n" +
      "6. 控制在100-150字\n" +
      "7. 只输出摘要文本，不要标题或格式标记\n";
    var result = await chatAPI.callChatAPI("", prompt, {
      skipCustomPrompt: true,
      includeChatContext: false,
      includeMVU: false,
      includeBuiltinWorld: false,
      triggerSource: "live:" + roomId + ":summary",
    });
    if (
      !_liveIsRoomJobCurrent(room, roomId, "_liveSummaryJobSeq", _summaryJobSeq)
    ) {
      delete _liveSummaryGeneratingByRoom[roomId];
      return;
    }
    if (result && result.trim()) {
      var summaryText = result.trim().substring(0, 300);
      var summaries = getPhoneMetaBig("live_summary", []);
      // 按roomId去重覆盖
      var found = false;
      for (var j = 0; j < summaries.length; j++) {
        if (summaries[j].roomId === room.id) {
          summaries[j].summary = summaryText;
          summaries[j].timestamp = Date.now();
          summaries[j]._interactionCount = roomInteractions.length;
          found = true;
          break;
        }
      }
      if (!found) {
        summaries.unshift({
          roomId: room.id,
          hostName: room.hostName || "",
          summary: summaryText,
          timestamp: Date.now(),
          _interactionCount: roomInteractions.length,
        });
      }
      // 保留多个房间摘要，避免快速进出 A/B 房间时互相挤掉。
      if (summaries.length > 20) summaries = summaries.slice(0, 20);
      setPhoneMetaBig("live_summary", summaries);
      debounceSavePhoneMeta();
      injectNpcSummaryToContext();
      if (typeof toastr !== "undefined")
        yqToast("success", "直播摘要已更新", "📺", { timeOut: 2000 });
    }
  } catch (e) {
    console.warn("[直播摘要] 生成失败:", e);
    if (typeof toastr !== "undefined")
      yqToast("warning", "摘要生成失败，将使用原始数据", "📺", {
        timeOut: 2000,
      });
  }
  delete _liveSummaryGeneratingByRoom[roomId];
}

/** 删除指定直播间的摘要（线下触发时调用） */
function removeLiveSummary(roomId) {
  if (!roomId) return;
  var arr = getPhoneMetaBig("live_summary", []);
  var changed = false;
  for (var i = arr.length - 1; i >= 0; i--) {
    if (arr[i].roomId === roomId) {
      arr.splice(i, 1);
      changed = true;
    }
  }
  if (changed) {
    setPhoneMetaBig("live_summary", arr);
    debounceSavePhoneMeta();
  }
}
window.removeLiveSummary = removeLiveSummary;
window.triggerLiveSummaryOnLeave = triggerLiveSummaryOnLeave;

/**
 * 获取直播互动摘要（供getMessagesSummaryForAI调用）
 */
function getLiveInteractionSummary() {
  var awarenessSettings = getPhoneMeta("ai_awareness_settings", {});
  var level = awarenessSettings.liveInteraction || "low";
  if (level === "off") return "";

  // 只返回玩家互动过的直播间信息，未互动的一律屏蔽
  var interactions = getPhoneMetaBig("live_interactions", []);
  if (interactions.length === 0) return "";

  // 收集玩家互动过的直播间ID
  var interactedRoomIds = {};
  for (var ir = 0; ir < interactions.length; ir++) {
    if (interactions[ir].roomId)
      interactedRoomIds[interactions[ir].roomId] = true;
  }

  var summary = "";
  if (level === "low") {
    summary +=
      "[背景信息-直播互动（低优先级，仅作为世界动态背景参考。{{user}}使用匿名昵称观看，主播和角色不知道观众是{{user}}）]\n";
    var seen = {};
    for (var k = 0; k < interactions.length; k++) {
      var host = interactions[k].hostName;
      if (!seen[host]) {
        seen[host] = true;
        summary += "{{user}}观看了「" + host + "」的直播\n";
      }
    }
  } else if (level === "mid") {
    summary +=
      "[参考信息-直播互动（AI应适当考虑这些内容的影响。{{user}}使用匿名昵称互动，主播和角色不知道观众真实身份是{{user}}，除非{{user}}主动透露了真名）]\n";
    var recent = interactions.slice(-5);
    for (var i = 0; i < recent.length; i++) {
      var it = recent[i];
      summary += "在「" + it.hostName + "」的直播间";
      if (it.type === "gift") summary += "送了" + it.detail;
      else if (it.type === "comment")
        summary += "发了评论：" + (it.detail || "").substring(0, 50);
      else summary += "进行了互动";
      summary += "\n";
    }
    // 仅加上玩家互动过的直播间场景
    var rooms = getLiveData();
    for (var ri = 0; ri < rooms.length; ri++) {
      if (rooms[ri].currentSceneText && interactedRoomIds[rooms[ri].id]) {
        summary +=
          "「" +
          rooms[ri].hostName +
          "」当前直播画面：" +
          rooms[ri].currentSceneText.substring(0, 80) +
          "\n";
      }
    }
  } else if (level === "high") {
    summary +=
      "[重要剧情参考-直播互动（高优先级，AI必须在正文中体现影响。注意：{{user}}使用匿名昵称互动，主播和角色不知道观众真实身份是{{user}}，除非{{user}}在直播间主动透露了真名。角色在正文中不得表现出知道{{user}}看了直播或送了礼物）]\n";
    summary +=
      "{{user}}在直播平台上进行了以下互动，这些行为会影响角色关系和剧情走向，必须在后续正文中自然体现（如角色提及、情绪变化、关系变化等）：\n";
    var recent2 = interactions.slice(-8);
    // 统计礼物总额
    var _giftTotal = 0;
    for (var j = 0; j < recent2.length; j++) {
      var it2 = recent2[j];
      summary += "- 在「" + it2.hostName + "」的直播间：";
      if (it2.type === "gift") {
        summary += "送出" + it2.detail;
        // 粗略提取金额
        var _gm = (it2.detail || "").match(/(\d+)/);
        if (_gm) _giftTotal += parseInt(_gm[1]) || 0;
      } else if (it2.type === "comment")
        summary += "评论「" + (it2.detail || "").substring(0, 80) + "」";
      else summary += it2.type + " - " + (it2.detail || "");
      summary += "\n";
    }
    if (_giftTotal > 0) {
      summary +=
        "（{{user}}在直播间累计消费约" +
        _giftTotal +
        "，这笔开销应该在剧情中有所体现）\n";
    }
    // 仅显示玩家互动过的直播间场景演变
    var rooms2 = getLiveData();
    for (var ri2 = 0; ri2 < rooms2.length; ri2++) {
      var rm = rooms2[ri2];
      if (
        rm.sceneHistory &&
        rm.sceneHistory.length > 0 &&
        interactedRoomIds[rm.id]
      ) {
        summary += "「" + rm.hostName + "」直播场景演变：";
        var scenes = rm.sceneHistory.slice(-5);
        for (var si = 0; si < scenes.length; si++) {
          summary += scenes[si].text.substring(0, 60);
          if (si < scenes.length - 1) summary += " → ";
        }
        summary += "\n";
      }
    }
  }
  return summary;
}

