window.phoneOpenLiveRoom = function (roomId) {
  var room = getLiveRoom(roomId);
  if (!room) {
    yqToast("warning", "直播间不存在");
    return;
  }
  // 已下播的直播间不可进入
  if (room.isLive === false) {
    if (typeof toastr !== "undefined")
      yqToast("info", room.hostName + " 已下播", "📺");
    return;
  }
  // 保存导航栈
  navigationStack.push({
    title: "📺 斗瘾直播",
    content: generateLiveListPanel(),
  });
  $("#phone-app-title").text(room.hostName + "的直播间");
  $("#phone-app-body").html(generateLiveDetailPanel(roomId));
  // 启动自动生成
  startLiveAutoGeneration(roomId);
  // 绑定事件
  setTimeout(function () {
    _bindLiveDetailEvents();
    var _freshRoom =
      typeof getLiveRoom === "function" ? getLiveRoom(roomId) : room;
    if (!_freshRoom || _freshRoom.isLive === false) return;
    if (_freshRoom.comments.length === 0) {
      _triggerHostResponse(_freshRoom, "auto", "");
    }
  }, 100);
};

function _bindLiveDetailEvents() {
  // 已下播房间：禁用交互控件
  var _roomId = _liveCurrentRoomId;
  if (_roomId) {
    var _room = getLiveRoom(_roomId);
    if (_room && _room.isLive === false) {
      $("#live-comment-input")
        .prop("disabled", true)
        .attr("placeholder", "直播已结束");
      $(
        "#live-send-comment-btn,#live-gift-btn,#live-like-btn,#live-genimg-btn,#live-player-end-btn",
      )
        .prop("disabled", true)
        .css("opacity", "0.4");
    }
  }
  // 发送评论
  $("#live-send-comment-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      var text = $("#live-comment-input").val();
      if (text && text.trim()) {
        liveSendComment(text);
        $("#live-comment-input").val("");
      }
    });
  // 回车发送
  $("#live-comment-input")
    .off("keypress")
    .on("keypress", function (e) {
      if (e.which === 13) {
        e.preventDefault();
        var text = $(this).val();
        if (text && text.trim()) {
          liveSendComment(text);
          $(this).val("");
        }
      }
    });
  // 弹幕开关
  $("#live-danmaku-toggle")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      _liveDanmakuEnabled = !_liveDanmakuEnabled;
      $(this).css("background", _liveDanmakuEnabled ? "#6366f1" : "#4b5563");
      $("#live-danmaku-layer").toggle(_liveDanmakuEnabled);
    });
  // 礼物按钮
  $("#live-gift-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      _showGiftPanel();
    });
  // 直播间内举报按钮
  $("#live-report-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      var roomId = $(this).data("room-id");
      if (roomId) _handleLiveReport(roomId);
    });
  // 手动生图按钮
  $("#live-genimg-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      if (!_liveCurrentRoomId) return;
      var room = getLiveRoom(_liveCurrentRoomId);
      if (!room) return;
      var check = isImageGenReady();
      if (!check.ready) {
        if (typeof toastr !== "undefined")
          yqToast("warning", check.reason, "🎨 直播生图");
        return;
      }
      var $btn = $(this);
      $btn.prop("disabled", true).css("opacity", "0.5");
      if (typeof toastr !== "undefined")
        yqToast("info", "正在生成直播画面...", "🎨");
      var ctx = {
        hostName: room.hostName,
        style: room.style,
        sceneText: room.currentSceneText || room.coverText || room.title,
        _priority: "medium",
      };
      // 角色一致性：传递characterRef和involvedChars
      if (room.characterRef) ctx.characterRef = room.characterRef;
      if (room.involvedChars && room.involvedChars.length > 0)
        ctx.involvedChars = room.involvedChars;
      window
        .phoneGenerateImage("live", ctx)
        .then(function (r) {
          if (r && r.success && r.imageData) {
            room.currentSceneImageId = r.imageId || r.entryId;
            saveLiveRoom(room);
            if (_liveCurrentRoomId === room.id) {
              $("#live-scene-area").html(
                '<img src="' +
                  r.imageData +
                  '" style="width:100%;height:100%;object-fit:contain;background:#000;">',
              );
              // 手动生图也显示配套台词
              if (r.liveLine) {
                _showSceneDialogue(r.liveLine, room.hostName);
              }
            }
            if (typeof toastr !== "undefined")
              yqToast("success", "直播画面已生成", "🎨");
          } else {
            if (typeof toastr !== "undefined")
              yqToast("error", (r && r.error) || "生图失败", "🎨");
          }
        })
        .catch(function (err) {
          if (typeof toastr !== "undefined")
            yqToast("error", err.message || "生图失败", "🎨");
        })
        .finally(function () {
          $btn.prop("disabled", false).css("opacity", "1");
        });
    });
  // 送礼物（使用容器级事件委托，避免全局冲突）
  $("#live-detail-container")
    .off("click.livegift")
    .on("click.livegift", ".live-send-gift-btn", function (e) {
      e.preventDefault();
      e.stopPropagation();
      var giftKey = $(this).attr("data-gift");
      if (giftKey) liveSendGift(giftKey);
    });
  // 点赞
  $("#live-like-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      _addDanmaku("❤️", false, _liveCurrentRoomId);
      // 飘心动画
      var $btn = $(this);
      var $heart = $(
        '<span style="position:absolute;color:#ef4444;font-size:20px;pointer-events:none;">❤️</span>',
      );
      $btn.parent().css("position", "relative").append($heart);
      $heart.animate({ bottom: "+=40px", opacity: 0 }, 800, function () {
        $heart.remove();
      });
    });
  // 线下见面按钮
  $("#live-meet-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      e.preventDefault();
      var roomId = $(this).data("room-id");
      if (!roomId) return;
      var room = getLiveRoom(roomId);
      if (!room) return;
      var $btn = $(this);
      $btn.prop("disabled", true).text("⏳ 约定中...");
      _handleLiveMeet(room);
    });
  // 玩家主播：榜单按钮
  $("#live-leaderboard-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      e.preventDefault();
      var roomId = $(this).data("room-id");
      if (!roomId) return;
      var room = getLiveRoom(roomId);
      if (room) _showPlayerLeaderboard(room);
    });
  // 玩家主播：结束直播按钮
  $("#live-player-end-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      e.preventDefault();
      if (!confirm("确定要结束直播吗？")) return;
      var roomId = $(this).data("room-id");
      if (!roomId) return;
      var room = getLiveRoom(roomId);
      if (!room) return;
      room.comments.push({
        author: "系统",
        content: "🔴 " + room.hostName + " 已结束直播",
        type: "system",
        time: Date.now(),
      });
      room.isLive = false;
      room._offlineReason = "manual";
      room._offlineTime = Date.now();
      room._offlineSummary = "主播手动结束直播";
      saveLiveRoom(room);
      stopLiveAutoGeneration();
