        _meetPrompt +=
          "- 弹幕中是否包含任何剧情角色的真名、职位、身份信息？如有则必须替换为外貌描述\n";
        _meetPrompt +=
          '\n输出JSON数组，每个元素是一步对话：\n[{"type":"host","content":"主播说的话"},{"type":"player","content":"玩家说的话"},{"type":"danmaku","content":"弹幕内容"},{"type":"host","content":"主播回应"},...]\n';
        _meetPrompt +=
