        _meetPrompt +=
          "生成6-10步对话，最后一步必须是主播宣布下播。只输出JSON。";

        var _meetResult = await liveAPI.callChatAPI("", _meetPrompt, {
          skipCustomPrompt: true,
          includeChatContext: false,
          includeMVU: false,
          includeBuiltinWorld: false,
          triggerSource: "live:" + String(room.id || "") + ":meet",
        });
        _meetResult = stripJsonCodeBlock(_meetResult);
        var _meetMatch = _meetResult.match(/\[[\s\S]*\]/);
        if (_meetMatch) {
          _meetDialogue = JSON.parse(_meetMatch[0]);
          if (!Array.isArray(_meetDialogue) || _meetDialogue.length < 3)
            _meetDialogue = null;
