          { type: "danmaku", content: "有人约主播了？" },
          { type: "player", content: "对，出来聊聊" },
          { type: "host", content: "行吧，大哥赏脸，那就见见" },
          { type: "danmaku", content: "主播要出去了" },
          { type: "host", content: "各位先散了，我有点事，回头再播" },
          { type: "danmaku", content: "主播下了！" },
