      }
    }

    // 播放对话序列
    for (var _di = 0; _di < _meetDialogue.length; _di++) {
      var _step = _meetDialogue[_di];
      if (!_step || !_step.content) continue;
      if (_step.type === "host") {
        addComment(room.hostName, _step.content, "host");
        await wait(1800 + Math.floor(Math.random() * 700));
      } else if (_step.type === "player") {
        addComment(getLiveNickname(), _step.content, null, true);
        await wait(1500 + Math.floor(Math.random() * 500));
      } else if (_step.type === "danmaku") {
        _addDanmaku(_step.content, false, room.id);
