    _insertLiveMeetFloor(room);
    // 线下触发：删除该直播间的摘要
    if (typeof removeLiveSummary === "function" && room.id) {
      removeLiveSummary(room.id);
    }

    // 约见面后跳过2轮自动生成，让AI专注回应LiveMeetEvent
    // [V10.4·2026-05-13] per-key 跳轮，只影响 live 和 chat，不影响 forum/surveillance/worldEvents
    if (typeof _autoGenSkipByKey !== "undefined") {
      _autoGenSkipByKey.live = 2;
      _autoGenSkipByKey.chat = 2;
    } else if (typeof _autoGenSkipRounds !== "undefined") {
      _autoGenSkipRounds = 2;
    }
    // 等待2秒后关闭
    await wait(2000);

    // 停止自动生成
    stopLiveAutoGeneration();

    // 标记直播间已结束（保留在列表中显示为灰色，不删除）
    room.isLive = false;
    // 记录下播原因和互动摘要（用于复播时的记忆）
    room._offlineReason = "player"; // 玩家约
    room._offlineMeetWith = getLiveNickname();
    // 记录玩家真实名字，防止换昵称后主播认不出
