    }
    room._offlineTime = Date.now();
    room._offlineSummary =
      "玩家（" +
      getLiveNickname() +
      "）打赏" +
      (room.playerGiftTotal || 0) +
      (_getGiftConfig() === _liveGiftConfigApoc
        ? "个物资后约主播线下见面，主播"
        : "元后约主播线下见面，主播") +
      (room.hostGender === "male"
        ? (function () {
            var _s = (room.style || "").toLowerCase();
            var _hi = room.involvedChars && room.involvedChars.length > 0;
            var _sub = _hi && /展示|炫耀|奉献|夫妻|情侣|共享|绿/.test(_s);
            if (_hi && !_sub && !/偷拍|挑衅|控制|威胁|PUA/.test(_s))
              _sub = true;
            return _sub ? "热情答应出来见面" : "答应出来见面";
          })()
        : "同意并下播") +
      "。";
    // 收藏的直播间不设清理倒计（永久保留等待复播），非收藏的下一轮清理
    if (!room.isFavorited) {
      room._offlineCleanupRound = 1;
    }
