  if (!prompt) {
    yqToast("error", "请输入风格提示词");
    return;
  }
  if (!lss.customStyles) lss.customStyles = [];
  var isDup = lss.customStyles.some(function (s, i) {
    return s.name === name && i !== editIndex;
  });
  if (isDup) {
