/** 偷拍被发现事件处理 */
function _handleDiscoveryEvent(room, data) {
  try {
    // 停止自动循环
    if (_liveCurrentRoomId === room.id) {
      _liveAutoLoopRunning = false;
      if (_liveAutoTimer) {
        clearTimeout(_liveAutoTimer);
        _liveAutoTimer = null;
      }
      if (_liveCommentTimer) {
        clearTimeout(_liveCommentTimer);
        _liveCommentTimer = null;
      }
      if (_liveImageTimer) {
        clearTimeout(_liveImageTimer);
        _liveImageTimer = null;
      }
    }
    var reason = data.discoveryReason || "偷拍被发现";
    room.comments.push({
      author: "系统",
      content: "⚠️ " + reason,
      type: "system",
      time: Date.now(),
    });
    // 检查涉及角色攻略度决定是否强制下播
    var _forceOffline = true;
    if (room.involvedChars && room.involvedChars.length > 0) {
      try {
        fetchLatestMvuData(true);
        var _dd = currentPhoneData || {};
        for (var _dci = 0; _dci < room.involvedChars.length; _dci++) {
          var _dcName = room.involvedChars[_dci];
          var _dcData =
            _dcName === "林知意"
              ? _.get(_dd, "林知意", null)
              : _.get(_dd, "女性角色." + _dcName, null);
          if (_dcData) {
            var _dcCorrupt = parseInt(_.get(_dcData, "攻略度", 0)) || 0;
            if (_dcCorrupt >= 70) {
              _forceOffline = false;
              break;
            }
          }
        }
      } catch (e) {}
    }
    if (_forceOffline) {
      room.comments.push({
        author: "系统",
        content: "🔴 直播被迫中断",
        type: "system",
        time: Date.now() + 1,
      });
      room.isLive = false;
      room._offlineReason = "discovery";
      room._offlineTime = Date.now();
      room._offlineSummary = reason;
      saveLiveRoom(room);
      stopLiveAutoGeneration();
      if (_liveCurrentRoomId === room.id) {
        _updateLiveCommentsView(room.comments);
        var $cc = $("#live-comments");
        _liveScrollToBottomIfNear($cc);
        $("#live-scene-area").html(
          '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:#1a1a2e;"><div style="text-align:center;color:#6b7280;"><div style="font-size:48px;margin-bottom:12px;">⚠️</div><div style="font-size:16px;font-weight:600;">直播被中断</div><div style="font-size:12px;margin-top:6px;color:#4b5563;">' +
            escapeHtml(reason) +
            "</div></div></div>",
        );
        $("#live-comment-input")
          .prop("disabled", true)
          .attr("placeholder", "直播已结束");
        $("#live-send-comment-btn").prop("disabled", true);
      }
      if (typeof toastr !== "undefined")
        yqToast("warning", "偷拍被发现，直播被迫中断", "⚠️");
    } else {
      // 攻略度高，不强制下播，但场景性质变化
      room.comments.push({
        author: "系统",
        content: "💜 对方发现了镜头，但没有强烈反抗...",
        type: "system",
        time: Date.now() + 1,
      });
      room.style = "公开"; // 从偷拍变为公开
      saveLiveRoom(room);
      if (typeof toastr !== "undefined")
        yqToast("info", "对方发现了直播，但没有阻止", "💜");
    }
  } catch (e) {
    console.warn("[偷拍发现] 处理失败:", e);
  }
}

/** 动态检查并显示玩家主播榜单按钮 */
function _checkAndShowPlayerLeaderboard(room) {
  if (!room || !room.isPlayerHosted) return;
  // 检查是否有观众首次达到约线下阈值（用于弹幕提示）
  var _vgt = room.viewerGiftTotals || {};
  var _meetThreshold = room.meetThreshold || 100000;
  var _vgtKeys = Object.keys(_vgt);
  for (var _vi = 0; _vi < _vgtKeys.length; _vi++) {
    if (_vgt[_vgtKeys[_vi]].total >= _meetThreshold) {
      // 首次有人达标时弹幕提示（用标记防重复）
      if (!room._leaderboardNotified) {
        room._leaderboardNotified = true;
        saveLiveRoom(room);
        _addDanmaku("👑 有土豪达到约线下条件了！", true, room.id);
        if (typeof toastr !== "undefined")
          yqToast("success", "有观众送礼达到约线下阈值！", "👑");
      }
      return;
    }
  }
}

/** 玩家主播排行榜弹窗 */
function _showPlayerLeaderboard(room) {
  var existing = $("#live-leaderboard-panel");
  if (existing.length > 0) {
    existing.remove();
    return;
  }
  var vgt = room.viewerGiftTotals || {};
  var allViewers = [];
  var keys = Object.keys(vgt);
  for (var i = 0; i < keys.length; i++) {
    if (vgt[keys[i]].total > 0) {
      allViewers.push({
        nick: keys[i],
        total: vgt[keys[i]].total,
        realName: vgt[keys[i]].realName,
        gender: vgt[keys[i]].gender || "male",
      });
    }
  }
  allViewers.sort(function (a, b) {
    return b.total - a.total;
  });
  var meetThreshold = room.meetThreshold || 100000;
  var rankEmojis = ["🥇", "🥈", "🥉"];
  var html =
    '<div id="live-leaderboard-panel" style="position:absolute;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.7);z-index:200;display:flex;align-items:center;justify-content:center;">';
  html +=
    '<div style="background:#1a1333;border:1px solid #4c3d8f;border-radius:12px;padding:16px;width:85%;max-height:70%;overflow-y:auto;">';
  html +=
    '<div style="font-size:14px;font-weight:700;color:#fbbf24;margin-bottom:4px;text-align:center;">👑 打赏排行榜</div>';
  html +=
    '<div style="font-size:10px;color:#9ca3af;text-align:center;margin-bottom:12px;">约线下需累计送礼达到 💰' +
    meetThreshold.toLocaleString() +
    "</div>";
  if (allViewers.length === 0) {
    html +=
      '<div style="text-align:center;padding:20px;color:#6b7280;font-size:12px;">暂无观众送礼</div>';
  }
  for (var qi = 0; qi < allViewers.length; qi++) {
    var q = allViewers[qi];
    var rankIcon = qi < 3 ? rankEmojis[qi] : qi + 1 + ".";
    var genderIcon = q.gender === "female" ? " ♀" : " ♂";
    var canMeetThis = q.total >= meetThreshold;
    var cardBg = canMeetThis ? "#3b2670" : "#2d2654";
    html +=
      '<div style="padding:10px;margin-bottom:8px;background:' +
      cardBg +
      ";border-radius:8px;" +
      (canMeetThis ? "border:1px solid rgba(236,72,153,0.4);" : "") +
      '">';
    html +=
      '<div style="display:flex;justify-content:space-between;align-items:center;">';
    html +=
      '<div style="color:#e2e8f0;font-size:13px;font-weight:600;">' +
      rankIcon +
      " " +
      escapeHtml(q.nick) +
      '<span style="color:#9ca3af;font-size:11px;">' +
      genderIcon +
      "</span></div>";
    html +=
      '<div style="color:#fbbf24;font-size:12px;">💰' +
      q.total.toLocaleString() +
      "</div>";
    html += "</div>";
    html += '<div style="display:flex;gap:6px;margin-top:6px;">';
    html +=
      '<button type="button" class="live-lb-detail-btn yq-btn yq-btn--indigo yq-btn--xs yq-btn--flex-1" data-nick="' +
      escapeHtml(q.nick) +
      '" data-room-id="' +
      escapeHtml(room.id) +
      '">详细</button>';
    if (canMeetThis) {
      html +=
        '<button type="button" class="live-lb-meet-btn yq-btn yq-btn--live-aud yq-btn--xs yq-btn--flex-1" data-nick="' +
        escapeHtml(q.nick) +
        '" data-real="' +
        escapeHtml(q.realName) +
        '" data-gender="' +
        q.gender +
        '" data-room-id="' +
        escapeHtml(room.id) +
        '">约线下</button>';
    } else {
      var _remaining = meetThreshold - q.total;
      html +=
        '<div style="flex:1;padding:4px 8px;background:#4b5563;color:#9ca3af;border-radius:4px;font-size:10px;text-align:center;">还差 💰' +
        _remaining.toLocaleString() +
        "</div>";
    }
    html += "</div></div>";
  }
  html +=
    '<div style="text-align:center;margin-top:8px;"><button type="button" id="live-lb-close" class="yq-btn yq-btn--neutral yq-btn--sm">关闭</button></div>';
  html += "</div></div>";
  $("#live-detail-container").append(html);
  // 绑定事件
  $("#live-lb-close")
    .off("click")
    .on("click", function () {
      $("#live-leaderboard-panel").remove();
    });
  $("#live-leaderboard-panel")
    .off("click.bg")
    .on("click.bg", function (e) {
      if (e.target === this) $(this).remove();
    });
  $(".live-lb-detail-btn")
    .off("click")
    .on("click", function (e) {
      e.stopPropagation();
      var nick = $(this).data("nick");
      var rid = $(this).data("room-id");
      var r = getLiveRoom(rid);
