/** 查看观众详细消息记录 */
function _showViewerDetail(room, nick) {
  var comments = room.comments || [];
  var filtered = [];
  for (var i = 0; i < comments.length; i++) {
    var c = comments[i];
    if (
      c.author === nick ||
      (c.type === "gift" && c.content && c.content.indexOf(nick) !== -1)
    ) {
      filtered.push(c);
    }
  }
  var html =
    '<div id="live-viewer-detail-panel" style="position:absolute;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.7);z-index:210;display:flex;align-items:center;justify-content:center;">';
  html +=
    '<div style="background:#1a1333;border:1px solid #4c3d8f;border-radius:12px;padding:16px;width:85%;max-height:70%;overflow-y:auto;">';
  html +=
    '<div style="font-size:14px;font-weight:700;color:#e2e8f0;margin-bottom:12px;text-align:center;">' +
    escapeHtml(nick) +
    " 的消息记录</div>";
