// 监听系统面板的数据变更通知，刷新当前打开的APP
// 协议 v2：发送方可附带 { version, changedKeys?: string[] }
//   - 未带 changedKeys：兼容旧行为，全量刷新 MVU 缓存
//   - 带 changedKeys：仅在命中手机 UI 关心的 key 前缀时才刷新，减少无效重绘
// 手机 UI 当前感兴趣的是 MVU 快照与 yinqi_phone 子结构（任务/商城等已迁出）
var _YQ_META_INTEREST_PREFIX = [
  "stat_data",
  "yinqi_phone",
  "yinqi_",
  "yinqi_statdata_backup",
  "yinqi_guard_snapshot",
  "chat_avatars",
  "avatar",
  "player_avatar",
  "npc_messages",
  "monitor",
  "image_index",
  "groups",
  "known_friends",
];
function _yqNormalizeMetaChangedKey(k) {
  var s = String(k || "");
  if (s.indexOf("yinqi_phone.") === 0) return s.slice("yinqi_phone.".length);
  return s;
}
function _yqMetaInterested(keys) {
  if (!Array.isArray(keys) || !keys.length) return true; // 未提供视为全量
  for (var i = 0; i < keys.length; i++) {
    var k = _yqNormalizeMetaChangedKey(keys[i]);
    for (var j = 0; j < _YQ_META_INTEREST_PREFIX.length; j++) {
      if (k.indexOf(_YQ_META_INTEREST_PREFIX[j]) === 0) return true;
    }
  }
  return false;
}
// [V5.3 P1 Fix · BUG-10] 显示/隐藏回档遮罩
function _yqShowRollbackOverlay(show, reason) {
  try {
    var id = "yq-rollback-overlay";
    var el = document.getElementById(id);
    if (show) {
      if (!el) {
        el = document.createElement("div");
        el.id = id;
        el.style.cssText = [
          "position:fixed",
          "inset:0",
          "background:rgba(0,0,0,.55)",
          "backdrop-filter:blur(3px)",
          "-webkit-backdrop-filter:blur(3px)",
          "display:flex",
          "align-items:center",
          "justify-content:center",
          "z-index:2147483647",
          "pointer-events:auto",
          "color:#fff",
          "font-family:Microsoft YaHei,sans-serif",
          "font-size:14px",
          "letter-spacing:1px",
          "user-select:none",
        ].join(";");
        el.innerHTML =
          '<div style="background:rgba(10,15,26,.9);border:1px solid rgba(125,211,252,.3);border-radius:12px;padding:18px 26px;text-align:center;box-shadow:0 14px 34px rgba(0,0,0,.42);">' +
          '<div style="font-size:28px;margin-bottom:8px;animation:yqSpin 1s linear infinite;display:inline-block;">⏪</div>' +
          '<div id="yq-rollback-overlay-text">数据回档中...</div>' +
          '<div style="font-size:10px;color:#6b7a96;margin-top:6px;">请稍候，请勿操作</div>' +
          "</div>" +
          "<style>@keyframes yqSpin{from{transform:rotate(0)}to{transform:rotate(360deg)}}</style>";
        document.body.appendChild(el);
      }
      try {
        var _t = document.getElementById("yq-rollback-overlay-text");
        if (_t)
          _t.textContent =
            "数据回档中..." + (reason ? "（" + reason + "）" : "");
      } catch (_tErr) {}
    } else {
      if (el && el.parentNode) el.parentNode.removeChild(el);
    }
  } catch (_ovErr) {}
}

window.addEventListener("message", function (e) {
  if (!e || !e.data) return;
  // 仅信任父页消息，避免其他 frame 伪造事件
  try {
    if (e.source !== window.parent) return;
  } catch (_srcErr) {
    return;
  }
  try {
    if (
      e.origin &&
      e.origin !== "null" &&
      window.location &&
      window.location.origin &&
      e.origin !== window.location.origin
    ) {
      return;
    }
  } catch (_oriErr) {
    return;
  }

  // [V5.3 P1 Fix · BUG-10] 处理 yinqi_rollback_lock 消息
  if (e.data.type === "yinqi_rollback_lock") {
    try {
      _yqShowRollbackOverlay(!!e.data.locked, String(e.data.reason || ""));
    } catch (_lkErr) {}
    return;
  }

  // [V5.3 P1 Fix · BUG-4] 处理 yinqi_rollback_complete 消息：回档完成后重置到主屏
  if (e.data.type === "yinqi_rollback_complete") {
    try {
      // 重置导航状态，避免 UI 停留在已回滚的子页上
      try {
        if (
          typeof navigationStack !== "undefined" &&
          Array.isArray(navigationStack)
        ) {
          navigationStack.length = 0;
        }
      } catch (_nsErr) {}
      try {
        if (typeof currentPanel !== "undefined") {
          window.currentPanel = null;
        }
      } catch (_cpErr) {}
