function _yqStripThinkingTags(text) {
  if (!text) return "";
  var s = String(text);
  // 1. 闭合标签：覆盖所有变体 + 带属性
  s = s.replace(
    /<(think|thinking|thought|reasoning|analysis|reflection|deliberation)\b[^>]*>[\s\S]*?<\/\1\s*>/gi,
    "",
  );
  // 2. 未闭合的开头标签：从 <think...> 一直吃到文末或下一个明确的非 thinking 标签
  //    这种情况发生在模型 token 用完截断时
  s = s.replace(
    /<(think|thinking|thought|reasoning|analysis|reflection|deliberation)\b[^>]*>[\s\S]*$/gi,
    "",
  );
