  if (!name || !Number.isFinite(deltaQty) || deltaQty === 0) return false;
  opts = opts || {};
  var save = opts.save !== false;

  // [V11.8.10·P1-3 fix·2026-05-27] 双源 key 一致化
  //   原 BUG: stat_data 侧直接用原 name 写入,但 _yqBagPath 等其他写入路径用 normalize key
  //          → 含特殊字符(.[]\/)的自定义商品名会产生"幽灵道具"
  //   修复: 双源都用 normalize key 写入,读时 fallback 兼容老存档原 key
  var safeKey = _yqNormalizeBagKey(name);
  var ok = true;

  // 1) stat_data.user.背包
  try {
    var bag = getVar("user.背包");
    if (!bag || typeof bag !== "object") bag = {};
    // 兼容老存档:优先 normalize key,fallback 原 name
    var entry = bag[safeKey] || bag[name];
    var entryKey = bag[safeKey] ? safeKey : bag[name] ? name : safeKey;
    if (entry && typeof entry === "object") {
      var newQty = (Number(entry.数量) || 0) + deltaQty;
      if (newQty <= 0) {
        delete bag[entryKey];
        // 同步清掉另一侧残留(老/新 key 不一致时)
        if (entryKey !== safeKey && bag[safeKey]) delete bag[safeKey];
        if (entryKey !== name && bag[name]) delete bag[name];
        if (deltaQty < 0 && (Number(entry.数量) || 0) + deltaQty < 0)
          ok = false;
      } else {
        // 写入侧统一用 normalize key
        if (entryKey !== safeKey) {
          // 老 key → 迁移到 normalize key
          bag[safeKey] = entry;
          delete bag[entryKey];
        }
        bag[safeKey].数量 = newQty;
      }
    } else if (deltaQty > 0) {
      bag[safeKey] = {
        数量: deltaQty,
        等级: Number(opts.level) || 1,
        说明: String(opts.aiDesc || ""),
      };
    } else {
      // 减量但条目不存在 → 不一致
      ok = false;
    }
    setVar("user.背包", bag);
  } catch (_e1) {
    ok = false;
  }

  // 2) chatMetadata.yinqi_phone.yinqi_inventory
  try {
    var inv = getMeta("yinqi_inventory", {}) || {};
    // 兼容老存档:优先 normalize key,fallback 原 name
    var iEntry = inv[safeKey] || inv[name];
    var iEntryKey = inv[safeKey] ? safeKey : inv[name] ? name : safeKey;
    if (iEntry && typeof iEntry === "object") {
      var iNew = (Number(iEntry.qty) || 0) + deltaQty;
      if (iNew <= 0) {
        delete inv[iEntryKey];
        if (iEntryKey !== safeKey && inv[safeKey]) delete inv[safeKey];
        if (iEntryKey !== name && inv[name]) delete inv[name];
        if (deltaQty < 0 && (Number(iEntry.qty) || 0) + deltaQty < 0)
          ok = false;
      } else {
        // 写入侧统一用 normalize key
        if (iEntryKey !== safeKey) {
          inv[safeKey] = iEntry;
          delete inv[iEntryKey];
        }
        inv[safeKey].qty = iNew;
      }
    } else if (deltaQty > 0) {
      inv[safeKey] = { qty: deltaQty, desc: String(opts.aiDesc || "") };
    } else {
      ok = false;
    }
    setMeta("yinqi_inventory", inv);
    if (save) saveMeta();
  } catch (_e2) {
    ok = false;
  }

  return ok;
}

function setVar(path, value) {
