function _yqSpendSilverPoints(cost, source) {
  try {
    var need = Math.max(0, Number(cost) || 0);
    var cur = getN("银麒系统.账户.银麒点");
    if (cur < need) {
      return {
        ok: false,
        pts: cur,
        need: need,
        source: String(source || "unknown"),
        reason: "insufficient",
      };
    }
    if (need > 0) {
      var _ok = setVar("银麒系统.账户.银麒点", cur - need);
      if (!_ok) {
        return {
          ok: false,
          pts: cur,
          need: need,
          source: String(source || "unknown"),
          reason: "setvar_failed",
        };
      }
    }
    try {
      // 保持守卫快照与账户值一致，避免跨模块读取旧值
      _yqCore.guard.updateSnapshot();
    } catch (_spSnapErr) {}
    return {
      ok: true,
      pts: cur - need,
      need: need,
      source: String(source || "unknown"),
    };
  } catch (_spErr) {
    return {
      ok: false,
      pts: 0,
      need: Math.max(0, Number(cost) || 0),
      source: String(source || "unknown"),
      reason: "error",
    };
  }
}

