var _yqAvatarCache = {};
var _yqAvatarStoreWindow = null;
var _yqAvatarStoreWindowAt = 0;
function _getPhoneImageStoreWindowCached() {
  var now = Date.now();
  if (_yqAvatarStoreWindow && now - _yqAvatarStoreWindowAt < 3000)
    return _yqAvatarStoreWindow;
  _yqAvatarStoreWindow = null;
  _yqAvatarStoreWindowAt = now;
  try {
    var iframes = _pd.querySelectorAll("iframe");
    for (var i = 0; i < iframes.length; i++) {
      try {
        var fw = iframes[i].contentWindow;
        if (fw && fw.phoneImageStore) {
          _yqAvatarStoreWindow = fw;
          break;
        }
      } catch (_ifErr) {}
    }
  } catch (_scanErr) {}
  return _yqAvatarStoreWindow;
}
function _yqGetPlayerGender() {
  // [V8.2+ BUG1] 修正优先级：MVU 是 stat_data 真源；phone iframe 的 yqGetUserGender
  // 依赖 currentPhoneData 同步，在面板刷新早于 phone sync 时会返回过期 male
  // 正确顺序：ctx.chat.variables > Mvu.getMvuData > phone.yqGetUserGender（仅作最后兜底）
  try {
    var ctx = _getCtx();
    if (ctx && ctx.chat && ctx.chat.length > 0) {
      for (var _mi = ctx.chat.length - 1; _mi >= 0; _mi--) {
        var _vars = ctx.chat[_mi].variables;
        var _sd = _vars && (_vars[ctx.chat[_mi].swipe_id || 0] || _vars[0]);
        if (
          _sd &&
          _sd.stat_data &&
          _sd.stat_data.user &&
          _sd.stat_data.user.gender
        ) {
          return String(_sd.stat_data.user.gender);
        }
      }
    }
  } catch (_) {}
  try {
    var mvu = _pw.Mvu;
    if (mvu && typeof mvu.getMvuData === "function") {
      var md = mvu.getMvuData({ type: "message", message_id: -1 });
      if (md && md.stat_data && md.stat_data.user && md.stat_data.user.gender)
        return String(md.stat_data.user.gender);
    }
  } catch (_) {}
  try {
    var fw = _getPhoneImageStoreWindowCached();
    if (fw && typeof fw.yqGetUserGender === "function")
      return fw.yqGetUserGender();
  } catch (_) {}
  return "male";
}

function _getAvatarById(avatars, imgId) {
  if (!imgId) return null;
  var cacheKey = String(imgId);
  var c = _yqAvatarCache[cacheKey];
  if (c && Date.now() - c.at < 1500) return c.data;
  var fw = _getPhoneImageStoreWindowCached();
  var store = fw && fw.phoneImageStore;
  if (store && typeof store.load === "function") {
    var data = store.load(imgId, false);
    if (data) {
      _yqAvatarCache[cacheKey] = { data: data, at: Date.now() };
      return data;
    }
  }
  return null;
}

function getAvatar(name) {
  try {
    var ctx = _getCtx();
    if (!ctx || !ctx.chatMetadata) return null;
    var phone = ctx.chatMetadata.yinqi_phone || {};
    var avatars = phone.chat_avatars || {};

    var isPlayer = false;
    try {
      var playerName = ctx.name1 ? String(ctx.name1) : "";
      if (
        playerName &&
        (name === playerName || name === "{{user}}" || name === "主角")
      )
        isPlayer = true;
    } catch (_) {}
    var _pGender = isPlayer ? _yqGetPlayerGender() : "male";

    // [V8.2+ BUG1] 玩家变性后：先尝试 chat_avatars 性别专属键，再尝试 default_avatars 性别专属键
    // 不能直接走 avatars[name]（那是男性旧图），必须把性别专属的完整 fallback 链走完
    if (isPlayer && _pGender !== "male") {
      var _suffixKeys =
        _pGender === "female"
          ? [name + "_female", "主角_女体"]
          : [name + "_futanari", "主角_双性"];
      // Layer 1: chat_avatars 性别键
      for (var _sk = 0; _sk < _suffixKeys.length; _sk++) {
        var _sData = _getAvatarById(avatars, avatars[_suffixKeys[_sk]]);
        if (_sData) return _sData;
      }
      // Layer 2: default_avatars 性别键（角色卡内置占位）
      var _defRes = _yqGetDefaultAvatar(name, true, _pGender);
      if (_defRes) return _defRes;
      // Layer 3: 继续往下走常规路径（avatars[name] / default_avatars[name]），保证不中断
    }

    var _byName = _getAvatarById(avatars, avatars[name]);
    if (_byName) return _byName;

    // [V8.2+ BUG1] 最后 fallback：chat_avatars 没有时查角色卡内置默认头像
    return _yqGetDefaultAvatar(name, isPlayer, _pGender);
  } catch (e) {}
  return null;
}

function avatarHtml(name, size) {
  size = size || 48;
  var src = getAvatar(name);
  if (src) {
    return (
      '<img src="' +
      src +
      '" style="width:' +
      size +
      "px;height:" +
      size +
      'px;border-radius:50%;object-fit:cover;flex-shrink:0;border:2px solid rgba(139,92,246,0.3);">'
    );
  }
  // 姓氏头像 — 用名字hash选颜色
  var ch = (name || "?").charAt(0);
  var colors = [
    ["#6366f1", "#8b5cf6"],
    ["#ec4899", "#f43f5e"],
    ["#14b8a6", "#06b6d4"],
    ["#f59e0b", "#f97316"],
    ["#10b981", "#34d399"],
    ["#8b5cf6", "#a78bfa"],
  ];
  var hash = 0;
  for (var hi = 0; hi < name.length; hi++)
    hash = (hash + name.charCodeAt(hi)) % colors.length;
  var c = colors[hash];
  return (
    '<div style="width:' +
    size +
    "px;height:" +
    size +
    "px;border-radius:50%;background:linear-gradient(135deg," +
    c[0] +
    "," +
    c[1] +
    ");display:flex;align-items:center;justify-content:center;font-size:" +
    Math.round(size * 0.48) +
    'px;color:#fff;flex-shrink:0;font-weight:700;text-shadow:0 1px 2px rgba(0,0,0,0.3);">' +
    escHtml(ch) +
    "</div>"
  );
}

