.yq-fill{height:100%;border-radius:99px;transition:width .5s}
.yq-btn{padding:8px 18px;border-radius:var(--yq-r-s);font-size:13px;font-weight:700;cursor:pointer;border:1px solid transparent;transition:all .25s;background:transparent}
.yq-btn:hover{transform:translateY(-1px)}
.yq-btn:active{transform:scale(0.97)}
.yq-btn.primary{color:#fff;background:linear-gradient(135deg,var(--yq-cyan),var(--yq-purple));border-color:var(--yq-cyan);font-weight:800;text-shadow:0 1px 2px rgba(0,0,0,0.3)}
.yq-btn.primary:hover{box-shadow:0 0 16px var(--yq-cyan-g);transform:translateY(-1px)}
.yq-btn.danger{color:var(--yq-red);border-color:rgba(255,64,96,.3);background:var(--yq-red-d)}
.yq-btn.danger:hover{box-shadow:0 0 8px var(--yq-red-g)}
.yq-btn.gold{color:var(--yq-gold);border-color:rgba(240,200,96,.3);background:var(--yq-gold-d)}
.yq-btn.gold:hover{box-shadow:0 0 8px rgba(240,200,96,0.3)}
.yq-btn.disabled{opacity:.35;cursor:not-allowed;pointer-events:none}
.yq-badge{display:inline-block;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:700}
.yq-badge.d{background:var(--yq-green-d);color:var(--yq-green);border:1px solid rgba(76,255,136,.2)}
.yq-badge.c{background:var(--yq-cyan-d);color:var(--yq-cyan);border:1px solid rgba(0,240,255,.2)}
.yq-badge.b{background:var(--yq-gold-d);color:var(--yq-gold);border:1px solid rgba(240,200,96,.2)}
.yq-badge.aa{background:var(--yq-rose-d);color:var(--yq-rose);border:1px solid rgba(255,107,157,.2)}
.yq-badge.ss{background:var(--yq-purple-d);color:var(--yq-purple);border:1px solid rgba(139,92,246,.2)}
.yq-badge.xx{background:var(--yq-red-d);color:var(--yq-red);border:1px solid rgba(255,64,96,.2)}
.yq-empty{font-size:14px;color:var(--yq-muted);font-style:italic;padding:16px 0;text-align:center}
.yq-overlay{position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.8);z-index:9999;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(6px)}
.yq-modal{background:var(--yq-bg);border:1px solid var(--yq-cyan);border-radius:var(--yq-r-l);padding:24px;max-width:520px;width:94%;max-height:85vh;overflow-y:auto;box-shadow:0 10px 40px rgba(0,0,0,0.7),0 0 30px var(--yq-cyan-g)}
.yq-modal h3{font-size:18px;color:var(--yq-cyan);margin-bottom:16px;text-shadow:0 0 10px var(--yq-cyan-g)}
.yq-modal textarea{width:100%;background:var(--yq-input);border:1px solid var(--yq-border-g);border-radius:var(--yq-r-s);color:var(--yq-fg);padding:12px;font-size:14px;resize:vertical;min-height:80px;transition:border-color .2s}
.yq-modal textarea:focus{border-color:var(--yq-cyan);box-shadow:0 0 10px var(--yq-cyan-g);outline:none}
.yq-modal .yq-actions{display:flex;gap:12px;justify-content:flex-end;margin-top:16px}
.yq-collapse{cursor:pointer;user-select:none}
.yq-collapse .yq-arrow{display:inline-block;transition:transform .2s;font-size:12px;color:var(--yq-cyan);margin-right:6px}
.yq-collapse.open .yq-arrow{transform:rotate(90deg)}
.yq-collapse-body{max-height:0;overflow:hidden;transition:max-height .3s ease,opacity .3s ease;opacity:0}
.yq-collapse.open .yq-collapse-body{max-height:10000px;opacity:1;overflow:visible}
.yq-select{background:var(--yq-input);border:1px solid var(--yq-border);border-radius:var(--yq-r-s);color:var(--yq-fg);padding:6px 10px;font-size:13px;transition:border-color .2s}
.yq-select:focus{border-color:var(--yq-cyan);box-shadow:0 0 6px var(--yq-cyan-g);outline:none}
.yq-shop-cat-label{display:inline}

/* ============================================================ */
/* [V3.§2.1.6] 据点 UI 美化 - 状态横幅 / 等级 CSS / 动画 / 移动端 */
/* ============================================================ */

/* 视图切换动画：透明度交叉 */
.yq-outpost-page[data-outpost="mybase"] {
 animation: yq-v3-fadein 0.3s ease-out;
}
@keyframes yq-v3-fadein {
 from { opacity: 0.4; transform: translateY(4px); }
 to { opacity: 1; transform: translateY(0); }
}

/* 视图模式按钮过渡 */
.yq-v3-view-mode { transition: all 0.2s ease; cursor: pointer; }
.yq-v3-view-mode:hover { opacity: 0.85; transform: scale(1.02); }

/* 设施卡片 hover 浮起 */
.yq-v3-fac-card { transition: transform 0.15s ease, box-shadow 0.15s ease; }
.yq-v3-fac-card:hover { transform: translateY(-2px); box-shadow: 0 4px 12px rgba(0,240,200,0.2) !important; }

/* 空位卡片 hover 高亮 */
.yq-v3-fac-empty { transition: background 0.2s ease, border-color 0.2s ease; }
.yq-v3-fac-empty:hover { background: rgba(0,240,200,0.05) !important; border-color: var(--yq-cyan) !important; }

/* 成员卡片 hover */
.yq-v3-mem-card { transition: transform 0.15s ease, box-shadow 0.15s ease; }
.yq-v3-mem-card:hover { transform: translateY(-1px); box-shadow: 0 3px 10px rgba(76,255,136,0.15) !important; }

/* 顶部状态横幅 */
.yq-v3-status-banner {
 padding: 8px 12px;
 border-radius: 6px;
 margin: 0 12px 8px 12px;
 font-size: 12px;
 font-weight: 600;
 display: flex;
 align-items: center;
 gap: 8px;
 animation: yq-v3-bannerSlide 0.3s ease-out;
}
@keyframes yq-v3-bannerSlide {
 from { opacity: 0; transform: translateX(-8px); }
 to { opacity: 1; transform: translateX(0); }
}
.yq-v3-status-banner.warn { background: rgba(255,200,80,0.12); border: 1px solid rgba(255,200,80,0.4); color: var(--yq-gold); }
.yq-v3-status-banner.danger { background: rgba(255,80,96,0.15); border: 1px solid rgba(255,80,96,0.45); color: var(--yq-red); animation: yq-v3-bannerSlide 0.3s ease-out, yq-v3-pulseRed 1.5s ease-in-out infinite; }
.yq-v3-status-banner.info { background: rgba(120,180,255,0.1); border: 1px solid rgba(120,180,255,0.4); color: var(--yq-cyan); }
@keyframes yq-v3-pulseRed {
 0%, 100% { box-shadow: 0 0 0 rgba(255,80,96,0); }
 50% { box-shadow: 0 0 12px rgba(255,80,96,0.4); }
}

/* LV1-6 等级演化（容器加 yq-v3-base-lv-N 类，影响顶部 header 的视觉） */
.yq-v3-base-lv-1 .yq-v3-base-header { border-left: 3px solid #6c8c9c; }
.yq-v3-base-lv-2 .yq-v3-base-header { border-left: 3px solid #5cd0d9; box-shadow: 0 0 8px rgba(92,208,217,0.15); }
.yq-v3-base-lv-3 .yq-v3-base-header { border-left: 3px solid #4cffc4; box-shadow: 0 0 12px rgba(76,255,196,0.25); }
.yq-v3-base-lv-4 .yq-v3-base-header { border-left: 3px solid #00f0ff; box-shadow: 0 0 16px rgba(0,240,255,0.35); }
.yq-v3-base-lv-5 .yq-v3-base-header { border-left: 3px solid #f0c860; box-shadow: 0 0 20px rgba(240,200,96,0.4); }
.yq-v3-base-lv-6 .yq-v3-base-header { border-left: 3px solid #c060ff; box-shadow: 0 0 24px rgba(192,96,255,0.5); animation: yq-v3-lv6Glow 3s ease-in-out infinite; }
@keyframes yq-v3-lv6Glow {
 0%, 100% { box-shadow: 0 0 24px rgba(192,96,255,0.5); }
 50% { box-shadow: 0 0 36px rgba(192,96,255,0.7); }
}

/* 升级数字翻牌动画（升级后 header 短暂脉冲） */
.yq-v3-base-header.yq-v3-just-upgraded { animation: yq-v3-upgradePulse 1s ease-out; }
@keyframes yq-v3-upgradePulse {
 0% { transform: scale(1); }
 50% { transform: scale(1.03); box-shadow: 0 0 30px rgba(76,255,196,0.6); }
 100% { transform: scale(1); }
}

/* 商城行 — 容器允许换行，防止手机端挤丢商品名/购买按钮 */
.yq-shop-row1 { display:flex; flex-wrap:wrap; align-items:center; gap:6px; row-gap:4px; justify-content:space-between; }
.yq-shop-name-group { display:flex; align-items:center; gap:6px; flex:1 1 120px; min-width:0; }
.yq-shop-name { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.yq-shop-ops { display:flex; align-items:center; gap:4px; flex-shrink:0; flex-wrap:wrap; justify-content:flex-end; }
.yq-shop-lead { display:flex; align-items:center; justify-content:flex-start; flex:0 0 auto; min-width:7.25rem; max-width:11rem; }
.yq-shop-tail { display:flex; align-items:center; justify-content:flex-end; flex:0 0 auto; min-width:2.85rem; }
.yq-shop-qty-wrap { display:inline-flex; align-items:center; gap:2px; background:rgba(0,0,0,0.3); border:1px solid var(--yq-border); border-radius:4px; flex-shrink:0; }
.yq-shop-total-price { font-size:.7rem; color:#f0c860; min-width:48px; text-align:right; flex-shrink:0; }

/* 移动端响应式：< 480px 单列；商城行名字独占，操作区独占，lead/tail 不硬撑宽度 */
@media (max-width: 480px) {
 .yq-v3-fac-grid { grid-template-columns: 1fr !important; }
 .yq-v3-mem-grid { grid-template-columns: 1fr !important; }
 .yq-v3-status-banner { font-size: 11px; padding: 6px 10px; }
 .yq-shop-name-group { flex: 1 1 100%; }
 .yq-shop-ops { flex: 1 1 100%; justify-content: flex-end; }
 .yq-shop-lead { min-width: 0 !important; max-width: none !important; }
 .yq-shop-tail { min-width: 0 !important; }
 .yq-shop-total-price { min-width: 36px; }
 /* ===== 手机端通用防溢出兜底（不要动既有 HTML，靠 CSS 兜底） ===== */
 #${PANEL_ID} .yq-card { min-width: 0; max-width: 100%; }
 #${PANEL_ID} .yq-body { overflow-x: hidden; }
 /* 所有内联 style 写的 space-between flex 行，手机端自动换行，防按钮被挤出 */
 #${PANEL_ID} [style*="display:flex"][style*="justify-content:space-between"],
 #${PANEL_ID} [style*="display: flex"][style*="justify-content: space-between"] {
 flex-wrap: wrap;
 }
 /* 按钮/链接不得超出父宽，防超长商品名/任务名撑开整行 */
 #${PANEL_ID} button,
 #${PANEL_ID} .yq-btn,
 #${PANEL_ID} select,
 #${PANEL_ID} input[type="text"],
 #${PANEL_ID} input[type="number"] { max-width: 100%; }
 /* 图像/SVG（关系网等）自适应缩放 */
 #${PANEL_ID} img,
 #${PANEL_ID} svg { max-width: 100%; height: auto; }
 /* 长字符串兜底（中文名/道具名）允许折行 */
 #${PANEL_ID} .yq-card,
 #${PANEL_ID} .yq-card * { overflow-wrap: anywhere; }
}

/* [V5.3 § P2-C] 窄视口（≤ 640px，覆盖手机 + 小尺寸桌面窗）压低 modal 高度上限
 让接受任务等信息密度高的弹窗在小屏保持居中时上下都有足够留白（约 100px+ 而非 63px），
 而不是 align-items: flex-start 贴顶（反而更显"靠上"）。修复用户反馈的"太靠上"bug。 */
@media (max-width: 640px) {
 .yq-modal {
 max-height: 88vh;
 padding: 14px;
 }
 .yq-modal h3 { font-size: 15px; margin-bottom: 10px; }
 .yq-modal textarea { min-height: 50px; padding: 8px; font-size: 13px; }
 .yq-modal .yq-actions { margin-top: 10px; }
}
/* [V6.1 FIX BUG-1] 手机端进一步压缩：接受任务弹窗信息密度高，原 70vh 放不下需下拉
 现策略：放宽 max-height 到 92vh，padding 压到 12px，按钮组 sticky 常驻底部 */
@media (max-width: 480px) {
 .yq-modal {
 max-height: 92vh;
 width: 96%;
 padding: 12px;
 }
 .yq-modal h3 { font-size: 14px; margin-bottom: 8px; }
 .yq-modal textarea { min-height: 46px; font-size: 13px; }
 /* 按钮组 sticky 底部：上下滚动时确认/取消按钮始终可见 */
 .yq-modal .yq-actions {
 position: sticky;
 bottom: -12px;
 background: var(--yq-bg);
 margin: 10px -12px -12px;
 padding: 10px 12px;
 border-top: 1px solid var(--yq-border);
 z-index: 2;
 }
 /* 折叠体缩排，信息密度大时节省竖向空间 */
 .yq-modal .yq-collapse-body { padding: 4px 8px; font-size: 11px; }
 .yq-modal .yq-card { padding: 8px 10px; }
}

/* 资源条美化（在原有基础上加点缀光晕） */
.yq-bar { background: rgba(255,255,255,0.05); border-radius: 4px; overflow: hidden; height: 8px; position: relative; }
.yq-bar .yq-fill { height: 100%; transition: width 0.3s ease, background 0.3s ease; border-radius: 4px; }

/* ============================================================ */
/* 底部横条面板                                                   */
/* ============================================================ */
.yq-bottom-bar{position:fixed;bottom:var(--bottomFormBlockSize,54px);left:0;right:0;z-index:500;font-family:"Microsoft YaHei","PingFang SC",sans-serif}

/* --- 折叠态：赛博朋克增强状态栏 --- */
.yq-bar-collapsed{display:flex;align-items:center;justify-content:space-between;padding:10px 18px;background:linear-gradient(135deg,rgba(8,8,18,0.97),rgba(12,8,22,0.97));border-top:2px solid transparent;border-image:linear-gradient(90deg,transparent,var(--yq-cyan,#00f0ff) 20%,var(--yq-mag,#e040fb) 80%,transparent) 1;backdrop-filter:blur(14px);cursor:pointer;transition:all .3s ease;position:relative;overflow:hidden}
.yq-bar-collapsed::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,240,255,0.4) 30%,rgba(224,64,251,0.3) 70%,transparent);animation:yqBarScanline 3s linear infinite}
.yq-bar-collapsed::after{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 30% 50%,rgba(0,240,255,0.03),transparent 60%);pointer-events:none}
.yq-bar-collapsed:hover{background:linear-gradient(135deg,rgba(12,12,24,0.98),rgba(16,12,28,0.98))}
.yq-bar-collapsed:hover::before{animation-duration:1.5s}

.yq-bar-status{display:flex;align-items:center;gap:10px;flex:1;min-width:0;overflow:hidden;flex-wrap:nowrap}

/* [V9.2] 行容器：
   PC 端两行在同一排（row-1 + row-2 用同一 flex 容器水平流动，宽度不够时自动折行），
   手机端（<480px 媒体查询里）才强制 row-2 换到第二行。 */
.yq-bar-row{display:flex;align-items:center;gap:8px;min-width:0;flex-wrap:nowrap;overflow:hidden}
.yq-bar-row-1{flex:0 0 auto;gap:10px}
.yq-bar-row-2{flex:0 1 auto;gap:6px;opacity:.92}

/* 等级徽章 */
.yq-bar-lv-badge{display:inline-flex;align-items:center;justify-content:center;min-width:38px;height:22px;border-radius:4px;font-size:11px;font-weight:900;letter-spacing:.05em;color:#fff;padding:0 6px;text-shadow:0 1px 3px rgba(0,0,0,0.5);position:relative;flex-shrink:0}
.yq-bar-lv-badge.lv-low{background:linear-gradient(135deg,#1a5276,#2471a3);box-shadow:0 0 8px rgba(36,113,163,0.4)}
.yq-bar-lv-badge.lv-mid{background:linear-gradient(135deg,#7d3c98,#a569bd);box-shadow:0 0 8px rgba(165,105,189,0.4)}
.yq-bar-lv-badge.lv-high{background:linear-gradient(135deg,#b7950b,#f1c40f);box-shadow:0 0 10px rgba(241,196,15,0.5);color:#1a1a2e}
.yq-bar-lv-badge.lv-max{background:linear-gradient(135deg,#ff1744,#ff6d00);box-shadow:0 0 12px rgba(255,23,68,0.5);animation:yqBadgePulse 2s ease-in-out infinite}

/* 标题 */
.yq-bar-title{font-size:13px;font-weight:900;letter-spacing:.15em;color:var(--yq-cyan,#00f0ff);text-shadow:0 0 8px rgba(0,240,255,0.3);white-space:nowrap;flex-shrink:0}

/* mini经验进度条 */
.yq-bar-exp{width:56px;height:14px;background:rgba(255,255,255,0.06);border-radius:3px;overflow:hidden;flex-shrink:0;position:relative;border:1px solid rgba(255,255,255,0.08)}
.yq-bar-exp-fill{height:100%;border-radius:2px;background:linear-gradient(90deg,var(--yq-cyan,#00f0ff),var(--yq-mag,#e040fb));transition:width .6s ease;box-shadow:0 0 6px rgba(0,240,255,0.4);position:absolute;top:0;left:0}
.yq-bar-exp-text{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,0.8);z-index:1;letter-spacing:.02em}

/* 状态指标组 */
.yq-bar-info{display:flex;align-items:center;gap:8px;font-size:12px;white-space:nowrap;overflow:hidden;flex-shrink:1;min-width:0}
.yq-bar-stat{display:inline-flex;align-items:center;gap:3px;padding:2px 6px;border-radius:3px;background:rgba(255,255,255,0.04);font-variant-numeric:tabular-nums}
.yq-bar-stat .icon{font-size:11px;flex-shrink:0}
.yq-bar-stat .val{color:var(--yq-fg,#e8e6f0);font-weight:600;font-size:11px}
.yq-bar-stat.danger .val{color:var(--yq-red,#ff4060);font-weight:700}
.yq-bar-stat.danger{background:rgba(255,64,96,0.1);animation:yqStatDanger 1.5s ease-in-out infinite}
.yq-bar-stat.warn .val{color:#ffa726}
.yq-bar-stat.task{border-left:2px solid var(--yq-mag,#e040fb);padding-left:8px}
/* [V9.2] 私密任务徽章：紫粉色边框 + 微弱光晕，与普通任务区分 */
.yq-bar-stat.sct{border-left:2px solid #c084fc;padding-left:8px;background:rgba(192,132,252,0.08)}
.yq-bar-stat.sct .val{color:#c084fc;font-weight:700}
.yq-bar-stat.sct .icon{filter:drop-shadow(0 0 3px rgba(192,132,252,0.5))}

.yq-bar-toggle{background:rgba(0,240,255,0.08);border:1px solid rgba(0,240,255,0.15);border-radius:6px;color:var(--yq-cyan,#00f0ff);padding:4px 12px;font-size:12px;cursor:pointer;transition:all .2s;flex-shrink:0}
.yq-bar-toggle:hover{background:rgba(0,240,255,0.2);box-shadow:0 0 8px rgba(0,240,255,0.3)}

/* --- 展开态 --- */
.yq-bar-expanded{background:var(--yq-bg,#0e0e1a);border-top:2px solid var(--yq-cyan,#00f0ff);box-shadow:0 -8px 32px rgba(0,0,0,0.6),0 0 20px rgba(0,240,255,0.06);max-height:80vh;display:flex;flex-direction:column}
.yq-bar-expanded-header{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--yq-border,rgba(0,240,255,0.08));cursor:pointer;transition:background .2s}
.yq-bar-expanded-header:hover{background:rgba(0,240,255,0.03)}
.yq-bar-expanded-header .yq-bar-title{font-size:18px;letter-spacing:.3em}
.yq-bar-panel-content{overflow-y:auto;flex:1;max-height:calc(80vh - 50px)}
.yq-bar-panel-content #${PANEL_ID}{margin:0;border:none;border-radius:0;box-shadow:none}
.yq-bar-panel-content #${PANEL_ID}::before{display:none}
.yq-bar-panel-content #${PANEL_ID} .yq-hdr{cursor:pointer;transition:background .2s}
.yq-bar-panel-content #${PANEL_ID} .yq-hdr:hover{background:linear-gradient(135deg,rgba(14,14,20,1),rgba(18,14,28,1))}
.yq-bottom-bar.expanded .yq-bar-expanded{animation:yqBarSlideUp .25s ease-out}

/* --- 动画 --- */
@keyframes yqBarSlideUp{from{transform:translateY(40px);opacity:0.6}to{transform:translateY(0);opacity:1}}
@keyframes yqBarSlideDown{from{transform:translateY(-40px);opacity:0.6}to{transform:translateY(0);opacity:1}}
@keyframes yqBarScanline{0%{background-position:-200% 0}100%{background-position:200% 0}}
@keyframes yqBadgePulse{0%,100%{box-shadow:0 0 8px rgba(255,23,68,0.4)}50%{box-shadow:0 0 16px rgba(255,23,68,0.7),0 0 24px rgba(255,109,0,0.3)}}
@keyframes yqStatDanger{0%,100%{opacity:1}50%{opacity:0.7}}

/* [V9.2] 顶部模式：悬浮条停在 #top-settings-holder 下方（JS 设置 top: Npx!important），
   展开态向下滑入，圆角在下方，边框和阴影方向反转 */
.yq-bottom-bar.yq-pos-top{bottom:auto!important}
