/* --- 响应式：PC端（宽屏，动态对齐 #sheld 宽度） --- */
/* [V8.2+ BUG2] 横条宽度改由 JS 动态测量 #sheld 盒模型，
   CSS 只负责保留移动端默认（左右撑满），PC 端由 JS 设置 inline 样式覆盖 */
@media(min-width:768px){
  .yq-bottom-bar{border-radius:12px 12px 0 0;overflow:hidden}
  .yq-bar-collapsed{padding:10px 24px;border-radius:12px 12px 0 0}
