// ======== 银麒赎世_角色卡/当前版本/作品展开/panel/_bottom_bar.js ========
// ==================== 底部横条面板 ====================
// 将系统面板从楼层内嵌改为屏幕底部固定横条
// 收起时显示关键状态摘要，展开时显示完整面板

var _yqBarExpanded = false;
var _yqBarCreated = false;
var BAR_ID = "yinqi-bottom-bar";
var BAR_PANEL_ID = "yinqi-bar-panel-wrap";

// ---- 主题系统 ----
var YQ_THEMES = {
  default: {},
  dark: {
    "--yq-bg": "#050508",
    "--yq-card": "#0a0a12",
    "--yq-input": "#0f0f1a",
    "--yq-surface": "#0a0a12",
    "--yq-cyan": "#64ffda",
    "--yq-cyan-d": "rgba(100,255,218,0.12)",
    "--yq-cyan-g": "rgba(100,255,218,0.35)",
