  },
  sakura: {
    "--yq-bg": "#1a0a14",
    "--yq-card": "#200e1a",
    "--yq-input": "#2a1224",
    "--yq-surface": "#200e1a",
    "--yq-cyan": "#ff6b9d",
    "--yq-cyan-d": "rgba(255,107,157,0.12)",
    "--yq-cyan-g": "rgba(255,107,157,0.35)",
    "--yq-mag": "#c084fc",
    "--yq-mag-d": "rgba(192,132,252,0.12)",
    "--yq-border": "rgba(255,107,157,0.08)",
    "--yq-border-g": "rgba(255,107,157,0.2)",
  },
  blood: {
    "--yq-bg": "#120808",
    "--yq-card": "#1a0a0a",
    "--yq-input": "#220e0e",
    "--yq-surface": "#1a0a0a",
    "--yq-cyan": "#ff1744",
    "--yq-cyan-d": "rgba(255,23,68,0.12)",
    "--yq-cyan-g": "rgba(255,23,68,0.35)",
    "--yq-mag": "#d50000",
    "--yq-mag-d": "rgba(213,0,0,0.12)",
    "--yq-border": "rgba(255,23,68,0.08)",
    "--yq-border-g": "rgba(255,23,68,0.2)",
  },
};

function _yqApplyTheme(name) {
  var vars = YQ_THEMES[name];
  if (!vars) return;
  try {
    var targets = [];
    var el1 = $p("#" + PANEL_ID)[0];
    var el2 = $p("#" + BAR_ID)[0];
    if (el1) targets.push(el1);
    if (el2) targets.push(el2);
    if (!targets.length) return;
    targets.forEach(function (el) {
      if (name === "default") {
        Object.keys(YQ_THEMES.dark).forEach(function (k) {
          el.style.removeProperty(k);
        });
      } else {
        Object.keys(vars).forEach(function (k) {
          el.style.setProperty(k, vars[k]);
        });
      }
    });
    setMeta("yinqi_panel_theme", name);
    saveMeta();
  } catch (_e) {}
}

function _yqGetCurrentTheme() {
  return getMeta("yinqi_panel_theme", "default");
}

// ---- 横条创建 ----
var _YQ_BAR_HEIGHT = 46;
var _yqAlignRaf = null;
var _yqAlignResizeHandler = null;

// [V9.2] 顶部/底部位置切换：默认顶部（避开输入框遮挡 + 美化冲突）
function _yqGetBarPosition() {
  try {
    var p = getMeta("yinqi_bar_position", "top");
    return p === "bottom" ? "bottom" : "top";
  } catch (_e) {
    return "top";
  }
}

function _yqSetChatPadding(add) {
  try {
    var chat = _pd.getElementById("chat");
    if (!chat) return;
    // 先清掉两边的 padding，避免切换位置后留下残留
    chat.style.removeProperty("padding-bottom");
    chat.style.removeProperty("padding-top");
    if (!add) return;
    var pos = _yqGetBarPosition();
    var prop = pos === "top" ? "padding-top" : "padding-bottom";
    chat.style.setProperty(prop, _YQ_BAR_HEIGHT + "px", "important");
  } catch (_e) {}
}

// [V8.2+ BUG2] PC 端动态对齐 #sheld（或 fallback #chat）的左右边缘
// CSS media query 只提供圆角等装饰，宽度/位置由 JS 每次测量 #sheld 的盒模型
// [V9.2] 支持顶部/底部位置切换：
//   - 顶部：紧贴 #top-settings-holder 下边缘（或 top:0 fallback）
//   - 底部：跟踪 #form_sheld 顶边缘（V9.1 输入框遮挡修复）
function _yqAlignBarToChat() {
  try {
    var bar = _pd.getElementById(BAR_ID);
    if (!bar) return;
    var pos = _yqGetBarPosition();
    // 先根据位置设置 top/bottom（二选一，另一个置为 auto）
    if (pos === "top") {
      // 顶部：紧贴 ST 菜单栏下方，不被输入框影响
      try {
        var topSettings = _pd.getElementById("top-settings-holder");
        var topPx = 0;
        if (topSettings) {
          var tRect = topSettings.getBoundingClientRect();
          topPx = Math.max(0, Math.round(tRect.bottom));
        }
        bar.style.setProperty("top", topPx + "px", "important");
        bar.style.setProperty("bottom", "auto", "important");
      } catch (_eTop) {
        bar.style.setProperty("top", "0px", "important");
        bar.style.setProperty("bottom", "auto", "important");
      }
    } else {
      // 底部：V9.1 动态跟踪输入框高度——输入大量文字时 ST 会把输入区顶高，
      // 悬浮条必须同步上移到输入框顶部之上，避免遮挡输入框和发送按钮
      try {
        var formSheld = _pd.getElementById("form_sheld");
        if (formSheld) {
          var fRect = formSheld.getBoundingClientRect();
          var vh = _pw.innerHeight || _pd.documentElement.clientHeight || 0;
          // form_sheld 的顶部 = 悬浮条应在的底部位置，加 2px 缓冲
          var bottomPx = Math.max(0, vh - Math.round(fRect.top) + 2);
          bar.style.setProperty("bottom", bottomPx + "px", "important");
          bar.style.setProperty("top", "auto", "important");
        }
      } catch (_eBottom) {}
    }
    // < 768px 走移动端默认（左右撑满 0/0），不管
    var vw = _pw.innerWidth || _pd.documentElement.clientWidth || 0;
    if (vw < 768) {
      bar.style.removeProperty("left");
      bar.style.removeProperty("right");
      bar.style.removeProperty("width");
      bar.style.removeProperty("max-width");
      bar.style.removeProperty("transform");
      return;
    }
    // 优先对齐 #sheld（聊天区容器），没有就退到 #chat
    var anchor = _pd.getElementById("sheld") || _pd.getElementById("chat");
    if (!anchor) return;
    var rect = anchor.getBoundingClientRect();
    if (!rect || rect.width <= 0) return;
    bar.style.setProperty("left", Math.round(rect.left) + "px", "important");
    bar.style.setProperty("right", "auto", "important");
    bar.style.setProperty("width", Math.round(rect.width) + "px", "important");
    bar.style.setProperty("max-width", "none", "important");
    bar.style.setProperty("transform", "none", "important");
  } catch (_e) {}
}

function _yqScheduleAlignBar() {
  try {
    if (_yqAlignRaf) {
      _pw.cancelAnimationFrame(_yqAlignRaf);
    }
    _yqAlignRaf = _pw.requestAnimationFrame(function () {
      _yqAlignRaf = null;
      _yqAlignBarToChat();
    });
  } catch (_e) {
    _yqAlignBarToChat();
  }
}

function _yqInstallAlignBarWatch() {
  if (_yqAlignResizeHandler) return;
  _yqAlignResizeHandler = function () {
    _yqScheduleAlignBar();
  };
  try {
    _pw.addEventListener("resize", _yqAlignResizeHandler, { passive: true });
  } catch (_e) {}
  // MutationObserver 监听 #sheld/#chat 布局变化（ST 主题切换、抽屉开关）
  try {
    var anchor = _pd.getElementById("sheld") || _pd.getElementById("chat");
    if (anchor && _pw.MutationObserver) {
      var mo = new _pw.MutationObserver(function () {
        _yqScheduleAlignBar();
      });
      mo.observe(anchor, {
        attributes: true,
        attributeFilter: ["style", "class"],
      });
      // 存起来便于销毁
      _yqAlignResizeHandler._mo = mo;
    }
  } catch (_e2) {}
  // [V9.1 FIX] 监听 #form_sheld 高度变化（输入框增高时触发）
  try {
    var formSheld = _pd.getElementById("form_sheld");
    if (formSheld && _pw.ResizeObserver) {
      var ro = new _pw.ResizeObserver(function () {
        _yqScheduleAlignBar();
      });
      ro.observe(formSheld);
      _yqAlignResizeHandler._ro = ro;
    }
    // 兜底：监听 textarea input 事件（ResizeObserver 不可用时）
    var ta = _pd.getElementById("send_textarea");
    if (ta) {
      _yqAlignResizeHandler._taHandler = function () {
        _yqScheduleAlignBar();
      };
      ta.addEventListener("input", _yqAlignResizeHandler._taHandler);
    }
  } catch (_e3) {}
  // [V9.2] 监听 #top-settings-holder 高度变化（抽屉展开/折叠、主题切换、菜单栏响应式）
  // 顶部模式下这是关键——ST 抽屉展开时会把 top-settings-holder 顶高，悬浮条要跟着下移
  try {
    var topSettings = _pd.getElementById("top-settings-holder");
    if (topSettings && _pw.ResizeObserver) {
      var roTop = new _pw.ResizeObserver(function () {
        _yqScheduleAlignBar();
      });
      roTop.observe(topSettings);
      _yqAlignResizeHandler._roTop = roTop;
    }
  } catch (_e4) {}
}

function _yqUninstallAlignBarWatch() {
  if (!_yqAlignResizeHandler) return;
  try {
    _pw.removeEventListener("resize", _yqAlignResizeHandler);
  } catch (_e) {}
  try {
    if (_yqAlignResizeHandler._mo) _yqAlignResizeHandler._mo.disconnect();
  } catch (_e2) {}
  try {
    if (_yqAlignResizeHandler._ro) _yqAlignResizeHandler._ro.disconnect();
  } catch (_e3) {}
  try {
    if (_yqAlignResizeHandler._roTop) _yqAlignResizeHandler._roTop.disconnect();
  } catch (_e3b) {}
  try {
    if (_yqAlignResizeHandler._taHandler) {
      var ta = _pd.getElementById("send_textarea");
      if (ta) ta.removeEventListener("input", _yqAlignResizeHandler._taHandler);
    }
  } catch (_e4) {}
  _yqAlignResizeHandler = null;
}

// [V9.2] 切换悬浮条顶部/底部位置，立即生效并持久化
function _yqSetBarPosition(pos) {
  try {
    var norm = pos === "bottom" ? "bottom" : "top";
    setMeta("yinqi_bar_position", norm);
    saveMeta();
    // 切换时把展开态收起，避免动画从错误方向滑入
    if (_yqBarExpanded) _yqToggleBar(false);
    // 更新 bar 的 class（用于 CSS 切换圆角方向和动画方向）
    var bar = _pd.getElementById(BAR_ID);
    if (bar) {
      bar.classList.remove("yq-pos-top", "yq-pos-bottom");
      bar.classList.add("yq-pos-" + norm);
      // 清掉旧位置的 inline 样式
      bar.style.removeProperty("top");
      bar.style.removeProperty("bottom");
    }
    // 重置 chat padding 到新位置
    _yqSetChatPadding(true);
    // 立即重算位置
    _yqScheduleAlignBar();
  } catch (_e) {}
}

function createBottomBar() {
  if (_yqBarCreated) return;
  if ($p("#" + BAR_ID).length) {
    _yqBarCreated = true;
    _yqSetChatPadding(true);
    _yqInstallAlignBarWatch();
    _yqScheduleAlignBar();
    return;
  }

  if (!$p("#yinqi-panel-css").length) {
    $p(_pd.head).append(PANEL_CSS);
  }

  var barHtml =
    '<div id="' +
    BAR_ID +
    '" class="yq-bottom-bar yq-pos-' +
    _yqGetBarPosition() +
    '">' +
    '<div class="yq-bar-collapsed" id="yq-bar-collapsed">' +
    '<div class="yq-bar-status" id="yq-bar-status">' +
    '<span class="yq-bar-title">银麒系统</span>' +
    '<span class="yq-bar-info" id="yq-bar-info">加载中…</span>' +
    "</div>" +
    '<button class="yq-bar-toggle" id="yq-bar-toggle-btn" title="展开面板">▲</button>' +
    "</div>" +
    '<div class="yq-bar-expanded" id="yq-bar-expanded" style="display:none">' +
    '<div class="yq-bar-expanded-header" id="yq-bar-expanded-header">' +
    '<span class="yq-bar-title">银 麒 系 统</span>' +
    '<span class="yq-bar-pending" id="yq-bar-pending" style="display:none;margin-left:auto;margin-right:10px;font-size:11px;color:var(--yq-mag,#e040fb);cursor:help" title="点击预览将在发送时追加到你输入末尾的面板操作（只读，不能手动清空；取消操作请走对应业务撤销，如商城撤回购买）"></span>' +
    '<button class="yq-bar-toggle" id="yq-bar-collapse-btn" title="收起面板">▼</button>' +
    "</div>" +
    '<div class="yq-bar-panel-content" id="' +
    BAR_PANEL_ID +
    '"></div>' +
    "</div>" +
    "</div>";

  $p("body").append(barHtml);
  _yqSetChatPadding(true);

  $p(_pd).on("click.yq-bar", "#yq-bar-toggle-btn", function () {
    _yqToggleBar(true);
  });
  $p(_pd).on("click.yq-bar", "#yq-bar-collapse-btn", function () {
    _yqToggleBar(false);
  });
  $p(_pd).on("click.yq-bar", ".yq-bar-expanded-header", function (e) {
    if (!$p(e.target).closest("#yq-bar-collapse-btn").length) {
      _yqToggleBar(false);
    }
  });
  // [V8.2+ pending优化] 点击 pending 指示器：阻止折叠 + 只读预览（不再提供清空选项）
  $p(_pd).on("click.yq-bar", "#yq-bar-pending", function (e) {
    e.stopPropagation();
    _yqShowPendingPreview();
  });
  $p(_pd).on("click.yq-bar", "#" + PANEL_ID + " .yq-hdr", function (e) {
    if (!$p(e.target).closest("button, a, .yq-btn, select, input").length) {
      _yqToggleBar(false);
    }
  });
  $p(_pd).on("click.yq-bar", "#yq-bar-collapsed", function (e) {
    if (!$p(e.target).closest("#yq-bar-toggle-btn").length) {
      _yqToggleBar(true);
    }
  });

  _yqBarCreated = true;
  _yqInstallAlignBarWatch();
  _yqScheduleAlignBar();
  _yqDbg("[横条] 底部横条已创建");
}

function _yqToggleBar(expand) {
  _yqBarExpanded = expand;
  var $bar = $p("#" + BAR_ID);
  if (!$bar.length) return;

  var $collapsed = $bar.find("#yq-bar-collapsed");
  var $expanded = $bar.find("#yq-bar-expanded");

  if (expand) {
    $collapsed.hide();
    $expanded.show();
    $bar.addClass("expanded");
    // 如果面板内容为空，注入面板
    var $panelWrap = $bar.find("#" + BAR_PANEL_ID);
    if (!$panelWrap.find("#" + PANEL_ID).length) {
      _yqMountPanelInBar();
    }
  } else {
    $expanded.hide();
    $collapsed.show();
    $bar.removeClass("expanded");
  }
  // [V8.2+ BUG2] 每次展开/折叠都重新对齐（ST 可能在这期间改变 sheld 布局）
  _yqScheduleAlignBar();
  // [V8.2+ pending优化] 切换时刷新指示器（刚展开时也要即时显示）
  try {
    _yqUpdatePendingIndicator();
  } catch (_) {}
}

function _yqMountPanelInBar() {
  var $panelWrap = $p("#" + BAR_PANEL_ID);
  if (!$panelWrap.length) return;
  // 移除旧面板（楼层内嵌的或横条内的）
  $p("#" + PANEL_ID).remove();
  // 注入CSS（如果还没有）
  if (!$p("#yinqi-panel-css").length) {
    $p(_pd.head).append(PANEL_CSS);
  }
  // 生成并挂载面板
  // [V9.6 补丁3.3·2026-05-10] try/catch 包裹 buildPanel，防止 ReferenceError 炸挂载
