    // 日期简写：去掉年份，只留"N月N日"，节省宽度
    //   "2026年9月17日" → "9月17日"
    //   "2026-09-17"    → "9月17日"
    //   其他格式原样
    var dateStr = dateRaw;
    try {
      var mCn = dateRaw.match(/(\d{1,2})\s*月\s*(\d{1,2})\s*日/);
      if (mCn) {
        dateStr = mCn[1] + "月" + mCn[2] + "日";
      } else {
        var mIso = dateRaw.match(/\d{4}[-/](\d{1,2})[-/](\d{1,2})/);
        if (mIso) dateStr = Number(mIso[1]) + "月" + Number(mIso[2]) + "日";
      }
    } catch (_eD) {}

    // 地点截短：PC 端 10 字、手机端 6 字；超过阈值保留最后一段
    // [V9.4.1] 智能截断：按 ·/__ 分段保留最细粒度的尾段，前缀用 … 省略
    //   "滨江市·滨江大学·松园6号楼406宿舍" → "…松园6号楼406宿舍" （保留关键信息）
    //   "男生宿舍406室" → 不截（原样）
    //   单段长地点 → 降级为前缀截断
    var vwNow = _pw.innerWidth || 1024;
    var locMaxLen = vwNow < 480 ? 6 : 10;
    var locShort = locStr;
    if (locStr.length > locMaxLen) {
      // 先尝试按分隔符分段，保留最后一段
      var _segs = locStr.split(/[·_\s]+/).filter(function (s) {
        return s;
      });
      if (_segs.length >= 2) {
        var _last = _segs[_segs.length - 1];
        if (_last && _last.length <= locMaxLen) {
          // 尾段足够短：显示 "…尾段"
          locShort = "…" + _last;
        } else if (_last && _last.length > locMaxLen) {
          // 尾段本身过长：取尾段的前 maxLen 字
          locShort = "…" + _last.slice(0, locMaxLen);
        } else {
          // 尾段为空（理论不会走到）：降级前缀截断
          locShort = locStr.slice(0, locMaxLen) + "…";
