// ==================== [V3 网友渗透] 任务系统对接工具 ====================
// 直接读 chatMetadata.yinqi_phone：手机 UI 与系统面板都跑在独立 iframe（手册 §8/§13.1），
// 跨 iframe 函数不可见，但 ST 提供共享的 getContext() —— 主页 / 子 iframe 均能访问同一 chatMetadata。
function _v3GetCtx() {
  try {
    var st = _pw.SillyTavern || window.SillyTavern;
    if (!st || typeof st.getContext !== "function") return null;
    return st.getContext();
  } catch (_e) {
    return null;
  }
}
function _v3ReadPhoneMeta() {
  try {
    var ctx = _v3GetCtx();
    if (!ctx || !ctx.chatMetadata) return {};
    return ctx.chatMetadata.yinqi_phone || {};
  } catch (_e) {
    return {};
  }
}
// 拉取已渗透网友列表（标星永远在前 → 近 14 天活跃 Top 8 → 按 archetype 分组）
// 返回 [{canon, archetype, starred, lastInteractionAt, ageGroup, occupationHint}]
function _v3GetUnlockedNetExecutors() {
  try {
    var phoneMeta = _v3ReadPhoneMeta();
    var meta = phoneMeta.yinqi_friend_meta || {};
    var starred = Array.isArray(phoneMeta.yinqi_friend_starred)
      ? phoneMeta.yinqi_friend_starred
      : [];
    var starredSet = {};
    for (var _ssi = 0; _ssi < starred.length; _ssi++)
      starredSet[starred[_ssi]] = true;
    var all = [];
    for (var k in meta) {
      if (!meta.hasOwnProperty(k)) continue;
      var row = meta[k];
      if (!row || row.npcKind !== "stranger_male") continue;
      if (!row.unlockedAsExecutor) continue;
      all.push({
        canon: k,
        archetype: (row.profile || {}).archetype || "其他",
        ageGroup: (row.profile || {}).ageGroup || "",
        occupationHint: (row.profile || {}).occupationHint || "",
        starred: !!starredSet[k],
        lastInteractionAt: Number(row.lastInteractionAt || 0),
      });
    }
    var starredArr = [];
    var unstarred = [];
    for (var _ai = 0; _ai < all.length; _ai++) {
      if (all[_ai].starred) starredArr.push(all[_ai]);
      else unstarred.push(all[_ai]);
    }
    // 标星按互动时间倒序
    starredArr.sort(function (a, b) {
      return b.lastInteractionAt - a.lastInteractionAt;
    });
    // 非标星：按互动时间倒序，截 Top 8
    unstarred.sort(function (a, b) {
      return b.lastInteractionAt - a.lastInteractionAt;
    });
    var topN = 8;
    unstarred = unstarred.slice(0, topN);
    return starredArr.concat(unstarred);
  } catch (_e) {
    return [];
  }
}

// 给 select 渲染 optgroup（按 archetype 二级分组）
function _v3BuildNetExecutorOptionsHtml() {
  var list = _v3GetUnlockedNetExecutors();
  if (!list || !list.length) return "";
  var groups = {};

  for (var i = 0; i < list.length; i++) {
    var arch = list[i].archetype || "其他";
    if (!groups[arch]) groups[arch] = [];
    groups[arch].push(list[i]);
  }
  var order = ["温柔型", "偷窥型", "权力型", "暴力型", "SM型", "其他"];
  var html = "";
  for (var oi = 0; oi < order.length; oi++) {
    var arch2 = order[oi];
    if (!groups[arch2] || !groups[arch2].length) continue;
    html += '<optgroup label="🔓 ' + arch2 + '">';
    for (var vi = 0; vi < groups[arch2].length; vi++) {
      var v = groups[arch2][vi];
      var prefix = v.starred ? "⭐ " : "";
      var brief = v.ageGroup ? "·" + v.ageGroup : "";
      html +=
        '<option value="' +
        escHtml(v.canon) +
        '">' +
        prefix +
        escHtml(v.canon) +
        brief +
        " ×1.3</option>";
    }
    html += "</optgroup>";
  }
  return html;
}

