// ==================== 暗派任务（私密任务）MVP ====================
function _sctGetTasks() {
  var list = getMeta("yinqi_secret_tasks", []);
  return Array.isArray(list) ? list : [];
}

function _sctSaveTasks(list) {
  setMeta("yinqi_secret_tasks", Array.isArray(list) ? list : []);
  var stats = getMeta("yinqi_secret_task_stats", null) || {};
  stats.totalCreated = Array.isArray(list) ? list.length : 0;
  setMeta("yinqi_secret_task_stats", stats);
  saveMeta();
}

function _sctCloneJson(v, fallback) {
  try {
    if (v === undefined) return fallback;
    return JSON.parse(JSON.stringify(v));
  } catch (_e) {
    return fallback;
  }
}

function _sctSeedRawId(seed) {
  return String(
    (seed && (seed.seedId || seed.id || seed.customId || seed.plotTaskId)) ||
      "",
  );
}

function _sctHashText(text) {
  var s = String(text || "");
  var h = 0;
  for (var i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  return Math.abs(h).toString(36);
}

function _sctSeedId(seed, source, idx) {
  return _sctSeedRawId(seed) || String((source || "seed") + "_" + (idx || 0));
}

function _sctSeedKey(seed, source, idx) {
  var chainId = seed && seed.chainId ? String(seed.chainId) : "";
