function _sctApplyExperienceReward(amount) {
  amount = Math.max(0, Math.floor(Number(amount) || 0));
  if (amount <= 0) return { ok: true, added: 0, upgraded: false };
  var lvThresholds = { 1: 30, 2: 150, 3: 800, 4: 5000, 5: 50000 };
  var curExp = getN("银麒系统.账户.当前经验");
  var curLv = getN("银麒系统.账户.系统等级");
  var remainExp = curExp + amount;
  var upgraded = false;
  while (curLv < 6 && remainExp >= (lvThresholds[curLv] || 99999)) {
    remainExp -= lvThresholds[curLv];
    curLv++;
    upgraded = true;
  }
  if (upgraded) {
    var lvOk = setVar("银麒系统.账户.系统等级", curLv);
    var expOk = setVar("银麒系统.账户.当前经验", remainExp);
    var nextOk = setVar(
      "银麒系统.账户.下一级所需",
      lvThresholds[curLv] || 99999,
    );
    if (!lvOk || !expOk || !nextOk)
      return { ok: false, added: amount, upgraded: false };
    try {
      _yqToast(
        "success",
        "🎉 私密任务经验到账，系统等级提升至 LV" + curLv,
        "",
        { timeOut: 5000 },
      );
    } catch (_) {}
    return {
      ok: true,
      added: amount,
      upgraded: true,
      lv: curLv,
      exp: remainExp,
    };
  }
  if (!setVar("银麒系统.账户.当前经验", remainExp))
    return { ok: false, added: amount, upgraded: false };
  return {
    ok: true,
    added: amount,
    upgraded: false,
    lv: curLv,
    exp: remainExp,
  };
}

