    '<input class="yq-select yq-bounty-field" data-field="action" style="width:100%;margin-top:2px" placeholder="例：为指定男性提供口交服务直到射精"></div>';
  html +=
    '<div style="margin-bottom:6px"><span style="font-size:.72rem;color:var(--yq-cyan)">穿着（可选）</span>';
  html +=
    '<input class="yq-select yq-bounty-field" data-field="clothing" style="width:100%;margin-top:2px" placeholder="不填则由AI根据行为内容自动生成"></div>';
