  html +=
    '<div style="margin-bottom:6px"><span style="font-size:.72rem;color:var(--yq-cyan)">对象（可选）</span>';
  html +=
    '<input class="yq-select yq-bounty-field" data-field="target" style="width:100%;margin-top:2px" placeholder="例：陌生男性/指定NPC，不填则默认随机NPC"></div>';
  html +=
    '<div style="margin-bottom:6px"><span style="font-size:.72rem;color:var(--yq-cyan)">补充说明（可选）</span>';
