    '<input class="yq-select yq-bounty-field" data-field="extra" style="width:100%;margin-top:2px" placeholder="额外要求或限制条件"></div>';
  html += '<div style="text-align:center;margin-top:10px">';
  html +=
    '<button class="yq-btn primary" id="yq-bounty-eval" style="padding:8px 20px">🔮 生成任务</button>';
  // [V7.1] 自定义任务暗派按钮
  html +=
    ' <button class="yq-btn" id="yq-bounty-eval-secret" style="padding:8px 20px;color:#b794f4;border-color:rgba(183,148,244,0.3);margin-left:8px' +
    (_sctHasActiveTask() ? ";opacity:.45;cursor:not-allowed" : "") +
    '"' +
    (_sctHasActiveTask() ? ' disabled title="已有私密任务进行中"' : "") +
