// ======== 银麒赎世_角色卡/当前版本/作品展开/panel/_build_panel_pages.js ========
// ==================== [V9.7·TG启发·P0] 商城道具描述分离 ====================
// 玩家在商城/背包看到的是"感受式/效果型"前半段；
// AI 在 EJS `[EJS]道具信息.xyaml` 的 _itemDb 看到完整版；
// 面板 desc 以 `|AI|` 分隔符作为玩家/AI 分界线，未带分隔符的 desc 直接整条给玩家。
//
// 规则：
//   `"玩家看到的效果描述。|AI| AI 演绎提示：..."` → 玩家端只渲染 `|AI|` 之前
//   `"纯玩家可见文案"` → 整条渲染
//   `"|AI| 纯 AI 指导"` → 玩家端空文案（少见，极特殊道具）
function _getPlayerVisibleDesc(rawDesc) {
  if (!rawDesc) return "";
  var s = String(rawDesc);
  var idx = s.indexOf("|AI|");
  if (idx < 0) return s;
  return s.slice(0, idx).trim();
}

// ==================== [V10] 装备概览 UI ====================
// 渲染角色的 6 属性槽概览（武器/防具/特殊×3/能力×5/技能×3/宠物×1）
// [V10.1] 判断角色是否可被玩家通过面板装备
// 规则：
//   - user（林凡）：始终可操作
//   - 林知意：始终可操作（女主）
//   - 女性角色：在场 + 好感度≥50 → 可操作
//   - 男性角色：不可通过面板操作（完全由 AI 演绎）
function _canPlayerEquipChar(charName) {
  try {
    if (!charName) return false;
    if (charName === "user" || charName === getUserName()) return true;
    if (charName === "林知意") return true;
    // 必须在场
    var scene = getVar("当前场景角色") || {};
    if (!scene[charName]) return false;
    // 女性角色 + 好感度≥50
    var femChars = getVar("女性角色") || {};
    if (femChars[charName]) {
      var aff = Number(femChars[charName].好感度) || 0;
      return aff >= 50;
    }
    // 男性角色：完全交给 AI 演绎，不通过面板操作
    return false;
  } catch (_) {
    return false;
  }
}

function _buildEquipOverview(charName, charPath) {
  try {
    var weapon = getVar(charPath + "._weapon") || null;
    var armor = getVar(charPath + "._armor") || null;
    var special = getVar(charPath + "._special") || [];
    var abilities = getVar(charPath + "._abilities") || [];
    var skills = getVar(charPath + "._skills") || [];
    var pet = getVar(charPath + "._pet") || null;
    if (!Array.isArray(special)) special = [];
    if (!Array.isArray(abilities)) abilities = [];
    if (!Array.isArray(skills)) skills = [];

    // 从商城 ITEMS 或道具字典查名字
    function _itemName(key) {
      if (!key) return null;
      // 尝试从 getShopItemsByCatAndLevel 查找（遍历所有分类和等级）
      var cats = ["sys", "wpn", "arm", "spc", "abl", "etc", "pet"];
      for (var ci = 0; ci < cats.length; ci++) {
        for (var li = 1; li <= 6; li++) {
          var items = getShopItemsByCatAndLevel(cats[ci], li);
          for (var ii = 0; ii < items.length; ii++) {
            if (items[ii].name === key) return items[ii];
          }
        }
      }
      return { name: key };
    }

    var isUser = charName === "user" || charName === getUserName();
    // [V10.1] 玩家可操作：user + 林知意 + 在场亲密女性（好感度≥50）
    var canEquip = _canPlayerEquipChar(charName);
    // [V10.10·2026-05-18] 即便 canEquip=false，只要持有 _portal 或背包有道具，
    //   也允许"打开背包"入口（用于改 / 卸下贞操环、查看赠予的道具）
    var _hasPortalForBag = false;
    var _bagHasItems = false;
    try {
      var _pBag = getVar(charPath + "._portal");
      if (_pBag && typeof _pBag === "object" && _pBag.target)
        _hasPortalForBag = true;
    } catch (_eHasPB) {}
    try {
      var _bagBC = getVar(charPath + ".背包") || {};
      var _bagBCKeys = Object.keys(_bagBC).filter(function (k) {
        return _bagBC[k] && (_bagBC[k].数量 || 0) > 0;
      });
      if (_bagBCKeys.length > 0) _bagHasItems = true;
    } catch (_eHasBag) {}
    var _showBagEntry = canEquip || _hasPortalForBag || _bagHasItems;
    var html = "";
    html +=
      '<div class="yq-card" style="padding:10px 14px;margin-top:8px;border-left:3px solid var(--yq-purple)">';
    html +=
      '<div style="font-size:12px;font-weight:800;color:var(--yq-purple);margin-bottom:6px;display:flex;justify-content:space-between;align-items:center">';
    html += "<span>🎒 装备槽</span>";
    // [V10.1+V10.10] 非 user 且（可操作 || 持有_portal || 背包有道具）显示"查看背包"按钮
    if (!isUser && _showBagEntry) {
      var _recvBag = getVar(charPath + ".背包") || {};
      var _bagCount = Object.keys(_recvBag).filter(function (k) {
        return _recvBag[k] && (_recvBag[k].数量 || 0) > 0;
      }).length;
      html +=
        '<button class="yq-btn yq-v10-char-bag" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" style="padding:2px 8px;font-size:9px;color:var(--yq-cyan);border-color:rgba(0,240,255,0.2)">🎒 打开背包(' +
        _bagCount +
        ")</button>";
    }
    html += "</div>";
    html += '<div style="font-size:11px;line-height:1.8">';

    // 武器
    var wpnName = weapon ? (typeof weapon === "string" ? weapon : "") : "";
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between">';
    html +=
      '<span>⚔ 武器: <span style="color:' +
      (wpnName ? "var(--yq-gold)" : "var(--yq-muted)") +
      '">' +
      escHtml(wpnName || "无") +
      "</span></span>";
    if (wpnName && canEquip)
      html +=
        '<button class="yq-btn yq-v10-unequip" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" data-slot="weapon" data-item="' +
        escHtml(wpnName) +
        '" style="padding:1px 6px;font-size:9px;color:var(--yq-red);border-color:rgba(255,64,96,0.2)">卸下</button>';
    html += "</div>";

    // 防具
    var armName = armor ? (typeof armor === "string" ? armor : "") : "";
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between">';
    html +=
      '<span>🛡 防具: <span style="color:' +
      (armName ? "var(--yq-green)" : "var(--yq-muted)") +
      '">' +
      escHtml(armName || "无") +
      "</span></span>";
    if (armName && canEquip)
      html +=
        '<button class="yq-btn yq-v10-unequip" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" data-slot="armor" data-item="' +
        escHtml(armName) +
        '" style="padding:1px 6px;font-size:9px;color:var(--yq-red);border-color:rgba(255,64,96,0.2)">卸下</button>';
    html += "</div>";

    // 特殊（最多3）
    // [V10.10·2026-05-18] 银麒次元贞操环装备状态从 chatMetadata.yinqi_portal_settings 迁到 stat_data.{prefix}._portal
    //   显示：作为虚拟特殊装备项加入"特殊"栏，不占 _special 真实槽位
    //   收回/修改：通过对方背包内的"已装备"卡片（_showCharBagModal 顶部）操作
    //              或通过主角背包"🎁 已赠予"tab 的修改/收回按钮
    var specNames = special
      .map(function (s) {
        return typeof s === "string" ? s : "";
      })
      .filter(Boolean);
    var _portalEntryEO = null;
    try {
      // [V10.10 HOTFIX·2026-05-18] 数据源单一化：仅读 stat_data._portal
      //   原 fallback 读 chatMetadata.yinqi_portal_settings 是 BUG —
      //   玩家通过面板把 _portal 设为 null 后，老 settings 还在 → 又把"已卸下"
      //   状态显示成"已装备"，导致用户报告"卸下后装备栏仍显示有贞操环"。
      //   迁移函数 _migratePortalSettings 在加载时把数据迁到 _portal，
      //   迁移后老 settings 由迁移函数清空，这里不再读 fallback。
      var _pData = getVar(charPath + "._portal");
      if (_pData && typeof _pData === "object" && _pData.target) {
        _portalEntryEO = _pData;
      }
    } catch (_eEOPortal) {}
    var _hasPortal = _portalEntryEO && _portalEntryEO.target;
    if (_hasPortal) {
      specNames.push(
        "🔮银麒次元贞操环(传送→" + (_portalEntryEO.target || "默认") + ")",
      );
    }
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between">';
    html +=
      "<span>✨ 特殊(" +
      specNames.length +
      '/3): <span style="color:' +
      (specNames.length > 0 ? "var(--yq-rose)" : "var(--yq-muted)") +
      '">' +
      (specNames.length > 0 ? escHtml(specNames.join(" / ")) : "无") +
      "</span></span>";
    if (specNames.length > 0 && (canEquip || _hasPortal))
      html +=
        '<button class="yq-btn yq-v10-manage" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" data-slot="special" style="padding:1px 6px;font-size:9px;color:var(--yq-rose);border-color:rgba(244,63,94,0.2)">管理</button>';
    html += "</div>";

    // 能力（最多5）
    var ablNames = abilities
      .map(function (s) {
        return typeof s === "string" ? s : "";
      })
      .filter(Boolean);
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between">';
    html +=
      "<span>⚡ 能力(" +
      ablNames.length +
      '/5): <span style="color:' +
      (ablNames.length > 0 ? "var(--yq-cyan)" : "var(--yq-muted)") +
      '">' +
      (ablNames.length > 0 ? escHtml(ablNames.join(" / ")) : "无") +
      "</span></span>";
    if (ablNames.length > 0 && canEquip)
      html +=
        '<button class="yq-btn yq-v10-manage" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" data-slot="abilities" style="padding:1px 6px;font-size:9px;color:var(--yq-cyan);border-color:rgba(96,165,250,0.2)">管理</button>';
    html += "</div>";

    // 技能（最多3）— 复用已有 _skills
    // [V10.4 BugB·2026-05-16] 走 _yqGetSkillLabel 转换中文名（与 user/林知意 V2 技能槽 UI 对齐）
    //   原 bug：直接 join 数组显示英文 ID（eagle_aim_test 等），用户看不懂
    //   修复：每项走 lookup 函数 — 内置 V2_SKILL_LABEL → customs.name → fallback skillId
    var sklNames = skills
      .map(function (s) {
        if (typeof s !== "string") return "";
        return typeof _yqGetSkillLabel === "function" ? _yqGetSkillLabel(s) : s;
      })
      .filter(Boolean);
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between">';
    html +=
      "<span>🎯 技能(" +
      sklNames.length +
      '/3): <span style="color:' +
      (sklNames.length > 0 ? "var(--yq-purple)" : "var(--yq-muted)") +
      '">' +
      (sklNames.length > 0 ? escHtml(sklNames.join(" / ")) : "无") +
      "</span></span>";
    if (sklNames.length > 0 && canEquip)
      html +=
        '<button class="yq-btn yq-v10-manage" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" data-slot="skills" style="padding:1px 6px;font-size:9px;color:var(--yq-purple);border-color:rgba(139,92,246,0.2)">管理</button>';
    html += "</div>";

    // 宠物（最多1）
    // [V11.3·2026-05-20] 所有角色都显示宠物栏（赠予后宠物归对方所有）
    //   - user / 林知意 / 在场好感度≥50女性（canEquip=true）：显示收回按钮（回对方背包）
    //   - 男性角色（canEquip=false）：只读展示，召唤/收回由 AI patch 控制
    var petName = pet ? (typeof pet === "string" ? pet : "") : "";
    // [V10.5/V10.3 万界生效] 宠物 CP 加持显示 — 走 lookup
    var _petBoostDisplay = "";
    if (petName) {
      var _pb =
        typeof _yqGetPetBoost === "function" ? _yqGetPetBoost(petName) : 0;
      if (_pb > 0) _petBoostDisplay = " (CP+" + _pb + ")";
    }
    // [V10.6] 宠物显示名映射
    var _petShowName = petName
      ? typeof _petDisplayName === "function"
        ? _petDisplayName(petName)
        : petName
      : "";
    html +=
      '<div style="display:flex;align-items:center;justify-content:space-between">';
    html +=
      '<span>🐾 宠物: <span style="color:' +
      (petName ? "var(--yq-gold)" : "var(--yq-muted)") +
      '">' +
      escHtml(petName ? _petShowName + _petBoostDisplay : "无") +
      "</span></span>";
    // canEquip 已包含 user + 林知意 + 在场好感度≥50女性，跟武器/防具卸下按钮逻辑一致
    if (petName && canEquip)
      html +=
        '<button class="yq-btn yq-v10-unequip" data-char="' +
        escHtml(charName) +
        '" data-path="' +
        escHtml(charPath) +
        '" data-slot="pet" data-item="' +
        escHtml(petName) +
        '" style="padding:1px 6px;font-size:9px;color:var(--yq-red);border-color:rgba(255,64,96,0.2)">收回</button>';
    html += "</div>";

    html += "</div></div>";
    return html;
  } catch (_eEO) {
    try {
      console.warn("[V10 装备概览] 渲染异常", _eEO);
    } catch (_) {}
    return "";
  }
}

// [V9.7·TG启发·P0] 给 AI prompt 用的完整 desc：把 `|AI|` 分隔符替换成自然语言
// 防止原始 `|AI|` token 直接出现在 AI 上下文里造成奇怪的符号输出
function _getAiVisibleDesc(rawDesc) {
  if (!rawDesc) return "";
  var s = String(rawDesc);
  // `|AI|` 标记仅是玩家端分隔用途，对 AI 来说是噪音；替换为自然换行语义
  return s.replace(/\s*\|AI\|\s*/g, "；").trim();
}

function buildShopPage(d) {
  var acc = (d.银麒系统 || {}).账户 || {};
  var pts = Number(acc.银麒点 || 0);
  var lv = Number(acc.系统等级 || 1);
  var categories = [
    { id: "wpn", icon: "🗡️", label: "武器" },
    { id: "arm", icon: "🛡️", label: "防具" },
    { id: "spc", icon: "✨", label: "特殊" },
    { id: "abl", icon: "⚡", label: "能力" },
    { id: "skl", icon: "🎯", label: "技能" },
    { id: "fac", icon: "🔧", label: "器械" },
    { id: "csm", icon: "💊", label: "消耗" },
    { id: "pet", icon: "🐾", label: "宠物" },
  ];

  var html = "";

  // 商城模式Tab：常驻 / 万界搜索
  html += '<div class="yq-tabs2" style="margin-bottom:4px">';
  html +=
    '<div class="yq-tab2 active" data-shop-mode="permanent">🏪 常驻商品</div>';
  html += '<div class="yq-tab2" data-shop-mode="custom">🔮 万界搜索</div>';
  html += "</div>";

  html += '<div id="yq-shop-mode-body">';
  html += buildShopPermanentMode(categories, pts, lv);
  html += "</div>";

  return html;
}

function buildShopPermanentMode(categories, pts, lv) {
  var html = "";

  // 二级Tab: 分类
  html += '<div class="yq-tabs2">';
  for (var ci = 0; ci < categories.length; ci++) {
    html +=
      '<div class="yq-tab2' +
      (ci === 0 ? " active" : "") +
      '" data-shop-cat="' +
      categories[ci].id +
      '">' +
      categories[ci].icon +
      '<span class="yq-shop-cat-label"> ' +
      categories[ci].label +
      "</span></div>";
  }
  html += "</div>";

  // 三级Tab: 等级
  html +=
    '<div style="display:flex;flex-wrap:wrap;background:rgba(14,14,26,0.3);padding:4px 8px;gap:4px;border-bottom:1px solid var(--yq-border);margin-top:2px">';
  for (var li = 1; li <= 6; li++) {
    var locked = li > lv;
    html +=
      '<div class="yq-tab3' +
      (li === 1 ? " active" : "") +
      (locked ? " locked" : "") +
      '" data-shop-lv="' +
      li +
      '">' +
      (locked ? "🔒" : "") +
      "LV" +
      li +
      "</div>";
  }
  html += "</div>";

  // [V10.4 Task2·2026-05-16] 万界 customs 渲染已移入 buildShopItems(catId,...)
  //   原 V10.3：customs 全量铺在 #yq-shop-items 容器外，所有 cat tab 都看到全部
  //   现 V10.4：移入 buildShopItems 内按 c.category===catId 过滤，切 cat tab 自动重渲
  //   万界 tab（buildShopCustomMode）保留全量列表（管理界面）

  // 商品列表区域
  html += '<div id="yq-shop-items" style="margin-top:6px">';
  html += buildShopItems("sys", 1, pts, lv);
  html += "</div>";
  // 展示给角色按钮
  html +=
    '<div style="margin-top:10px"><button class="yq-btn gold yq-display-shop-btn" style="width:100%;padding:10px;font-size:13px" disabled>📋 展示给角色（请勾选商品）</button></div>';

  return html;
}

function buildShopCustomMode(pts, lv) {
  var html = "";
  html +=
    '<div style="display:flex;justify-content:space-between;margin-bottom:6px"><div style="display:flex;gap:4px"><button class="yq-btn yq-shop-import" style="padding:4px 8px;font-size:.72rem;color:var(--yq-cyan);border-color:var(--yq-border)">📥 导入</button><button class="yq-btn yq-shop-export" style="padding:4px 8px;font-size:.72rem;color:var(--yq-gold);border-color:var(--yq-border)">📤 导出</button></div>';
  html +=
    '<button class="yq-btn" id="yq-shop-api-settings" style="padding:4px 10px;font-size:.72rem;color:var(--yq-dim);border-color:var(--yq-border)">⚙️ API设置</button>';
  html += "</div>";
  html +=
    '<div style="font-size:.78rem;color:var(--yq-fg);margin-bottom:6px">🔍 描述你想要的道具，AI评估定价（价格×2）</div>';
  html +=
    '<textarea id="yq-custom-input" rows="3" placeholder="例：一种能让穿戴者对精液产生依赖的纳米贴片..." style="width:100%;padding:8px;background:var(--yq-input);color:var(--yq-fg);border:1px solid var(--yq-border);border-radius:var(--yq-r-s);font-size:.78rem;resize:vertical;box-sizing:border-box"></textarea>';
  html += '<div style="text-align:center;margin-top:8px">';
  html +=
    '<button class="yq-btn primary" id="yq-custom-search" style="padding:8px 20px">🔮 万界搜索</button>';
  html += "</div>";
  html += '<div id="yq-custom-result" style="margin-top:10px"></div>';

  // 已有自定义商品列表
  var customs = getMeta("yinqi_custom_items", []);
  if (customs.length > 0) {
    html +=
      '<div style="margin-top:12px;border-top:1px solid var(--yq-border);padding-top:8px">';
    html +=
      '<div style="font-size:.78rem;color:var(--yq-purple);font-weight:600;margin-bottom:6px">已定制商品</div>';
    for (var i = 0; i < customs.length; i++) {
      var c = customs[i];
      var canBuyC = pts >= (c.price || 0);
      html +=
        '<div class="yq-card" style="padding:6px 8px;display:flex;justify-content:space-between;align-items:center">';
      html +=
        '<div style="flex:1;min-width:0"><div style="font-size:.78rem;color:#e8e6f0">' +
        escHtml(c.name || "") +
        "</div>";
      html +=
        '<div style="font-size:.68rem;color:#9a98b0">' +
        escHtml(c.effect || c.desc || "") +
        "</div></div>";
      html +=
        '<div style="display:flex;gap:4px;align-items:center;flex-shrink:0;margin-left:6px">';
      html +=
        '<span style="font-size:.75rem;color:#f0c860">' +
        (c.price || 0) +
        "点</span>";
      html +=
        '<button class="yq-btn gold yq-buy-custom' +
        (canBuyC ? "" : " disabled") +
        '" data-cidx="' +
        i +
        '" data-custom-id="' +
        escHtml(c.customId || "") +
        '" data-price="' +
        (c.price || 0) +
        '">购买</button>';
      html +=
        '<button class="yq-btn danger yq-del-custom" data-cidx="' +
        i +
        '" data-custom-id="' +
        escHtml(c.customId || "") +
        '" style="padding:2px 6px;font-size:.7rem">🗑</button>';
      html += "</div></div>";
    }
    html += "</div>";
  }
  return html;
}

function buildShopItems(catId, level, pts, sysLv) {
  if (level > sysLv)
    return '<div class="yq-empty">需要系统等级LV' + level + "解锁</div>";

  var html = "";

  // [V10.4 Task2·2026-05-16] 万界 customs 按 cat 过滤渲染
  //   仅在当前 cat tab 显示对应分类的 customs；缺 c.category 的老数据归 "etc" 不显示
  //   cidx 必须用 customs 全量数组真实 index（不是 filter 后子 index），
  //   购买事件 _bind_events.js:4003-4101 会用 customId 二次定位兜底
  //   注：customs 不受 level tab 过滤，只看 cat；超 sysLv 的 customs 置灰但保留
  var _allCustoms = getMeta("yinqi_custom_items", []);
  if (_allCustoms.length > 0) {
    var _matchedHtml = "";
    var _matchedCount = 0;
    for (var _ci2 = 0; _ci2 < _allCustoms.length; _ci2++) {
      var _c = _allCustoms[_ci2];
      var _cCat = _c.category || "etc";
      if (_cCat !== catId) continue;
      var _cLvOk = Number(_c.level || 1) <= sysLv;
      var _canBuyC = pts >= (_c.price || 0);
      _matchedHtml +=
        '<div class="yq-card" style="padding:6px 8px;display:flex;justify-content:space-between;align-items:center' +
        (!_cLvOk ? ";opacity:0.4" : "") +
        '">';
      _matchedHtml +=
        '<div style="flex:1;min-width:0"><div style="font-size:.78rem;color:#e8e6f0">' +
        escHtml(_c.name || "") +
        ' <span style="font-size:.62rem;color:#5a586e">LV' +
        (_c.level || 1) +
        " " +
        ({
          sys: "⚙️",
          wpn: "🗡️",
          arm: "🛡️",
          spc: "✨",
          abl: "⚡",
          skl: "🎯",
          fac: "🔧",
          csm: "💊",
          pet: "🐾",
          etc: "📦",
        }[_cCat] || "📦") +
        "</span>" +
        "</div>";
      _matchedHtml +=
        '<div style="font-size:.68rem;color:#9a98b0">' +
        escHtml(_c.effect || _c.desc || "") +
        "</div></div>";
      _matchedHtml +=
        '<div style="display:flex;gap:4px;align-items:center;flex-shrink:0;margin-left:6px">';
      _matchedHtml +=
        '<span style="font-size:.75rem;color:#f0c860">' +
        (_c.price || 0) +
        "点</span>";
      _matchedHtml +=
        '<button class="yq-btn gold yq-buy-custom' +
        (_canBuyC && _cLvOk ? "" : " disabled") +
        '" data-cidx="' +
        _ci2 +
        '" data-custom-id="' +
        escHtml(_c.customId || "") +
        '" data-price="' +
        (_c.price || 0) +
        '">购买</button>';
      _matchedHtml +=
        '<button class="yq-btn danger yq-del-custom" data-cidx="' +
        _ci2 +
        '" data-custom-id="' +
        escHtml(_c.customId || "") +
        '" style="padding:2px 6px;font-size:.7rem">🗑</button>';
      _matchedHtml += "</div></div>";
      _matchedCount++;
    }
    if (_matchedCount > 0) {
      html +=
        '<div style="margin:0 0 6px"><div style="font-size:.78rem;color:var(--yq-purple);font-weight:600;margin-bottom:4px">🔮 自定义商品（' +
        _matchedCount +
        " 件）</div>";
      html += _matchedHtml;
      html += "</div>";
    }
  }

  // 从phoneMeta读取常驻商品（07_panels.js中硬编码的）
  // 这里简化处理——实际商品数据在手机UI的07_panels.js中
  // 底部面板从phoneMeta读取或直接硬编码核心商品
  var items = getShopItemsByCatAndLevel(catId, level);
  // [V10.4 Task2] empty 提示拼到 customs html 之后，避免丢掉 customs 渲染
  if (items.length === 0)
    return html + '<div class="yq-empty">该分类暂无LV' + level + "商品</div>";

  // [V10.4 Task2] 不再 var html=""（前面已声明），直接追加内置商品
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    // [V10.11·2026-05-18] 隐藏已迁移到据点直购的道具（掩饰 4 件）
    if (item._hidden) continue;
    var canBuy = pts >= item.price;
    // 判断是否为重要剧情道具
    var isPlotItem =
      item.category === "plot" ||
      item.name === "命运偏转符" ||
      item.name === "基因锚定剂" ||
      item.name === "丧尸咬伤解毒剂" ||
      item.name === "丧尸驱避剂";
    var nameColor = isPlotItem
      ? "color:#FFD700;font-weight:700;text-shadow:0 0 3px rgba(255,215,0,0.4)"
      : "color:#e8e6f0";

    // [V8] 商城折叠详情:默认只显名字+价格+购买,点"ℹ"或整卡展开 desc(本地 toggle)
    html +=
      '<div class="yq-card yq-shop-item-card" style="padding:6px 8px;cursor:pointer" title="点击卡片查看详情">';
    // 第一行:名字 + 价格 + 购买（class 化；移动端自动换行为两行）
    html += '<div class="yq-shop-row1">';
    html +=
      '<div class="yq-shop-name-group"><input type="checkbox" class="yq-shop-display-check" data-name="' +
      escHtml(item.name) +
      '" data-desc="' +
      escHtml(item.desc || "") +
      '" data-price="' +
      item.price +
      '" data-level="' +
      level +
      '">';
    html +=
      '<div class="yq-shop-name"><span style="font-size:.78rem;' +
      nameColor +
      '">' +
      escHtml(
        item.type === "pet" && typeof _petDisplayName === "function"
          ? _petDisplayName(item.name)
          : item.name,
      ) +
      "</span></div></div>";
    html += '<div class="yq-shop-ops">';
    html +=
      '<button class="yq-btn yq-shop-toggle-desc" style="padding:2px 6px;font-size:10px;color:var(--yq-muted);border-color:var(--yq-border);background:rgba(255,255,255,0.02)" title="查看道具说明">ℹ</button>';
    // [V8] 如果 sessionStorage 里有最近购买记录(20 秒内且匹配),渲染为撤回按钮
    var _pendUndo = null;
    try {
      var raw = sessionStorage.getItem("_yqLastShopBuy_" + item.name);
      if (raw) {
        var o = JSON.parse(raw);
        if (o && Date.now() - (o.at || 0) < 20000) _pendUndo = o;
      }
    } catch (_e) {}
    // 左侧槽: 撤回在「−」左边,空槽对齐桌面端各行「购买」列（移动端 CSS 覆盖为 min-width:0）
    html += '<div class="yq-shop-lead">';
    if (_pendUndo) {
      html +=
        '<button class="yq-btn danger yq-undo-buy" data-item-id="' +
        escHtml(item.name) +
        '" data-price="' +
        item.price +
        '" data-old-pts="' +
        _pendUndo.oldPts +
        '" data-bought-qty="' +
        _pendUndo.qty +
        '">已购×' +
        _pendUndo.qty +
        " ↩撤回</button>";
    }
    html += "</div>";
    // [V8] +/- 数字输入 批量购买
    // [V7.3.1 CH-10] price=0 时 pts/0 为 Infinity，input max="Infinity" 会导致 parseInt(NaN)、
    // 控件与部分环境下 save/重渲异常；0 价商品（魅魔诱饵）强制单次购买 maxQty=1
    var maxQty =
      !item.price || item.price <= 0
        ? 1
        : Math.max(1, Math.floor(pts / item.price));
    html += '<div class="yq-shop-qty-wrap">';
    html +=
      '<button class="yq-btn yq-shop-qty-minus" data-item-id="' +
      escHtml(item.name) +
      '" style="padding:0 6px;font-size:12px;color:var(--yq-dim);border:0;background:transparent;min-width:20px" title="-1">−</button>';
    html +=
      '<input type="number" class="yq-shop-qty-input" data-item-id="' +
      escHtml(item.name) +
      '" data-price="' +
      item.price +
      '" data-max="' +
      maxQty +
      '" value="1" min="1" max="' +
      maxQty +
      '" style="width:36px;padding:2px;font-size:11px;text-align:center;background:transparent;border:0;color:#e2e8f0">';
    html +=
      '<button class="yq-btn yq-shop-qty-plus" data-item-id="' +
      escHtml(item.name) +
      '" style="padding:0 6px;font-size:12px;color:var(--yq-dim);border:0;background:transparent;min-width:20px" title="+1">+</button>';
    html += "</div>";
    // 总价显示 (动态更新)
    html +=
      '<span class="yq-shop-total-price" data-item-id="' +
      escHtml(item.name) +
      '" data-price="' +
      item.price +
      '">' +
      item.price +
      "点</span>";
    // 右侧槽: 仅「购买」,与左侧槽互斥,撤回消失后桌面端仍占宽度以免错位（移动端 CSS 覆盖）
    html += '<div class="yq-shop-tail">';
    if (!_pendUndo) {
      html +=
        '<button class="yq-btn gold yq-buy-item' +
        (canBuy ? "" : " disabled") +
        '" data-item-id="' +
        escHtml(item.name) +
        '" data-price="' +
        item.price +
        '">购买</button>';
    }
    html += "</div>";
    html += "</div>";
    html += "</div>";
    // [V2/§4] v2 道具门槛徽章（总是显示，不折叠）
    if (item.v2Group) {
      var _v2Tags = [];
      // [V10.9·2026-05-18] 玩家可读化：total → 累计完成任务次数；B级/S级/X级 → B/S/X 级任务次数
      if (item.reqTaskTotal != null)
        _v2Tags.push("累计任务≥" + item.reqTaskTotal + "次");
      if (item.reqTaskB != null)
        _v2Tags.push("B 级任务≥" + item.reqTaskB + "次");
      if (item.reqTaskS != null)
        _v2Tags.push("S 级任务≥" + item.reqTaskS + "次");
      if (item.reqTaskX != null)
        _v2Tags.push("X 级任务≥" + item.reqTaskX + "次");
      if (item.uniqueSkill) _v2Tags.push("全卡限1位");
      if (item.maxStack != null && item.maxStack > 1)
        _v2Tags.push("同角色可叠" + item.maxStack + "次");
      if (item.reqPrereq) _v2Tags.push("需先购「" + item.reqPrereq + "」");
      if (item.reqSysLv) _v2Tags.push("需系统LV" + item.reqSysLv + "+");
      if (item.v2SkillTarget) _v2Tags.push("仅" + item.v2SkillTarget);
      if (item.v2SkillGender === "male") _v2Tags.push("仅男性");
      if (item.v2SkillGender === "female") _v2Tags.push("仅女性");
      if (_v2Tags.length > 0) {
        html +=
          '<div style="display:flex;flex-wrap:wrap;gap:3px;margin-top:3px">';
        for (var _vt = 0; _vt < _v2Tags.length; _vt++) {
          html +=
            '<span style="font-size:9px;color:var(--yq-gold);background:rgba(240,200,96,0.10);padding:0px 4px;border-radius:2px;line-height:1.4">' +
            escHtml(_v2Tags[_vt]) +
            "</span>";
        }
        html += "</div>";
      }
    }
    // 第二行:折叠详情(默认 hidden)
    // [V9.7·TG启发·P0] 玩家可见文案：取 `|AI|` 之前；AI 演绎提示对玩家隐藏
    html +=
      '<div class="yq-item-desc" style="display:none;font-size:.68rem;color:#9a98b0;margin-top:4px;line-height:1.5">' +
      escHtml(_getPlayerVisibleDesc(item.desc) || "无描述") +
      "</div>";
    // [V11.8.10·P1-7 fix·2026-05-27] doll 型道具配套销售提示
    //   原 BUG: 超仿真人偶 + 感官接入套件 必须配合使用,但商城没显式提示
    //   修复: 检测玩家持有状态,未持有配套件时显示提示
    if (item.name === "超仿真人偶" || item.name === "感官接入套件") {
      var _pairName =
        item.name === "超仿真人偶" ? "感官接入套件" : "超仿真人偶";
      var _hasInv = false;
      try {
        var _inv = getMeta("yinqi_inventory", {}) || {};
        _hasInv = !!(_inv[_pairName] && _inv[_pairName].qty > 0);
      } catch (_eDoll) {}
      if (!_hasInv) {
        html +=
          '<div style="margin-top:3px;padding:3px 6px;background:rgba(244,63,94,0.10);border-left:2px solid var(--yq-rose);font-size:.65rem;color:var(--yq-rose);line-height:1.4">⚠️ doll 型 S 级任务需配合「' +
          escHtml(_pairName) +
          "」使用,当前未持有</div>";
      } else {
        html +=
          '<div style="margin-top:3px;padding:3px 6px;background:rgba(34,197,94,0.10);border-left:2px solid var(--yq-cyan);font-size:.65rem;color:var(--yq-cyan);line-height:1.4">✅ 已持有「' +
          escHtml(_pairName) +
          "」,可组成 doll 型 S 级任务装备组</div>";
      }
    }
    html += "</div>";
  }
  return html;
}

