// ==================== 角色性别硬约束（与 [initvar] 同步） ====================
// 核心 NPC 性别为"设定写死、不可变更"的硬事实；AI 若把他们 insert 到错误的一侧，
// 面板渲染前会自动搬回正确侧（含字段合并），防止配角页显示"陈文博"带好感度/攻略度。
// 与 `[initvar]变量初始化.xyaml` 的 `女性角色` / `男性角色` 段保持一致。
// 注：主角（{{user}}）不进该表——主角走 stat_data.user，不该出现在 男性角色/女性角色 record。
// 若 AI 误把主角 insert 到 record，由 `_yqEvictUserFromRecords` 单独清理（见 _yqFixCharGenderMismatch）。
var MALE_CORE_NAMES = {
  赵文斌: 1,
  刘振宇: 1,
  陈文博: 1,
  强坤: 1,
  林鸿盛: 1,
};
var FEMALE_CORE_NAMES = {
  林知意: 1, // 主角配角（独立 stat_data.角色.林知意）
  宋以薇: 1,
  方若琳: 1,
  李婉柔: 1,
  林安然: 1,
  苏曼: 1,
  沈若兰: 1,
};

/**
 * 扫描 stat_data.女性角色 / stat_data.男性角色，把被 AI 错放侧的**核心 NPC**迁回正确侧。
 * - 若错侧有字段（如屈辱度/好感度），尽量合并回正确侧后再删除错条目，避免丢数据。
 * - 返回 { moved: [{name, from, to}], cleaned: n } 供调试观察与日志记录。
 * 安全：未识别的非核心 NPC 不动（留给 MVU 规则约束）；仅操作内存，调用方负责 saveMeta。
 */
function _yqFixCharGenderMismatch(opts) {
  opts = opts || {};
  var d = getAllData() || {};
  var fem = d.女性角色 || {};
  var male = d.男性角色 || {};
  var moved = [];
  var cleaned = 0;

  // 字段白名单（与 [initvar] / [mvu_update] 同步）
  var MALE_ALLOWED = { 屈辱度: 1, 姓名: 1, 昵称: 1, 装备: 1, 状态: 1, 能力: 1 };
  var FEMALE_ALLOWED = {
    好感度: 1,
    攻略度: 1,
    与user关系: 1,
    已与user性交: 1,
    姓名: 1,
    昵称: 1,
    装备: 1,
    状态: 1,
    能力: 1,
  };

  function mergeFields(target, source) {
    if (!source) return target || {};
    if (!target) target = {};
    for (var k in source) {
      if (!source.hasOwnProperty(k)) continue;
      if (target[k] == null || target[k] === "") target[k] = source[k];
    }
    return target;
  }
  function pickByWhitelist(obj, whitelist) {
    var out = {};
    if (!obj) return out;
    for (var k in obj) {
      if (obj.hasOwnProperty(k) && whitelist[k]) out[k] = obj[k];
    }
    return out;
  }

  // 0) 主角（{{user}}）不该出现在 女性角色/男性角色 record —— 若 AI 误 insert，直接清出
  try {
    var _userName = getUserName();
    if (_userName && _userName !== "主角") {
      if (fem[_userName]) {
        setVar("女性角色." + _userName, undefined);
        moved.push({ name: _userName, from: "女性角色", to: "user(主角清出)" });
        cleaned++;
      }
      if (male[_userName]) {
        setVar("男性角色." + _userName, undefined);
        moved.push({ name: _userName, from: "男性角色", to: "user(主角清出)" });
        cleaned++;
      }
    }
  } catch (_eEvU) {}

  // 1) 男性核心在女性侧 → 搬回男性侧（合并后按男性白名单过滤，剔除好感度/攻略度等女性字段）
  Object.keys(MALE_CORE_NAMES).forEach(function (name) {
    if (fem[name]) {
      var merged = mergeFields(male[name] || {}, fem[name]);
      merged = pickByWhitelist(merged, MALE_ALLOWED);
      if (merged.屈辱度 == null) merged.屈辱度 = 0;
      setVar("男性角色." + name, merged);
      setVar("女性角色." + name, undefined);
      moved.push({ name: name, from: "女性角色", to: "男性角色" });
      cleaned++;
    }
  });

  // 2) 女性核心在男性侧 → 搬回女性侧（林知意除外，她在 stat_data.角色.林知意）
  Object.keys(FEMALE_CORE_NAMES).forEach(function (name) {
    if (name === "林知意") return;
    if (male[name]) {
      var merged = mergeFields(fem[name] || {}, male[name]);
      merged = pickByWhitelist(merged, FEMALE_ALLOWED);
      if (merged.好感度 == null) merged.好感度 = 0;
      if (merged.攻略度 == null) merged.攻略度 = 0;
      if (merged["与user关系"] == null) merged["与user关系"] = "陌生人";
      if (merged["已与user性交"] == null) merged["已与user性交"] = false;
