// ============================================================
// [V6.5.1 · 信息通道修复 · Fix #5] NPC 一致性清扫
// ------------------------------------------------------------
// 当某 NPC 已处于"明确不可正常联系"状态（丧尸/永久失联/Ⅶ级后宫殿永久关押）时，
// 标记该 NPC 在手机 UI 各社交渠道（朋友圈/论坛/直播/聊天）的内容为 _apocHidden:true，
// 让 [EJS]手机动态摘要 不再注入给主 AI，也让手机 UI 渲染层跳过这些内容。
//
// 保守原则（防误清）：只在 3 种"明确强信号"下清扫，绝不做模糊推断：
// 1. yinqi_friend_meta[name].postApocStatus === 'zombie' | 'permanent_lost'
// 2. stat_data.女性角色.{name}.hp === 0 或 男性角色.{name}.hp === 0（若 Schema 含 hp 字段）
// 3. 角色.林知意._takenByAwakener.statusNow === 'apex_permanent_concubine'
// 女性角色.{name}._takenByAwakener.statusNow === 'apex_permanent_concubine'
//
// 只改 _apocHidden 派生字段，不删原数据；与删楼回档兼容（回档后可重新清扫）。
// 调用频率控制：_refreshPanelNow 入口节流 30s。
// ============================================================
var _syncApocHiddenLastAt = 0;
function _yqSyncNpcStatusToPhone(opts) {
  opts = opts || {};
  try {
    var now = Date.now();
    if (!opts.force && now - _syncApocHiddenLastAt < 30000) return null;
    _syncApocHiddenLastAt = now;

    var ctx = _getCtx && _getCtx();
    if (!ctx || !ctx.chatMetadata) return null;
    var pm = ctx.chatMetadata.yinqi_phone;
    if (!pm) return null;

    // ---------- 构建明确不可正常联系的 NPC 名单 ----------
    var apocSet = {};
    function _markApoc(name, reason) {
      var k = String(name || "").trim();
      if (!k) return;
      apocSet[k] = { reason: reason, at: now };
    }

    // 信号 1：yinqi_friend_meta.postApocStatus
    try {
      var fm = pm.yinqi_friend_meta || {};
      Object.keys(fm).forEach(function (name) {
        var row = fm[name];
        if (!row || row._aliasOf) return;
        var s = row.postApocStatus;
        if (s === "zombie") _markApoc(name, "zombie");
        else if (s === "permanent_lost") _markApoc(name, "permanent_lost");
      });
    } catch (_eF1) {}

    // 信号 2：stat_data.女性角色/男性角色.{name}.hp === 0
    try {
      var d = getAllData() || {};
      var femX = d.女性角色 || {};
      Object.keys(femX).forEach(function (name) {
        var ch = femX[name];
        if (!ch) return;
        if (typeof ch.hp === "number" && ch.hp === 0)
          _markApoc(name, "hp_zero");
        // 林知意虽在 d.角色.林知意，这里只处理 record 里的
      });
      var maleX = d.男性角色 || {};
      Object.keys(maleX).forEach(function (name) {
        var ch = maleX[name];
        if (!ch) return;
        if (typeof ch.hp === "number" && ch.hp === 0)
          _markApoc(name, "hp_zero");
      });
      // 信号 3：_takenByAwakener.statusNow === 'apex_permanent_concubine'
      Object.keys(femX).forEach(function (name) {
        var ch = femX[name];
        if (!ch) return;
        var tb = ch._takenByAwakener;
        if (tb && tb.statusNow === "apex_permanent_concubine")
          _markApoc(name, "apex_concubine");
      });
      var linz = (d.角色 || {}).林知意;
      if (
        linz &&
        linz._takenByAwakener &&
        linz._takenByAwakener.statusNow === "apex_permanent_concubine"
      ) {
        _markApoc("林知意", "apex_concubine");
      }
    } catch (_eF23) {}

    var hiddenCount = 0;
    var restoredCount = 0;
    var changed = false;

    // ---------- 1. 写 yinqi_apoc_hidden_contacts 索引 map（供 EJS + 手机 UI guard 读）----------
    try {
      var old = pm.yinqi_apoc_hidden_contacts || {};
      var oldStr = JSON.stringify(old);
      var newStr = JSON.stringify(apocSet);
      if (oldStr !== newStr) {
        pm.yinqi_apoc_hidden_contacts = apocSet;
        changed = true;
      }
    } catch (_eIdx) {}

    function _hitApoc(nm) {
      if (!nm) return false;
      return !!apocSet[String(nm).trim()];
    }

    // ---------- 2. 标记 moments ----------
    try {
      var momArr = pm.moments;
      if (Array.isArray(momArr)) {
        for (var mi = 0; mi < momArr.length; mi++) {
          var mm = momArr[mi];
          if (!mm) continue;
          var shouldHide = _hitApoc(mm.author);
          if (shouldHide && !mm._apocHidden) {
            mm._apocHidden = true;
            hiddenCount++;
            changed = true;
          } else if (!shouldHide && mm._apocHidden) {
            // 理论上不会反转（zombie 是单向终态），但保留兜底
            delete mm._apocHidden;
            restoredCount++;
            changed = true;
          }
        }
      }
    } catch (_eMM) {}

    // ---------- 3. 标记 forum_data ----------
    try {
      var fd = pm.forum_data;
      if (fd && typeof fd === "object") {
        Object.keys(fd).forEach(function (board) {
          var posts = fd[board];
          if (!Array.isArray(posts)) return;
          for (var pi = 0; pi < posts.length; pi++) {
            var pp = posts[pi];
            if (!pp) continue;
            var shouldHideP = _hitApoc(pp.author);
            if (shouldHideP && !pp._apocHidden) {
              pp._apocHidden = true;
              hiddenCount++;
              changed = true;
            } else if (!shouldHideP && pp._apocHidden) {
              delete pp._apocHidden;
              restoredCount++;
              changed = true;
            }
          }
        });
      }
    } catch (_eFd) {}

    // ---------- 4. 标记 live_rooms ----------
    try {
      var lr = pm.live_rooms;
      if (Array.isArray(lr)) {
        for (var li = 0; li < lr.length; li++) {
          var rr = lr[li];
          if (!rr) continue;
          var shouldHideL = _hitApoc(rr.hostName);
          if (shouldHideL && !rr._apocHidden) {
            rr._apocHidden = true;
            hiddenCount++;
            changed = true;
          } else if (!shouldHideL && rr._apocHidden) {
            delete rr._apocHidden;
            restoredCount++;
            changed = true;
          }
        }
      }
    } catch (_eLr) {}

    if (changed) {
      try {
        saveMeta();
      } catch (_eSv) {}
      try {
        if (opts.log !== false) {
          _yqCore.taskFlow.appendOperationLog("apoc_sync_npc_status", {
            hidden: hiddenCount,
            restored: restoredCount,
            total: Object.keys(apocSet).length,
          });
        }
      } catch (_eLg) {}
    }

    return {
      apocNames: Object.keys(apocSet),
      hidden: hiddenCount,
      restored: restoredCount,
    };
  } catch (_eAll) {
    try {
      console.warn("[apoc-sync] 清扫异常:", _eAll);
    } catch (_) {}
    return null;
  }
}

