    var bFem = !!femChars[b];
    if (aFem && !bFem) return -1;
    if (!aFem && bFem) return 1;
    return 0;
  });
  if (absentNames.length > 0) {
    // 核心角色不可删除
    var _coreChars = {
      林知意: 1,
      赵文斌: 1,
      刘振宇: 1,
      陈文博: 1,
      宋以薇: 1,
      方若琳: 1,
      李婉柔: 1,
      林安然: 1,
      林鸿盛: 1,
      沈若兰: 1,
      强坤: 1,
      苏曼: 1,
    };
    html += '<div class="yq-char-grid">';
    for (var ai = 0; ai < absentNames.length; ai++) {
      var an = absentNames[ai];
      var aFem = femChars[an];
      var aMale = maleChars[an];
      html += renderCharCard(an, null, !!aFem, aFem || aMale, false);
      // 非核心角色显示删除按钮
      if (!_coreChars[an]) {
        html +=
          '<div style="text-align:right;margin-top:-8px;margin-bottom:8px;padding-right:8px"><button class="yq-btn yq-delete-char-btn" data-name="' +
          escHtml(an) +
          '" data-gender="' +
          (aFem ? "f" : "m") +
          '" style="padding:3px 10px;font-size:10px;color:var(--yq-red);border-color:rgba(255,64,96,0.2)">🗑️ 删除角色</button></div>';
      }
    }
    html += "</div>";
  } else {
    html += '<div class="yq-empty">所有角色都在场</div>';
  }
  html += "</div>";

  // === 关系网（SVG网络图 + 头像节点 + 箭头连线） ===
  html +=
    '<div class="yq-char-page" data-char="relations" style="display:none">';
  var _un = getUserName();

  // SVG关系网络图
  var W = 460,
    H = 520;
  // 节点位置（手动布局，以男女主为中心）
  var nodes = [
    { name: _un, x: 150, y: 200, c: "#f0c860", r: "男主" },
    { name: "林知意", x: 310, y: 200, c: "#ff6b9d", r: "女主" },
    { name: "赵文斌", x: 60, y: 80, c: "#00f0ff", r: "室友" },
    { name: "刘振宇", x: 150, y: 50, c: "#00f0ff", r: "室友" },
    { name: "陈文博", x: 240, y: 80, c: "#00f0ff", r: "室友" },
    { name: "宋以薇", x: 400, y: 80, c: "#ff6b9d", r: "闺蜜" },
    { name: "方若琳", x: 400, y: 200, c: "#ff6b9d", r: "闺蜜" },
    { name: "李婉柔", x: 400, y: 320, c: "#ff6b9d", r: "闺蜜" },
    { name: "林安然", x: 310, y: 400, c: "#ff6b9d", r: "妹妹" },
    { name: "强坤", x: 60, y: 320, c: "#00f0ff", r: "父亲" },
    { name: "苏曼", x: 60, y: 200, c: "#ff6b9d", r: "母亲" },
    { name: "林鸿盛", x: 230, y: 460, c: "#00f0ff", r: "岳父" },
    { name: "沈若兰", x: 380, y: 460, c: "#ff6b9d", r: "岳母" },
  ];
  // 连线关系
  var edges = [
    { from: _un, to: "林知意", label: "💕恋人", color: "#ff6b9d" },
    { from: _un, to: "赵文斌", label: "兄弟", color: "#00f0ff44" },
    { from: _un, to: "刘振宇", label: "兄弟", color: "#00f0ff44" },
    { from: _un, to: "陈文博", label: "兄弟", color: "#00f0ff44" },
    { from: "林知意", to: "宋以薇", label: "闺蜜", color: "#ff6b9d44" },
    { from: "林知意", to: "方若琳", label: "闺蜜", color: "#ff6b9d44" },
    { from: "林知意", to: "李婉柔", label: "闺蜜", color: "#ff6b9d44" },
    { from: "林知意", to: "林安然", label: "姐妹", color: "#ff6b9d88" },
    { from: "赵文斌", to: "宋以薇", label: "前任✕", color: "#ff406044" },
    { from: "刘振宇", to: "方若琳", label: "♥情侣", color: "#8b5cf688" },
    { from: "陈文博", to: "李婉柔", label: "♥情侣", color: "#8b5cf688" },
    { from: "强坤", to: _un, label: "父子", color: "#f0c86044" },
    { from: "苏曼", to: _un, label: "母子", color: "#f0c86044" },
    { from: "林鸿盛", to: "林知意", label: "父女", color: "#ff6b9d44" },
    { from: "沈若兰", to: "林知意", label: "母女", color: "#ff6b9d44" },
    { from: "强坤", to: "林鸿盛", label: "酒友", color: "#ffffff22" },
    { from: "强坤", to: "苏曼", label: "♥夫妻", color: "#8b5cf688" },
    { from: "林鸿盛", to: "沈若兰", label: "♥夫妻", color: "#8b5cf688" },
  ];

  // 构建节点索引
  var nodeMap = {};
  for (var ni = 0; ni < nodes.length; ni++) nodeMap[nodes[ni].name] = nodes[ni];

  // 缩放控制按钮
  html += '<div style="position:relative;padding:8px">';
  html +=
    '<div style="position:absolute;top:12px;right:12px;z-index:5;display:flex;flex-direction:column;gap:4px">';
  html +=
    '<button class="yq-btn yq-rel-zoom-in" style="padding:4px 8px;font-size:16px;color:var(--yq-cyan);border-color:var(--yq-border);line-height:1">➕</button>';
  html +=
    '<button class="yq-btn yq-rel-zoom-out" style="padding:4px 8px;font-size:16px;color:var(--yq-cyan);border-color:var(--yq-border);line-height:1">➖</button>';
  html += "</div>";
  html +=
    '<div id="yq-rel-container" style="overflow:hidden;cursor:grab;touch-action:none">';
  html +=
    '<div id="yq-rel-inner" style="transform-origin:0 0;transition:transform 0.2s">';
  html +=
    '<svg viewBox="0 0 ' +
    W +
    " " +
    H +
    '" style="width:100%;max-width:' +
    W +
    'px;margin:0 auto;display:block" xmlns="http://www.w3.org/2000/svg">';
  // 定义箭头marker
  html +=
    '<defs><marker id="yq-arrow" viewBox="0 0 10 7" refX="10" refY="3.5" markerWidth="8" markerHeight="6" orient="auto-start-reverse"><polygon points="0 0, 10 3.5, 0 7" fill="#9a98b0"/></marker></defs>';

  // 画连线
  for (var ei = 0; ei < edges.length; ei++) {
    var e = edges[ei];
    var nf = nodeMap[e.from],
      nt = nodeMap[e.to];
    if (!nf || !nt) continue;
    // 计算连线中点（用于放标签）
    var mx = (nf.x + nt.x) / 2,
      my = (nf.y + nt.y) / 2;
    // 缩短线段避免覆盖节点（节点半径约22px）
    var dx = nt.x - nf.x,
      dy = nt.y - nf.y;
    var dist = Math.sqrt(dx * dx + dy * dy) || 1;
    var ux = dx / dist,
      uy = dy / dist;
    var x1 = nf.x + ux * 26,
      y1 = nf.y + uy * 26;
    var x2 = nt.x - ux * 26,
      y2 = nt.y - uy * 26;
    html +=
      '<line x1="' +
      x1 +
      '" y1="' +
      y1 +
      '" x2="' +
      x2 +
      '" y2="' +
      y2 +
      '" stroke="' +
      e.color +
      '" stroke-width="1.5" marker-end="url(#yq-arrow)"/>';
    // 标签背景+文字
    html +=
      '<rect x="' +
      (mx - 22) +
      '" y="' +
      (my - 7) +
      '" width="44" height="14" rx="3" fill="#0e0e1a" fill-opacity="0.85"/>';
    html +=
      '<text x="' +
      mx +
      '" y="' +
      (my + 3) +
      '" text-anchor="middle" font-size="8" fill="#9a98b0" font-family="Microsoft YaHei,sans-serif">' +
      escHtml(e.label) +
      "</text>";
  }

  // 画节点（支持头像）
  for (var nj = 0; nj < nodes.length; nj++) {
    var nd = nodes[nj];
    var avatarSrc = getAvatar(nd.name);
    var clipId = "yq-clip-" + nj;
    // clipPath for circular avatar
    html +=
      '<defs><clipPath id="' +
      clipId +
      '"><circle cx="' +
      nd.x +
      '" cy="' +
      nd.y +
      '" r="19"/></clipPath></defs>';
    // 外圈光晕
    html +=
      '<circle cx="' +
      nd.x +
      '" cy="' +
      nd.y +
      '" r="24" fill="none" stroke="' +
      nd.c +
      '" stroke-width="1" opacity="0.3"/>';
    // 内圈背景
    html +=
      '<circle cx="' +
      nd.x +
      '" cy="' +
      nd.y +
      '" r="20" fill="#1a1a2e" stroke="' +
      nd.c +
      '" stroke-width="2"/>';
    if (avatarSrc) {
      // 有头像：用圆形裁剪的图片
      html +=
        '<image href="' +
        avatarSrc +
        '" x="' +
        (nd.x - 19) +
        '" y="' +
        (nd.y - 19) +
        '" width="38" height="38" clip-path="url(#' +
        clipId +
        ')" preserveAspectRatio="xMidYMid slice"/>';
    } else {
      // 无头像：姓氏文字
      var ch = (nd.name || "?").charAt(0);
      html +=
        '<text x="' +
        nd.x +
        '" y="' +
        (nd.y + 5) +
        '" text-anchor="middle" font-size="14" fill="' +
        nd.c +
        '" font-weight="700" font-family="Microsoft YaHei,sans-serif">' +
        escHtml(ch) +
        "</text>";
    }
    // 名字标签
    html +=
      '<text x="' +
      nd.x +
      '" y="' +
      (nd.y + 38) +
      '" text-anchor="middle" font-size="9" fill="' +
      nd.c +
      '" font-family="Microsoft YaHei,sans-serif">' +
      escHtml(nd.name) +
      "</text>";
    // 角色标签
    html +=
      '<text x="' +
      nd.x +
      '" y="' +
      (nd.y + 49) +
      '" text-anchor="middle" font-size="7" fill="#5a586e" font-family="Microsoft YaHei,sans-serif">' +
      escHtml(nd.r) +
      "</text>";
  }

  html += "</svg></div></div></div></div>";

  return html;
}

