  h +=
    '</div><div style="display:flex;gap:6px;margin-top:6px"><input id="yq-prof-nsfw-custom" style="flex:1;padding:4px 8px;font-size:11px;background:var(--yq-input);border:1px solid var(--yq-border);border-radius:4px;color:var(--yq-fg);outline:none" placeholder="自定义标签" maxlength="10"><button class="yq-btn yq-prof-add-tag" data-field="nsfw" style="padding:4px 10px;font-size:11px">+</button></div></div>';

  h += fieldBlock(
