  h += "</div>";
  return h;
}

function _yqShowProfileEditor() {
  var $overlay = $p('<div class="yq-overlay" id="yq-profile-overlay"></div>');
  var $modal = $p('<div class="yq-modal" style="max-width:480px"></div>');
  $modal.html(
    '<div style="font-size:16px;font-weight:700;color:var(--yq-cyan);margin-bottom:12px;letter-spacing:2px">\u270f\ufe0f 编辑人设偏好</div>' +
      _yqBuildProfileEditorModal(),
  );
  $overlay.append($modal);
  $p(_pd.body).append($overlay);

  $overlay.on("click", ".yq-prof-tag", function () {
    var $t = $p(this);
    var field = $t.attr("data-field");
    if (field === "personality") {
      if ($t.hasClass("yq-prof-sel")) {
        $t.removeClass("yq-prof-sel");
      } else {
        if ($overlay.find("#yq-prof-personality .yq-prof-sel").length >= 2)
          return;
        $t.addClass("yq-prof-sel");
      }
    } else {
      $t.toggleClass("yq-prof-sel");
    }
  });

  $overlay.on("click", ".yq-prof-add-tag", function () {
    var field = $p(this).attr("data-field");
    var $input = $overlay.find(
      field === "personality" ? "#yq-prof-p-custom" : "#yq-prof-nsfw-custom",
    );
    var val = ($input.val() || "").trim();
    if (!val) return;
    var $container = $overlay.find(
      field === "personality" ? "#yq-prof-personality" : "#yq-prof-nsfw",
    );
    var selClass = "";
    if (field === "personality") {
      selClass =
        $container.find(".yq-prof-sel").length < 2 ? " yq-prof-sel" : "";
    } else {
      selClass = " yq-prof-sel";
    }
    $container.append(
      '<span class="yq-btn yq-prof-tag' +
        selClass +
        '" data-field="' +
        field +
        '" data-val="' +
        escHtml(val) +
        '" style="padding:4px 10px;font-size:11px;border-radius:14px">' +
        escHtml(val) +
        "</span>",
    );
    $input.val("");
  });

  $overlay.on(
    "keydown",
    "#yq-prof-p-custom, #yq-prof-nsfw-custom",
    function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        $p(this).closest("div").find(".yq-prof-add-tag").trigger("click");
      }
    },
  );
  $overlay.on("click", ".yq-prof-cancel", function () {
    $overlay.remove();
  });
  $overlay.on("click", function (e) {
    if (e.target === $overlay[0]) $overlay.remove();
  });
  $overlay.on("click", ".yq-prof-save", function () {
    _yqSaveProfileFromModal($overlay);
  });
}

async function _yqSaveProfileFromModal($overlay) {
  var $btn = $overlay.find(".yq-prof-save");
  $btn.prop("disabled", true).text("保存中...");

