          var ch = getMeta("chat_history", {});
          if (ch[charName]) {
            delete ch[charName];
            setMeta("chat_history", ch);
          }
        } catch (e) {}

        // 8. phoneMeta: unreads
        try {
          var ur = getMeta("unreads", {});
          if (ur[charName]) {
            delete ur[charName];
            setMeta("unreads", ur);
          }
        } catch (e) {}

        // 9. phoneMeta: phone_char_appearance (角色形象)
        try {
          var pca = getMeta("phone_char_appearance", {});
          if (pca[charName]) {
            delete pca[charName];
            setMeta("phone_char_appearance", pca);
          }
        } catch (e) {}

        // 10. phoneMeta: yinqi_surveillance_targets (监控)
