    input.onchange = function (e) {
      var file = e.target.files[0];
      if (!file) return;
      var reader = new FileReader();
      reader.onload = function (ev) {
        try {
          var data = JSON.parse(ev.target.result);
          if (data.type !== "yinqi_tasks_v1") {
            _yqToast("error", "文件格式不正确");
            return;
          }
          var imported = 0;
          if (data.customPool && data.customPool.length > 0) {
            var pool = getMeta("yinqi_task_pool", []);
            var existIds = {};
            pool.forEach(function (t) {
              if (t.seedId) existIds[t.seedId] = true;
            });
            data.customPool.forEach(function (t) {
              if (!existIds[t.seedId || t.desc]) {
                pool.push(t);
                imported++;
              }
            });
            setMeta("yinqi_task_pool", pool);
          }
          saveMeta();
          refreshPanel();
          _yqToast("success", "导入成功：" + imported + "个任务");
        } catch (err) {
          _yqToast("error", "导入失败：" + err.message);
        }
      };
      reader.readAsText(file);
    };
    input.click();
  });

