  function updateDailyReward(idx) {
    var dailySlots = getMeta("yinqi_daily_slots", []);
    if (!dailySlots[idx]) return;
    var seed = dailySlots[idx];
    var $p2 = $p("#" + PANEL_ID);
    var executor =
      $p2.find('.yq-task-executor[data-idx="' + idx + '"]').val() || "林知意";
    var target =
      $p2.find('.yq-task-target[data-idx="' + idx + '"]').val() || "随机NPC";
    var mode =
      $p2.find('.yq-task-mode[data-idx="' + idx + '"]').val() || "solo_npc";
    if (mode === "user_replace") target = getUserName();
    var subCoeff = 0;
    $p2
      .find('.yq-sub-executor[data-idx="' + idx + '"]:checked')
      .each(function () {
        subCoeff += parseFloat($p(this).data("coeff")) || 0;
      });
    var reward = calculateReward(seed, executor, target, mode, subCoeff);
    $p2
      .find('.yq-task-reward[data-idx="' + idx + '"]')
      .text("预估: " + reward + "💠");
  }
