  // [V13·2026-06-01] 记忆自动召回快捷总开关
  // [V13.0.1·2026-06-01 修复] 用命名空间 + 先 off 再 on，防止 bindEvents 随 refreshPanel
  //   多次执行导致 handler 累积重复绑定（曾累积 6 个 → 点一次 toggle 被连环执行 6 次，
  //   开→关→弹开启框反复翻转，表现为"开关显示失效/点了没用"）。
  $p(_pd).off("click.yqrecalltoggle", "#yq-recall-toggle-btn");
  $p(_pd).on("click.yqrecalltoggle", "#yq-recall-toggle-btn", function (e) {
    e.stopPropagation();
    try {
      if (
        !(
          typeof _yqCore === "object" &&
          _yqCore &&
          _yqCore.recall &&
          typeof _yqCore.recall.getSettings === "function"
        )
      ) {
        _yqToast("warning", "召回模块未就绪，请稍后再试");
        return;
      }
      var cur = _yqCore.recall.getSettings();
      if (cur.masterEnabled) {
        // 当前开 → 直接关
        _yqCore.recall.setSettings({ masterEnabled: false });
        try {
          _yqCore.recall.refresh();
        } catch (_er) {}
        _yqToast("info", "🧠 记忆自动召回已关闭（数据库原生召回不受影响）");
        refreshPanel();
        return;
      }
      // 当前关 → 开启前弹提示确认
      var _msg =
        "开启面板「记忆自动召回」前请确认：\n\n" +
        "① 数据库已导入 V13 表格模板（含召回缓冲表 / 触发关键词列），否则通道2语义召回无数据。\n\n" +
        "② 建议在数据库 AutoCardUpdater 设置里关闭其原生『AI 主动召回 / recall』开关，避免与面板召回重复注入、浪费 token。\n\n" +
        "开启后状态会自动保存（存在本聊天存档里），关闭酒馆 / 切换聊天都不会重置。\n\n" +
        "确认开启？";
      if (typeof showCustomConfirm === "function") {
        showCustomConfirm({
          title: "🧠 开启记忆自动召回",
          message: _msg,
          confirmText: "确认开启",
          cancelText: "取消",
        }).then(function (ok) {
          if (!ok) return;
          _yqCore.recall.setSettings({ masterEnabled: true });
          try {
            _yqCore.recall.ensureHook();
          } catch (_eh) {}
          try {
            _yqCore.recall.refresh();
          } catch (_er2) {}
          _yqToast("success", "🧠 记忆自动召回已开启");
          refreshPanel();
        });
      } else {
        // 无确认弹窗时退化为直接开
        _yqCore.recall.setSettings({ masterEnabled: true });
        try {
          _yqCore.recall.ensureHook();
        } catch (_eh2) {}
        try {
          _yqCore.recall.refresh();
        } catch (_er3) {}
        _yqToast("success", "🧠 记忆自动召回已开启");
        refreshPanel();
      }
    } catch (_eToggle) {
      try {
        _yqToast("warning", "切换失败：" + (_eToggle && _eToggle.message));
      } catch (_) {}
    }
  });

