  // 关系网缩放拖动
  (function () {
    var scale = 1.0,
      panX = 0,
      panY = 0,
      dragging = false,
      startX = 0,
      startY = 0;
    function updateTransform() {
      var el = _pd.getElementById("yq-rel-inner");
      if (el)
        el.style.transform =
          "scale(" + scale + ") translate(" + panX + "px," + panY + "px)";
    }
    $panel.on("click", ".yq-rel-zoom-in", function () {
      scale = Math.min(2.0, scale + 0.2);
      updateTransform();
    });
    $panel.on("click", ".yq-rel-zoom-out", function () {
      scale = Math.max(0.4, scale - 0.2);
      updateTransform();
    });
    $panel.on("mousedown touchstart", "#yq-rel-container", function (e) {
      dragging = true;
      var ev =
        e.originalEvent && e.originalEvent.touches
          ? e.originalEvent.touches[0]
          : e;
      startX = ev.clientX - panX;
      startY = ev.clientY - panY;
    });
    // document 级监听：必须命名空间 + 先 off，否则 refreshPanel 重复绑定会泄漏
    $p(_pd).off(
      "mousemove.yqrellive touchmove.yqrellive mouseup.yqrellive touchend.yqrellive",
    );
    $p(_pd).on("mousemove.yqrellive touchmove.yqrellive", function (e) {
      if (!dragging) return;
      var ev =
        e.originalEvent && e.originalEvent.touches
          ? e.originalEvent.touches[0]
          : e;
      panX = ev.clientX - startX;
      panY = ev.clientY - startY;
      updateTransform();
    });
    $p(_pd).on("mouseup.yqrellive touchend.yqrellive", function () {
      dragging = false;
    });
  })();
}

// ==================== [V10.4] 撤回窗口清除（模块级，供 showBackpackModal 等外部函数调用） ====================
// 道具使用/装备/赠送后撤回按钮还能点 + 返还点数，但道具已消耗/分发导致刷点
// 在 使用/装备/赠送 入口立即调用，清除 sessionStorage 撤回令牌 + UI 回填"购买"按钮
function _yqConsumeShopBuyLock(itemName) {
  if (!itemName) return;
  try {
    sessionStorage.removeItem("_yqLastShopBuy_" + itemName);
  } catch (_eSS) {}
  // 同步回填 UI：已购×N ↩撤回 → 购买
  try {
    var $panel = $p("#" + PANEL_ID);
    var $undo = $panel.find('.yq-undo-buy[data-item-id="' + itemName + '"]');
    $undo.each(function () {
      var $b = $p(this);
      $b.text("购买")
        .removeClass("danger yq-undo-buy")
        .addClass("gold yq-buy-item");
      try {
        var $card = $b.closest(".yq-shop-item-card");
        var $lead = $card.find(".yq-shop-lead").first();
        var $tail = $card.find(".yq-shop-tail").first();
        $b.detach();
        $lead.empty();
        $tail.empty().append($b);
      } catch (_eSlot) {}
    });
  } catch (_eUI) {}
}

