  //   最终在 reward 公式末尾乘 (1 + _nsfwBonusTotal)
  var _nsfwBonusTotal = _calcNsfwRewardBonusForTask(
    executor,
    seed._subExecutors || [],
  );
  var _modeMap = {
    solo_npc: 1.0,
    user_replace: 0.5,
    user_watch: 1.2,
    user_join: 1.3,
