        msg += "• 但心理影响是真实的（羞耻感、记忆、情感变化）\n";
        msg += "• 请AI按照梦境场景演绎任务过程，不要写【梦境结束】\n";
        msg += "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n";
      }

      // 记忆棱镜特殊说明
      var hasMemCrystal = selectedItems.some(function (item) {
        return item.indexOf("记忆棱镜") !== -1;
      });
      if (hasMemCrystal && seed.st !== "memory") {
        msg += "\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n";
        msg += "【重要】玩家选择使用记忆棱镜执行此任务\n";
        msg += "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n";
        msg += "• 任务将通过潜入他人记忆进行，执行者以记忆主体的第一视角体验\n";
        msg += "• 记忆中的事件是过去真实发生的，但执行者只是观察者无法改变\n";
        msg += "• 主角可以旁观但不能干涉记忆内容\n";
        msg += "• 请AI在描述开头标注[记忆主体:角色名]\n";
        msg += "• 请AI明确标注这是记忆场景，不是当前现实\n";
        msg += "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n";
      }
    }

    $p("#yq-accept-overlay").remove();
    sendMessage(msg);
    // 如果是剧情任务，删除临时数据
    if (seed._source === "plot") {
      setMeta("yinqi_plot_task", null);
    }
    saveMeta();
    refreshPanel();
    // 通知手机UI刷新任务面板
    try {
      var iframes = _pd.querySelectorAll("iframe");
      for (var fi = 0; fi < iframes.length; fi++) {
        try {
          var fw = iframes[fi].contentWindow;
          if (fw && typeof fw.generateTaskPanel === "function") {
            // 如果手机UI的任务面板正在显示，触发刷新
            var $taskBody =
              fw.document && fw.document.getElementById("phone-app-body");
            if ($taskBody) $taskBody.innerHTML = fw.generateTaskPanel();
          }
        } catch (e) {}
      }
    } catch (e) {}
  });
}

// ==================== 背包辅助函数 ====================
function _buildBackpackItems(groups, inv, userEquip, tabId) {
  var gItems = groups[tabId] || [];
  if (gItems.length === 0) {
    return '<div class="yq-empty">该分类暂无物品</div>';
  }

  var tabLabels = {
    wpn: "🗡️ 武器",
    arm: "🛡️ 防具",
    spc: "✨ 特殊",
    abl: "⚡ 能力",
    skl: "🎯 技能",
    fac: "🔧 器械",
    csm: "💊 消耗",
    pet: "🐾 宠物",
  };
  var tabColors = {
    wpn: "var(--yq-red)",
    arm: "var(--yq-green)",
    spc: "var(--yq-cyan)",
    abl: "var(--yq-purple)",
    skl: "var(--yq-gold)",
    fac: "var(--yq-rose)",
    csm: "var(--yq-dim)",
    pet: "var(--yq-green)",
  };

  var gc = tabColors[tabId] || "var(--yq-dim)";
  var html = '<div style="margin-bottom:12px">';
  html +=
    '<div style="font-size:12px;font-weight:700;color:' +
    gc +
    ';margin-bottom:6px;padding-left:2px">' +
    (tabLabels[tabId] || tabId) +
    ' <span style="font-size:10px;color:var(--yq-muted)">(' +
    gItems.length +
    ")</span></div>";

  for (var ii = 0; ii < gItems.length; ii++) {
    var k = gItems[ii];
    var item = inv[k];
    // [V10.3 FIX] 防御：使用消耗品后 inv[k] 可能已被 delete，但 groups 数组未同步
    //   tab click handler 改为每次重读 meta + 重建 groups（见下方），此处再加一道兜底
    if (!item) continue;
    var info = getItemInfo(k);
    var itemType = getItemType(k);
    // [V10.1 FIX] 装备判断：由于装备时已从 inventory 减 qty，
    // 背包列表中出现的同名道具都是未装备的副本，不标记"装备中"。
    // 装备状态已通过头部"当前装备"区域展示。
    var isEquipped = false;
    var cpMatch = (info.desc || "").match(/(?:攻击|战斗力|CP)\+(\d+)/i);
    var defMatch = (info.desc || "").match(/(?:防御|DEF)\+(\d+)/i);
    // 判断是否为重要剧情道具
    var isPlotItem =
      k === "命运偏转符" ||
      k === "基因锚定剂" ||
      k === "丧尸咬伤解毒剂" ||
      k === "丧尸驱避剂";
    var nameStyle = isPlotItem
      ? "font-size:14px;font-weight:700;color:#FFD700;text-shadow:0 0 4px rgba(255,215,0,0.4);overflow:hidden;text-overflow:ellipsis;white-space:nowrap"
      : "font-size:14px;font-weight:700;color:var(--yq-fg);overflow:hidden;text-overflow:ellipsis;white-space:nowrap";

    html +=
      '<div class="yq-card" data-item-name="' +
      escHtml(k) +
      '" style="padding:10px 14px;margin-bottom:6px;border-left:3px solid ' +
      gc +
      ';cursor:pointer" title="点击卡片查看详情">';
    html +=
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">';
    html +=
      '<div style="display:flex;align-items:center;gap:8px;flex:1;min-width:0">';
    html +=
      '<span style="' + nameStyle + '">' + escHtml(info.name || k) + "</span>";
    if ((item.qty || 1) > 1)
      html +=
        '<span class="yq-item-qty" style="font-size:11px;color:var(--yq-gold);font-weight:600">×' +
        item.qty +
        "</span>";
    if (isEquipped)
      html +=
        '<span style="font-size:10px;color:var(--yq-cyan);background:rgba(0,240,255,0.12);padding:1px 6px;border-radius:3px;font-weight:700">装备中</span>';
    html += "</div>";
    if (cpMatch || defMatch) {
      html += '<div style="display:flex;gap:4px;flex-shrink:0">';
      if (cpMatch)
        html +=
          '<span style="font-size:10px;color:var(--yq-red);background:rgba(255,64,96,0.12);padding:1px 6px;border-radius:3px;font-weight:700">⚔️' +
          cpMatch[1] +
          "</span>";
      if (defMatch)
        html +=
          '<span style="font-size:10px;color:var(--yq-green);background:rgba(76,255,136,0.12);padding:1px 6px;border-radius:3px;font-weight:700">🛡️' +
          defMatch[1] +
          "</span>";
      html += "</div>";
    }
    html += "</div>";
    // [V8] 折叠详情:默认隐藏 desc,点"ℹ 详情"按钮本地 toggle(不走 refreshPanel,保持展开状态)
    html +=
      '<div class="yq-item-desc" style="display:none;font-size:12px;color:var(--yq-dim);margin-bottom:8px;line-height:1.5">' +
      escHtml(_getPlayerVisibleDesc(info.desc) || "无描述") +
      "</div>";
    html +=
      '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">';
    // [V8] 详情切换按钮(所有道具都有,样式低调)
    html +=
      '<button class="yq-btn yq-bp-toggle-desc" style="padding:2px 8px;font-size:10px;color:var(--yq-muted);border-color:var(--yq-border);background:rgba(255,255,255,0.02)" title="查看道具说明">ℹ 详情</button>';

    // [V2/§4] v2 身边人道具优先显示"使用"按钮（按 v2Group 分流）
    // [V10.9·2026-05-18] 移除 v2 类的"🎁 赠予"按钮 — 因为：
    //   1. v2_skill 已有"装备到角色"（弹窗选目标），赠予冗余
    //   2. v2_general/male/female 已有"给他人使用"语义，赠予冗余
    //   3. v2_linzhiyi 只能对林知意，赠予无意义
    //   4. v2_consume 已是消耗品给他人使用流程，赠予无意义
    //   5. 赠予路径 showGiftModal 对 v2 类道具存在 BUG（itemType 分支不全）— 玩家反馈
    if (info.v2Group) {
      var _v2Label = "使用";
      if (info.v2Group === "v2_consume") _v2Label = "🤝 给他人使用";
      else if (info.v2Group === "v2_skill") _v2Label = "⚡ 装备到角色";
      else if (info.v2Group === "v2_linzhiyi") _v2Label = "💞 对林知意使用";
      else _v2Label = "🤝 给他人使用"; // v2_general / v2_male / v2_female
      html +=
        '<button class="yq-btn primary yq-bp-use-v2" data-item="' +
        escHtml(k) +
        '" data-v2-group="' +
        escHtml(info.v2Group) +
        '" style="padding:3px 10px;font-size:11px">' +
        _v2Label +
        "</button>";
      // [V10.9] v2 类移除赠予按钮（避免 BUG + 语义冗余）
    } else if (info.v5Group) {
      // [V5/§5] 变性玩法道具使用按钮
      var _v5Label = "使用";
      if (info.v5Group === "v5_female_flip") _v5Label = "⚠ 永久变女";
      else if (info.v5Group === "v5_succubus") _v5Label = "激活魅魔";
      else if (info.v5Group === "v5_revert") _v5Label = "⚠ 恢复男性";
      else if (info.v5Group === "v5_futanari") _v5Label = "开启双性";
      html +=
        '<button class="yq-btn primary yq-bp-use-v5" data-item="' +
        escHtml(k) +
        '" data-v5-group="' +
        escHtml(info.v5Group) +
        '" style="padding:3px 10px;font-size:11px;color:#ff9800;border-color:rgba(255,152,0,0.3)">' +
        _v5Label +
        "</button>";
      // [V10.10·2026-05-18] V5 道具移除"🎁 赠予"按钮
      //   理由：V5 是主角变性玩法专属（变女 / 魅魔 / 恢复男性 / 双性），
      //         接收方 NPC 无法激活这些能力，赠予无意义且 showGiftModal 漏写 v5 字段会触发 BUG
    } else if (info.v6Group) {
      // [V6/§6] 暗攻略检测道具使用按钮
      var _v6Label = "使用";
      if (info.v6Group === "v6_antidote") _v6Label = "💊 对女性使用";
      else _v6Label = "📡 查看说明";
      html +=
        '<button class="yq-btn primary yq-bp-use-v6" data-item="' +
        escHtml(k) +
        '" data-v6-group="' +
        escHtml(info.v6Group) +
        '" style="padding:3px 10px;font-size:11px;color:#ff79c6;border-color:rgba(255,121,198,0.3)">' +
        _v6Label +
        "</button>";
      // [V10.10·2026-05-18] V6 道具移除"🎁 赠予"按钮
      //   理由：V6 是暗攻略检测玩法专属（觉醒解咒剂仅对已被暗攻略的女性使用 / 监控升级永久性购买即生效），
      //         赠予 NPC 无意义且 showGiftModal 漏写 v6 字段会触发 BUG
    } else if (
      itemType === "weapon" ||
      itemType === "armor" ||
      itemType === "equipment" ||
      itemType === "special" ||
      itemType === "pet"
    ) {
      // [V10.10·2026-05-18] 银麒次元贞操环改造方案：
      //   1. 主角背包按钮："🔮 装备/赠予" → "🎁 赠予到对方背包"
      //      点击 → 弹窗选 NPC → 道具进入对方背包（不直接装备，不弹传送目标）
      //   2. 装备状态从 chatMetadata.yinqi_portal_settings 迁到 stat_data.{charPath}._portal
      //      (object: { target, detail } | null)
      //   3. NPC 背包模态框（_showCharBagModal）显示：
      //      - 已装备 _portal → 顶部虚拟卡片"已装备 [传送→XX]" + 改目标/卸下按钮
      //      - 背包里有贞操环 → 普通卡片 + "🔮 佩戴+设传送目标"按钮
      //   4. AI 路径：通过 JSONPatch 直接写 _portal 字段（守卫 §9.5 自动管理背包扣减）
      //   5. 老存档兼容：启动时迁移 yinqi_portal_settings → _portal
      //   6. 已赠予 tab 数据源改为扫所有 _portal 字段
      if (k === "银麒次元贞操环") {
        html +=
          '<button class="yq-btn gold yq-bp-portal-gift" data-item="' +
          escHtml(k) +
          '" style="padding:3px 10px;font-size:11px">🎁 赠予到对方背包</button>';
      } else if (isEquipped) {
        html +=
          '<button class="yq-btn danger yq-bp-unequip" data-item="' +
          escHtml(k) +
          '" data-type="' +
          itemType +
          '" style="padding:3px 10px;font-size:11px">' +
          (itemType === "pet" ? "收回" : "卸下") +
          "</button>";
      } else {
        html +=
          '<button class="yq-btn primary yq-bp-equip" data-item="' +
          escHtml(k) +
          '" data-type="' +
          itemType +
          '" data-desc="' +
          escHtml(info.desc || "") +
          '" style="padding:3px 10px;font-size:11px">' +
          (itemType === "pet" ? "召唤" : "装备") +
          "</button>";
      }
      // [V11.3·2026-05-20] 宠物可赠予（赠予后自动召唤，归对方所有）
      // [V10.4 BugB] 贞操环已在上面早 return 渲染，此分支不再走
      if (k !== "银麒次元贞操环") {
        html +=
          '<button class="yq-btn gold yq-bp-gift" data-item="' +
          escHtml(k) +
          '" data-type="' +
          itemType +
          '" data-desc="' +
          escHtml(info.desc || "") +
          '" style="padding:3px 10px;font-size:11px">🎁 赠予</button>';
      }
    } else if (itemType === "enhance") {
      // [V10.9·2026-05-18] enhance 类两按钮："🧪 自己使用" + "🤝 给他人使用"
      //   主角自己使用 → 走 yq-bp-use-enhance（已有 handler，写入 user._abilities + user.能力）
      //   给他人使用 → 走 yq-bp-use-other-ability（新 handler，写入对方 _abilities + .能力）
      //   特殊道具（基因锚定剂 / 7 个身体改造道具）保持原状走 yq-bp-use-enhance 内的特殊分支
      // 移除"🎁 赠予"按钮（避免 showGiftModal BUG + 语义冗余）
      html +=
        '<button class="yq-btn primary yq-bp-use-enhance" data-item="' +
        escHtml(k) +
        '" data-desc="' +
        escHtml(info.desc || "") +
        '" style="padding:3px 10px;font-size:11px">🧪 自己使用</button>';
      html +=
        '<button class="yq-btn primary yq-bp-use-other-ability" data-item="' +
        escHtml(k) +
        '" data-desc="' +
        escHtml(info.desc || "") +
        '" style="padding:3px 10px;font-size:11px;color:#9f7aea;border-color:rgba(159,122,234,0.4)">🤝 给他人使用</button>';
    } else if (itemType === "skill") {
      // [V10.9·2026-05-18] skill 类（无 v2Group 传统技能，如影分身术）两按钮
      //   设计：技能写入面板 _skills 数组（中文名直接 push，_yqGetSkillLabel fallback 显示中文）
      //   自己使用 → 写入 user._skills + 注入消息
      //   给他人使用 → 写入对方 _skills + 注入消息
      // 移除"🎁 赠予"按钮（避免 showGiftModal BUG + 语义冗余）
      html +=
        '<button class="yq-btn primary yq-bp-use-skill-self" data-item="' +
        escHtml(k) +
        '" data-desc="' +
        escHtml(info.desc || "") +
        '" style="padding:3px 10px;font-size:11px">🧪 自己使用</button>';
      html +=
        '<button class="yq-btn primary yq-bp-use-skill-other" data-item="' +
        escHtml(k) +
        '" data-desc="' +
        escHtml(info.desc || "") +
        '" style="padding:3px 10px;font-size:11px;color:#9f7aea;border-color:rgba(159,122,234,0.4)">🤝 给他人使用</button>';
    } else if (itemType === "consumable" || itemType === "facility") {
      html +=
        '<button class="yq-btn primary yq-bp-use" data-item="' +
        escHtml(k) +
        '" style="padding:3px 10px;font-size:11px">使用</button>';
      html +=
        '<button class="yq-btn gold yq-bp-gift" data-item="' +
        escHtml(k) +
        '" data-type="' +
        itemType +
        '" data-desc="' +
        escHtml(info.desc || "") +
        '" style="padding:3px 10px;font-size:11px">🎁 赠予</button>';
    } else {
      html +=
        '<button class="yq-btn primary yq-bp-use" data-item="' +
        escHtml(k) +
        '" style="padding:3px 10px;font-size:11px">使用</button>';
      html +=
        '<button class="yq-btn gold yq-bp-gift" data-item="' +
        escHtml(k) +
        '" data-type="' +
        itemType +
        '" data-desc="' +
        escHtml(info.desc || "") +
        '" style="padding:3px 10px;font-size:11px">🎁 赠予</button>';
    }
    html +=
      '<button class="yq-btn yq-bp-display" data-item="' +
      escHtml(k) +
      '" data-desc="' +
      escHtml(info.desc || "") +
      '" data-lv="' +
      (info.level || 1) +
      '" style="padding:3px 10px;font-size:11px;color:var(--yq-gold);border-color:rgba(240,200,96,0.3)">👁 展示</button>';
    html += "</div></div>";
  }
  html += "</div>";
  return html;
}

function _buildGiftedItems() {
  // [V10.10·2026-05-18] 数据源从 chatMetadata.yinqi_portal_settings 改为扫描所有角色的 _portal 字段
  //   兼容老存档：_migratePortalSettings 在初始化时已迁移，此处只读 stat_data
  var giftedList = [];
  var d = null;
  try {
    d = getAllData() || {};
  } catch (_) {
    d = {};
  }
  // 1. 林知意
  try {
    var lzPortal = (d.角色 && d.角色.林知意 && d.角色.林知意._portal) || null;
    if (lzPortal && typeof lzPortal === "object" && lzPortal.target) {
      giftedList.push({
        char: "林知意",
        path: "角色.林知意",
        target: lzPortal.target,
        detail: lzPortal.detail || "",
      });
    }
  } catch (_) {}
  // 2. 所有女性 NPC
  try {
    var fc = d.女性角色 || {};
    for (var fn in fc) {
      if (!fc.hasOwnProperty(fn) || fn === "林知意") continue;
      var p = fc[fn] && fc[fn]._portal;
      if (p && typeof p === "object" && p.target) {
        giftedList.push({
          char: fn,
          path: "女性角色." + fn,
          target: p.target,
          detail: p.detail || "",
        });
      }
    }
  } catch (_) {}
  // 3. 变性女主（user._portal）
  try {
    if (
      d.user &&
      d.user._portal &&
      typeof d.user._portal === "object" &&
      d.user._portal.target
    ) {
      giftedList.push({
        char: getUserName() || "主角",
        path: "user",
        target: d.user._portal.target,
        detail: d.user._portal.detail || "",
      });
    }
  } catch (_) {}

  // [V11.3·2026-05-20] 扫描已赠予的宠物（所有非 user 角色的 _pet）
  var giftedPets = [];
  try {
    var _lzPet = (d.角色 && d.角色.林知意 && d.角色.林知意._pet) || null;
    if (_lzPet)
      giftedPets.push({ char: "林知意", path: "角色.林知意", pet: _lzPet });
    var _gfc = d.女性角色 || {};
    for (var _gfn in _gfc) {
      if (!_gfc.hasOwnProperty(_gfn) || _gfn === "林知意") continue;
      if (_gfc[_gfn] && _gfc[_gfn]._pet)
        giftedPets.push({
          char: _gfn,
          path: "女性角色." + _gfn,
          pet: _gfc[_gfn]._pet,
        });
    }
    var _gmc = d.男性角色 || {};
    for (var _gmn in _gmc) {
      if (!_gmc.hasOwnProperty(_gmn)) continue;
      if (_gmc[_gmn] && _gmc[_gmn]._pet)
        giftedPets.push({
          char: _gmn,
