      "疤痕瑕疵消除液",
      "体型重塑药浴",
      "胸部精密重塑液",
      "逆龄精华·5年",
      "完美体型重塑仪",
      "银麒·造物重铸",
    ];
    if (_bodyModItemsGift.indexOf(itemName) !== -1) {
      _handleBodyMod(itemName);
      return;
    }
    // 获取道具等级和分类
    var itemLv = 1;
    var itemCat = "csm";
    var allItems = [];
    var cats = ["wpn", "arm", "spc", "abl", "skl", "fac", "csm", "pet"];
    for (var ci = 0; ci < cats.length; ci++)
      for (var li = 1; li <= 6; li++) {
        var catItems = getShopItemsByCatAndLevel(cats[ci], li);
        for (var ai = 0; ai < catItems.length; ai++) {
          if (catItems[ai].name === itemName) {
            itemLv = catItems[ai].level;
            itemCat = cats[ci];
          }
        }
      }
    // fallback: 查自定义道具
    if (itemCat === "etc") {
      var _custItems = getMeta("yinqi_custom_items", []);
      for (var _gi = 0; _gi < _custItems.length; _gi++) {
        if (_custItems[_gi].name === itemName) {
          itemLv = Number(_custItems[_gi].level) || 1;
          itemCat = _custItems[_gi].category || "etc";
          break;
        }
      }
    }
    // 系统道具和其他道具不检查使用权，武器/防具/能力检查
    var needsCheck =
      itemCat === "wpn" || itemCat === "arm" || itemCat === "abl";
    var eligible;
    if (needsCheck) {
      eligible = getEligibleCharacters(itemLv);
      if (eligible.length === 0) {
        _yqToast("warning", "没有角色满足LV" + itemLv + "道具的使用权条件");
