      var mc = d2.男性角色 || {};
      for (var mn in mc) {
        if (mc.hasOwnProperty(mn))
          eligible.push({ name: mn, type: "male", done: "-", needed: "-" });
      }
    }
    showGiftModal(itemName, itemType, itemDesc, itemLv, eligible);
