// [V10.10] 老存档迁移：yinqi_portal_settings → stat_data._portal
//   首次加载时执行，写入 yinqi_portal_migrated 标记防重复
//   [V10.10 HOTFIX·2026-05-18] 迁移完成后清空 yinqi_portal_settings —
//     防止 _buildEquipOverview / _buildGiftedItems 等读到老数据回流，
//     造成"卸下后装备栏仍显示"BUG。
function _migratePortalSettings() {
  try {
    if (getMeta("yinqi_portal_migrated", false)) return;
    var oldSettings = getMeta("yinqi_portal_settings", {});
    if (!oldSettings || typeof oldSettings !== "object") {
      setMeta("yinqi_portal_migrated", true);
      // 即便没有老数据，也清空一下避免后续误用
      setMeta("yinqi_portal_settings", {});
      saveMeta();
      return;
    }
    var d = getAllData() || {};
    var migratedCount = 0;
    for (var charName in oldSettings) {
      var s = oldSettings[charName];
      if (!s || !s.equipped) continue;
      var prefix = null;
      if (charName === "林知意") prefix = "角色.林知意";
      else if (d.女性角色 && d.女性角色[charName])
        prefix = "女性角色." + charName;
      else if (charName === getUserName()) prefix = "user";
      if (!prefix) continue;
      var existing = getVar(prefix + "._portal");
      if (!existing || typeof existing !== "object") {
        setVar(prefix + "._portal", {
          target: s.target || "默认",
          detail: s.detail || "",
        });
        migratedCount++;
      }
    }
    setMeta("yinqi_portal_migrated", true);
    // [V10.10 HOTFIX] 清空老数据，防止数据源混乱
    setMeta("yinqi_portal_settings", {});
    saveMeta();
    if (migratedCount > 0) {
      try {
        if (typeof console !== "undefined")
          console.log(
            "[V10.10] 贞操环装备状态迁移完成：" + migratedCount + " 个角色",
          );
      } catch (_) {}
    }
  } catch (e) {
    try {
      console.warn("[V10.10] _migratePortalSettings 异常:", e);
    } catch (_) {}
  }
}

