    '<button class="yq-btn primary" id="yq-display-confirm">确认展示</button>';
  html += "</div></div></div>";

  $p(_pd.body).append(html);
  $p("#yq-display-cancel, #yq-display-overlay").on("click", function (e) {
    if (e.target === this) $p("#yq-display-overlay").remove();
  });

  $p("#yq-display-confirm").on("click", function () {
    var target = ($p("#yq-display-target").val() || "").trim();
    var note = ($p("#yq-display-note").val() || "").trim();
    var persuadeMode = $p("#yq-display-persuade").val() || "free";
    var persuadeLabels = {
      free: "自由发挥",
      org: "虚构借口隐瞒",
      truth: "坦白系统真相",
      custom: "自定义",
    };
    var persuadeText = "";
    if (persuadeMode === "custom" && note) persuadeText = "说服方式：" + note;
    else if (persuadeMode !== "free")
      persuadeText =
        "说服方式：" + (persuadeLabels[persuadeMode] || persuadeMode);

    var msg = "";
    if (type === "task") {
      msg +=
        "【任务展示】{{user}}决定把几个任务选项展示给角色，让对方自己选择。\n";
      msg += "展示对象：" + (target || "由{{user}}自行判断展示给谁") + "\n\n";
      msg += "任务选项：\n";
      for (var ti = 0; ti < items.length; ti++) {
        var _dChain = items[ti].chainId
          ? " 🔗" +
            (items[ti].chainTitle || "连环") +
            " " +
            (items[ti].chainStep || 0) +
            "/" +
            (items[ti].chainTotal || 0)
          : "";
        msg +=
          ti +
          1 +
          ". [" +
          items[ti].level +
          "]" +
          _dChain +
          " " +
          _getAiVisibleDesc(items[ti].desc) +
          " | 奖励" +
          items[ti].reward +
          "\n";
      }
    } else if (type === "shop") {
      msg += "【商城展示】{{user}}决定把一些可用物资信息展示给角色。\n";
      msg += "展示对象：" + (target || "由{{user}}自行判断展示给谁") + "\n\n";
      msg += "商品列表：\n";
      for (var si = 0; si < items.length; si++) {
        msg +=
          si +
          1 +
          ". " +
          items[si].name +
          " [LV" +
          items[si].level +
          "] " +
          items[si].price +
          "💠 — " +
          _getAiVisibleDesc(items[si].desc) +
          "\n";
      }
    } else {
      msg += "【道具展示】{{user}}决定把一件道具展示给角色。\n";
      msg += "展示对象：" + (target || "由{{user}}自行判断展示给谁") + "\n";
      msg += "道具：" + items[0].name + " [LV" + items[0].level + "]\n";
      msg += "描述：" + _getAiVisibleDesc(items[0].desc) + "\n";
    }
    if (note && persuadeMode !== "custom") msg += "\n玩家备注：" + note;
    if (persuadeText) msg += "\n" + persuadeText;

    $p("#yq-display-overlay").remove();
    $p("#yq-bp-overlay").remove();
    sendMessage(msg);
    _yqToast("success", typeLabel + "已展示");
  });
}

// ==================== [V9.6 P3·2026-05-10] 身体改造道具使用 ====================
// 弹窗：选择目标角色（主角/林知意/所有女/所有男）+ 填参数（胸型/体型/体态）
// 写入位置：
//   1. chatMetadata.yinqi_phone.yinqi_body_mods[角色名]  — 世界书 EJS 读取真源
//   2. MVU 对应字段（若存在）：
//      - 主角女体/双性态的胸部状态（`user.胸部状态`）
//      - 女性/场景角色详情的身体状态.胸部状态
function _handleBodyMod(itemName) {
  var d = getAllData();
  var userName = getUserName();

  // [V10.4·2026-05-13] 身体改造弹窗打开时立即清除撤回窗口
  //   防止玩家改造完成后回头撤回购买还点数（道具已经用在目标身体上了）
  try {
    _yqConsumeShopBuyLock(itemName);
  } catch (_eBodyLock) {}

  // [V9.6 P3++·2026-05-10] 目标列表只显示当前在场角色
  //   玩家反馈：不在场角色不应可选，避免对不存在的 NPC 做改造操作
  //   主角：永远在场（是玩家本人）
  //   林知意：按"是否在当前场景里最近被提到"判断（不再硬编码永远在场）
  //   其他角色：必须出现在 stat_data.当前场景角色 或 场景角色详情 中
  var _sceneChars = d.当前场景角色 || {};
  var _sceneDetails = d.场景角色详情 || {};
  function _isOnSite(name) {
    if (!name) return false;
    return !!(_sceneChars[name] || _sceneDetails[name]);
  }
  // 林知意特殊：[V9.6 P3+++] 女主角可远程改造（银麒系统远程注入能力），不受在场限制
  var _lzOnSite = true;

  // 收集可选目标列表
  var targets = [];
  // [V9.6 P3+·2026-05-10] 主角 key 用 metaName（优先）或 getUserName（兜底）
  //   保持与玩家角色世界书 EJS 的 key 顺序一致，避免读写错位
  var _userKey = "";
  try {
    _userKey = getVar("user.metaName") || "";
  } catch (_eUK) {}
  if (!_userKey) _userKey = getUserName() || "{{user}}";
  targets.push({
    name: _userKey,
    tag: "主角（本人）",
    _ref: "user",
    key: _userKey,
  });
  if (_lzOnSite) {
    targets.push({
      name: "林知意",
      tag: "女主·远程可用",
      _ref: "角色.林知意",
      key: "林知意",
    });
  }
  var femChars = d.女性角色 || {};
  var femNames = Object.keys(femChars);
  for (var _fi = 0; _fi < femNames.length; _fi++) {
    if (!_isOnSite(femNames[_fi])) continue;
    targets.push({
      name: femNames[_fi],
      tag: "女性·在场",
      _ref: "女性角色." + femNames[_fi],
      key: femNames[_fi],
    });
  }
  var maleChars = d.男性角色 || {};
  var maleNames = Object.keys(maleChars);
  for (var _mi = 0; _mi < maleNames.length; _mi++) {
    if (!_isOnSite(maleNames[_mi])) continue;
    targets.push({
      name: maleNames[_mi],
      tag: "男性·在场",
      _ref: "男性角色." + maleNames[_mi],
      key: maleNames[_mi],
    });
  }
  // 场景角色详情里的 NPC（不在女性/男性角色 record 里的，一般是临时 NPC）
  try {
    var _scKeys = Object.keys(_sceneDetails);
    for (var _si = 0; _si < _scKeys.length; _si++) {
      var _sn = _scKeys[_si];
      if (_sn === "林知意" || _sn === "{{user}}" || _sn === userName) continue;
      if (femChars[_sn] || maleChars[_sn]) continue;
      targets.push({
        name: _sn,
        tag: "场景NPC·在场",
        _ref: "场景角色详情." + _sn,
        key: _sn,
      });
    }
  } catch (_eSc) {}

  // 如果只剩主角和林知意两个候选，给玩家提示一下（避免玩家疑惑为什么 XX 不见了）
  if (targets.length <= 2) {
    // 不中断，只提示
    try {
      _yqToast("info", "仅主角和林知意在场。对其他角色改造需等其进入当前场景");
    } catch (_eToast) {}
  }

  // 构建选择弹窗 HTML
  var html =
    '<div class="yq-overlay" id="yq-bodymod-overlay" style="z-index:100000">';
  html += '<div class="yq-modal" style="max-width:480px">';
  html +=
    '<h3 style="margin:0 0 10px">🧬 身体改造 · <span style="color:var(--yq-gold)">' +
    escHtml(itemName) +
    "</span></h3>";
  html +=
    '<div style="font-size:.78rem;color:var(--yq-dim);margin-bottom:12px">选择改造目标：</div>';
  html +=
    '<div style="max-height:240px;overflow:auto;margin-bottom:10px;padding:4px;background:rgba(0,0,0,0.15);border-radius:6px">';
  for (var _ti = 0; _ti < targets.length; _ti++) {
    var t = targets[_ti];
    var tagColor =
      t._ref === "user"
        ? "var(--yq-gold)"
        : t.key === "林知意"
          ? "var(--yq-rose)"
          : t.tag.indexOf("女性") === 0
            ? "var(--yq-cyan)"
            : "var(--yq-dim)";
    html +=
      '<div class="yq-bodymod-target" data-key="' +
      escHtml(t.key) +
      '" data-ref="' +
      escHtml(t._ref) +
      '" data-tag="' +
      escHtml(t.tag) +
      '" style="padding:6px 10px;margin:3px 0;border-radius:4px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;background:rgba(30,35,55,0.6);border:1px solid var(--yq-border)">';
    html +=
      '<span style="font-size:.85rem;color:var(--yq-fg)">' +
      escHtml(t.name) +
      "</span>";
    html +=
      '<span style="font-size:.68rem;color:' +
      tagColor +
      '">【' +
      escHtml(t.tag) +
      "】</span>";
    html += "</div>";
  }
  html += "</div>";
  html +=
    '<div id="yq-bodymod-params" style="display:none;margin-bottom:10px"></div>';
  html += '<div style="display:flex;gap:8px;justify-content:flex-end">';
  html +=
    '<button class="yq-btn" id="yq-bodymod-cancel" style="padding:6px 14px">取消</button>';
  html +=
    '<button class="yq-btn primary" id="yq-bodymod-confirm" style="padding:6px 14px;display:none">确认使用</button>';
  html += "</div>";
  html += "</div></div>";

  $p(_pd).find("#yq-bodymod-overlay").remove();
  $p(_pd.body).append(html);

  var _selected = null;

  // 目标点击
  $p(_pd).on(
    "click.yqbm",
    "#yq-bodymod-overlay .yq-bodymod-target",
    function () {
      $p("#yq-bodymod-overlay .yq-bodymod-target").css("border-color", "");
      $p(this).css("border-color", "var(--yq-gold)");
      _selected = {
        key: $p(this).data("key"),
        ref: $p(this).data("ref"),
        tag: $p(this).data("tag"),
      };
      // 决定是否需要参数输入
      _renderBodyModParams(itemName, _selected);
      $p("#yq-bodymod-confirm").show();
    },
  );

  // 取消
  $p(_pd).on("click.yqbm", "#yq-bodymod-cancel", function () {
    $p("#yq-bodymod-overlay").remove();
    $p(_pd).off("click.yqbm");
  });

  // 确认
  $p(_pd).on("click.yqbm", "#yq-bodymod-confirm", function () {
    if (!_selected) {
      _yqToast("warning", "请先选择目标");
      return;
    }
    var paramsObj = _collectBodyModParams(itemName);
    _applyBodyMod(itemName, _selected, paramsObj);
    $p("#yq-bodymod-overlay").remove();
    $p(_pd).off("click.yqbm");
  });
}

// 根据道具类型决定要不要渲染参数输入
// [V9.6 P3+·2026-05-10] 新增：显示目标的旧改造值、在场状态、操作提示
function _renderBodyModParams(itemName, target) {
  var $box = $p("#yq-bodymod-params");
  $box.empty().hide();

  // 读取目标的现有改造记录（供覆盖前展示）
  var _prev = null;
  try {
    var ctx = (window.parent || window).SillyTavern.getContext();
    var _mods =
      (ctx.chatMetadata &&
        ctx.chatMetadata.yinqi_phone &&
        ctx.chatMetadata.yinqi_phone.yinqi_body_mods) ||
      {};
    _prev = _mods[target.key] || null;
  } catch (_ePrev) {}

  // 检查目标是否在场（主角/林知意总是在场；其他角色已经过滤过）
  var _onSite = true;
  var _onSiteNote = "";
  try {
    var d = getAllData();
    var userName = getUserName();
    if (target.key === userName || target.ref === "user") {
      _onSiteNote = "主角本人（改造后 AI 当轮即可承接）";
    } else if (target.key === "林知意") {
      _onSiteNote = "女主（常驻场景，改造后 AI 当轮即可承接）";
    } else {
      _onSiteNote = "当前在场（改造后 AI 当轮即可承接剧情演绎）";
    }
  } catch (_eSite) {}

  // 构建参数区 HTML
  var html = "";

  // 在场状态提示
  var _siteColor = _onSite ? "var(--yq-cyan)" : "var(--yq-gold)";
  html +=
    '<div style="font-size:.72rem;color:' +
    _siteColor +
    ';margin-bottom:6px;padding:4px 6px;background:rgba(0,0,0,0.2);border-radius:4px">' +
    escHtml(_onSiteNote) +
    "</div>";

  // 显示现有改造记录（累加型 / 覆盖型都显示）
  if (_prev) {
    var _prevLines = [];
    if (_prev.beauty) _prevLines.push("容貌 +" + _prev.beauty + "%");
    if (_prev.scars_cleared) _prevLines.push("疤痕已清除");
    if (_prev.age_adjust && Number(_prev.age_adjust) < 0)
      _prevLines.push("年龄 " + Number(_prev.age_adjust) + " 岁");
    if (_prev.breast_cup) _prevLines.push("胸型：" + _prev.breast_cup);
    if (_prev.body_reshape) _prevLines.push("体型：" + _prev.body_reshape);
    if (_prev.tone_params) _prevLines.push("完美参数：" + _prev.tone_params);
    if (_prev.custom_notes) _prevLines.push("重铸：" + _prev.custom_notes);
    if (_prevLines.length > 0) {
      html +=
        '<div style="font-size:.72rem;color:var(--yq-dim);margin-bottom:6px;padding:4px 6px;background:rgba(0,0,0,0.2);border-radius:4px">当前改造记录：' +
        escHtml(_prevLines.join("；")) +
        "</div>";
    }
  }

  var needsParams = false;
  var oldHint = function (fieldName) {
    var v = _prev && _prev[fieldName];
    return v ? "（旧值：" + String(v).slice(0, 50) + " — 将被覆盖）" : "";
  };

  if (itemName === "胸部精密重塑液") {
    needsParams = true;
    html +=
      '<label style="font-size:.78rem;color:var(--yq-fg);display:block;margin-bottom:4px">胸型参数（D杯 / 圆润挺翘 / 小巧可爱）' +
      escHtml(oldHint("breast_cup")) +
      "：</label>";
    html +=
      '<input type="text" id="yq-bm-breast" value="' +
      escHtml((_prev && _prev.breast_cup) || "") +
      '" placeholder="D杯，自然下垂" style="width:100%;padding:6px;background:rgba(0,0,0,0.3);border:1px solid var(--yq-border);color:var(--yq-fg);border-radius:4px">';
  } else if (itemName === "体型重塑药浴") {
    needsParams = true;
    html +=
      '<label style="font-size:.78rem;color:var(--yq-fg);display:block;margin-bottom:4px">体型参数（纤细型 / 丰满型 / 运动型）' +
      escHtml(oldHint("body_reshape")) +
      "：</label>";
    html +=
      '<input type="text" id="yq-bm-body" value="' +
      escHtml((_prev && _prev.body_reshape) || "") +
      '" placeholder="纤细型：腰臀比 0.7，腿部修长" style="width:100%;padding:6px;background:rgba(0,0,0,0.3);border:1px solid var(--yq-border);color:var(--yq-fg);border-radius:4px">';
  } else if (itemName === "完美体型重塑仪") {
    needsParams = true;
    html +=
      '<label style="font-size:.78rem;color:var(--yq-fg);display:block;margin-bottom:4px">完美体态参数' +
      escHtml(oldHint("tone_params")) +
      "：</label>";
    html +=
      '<input type="text" id="yq-bm-tone" value="' +
      escHtml((_prev && _prev.tone_params) || "") +
      '" placeholder="身高165cm 体重48kg BWH 88/58/90 肌肤细腻白皙" style="width:100%;padding:6px;background:rgba(0,0,0,0.3);border:1px solid var(--yq-border);color:var(--yq-fg);border-radius:4px">';
  } else if (itemName === "银麒·造物重铸") {
    needsParams = true;
    html +=
      '<label style="font-size:.78rem;color:var(--yq-fg);display:block;margin-bottom:4px">重铸方向' +
      escHtml(oldHint("custom_notes")) +
      "：</label>";
    html +=
      '<textarea id="yq-bm-rebuild" rows="3" placeholder="示例：胸围从B杯升到E杯，腰细化为 58cm，皮肤调整为白嫩，五官保留但去除所有瑕疵" style="width:100%;padding:6px;background:rgba(0,0,0,0.3);border:1px solid var(--yq-border);color:var(--yq-fg);border-radius:4px;resize:vertical">' +
      escHtml((_prev && _prev.custom_notes) || "") +
      "</textarea>";
  }
  // 累加型道具（颜值/疤痕/年龄）——不需要参数，但显示操作预览
  if (!needsParams) {
    var _opLabel = "";
    if (itemName === "容貌优化精华") {
      var _newBeauty = (Number(_prev && _prev.beauty) || 0) + 15;
      _opLabel = "容貌将 +15%（累计 " + _newBeauty + "%）";
    } else if (itemName === "疤痕瑕疵消除液") {
      _opLabel =
        _prev && _prev.scars_cleared
          ? "疤痕已清除（重复使用无额外效果）"
          : "将清除目标全身疤痕瑕疵";
    } else if (itemName === "逆龄精华·5年") {
      var _newAge = (Number(_prev && _prev.age_adjust) || 0) - 5;
      _opLabel = "年龄将逆转 5 岁（累计 " + Math.abs(_newAge) + " 岁）";
    }
    if (_opLabel) {
      html +=
        '<div style="font-size:.78rem;color:var(--yq-cyan);padding:6px;background:rgba(0,240,255,0.08);border-radius:4px">' +
        escHtml(_opLabel) +
        "</div>";
    }
  }

  $box.html(html).show();
}

function _collectBodyModParams(itemName) {
  var obj = {};
  if (itemName === "胸部精密重塑液")
    obj.breast_cup = $p("#yq-bm-breast").val() || "";
  else if (itemName === "体型重塑药浴")
    obj.body_reshape = $p("#yq-bm-body").val() || "";
  else if (itemName === "完美体型重塑仪")
    obj.tone_params = $p("#yq-bm-tone").val() || "";
  else if (itemName === "银麒·造物重铸")
    obj.custom_notes = $p("#yq-bm-rebuild").val() || "";
  return obj;
}

// 核心写入函数
function _applyBodyMod(itemName, target, params) {
  // 1. 扣库存
  var inv = getMeta("yinqi_inventory", {});
  if (inv[itemName]) {
    inv[itemName].qty = (inv[itemName].qty || 1) - 1;
    if (inv[itemName].qty <= 0) delete inv[itemName];
    setMeta("yinqi_inventory", inv);
  }
  // [V11.8.10·P0-1 fix·2026-05-27] 同步扣 stat_data.user.背包(双源一致性)
  //   原 BUG: _applyBodyMod 只扣 inv,user.背包 仍含此 body mod 道具
  //   修复: 同步扣 user.背包,确保 AI 看不到已用掉的改造道具
  try {
    var _bpBM = (getAllData().user && getAllData().user.背包) || {};
    if (_bpBM[itemName]) {
      var _bmQty = (_bpBM[itemName].数量 || 1) - 1;
      if (_bmQty <= 0) setVar(_yqBagPath(itemName), undefined);
      else setVar(_yqBagPath(itemName, "数量"), _bmQty);
    }
  } catch (_eBM) {}

  var actionLabel = "";

  // 2. 写 chatMetadata.yinqi_phone.yinqi_body_mods[target.key]
  try {
    var ctx = (window.parent || window).SillyTavern.getContext();
    if (!ctx.chatMetadata.yinqi_phone) ctx.chatMetadata.yinqi_phone = {};
    if (!ctx.chatMetadata.yinqi_phone.yinqi_body_mods)
      ctx.chatMetadata.yinqi_phone.yinqi_body_mods = {};
    var mods = ctx.chatMetadata.yinqi_phone.yinqi_body_mods;
    if (!mods[target.key]) mods[target.key] = { history: [] };
    var slot = mods[target.key];

    if (itemName === "容貌优化精华") {
      slot.beauty = (Number(slot.beauty) || 0) + 15;
      actionLabel = "容貌 +15%（累计 " + slot.beauty + "%）";
    } else if (itemName === "疤痕瑕疵消除液") {
      slot.scars_cleared = true;
      actionLabel = "疤痕瑕疵已清除";
    } else if (itemName === "逆龄精华·5年") {
      slot.age_adjust = (Number(slot.age_adjust) || 0) - 5;
      actionLabel =
        "年龄逆转 5 岁（累计 " + Math.abs(slot.age_adjust) + " 岁）";
    } else if (itemName === "胸部精密重塑液") {
      slot.breast_cup = params.breast_cup || slot.breast_cup || "";
      actionLabel = "胸型重塑为：" + slot.breast_cup;
    } else if (itemName === "体型重塑药浴") {
      slot.body_reshape = params.body_reshape || slot.body_reshape || "";
      actionLabel = "体型重塑为：" + slot.body_reshape;
    } else if (itemName === "完美体型重塑仪") {
      slot.tone_params = params.tone_params || slot.tone_params || "";
      actionLabel = "完美体态参数：" + slot.tone_params;
    } else if (itemName === "银麒·造物重铸") {
      slot.custom_notes = params.custom_notes || "";
      actionLabel = "基因级重铸：" + slot.custom_notes;
    }

    if (!Array.isArray(slot.history)) slot.history = [];
    slot.history.push({
      item: itemName,
      at: Date.now(),
      detail: actionLabel,
    });
    // 历史最多保留 20 条
    if (slot.history.length > 20) slot.history = slot.history.slice(-20);

    ctx.saveMetadata();

    // 3. 同步 MVU（对已有字段）
    //   策略：用正则定位 `（银麒改造：...）` 已有标记 → 有则替换，无则追加
    function _updateChestField(path, cupParam) {
      var cur = getVar(path) || "";
      var mark = "（银麒改造：" + cupParam + "）";
      var re = /（银麒改造：[^）]*）/g;
      if (re.test(cur)) {
        setVar(path, cur.replace(re, mark));
      } else {
        setVar(path, (cur || "") + mark);
      }
    }
    try {
      // 胸型：如果 schema 里有对应字段，同步
      //   主角：user.胸部状态（仅 female/futanari）
      //   女性/场景角色：女性角色.{name}.身体状态.胸部状态 / 场景角色详情.{name}.身体状态.胸部状态
      if (
        itemName === "胸部精密重塑液" &&
        params.breast_cup &&
        target.ref === "user"
      ) {
        var uGender = getVar("user.gender") || "male";
        if (uGender !== "male") {
          _updateChestField("user.胸部状态", params.breast_cup);
        }
      } else if (
        itemName === "胸部精密重塑液" &&
        params.breast_cup &&
        target.ref.indexOf("女性角色.") === 0
      ) {
        _updateChestField(target.ref + ".身体状态.胸部状态", params.breast_cup);
      } else if (
        itemName === "胸部精密重塑液" &&
        params.breast_cup &&
        target.ref.indexOf("场景角色详情.") === 0
      ) {
        _updateChestField(target.ref + ".身体状态.胸部状态", params.breast_cup);
      }
    } catch (_eMvu) {}
  } catch (_eMod) {
    _yqToast("error", "写入失败：" + (_eMod.message || _eMod));
    return;
  }

  saveMeta();
  updateGuardSnapshot();
  // [V9.6 P3++] 目标已在入口过滤为仅在场角色，此处不再需要"不在场提示"
  _injectSystemMessage(
    "[系统操作] {{user}}对" +
      target.key +
      "使用了「" +
      itemName +
      "」，" +
      (actionLabel || "已写入银麒改造记录"),
  );
  try {
    _yqCore.taskFlow.appendOperationLog("body_mod_use", {
      item: itemName,
      target: target.key,
      detail: actionLabel,
    });
  } catch (_eLog) {}
  _yqBpInPlaceRefresh(itemName);
  refreshPanel();
  _yqToast("success", target.key + " · " + (actionLabel || itemName));
}

// ==================== 丧尸化防护道具使用 ====================
function _handleUseProtection(itemName) {
  var isAnchor = itemName === "基因锚定剂";
  var abilityTag = isAnchor ? "免疫丧尸化" : "命运偏转(免疫一次随机丧尸化)";
  // 收集可选角色（自己+所有已知角色）
  var d = getAllData();
  var candidates = [
    { name: (getUserName() || "主角") + "（自己）", key: "user", isSelf: true },
  ];
  // 林知意
  candidates.push({
    name: "林知意",
    key: "角色.林知意",
    isSelf: false,
    isFem: true,
    isLzy: true,
  });
  // 女性角色
  var fc = d.女性角色 || {};
  for (var fn in fc) {
    if (fc.hasOwnProperty(fn))
      candidates.push({
        name: fn,
        key: "女性角色." + fn,
        isSelf: false,
        isFem: true,
      });
  }
  // 男性角色
  var mc = d.男性角色 || {};
  for (var mn in mc) {
    if (mc.hasOwnProperty(mn))
      candidates.push({
        name: mn,
        key: "男性角色." + mn,
        isSelf: false,
        isFem: false,
      });
  }

  // 过滤已有该能力的角色
  var filtered = candidates.filter(function (c) {
    var curAbility;
    if (c.isSelf) curAbility = (d.user || {}).能力 || "无";
    else if (c.isLzy)
      curAbility = "无"; // 林知意没有独立能力字段，用女性角色record
    else {
      var charData = c.isFem
        ? (d.女性角色 || {})[c.name]
        : (d.男性角色 || {})[c.name];
      curAbility = (charData || {}).能力 || "无";
    }
    if (isAnchor && curAbility.indexOf("免疫丧尸化") >= 0) return false;
    if (!isAnchor && curAbility.indexOf("命运偏转") >= 0) return false;
    return true;
  });

  if (filtered.length === 0) {
    _yqToast("info", "所有角色都已拥有该防护");
    return;
  }

  var html = '<div class="yq-overlay" id="yq-protect-overlay">';
  html += '<div class="yq-modal">';
  html += "<h3>🛡️ " + escHtml(itemName) + " — 选择目标</h3>";
  html +=
    '<div style="font-size:12px;color:var(--yq-dim);margin-bottom:12px">' +
    (isAnchor
      ? "永久免疫丧尸化（含被咬+随机选中）"
      : "免疫一次随机丧尸化选中（不防被咬）") +
    "</div>";
  for (var ci = 0; ci < filtered.length; ci++) {
    var c = filtered[ci];
    html +=
      '<button class="yq-btn yq-protect-pick" data-name="' +
      escHtml(c.name) +
      '" data-key="' +
      escHtml(c.key) +
      '" data-self="' +
      (c.isSelf ? "1" : "0") +
      '" style="display:block;width:100%;text-align:left;padding:10px 14px;margin-bottom:6px;color:var(--yq-fg);border-color:var(--yq-border);font-size:13px">';
    html += "👤 " + escHtml(c.name);
    html += "</button>";
  }
  html +=
    '<div style="margin-top:12px;text-align:right"><button class="yq-btn danger" id="yq-protect-cancel" style="padding:6px 16px">取消</button></div>';
  html += "</div></div>";

  $p(_pd.body).append(html);
  $p("#yq-protect-cancel, #yq-protect-overlay").on("click", function (e) {
    if (e.target === this) $p("#yq-protect-overlay").remove();
  });
  // 先解绑旧的事件（避免重复绑定）
  $p(_pd).off("click.protect");
  // 使用命名空间绑定新事件
  $p(_pd).on(
    "click.protect",
    "#yq-protect-overlay .yq-protect-pick",
    function (e) {
      e.stopPropagation();
      var name = $p(this).data("name");
      var key = $p(this).data("key");
      var isSelf = $p(this).data("self") === "1";
      // 消耗道具
      var inv = getMeta("yinqi_inventory", {});
      if (inv[itemName]) {
        inv[itemName].qty = (inv[itemName].qty || 1) - 1;
        if (inv[itemName].qty <= 0) delete inv[itemName];
        setMeta("yinqi_inventory", inv);
        saveMeta();
      }
      // 同步MVU背包
      try {
        var _bpProt = (getAllData().user && getAllData().user.背包) || {};
        if (_bpProt[itemName]) {
          var _pQty = (_bpProt[itemName].数量 || 1) - 1;
          if (_pQty <= 0) setVar(_yqBagPath(itemName), undefined);
          else setVar(_yqBagPath(itemName, "数量"), _pQty);
        }
      } catch (e) {}
      // 写入能力字段
      var abilityEntry = itemName + "(" + abilityTag + ")";
      if (isSelf) {
        var curAbility = getVar("user.能力") || "无";
        if (curAbility === "无") setVar("user.能力", abilityEntry);
        else setVar("user.能力", curAbility + "/" + abilityEntry);
        // [V11.8.10·能力槽同步 fix·2026-05-27] 写 user._abilities 数组
        //   原 BUG: _handleUseProtection 只写字符串字段,玩家面板"管理"看不到这条能力,无法主动清除
        //   修复: 同步 push 到 _abilities 数组(用道具中文名),让管理 modal 列出
        try {
          var _ablU = getVar("user._abilities") || [];
          if (!Array.isArray(_ablU)) _ablU = [];
          if (_ablU.indexOf(itemName) < 0 && _ablU.length < 5) {
            _ablU.push(itemName);
            setVar("user._abilities", _ablU);
          }
        } catch (_eAblU) {}
        updateGuardSnapshot();
      } else {
        var curAbility2 = getVar(key + ".能力") || "无";
        if (curAbility2 === "无") setVar(key + ".能力", abilityEntry);
        else setVar(key + ".能力", curAbility2 + "/" + abilityEntry);
        // [V11.8.10·能力槽同步 fix] 同步写对方 _abilities 数组
        try {
          var _ablT = getVar(key + "._abilities") || [];
          if (!Array.isArray(_ablT)) _ablT = [];
          if (_ablT.indexOf(itemName) < 0 && _ablT.length < 5) {
            _ablT.push(itemName);
            setVar(key + "._abilities", _ablT);
          }
        } catch (_eAblT) {}
      }
      // 通知主AI
      var targetDisplay = isSelf ? "自己" : name;
      _injectSystemMessage(
        "[系统操作] {{user}}对" +
          targetDisplay +
          "使用了" +
          itemName +
          "。" +
          targetDisplay +
          "获得" +
          abilityTag +
          "能力，AI在后续剧情中该角色不会被丧尸化感染。",
      );
      $p("#yq-protect-overlay").remove();
      _yqBpInPlaceRefresh(itemName);
      refreshPanel();
      _yqToast(
        "success",
        targetDisplay +
          " 已获得" +
          (isAnchor ? "永久丧尸化免疫" : "一次丧尸化免疫"),
      );
    },
  );
}

// ==================== 纳米监控使用 ====================
var SURV_MAX = 10; // 最大监控目标数

function _getSurvTargets() {
  var raw = getMeta("yinqi_surveillance_targets", []);
  return Array.isArray(raw) ? raw : [];
}
function _setSurvTargets(targets) {
  setMeta("yinqi_surveillance_targets", targets);
  saveMeta();
}

function _handleUseSurveillance() {
  var targets = _getSurvTargets();
  if (targets.length >= SURV_MAX) {
    _yqToast(
      "warning",
      "监控目标已达上限（" + SURV_MAX + "个），请先移除再添加",
    );
    return;
  }
  // 收集可选角色（排除已监控的）
  var d = getAllData();
  var monitored = {};
  for (var ti = 0; ti < targets.length; ti++)
    monitored[targets[ti].name] = true;
  var candidates = [];
  // 女性角色
  var fc = d.女性角色 || {};
  for (var fn in fc) {
    if (fc.hasOwnProperty(fn) && !monitored[fn]) candidates.push(fn);
  }
  // 男性角色
  var mc = d.男性角色 || {};
  for (var mn in mc) {
    if (mc.hasOwnProperty(mn) && !monitored[mn]) candidates.push(mn);
  }
  // 林知意
  if (!monitored["林知意"]) candidates.unshift("林知意");

  if (candidates.length === 0) {
    _yqToast("info", "没有可监控的新角色");
    return;
  }

  // 弹出选择弹窗
  var html = '<div class="yq-overlay" id="yq-surv-overlay">';
  html += '<div class="yq-modal">';
  html += "<h3>📡 纳米监控 — 选择目标</h3>";
  html +=
    '<div style="font-size:12px;color:var(--yq-dim);margin-bottom:12px">已监控 ' +
    targets.length +
    "/" +
    SURV_MAX +
    "，选择一个角色植入纳米监控（消耗1个）</div>";
  for (var ci = 0; ci < candidates.length; ci++) {
    html +=
      '<button class="yq-btn yq-surv-pick" data-name="' +
      escHtml(candidates[ci]) +
      '" style="display:block;width:100%;text-align:left;padding:10px 14px;margin-bottom:6px;color:var(--yq-fg);border-color:var(--yq-border);font-size:13px">';
    html += "👤 " + escHtml(candidates[ci]);
    html += "</button>";
  }
  html +=
    '<div style="margin-top:12px;text-align:right"><button class="yq-btn danger" id="yq-surv-cancel" style="padding:6px 16px">取消</button></div>';
  html += "</div></div>";

  $p(_pd.body).append(html);
  $p("#yq-surv-cancel, #yq-surv-overlay").on("click", function (e) {
    if (e.target === this) $p("#yq-surv-overlay").remove();
  });
  $p(_pd).off("click.yqsurv");
  $p(_pd).on("click.yqsurv", "#yq-surv-overlay .yq-surv-pick", function (e) {
    e.stopPropagation();
    var name = $p(this).data("name");
    if (!name) return;
    // 消耗道具
    var inv = getMeta("yinqi_inventory", {});
    if (inv["纳米监控"]) {
      inv["纳米监控"].qty = (inv["纳米监控"].qty || 1) - 1;
      if (inv["纳米监控"].qty <= 0) delete inv["纳米监控"];
      setMeta("yinqi_inventory", inv);
    }
    // 同步MVU背包
    try {
      var _bpSurv = (getAllData().user && getAllData().user.背包) || {};
      if (_bpSurv["纳米监控"]) {
        var _sQty = (_bpSurv["纳米监控"].数量 || 1) - 1;
        if (_sQty <= 0) setVar("user.背包.纳米监控", undefined);
        else setVar("user.背包.纳米监控.数量", _sQty);
      }
    } catch (e) {}
    // 添加监控目标（防重复）
    var tgts = _getSurvTargets();
    if (
      tgts.some(function (t) {
        return (t.name || t) === name;
      })
    ) {
      _yqToast("warning", "该角色已在监控列表中");
      $p("#yq-surv-overlay").remove();
      return;
    }
    tgts.push({ name: name, time: Date.now() });
    _setSurvTargets(tgts);
    // 在MVU中初始化监控字段
    // 先确保监控对象存在
    var survObj = getVar("银麒系统.监控");
    if (!survObj || typeof survObj !== "object") {
      setVar("银麒系统.监控", {});
    }
    setVar("银麒系统.监控." + name, "刚被植入纳米监控，等待数据同步...");
    updateGuardSnapshot();
    // 通知主AI
    _injectSystemMessage(
      "[系统操作] {{user}}对「" +
        name +
        "」使用了纳米监控，该角色的一切动态将被实时监控。AI每轮必须在 银麒系统.监控." +
        name +
        " 中更新该角色的当前状态（一句话15-30字）。",
    );
    $p("#yq-surv-overlay").remove();
    _yqBpInPlaceRefresh("纳米监控");
    refreshPanel();
    _yqToast("success", "已对「" + name + "」植入纳米监控");
  });
}

// ==================== 堕落清洗仪使用 ====================
function _handleUseCorruptionWash() {
  var d = getAllData();
  // 收集可选角色：林知意 + 所有女性角色（攻略度>0的）
  var candidates = [];
  var lzyCorr = Number(((d.角色 || {}).林知意 || {}).攻略度) || 0;
  candidates.push({
    name: "林知意",
    corruption: lzyCorr,
    key: "角色.林知意.攻略度",
  });
