  for (var fn in fc) {
    if (fc.hasOwnProperty(fn)) {
      var corr = Number(fc[fn].攻略度) || 0;
      candidates.push({
        name: fn,
        corruption: corr,
        key: "女性角色." + fn + ".攻略度",
      });
