  var html = '<div class="yq-overlay" id="yq-corr-overlay">';
  html += '<div class="yq-modal" style="max-width:380px">';
  html +=
    '<h3>🧹 堕落清洗仪 — 选择目标 <button class="yq-btn danger" style="float:right;padding:2px 8px" id="yq-corr-close">关闭</button></h3>';
  html +=
    '<div style="font-size:12px;color:var(--yq-dim);margin-bottom:12px">选择角色并调整攻略度（±20范围，由面板直接修改）</div>';
  for (var ci = 0; ci < candidates.length; ci++) {
    var c = candidates[ci];
    html += '<div class="yq-card" style="padding:10px 12px;margin-bottom:6px">';
    html +=
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">';
    html +=
      '<span style="font-size:13px;font-weight:700;color:var(--yq-rose)">👤 ' +
      escHtml(c.name) +
      "</span>";
    html +=
      '<span style="font-size:12px;color:var(--yq-dim)">当前攻略度: <span style="color:var(--yq-mag)">' +
      c.corruption +
      "</span></span>";
    html += "</div>";
    html += '<div style="display:flex;gap:6px;justify-content:center">';
    html +=
      '<button class="yq-btn danger yq-corr-adjust" data-name="' +
      escHtml(c.name) +
      '" data-key="' +
      escHtml(c.key) +
      '" data-cur="' +
      c.corruption +
      '" data-delta="-20" style="padding:4px 14px;font-size:12px">-20</button>';
    html +=
      '<button class="yq-btn danger yq-corr-adjust" data-name="' +
      escHtml(c.name) +
      '" data-key="' +
      escHtml(c.key) +
      '" data-cur="' +
      c.corruption +
      '" data-delta="-10" style="padding:4px 14px;font-size:12px">-10</button>';
    html +=
      '<button class="yq-btn gold yq-corr-adjust" data-name="' +
      escHtml(c.name) +
      '" data-key="' +
      escHtml(c.key) +
      '" data-cur="' +
      c.corruption +
      '" data-delta="10" style="padding:4px 14px;font-size:12px">+10</button>';
    html +=
      '<button class="yq-btn gold yq-corr-adjust" data-name="' +
      escHtml(c.name) +
      '" data-key="' +
      escHtml(c.key) +
      '" data-cur="' +
      c.corruption +
      '" data-delta="20" style="padding:4px 14px;font-size:12px">+20</button>';
    html += "</div></div>";
  }
  html += "</div></div>";

  $p(_pd.body).append(html);
  $p("#yq-corr-close, #yq-corr-overlay").on("click", function (e) {
    if (e.target === this) $p("#yq-corr-overlay").remove();
  });
  // 先解绑旧的事件（避免重复绑定）
  $p(_pd).off("click.corrWash");
  // 使用命名空间绑定新事件
  $p(_pd).on(
    "click.corrWash",
    "#yq-corr-overlay .yq-corr-adjust",
    function (e) {
      e.stopPropagation();
      var name = $p(this).data("name");
      var key = $p(this).data("key");
      var cur = Number($p(this).data("cur"));
      var delta = Number($p(this).data("delta"));
      var newVal = Math.max(0, Math.min(100, cur + delta));
      // 消耗道具
      var inv = getMeta("yinqi_inventory", {});
      if (inv["堕落清洗仪"]) {
        inv["堕落清洗仪"].qty = (inv["堕落清洗仪"].qty || 1) - 1;
        if (inv["堕落清洗仪"].qty <= 0) delete inv["堕落清洗仪"];
        setMeta("yinqi_inventory", inv);
      }
      try {
        var _bpCW = (getAllData().user && getAllData().user.背包) || {};
        if (_bpCW["堕落清洗仪"]) {
          var _cwQ = (_bpCW["堕落清洗仪"].数量 || 1) - 1;
          if (_cwQ <= 0) setVar("user.背包.堕落清洗仪", undefined);
          else setVar("user.背包.堕落清洗仪.数量", _cwQ);
        }
      } catch (e2) {}
      // 直接修改MVU攻略度
      setVar(key, newVal);
      saveMeta();
      _injectSystemMessage(
        "[系统操作] {{user}}对「" +
          name +
          "」使用了堕落清洗仪，攻略度从" +
          cur +
          "调整为" +
          newVal +
          "（" +
          (delta > 0 ? "+" : "") +
          delta +
          "）",
      );
      $p("#yq-corr-overlay").remove();
      _yqBpInPlaceRefresh(itemName);
      refreshPanel();
      _yqToast("success", name + " 攻略度: " + cur + " → " + newVal);
    },
  );
}

// ==================== 丧尸化逆转针使用 ====================
function _handleUseZombieReverse() {
  var d = getAllData();
  var sceneChars = d.场景角色详情 || {};
  var candidates = [];
  for (var sn in sceneChars) {
    if (!sceneChars.hasOwnProperty(sn)) continue;
    var sc = sceneChars[sn];
    // 检查身体状态或当前情绪中是否含"丧尸"关键词
    var stStr = JSON.stringify(sc);
    if (stStr.indexOf("丧尸") >= 0) {
      candidates.push({
        name: sn,
        status: (sc.身体状态 && sc.身体状态.鸡巴状态) || "丧尸",
      });
    }
  }
  if (candidates.length === 0) {
    _yqToast("warning", "当前场景中没有丧尸角色");
    return;
  }
  var html = '<div class="yq-overlay" id="yq-zombie-overlay">';
  html += '<div class="yq-modal" style="max-width:380px">';
  html +=
