// 获取物品类型
/**
 * [V6.1 FIX BUG-2] 通过商城真实分类反查道具所属 cat（sys/wpn/arm/abl/etc）
 * 先走扁平缓存 `getShopItemsByCatAndLevel._allFlat`（含 category），找不到再 fallback
 * 返回值是商城分类字符串，与 `_buildBackpackItems` 的 `typeMapping` 输出对齐
 */
function _getShopCategoryByName(name) {
  try {
    if (!name) return null;
    var allFlat = getShopItemsByCatAndLevel._allFlat;
    if (!allFlat) {
      // 主动构建扁平缓存（与 getItemInfo 的构建口径一致）
      var allCats = ["wpn", "arm", "spc", "abl", "skl", "fac", "csm", "pet"];
      allFlat = [];
      for (var ai = 0; ai < allCats.length; ai++) {
        for (var lv = 1; lv <= 6; lv++) {
          var items = getShopItemsByCatAndLevel(allCats[ai], lv);
          for (var j = 0; j < items.length; j++) {
            // [V10.10 HOTFIX·2026-05-18] 显式记录"所在数组的 cat"作为反查真源
            //   原 bug：item.category="plot"（剧情道具元数据）覆盖了实际所在数组的 cat（spc）
            //   导致命运偏转符 inv 写入 cat=plot → 背包分类找不到 plot → fallback 到 csm（消耗）
            //   修复：用 _arrayCat 字段记录实际所在数组分类，反查时优先返回它
            items[j]._arrayCat = allCats[ai];
            if (!items[j].category) items[j].category = allCats[ai];
            allFlat.push(items[j]);
          }
        }
      }
      getShopItemsByCatAndLevel._allFlat = allFlat;
    }
    for (var i = 0; i < allFlat.length; i++) {
      if (allFlat[i].name === name) {
        // [V10.10 HOTFIX] 优先返回数组实际分类，category 字段仅作为元数据（如 plot 标记）
        return allFlat[i]._arrayCat || allFlat[i].category || null;
      }
    }
    // fallback: 自定义道具 category（yinqi_custom_items）
    try {
      var _cust = getMeta("yinqi_custom_items", []);
      for (var ci = 0; ci < _cust.length; ci++) {
        if (_cust[ci].name === name) return _cust[ci].category || null;
      }
    } catch (_) {}
    return null;
  } catch (_) {
    return null;
  }
}

// [V10.1 UX] 背包原地刷新辅助：使用/装备/召唤道具后，移除对应卡片或更新数量，不关闭背包
function _yqBpInPlaceRefresh(itemName) {
  try {
    var $overlay = $p("#yq-bp-overlay");
    if (!$overlay.length) return;
    var $card = $overlay.find('.yq-card[data-item-name="' + itemName + '"]');
    if ($card.length) {
      var _newQty = 0;
      try {
        var _inv = getMeta("yinqi_inventory", {});
        _newQty = (_inv[itemName] || {}).qty || 0;
      } catch (_e) {}
      if (_newQty <= 0) {
        $card.fadeOut(200, function () {
          $p(this).remove();
        });
      } else {
        $card.find(".yq-item-qty").text("×" + _newQty);
      }
    } else {
      // 卡片未找到（可能是 data-item-name 不匹配），fallback 重新触发 tab
      var $activeTab = $overlay.find(".yq-bp-tab.active");
      if ($activeTab.length) $activeTab.trigger("click");
    }
  } catch (_e) {
    // 最终 fallback：关闭背包
    try {
      $p("#yq-bp-overlay").remove();
    } catch (_) {}
  }
}

function getItemType(name) {
  // [V10.1 fix] 优先通过商城反查获取真实分类，避免硬编码 map 与商城数据不同步
  var catTypeMap = {
    wpn: "weapon",
    arm: "armor",
    spc: "special",
    abl: "enhance",
    skl: "skill",
    fac: "facility",
    csm: "consumable",
    pet: "pet",
  };
  try {
    var shopCat = _getShopCategoryByName(name);
    if (shopCat && catTypeMap[shopCat]) return catTypeMap[shopCat];
  } catch (_) {}
  // fallback: 消耗品
  return "consumable";
}

// 使用权检查
function getEligibleCharacters(itemLevel) {
  var history = getMeta("yinqi_task_history", []);
  var d = getAllData();
  var femChars = d.女性角色 || {};
  var maleChars = d.男性角色 || {};
  var rankOrder = ["D", "C", "B", "A", "S", "X"];
  var lvToRank = { 1: "D", 2: "C", 3: "B", 4: "A", 5: "S", 6: "X" };
  var targetRankIdx = rankOrder.indexOf(lvToRank[itemLevel] || "D");

  function countExec(name) {
    var c = 0;
    for (var i = 0; i < history.length; i++) {
      var h = history[i];
      if (h.executor === name && h.grade !== "失败") {
        var ri = rankOrder.indexOf((h.level || "D级").charAt(0));
        if (ri >= targetRankIdx) c++;
      }
    }
    return c;
  }
  function countTarget(name) {
    var c = 0;
    for (var i = 0; i < history.length; i++) {
      var h = history[i];
      if (h.target === name && h.grade !== "失败") {
        var ri = rankOrder.indexOf((h.level || "D级").charAt(0));
        if (ri >= targetRankIdx) c++;
      }
    }
    return c;
  }

  var eligible = [];
  var motherNames = ["苏曼", "沈若兰"];
  // [V11.4·2026-05-24·玩家反馈修复] 林知意永远可选（女主作为永久绑定执行者，
  // 不需要任务历史门槛——开局玩家想用能力道具/特殊装备给她加 buff 的需求合理）
  var zhiyiDone = countExec("林知意");
  eligible.push({
    name: "林知意",
    type: "female",
    done: zhiyiDone,
    needed: 0, // needed=0 表示无门槛
  });
  for (var fn in femChars) {
    if (fn === "林知意") continue; // 林知意已在上方单独处理
    var fc = femChars[fn];
    var hadSex = fc.已与user性交 === true || fc.已与user性交 === "true";
    var aff = Number(fc.好感度) || 0;
    var needed;
    if (fn === "林知意") needed = 0;
    else if (motherNames.indexOf(fn) !== -1 || hadSex || aff >= 90) needed = 2;
    else if (aff >= 60) needed = 3;
    else if (aff >= 50) needed = 4;
    else needed = 100;
    var done = countExec(fn);
    if (done >= needed)
      eligible.push({ name: fn, type: "female", done: done, needed: needed });
  }
  for (var mn in maleChars) {
    var needed2;
    if (mn === "强坤" || mn === "林鸿盛") needed2 = 2;
    else if (mn === "赵文斌" || mn === "刘振宇" || mn === "陈文博") needed2 = 4;
    else needed2 = 100;
    var done2 = countTarget(mn);
    if (done2 >= needed2)
      eligible.push({ name: mn, type: "male", done: done2, needed: needed2 });
  }
  return eligible;
}

