// 赠予弹窗
function showGiftModal(itemName, itemType, itemDesc, itemLv, eligible) {
  // 获取好感度数据用于排序和显示
  var d = getAllData();
  var femChars = d.女性角色 || {};
  // 排序：女性优先，女性内按好感度降序，男性内按屈辱度降序
  var maleChars = d.男性角色 || {};
  eligible.sort(function (a, b) {
    // 女性优先
    if (a.type === "female" && b.type !== "female") return -1;
    if (a.type !== "female" && b.type === "female") return 1;
    // 林知意始终第一
    if (a.name === "林知意") return -1;
    if (b.name === "林知意") return 1;
    // 同性别按好感度/屈辱度排序
    if (a.type === "female") {
      var aAff = Number((femChars[a.name] || {}).好感度) || 0;
      var bAff = Number((femChars[b.name] || {}).好感度) || 0;
      return bAff - aAff;
    } else {
      var aDesire = Number((maleChars[a.name] || {}).屈辱度) || 0;
      var bDesire = Number((maleChars[b.name] || {}).屈辱度) || 0;
      return bDesire - aDesire;
    }
  });

  var html = '<div class="yq-overlay" id="yq-gift-overlay">';
  html += '<div class="yq-modal" style="max-width:400px">';
  html +=
    "<h3>🎁 赠予 " +
    escHtml(itemName) +
    ' <button class="yq-btn danger" style="float:right;padding:2px 8px" id="yq-gift-close">关闭</button></h3>';
  html +=
    '<div style="font-size:12px;color:var(--yq-dim);margin-bottom:10px">选择赠予对象（共' +
    eligible.length +
    "人可选）</div>";
  var lastType = "";
  for (var i = 0; i < eligible.length; i++) {
