function _recordEvalFailure(channel, type, err, raw, prompt, attempt) {
  try {
    var list = getMeta("yinqi_eval_failures", []) || [];
    var msg = "";
    try {
      msg = err && err.message ? err.message : String(err || "");
    } catch (_) {}
    var hint = "";
    if (/HTTP\s+400|400\s+Bad\s+Request|Bad\s+Request/i.test(msg)) {
      hint =
        "HTTP 400 通常是请求格式或 API URL 问题；优先检查 URL 是否被填成完整 /v1/chat/completions，建议只填 base 或 /v1。";
    }
    list.push({
      ts: Date.now(),
      channel: String(channel || "?"),
      type: String(type || "unknown"),
      attempt: Number(attempt || 0),
      error: msg.substring(0, 300),
      hint: hint,
      rawPreview: String(raw || "").substring(0, 500),
      promptPreview: String(prompt || "").substring(0, 200),
    });
    if (list.length > 30) list = list.slice(-30);
    setMeta("yinqi_eval_failures", list);
    saveMeta();
  } catch (_e) {}
}
function _yqEvalFailureReport() {
  var list = getMeta("yinqi_eval_failures", []) || [];
  try {
    console.table(list.slice(-10));
  } catch (_e) {}
  return {
    total: list.length,
    recent: list.slice(-10),
    suggestions: list
      .filter(function (f) {
        return f && f.hint;
      })
      .map(function (f) {
        return f.hint;
      })
      .filter(function (v, i, arr) {
        return arr.indexOf(v) === i;
      }),
  };
}
try {
  if (typeof window !== "undefined")
    window._yqEvalFailureReport = _yqEvalFailureReport;
  if (_pw && _pw !== window) _pw._yqEvalFailureReport = _yqEvalFailureReport;
} catch (_eExposeEvalReport) {}

