    // [V10.6] 兜底：剥离后找不到 → 从原始 text 找
    if (!jsonMatch) {
      jsonMatch = (text || "").match(/\{[\s\S]*\}/);
    }
    if (jsonMatch) {
      var raw = jsonMatch[0];
