          var obj2 = JSON.parse(fixed);
          if (obj2.grade && obj2.review) return obj2;
        } catch (e2) {}
      }
    }
    // 最后尝试：用正则提取关键字段
    var gradeM = text.match(/"grade"\s*:\s*"([^"]+)"/);
    var reviewM = text.match(/"review"\s*:\s*"([^"]+)"/);
    var coeffM = text.match(/"gradeCoeff"\s*:\s*([\d.]+)/);
    var titleM = text.match(/"forumTitle"\s*:\s*"([^"]+)"/);
    var bodyM = text.match(/"forumBody"\s*:\s*"([^"]+)"/);
    var imgM = text.match(/"imageDesc"\s*:\s*"([^"]+)"/);
    if (gradeM && reviewM) {
