// ==================== 连环任务历史获取 ====================
function getChainHistory(chainId, currentStep) {
  // 获取同一连环任务链中，当前步骤之前的所有任务历史
  var history = [];
  var taskHistory = getMeta("yinqi_task_history", []);

  for (var i = 0; i < taskHistory.length; i++) {
    var task = taskHistory[i];
    if (task.chainId === chainId && task.chainStep < currentStep) {
      history.push({
        step: task.chainStep,
        title: task.desc || task.title || "未知任务",
        level: task.level || "",
        summary: task.summary || task.executionSummary || "",
      });
    }
  }

  // 按步骤排序
  history.sort(function (a, b) {
    return a.step - b.step;
  });

  return history;
}

function getItemInfo(id) {
  // 从完整商品数据中查找（支持按name或id查找）
  var cats = ["wpn", "arm", "spc", "abl", "skl", "fac", "csm", "pet"];
  for (var ci = 0; ci < cats.length; ci++) {
    var items = getShopItemsByCatAndLevel._allFlat;
    if (!items) {
      // [V10.3 FIX] 构建扁平化缓存时同步打 category 标记，与 _getShopCategoryByName 保持一致
      // 避免谁先调用谁建缓存导致 category 缺失（购买时分类反查失败 → 全部归到 csm）
      items = [];
      var allCats = ["wpn", "arm", "spc", "abl", "skl", "fac", "csm", "pet"];
      for (var ai = 0; ai < allCats.length; ai++) {
        for (var lv = 1; lv <= 6; lv++) {
          var lvItems = getShopItemsByCatAndLevel(allCats[ai], lv);
          for (var li = 0; li < lvItems.length; li++) {
            // 反向标 category（ALL[cat] 里 item 没有 category 字段）
            if (!lvItems[li].category) lvItems[li].category = allCats[ai];
            items.push(lvItems[li]);
          }
        }
      }
      getShopItemsByCatAndLevel._allFlat = items;
    }
    for (var i = 0; i < items.length; i++) {
      if (items[i].name === id || items[i].id === id) {
        var it = items[i];
        // [V2/§4] 透传 v2 元数据字段给背包/使用 handler
        // [V5/§5] 同时透传 v5 元数据
        return {
          name: it.name,
          desc: it.desc,
          level: it.level,
          // [V10.3 FIX] 透传 category 字段，让购买流程的 fallback 真正生效
          category: it.category,
          v2Group: it.v2Group,
          cpBonus: it.cpBonus,
          v2Skill: it.v2Skill,
          v2SkillGender: it.v2SkillGender,
          v2SkillTarget: it.v2SkillTarget,
          reqTaskTotal: it.reqTaskTotal,
          reqTaskB: it.reqTaskB,
          reqTaskS: it.reqTaskS,
          reqTaskX: it.reqTaskX,
          uniqueSkill: it.uniqueSkill,
          maxStack: it.maxStack,
          reqPrereq: it.reqPrereq,
          reqSysLv: it.reqSysLv,
          autoSkill: it.autoSkill,
          consumable: it.consumable,
          stackGroupSize: it.stackGroupSize,
          reqTaskTotalPerGroup: it.reqTaskTotalPerGroup,
          v5Group: it.v5Group,
          v5ConfirmWarning: it.v5ConfirmWarning,
          // [V3/§3] 地图事件雷达字段
          v3Group: it.v3Group,
          v3FacilityType: it.v3FacilityType,
          v3Radar: it.v3Radar,
          v3RadarPlus: it.v3RadarPlus,
          // [V6/§6] 暗攻略检测字段
          v6Group: it.v6Group,
          v6Tier: it.v6Tier,
        };
      }
    }
    break; // 只需要执行一次
  }
  // fallback: 查phoneMeta inventory（自定义道具）
  // [V10.3 万界生效 v4.1] 不再早 return — 必须先查 customs 拿扩展字段（v2Group/v2Skill/race/cp 等）
  //   原逻辑：if (_inv[id] && _inv[id].desc) return { name, desc } → 直接退出
  //   BUG：万界 skl/pet 购买后写入 inv，此处早 return → v2Group 字段被吞 → 背包渲染普通"使用"按钮 → skl 走不到 _v2HandleUseItem
  //   修复：把 inv 的 desc 作为 fallback 值，但不 return；继续往下走 customs 查询（customs 是真源）
  var _invFallbackDesc = "";
  try {
    var _inv = getMeta("yinqi_inventory", {});
    if (_inv[id] && _inv[id].desc) _invFallbackDesc = _inv[id].desc;
  } catch (e) {}
  // fallback: 查yinqi_custom_items（未购买的自定义商品）
  // [V10.3 万界生效] 透传 skl/pet 扩展字段，让背包按钮分支识别 v2Group → 走 _v2HandleUseItem
  //   原代码只返回 {name, desc} → skl 走不到 v2 装备技能槽路径 → 万界 skl 完全失效。
  //   修复：透传 v2Group/v2Skill/v2SkillGender/skillMult + race/cp + 兜底字段，
  //   让 _buildBackpackItems 识别 info.v2Group 后渲染"装备能力"按钮，调 _v2HandleUseItem。
  try {
    var _cust = getMeta("yinqi_custom_items", []);
    for (var _ci = 0; _ci < _cust.length; _ci++) {
      if (_cust[_ci].name === id) {
        var c = _cust[_ci];
        return {
          name: id,
          desc: c.effect || c.desc || _invFallbackDesc,
          category: c.category,
          level: Number(c.level) || 1,
          // [V10.3] 扩展字段透传：让按钮分支拿到这些后路由到正确 handler
          v2Group: c.v2Group,
          v2Skill: c.v2Skill,
          v2SkillGender: c.v2SkillGender,
          // 万界自定义 skill 倍率（lookup 函数 _yqGetSkillMult 也会查 customs 兜底）
          skillMult: c.skillMult,
          // 万界自定义 pet 加持（lookup 函数 _yqGetPetBoost 兜底已就位）
          race: c.race,
          cp: c.cp,
          // 防 V2 cap/门槛崩溃：万界 skl 不设门槛
          reqTaskTotal: 0,
          maxStack: 1,
        };
      }
    }
  } catch (e) {}
  // customs 没找到就用 inv fallback desc 兜底返回
  if (_invFallbackDesc) return { name: id, desc: _invFallbackDesc };
  return { name: id, desc: "" };
}

// ==================== 战斗力计算 ====================
function calcCombatPower(name) {
  var d = getAllData();
  var userName = getUserName();
  var base, equipStr, statusStr, abilityStr;
  // [V2/§4.9] 读取 _cp_bonus / _skills（面板独占写入）
  var cpBonus = 0;
  var skills = [];
  var skipCpCap = false; // [V5.2/§P1.4] 林知意·银麒深度共鸣 突破硬顶

  if (name === userName || name === "{{user}}") {
    var lv = Number(((d.银麒系统 || {}).账户 || {}).系统等级 || 1);
    base = { 1: 10, 2: 20, 3: 40, 4: 80, 5: 160, 6: 320 }[lv] || 10;
    var u = d.user || {};
    equipStr = u.装备 || "无";
    statusStr = u.状态 || "健康";
    abilityStr = u.能力 || "无";
    cpBonus = Number(u._cp_bonus) || 0;
    skills = Array.isArray(u._skills) ? u._skills.slice() : [];
  } else {
    var femChars = d.女性角色 || {};
    var maleChars = d.男性角色 || {};
    // 林知意特殊处理：她在角色.林知意中，不在女性角色record中
    if (name === "林知意") {
      var zx = (d.角色 || {}).林知意 || {};
      base = 2;
      equipStr = zx.装备 || "无";
      statusStr = zx.状态 || "健康";
      abilityStr = zx.能力 || "无";
      cpBonus = Number(zx._cp_bonus) || 0;
      skills = Array.isArray(zx._skills) ? zx._skills.slice() : [];
      skipCpCap = zx._skip_cp_cap === true;
    } else if (femChars[name]) {
      base = name === "林安然" ? 1.5 : 2;
      equipStr = femChars[name].装备 || "无";
      statusStr = femChars[name].状态 || "健康";
      abilityStr = femChars[name].能力 || "无";
      cpBonus = Number(femChars[name]._cp_bonus) || 0;
      skills = Array.isArray(femChars[name]._skills)
        ? femChars[name]._skills.slice()
        : [];
      skipCpCap = femChars[name]._skip_cp_cap === true;
    } else if (maleChars[name]) {
      base = name === "刘振宇" ? 6 : 4;
      equipStr = maleChars[name].装备 || "无";
      statusStr = maleChars[name].状态 || "健康";
      abilityStr = maleChars[name].能力 || "无";
      cpBonus = Number(maleChars[name]._cp_bonus) || 0;
      skills = Array.isArray(maleChars[name]._skills)
        ? maleChars[name]._skills.slice()
        : [];
      skipCpCap = maleChars[name]._skip_cp_cap === true;
    } else {
      return {
        total: 4,
        base: 4,
        equip: "无",
        status: "健康",
        ability: "无",
        cpBonus: 0,
        skills: [],
      };
    }
  }

  // [V2/§4.2] _cp_bonus 叠加到基础 CP（面板独占写入，守卫拦截 AI 改动）
  var baseWithBonus = base + cpBonus;

  // 解析能力乘数（AI 写的 abilityStr 和 v2 _skills 均叠加）
  var abilityMult = 1.0;
  if (abilityStr && abilityStr !== "无") {
    var multMatches = abilityStr.match(/×([\d.]+)/g);
    if (multMatches) {
      for (var mi = 0; mi < multMatches.length; mi++) {
        var mv = parseFloat(multMatches[mi].replace("×", ""));
        if (mv > 0 && mv < 10) abilityMult *= mv;
      }
    }
  }
  // [V5.2/§P3.1 + V10.3 万界生效] _skills 能力乘数表：将 v2 道具装的能力真实加入战斗力
  //   V2_SKILL_MULT 在本文件模块顶层（紧挨 V2_SKILL_LABEL 之前），lookup _yqGetSkillMult 先查内置后查 customs。
  //   万界 skl 通过 customs.v2Skill === skillId + customs.skillMult 兜底，desc ×N.N 第二层兜底。
  //   条件性能力（狂战士低 HP 额外 ×1.5、心电感应与主角同场景 ×1.1 等）交由 AI 按场景描写；
  //   这里做"平均基础增益"：每条能力给一个固定乘数，总乘数 cap=2.0 防失控。
  var skillMult = 1.0;
  if (Array.isArray(skills) && skills.length > 0) {
    for (var _si = 0; _si < skills.length; _si++) {
      var _m = _yqGetSkillMult(skills[_si]);
      if (typeof _m === "number" && _m > 0 && _m < 2.5) skillMult *= _m;
    }
    // 失控兜底
    if (skillMult > 2.0) skillMult = 2.0;
  }
  var enhancedBase =
    Math.round(baseWithBonus * abilityMult * skillMult * 100) / 100;

  // 解析武器/装备加成（累加所有CP）
  var weaponBonus = 0;
  var defenseBonus = 0;
  if (equipStr && equipStr !== "无") {
    var cpMatches = equipStr.match(/CP\+(\d+)/gi);
    if (cpMatches) {
      for (var cpi = 0; cpi < cpMatches.length; cpi++) {
        weaponBonus += parseInt(cpMatches[cpi].replace(/CP\+/i, "")) || 0;
      }
    }
    // [V2/§4.8] 武器加成上限从 enhancedBase 放宽到 enhancedBase * 2
    weaponBonus = Math.min(weaponBonus, enhancedBase * 2);
    var defMatches = equipStr.match(/DEF\+(\d+)/gi);
    if (defMatches) {
      for (var dfi = 0; dfi < defMatches.length; dfi++) {
        defenseBonus += parseInt(defMatches[dfi].replace(/DEF\+/i, "")) || 0;
      }
    }
  }

  // 解析状态修正
  var statusMult = 1.0;
  if (statusStr.indexOf("重伤") >= 0) statusMult = 0.5;
  else if (statusStr.indexOf("轻伤") >= 0) statusMult = 0.8;
  else if (statusStr.indexOf("被咬") >= 0) statusMult = 0.3;

  var total = Math.round((enhancedBase + weaponBonus) * statusMult);

  // [V2/§4.1] 硬封顶：林知意 160、其他非主角 220（防 AI 乱写 CP 失衡）
  // [V5.2/§P1.4] 林知意·银麒深度共鸣（skipCpCap=true）可突破到 260
  if (name === "林知意") {
    total = Math.min(total, skipCpCap ? 260 : 160);
  } else if (name !== userName && name !== "{{user}}") {
    total = Math.min(total, skipCpCap ? 320 : 220);
  }

  return {
    total: total,
    base: base,
    defense: defenseBonus,
    equip: equipStr,
    status: statusStr,
    ability: abilityStr,
    cpBonus: cpBonus,
    skills: skills,
  };
}

