// ==================== [V10.3 万界生效] 道具效果 lookup 工具 ====================
// 设计原则：customs（yinqi_custom_items）是真源，静态表只存内置。
//   lookup 先查内置静态表，未命中再查 customs（含 desc/effect 数值解析兜底）。
//   优势：customs 即真源，零迁移代码，无 cache invalidation 风险（参见手册 §14.42/§14.62）。
// 位置：模块顶层，IIFE 闭包内所有 part 可见。
//   - 引用 V2_SKILL_LABEL：在本函数定义点上方已声明，可直接访问。
//   - 引用 V2_SKILL_MULT：var hoisting 让顶层 var 在整个模块作用域可见，运行时一定有值。
//   - 引用 _PET_BOOST_TABLE：在 _core.js 模块顶层（IIFE 第 1 个 part），运行时同闭包可访问。
// 性能：customs 通常 < 50 条，O(N) 查询 + try/catch 兜底，< 1ms 无感。

function _yqGetCustomItemByName(name) {
  if (!name) return null;
  try {
    var customs = getMeta("yinqi_custom_items", []);
    if (!Array.isArray(customs)) return null;
    for (var i = 0; i < customs.length; i++) {
      if (customs[i] && customs[i].name === name) return customs[i];
    }
  } catch (e) {}
  return null;
}

// 宠物 CP 加持查询：内置 _PET_BOOST_TABLE → customs.cp → 解析 desc CP+N
function _yqGetPetBoost(name) {
  if (!name) return 0;
  try {
    if (
      typeof _PET_BOOST_TABLE !== "undefined" &&
      _PET_BOOST_TABLE[name] != null
    ) {
      return Number(_PET_BOOST_TABLE[name]) || 0;
    }
  } catch (_) {}
  var c = _yqGetCustomItemByName(name);
  if (c && c.category === "pet") {
    if (typeof c.cp === "number" && c.cp >= 0 && c.cp <= 50) return c.cp;
    try {
      var m = String(c.effect || c.desc || "").match(/CP\+(\d+)/i);
      if (m) {
        var v = parseInt(m[1], 10);
        if (v >= 0 && v <= 50) return v;
      }
    } catch (_) {}
  }
  return 0;
}

// 技能战力倍率查询：内置 V2_SKILL_MULT → customs.skillMult → 解析 desc ×N
function _yqGetSkillMult(skillId) {
  if (!skillId) return null;
  try {
    if (
      typeof V2_SKILL_MULT !== "undefined" &&
      V2_SKILL_MULT[skillId] != null
    ) {
      return Number(V2_SKILL_MULT[skillId]);
    }
  } catch (_) {}
  try {
    var customs = getMeta("yinqi_custom_items", []);
    if (Array.isArray(customs)) {
      for (var i = 0; i < customs.length; i++) {
        var c = customs[i];
        if (c && c.category === "skl" && c.v2Skill === skillId) {
          if (
            typeof c.skillMult === "number" &&
            c.skillMult > 0.9 &&
            c.skillMult < 2.5
          ) {
            return c.skillMult;
          }
          try {
            var m = String(c.effect || c.desc || "").match(/[×x]([\d.]+)/);
            if (m) {
              var v = parseFloat(m[1]);
              if (v > 0.9 && v < 2.5) return v;
            }
          } catch (_) {}
          return 1.05; // 老存档兜底默认值（保守倍率）
        }
      }
    }
  } catch (_) {}
  return null;
}

// 技能显示名查询：内置 V2_SKILL_LABEL → customs.name → fallback skillId
function _yqGetSkillLabel(skillId) {
  if (!skillId) return "";
  try {
    if (typeof V2_SKILL_LABEL !== "undefined" && V2_SKILL_LABEL[skillId]) {
      return V2_SKILL_LABEL[skillId];
    }
  } catch (_) {}
  try {
    var customs = getMeta("yinqi_custom_items", []);
    if (Array.isArray(customs)) {
      for (var i = 0; i < customs.length; i++) {
        var c = customs[i];
        if (c && c.category === "skl" && c.v2Skill === skillId) {
          return c.name || skillId;
        }
      }
    }
  } catch (_) {}
  return skillId;
}

