/**
 * [V6.5.5 · _tasks_completed 旧存档迁移 · 2026-04-24]
 *
 * 根因：任务提交时 _v2Bump（执行者/副执行者/男性对象(熟人)）的写入逻辑在 V2·§4.10 新增，
 * 但老玩家在这之前已经完成了大量任务 → 这些角色的 _tasks_completed.total 长期为 0
 * → 所有 reqTaskTotal >= N 的 v2_skill 武器防具能力都无法装备（典型：鹰眼射手/狂战斗魂 40 次门槛）
 *
 * 修复：面板首次加载时一次性扫描 yinqi_task_history，按 executor + target(熟人男性) 累加到 _tasks_completed
 * - 幂等：yinqi_v2_tc_migrated flag 防重跑
 * - setVar 直接改 stat_data 不走 MVU，不被守卫拦截
 * - 字段名：history 里是英文 executor/target（不是中文"执行者"/"男性对象"）
 * - 失败判断：reward < 0 或 grade === "失败" 或 gradeCoeff === 0（history 里无 isFail 字段）
 * - 限制：history 未保存副执行者 → 无法追溯 _v2Sub 的计数，只能累加执行者和男性对象
 */
function _v2MigrateTasksCompletedFromHistory() {
  try {
    if (getMeta("yinqi_v2_tc_migrated", false)) return;
    var history = getMeta("yinqi_task_history", []) || [];
    if (!Array.isArray(history) || history.length === 0) {
      setMeta("yinqi_v2_tc_migrated", true);
      saveMeta();
      return;
    }
    var _bump = function (name, lvChar) {
      var base = _v2ResolveRoleBasePath(name);
      if (!base) return false;
      var path = base + "._tasks_completed";
      var rec = getVar(path);
      if (!(rec && typeof rec === "object" && !Array.isArray(rec))) {
        rec = { total: 0, d: 0, c: 0, b: 0, a: 0, s: 0, x: 0 };
      }
      if (typeof rec.total !== "number") rec.total = 0;
      rec.total++;
      if (lvChar) {
        if (typeof rec[lvChar] !== "number") rec[lvChar] = 0;
        rec[lvChar]++;
      }
      setVar(path, rec);
      return true;
    };
    var bumped = 0;
    var skippedFail = 0;
    var skippedNoRecord = 0;
    for (var i = 0; i < history.length; i++) {
      var h = history[i] || {};
      var isFail =
        Number(h.reward || 0) < 0 ||
        String(h.grade || "") === "失败" ||
        Number(h.gradeCoeff || 0) === 0;
      if (isFail) {
        skippedFail++;
        continue;
      }
      var lvMatch = String(h.level || "")
        .toLowerCase()
        .match(/[dcbasx]/);
      var lvChar = lvMatch ? lvMatch[0] : "";
      if (h.executor) {
        if (_bump(h.executor, lvChar)) bumped++;
        else skippedNoRecord++;
      }
      if (h.target && h.target !== "随机NPC" && h.target !== h.executor) {
        if (_bump(h.target, lvChar)) bumped++;
        else skippedNoRecord++;
      }
    }
    setMeta("yinqi_v2_tc_migrated", true);
    saveMeta();
    try {
      console.log(
        "[V2 迁移] _tasks_completed 迁移完成：历史 " +
          history.length +
          " 条，跳过失败 " +
          skippedFail +
          " 条，跳过无记录 " +
          skippedNoRecord +
          " 次，累计追加 " +
          bumped +
          " 次",
      );
    } catch (_) {}
    if (bumped > 0) {
      try {
        if (typeof _yqToast === "function") {
          _yqToast(
            "info",
            "✨ 已从 " +
              history.length +
              " 条任务历史补齐 " +
              bumped +
              " 次角色任务计数（有等级要求的武器防具门槛按真实游戏进度重算）",
            "",
            { timeOut: 10000 },
          );
        }
      } catch (_) {}
    }
  } catch (e) {
    try {
      console.warn("[V2 迁移] 失败:", e && e.message);
    } catch (_) {}
  }
}

