  // 候选池不含 user，玩家无法装备。本轮加入候选池让变性玩家体验闭环。
  // 安全性：
  // - 守卫 V2_FIXED_CHAR_PATHS 已含 "user"，`_v2ApplyCpBonus` 对 record="user" 的 setVar 合规
  // - _v2GetCpBonus/_v2GetSkills/_v2GetTasksCompleted 都按 record 路径读，user 路径都有 Schema prefault
  // - 面板写入不经 MVU 事件 → 零守卫拦截风险
  // 限制：仅 gender !== male 时加入；filterGender 必须包含 female
  try {
    var _uGender = String(getVar("user.gender") || "male");
    if (
      _uGender !== "male" &&
      (filterGender === "all" || filterGender === "female")
    ) {
      var _uName = getUserName();
      if (_uName && _uName !== "林知意") {
        list.push({
          name: _uName,
          gender: "female",
          record: "user",
          _isPlayer: true,
        });
      }
    }
  } catch (_eV2P) {}
  var fem = d.女性角色 || {};
  for (var fn in fem) {
    if (!fem.hasOwnProperty(fn)) continue;
    if (filterGender === "male") continue;
    list.push({ name: fn, gender: "female", record: "女性角色." + fn });
  }
  var male = d.男性角色 || {};
  for (var mn in male) {
    if (!male.hasOwnProperty(mn)) continue;
    if (filterGender === "female" || filterGender === "female_no_linzhiyi")
      continue;
    list.push({ name: mn, gender: "male", record: "男性角色." + mn });
  }
  return list;
}

function _v2GetTasksCompleted(rolePath) {
