function _v2GetSkills(rolePath) {
  var s = getVar(rolePath + "._skills");
  return Array.isArray(s) ? s.slice() : [];
}

function _v2CheckGate(rolePath, info) {
  // 返回 {ok, reason}
  // [V10.9·2026-05-18] reason 文案玩家可读化（移除 total/B/S 等技术词）
  var tc = _v2GetTasksCompleted(rolePath);
  if (info.reqTaskTotal != null && tc.total < info.reqTaskTotal) {
    return {
      ok: false,
      reason:
        "已完成任务 " +
        tc.total +
        " 次，还差 " +
        (info.reqTaskTotal - tc.total) +
        " 次（需累计 ≥ " +
        info.reqTaskTotal +
        " 次）",
    };
  }
  if (info.reqTaskB != null && (tc.b || 0) < info.reqTaskB) {
    return {
      ok: false,
      reason:
        "B 级任务完成 " +
        (tc.b || 0) +
        " 次，还差 " +
        (info.reqTaskB - (tc.b || 0)) +
        " 次（需 ≥ " +
        info.reqTaskB +
        " 次）",
    };
  }
  if (info.reqTaskS != null && (tc.s || 0) < info.reqTaskS) {
    return {
      ok: false,
      reason:
        "S 级任务完成 " +
        (tc.s || 0) +
        " 次，还差 " +
        (info.reqTaskS - (tc.s || 0)) +
        " 次（需 ≥ " +
        info.reqTaskS +
        " 次）",
    };
  }
  if (info.reqTaskX != null && (tc.x || 0) < info.reqTaskX) {
    return {
      ok: false,
      reason:
        "X 级任务完成 " +
        (tc.x || 0) +
        " 次，还差 " +
        (info.reqTaskX - (tc.x || 0)) +
        " 次（需 ≥ " +
        info.reqTaskX +
        " 次）",
    };
  }
  return { ok: true };
}

function _v2ConsumeOne(itemName) {
