  try {
    var bp = (getAllData().user && getAllData().user.背包) || {};
    var safe = _yqNormalizeBagKey(itemName);
    var node = bp[safe] || bp[itemName];
    if (node && typeof node.数量 === "number") {
      var n = node.数量 - 1;
      if (n <= 0) setVar(_yqBagPath(itemName), undefined);
      else setVar(_yqBagPath(itemName, "数量"), n);
    }
  } catch (_e) {}
}

// [V11.8.10·玩家反馈 1 fix·2026-05-27] V2 abl 道具同步写入对方 _abilities 槽 + 能力字符串
//   作用: V2 道具的"技能"语义升级为"能力"语义,对方能力栏显示道具中文名
//   注意: _skills 业务逻辑(skillId 校验/全卡唯一/CP 加成)不变,本函数仅做能力栏显示同步
function _yqV2SyncAbility(record, itemName) {
  if (!record || !itemName) return;
  try {
    var _abilTgt = getVar(record + "._abilities") || [];
    if (!Array.isArray(_abilTgt)) _abilTgt = [];
    if (_abilTgt.indexOf(itemName) < 0 && _abilTgt.length < 5) {
      _abilTgt.push(itemName);
      setVar(record + "._abilities", _abilTgt);
    }
    // 同步写入 .能力 字符串字段(老兼容字段)
    var _curAbilStr = getVar(record + ".能力") || "无";
    if (_curAbilStr === "无" || !_curAbilStr) {
      setVar(record + ".能力", itemName);
    } else if (_curAbilStr.indexOf(itemName) < 0) {
      setVar(record + ".能力", _curAbilStr + "/" + itemName);
    }
  } catch (_eSync) {}
}

function _v2CheckGlobalUniqueSkill(skillId) {
