function _v2ApplyConsume(target, record, itemInfo) {
  // 紧急肾上腺素：下次战斗 CP×1.5（用 _skills 标记，战斗结算读一次后清除）
  // 觉醒者精华：立即 +3 cpBonus，stackGroupSize=5
  if (itemInfo.v2Skill === "adrenaline_once") {
    var skills = _v2GetSkills(record);
    if (skills.indexOf("adrenaline_once") < 0) {
      skills.push("adrenaline_once");
      setVar(record + "._skills", skills);
    }
    _v2ConsumeOne(itemInfo.name);
    saveMeta();
    updateGuardSnapshot();
    _injectSystemMessage(
      "[系统操作] {{user}}给" +
        target +
        "使用了「紧急肾上腺素」，下次战斗 CP×1.5",
    );
    _yqBpInPlaceRefresh(itemName);
    refreshPanel();
    try {
      _yqToast("success", target + " 注射肾上腺素");
    } catch (_) {}
    return;
  }
  if (itemInfo.name === "觉醒者精华") {
    // 累积门槛：每 stackGroupSize 个一组，从第 N+1 个开始需要门槛
    var stackKey = "yinqi_v2_essence_count";
    var counts = getMeta(stackKey, {});
    var used = counts[target] || 0;
    var groupSize = itemInfo.stackGroupSize || 5;
    var req = itemInfo.reqTaskTotalPerGroup || 20;
    if (used >= groupSize) {
      var groups = Math.floor(used / groupSize);
      var tc = _v2GetTasksCompleted(record);
      if (tc.total < groups * req) {
        try {
          if (typeof toastr !== "undefined")
            toastr.error(
              target +
                " 已用 " +
                used +
                " 次，使用第 " +
                (used + 1) +
                " 个需任务数 ≥ " +
                groups * req +
                "（当前 " +
                tc.total +
                "）",
            );
        } catch (_) {}
        return;
      }
    }
    var old = _v2GetCpBonus(record);
    var bonus = _yqNumberOr(itemInfo.cpBonus, 3);
    setVar(record + "._cp_bonus", old + bonus);
    counts[target] = used + 1;
    setMeta(stackKey, counts);
    _v2ConsumeOne(itemInfo.name);
    saveMeta();
    updateGuardSnapshot();
    _injectSystemMessage(
      "[系统操作] {{user}}对" +
        target +
        "使用了「觉醒者精华」，基础CP +" +
        bonus,
    );
    _yqBpInPlaceRefresh(itemName);
    refreshPanel();
    try {
      _yqToast("success", target + " CP +" + bonus);
    } catch (_) {}
    return;
  }
  // 其他消耗型 fallback：走 cpBonus 路径
  _v2ApplyCpBonus(target, record, itemInfo.cpBonus || 0, itemInfo);
}

