// ==================== [V10.9·2026-05-18] enhance/skill 类"给他人使用" handler ====================
// 设计：
//   - enhance 类（写 user._abilities + user.能力）→ "给他人使用"写到对方相同字段
//   - skill 类（无 v2Group 传统技能，如影分身术）→ "自己使用/给他人使用"都写 _skills 数组
// 实现细节：
//   - 走面板 setVar 直写 stat_data，绕过 MVU 事件，不被守卫 V2_PROTECTED_SUFFIXES 回滚
//   - 严格 validate-then-consume：先校验槽满 / 重复，通过才扣库存
//   - 复用 _v2ListCandidates / _v2ShowTargetPickerModal（已有门槛预览能力）
//   - 失败时 toastr 加"道具未消耗"明示

function _handleEnhanceForOther(itemName, itemDesc) {
  var info = getItemInfo(itemName) || {
    name: itemName,
    desc: itemDesc || "",
    level: 1,
  };
  info.name = info.name || itemName;
  info.desc = info.desc || itemDesc || "";
  // 候选：所有 NPC（含林知意 + 女性 + 男性，不含 user 自己）
  var cand = _v2ListCandidates("all");
  if (!cand || cand.length === 0) {
    try {
      if (typeof toastr !== "undefined")
        toastr.warning("当前没有可用的 NPC 角色（道具未消耗）");
    } catch (_) {}
    return;
  }
  _v2ShowTargetPickerModal(
    "选择使用目标 · " + itemName,
    cand,
    info,
    function (name, record) {
      // 校验：_abilities 数组重复 / 槽满（≥5）
      var _abl = getVar(record + "._abilities");
      if (!Array.isArray(_abl)) _abl = [];
      if (_abl.indexOf(itemName) >= 0) {
        try {
          if (typeof toastr !== "undefined")
            toastr.warning(
              name + " 已拥有「" + itemName + "」能力（道具未消耗）",
            );
        } catch (_) {}
        return;
      }
      if (_abl.length >= 5) {
        try {
          if (typeof toastr !== "undefined")
            toastr.error(
              name + " 的能力槽已满（5/5），请先遗忘一项再使用（道具未消耗）",
              "",
              { timeOut: 5000 },
            );
        } catch (_) {}
        return;
      }
      // 通过 → 写入字段
      _abl.push(itemName);
      setVar(record + "._abilities", _abl);
      // 同步写入 .能力 字符串字段（与"自己使用"路径对称）
      var cpInfo = (info.desc || itemDesc || "").match(
        /[×x][\d.]+|CP\+\d+|战斗力\+\d+|免疫丧尸化|信息素/i,
      );
      var entry = itemName + (cpInfo ? "(" + cpInfo[0] + ")" : "");
      var curStr = getVar(record + ".能力") || "无";
      if (curStr === "无") setVar(record + ".能力", entry);
      else setVar(record + ".能力", curStr + "/" + entry);
      // 消耗道具
      _v2ConsumeOne(itemName);
      saveMeta();
      updateGuardSnapshot();
      _injectSystemMessage(
        "[系统操作] {{user}}对" +
          name +
          "使用了「" +
          itemName +
          "」，获得永久强化",
      );
      try {
        _yqCore.taskFlow.appendOperationLog("v10_9_enhance_other", {
          target: name,
          item: itemName,
        });
      } catch (_) {}
      _yqBpInPlaceRefresh(itemName);
      refreshPanel();
      try {
        _yqToast("success", name + " 获得能力「" + itemName + "」");
      } catch (_) {}
    },
  );
}

