function _v5GetAbsDay() {
  var cd = Number(getVar("银麒系统.世界.末日倒计时"));
  if (!isFinite(cd)) cd = 30;
  // 绝对日：以开场为 D0（倒计时 30），每过一天 +1；末日前 absDay = 30 - cd
  return Math.max(0, 30 - cd);
}

/**
 * [V6.5.4 P1·2026-04-24] 变性后自动触发专属性别头像生成 + 手机 UI 头像重绘
 *
 * 根因：原实现只改 user.gender + toast 提示玩家手动去「角色形象」APP 生成
 * 手机 UI 的 getCharacterAvatar 按性别查 <玩家名>_female/_futanari，但这个 key 仅
 * 在 yqEnsureDefaultAvatars() 自愈分支里才会自动触发 generateAvatar 生成。
 * 而 yqEnsureDefaultAvatars() 只在启动/CHAT_CHANGED 时跑，变性本身不触发 CHAT_CHANGED
 * → 玩家直到 F5 或切对话才能看到新头像
