 * 修复：变性瞬间主动通过手机 UI iframe 的 PhoneCharacterAppearance.generateAvatar 生成
 * 同时清 sessionStorage 防重 flag，保证自愈分支下次还能触发（双保险）
 *
 * @param {string} genderTag "female" / "futanari" —— 用于 toast 文案与日志
 */
function _v5TryAutoGenPlayerAvatar(genderTag) {
  try {
    var _genderLabel = genderTag === "futanari" ? "双性" : "女体";
