 * 多执行者时取所有执行者加成"最大值"作为本次任务的加成（不累加副执行者）
 * 避免堆多个副执行者来无限放大
 */
function _calcNsfwRewardBonusForTask(executor, subExecutors) {
  var mainBonus = _getNsfwBonusForExecutor(executor);
  var maxSub = 0;
  if (Array.isArray(subExecutors)) {
    for (var i = 0; i < subExecutors.length; i++) {
      var sb = _getNsfwBonusForExecutor(subExecutors[i]);
      if (sb > maxSub) maxSub = sb;
