// [V6.5.1 FIX·2026-04-24] injectPanel 锚点选择重构
// ========================================================
// 历史 Bug：面板有时挂到"倒数第二 AI 回复"而非最新 AI 楼。
// 根因（TOCTOU 竞态）：
// - `injectPanel` 被 `_debouncedInjectPanel(300ms)` 触发；
// - 最极端场景：`GENERATION_ENDED` 发射时 `chat` 数组已 push 最新 AI 楼，
// 但 ST 的 DOM `$('#chat .mes')` 还没完成 append；
// - 于是：`$messages.length = chat.length - 1`；
// - 主循环 `i = chat.length - 1`，合格但 `$messages.eq(i)` 是**空集**（超出 DOM 长度）；
// - 两层 fallback 也取空 → 终极 fallback `$messages.last()` 拿到 DOM 最后一条
// = `chat[length - 2]` = 用户视角的"倒数第二 AI 回复"；
// - 面板就挂错了楼。
// 副因（DOM 错位）：
// - swipe/delete/rewind 后偶发 `$messages.eq(i)` 与 `chat[i]` 语义不一致；
// - 如 chat[14] 是长 thinking 回复、DOM `[mesid="14"]` 却复用了早前楼层的旧 HTML。
// 修复：
// 1) 优先 `mesid="i"` 精确定位 → 根治 DOM 错位；
// 2) 若合格 chat[i] 但 DOM 未就绪 → 延迟 200ms 重试（最多 _INJECT_RETRY_MAX 次）
// 而不是掉进 fallback 挂错楼；
// 3) 尾部空洞 `chat[length-1]==null` 时打 warn 并从真实长度往前找；
// 4) 成功挂载后若 mesid 不等于"期望最新有效 AI 楼索引"，打 warn 方便后续观察。
// 零风险承诺：正常 DOM 就绪路径完全保持原语义（mesid 找到即 break），
// 只在异常路径上用延迟重试替代"掉到错楼"。
var _INJECT_RETRY_MAX = 3;
var _INJECT_RETRY_DELAY_MS = 200;
var _injectPanelRetryCount = 0;
var _injectPanelRetryTimer = null;

function _resolveMesDom($messages, chatIdx) {
  if (!$messages || !$messages.length) return null;
  try {
    var $byMesid = $messages.filter('[mesid="' + String(chatIdx) + '"]').last();
    if ($byMesid && $byMesid.length) return $byMesid;
  } catch (_e) {}
  var $byEq = $messages.eq(chatIdx);
  return $byEq && $byEq.length ? $byEq : null;
}

function injectPanel() {
  try {
    try {
      _yqMigrateStatData();
    } catch (_eMig) {
      try {
        console.warn("[迁移] injectPanel 入口调用失败:", _eMig);
      } catch (_) {}
    }

    // 底部横条模式：面板挂载到横条容器中
    if (_yqBarCreated && $p("#" + BAR_ID).length) {
      updateBarStatus();
      if (_yqBarExpanded) {
        _yqMountPanelInBar();
      }
      _injectPanelRetryCount = 0;
      return;
    }

    $p("#" + PANEL_ID).remove();
    var $messages = $p("#chat .mes");
    if ($messages.length === 0) {
      var $chat = $p("#chat");
      if ($chat.length) {
        if (!$p("#yinqi-panel-css").length) $p(_pd.head).append(PANEL_CSS);
        $chat.append(
          '<div class="mes" style="border:none;padding:0;margin:0">' +
            buildPanel() +
            "</div>",
        );
        bindEvents();
        try {
          _yqSyncEventChainToastAfterRender();
        } catch (_eEcHintIp) {}
      }
      _injectPanelRetryCount = 0;
      return;
    }

    // [V5.2/§P1.3] 楼层 5 维过滤：!is_user && !is_system && 非整体特殊标签 && 非空 mes
    // 原逻辑缺陷：只检查 .mes 内含特殊标签（indexOf 会误伤"正文+WorldEvent 混合楼层"），
    // 且不识别 user 输入楼 / sendSystemMessage 注入楼，会把面板挂到不该挂的楼层
    var ctx = _getCtx();
    var $targetMsg = null;
    var _chosenChatIdx = -1;
    var _needsRetry = false; // [V6.5.1] 锁定"合格 chat 项但 DOM 未就绪"的重试标志
    function _isSpecialOnlyFloor(mesRaw) {
      var t = String(mesRaw || "").trim();
      if (!t) return true; // 空楼也跳过
      // 仅当整条消息等于 特殊标签 包裹内容时才视为特殊楼
      return /^<(WorldEvent|LiveMeetEvent|ForumMeetEvent)>[\s\S]*<\/\1>\s*$/.test(
        t,
      );
    }
    if (ctx && ctx.chat && ctx.chat.length > 0) {
      // [V6.5.1] 尾部空洞清理（swipe/delete 可能留下 undefined）
      var _realLen = ctx.chat.length;
      while (_realLen > 0 && !ctx.chat[_realLen - 1]) _realLen--;
      if (_realLen !== ctx.chat.length) {
        try {
          console.warn(
            "[面板] chat 尾部空洞数=" +
              (ctx.chat.length - _realLen) +
              " 真实长度=" +
              _realLen,
          );
        } catch (_) {}
      }
      for (var i = _realLen - 1; i >= 0; i--) {
        var msg = ctx.chat[i];
        if (!msg) continue;
        if (msg.is_user === true) continue; // user 输入楼不挂
        if (msg.is_system === true) continue; // sendSystemMessage 注入的系统楼不挂
        if (_isSpecialOnlyFloor(msg.mes)) continue; // 整体是特殊标签的楼不挂
        var $cand = _resolveMesDom($messages, i);
        if ($cand && $cand.length) {
          $targetMsg = $cand;
          _chosenChatIdx = i;
          break;
        }
        // [V6.5.1 根因修复] chat[i] 合格但 DOM 未就绪（或错位不可定位）
        // → 不退化到 fallback，而是标记为"需要 200ms 后重试"，避免挂到错楼
        _needsRetry = true;
        break;
      }
    }

    // [V6.5.1] 合格 AI 楼 DOM 未就绪：延迟重试，而不是掉进 fallback 挂错楼
    if (_needsRetry && !$targetMsg) {
      if (_injectPanelRetryCount < _INJECT_RETRY_MAX) {
        _injectPanelRetryCount++;
        try {
          console.warn(
            "[面板] 合格 AI 楼 DOM 未就绪，" +
              _INJECT_RETRY_DELAY_MS +
              "ms 后重试（第 " +
              _injectPanelRetryCount +
              "/" +
              _INJECT_RETRY_MAX +
              " 次）",
          );
        } catch (_) {}
        if (_injectPanelRetryTimer) {
          try {
            clearTimeout(_injectPanelRetryTimer);
          } catch (_) {}
        }
        _injectPanelRetryTimer = setTimeout(function () {
          _injectPanelRetryTimer = null;
          try {
            if (!_pw._phoneInsertingFloor && !_streamFreeze) injectPanel();
          } catch (_) {}
        }, _INJECT_RETRY_DELAY_MS);
        return; // ★ 本轮不挂任何楼；等 DOM 就绪后的下一轮挂最新 AI
      }
      // 超过重试次数 → 保底走原 fallback（避免面板永久消失）
      try {
        console.warn(
          "[面板] DOM 未就绪重试 " +
            _INJECT_RETRY_MAX +
            " 次仍失败，降级到末尾 fallback 以保证面板可用性",
        );
      } catch (_) {}
    }

    // fallback：若一条合格 AI 楼都没有（chat 里确实没有），再从后向前只跳 is_user / is_system
    if (!$targetMsg || $targetMsg.length === 0) {
      if (ctx && ctx.chat && ctx.chat.length > 0) {
        for (var j = ctx.chat.length - 1; j >= 0; j--) {
          var m2 = ctx.chat[j];
          if (!m2) continue;
          if (m2.is_user === true) continue;
          if (m2.is_system === true) continue;
          var $cand2 = _resolveMesDom($messages, j);
          if ($cand2 && $cand2.length) {
            $targetMsg = $cand2;
            _chosenChatIdx = j;
            break;
          }
        }
      }
