// 短名 → 长名（即"地图按钮 → xyaml 真名"），如果传入的已经是长名则原样返回
function _resolveLocCanonical(name) {
  if (!name) return name;
  if (LOC_ALIAS.hasOwnProperty(name)) return LOC_ALIAS[name];
