// [V10.11·2026-05-18] 主线女主 MVU 桥接工具函数
//   主线女主（林知意 + 6 个核心 NPC）的好感度/攻略度统一走 MVU stat_data 真源
//   普通据点 NPC（worker/prisoner/slave 等）继续走 pb.members[].affection/corruption
// ============================================================
var _MVU_MAIN_FEMALES = [
  "林知意",
  "宋以薇",
  "方若琳",
  "李婉柔",
  "林安然",
  "苏曼",
  "沈若兰",
];
function _isMvuMainFemale(name) {
  return _MVU_MAIN_FEMALES.indexOf(name) !== -1;
}
function _getMvuFemalePath(name) {
  return name === "林知意" ? "角色.林知意" : "女性角色." + name;
}
function _getMemberAffection(m) {
  if (!m || !m.name) return 30;
  if (_isMvuMainFemale(m.name)) {
    var v = Number(getVar(_getMvuFemalePath(m.name) + ".好感度"));
    return Number.isFinite(v)
      ? v
      : m.affection !== undefined
        ? m.affection
        : 30;
  }
  return m.affection !== undefined ? m.affection : 30;
}
function _getMemberCorruption(m) {
  if (!m || !m.name) return 0;
  if (_isMvuMainFemale(m.name)) {
    var v = Number(getVar(_getMvuFemalePath(m.name) + ".攻略度"));
    return Number.isFinite(v) ? v : m.corruption || 0;
  }
  return m.corruption || 0;
}
function _addMemberAffection(m, delta) {
  if (!m || !m.name) return;
  if (_isMvuMainFemale(m.name)) {
    var path = _getMvuFemalePath(m.name) + ".好感度";
    var cur = Number(getVar(path)) || 0;
    setVar(path, Math.max(0, Math.min(100, cur + delta)));
  } else {
    if (m.affection === undefined) m.affection = 30;
    m.affection = Math.max(0, Math.min(100, m.affection + delta));
  }
}
function _addMemberCorruption(m, delta) {
  if (!m || !m.name) return;
  if (_isMvuMainFemale(m.name)) {
    var path = _getMvuFemalePath(m.name) + ".攻略度";
    var cur = Number(getVar(path)) || 0;
    // 攻略度单调递增（§V9.6 守卫约束），只加不减
    if (delta > 0) setVar(path, Math.min(100, cur + delta));
  } else {
    m.corruption = Math.min(100, (m.corruption || 0) + delta);
  }
}

