 * food / water 用 foodCap；medical / parts 用 otherCap
 * LV6 = Infinity（满级无上限）
 */
var OUTPOST_RESOURCE_CAPS = {
  1: { food: 300, water: 300, medical: 100, parts: 100 },
  2: { food: 800, water: 800, medical: 250, parts: 250 },
  3: { food: 2000, water: 2000, medical: 600, parts: 600 },
