};
function _v2GetCaps(coreLevel) {
  return OUTPOST_RESOURCE_CAPS[coreLevel] || OUTPOST_RESOURCE_CAPS[1];
}

/**
 * [V2.§4.2] NPC 每日消耗矩阵（按类型）
 * food/water 单位/天，medical 单位/月（28 天）→ 日均
 * 主角和林知意特殊处理（见 _v2GetMemberDailyCost）
 */
var OUTPOST_NPC_DAILY_CONSUMPTION = {
  leader: { food: 1.5, water: 2.0, medicalPerMonth: 0.5 },
  core: { food: 1.5, water: 2.0, medicalPerMonth: 0.5 },
  member: { food: 1.2, water: 1.8, medicalPerMonth: 0.4 },
  worker: { food: 1.5, water: 2.5, medicalPerMonth: 0.6 },
  newcomer: { food: 1.0, water: 1.5, medicalPerMonth: 0.3 },
  prisoner: { food: 0.6, water: 1.2, medicalPerMonth: 0.3 },
  slave: { food: 0.4, water: 1.0, medicalPerMonth: 0.1 },
  // 兜底（旧存档可能有不规范 type）
  _default: { food: 1.0, water: 1.5, medicalPerMonth: 0.4 },
};

/**
 * [V2.§4.2] 单个 NPC 的日消耗（含主角/林知意特例）
 */
function _v2GetMemberDailyCost(member) {
  if (!member || !member.name) return { food: 0, water: 0, medical: 0 };
  // 主角与林知意按 leader/core 档位（与 V2 文档一致）
  var t = String(member.type || "").trim();
  if (member.name === "林知意") t = "core";
  if (member.job === "领袖" || t === "leader") t = "leader";
  var c =
    OUTPOST_NPC_DAILY_CONSUMPTION[t] || OUTPOST_NPC_DAILY_CONSUMPTION._default;
  return {
    food: c.food,
    water: c.water,
    medical: c.medicalPerMonth / 28, // 月折日
  };
}

/**
 * [V2.§4.2] 据点全员日消耗汇总
 * 返回 { food, water, medical } 浮点数
 */
function _v2GetTotalDailyConsumption(members) {
  var total = { food: 0, water: 0, medical: 0 };
  if (!members || !members.length) return total;
  for (var i = 0; i < members.length; i++) {
    var c = _v2GetMemberDailyCost(members[i]);
    total.food += c.food;
    total.water += c.water;
    total.medical += c.medical;
  }
  return total;
}

/**
 * [V2.§3.3] 资源加值（含上限+溢出消失）
 * @param {object} resources 据点 resources 对象（会被原地修改）
 * @param {number} coreLevel 据点等级
 * @param {object} delta { food, water, medical, parts } 变化量（可负）
 * @returns {object} { applied: 实际入库, overflow: 溢出消失量, capped: 是否触顶 }
 */
function _v2ApplyResourceDelta(resources, coreLevel, delta) {
  var caps = _v2GetCaps(coreLevel);
  var result = { applied: {}, overflow: {}, capped: {} };
  var keys = ["food", "water", "medical", "parts"];
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i];
    if (delta[k] === undefined) continue;
    var cur = Number(resources[k]) || 0;
    var d = Number(delta[k]) || 0;
    var cap = caps[k];
    var next = cur + d;
    if (next < 0) next = 0;
    var actualNext = cap === Infinity ? next : Math.min(cap, next);
    var overflow = next - actualNext;
    resources[k] = actualNext;
    result.applied[k] = actualNext - cur;
    result.overflow[k] = overflow;
    result.capped[k] = cap !== Infinity && actualNext >= cap;
  }
  return result;
}

/**
 * [V2.§8] 末日前/末日临界期/末日后的消耗系数
 * cd > 0：末日前（系数 0，零消耗）
 * cd 0 ~ -7：临界期（线性渐变 0 → 1）
 * cd <= -7：末日后（系数 1.0 标准）
 */
function _v2GetEndtimeConsumptionRatio(cd) {
  if (cd > 0) return 0;
  if (cd <= -7) return 1.0;
  // 临界期：cd=0 → 0, cd=-7 → 1.0 线性
  return Math.abs(cd) / 7;
}

