/**
 * [V2.§18] 生成一个不与现有名字冲突的具名 NPC
 * @param {string} gender 'male' | 'female'
 * @param {string[]} excludeNames 已经占用的名字（可选；不传则自动收集）
 * @returns {string}
 */
function _v2GenUniqueMemberName(gender, excludeNames) {
  var pool = gender === "female" ? V2_FEMALE_NAMES : V2_MALE_NAMES;
  var existing = excludeNames || _v2CollectKnownNames();
  var lookup = {};
  for (var li = 0; li < existing.length; li++) lookup[existing[li]] = true;
  // 100 次随机尝试
  for (var i = 0; i < 100; i++) {
    var s = V2_SURNAMES[Math.floor(Math.random() * V2_SURNAMES.length)];
    var n = pool[Math.floor(Math.random() * pool.length)];
    var full = s + n;
    if (!lookup[full]) return full;
  }
  // 兜底：加数字后缀
  var base = V2_SURNAMES[0] + pool[0];
  for (var k = 2; k < 9999; k++) {
    var candidate = base + k;
    if (!lookup[candidate]) return candidate;
  }
  return base + Date.now();
}

