/**
 * [V2] 根据 FACILITY_DEFS[name] 的 LV1 数值生成简洁 desc(供安装界面用)
 * 示例:
 *   温室农场 → "🌾 种植食物 · LV1:+5 食/天 · 需工人(农业)"
 *   能源护盾 → "⚡ 屏障自动维修 · LV1:+5/天"
 */
function _v2BuildFacilityInstallDesc(name) {
  var def = FACILITY_DEFS[name];
  if (!def) return "未知设施";
  var lv1 = (def.levels && def.levels[0]) || {};
  var parts = [];
  if (def.icon) parts.push(def.icon);
  parts.push(def.desc || name);
  // LV1 关键数值(按 tier 侧重不同字段)
  var stats = [];
  if (lv1.food) stats.push("+" + lv1.food + " 食/天");
  if (lv1.water) stats.push("+" + lv1.water + " 水/天");
  if (lv1.parts) stats.push("+" + lv1.parts + " 物/天");
  if (lv1.medical !== undefined) {
    if (lv1.medical < 0) stats.push(-lv1.medical + " 医/天");
    else stats.push("+" + lv1.medical + " 医/天");
  }
  if (lv1.healMult) stats.push("治疗x" + lv1.healMult);
  if (lv1.antiPlague) stats.push("抗瘟疫");
  if (lv1.yp) stats.push("+" + lv1.yp + " yp/天");
  if (lv1.ypOnce) stats.push("一次 yp+" + lv1.ypOnce[0] + "~" + lv1.ypOnce[1]);
  if (lv1.capacity) stats.push("容量 " + lv1.capacity);
  if (lv1.monthlyNpc) stats.push("月+" + lv1.monthlyNpc + " NPC");
  if (lv1.corruptDaily) stats.push("堕落+" + lv1.corruptDaily + "/天");
  if (lv1.forumHype) stats.push("论坛热度 " + lv1.forumHype);
  if (lv1.shieldRepair) stats.push("屏障修复 +" + lv1.shieldRepair + "/天");
  if (lv1.combatBonus) stats.push("防御战 CP +" + lv1.combatBonus);
  if (lv1.raiderReduce)
    stats.push("骚扰率 -" + Math.round(lv1.raiderReduce * 100) + "%");
  if (lv1.nsfwRooms) stats.push("NSFW 房 +" + lv1.nsfwRooms);
  if (lv1.partsConsume) stats.push("耗物 " + lv1.partsConsume + "/天");
  if (stats.length > 0) parts.push("LV1: " + stats.join(", "));
  // operator 需求
  if (def.needsOperator) {
    parts.push("需工人" + (def.requiredJob ? "·" + def.requiredJob : ""));
  }
  // 前置设施
  if (def.requiresFacility) {
    parts.push("前置: " + def.requiresFacility);
  }
  // maxCount
  if (def.maxCount && def.maxCount > 1) {
    parts.push("最多 " + def.maxCount + " 个");
  } else if (def.maxCount === 1) {
    parts.push("唯一");
  }
  return parts.join(" · ");
}

