/**
 * [V2.§6.3] 设施数组归一化（旧字符串 → 新对象格式）
 * 幂等
 */
function _v2NormalizeFacilities(facilities) {
  if (!Array.isArray(facilities)) return [];
  var result = [];
  var migrated = false;
  facilities.forEach(function (f, i) {
    if (typeof f === "string") {
      migrated = true;
      // 已知映射
      if (Object.prototype.hasOwnProperty.call(LEGACY_FACILITY_NAME_MAP, f)) {
        var mapTo = LEGACY_FACILITY_NAME_MAP[f];
        if (mapTo === null) return; // 跳过已废弃
      }
      // 已知设施名 → 转 LV1 对象
      if (FACILITY_DEFS[f]) {
        result.push(_v2NewFacility(f, 1));
      } else {
        // 未知设施名（用户自定义/手动改的）→ 保留为标签型设施（无产出）
        result.push({
          id: "fac_legacy_" + Date.now() + "_" + i,
          type: f,
          level: 1,
          operatorId: null,
          status: "running",
          isLegacyTag: true,
        });
      }
    } else if (f && typeof f === "object") {
      // 已是对象，补全字段
      if (!f.id)
        f.id =
          "fac_" +
          Date.now() +
          "_" +
          i +
          "_" +
          Math.floor(Math.random() * 1000);
      if (!f.level) f.level = 1;
      if (f.operatorId === undefined) f.operatorId = null;
      if (!f.status) f.status = "running";
      result.push(f);
    }
  });
  return { facilities: result, migrated: migrated };
}

/**
 * 创建一个新设施对象
 */
function _v2NewFacility(type, level) {
  return {
    id:
      "fac_" +
      type +
      "_" +
      Date.now() +
      "_" +
      Math.floor(Math.random() * 10000),
    type: type,
    level: Math.max(1, Math.min(3, level || 1)),
    operatorId: null,
    status: "running",
    builtAtDay: 0,
  };
}

/**
 * [V2.§6.3.4] operator 状态影响产出系数
 * @param {object} memberOrNull operator NPC（可能为 null）
 */
function _v2GetOperatorEfficiency(member) {
  if (!member) return 0; // 无人 = 0%
  if (member.status === "missing" || member.status === "dead") return 0;
  if (member.status === "injured") return 0.5; // 受伤 = 50%
  var aff = _yqNumberOr(_getMemberAffection(member), 30);
  if (aff >= 40) return 1.0; // happy = 100%
  if (aff >= 20) return 0.8; // 中立 = 80%
  return 0.5; // 不满 = 50%（且 5%/天 概率破坏 — N5 处理）
}

/**
 * [V2.§6.1-6.3] 计算单个设施的实际日产出
 * 自动设施直接生效；operate 设施按 operator 状态打折
 * 输出含：food/water/medical/parts（资源）+ yp（银麒点）+ corruptionPerOp（操作者攻略度/天）
 */
function _v2GetFacilityProduction(facility, members) {
  var def = FACILITY_DEFS[facility.type];
  if (!def) return {};
  var levelCfg = def.levels[(facility.level || 1) - 1];
  if (!levelCfg) return {};
  var efficiency = 1.0;
  var operator = null;
  if (def.needsOperator) {
    if (facility.operatorId && members) {
      for (var i = 0; i < members.length; i++) {
        if (members[i] && members[i].id === facility.operatorId) {
          operator = members[i];
          break;
        }
      }
    }
    efficiency = _v2GetOperatorEfficiency(operator);
  }
  var output = {};
  ["food", "water", "medical", "parts"].forEach(function (k) {
    if (levelCfg[k] !== undefined) {
      output[k] = levelCfg[k] * efficiency;
    }
  });
  // 防御类副消耗（如能源护盾每天耗 10 物资）
  if (levelCfg.partsConsume) {
    output.parts = (output.parts || 0) - levelCfg.partsConsume;
  }
  // [N4] NSFW 设施：银麒点产出 + 操作者攻略度变化
  if (levelCfg.yp !== undefined) {
    output.yp = levelCfg.yp * efficiency;
  }
  if (levelCfg.corruptDaily !== undefined && operator) {
    output.corruptionPerOp = levelCfg.corruptDaily;
    output.operatorId = operator.id;
  }
  return output;
}

/**
 * [V2.§6.1-6.3] 据点全部设施日产出汇总
 */
function _v2GetTotalFacilityProduction(facilities, members, locationBonuses) {
  var total = { food: 0, water: 0, medical: 0, parts: 0 };
  if (!facilities || !facilities.length) return total;
  for (var i = 0; i < facilities.length; i++) {
    var prod = _v2GetFacilityProduction(facilities[i], members);
    ["food", "water", "medical", "parts"].forEach(function (k) {
      if (prod[k] !== undefined) total[k] += prod[k];
    });
  }
  // [V8] 地点加成 multiplier — 向后兼容,无 locationBonuses 则 no-op
  if (locationBonuses && typeof locationBonuses === "object") {
    if (locationBonuses.food_mult && locationBonuses.food_mult !== 1)
      total.food = Math.round(total.food * locationBonuses.food_mult);
    if (locationBonuses.water_mult && locationBonuses.water_mult !== 1)
      total.water = Math.round(total.water * locationBonuses.water_mult);
    if (locationBonuses.medical_mult && locationBonuses.medical_mult !== 1)
      total.medical = Math.round(total.medical * locationBonuses.medical_mult);
    if (locationBonuses.parts_mult && locationBonuses.parts_mult !== 1)
      total.parts = Math.round(total.parts * locationBonuses.parts_mult);
  }
  return total;
}

/**
 * [V2.§6.3.3] 自动分配 operator（按好感度高→低指派给 operate 设施）
 * @returns {object} { assignments: [...changes], unassigned: [...idleFacilities] }
 */
function _v2AutoAssignOperators(facilities, members) {
  var changes = [];
  var idle = [];
  if (!facilities || !members)
    return { assignments: changes, unassigned: idle };
  // 按 type 分组
  var byType = {};
  facilities.forEach(function (f) {
    var def = FACILITY_DEFS[f.type];
    if (!def || !def.needsOperator) return;
    if (!byType[def.requiredJob]) byType[def.requiredJob] = [];
    byType[def.requiredJob].push(f);
  });
  // 已被占用的 operator
  var occupiedIds = {};
  facilities.forEach(function (f) {
    if (f.operatorId) occupiedIds[f.operatorId] = true;
  });
  // 按 job 匹配可用 NPC
  Object.keys(byType).forEach(function (job) {
    var isNsfwJob =
      ["接客者", "模特", "繁殖者", "共用伴侣", "拍卖品"].indexOf(job) >= 0;
    var candidates = members.filter(function (m) {
      if (!m || !m.id) return false;
      if (m.job !== job) return false;
      if (m.status !== "healthy") return false;
      if (occupiedIds[m.id]) return false;
      return true;
    });
    if (isNsfwJob) {
      // NSFW 自动分配排序：囚犯/奴隶（强制）优先（攻略度高优先）；自愿走核心/成员需 affection>=70
      candidates.sort(function (a, b) {
        var aForced = a.type === "prisoner" || a.type === "slave" ? 1 : 0;
        var bForced = b.type === "prisoner" || b.type === "slave" ? 1 : 0;
        if (aForced !== bForced) return bForced - aForced;
        return (
          (b.type === "prisoner" || b.type === "slave" ? 1 : 0) -
            (a.type === "prisoner" || a.type === "slave" ? 1 : 0) ||
          _getMemberCorruption(b) - _getMemberCorruption(a)
        );
      });
      candidates = candidates.filter(function (m) {
        if (m.type === "prisoner" || m.type === "slave") return true;
        return _getMemberAffection(m) >= 70; // 自愿门槛
      });
    } else {
      candidates.sort(function (a, b) {
        return _getMemberAffection(b) - _getMemberAffection(a);
      });
    }
    // 分配
    byType[job].forEach(function (f) {
      if (f.operatorId) return;
      if (candidates.length > 0) {
        var chosen = candidates.shift();
        f.operatorId = chosen.id;
        occupiedIds[chosen.id] = true;
        changes.push({
          facilityType: f.type,
          facilityId: f.id,
          operatorId: chosen.id,
          operatorName: chosen.name,
        });
      } else {
        idle.push(f);
      }
    });
  });
  return { assignments: changes, unassigned: idle };
}

