/**
 * 日结主函数
 * 末日前（absDay < 30）：每 2 天 50% 生成 1-3 条末日前事件（nsfw_event）
 * 末日后（cd <= -5 即 absDay >= 35）：70% 生成 2-5 条末日后事件
 * 事件寿命：末日前 3 天 / 末日后 5 天，过期自动标记 ignored
 */
function _v3RollMapEventsDaily(absDay) {
  var events = getMeta("yinqi_map_events", []) || [];
  if (!Array.isArray(events)) events = [];
  var cd = getNSafe("银麒系统.世界.末日倒计时", 29);
  var isApoc = cd <= 0;

  // 1. 过期清理
  for (var i = 0; i < events.length; i++) {
    if (
      events[i] &&
      events[i].status === "pending" &&
      events[i].expiresDay <= absDay
    ) {
      events[i].status = "ignored";
    }
  }

  // 2. Roll 新事件
  // [V10.4·2026-05-13] 放宽门槛修复玩家反馈"地图事件不刷新"
  //   原：末日前每2天roll+50%+必须有基建；末日后cd>-5整段return
  //   改：末日前每日roll+60%概率；末日后cd≤0即启动（即末日当天就有事件）
  //       基建缺失时降级为无基建也可见的事件，不再100%门控
  var added = 0;
  var _pendingCount = 0;
  for (var _pi = 0; _pi < events.length; _pi++) {
    if (events[_pi] && events[_pi].status === "pending") _pendingCount++;
  }
  if (!isApoc) {
    // 末日前改为每日 roll，60% 概率生成 1-3 条
    var lastRoll = getMeta("yinqi_map_events_last_roll", 0);
    if (absDay - lastRoll < 1) {
      setMeta("yinqi_map_events", events);
      return;
    }
    setMeta("yinqi_map_events_last_roll", absDay);
    if (Math.random() < 0.6) {
      var n = 1 + Math.floor(Math.random() * 3); // 1-3 条
      var pool = V3_PREAPOC_EVENT_POIS.nsfw_event;
      // [V10.4·2026-05-13] 剧情感知：排除玩家当前所在地点 + 按时间段过滤
      //   避免"你在图书馆，图书馆发生了色情事件"的违和感
      var _curLoc = "";
      try {
        _curLoc = getVar("银麒系统.世界.地点") || "";
      } catch (_eL) {}
      var _curHour = 12;
      try {
        var _t = getVar("银麒系统.世界.时刻") || "12:00";
        _curHour = parseInt(_t.split(":")[0]) || 12;
      } catch (_eH) {}
      // 夜间场所（22:00-06:00 才合理）
      var _nightOnly = [
        "星光KTV",
        "后街酒吧",
        "鼎盛私人会所",
        "蜜月情趣酒店",
        "天堂浴场",
      ];
      var _filteredPool = pool.filter(function (loc) {
        if (_curLoc && loc.indexOf(_curLoc) >= 0) return false; // 排除当前位置
        if (_curHour >= 6 && _curHour < 22 && _nightOnly.indexOf(loc) >= 0)
          return false; // 白天排除夜店
        return true;
      });
      if (_filteredPool.length === 0) _filteredPool = pool; // fallback
      for (var j = 0; j < n; j++) {
        _v3AddMapEvent({
          type: "nsfw_event",
          location:
            _filteredPool[Math.floor(Math.random() * _filteredPool.length)],
          severity: "moderate",
          createdDay: absDay,
          expiresDay: absDay + 3,
          requires: ["desire_resonance"],
        });
        added++;
      }
    }
  } else {
    // 末日后：cd <= 0 即启动（不再卡 cd <= -5）
    // [V11.4·2026-05-24·BUG #2 修复] 末日后也加 last_roll 同日防重入
    //   原 BUG：跨天补跑 N 次时一次刷 N×(2-5) 条事件
    //   _yqCheckOutpostDailyCrossover 循环调 N 次 → 末日后每次 70% 概率刷 2-5 条
    //   跨 5 天 = 期望 7-17 条事件突然出现
    //   修复：用独立 key yinqi_map_events_last_roll_apoc 防重入，
    //         同 absDay 已 roll 过则直接 return（与末日前对称）
    var lastRollApoc = getMeta("yinqi_map_events_last_roll_apoc", 0);
    if (absDay - lastRollApoc < 1) {
      setMeta("yinqi_map_events", events);
      return;
    }
    setMeta("yinqi_map_events_last_roll_apoc", absDay);

    if (Math.random() < 0.7) {
      var m = 2 + Math.floor(Math.random() * 4); // 2-5 条
      var types = [
        "awakener_solo",
        "zombie_horde",
        "survivor_call",
