            Math.random() < 0.2
              ? "major"
              : Math.random() < 0.5
                ? "minor"
                : "moderate",
          createdDay: absDay,
          expiresDay: absDay + 5,
          requires: requires,
        });
        added++;
      }
    }
  }

  // [V10.4·2026-05-13] 无事件兜底：如果连续3天都没有pending事件，强制生成1条
  //   原设计依赖基建门控（desire_resonance / signal_tower），玩家没基建时永远看不到事件
  //   现在作为"地图有活物"的最低保障，哪怕没基建也每3天给1条
  if (added === 0 && _pendingCount === 0) {
    var _lastFallback = getMeta("yinqi_map_events_last_fallback", 0);
    if (absDay - _lastFallback >= 3) {
      setMeta("yinqi_map_events_last_fallback", absDay);
      var _fbPool = isApoc
        ? V3_POSTAPOC_EVENT_POIS.nsfw_event ||
          V3_POSTAPOC_EVENT_POIS.survivor_call ||
          []
        : V3_PREAPOC_EVENT_POIS.nsfw_event || [];
      if (_fbPool.length > 0) {
        _v3AddMapEvent({
          type: "nsfw_event",
          location: _fbPool[Math.floor(Math.random() * _fbPool.length)],
          severity: "minor",
          createdDay: absDay,
          expiresDay: absDay + 3,
          requires: [], // 兜底事件不要求基建
        });
