/**
 * [V6.1] 觉醒者等级→CP 范围映射（V3 融合版 · 扩展至 Ⅶ 天启）
 */
function _v3GetAwakenerCpByLevel(level) {
  var cpRanges = {
    1: [4, 6], // Ⅰ 初醒
    2: [10, 16], // Ⅱ 欲火
    3: [25, 40], // Ⅲ 炽焰
    4: [45, 75], // Ⅳ 魔欲（V6.1 上调：+15%）
    5: [100, 170], // Ⅴ 欲神（V6.1 上调：+13%）
    6: [200, 340], // Ⅵ 原罪（V6.1 上调：+13%）
    7: [400, 650], // Ⅶ 天启（V6.1 新增，末日终局威胁）
  };
  var r = cpRanges[level] || [4, 6];
  return Math.floor(r[0] + Math.random() * (r[1] - r[0]));
}

/**
 * [V6.1] 末日天数 → 觉醒者可出现的最高等级（成长上限）
 */
function _v3GetAwakenerLevelCap(absDay) {
  if (absDay < 3) return 2; // D+0-2: 最多 Ⅱ 级（初始配置）
  if (absDay < 7) return 3; // D+3-6: 开 Ⅲ 级
  if (absDay < 14) return 4; // D+7-13: 开 Ⅳ 级
  if (absDay < 21) return 5; // D+14-20: 开 Ⅴ 级
  if (absDay < 30) return 6; // D+21-29: 开 Ⅵ 级
  return 7; // D+30+: 开 Ⅶ 级
}

/**
 * [V6.1] 觉醒者等级中文名
 */
function _v3AwakenerLvName(level) {
  var names = ["", "初醒", "欲火", "炽焰", "魔欲", "欲神", "原罪", "天启"];
  return names[level] || "?";
}

/**
 * [V6.1] 觉醒者罗马数字
 */
function _v3AwakenerLvRoman(level) {
  var romans = ["", "Ⅰ", "Ⅱ", "Ⅲ", "Ⅳ", "Ⅴ", "Ⅵ", "Ⅶ"];
  return romans[level] || "?";
}

/**
 * [V6.1] 觉醒者群体协作 CP 公式（替代旧 N^0.7 公式）
 * 公式：sumCP × N^0.75 / N × (1 + 0.08×最高等级) × 1.1 (同据点默契)
 * 相比旧公式提升约 14-45%（等级越高提升越大）
 */
function _v3CalcAwakenerGroupCP(awks) {
  if (!awks || !awks.length) return 0;
  var sumCP = 0;
  var maxLv = 0;
  awks.forEach(function (a) {
    sumCP += a.cp || 0;
    if ((a.level || 1) > maxLv) maxLv = a.level || 1;
  });
  // 基础群体协作：单体平均 × N^0.75
  var baseGroupCP =
    (sumCP / awks.length) * Math.pow(awks.length, 0.75) * awks.length;
  // 高级加成：最高等级每提高 1 级 +8%
  var levelBonus = 1 + (maxLv - 1) * 0.08;
  // 同据点默契加成 +10%
  var teamBonus = 1.1;
  return Math.round(baseGroupCP * levelBonus * teamBonus);
}

/**
 * [V6.1 方案 A] 每日 roll 觉醒者升级
 * 解决"21 个初始觉醒者从 Day0 到 Day100 CP 恒定"的核心 bug
 *
 * @param {object} op yinqi_outposts
 * @param {number} absDay 末日第几天（绝对值）
 */
function _v3RollAwakenerEvolutionDaily(op, absDay) {
  if (!op || !op.npcData) return;
  if (absDay <= 0) return; // 末日前不触发

  Object.keys(op.npcData).forEach(function (npcName) {
    var nd = op.npcData[npcName];
    if (!nd || !nd.awakeners || !nd.awakeners.length) return;

    var aggressionMod = 1 + (nd.aggression || 0.3);
    var dayMod = 1 + absDay / 20;

    nd.awakeners.forEach(function (a) {
      var lvCap = _v3GetAwakenerLevelCap(absDay);
      if ((a.level || 1) >= lvCap) return;

      var baseP = 0.04 + 0.01 * aggressionMod;
      var upgradeP = (baseP * dayMod * (7 - (a.level || 1))) / 6;

      if (Math.random() < upgradeP) {
        a.level = Math.min(lvCap, (a.level || 1) + 1);
        a.cp = _v3GetAwakenerCpByLevel(a.level);

        nd._awakenerLog = nd._awakenerLog || [];
        nd._awakenerLog.push({
          day: absDay,
          name: a.name,
          newLevel: a.level,
          newCp: a.cp,
          reason: "time_evolution",
        });
        if (nd._awakenerLog.length > 10)
          nd._awakenerLog = nd._awakenerLog.slice(-10);
      }
    });
  });
}

/**
 * [V6.1 方案 H] 末日特定天数保底触发高阶觉醒者
 * Day14 保底 Ⅳ / Day21 保底 Ⅴ / Day28 保底 Ⅵ / Day30+ 保底 Ⅶ
 * 确保玩家不会因为随机性而错过世界进化
 */
function _v3EnsureHighTierAwakenerExists(op, absDay) {
  if (!op || !op.npcData) return;
  if (absDay <= 0) return;

  var targetLv = 0;
  if (absDay >= 30) targetLv = 7;
  else if (absDay >= 28) targetLv = 6;
  else if (absDay >= 21) targetLv = 5;
  else if (absDay >= 14) targetLv = 4;
  if (targetLv === 0) return;

  // 检查是否已有
  var hasTarget = false;
  Object.keys(op.npcData).forEach(function (np) {
    var nd = op.npcData[np];
    (nd.awakeners || []).forEach(function (a) {
      if ((a.level || 1) >= targetLv) hasTarget = true;
    });
  });
