  if (!op || !op.npcData) return null;
  var allAwakeners = [];
  Object.keys(op.npcData).forEach(function (npcName) {
    var nd = op.npcData[npcName];
    if (!nd.awakeners) return;
    nd.awakeners.forEach(function (a) {
      if ((a.population || 0) === 0 || (nd.population || 0) === 0) return;
      allAwakeners.push(Object.assign({}, a, { fromBase: npcName }));
