  });
  if (!allAwakeners.length) return null;

  // 队伍规模：Day3→1, Day7→2, Day14→3, Day21→4, Day28→5，据点高级 +1
  var baseSize = Math.max(1, Math.min(5, Math.floor(absDay / 7) + 1));
