  var size = Math.min(5, baseSize + lvBonus);

  // 按等级降序
  allAwakeners.sort(function (a, b) {
    return (b.level || 1) - (a.level || 1);
  });

  var squad = [allAwakeners[0]];
  var leaderBase = squad[0].fromBase;
  var sameBase = allAwakeners.slice(1).filter(function (a) {
    return a.fromBase === leaderBase;
  });
  var otherBase = allAwakeners.slice(1).filter(function (a) {
    return a.fromBase !== leaderBase;
  });

  var sameCount = Math.min(sameBase.length, Math.floor((size - 1) * 0.6));
  for (var i = 0; i < sameCount; i++) squad.push(sameBase[i]);
  var crossCount = size - 1 - sameCount;
  otherBase.sort(function (a, b) {
    return (b.level || 1) - (a.level || 1);
