 * 在 yq-npc-attack 的成功分支（ratio >= 1.2）末尾调用
 *   - femaleCount = floor(estimatedFemales × lootRatio × 0.3)，上限 5
 *   - estimatedFemales = 据点人口 × 40%（npcData 无 femaleCount 字段，用启发式）
 *   - 将 player_female_loot 事件推入 yinqi_event_chains，玩家下一轮在事件 tab 决定处理方式
 */
function _v3OnPlayerAttackOutpostSuccess(targetNpc, playerCP, npcCP) {
  try {
    var op = getMeta("yinqi_outposts", null);
    if (!op || !op.npcData || !op.npcData[targetNpc]) return false;
    var nd = op.npcData[targetNpc];
    // 估算女性数：总人口 × 40%（方案 V3 §5.1 说的"targetFemales"在无专门字段时按启发式估）
    var estimatedFemales = Math.max(0, Math.floor((nd.population || 0) * 0.4));
    if (estimatedFemales === 0) return false;
    var lootRatio = Math.min(1.0, playerCP / Math.max(1, npcCP));
    var femaleLoot = Math.floor(estimatedFemales * lootRatio * 0.3);
    femaleLoot = Math.min(femaleLoot, 5); // 单次上限 5 名
    if (femaleLoot <= 0) return false;
    // 生成 player_female_loot 事件
    var absDay = Math.abs(getN("银麒系统.世界.末日倒计时") || 0);
    var pm = _getCtx().chatMetadata.yinqi_phone || {};
    if (!pm.yinqi_event_chains) pm.yinqi_event_chains = [];
    pm.yinqi_event_chains.push({
      id: "loot_attack_" + Date.now(),
      type: "player_female_loot",
      status: "pending_player_decision",
      severity: "moderate",
      day: absDay,
      fromBase: targetNpc,
      femaleCount: femaleLoot,
      hint:
        "[NTL] {{user}}攻陷 " +
        targetNpc +
        "，缴获 " +
        femaleLoot +
        " 名幸存女性（战利品）。请在「事件」tab 决定处置方式（全部带回 / 部分带回 / 全部释放）。",
      playerCP: playerCP,
      npcCP: npcCP,
      createdAt: Date.now(),
    });
    saveMeta();
    try {
      _yqCore.taskFlow.appendOperationLog("v6_ntl_loot_roll", {
        fromBase: targetNpc,
        femaleCount: femaleLoot,
        ratio: lootRatio,
      });
    } catch (_eLg) {}
    try {
      if (typeof toastr !== "undefined")
        toastr.success(
          "[NTL] 缴获 " + femaleLoot + " 名战利品女性，请在事件 tab 处置",
          "",
          { timeOut: 8000 },
        );
    } catch (_eT) {}
    return true;
  } catch (e) {
    try {
      console.warn("[v6 NTL loot] 异常:", e);
    } catch (_) {}
    return false;
  }
}

/**
 * 防御：把 alliance.totalCP 与玩家据点防御 CP 对比，决出守卫胜负
 * 守方 CP = userCP + 据点屏障 ×10 + 同住成员 CP 总和
 */
function _v3AllianceDefend(eventId) {
  var event = _v3GetAllianceEvent(eventId);
  if (!event || event.status !== "pending") {
    try {
      if (typeof toastr !== "undefined") toastr.error("事件不存在或已结束");
    } catch (_e) {}
    return;
  }
  var alliance = event.alliance || {};
  var op = getMeta("yinqi_outposts", null);
  var pb = op && op.playerBase;
  var userCP = typeof _v3CalcUserCP === "function" ? _v3CalcUserCP() : 10;
  var shieldCP = ((pb && pb.coreLevel) || 1) * 15;
  var memberCP =
    ((pb && pb.members) || []).filter(function (m) {
      return m && m.status !== "dead";
    }).length * 4;
  var defCP = userCP + shieldCP + memberCP;
  var attackCP = alliance.totalCP || 0;
  var ratio = attackCP > 0 ? defCP / attackCP : 999;

  showCustomConfirm({
    title: "防御 NPC 联军",
    message:
      "联军总 CP：" +
      attackCP +
      "（" +
      (alliance.members || []).join("、") +
      "）" +
      "\n守方 CP：" +
      defCP +
      "（玩家 " +
      userCP +
      " + 屏障 " +
      shieldCP +
      " + " +
      ((pb && pb.members) || []).length +
      " 名成员）" +
      "\n比值：" +
      ratio.toFixed(2) +
      "\n\n比值 > 1.5：守住 / 0.8-1.5：苦战 / < 0.8：失守" +
      "\n\n确认防御？",
    confirmText: "防御",
    cancelText: "取消",
  }).then(function (ok) {
    if (!ok) return;
    var hint, resultLabel;
    if (ratio >= 1.5) {
      // 守住，敌方退却
      resultLabel = "victory";
      hint =
        "[NPC 联军防御·胜利] 联军（" +
        (alliance.members || []).join("、") +
        "）被据点屏障击退。三据点关系 -20，未来更易触发联军。";
      // 三据点关系 -20
      (alliance.members || []).forEach(function (n) {
        if (op && op.npcData && op.npcData[n])
          op.npcData[n].relation = Math.max(
            0,
            _yqCore.outpost._numberOr(op.npcData[n].relation, 50) - 20,
          );
      });
    } else if (ratio >= 0.8) {
      // 苦战，物资损失 30%、成员伤亡 1-2 人
      resultLabel = "pyrrhic";
      if (pb && pb.resources) {
        ["food", "water", "medical", "parts"].forEach(function (k) {
          pb.resources[k] = Math.floor((pb.resources[k] || 0) * 0.7);
        });
      }
      var casualtyCount = Math.min(2, ((pb && pb.members) || []).length);
      var casualties = [];
      for (var i = 0; i < casualtyCount; i++) {
        var m = pb.members[i];
        if (m && m.name !== getUserName() && m.name !== "林知意") {
          m.status = "dead";
          casualties.push(m.name);
        }
      }
      try {
        if (typeof _v3ApplyUserInjury === "function")
          _v3ApplyUserInjury("severe", 40);
      } catch (_eInj) {}
      hint =
        "[NPC 联军防御·苦战] 联军被击退但代价惨重：物资 -30%" +
        (casualties.length > 0 ? "，" + casualties.join("、") + " 牺牲" : "") +
        "，玩家重伤（HP -40）。";
    } else {
      // 失守，物资损失 70%，成员伤亡 4-6 人，玩家可能死亡
      resultLabel = "defeat";
      if (pb && pb.resources) {
        ["food", "water", "medical", "parts"].forEach(function (k) {
          pb.resources[k] = Math.floor((pb.resources[k] || 0) * 0.3);
        });
      }
      var killCount = Math.min(6, ((pb && pb.members) || []).length);
      for (var j = 0; j < killCount; j++) {
        var mm = pb.members[j];
        if (mm && mm.name !== getUserName()) mm.status = "dead";
      }
      try {
        if (typeof _v3ApplyUserInjury === "function")
          _v3ApplyUserInjury("severe", 80);
      } catch (_eInj2) {}
      hint =
        "[NPC 联军防御·失败] 据点屏障被击溃，物资损失 70%，6 名成员牺牲，玩家濒死（HP -80）。";
    }
    if (op) setMeta("yinqi_outposts", op);
    _v3FinishAllianceEvent(event, resultLabel, hint);
  });
}

/**
 * 谈判：消耗大量物资 + 向某据点让出位置
 */
function _v3AllianceNegotiate(eventId) {
  var event = _v3GetAllianceEvent(eventId);
  if (!event || event.status !== "pending") return;
  var alliance = event.alliance || {};
  var foodCost = 200,
    waterCost = 200,
    medCost = 50;

  showCustomConfirm({
    title: "谈判·解散联军",
    message:
      "向联军每方据点贡纳：食物 " +
      foodCost +
      " / 饮水 " +
      waterCost +
      " / 医疗 " +
      medCost +
      "\n联军成员：" +
      (alliance.members || []).join("、") +
      "\n\n确认？联军会撤退，但你的物资大幅消耗，关系暂时上升 +10。",
    confirmText: "确认贡纳",
    cancelText: "取消",
  }).then(function (ok) {
    if (!ok) return;
    var op = getMeta("yinqi_outposts", null);
    var pb = op && op.playerBase;
    if (pb && pb.resources) {
      var totalFood = foodCost * (alliance.members || []).length;
      var totalWater = waterCost * (alliance.members || []).length;
      var totalMed = medCost * (alliance.members || []).length;
      if (
        (pb.resources.food || 0) < totalFood ||
        (pb.resources.water || 0) < totalWater
      ) {
        try {
          if (typeof toastr !== "undefined") toastr.error("物资不足");
        } catch (_e) {}
        return;
      }
      pb.resources.food -= totalFood;
      pb.resources.water -= totalWater;
      pb.resources.medical = Math.max(
        0,
        (pb.resources.medical || 0) - totalMed,
      );
    }
    // 三方关系 +10
    (alliance.members || []).forEach(function (n) {
      if (op && op.npcData && op.npcData[n])
        op.npcData[n].relation = Math.min(
          100,
          _yqCore.outpost._numberOr(op.npcData[n].relation, 50) + 10,
        );
    });
    setMeta("yinqi_outposts", op);
    _v3FinishAllianceEvent(
      event,
      "negotiated",
      "[NPC 联军·谈判成功] 你向联军每方据点贡纳大量物资。联军撤退，三方关系 +10。",
    );
  });
}

