/**
 * 反袭：先发制人攻击联军中最弱一方，分化联军
 */
function _v3AllianceCounterAttack(eventId) {
  var event = _v3GetAllianceEvent(eventId);
  if (!event || event.status !== "pending") return;
  var alliance = event.alliance || {};
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.npcData) return;
  // 找最弱
  var weakest = null;
  (alliance.members || []).forEach(function (n) {
    var d = op.npcData[n];
    if (d && (!weakest || (d.population || 0) < (weakest.data.population || 0)))
      weakest = { name: n, data: d };
  });
  if (!weakest) return;

  var userCP = typeof _v3CalcUserCP === "function" ? _v3CalcUserCP() : 10;
  var weakCP =
    (weakest.data.combatCap || 1) * Math.sqrt(weakest.data.population || 1);
  var ratio = userCP / weakCP;
  var successRate = Math.max(0.1, Math.min(0.9, ratio / 2));

  showCustomConfirm({
    title: "反袭 " + weakest.name + "（联军最弱）",
    message:
      "玩家 CP：" +
      userCP +
      " vs " +
      weakest.name +
      " CP " +
      Math.round(weakCP) +
      "\n成功率 ≈ " +
      Math.round(successRate * 100) +
      "%" +
      "\n\n成功 → 该据点元气大伤（人口 -50%），联军解散" +
      "\n失败 → 玩家重伤，联军照常进攻",
    confirmText: "反袭",
    cancelText: "取消",
  }).then(function (ok) {
    if (!ok) return;
    var success = Math.random() < successRate;
    if (success) {
      weakest.data.population = Math.floor(
        (weakest.data.population || 0) * 0.5,
      );
      weakest.data.femaleCount = Math.floor(
        (weakest.data.femaleCount || 0) * 0.5,
      );
      weakest.data.relation = Math.max(
        0,
        _yqCore.outpost._numberOr(weakest.data.relation, 50) - 30,
      );
      // 联军解散：从 hint 移除其他成员，关系 +5（怕你下一个）
      (alliance.members || []).forEach(function (n) {
        if (n !== weakest.name && op.npcData[n])
          op.npcData[n].relation = Math.min(
            100,
            _yqCore.outpost._numberOr(op.npcData[n].relation, 50) + 5,
          );
      });
      setMeta("yinqi_outposts", op);
      _v3FinishAllianceEvent(
        event,
        "counter_success",
        "[NPC 联军·反袭成功] " +
          weakest.name +
          " 元气大伤（人口 -50%），关系 -30。其他联军成员见势不妙撤退，关系 +5。",
      );
    } else {
      try {
        if (typeof _v3ApplyUserInjury === "function")
          _v3ApplyUserInjury("severe", 50);
      } catch (_eInj) {}
      // 失败 → 联军照常进攻（直接走防御失败结局）
      var hint =
        "[NPC 联军·反袭失败] 你被 " +
        weakest.name +
        " 反杀重伤（HP -50）。联军照常进发，3 天后到达据点。";
      // 改 alliance 状态为 fighting 让下一日结自动判防御失败
      event.alliance.status = "post_counter_fail";
      setMeta("yinqi_outposts", op);
      _v3FinishAllianceEvent(event, "counter_failed", hint);
      // 自动追加一条新 alliance event 让 3 天后玩家再次面对（模拟联军照常进攻）
      var newChains = getMeta("yinqi_event_chains", []) || [];
      newChains.push({
        id: "ec_alliance_" + Date.now(),
        type: "npc_alliance_attack",
        severity: "major",
        day: Math.abs(getN("银麒系统.世界.末日倒计时") || 0),
        arriveDay: Math.abs(getN("银麒系统.世界.末日倒计时") || 0) + 3,
        alliance: event.alliance,
        status: "pending",
        hint:
          "[NPC 联军重新预警] 反袭失败，" +
          (alliance.members || []).join("、") +
          " 联军继续进发，3 天后到达。请再次决定（建议防御/谈判/撤离）。",
        createdAt: Date.now(),
      });
      setMeta("yinqi_event_chains", newChains);
    }
  });
}

// ============================================================
// [V3.§2.8] MVU 模式探测 + 一键切换（额外模型 ↔ 主 AI）
// ============================================================

var V3_MVU_PLOT_ENTRIES = [
  "[mvu_plot]主聊_COT_叙事与禁令",
  "[mvu_plot]主聊_输出检查清单",
  "[mvu_plot]主聊_银麒叙事输出边界",
  "[mvu_plot]主聊_禁区_不写变量补丁",
];
var V3_MVU_UPDATE_ENTRIES = [
  "[mvu_update]变量更新规则",
  "[mvu_update]变量输出格式",
  "[mvu_update]额外_COT_补丁上下文",
];

/**
 * 判定当前 MVU 模式
 *
 * 银麒赎世的两种模式设计（见 §3.2）：
 * - **额外模型模式**（默认）：玩家在 ST 配了额外模型做变量解析
 *   - `[mvu_plot]*` 四件套保持 enabled → 主 AI 看到"不写补丁"禁令 → 只写叙事
 *   - `[mvu_update]*` 三件套保持 enabled → 额外模型看到"补丁格式"规则 → 输出 JSONPatch
 * - **主 AI 模式**：玩家只有一个模型，主 AI 既写叙事又写补丁
 *   - `[mvu_plot]*` 三件套 enabled=false → 主 AI 不再受"不写补丁"约束
 *   - `[mvu_update]*` 三件套保持 enabled → 主 AI 自己看"补丁格式"并输出
 *
 * ⚠ 此开关**只**控制这 7 条世界书条目的 enabled；ST 里"额外模型"的 API 配置
 *   （选哪个模型、用哪个 API key）由玩家在 ST UI / MagVarUpdate 插件里独立设置。
 */
function _v3GetMvuMode() {
  try {
    var ctx = _getCtx();
    var book =
      ctx &&
      ctx.characters &&
      ctx.characters[ctx.characterId] &&
      ctx.characters[ctx.characterId].data &&
      ctx.characters[ctx.characterId].data.character_book;
    if (!book || !Array.isArray(book.entries)) return "unknown";
    var updateOn = 0,
      plotOn = 0;
    book.entries.forEach(function (e) {
      if (
        e &&
        V3_MVU_UPDATE_ENTRIES.indexOf(e.comment) >= 0 &&
        e.enabled !== false
      )
        updateOn++;
      if (
        e &&
        V3_MVU_PLOT_ENTRIES.indexOf(e.comment) >= 0 &&
        e.enabled !== false
      )
        plotOn++;
    });
    // mvu_update 三件套必须全开（两种模式都需要补丁格式规则）
    if (updateOn < V3_MVU_UPDATE_ENTRIES.length) return "mixed";
    // mvu_plot 全开 = 额外模型模式（默认）
    if (plotOn === V3_MVU_PLOT_ENTRIES.length) return "extra";
    // mvu_plot 全关 = 主 AI 模式
    if (plotOn === 0) return "main";
    return "mixed";
  } catch (e) {
    return "unknown";
  }
}

function _yqMvuHealthReport() {
  var report = {
    mode: "unknown",
    plot: [],
    update: [],
    latestAiHasPatch: false,
    latestAiPreview: "",
    suggestions: [],
  };
  try {
    var ctx = _getCtx();
    var book =
      ctx &&
      ctx.characters &&
      ctx.characters[ctx.characterId] &&
      ctx.characters[ctx.characterId].data &&
      ctx.characters[ctx.characterId].data.character_book;
    report.mode = _v3GetMvuMode();
    if (book && Array.isArray(book.entries)) {
      V3_MVU_PLOT_ENTRIES.forEach(function (name) {
        var e = book.entries.find(function (it) {
          return it && it.comment === name;
        });
        report.plot.push({
          name: name,
          enabled: !!(e && e.enabled !== false),
          found: !!e,
        });
      });
      V3_MVU_UPDATE_ENTRIES.forEach(function (name) {
        var e2 = book.entries.find(function (it) {
          return it && it.comment === name;
        });
        report.update.push({
          name: name,
          enabled: !!(e2 && e2.enabled !== false),
          found: !!e2,
        });
      });
    }
    var chat = (ctx && ctx.chat) || [];
    for (var i = chat.length - 1; i >= 0; i--) {
      var m = chat[i];
      if (m && !m.is_user && m.mes) {
        var txt = String(m.mes || "");
        report.latestAiHasPatch =
          /<UpdateVariable[\s>]/.test(txt) || /<JSONPatch[\s>]/.test(txt);
        report.latestAiPreview = txt.slice(0, 240);
        break;
      }
    }
    if (report.mode === "extra" && !report.latestAiHasPatch) {
      report.suggestions.push(
        "extra 模式下主 AI 不写补丁是正常的；若变量不更新，请检查 ST / MagVarUpdate 额外模型 API 是否配置并实际运行。",
      );
    }
    if (report.mode === "extra" && report.latestAiHasPatch) {
      report.suggestions.push(
        "当前 extra 模式下最新主 AI 含补丁块，可能是主 AI 误写补丁；建议检查模式或提示词分流。",
      );
    }
    if (report.mode === "main" && !report.latestAiHasPatch) {
      report.suggestions.push(
        "当前主 AI 模式下最新 AI 未见补丁块；若连续多轮如此，变量可能不会更新。",
      );
    }
    if (report.mode === "mixed") {
      report.suggestions.push(
        "检测到 mixed/异常模式，请在据点事件页切换到「额外模型」或「主 AI」。",
      );
    }
    try {
      console.table(report.plot.concat(report.update));
    } catch (_ctE) {}
    try {
      console.log("[银麒 MVU 健康报告]", report);
    } catch (_clE) {}
  } catch (e) {
    report.error = String((e && e.message) || e);
  }
  return report;
}

function _v3SwitchMvuMode(targetMode) {
  var ctx = _getCtx();
  if (!ctx || !ctx.characters || !ctx.characters[ctx.characterId]) {
    try {
      if (typeof toastr !== "undefined") toastr.error("ST 上下文不可用");
    } catch (_e) {}
    return;
  }
  var ch = ctx.characters[ctx.characterId];
  var book = ch.data && ch.data.character_book;
  if (!book || !Array.isArray(book.entries)) {
    try {
      if (typeof toastr !== "undefined") toastr.error("character_book 不可用");
    } catch (_e) {}
    return;
  }
  var changed = 0;
  book.entries.forEach(function (e) {
    if (!e) return;
