function _v3SweepEventChains(absDay) {
  // 第一轮低风险实现：过期即自动归档，避免 pending 红点和 EJS 约束长期残留。
  // 二轮可按 type 细化 rescue_friend / tribute / harem / apex 等事件的自然后果。
  var chains = getMeta("yinqi_event_chains", []) || [];
  if (!Array.isArray(chains) || !chains.length) return 0;
  var changed = 0;
  for (var i = 0; i < chains.length; i++) {
    var e = chains[i];
    if (!e || e.status !== "pending" || e.expiresDay == null) continue;
    var exp = Number(e.expiresDay);
    if (!isFinite(exp) || exp > absDay) continue;
    e.status = "ignored";
    e.resolvedAt = Date.now();
    e.resolvedNote = "事件已过期自动归档 · " + _yqEventChainTypeLabel(e.type);
    changed++;
    try {
      _yqCore.taskFlow.appendOperationLog("event_chain_expired", {
        id: e.id || "",
        type: e.type || "",
        expiresDay: exp,
        absDay: absDay,
      });
    } catch (_logE) {}
  }
  if (changed > 0) {
    setMeta("yinqi_event_chains", chains);
    try {
      _injectSystemMessage(
        "[系统操作] " +
          changed +
          " 条剧情事件因超过处理时限被自动归档；后续叙事按其自然错过处理。",
      );
    } catch (_msgE) {}
  }
  return changed;
}

