      color: "var(--yq-muted)",
      bg: "rgba(90,88,110,0.15)",
      tooltip: tip || "玩家选择忽略",
    };
  }
  if (s !== "resolved") return null;
  // result 精细映射（来源：_v3FinishAllianceEvent / _v3FinishThreat / _v3StartFriendRescue）
  var SUCCESS = {
    success: "营救成功", // rescue_friend
    rescued: "救回", // awakener_threat
    defeated: "击败觉醒者",
    victory: "守住",
    negotiated: "谈判成功",
    counter_success: "反袭成功",
  };
  var FAIL = {
    fail: "营救失败",
    permanent_taken: "被永久掠走",
    defeat: "失守",
    counter_failed: "反袭失败",
  };
  var WARN = {
    pyrrhic: "惨胜",
    retreated: "撤离",
  };
  if (SUCCESS[r]) {
    return {
      icon: "✓",
      label: SUCCESS[r],
      color: "var(--yq-green)",
      bg: "var(--yq-green-d)",
      tooltip: tip,
    };
  }
  if (FAIL[r]) {
    return {
      icon: "✗",
      label: FAIL[r],
      color: "var(--yq-red)",
      bg: "var(--yq-red-d)",
      tooltip: tip,
    };
  }
  if (WARN[r]) {
    return {
      icon: r === "retreated" ? "→" : "⚠",
      label: WARN[r],
      color: "var(--yq-gold)",
      bg: "var(--yq-gold-d)",
      tooltip: tip,
    };
  }
  // 兜底：status=resolved 无 result → 玩家手动点「已处理」
  return {
    icon: "✓",
    label: "已处理",
    color: "var(--yq-green)",
    bg: "var(--yq-green-d)",
