}

/**
 * 更新事件状态
 */
function _v3UpdateEventStatus(eventId, newStatus) {
  if (!eventId) return;
  var chains = getMeta("yinqi_event_chains", []) || [];
  var found = false;
  var evType = "";
  for (var i = 0; i < chains.length; i++) {
    if (chains[i] && chains[i].id === eventId) {
      evType = chains[i].type || "";
      chains[i].status = newStatus;
      chains[i].resolvedAt = Date.now();
      chains[i].resolvedNote =
        (newStatus === "resolved" ? "玩家标记已读" : "玩家标记忽略") +
        " · " +
        _yqEventChainTypeLabel(evType);
      found = true;
      break;
    }
  }
  if (found) {
    setMeta("yinqi_event_chains", chains);
    saveMeta();
    try {
      _yqCore.taskFlow.appendOperationLog("event_chain_" + newStatus, {
        eventId: eventId,
        type: evType,
      });
    } catch (_eLogEc) {}
    try {
      var lab = _yqEventChainTypeLabel(evType);
      var verb =
        newStatus === "resolved"
          ? "将「" +
            lab +
            "」标记为已读/归档（未执行营救、战斗或谈判结算；叙事侧请自行收尾）。"
          : "选择忽略「" + lab + "」提醒（剧情后果请仍按既有设定承接）。";
      _injectSystemMessage("[系统操作] {{user}}在剧情事件面板" + verb);
    } catch (_eInjEc) {}
    refreshPanel();
    try {
      if (typeof toastr !== "undefined")
        toastr.success("事件已" + (newStatus === "resolved" ? "处理" : "忽略"));
    } catch (_eT) {}
  }
}

/**
 * 暴露事件回滚（消耗记忆调整剂）
 */
function _v3RollbackExposureEvent(eventId) {
  if (!eventId) return;
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.playerBase) return;
  var pb = op.playerBase;
  var memCount =
    (pb._concealItems &&
      pb._concealItems.memEraser &&
      pb._concealItems.memEraser.count) ||
    0;
  if (memCount <= 0) {
    try {
      if (typeof toastr !== "undefined") toastr.warning("没有库存的记忆调整剂");
    } catch (_eT) {}
    return;
  }

  var chains = getMeta("yinqi_event_chains", []) || [];
  for (var i = 0; i < chains.length; i++) {
    if (chains[i] && chains[i].id === eventId && chains[i].rollbackable) {
      chains[i].status = "rolled_back";
      chains[i].resolvedAt = Date.now();
      chains[i].resolvedNote = "记忆调整剂回滚 · 据点暴露";
      // 同住人 awareness 回滚（按当时 +20 撤回）
      (pb.members || []).forEach(function (m) {
        if (m && m.name && m.name !== getUserName() && m.name !== "林知意") {
          m.awareness = Math.max(0, (m.awareness || 0) - 20);
        }
      });
      // 重置 weekly roll
      pb._lastExposureRollDay = Math.abs(getN("银麒系统.世界.末日倒计时") || 0);
      // 消耗 1 个记忆调整剂
      pb._concealItems.memEraser.count = memCount - 1;
      // [V10.2·2026-05-15] 双源同步：原单写 setMeta 会导致 stat_data.user.背包 残留
      try {
        _yqDualBagSync("记忆调整剂", -1, { save: false });
      } catch (_eInv) {}
      setMeta("yinqi_outposts", op);
      setMeta("yinqi_event_chains", chains);
      saveMeta();
      try {
        _yqCore.taskFlow.appendOperationLog("event_chain_rolled_back", {
          eventId: eventId,
          type: "exposure",
        });
      } catch (_eLogRb) {}
      try {
        _injectSystemMessage(
          "[系统操作] {{user}}使用记忆调整剂回滚了一条「据点暴露」相关剧情事件记录。",
        );
      } catch (_eInjRb) {}
      refreshPanel();
      try {
        if (typeof toastr !== "undefined")
          toastr.success(
            "✓ 暴露事件已回滚（剩余 " + (memCount - 1) + " 个记忆调整剂）",
          );
      } catch (_eT2) {}
      return;
    }
  }
  try {
    if (typeof toastr !== "undefined") toastr.error("事件不可回滚或已处理");
  } catch (_eT3) {}
}


