// ============================================================
// [V2.§9 N5] 异常状态注册表（扩展性预留：注册新异常只追加配置）
// ============================================================

/**
 * 异常状态定义
 * - check(pb, dailyCons): 是否触发
 * - severity: 等级（warning / danger）
 * - onTick(pb, days, op): 每天持续时的副作用
 * - msg(pb, days): 注入主 AI 的系统消息
 */
var ABNORMAL_STATES = {
  饥饿: {
    severity: "warning",
    check: function (pb, dailyCons) {
      return (
        (pb.resources.food || 0) < dailyCons.food &&
        (pb.resources.food || 0) > 0
      );
    },
    onTick: function (pb, days) {
      // 全员好感 -1，工作产出 ×0.7（产出折扣在 _v2GetOperatorEfficiency 内不实现，仅好感降低）
      (pb.members || []).forEach(function (m) {
        if (m) _addMemberAffection(m, -1);
      });
    },
    msg: function (pb, days) {
      return "🍞 据点饥饿状态第 " + days + " 天 — 全员好感 -1 / 工作产出降低";
    },
  },
  饥荒: {
    severity: "danger",
    check: function (pb) {
      return (pb.resources.food || 0) === 0;
    },
    onTick: function (pb, days) {
      // 1% 概率随机 NPC 死亡，5% 概率核心叛逃，全员好感 -3
      (pb.members || []).forEach(function (m) {
        if (m) _addMemberAffection(m, -3);
      });
      var alive = (pb.members || []).filter(function (m) {
        return (
          m &&
          m.status === "healthy" &&
          m.name &&
          m.type !== "leader" &&
          m.name !== "林知意"
        );
      });
      if (
        alive.length > 0 &&
        Math.random() < 0.01 * Math.min(alive.length, 10)
      ) {
        var victim = alive[Math.floor(Math.random() * alive.length)];
        victim.status = "dead";
        victim.hp = 0;
        return "💀 饥荒夺走了 " + victim.name + " 的生命";
      }
    },
    msg: function (pb, days) {
      return "🍞 据点饥荒第 " + days + " 天 — 1% 概率 NPC 饿死 / 全员好感-3";
    },
  },
  缺水: {
    severity: "warning",
    check: function (pb, dailyCons) {
      return (
        (pb.resources.water || 0) < dailyCons.water &&
        (pb.resources.water || 0) > 0
      );
    },
    onTick: function (pb, days) {
      (pb.members || []).forEach(function (m) {
        if (m) _addMemberAffection(m, -2);
      });
    },
    msg: function (pb, days) {
      return "💧 据点缺水第 " + days + " 天 — 全员好感-2 / 内乱概率上升";
    },
  },
  干渴: {
    severity: "danger",
    check: function (pb) {
      return (pb.resources.water || 0) === 0;
    },
    onTick: function (pb, days) {
      var alive = (pb.members || []).filter(function (m) {
        return (
          m &&
          m.status === "healthy" &&
          m.name &&
          m.type !== "leader" &&
          m.name !== "林知意"
        );
      });
      if (
        alive.length > 0 &&
        Math.random() < 0.03 * Math.min(alive.length, 10)
      ) {
        var victim = alive[Math.floor(Math.random() * alive.length)];
        victim.status = "dead";
        victim.hp = 0;
        return "💀 干渴夺走了 " + victim.name + " 的生命";
      }
    },
    msg: function (pb, days) {
      return "💧 据点干渴第 " + days + " 天 — 3% 概率 NPC 渴死";
    },
  },
  医疗崩溃: {
    severity: "danger",
    check: function (pb) {
      return (
        (pb.resources.medical || 0) === 0 &&
        (pb.members || []).some(function (m) {
          return m && m.status === "injured";
        })
      );
    },
    onTick: function (pb, days) {
      // injured NPC 5%/天 死亡
      (pb.members || []).forEach(function (m) {
        if (m && m.status === "injured" && Math.random() < 0.05) {
          m.status = "dead";
          m.hp = 0;
          return;
        }
      });
    },
    msg: function (pb, days) {
      return "💊 据点医疗崩溃第 " + days + " 天 — 受伤 NPC 5%/天 死亡";
    },
  },
  鼠患: {
    severity: "warning",
    check: function (pb) {
      var caps = _v2GetCaps(pb.coreLevel || 1);
      if (caps.food === Infinity) return false;
      return (pb.resources.food || 0) > caps.food * 0.9;
    },
    onTick: function (pb, days) {
      // 食物自然减 5/天
      pb.resources.food = Math.max(0, (pb.resources.food || 0) - 5);
    },
    msg: function (pb, days) {
      return "🐀 仓库鼠患（食物 >90% 上限）— 食物 -5/天，建议清理或派遣";
    },
  },
};

/**
 * 检测当前所有异常 + 应用 onTick + 返回触发的消息
 * @returns {string[]} 系统消息列表
 */
function _v2CheckAndApplyAbnormals(pb, dailyCons, op) {
  if (!pb || !pb.resources) return [];
  if (!pb._abnormalDays) pb._abnormalDays = {};
  var msgs = [];
  var allKeys = Object.keys(ABNORMAL_STATES);
  allKeys.forEach(function (key) {
    var def = ABNORMAL_STATES[key];
    var triggered = def.check(pb, dailyCons || { food: 1, water: 1 });
    if (triggered) {
      pb._abnormalDays[key] = (pb._abnormalDays[key] || 0) + 1;
      var extraMsg;
      try {
        extraMsg = def.onTick(pb, pb._abnormalDays[key], op);
      } catch (_e) {}
      msgs.push(def.msg(pb, pb._abnormalDays[key]));
      if (extraMsg) msgs.push(extraMsg);
    } else {
      // 异常解除：重置计数
      if (pb._abnormalDays[key]) {
        var recoverMsg = "✅ 据点「" + key + "」状态已解除";
        if (key === "饥饿" || key === "饥荒")
          recoverMsg +=
            "，食物储备已恢复到当前日耗需求以上，正文不得继续描写断粮";
        else if (key === "缺水" || key === "干渴")
          recoverMsg +=
            "，饮水储备已恢复到当前日耗需求以上，正文不得继续描写断水";
        else if (key === "医疗崩溃")
          recoverMsg += "，医疗资源或伤员状态已恢复到安全线以上";
        else if (key === "鼠患") recoverMsg += "，仓储压力已解除";
        msgs.push(recoverMsg);
        delete pb._abnormalDays[key];
      }
    }
  });
  return msgs;
}

