// 初始化NPC据点（末日后首次运行时）
/**
 * [V2.§12] 旧存档迁移：百分比→绝对值 + backgroundPop→具名 NPC
 * 幂等（_schemaVersion === "v2.1" 时 no-op），可重复调用安全
 */
function _v2MigrateOldOutpostSchema() {
  try {
    var op = getMeta("yinqi_outposts", null);
    if (!op) return { skipped: "no-op-data" };
    if (op._schemaVersion === "v2.1") return { skipped: "already-v2.1" };

    var migLog = { playerBase: null, npcOutposts: [], membersGenerated: 0 };

    // === 玩家据点 ===
    if (op.playerBase) {
      var pb = op.playerBase;
      var caps = _v2GetCaps(pb.coreLevel || 1);
      var oldRes = pb.resources || { food: 100, water: 100, medical: 100 };
      // 旧值在 0-100 区间 → 按 LV 上限等比放大
      var newFood = Math.round(((oldRes.food || 0) / 100) * caps.food);
      var newWater = Math.round(((oldRes.water || 0) / 100) * caps.water);
      var newMedical = Math.round(((oldRes.medical || 0) / 100) * caps.medical);
      var newParts = Math.round(
        ((oldRes.weapons || oldRes.parts || 0) / 100) * caps.parts,
      );
      pb.resources = {
        food: isFinite(newFood) ? newFood : 0,
        water: isFinite(newWater) ? newWater : 0,
        medical: isFinite(newMedical) ? newMedical : 0,
        parts: isFinite(newParts) ? newParts : 0,
      };
      migLog.playerBase = {
        oldRes: oldRes,
        newRes: pb.resources,
        coreLevel: pb.coreLevel || 1,
        caps: caps,
      };

      // backgroundPop → 具名 NPC（决策 7）
      if (pb.backgroundPop && pb.backgroundPop.total > 0) {
        var bg = pb.backgroundPop;
        if (!pb.members) pb.members = [];
        var existingNames = pb.members
          .map(function (m) {
            return m && m.name;
          })
          .filter(Boolean);
        var allKnown = _v2CollectKnownNames().concat(existingNames);
        var maleQuota = Math.max(0, Number(bg.male) || 0);
        var femaleQuota = Math.max(0, Number(bg.female) || 0);
        var totalQuota = Math.max(
          0,
          Number(bg.total) || maleQuota + femaleQuota,
        );
        // 拆分劳工 / 囚犯 / 奴隶
        var slaveCount = Math.max(0, Number(bg.slaves) || 0);
        var prisonerCount = Math.max(0, Number(bg.prisoners) || 0);
        var workerCount = Math.max(
          0,
          Number(bg.workers) || totalQuota - slaveCount - prisonerCount,
        );
        // 性别按比例分配（兜底各半）
        var totalRoles = workerCount + prisonerCount + slaveCount;
        if (totalRoles === 0) totalRoles = totalQuota;
        // 生成
        function makeOne(role, idx) {
          // 性别分配：尽量按 male/female 比例
          var isFemale = false;
          if (femaleQuota > 0 && (idx % 2 === 0 || maleQuota === 0)) {
            isFemale = true;
            femaleQuota--;
          } else if (maleQuota > 0) {
            maleQuota--;
          } else if (femaleQuota > 0) {
            isFemale = true;
            femaleQuota--;
          }
          var newName = _v2GenUniqueMemberName(
            isFemale ? "female" : "male",
            allKnown,
          );
          allKnown.push(newName);
          migLog.membersGenerated++;
          return {
            id:
              "uid_mig_" +
              Date.now() +
              "_" +
              Math.floor(Math.random() * 1000) +
              "_" +
              idx,
            name: newName,
            type: role,
            gender: isFemale ? "female" : "male",
            age: 18 + Math.floor(Math.random() * 35),
            affection: role === "worker" ? 30 : role === "prisoner" ? 15 : 5,
            loyalty: role === "worker" ? 40 : 20,
            corruption: role === "slave" ? 30 : role === "prisoner" ? 15 : 0,
            job: "无",
            status: "healthy",
            hp: 100,
            source: "迁移自背景人口",
            joinDay: pb.deployDay || 0,
            tags: ["迁移生成"],
            customNotes: "",
            extData: {},
          };
        }
        var idx = 0;
        for (var w = 0; w < workerCount; w++)
          pb.members.push(makeOne("worker", idx++));
        for (var p = 0; p < prisonerCount; p++)
          pb.members.push(makeOne("prisoner", idx++));
        for (var s = 0; s < slaveCount; s++)
          pb.members.push(makeOne("slave", idx++));
        // 清空背景人口（已转为具名）
        delete pb.backgroundPop;
      }

      // [N2] 设施数组归一化（旧字符串 → 新对象 + 已废弃名清理）
      if (Array.isArray(pb.facilities)) {
        var _v2FacRes = _v2NormalizeFacilities(pb.facilities);
        pb.facilities = _v2FacRes.facilities;
        if (_v2FacRes.migrated)
          migLog.facilitiesMigrated = pb.facilities.length;
      }
      if (pb.facilityMode === undefined) pb.facilityMode = "auto"; // [N2] 默认自动分配

      // 加 schema 字段
      pb._schemaVersion = "v2.1";
      if (!pb._lastDailyTickDate) pb._lastDailyTickDate = "";

      // 给已有 members（user / 林知意 / 旧 NPC）补全 V2 字段
      (pb.members || []).forEach(function (m) {
        if (!m) return;
        if (!m.id)
          m.id =
            "uid_legacy_" + (m.name || Math.random()).toString().slice(0, 8);
        if (!m.gender) m.gender = m.name === "林知意" ? "female" : "male";
        if (m.affection === undefined)
          m.affection = m.type === "core" || m.type === "leader" ? 60 : 30;
        if (m.loyalty === undefined)
          m.loyalty = m.type === "core" || m.type === "leader" ? 80 : 40;
        if (m.corruption === undefined) m.corruption = 0;
        if (!m.status) m.status = "healthy";
        if (m.hp === undefined) m.hp = 100;
        if (!m.tags) m.tags = [];
        if (m.customNotes === undefined) m.customNotes = "";
        if (!m.extData) m.extData = {};
      });
    }

    // === NPC 据点 ===
    for (var nm in op.npcData || {}) {
      if (!op.npcData.hasOwnProperty(nm)) continue;
      var nd = op.npcData[nm];
      if (!nd.resources) continue;
      // NPC 据点按 LV3 上限等比放大
      var npcCaps = OUTPOST_RESOURCE_CAPS[3];
      var oldNR = nd.resources;
      nd.resources = {
        food: Math.round(((oldNR.food || 0) / 100) * npcCaps.food),
        water: Math.round(((oldNR.water || 0) / 100) * npcCaps.water),
        medical: Math.round(((oldNR.medical || 0) / 100) * npcCaps.medical),
        weapons: oldNR.weapons || 0, // weapons 字段保留（仅显示用，不参与日结）
      };
      migLog.npcOutposts.push({
        name: nm,
        oldRes: oldNR,
        newRes: nd.resources,
      });
    }

    // === 标记 schema 版本 ===
    op._schemaVersion = "v2.1";
    if (!op._migrationLog) op._migrationLog = [];
    op._migrationLog.push({
      from: "v1",
      to: "v2.1",
      at: new Date().toISOString(),
      changes: migLog,
    });

    setMeta("yinqi_outposts", op);
    saveMeta();

    try {
      console.log("[V2 迁移] 据点 schema 已升级到 v2.1：", migLog);
    } catch (_eL) {}

    // 注入系统消息（只在玩家据点存在时；NPC-only 静默）
    if (op.playerBase && op.playerBase.location) {
      var migSummary =
        "据点物资从百分比迁移到绝对数值（食物 " +
        (migLog.playerBase
          ? Math.round(migLog.playerBase.oldRes.food || 0) +
            "% → " +
            (op.playerBase.resources.food || 0) +
            "/" +
            migLog.playerBase.caps.food
          : "—") +
        "）";
      if (migLog.membersGenerated > 0) {
        migSummary +=
          "；背景人口已转为 " + migLog.membersGenerated + " 名具名 NPC";
      }
      try {
        _injectSystemMessage("【系统升级】" + migSummary);
      } catch (_eIS) {}
    }

    return { migrated: true, log: migLog };
  } catch (_eMig) {
    try {
      console.warn("[V2 迁移] 失败（已忽略）:", _eMig && _eMig.message);
    } catch (_e) {}
    return { failed: String(_eMig && _eMig.message) };
  }
}

