// [V6.1 OPT-7 · 方案1] 老存档 stat_data 字段补齐迁移函数
// --------------------------------------------------------------------------
// 问题：MVU Zod 的 Schema.prefault 只在"新建聊天"时兜底所有字段。老存档
//       已有 stat_data 后，新增的 Schema 字段不会被主动回填，EJS/面板读
//       到 undefined 时可能崩溃或走错分支（玩家反馈"历史人物没了+面板UI混乱"）。
//
// 解决：启动时扫 Schema 定义的所有字段，对 undefined 字段用默认值回填。
//       严格"只补 undefined 不覆盖已有值"，防止误覆盖玩家合法状态。
//
// 风险防御：
//   1. 绕过 MVU 事件：通过直接操作 message.variables[swipeId].stat_data
//      （不走 Mvu.replaceMvuData → 不触发 VARIABLE_UPDATE_ENDED → 守卫不回滚）
//   2. 只补 undefined：_.get(sd, path) === undefined 才 set
//   3. 幂等锁：phoneMeta.yinqi_migrate_v1_done = true（重复执行直接跳过）
//   4. 诊断日志：补齐清单 console.log + 可选 _yinqiDiagPush
//   5. 回滚入口：window._yqResetMigrationLock() 父页控制台可调
//
// 不处理：
//   - AI 真实删除的字段（守卫职责）
//   - 字段重命名或结构重组（OPT-7 完整版，另议）
//   - IndexedDB 图片 / phoneMeta 独立数据（由手机 UI migrateXxx 系列处理）
// ==========================================================================
function _yqMigrateStatData() {
  try {
    // 幂等锁
    var migrateDone = getMeta("yinqi_migrate_v1_done", false);
    if (migrateDone === true) {
      return { done: true, skipped: "already-migrated" };
    }

    var ctx = _getCtx();
    if (!ctx || !ctx.chat || ctx.chat.length === 0) {
      return { done: false, skipped: "no-chat" };
    }
    // 找最新含 stat_data 的消息（不限 user/system，因为初始化通常在首楼）
    var targetMsg = null;
    var targetSwipe = 0;
    for (var i = ctx.chat.length - 1; i >= 0; i--) {
      var m = ctx.chat[i];
      if (!m) continue;
      var sid = m.swipe_id != null ? m.swipe_id : 0;
      var vars = m.variables && m.variables[sid];
      if (vars && vars.stat_data) {
        targetMsg = m;
        targetSwipe = sid;
        break;
      }
    }
    if (!targetMsg) {
      return { done: false, skipped: "no-stat-data" };
