// 据点页面构建
function buildOutpostPage() {
  // [V2.§12] 每次打开据点 tab 时尝试做一次 schema 迁移（自身幂等，无副作用）
  try {
    _v2MigrateOldOutpostSchema();
  } catch (_eMigCall) {}
  // [V6.1 FIX BUG-2] 每次打开据点 tab 都跑一次 ensureMemberFields 兜底（补 id/status 等）
  // 这样老存档 + 旧手动添加成员的场景也能被自动修正，设施 operator select 才能正确显示
  try {
    _v2EnsureMemberFields();
  } catch (_eEnsM) {}

  // [N3] 每次打开据点 tab 时检查派遣返回（独立于 processOutpostDailyEvents 的日结，
