  try {
    _v2CheckPendingDispatchReturns();
  } catch (_eDspChk) {}

  var op = getMeta("yinqi_outposts", null);
  var cd = getN("银麒系统.世界.末日倒计时");
  // [V3.§2.7] 活跃事件数（与子页列表、主按钮红点、EJS 一致）
