  html += '<div class="yq-tab2" data-outpost-tab="npc">📋 NPC据点</div>';
  html +=
    '<div class="yq-tab2" data-outpost-tab="events">📌 事件' +
    ecBadge +
    "</div>";
  html += '<div class="yq-tab2" data-outpost-tab="intel">📜 情报</div>';
  html +=
    '<div class="yq-btn yq-outpost-manual-sync" style="margin-left:auto;padding:4px 8px;font-size:11px;color:var(--yq-cyan);border-color:var(--yq-border);cursor:pointer" title="手动刷新据点同步（强制调用 outpostSync API 从最近聊天推断据点变化）">🔄 同步</div>';
  html +=
    '<div class="yq-btn yq-outpost-api-cfg" style="padding:4px 8px;font-size:11px;color:var(--yq-muted);border-color:var(--yq-border);cursor:pointer" title="据点同步API配置">⚙️</div>';
  html += "</div>";

  // 地图tab
  html += '<div class="yq-outpost-page" data-outpost="map">';
  html += buildMapView(op, cd);
  html += "</div>";

  // 我的据点tab
  html +=
    '<div class="yq-outpost-page" data-outpost="mybase" style="display:none">';
  html += buildMyBaseView(op);
  html += "</div>";

  // [N3] 派遣 tab
  html +=
    '<div class="yq-outpost-page" data-outpost="dispatch" style="display:none">';
  html += buildDispatchView(op, cd);
  html += "</div>";

  // NPC据点tab
  html +=
    '<div class="yq-outpost-page" data-outpost="npc" style="display:none">';
  html += buildNpcOutpostList(op, cd);
  html += "</div>";

  // [V3.§2.7] 事件 tab
  html +=
    '<div class="yq-outpost-page" data-outpost="events" style="display:none">';
  html += _v3BuildEventsView();
  html += "</div>";

  // 情报tab
  html +=
    '<div class="yq-outpost-page" data-outpost="intel" style="display:none">';
  html += buildIntelView(op);
  html += "</div>";

  return html;
}

