// [V8] cost 从弹窗动态传入(末日后 0 / 否则按 _v7CalcRelocateCost 算出)
function _v6DoDeployBase(loc, takeoverMethod, cost) {
  var opt = SEMI_PUBLIC_TAKEOVER_OPTIONS.find(function (o) {
