// [N5.§11.3] 7 天推演（不含随机事件）
function _v2ShowForecast() {
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.playerBase) return;
  var pb = op.playerBase;
  var caps = _v2GetCaps(pb.coreLevel || 1);
  var cd = getN("银麒系统.世界.末日倒计时");
  var cons = _v2GetTotalDailyConsumption(pb.members);
  var prod = _v2GetTotalFacilityProduction(
    pb.facilities,
    pb.members,
    pb._locationBonuses,
  );

  // 模拟 7 天（不触发随机事件，只算静态吞吐）
  var simRes = JSON.parse(
    JSON.stringify(pb.resources || { food: 0, water: 0, medical: 0, parts: 0 }),
  );
  if (simRes.parts === undefined) simRes.parts = 0;
  var html =
    '<div class="yq-overlay" id="yq-v5-forecast-overlay"><div class="yq-modal" style="max-width:520px;width:92%">';
  html +=
    '<h3 style="margin:0 0 10px;font-size:15px;color:var(--yq-cyan)">🔮 7 天推演（按当前产/耗，不含随机事件）</h3>';
  html += '<table style="width:100%;font-size:11px;border-collapse:collapse">';
  html +=
    '<thead><tr style="background:rgba(0,240,200,0.06);color:var(--yq-dim)">' +
    '<th style="padding:4px;text-align:left">日期</th>' +
    '<th style="padding:4px;text-align:right">🍞食物</th>' +
    '<th style="padding:4px;text-align:right">💧饮水</th>' +
    '<th style="padding:4px;text-align:right">💊医疗</th>' +
    '<th style="padding:4px;text-align:right">🛠️物资</th>' +
    '<th style="padding:4px;text-align:left">异常预警</th></tr></thead><tbody>';
  var hits = [];
  for (var day = 1; day <= 7; day++) {
    var ratio = _v2GetEndtimeConsumptionRatio(cd - day);
    simRes.food = Math.max(
      0,
      Math.min(
        caps.food === Infinity ? 99999 : caps.food,
        simRes.food + (prod.food || 0) - cons.food * ratio,
      ),
    );
    simRes.water = Math.max(
      0,
      Math.min(
        caps.water === Infinity ? 99999 : caps.water,
        simRes.water + (prod.water || 0) - cons.water * ratio,
      ),
    );
    simRes.medical = Math.max(
      0,
      Math.min(
        caps.medical === Infinity ? 99999 : caps.medical,
        simRes.medical + (prod.medical || 0) - cons.medical * ratio,
      ),
    );
    simRes.parts = Math.max(
      0,
      Math.min(
        caps.parts === Infinity ? 99999 : caps.parts,
        simRes.parts + (prod.parts || 0),
      ),
    );
    // 异常预警
    var alerts = [];
    if (simRes.food < cons.food * ratio && simRes.food > 0) alerts.push("饥饿");
    if (simRes.food === 0) alerts.push("饥荒⚠");
    if (simRes.water < cons.water * ratio && simRes.water > 0)
      alerts.push("缺水");
    if (simRes.water === 0) alerts.push("干渴⚠");
    var rowColor = alerts.length > 0 ? "color:var(--yq-gold)" : "";
    if (
      alerts.some(function (a) {
        return a.indexOf("⚠") >= 0;
      })
    )
      rowColor = "color:var(--yq-red);font-weight:600";
    html +=
      '<tr style="border-bottom:1px dashed rgba(255,255,255,0.04);' +
      rowColor +
      '">';
    html += '<td style="padding:4px">D' + (cd - day) + "</td>";
    html +=
      '<td style="padding:4px;text-align:right">' +
      Math.round(simRes.food) +
      "</td>";
    html +=
      '<td style="padding:4px;text-align:right">' +
      Math.round(simRes.water) +
      "</td>";
    html +=
      '<td style="padding:4px;text-align:right">' +
      Math.round(simRes.medical) +
      "</td>";
    html +=
      '<td style="padding:4px;text-align:right">' +
      Math.round(simRes.parts) +
      "</td>";
    html += '<td style="padding:4px">' + alerts.join("/") + "</td>";
    html += "</tr>";
  }
  html += "</tbody></table>";
  html +=
    '<div style="font-size:10px;color:var(--yq-muted);margin-top:8px">提示：推演不含派遣返回 / 突发事件 / NSFW 设施月度奖励，仅作每日生产消耗的快速估算</div>';
  html +=
    '<div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="yq-btn primary yq-v5-fc-close" style="padding:6px 16px">关闭</button></div>';
  html += "</div></div>";
  $p("#yq-v5-forecast-overlay").remove();
  $p(_pd.body).append(html);
  $p("#yq-v5-forecast-overlay").on(
    "click",
    ".yq-v5-fc-close, #yq-v5-forecast-overlay",
    function (e) {
      if (
        e.target !== e.currentTarget &&
        !$p(e.target).hasClass("yq-v5-fc-close")
      )
        return;
      $p("#yq-v5-forecast-overlay").remove();
    },
  );
}

// [N3] 检查所有进行中派遣是否到返程日，到则结算（与 processOutpostDailyEvents 共享逻辑）
function _v2CheckPendingDispatchReturns() {
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.playerBase || !op.dispatches) return 0;
  var pb = op.playerBase;
  var cd = getN("银麒系统.世界.末日倒计时");
  var settled = 0;
  op.dispatches.forEach(function (d) {
    if (d.status !== "in_progress") return;
    if (d.returnDay < cd) return; // 还没到返回日
    var rResult = _v2CalculateDispatchResult(d, pb);
    d.report = rResult;
    d.status = "returned";
    d.returnedAt = new Date().toISOString();
    _v2ApplyResourceDelta(pb.resources, pb.coreLevel || 1, rResult.loot || {});
    (pb.members || []).forEach(function (m) {
      if (!m || d.memberIds.indexOf(m.id) < 0) return;
      m.jobLockedUntil = null;
      if (rResult.hpDelta < 0) {
        m.hp = Math.max(0, (m.hp || 100) + rResult.hpDelta);
        if (rResult.result === "dead") m.status = "dead";
        else if (
          rResult.result === "injured_severe" ||
          rResult.result === "injured_light"
        )
          m.status = "injured";
      }
      if (rResult.corruptionDelta > 0) {
        _addMemberCorruption(m, rResult.corruptionDelta);
      }
    });
    if (rResult.relDelta && op.npcData && op.npcData[d.targetPoi]) {
      op.npcData[d.targetPoi].relation = Math.max(
        0,
        Math.min(
          100,
          _yqCore.outpost._numberOr(op.npcData[d.targetPoi].relation, 50) +
            rResult.relDelta,
        ),
      );
    }
    settled++;
  });
  if (settled > 0) {
    setMeta("yinqi_outposts", op);
    saveMeta();
  }
  return settled;
}

