        : risk.finalRisk > 0.15
          ? "var(--yq-gold)"
          : "var(--yq-green)") +
      '">最终风险：约 ' +
      Math.round(risk.finalRisk * 100) +
      "% / NSFW 概率约 " +
      Math.round(risk.nsfwRate * 100) +
      "%</div>";
    s +=
      '<div style="color:var(--yq-muted);margin-top:4px">耗时：' +
      cfg.duration +
      " 天 · 预计 D" +
      (cd - cfg.duration) +
      " 返回</div>";
    $ov.find(".yq-v3-dsp-risk-summary").html(s);
  }
  $ov.on(
    "change",
    ".yq-v3-dsp-member, .yq-v3-dsp-equip, .yq-v3-dsp-no-nsfw, .yq-v3-dsp-poi",
    refreshRiskSummary,
  );
  refreshRiskSummary();

  $ov.on("click", ".yq-v3-dsp-cancel", function () {
    $ov.remove();
  });
  $ov.on("click", ".yq-v3-dsp-go", function () {
    var poi = $ov.find(".yq-v3-dsp-poi").val();
    var memberIds = $ov
      .find(".yq-v3-dsp-member:checked")
      .map(function () {
        return $p(this).val();
      })
      .get();
    var equipment = $ov
      .find(".yq-v3-dsp-equip:checked")
      .map(function () {
        return $p(this).val();
      })
      .get();
    var allowNsfw = !$ov.find(".yq-v3-dsp-no-nsfw").is(":checked");
    if (!poi || memberIds.length === 0) {
      if (typeof toastr !== "undefined")
        toastr.warning("请选择至少 1 名 NPC + 目的地");
      return;
    }
    _v2CreateDispatch(poi, memberIds, equipment, allowNsfw);
    $ov.remove();
  });
}

// [N3] 创建派遣
function _v2CreateDispatch(poi, memberIds, equipment, allowNsfw) {
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.playerBase) return;
  var pb = op.playerBase;
  var cfg = _v2GetDispatchTargetCfg(poi);
  var cd = getN("银麒系统.世界.末日倒计时");

  // 扣装备
  if (equipment && equipment.length) {
    var nameMap = {
      冷兵器: "冷兵器",
      土制防具: "土制防具",
      纳米监控: "纳米监控",
      仿真面具: "拟态面具",
    };
    // [V10.2·2026-05-15] 双源同步：每件 -n（n = 派遣 NPC 数）
    equipment.forEach(function (eq) {
      var invName = nameMap[eq];
      if (!invName) return;
      var n = memberIds.length;
      if (n > 0) _yqDualBagSync(invName, -n);
    });
  }

  // 锁定 NPC（标记 jobLockedUntil）
  var returnDay = cd - cfg.duration;
  (pb.members || []).forEach(function (m) {
    if (m && memberIds.indexOf(m.id) >= 0) {
      m.jobLockedUntil = returnDay;
    }
  });

  var dispatch = {
    id: "dsp_" + Date.now() + "_" + Math.floor(Math.random() * 10000),
    memberIds: memberIds,
    targetPoi: poi,
    equipment: equipment || [],
    allowNsfw: allowNsfw,
    startDay: cd,
    duration: cfg.duration,
    returnDay: returnDay,
    status: "in_progress",
    createdAt: new Date().toISOString(),
  };

  if (!Array.isArray(op.dispatches)) op.dispatches = [];
  op.dispatches.push(dispatch);

  setMeta("yinqi_outposts", op);
  saveMeta();
  refreshPanel();

  var memberNames = memberIds
    .map(function (id) {
      var m = (pb.members || []).find(function (x) {
        return x && x.id === id;
      });
      return m ? m.name : "?";
    })
    .join(" + ");
  _injectSystemMessage(
    "【派遣出发】" +
      memberNames +
      " 前往 " +
      poi +
      "（预计 " +
      cfg.duration +
      " 天）。",
  );
  if (typeof toastr !== "undefined")
    toastr.success("派遣出发：" + memberNames + " → " + poi);
}

// [N3] 召回派遣（产出 -50%）
function _v2RecallDispatch(dspId) {
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.dispatches) return;
  var d = op.dispatches.find(function (x) {
    return x.id === dspId;
  });
  if (!d || d.status !== "in_progress") return;

  showCustomConfirm({
    title: "召回派遣",
    message:
      "确认召回 " + d.targetPoi + " 的派遣队伍？\n（产出 ×0.5 + 视为正常返回）",
    confirmText: "召回",
    cancelText: "继续派遣",
  }).then(function (ok) {
    if (!ok) return;
    var pb = op.playerBase;
    // 立即结算（按"recalled"结果）
    var result = _v2CalculateDispatchResult(d, pb);
    result.result = "recalled";
    // 战利品减半
    Object.keys(result.loot || {}).forEach(function (k) {
      result.loot[k] = Math.round(result.loot[k] * 0.5);
    });
    d.status = "returned";
    d.report = result;
    d.returnedAt = new Date().toISOString();
    // 释放 NPC
    (pb.members || []).forEach(function (m) {
      if (m && d.memberIds.indexOf(m.id) >= 0) m.jobLockedUntil = null;
    });
    setMeta("yinqi_outposts", op);
    saveMeta();
    refreshPanel();
    if (typeof toastr !== "undefined") toastr.info("已召回：" + d.targetPoi);
  });
}

