// ==================== [V7] 据点搬迁（无损迁移 + 末日后废墟重建）====================
//
// 设计：消耗 1 个据点核心 → 把当前 playerBase 整体迁到新地点
//   保留：等级 / 设施 / 成员 / 房间 / 资源 / 屏障完整度 / NSFW 政策 / 背景人口
//   重置：暴露状态（_abnormalDays）/ _lastDailyTickDate / lastThreat / members[].awareness
//   更新：location / _takeoverMethod / deployDay
// 禁止：无核心 / 派遣队伍在外 / 冷却期内（距上次 deployDay 未满 7 天）
// 末日后：可搬入被推平的 NPC 据点（population<=0）
//
// 实现锚点详见 V3升级方案_2026-04-19.md §2.12 + 开发工作手册 §13.16-§13.21

/**
 * 搬迁可行性校验。
 * deployDay 语义：部署时 getN("银麒系统.世界.末日倒计时") 的值（cd 是单调递减的，
 * 末日后 cd 保持 0 或变负）。冷却判断用绝对差 |deployDay - 当前 cd| >= 7
 * 即"已过去的天数"，无论末日前后都成立。
 *
 * @returns {{ok: boolean, reason?: string, cooldownLeft?: number}}
 */
function _v7IsRelocatable(pb, inv, currentCd) {
  if (!pb || !pb.location) {
    return { ok: false, reason: "尚未建立据点，无法搬迁" };
  }
  if (!inv["据点核心"] || (inv["据点核心"].qty || 0) < 1) {
    return {
      ok: false,
      reason: "需要 1 个「据点核心」作为搬迁燃料（背包无核心）",
    };
  }
  var active = (pb.pendingDispatches || []).filter(function (d) {
    return d && d.status === "dispatched";
  });
  if (active.length > 0) {
    return {
      ok: false,
      reason: "有 " + active.length + " 支派遣队伍在外，召回后再搬迁",
    };
  }
  var oldDay = pb.deployDay;
  if (typeof oldDay === "number") {
    var elapsed = Math.abs(oldDay - currentCd);
    if (elapsed < 7) {
      return {
        ok: false,
        reason: "搬迁冷却中，还需 " + (7 - elapsed) + " 天",
        cooldownLeft: 7 - elapsed,
      };
    }
  }
  return { ok: true };
}

/**
 * 搬迁按钮入口 —— 做可行性校验后调目标选择弹窗
 */
function _v7HandleRelocate() {
  var op = getMeta("yinqi_outposts", null);
  if (!op || !op.playerBase) {
    if (typeof toastr !== "undefined") toastr.warning("尚未建立据点");
    return;
  }
  var pb = op.playerBase;
  var inv = getMeta("yinqi_inventory", {});
  var currentCd = getN("银麒系统.世界.末日倒计时");
  var check = _v7IsRelocatable(pb, inv, currentCd);
  if (!check.ok) {
    if (typeof toastr !== "undefined") {
      if (check.cooldownLeft) toastr.warning(check.reason);
      else toastr.error(check.reason);
    }
    return;
  }
  _v7ShowRelocateTargets(pb);
}

