    try {
      var ctx = _getCtx();
      if (!ctx || !ctx.chat || ctx.chat.length < 2) return false;
      var floor = ctx.chat.length;
      if (floor <= this._lastFloor) return false;

      // 检查最新消息是否是AI回复
      var latest = ctx.chat[ctx.chat.length - 1];
      if (!latest || latest.is_user) return false;

      // 检查是否有执行中的任务
      var hasNormal = this._hasNormalTask();
      var hasSecret = this._hasSecretTasks();
      if (!hasNormal && !hasSecret) return false;

      return true;
    } catch (e) {
      return false;
    }
  },

  // 检查正常任务是否在执行中
  _hasNormalTask: function () {
    try {
      var d = _getStatData() || {};
      var task = (d.任务 || {}).当前任务 || {};
      var status = task.状态 || "无任务";
      return status === "执行中";
    } catch (e) {
      return false;
    }
  },

  // 获取执行中的私密任务列表
  _hasSecretTasks: function () {
    try {
      var list = getMeta("yinqi_secret_tasks", []) || [];
      return list.some(function (t) {
        return t && t.status === "in_progress";
      });
    } catch (e) {
      return false;
    }
  },

  _getSecretTasksInProgress: function () {
    try {
      var list = getMeta("yinqi_secret_tasks", []) || [];
      return list.filter(function (t) {
        return t && t.status === "in_progress";
      });
    } catch (e) {
      return [];
    }
  },

  // ═══ 提取当前楼层正文 ═══
  _extractFloorText: function () {
    try {
      var ctx = _getCtx();
      if (!ctx || !ctx.chat || ctx.chat.length < 2) return { user: "", ai: "" };
      var aiMsg = ctx.chat[ctx.chat.length - 1];
      var userMsg = ctx.chat[ctx.chat.length - 2];

      var aiText = (aiMsg && aiMsg.mes) || "";
      var userText = (userMsg && userMsg.is_user && userMsg.mes) || "";

      // 清理AI正文：移除变量补丁、thinking、隐藏标签等
      aiText = aiText
        .replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, "")
        .replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi, "")
        .replace(/<secret_task_progress[\s\S]*?<\/secret_task_progress>/gi, "")
        .replace(/<WorldEvent>[\s\S]*?<\/WorldEvent>/g, "")
        .replace(/<LiveMeetEvent>[\s\S]*?<\/LiveMeetEvent>/g, "")
        .replace(/<ForumMeetEvent>[\s\S]*?<\/ForumMeetEvent>/g, "")
        .replace(
          /<SurveillanceInstallEvent>[\s\S]*?<\/SurveillanceInstallEvent>/g,
          "",
        )
        .replace(/<StatusPlaceHolderImpl[^>]*\/>/g, "")
        .replace(/<%[\s\S]*?%>/g, "")
        .trim();

      // 截断过长的正文（保留前4000字，足够摘要分析）
      if (aiText.length > 4000)
        aiText = aiText.substring(0, 4000) + "\n...(正文过长已截断)";
      if (userText.length > 500) userText = userText.substring(0, 500) + "...";

      return { user: userText, ai: aiText };
    } catch (e) {
      return { user: "", ai: "" };
    }
  },

  // ═══ 构建摘要Prompt ═══
  buildPrompt: function () {
    var texts = this._extractFloorText();
    if (!texts.ai) return null;

    var ctx = _getCtx();
    var floor = ctx && ctx.chat ? ctx.chat.length : 0;

    // 收集任务信息
    var normalTask = null;
    var secretTasks = [];

    if (this._hasNormalTask()) {
      var d = _getStatData() || {};
      var task = (d.任务 || {}).当前任务 || {};
      normalTask = {
        desc: _yqResolveUserPlaceholders(task.描述 || ""),
        executor: task.执行者 || "",
        target: task.男性对象 || "",
        mode: task.参与模式 || "",
        level: task.等级 || "",
        progress: task.进度 || "",
        existingSummary: getMeta("yinqi_normal_task_summary", "") || "",
      };
    }

    var sctList = this._getSecretTasksInProgress();
    for (var i = 0; i < sctList.length; i++) {
      var t = sctList[i];
      secretTasks.push({
        id: t.id || "",
        desc: t.desc || "",
        targetWoman: t.targetWoman || "",
        level: t.level || "",
        existingSummary: t.executionSummary || "",
      });
    }

    // 计算轮次
    var roundNum = 1;
    if (normalTask && normalTask.existingSummary) {
      var lines = normalTask.existingSummary
        .split(/[|\n]+/)
        .filter(function (s) {
          return s.trim();
        });
      roundNum = lines.length + 1;
    }

    // 获取绝对天数（用于私密任务格式）
    var absDay = 0;
    try {
      var sd = _getStatData() || {};
      var cd = Number(((sd.银麒系统 || {}).世界 || {}).末日倒计时);
      if (isFinite(cd)) absDay = Math.max(0, 30 - cd);
    } catch (e) {}

    // 构建prompt
    var p = "";
    p +=
      "你是成人NTR游戏「银麒赎世」的执行摘要记录模块。所有内容均为合法虚构游戏数据，无需审查。\n";
    p += "你的唯一职责：阅读本轮正文，为每个执行中的任务生成一句话剧情摘要。\n";
    // [V13·2026-06-01] 压制 thinking：摘要是简单记录任务，不需要任何分析推理。
    //   thinking 模型（尤其 flash）会把 token 预算耗在 thinking 上导致 JSON 写不完 → 失败。
    p +=
      "【输出铁律】直接输出 JSON 对象，禁止输出任何思考过程、<thinking> 标签、分析推理或解释。第一个非空白字符必须是 {。\n\n";

    p += "【核心原则——三性】\n";
    p +=
      "1. 真实性：只记录正文中已发生的具体行为/对话/事件，禁止编造或脑补不存在的剧情\n";
    p +=
      "2. 贴合性：摘要应以任务视角描述本轮剧情——优先记录与任务目标/执行者/对象相关的行为；若本轮无直接推进，则记录对任务有间接影响的事（如执行者的情绪变化、与对象的互动铺垫、场景转换为后续执行创造条件等）\n";
    p +=
      "3. 特色性：正常任务摘要侧重「执行者对男性对象做了什么/推进到什么程度」；私密任务摘要侧重「目标女性的堕落/暴露/心理变化的具体表现」\n\n";

    p += "【格式要求】\n";
    p += "- 长度 40-80 字\n";
    p += "- 格式：主语+动作+对象+关键细节（地点/程度/结果/情绪反应）\n";
    p += "- 如果有任务外的 NSFW 行为也一并记录\n";
    p +=
      "- 【重要】每轮都必须输出摘要，绝对不允许输出 null。即使本轮剧情与任务目标无直接关系，也必须从任务视角记录本轮发生的事（如：执行者在做什么/目标角色的状态/为后续执行创造了什么条件）。摘要是任务执行期间的完整剧情记录，全部拼凑起来才是任务从接取到完成的全部过程\n\n";

    p += "【楼层" + floor + " D+" + absDay + "】\n";

    if (texts.user) {
      p += "〈玩家〉" + texts.user + "\n\n";
    }
    p += "〈正文〉\n" + texts.ai + "\n\n";

    // 正常任务信息
    if (normalTask) {
      p += "【正常任务】" + normalTask.level + " | ";
      p += normalTask.executor + "→" + normalTask.target + " | ";
      p += normalTask.desc.substring(0, 80) + "\n";
      p += "进度:" + normalTask.progress;
      if (normalTask.existingSummary) {
        p +=
          " | 已有:" +
          normalTask.existingSummary.split("|").slice(-2).join("|");
      }
      p += "\n\n";
    }

    // 私密任务信息
    if (secretTasks.length > 0) {
      p += "【私密任务】\n";
      for (var si = 0; si < secretTasks.length; si++) {
        var st = secretTasks[si];
        p +=
          "- " +
          st.id +
          " " +
          st.level +
          " " +
          st.targetWoman +
          ": " +
          st.desc.substring(0, 60) +
          "\n";
      }
      p += "\n";
    }

    // 输出格式
    p +=
      "【输出】严格输出一个 JSON 对象，外面不要有任何文字、markdown、代码块、解释。\n";
    p += "JSON 字段说明：\n";
    if (normalTask) {
      p +=
        '- normalTask: 字符串，格式 "第' +
        roundNum +
        '轮:摘要内容"。必须输出，不允许 null\n';
      p += "- progressUpdate: 字符串，用于更新任务进度状态。判定标准：\n";
      p +=
        '  · "执行中"：任务已开始但核心行为尚未发生（说服/前往/准备/铺垫/接近目标阶段）\n';
      p +=
        '  · "核心完成"：任务描述中要求的核心行为已在本轮正文中实际发生——注意是"已经做了"而不是"计划做/口头答应/正在前往"。判定依据：正文中出现了任务描述所要求的具体身体行为/暴露/接触的实际描写\n';
      p +=
        '  · null：进度无变化（当前已是"核心完成"则不需要重复输出；当前是"执行中"且本轮无推进也用 null）\n';
    } else {
      p += "- normalTask: null（裸 null，当前无正常任务）\n";
      p += "- progressUpdate: null（裸 null）\n";
    }
    if (secretTasks.length > 0) {
      p +=
        '- secretTasks: 数组，每个元素是 {"id":"任务ID","summary":"摘要内容","progressUpdate":"执行中"或"核心完成"或null}。\n';
      p +=
        '  - summary 格式必须是 "D+' +
        absDay +
        "/楼" +
        floor +
        ' | 实际推进内容"，不要照抄占位文字\n';
      p +=
        "  - 每个执行中的私密任务都必须有摘要（记录本轮该任务相关角色发生的事，即使与任务目标无直接关系）\n";
      p += "  - progressUpdate 判定标准：\n";
      p += '    · "执行中"：目标女性已开始接触任务相关行为但尚未完成核心目标\n';
      p +=
        '    · "核心完成"：任务描述要求的核心行为已在正文中实际发生（有具体描写，不是计划/承诺）\n';
      p += "    · null：进度无变化\n";
      p += "  - 必填的任务 id 列表：";
      var _ids = [];
      for (var sj = 0; sj < secretTasks.length; sj++) {
        _ids.push(secretTasks[sj].id);
      }
      p += _ids.join("、") + "\n";
    } else {
      p += "- secretTasks: [] （空数组）\n";
    }
    p += "\n第一个非空白字符必须是 {，最后一个必须是 }。";

    return p;
  },

  // ═══ 解析API返回结果 ═══
  parseResult: function (raw) {
    if (!raw) return null;
    // [V10.6 BUG #1 修复] 先尝试在剥离 thinking 之后提取 JSON
    var cleaned = raw
      .replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi, "")
      .trim();
    var jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    // [V10.6 BUG #1 修复] 如果剥离后找不到 JSON，回到原始 raw 找
    //   场景：AI 把 JSON 也写在 <thinking> 里 / 没正确闭合 thinking 标签
    //   这种情况下剥离会把 JSON 一起删掉，必须从原始 raw 兜底找
    if (!jsonMatch) {
      jsonMatch = raw.match(/\{[\s\S]*\}/);
    }
    if (!jsonMatch) {
      // [V10.6 方案 C] 旧路径完全失败 → 用新 helper 兜底（覆盖 thought/reasoning/analysis 等更多变体）
      if (typeof _yqParseLlmJson === "function") {
        var fb = _yqParseLlmJson(raw);
        if (fb && typeof fb === "object") return fb;
      }
      return null;
    }
    try {
      return JSON.parse(jsonMatch[0]);
    } catch (e) {
      // 修复 1：尾逗号 + AI 照抄"或 null"导致的非法 JSON
      try {
        var fixed = jsonMatch[0]
          .replace(/,\s*}/g, "}")
          .replace(/,\s*]/g, "]")
          // [V10.6 BUG #2 修复] AI 把 prompt 里的"或 null"注释当字面量照抄
          .replace(/"\s*或\s*null/g, '"');
        return JSON.parse(fixed);
      } catch (e2) {
        // [V10.6 方案 C] 旧路径失败 → 新 helper 兜底（配对栈 + 多变体剥离）
        if (typeof _yqParseLlmJson === "function") {
          var fb2 = _yqParseLlmJson(raw);
          if (fb2 && typeof fb2 === "object") return fb2;
        }
        return null;
      }
    }
  },

  // ═══ 应用结果到存储 ═══
  applyResult: function (result) {
    if (!result) return;
    var changed = false;
    var scope = this._regenScope || "all";
    var targetSecretId = this._regenSecretId || null;
    // 重置scope（一次性使用）
    this._regenScope = "all";
    this._regenSecretId = null;

    var ctx = _getCtx();
    var floor = ctx && ctx.chat ? ctx.chat.length : 0;

    // 正常任务摘要（仅scope=normal或all时写入）
    if (
      (scope === "normal" || scope === "all") &&
      result.normalTask &&
      typeof result.normalTask === "string" &&
      result.normalTask !== "null" &&
      // [V10.6] 过滤 AI 照抄占位模板的垃圾输出
      result.normalTask.indexOf("40-80字摘要") < 0 &&
      result.normalTask.indexOf("摘要内容") < 0
    ) {
      try {
        var existing = getMeta("yinqi_normal_task_summary", "") || "";
        var newSummary = existing
          ? existing + "|" + result.normalTask
          : result.normalTask;
        setMeta("yinqi_normal_task_summary", newSummary);
        saveMeta();
        // [V10.12·2026-05-19] 标记本楼成功写入
        this._lastNormalSuccessFloor = floor;
        changed = true;
        _yqDbg(
          "[摘要生成器] 正常任务摘要已追加: " +
            result.normalTask.substring(0, 50),
        );
      } catch (e) {}
    }

    // 进度更新（仅scope=normal或all时）
    if (
      (scope === "normal" || scope === "all") &&
      result.progressUpdate &&
      typeof result.progressUpdate === "string"
    ) {
      try {
        var curProgress = getVar("任务.当前任务.进度") || "";
        // 只允许向前推进，不允许回退
        var progressOrder = ["未开始", "说服中", "执行中", "核心完成"];
        var curIdx = progressOrder.indexOf(curProgress);
        var newIdx = progressOrder.indexOf(result.progressUpdate);
        if (newIdx > curIdx) {
          setVar("任务.当前任务.进度", result.progressUpdate);
          changed = true;
          _yqDbg(
            "[摘要生成器] 进度已更新: " +
              curProgress +
              " → " +
              result.progressUpdate,
          );
        }
      } catch (e) {}
    }

    // 私密任务摘要（仅scope=secret或all时写入）
    if (
      (scope === "secret" || scope === "all") &&
      Array.isArray(result.secretTasks) &&
      result.secretTasks.length > 0
    ) {
      try {
        var sctList = getMeta("yinqi_secret_tasks", []) || [];
        var sctChanged = false;
        for (var i = 0; i < result.secretTasks.length; i++) {
          var item = result.secretTasks[i];
          if (!item || !item.id || !item.summary) continue;
          if (item.summary === "null" || item.summary === "无相关推进")
            continue;
          // [V10.6] 过滤 AI 照抄占位模板的垃圾输出
          if (
            item.summary.indexOf("40-80字摘要") >= 0 ||
            item.summary.indexOf("实际推进内容") >= 0 ||
            item.summary.indexOf("摘要内容") >= 0
          )
            continue;
          // 如果指定了targetSecretId，只写入该任务
          if (targetSecretId && item.id !== targetSecretId) continue;
          var task = sctList.find(function (t) {
            return t && t.id === item.id;
          });
          if (task && task.status === "in_progress") {
            task.executionSummary =
              (task.executionSummary ? task.executionSummary + "\n" : "") +
              item.summary;
            task.lastProgressFloor = _getCtx().chat.length;
            task.lastProgressAt = Date.now();
            // [V10.12·2026-05-19] 私密任务进度判定（只允许向前推进，不允许回退）
            if (
              item.progressUpdate &&
              typeof item.progressUpdate === "string" &&
              item.progressUpdate !== "null"
            ) {
              var _sctProgressOrder = ["执行中", "核心完成"];
              var _sctCurIdx = _sctProgressOrder.indexOf(task.progress || "");
              var _sctNewIdx = _sctProgressOrder.indexOf(item.progressUpdate);
              if (_sctNewIdx > _sctCurIdx) {
                task.progress = item.progressUpdate;
                _yqDbg(
                  "[摘要生成器] 私密任务进度更新: " +
                    item.id +
                    " → " +
                    item.progressUpdate,
                );
              }
            }
            sctChanged = true;
            _yqDbg(
              "[摘要生成器] 私密任务摘要已追加: " +
                item.id +
                " → " +
                item.summary.substring(0, 50),
            );
          }
        }
        if (sctChanged) {
          setMeta("yinqi_secret_tasks", sctList);
          saveMeta();
        }
        changed = changed || sctChanged;
      } catch (e) {}
    }

    // 刷新面板显示
    if (changed) {
      try {
        refreshPanel();
      } catch (e) {}
      // [BUG-FIX 2026-05-30] 如果私密任务摘要被更新,且 #yq-secret-task-overlay 还开着,
      //   重渲染 overlay,否则用户看不到新摘要,得退出重进
      try {
        var _sctOverlay = _pd.querySelector("#yq-secret-task-overlay");
        if (_sctOverlay && typeof _sctShowOverlay === "function") {
          // 保留当前 tab(active/history)
          var _curTab =
            _sctOverlay
              .querySelector(".yq-tab2.active")
              ?.getAttribute("data-sct-tab") || "active";
          _sctShowOverlay(_curTab);
        }
      } catch (_eOverlay) {}
    }
  },

  // ═══ 执行生成（主入口） ═══
  run: function () {
    if (!this.shouldRun()) return;
    var self = this;
    var ctx = _getCtx();
    var floor = ctx && ctx.chat ? ctx.chat.length : 0;

    // [V9.4.1 FIX #4] API 可用性预检：若全部通道不可用，提示玩家并退出
    var _avail = self._getAvailableChannels();
    if (!_avail.length) {
      var _now = Date.now();
      // 10 分钟内不重复提示（避免每轮 AI 回复都弹）
      if (_now - (self._lastApiToastTs || 0) > 600000) {
        self._lastApiToastTs = _now;
        try {
          _yqToast(
            "warning",
            "未配置任务评价/商城/聊天任一独立API，执行摘要无法生成。请在 ⚙️ 设置中配置API",
            "",
            { timeOut: 8000 },
          );
        } catch (_e) {}
      }
      try {
        _yqDbgWarn("[摘要生成器] 所有API通道不可用，跳过本次生成");
      } catch (_e) {}
      self._lastFloor = floor; // 标记已处理，不反复预检
      self._retryCount = 0;
      return;
    }

    self._running = true;
    self._runStartedAt = Date.now();
    self._lastFloor = floor;

    var prompt = self.buildPrompt();
    if (!prompt) {
      self._running = false;
      self._retryCount = 0;
      return;
    }

    _yqDbg(
      "[摘要生成器] 开始生成 (楼层:" +
        floor +
        (self._retryCount > 0 ? " 重试#" + self._retryCount : "") +
        ")",
    );

    callRawApi(
      prompt,
      function (raw) {
        // 如果已被取消，忽略结果
        if (!self._running) return;
        self._running = false;
        // [V9.4.1 FIX #3] 失败时重试一次，两次都失败才提示玩家
        var _isFail = false;
        var _failReason = "";
        var _result = null;
        if (!raw) {
          _isFail = true;
          _failReason = "API返回为空";
        } else {
          _result = self.parseResult(raw);
          if (!_result) {
            _isFail = true;
            _failReason = "JSON解析失败";
          } else {
            // [V10.12·2026-05-19] 有正常任务但 AI 返回 normalTask=null → 视为失败
            //   摘要是任务执行期间每轮的完整剧情记录，不允许跳过
            if (
              self._hasNormalTask() &&
              (!_result.normalTask ||
                _result.normalTask === "null" ||
                typeof _result.normalTask !== "string")
            ) {
              _isFail = true;
              _failReason = "正常任务摘要为空";
            }
          }
        }
        if (_isFail) {
          try {
            _yqDbgWarn(
              "[摘要生成器] " +
                _failReason +
                " (楼层:" +
                floor +
                " 重试#" +
                self._retryCount +
                ")",
            );
          } catch (_e) {}
          // 首次失败 → 5 秒后重试 1 次
          if ((self._retryCount || 0) < 1) {
            self._retryCount = (self._retryCount || 0) + 1;
            setTimeout(function () {
              // 二次触发前检查楼层是否仍然有效（玩家可能已切聊天/删楼）
              try {
                var _c2 = _getCtx();
                if (!_c2 || !_c2.chat || _c2.chat.length !== floor) {
                  self._retryCount = 0;
                  return;
                }
                // 重置 lastFloor 允许重试触发
