function buildMoodAvatarKey(charId, name, moodId) {
  const safeCharId = String(charId || GLOBAL_CHAR_ID);
  const safeName = name.trim().toLowerCase();
  // [V12·2026-05-31 头像key修复] 生图脚本(v71-bubble-batch-runner-v3)把扩展 key
  //   `name__mood__outfit__act` 整个塞进了 moodId 字段。直连写库时它写的是 record.id（单名正确），
  //   但导出→导入 round-trip 会用 moodId 重建 id → 变成 `_global___name__name__mood__...`（双名），
  //   导致气泡查找(_global___name__mood__outfit__act 单名)永远 miss、只能落 L5 兜底主头像。
  //   修复：若 moodId 以 `{safeName}__` 开头，剥离这层冗余前缀，还原成生图脚本的标准单名 key。
  let normMood = String(moodId == null ? "" : moodId);
  const dupPrefix = safeName + CHAR_ID_SEPARATOR;
  if (normMood.indexOf(dupPrefix) === 0) {
    normMood = normMood.slice(dupPrefix.length);
  }
  return (
    safeCharId + CHAR_ID_SEPARATOR + safeName + CHAR_ID_SEPARATOR + normMood
  );
}

function buildColorConfigKey(charId, name) {
  const safeCharId = String(charId || GLOBAL_CHAR_ID);
  const safeName = name.trim().toLowerCase();
  return "color_" + safeCharId + CHAR_ID_SEPARATOR + safeName;
}

function extractDisplayName(storedKey, charId) {
  // 有 charId 时精确切割
  if (charId != null) {
    const prefix = String(charId) + CHAR_ID_SEPARATOR;
    if (storedKey.startsWith(prefix)) return storedKey.slice(prefix.length);
  }
  // 尝试 _global_ 前缀
  const globalPrefix = GLOBAL_CHAR_ID + CHAR_ID_SEPARATOR;
  if (storedKey.startsWith(globalPrefix))
    return storedKey.slice(globalPrefix.length);
  // 回退：数字型 charId 不含下划线，第一个 __ 就是分隔符
  const sepIndex = storedKey.indexOf(CHAR_ID_SEPARATOR);
  return sepIndex >= 0
    ? storedKey.slice(sepIndex + CHAR_ID_SEPARATOR.length)
    : storedKey;
}

function escapeHtmlAttr(value) {
