      cgImgStore.createIndex("group", "group", { unique: false });
    }
    // v1→v2 别名迁移（仅极老库需要）
    if (oldVersion && oldVersion < 2 && tx) {
      try {
        const avatarStore = tx.objectStore(STORE_AVATARS);
        const cursorReq = avatarStore.openCursor();
        const toDelete = [];
        const toAdd = [];
        cursorReq.onsuccess = (e) => {
          const cursor = e.target.result;
          if (cursor) {
            const record = cursor.value;
            if (!record.alias.includes(CHAR_ID_SEPARATOR)) {
              toDelete.push(record.alias);
              toAdd.push({
                ...record,
                alias: GLOBAL_CHAR_ID + CHAR_ID_SEPARATOR + record.alias,
              });
            }
            cursor.continue();
          } else {
            for (const key of toDelete) avatarStore.delete(key);
            for (const rec of toAdd) avatarStore.put(rec);
          }
        };
      } catch (_) {}
    }
  }

  _bindVersionChange(db) {
    // [V13.0.1] 别的连接要升级时本连接主动 close，避免反向阻塞成 blocked
    try {
      db.onversionchange = () => {
        try {
          console.warn(
            "[v71] 检测到其它连接请求 DB 升级，主动关闭本连接以避免阻塞。",
          );
        } catch (_) {}
        try {
          db.close();
        } catch (_) {}
        if (this.db === db) this.db = null;
      };
    } catch (_) {}
  }

  async init() {
    if (this.db) return this.db;
    // [V13.0.2·2026-06-01] 手机端 blocked 根治：不再无条件 open(固定高版本号)。
    //   旧方案 open(6) 对历史 v4/v5 库强制升级，而升级要求所有其它连接先关闭；
    //   手机端常有另一标签页/微信窗口/僵尸 iframe 占用旧版本 → 永久 blocked（实测"打开超时"）。
    //   新策略：先【不带版本号】open——用库的现有版本打开，不触发升级、不会 blocked。
    //   打开后检查 store 是否齐全：齐全(99%)直接用；只有真缺 store 才升一级补建（罕见，
    //   此时多为全新库或本就需要建库，不会被既有连接阻塞）。
    try {
      const db = await this._openNoUpgrade();
      const hasCore =
        db.objectStoreNames.contains(STORE_AVATARS) &&
        db.objectStoreNames.contains(STORE_MOOD_AVATARS) &&
        db.objectStoreNames.contains(STORE_CONFIG) &&
        db.objectStoreNames.contains(STORE_LOCAL_FONTS) &&
        db.objectStoreNames.contains(STORE_CG_GROUPS) &&
        db.objectStoreNames.contains(STORE_CG_IMAGES);
      if (hasCore) {
        this._bindVersionChange(db);
        this.db = db;
        return this.db;
      }
      // 缺 store → 需要升级建库。先记下当前版本，关闭本连接再升一级。
      const curVer = db.version;
      try {
        db.close();
      } catch (_) {}
      const upgraded = await this._openWithUpgrade(curVer + 1);
      this.db = upgraded;
      return this.db;
    } catch (err) {
      // 无版本号路径异常（极少）→ 回退到带版本升级路径兜底
      try {
        console.warn(
          "[v71] 无升级打开失败，回退升级打开:",
          err && (err.message || err),
        );
      } catch (_) {}
      const upgraded = await this._openWithUpgrade(DB_VERSION);
      this.db = upgraded;
      return this.db;
    }
  }

  // [V13.0.2] 不带版本号打开：用库现有版本，绝不触发 upgrade/blocked
  _openNoUpgrade() {
    return new Promise((resolve, reject) => {
      let settled = false;
      const finish = (fn, arg) => {
        if (settled) return;
        settled = true;
        try {
          clearTimeout(tid);
        } catch (_) {}
        fn(arg);
      };
      const tid = setTimeout(() => {
        finish(reject, new Error("IndexedDB 打开超时（无升级路径）"));
      }, 8000);
      let request;
      try {
        request = indexedDB.open(DB_NAME); // 不带版本号
      } catch (e) {
        finish(reject, e);
        return;
      }
      request.onsuccess = (event) => finish(resolve, event.target.result);
      request.onerror = (event) =>
        finish(
          reject,
          new Error(
            "IndexedDB 打开失败: " +
              (event.target.error && event.target.error.name),
          ),
        );
      // 不带版本号理论上不会 upgrade/blocked；万一空库会触发 onupgradeneeded（version 1 建库）
      request.onupgradeneeded = (event) => {
        try {
          this._createStores(
            event.target.result,
            event.target.transaction,
            event.oldVersion,
          );
        } catch (_) {}
      };
      request.onblocked = () => {
        try {
          console.warn("[v71] 无升级打开被阻塞（异常，通常不应发生）。");
        } catch (_) {}
      };
    });
  }

  // [V13.0.2] 带版本号升级打开：仅在缺 store 时调用，补建缺失 store
  _openWithUpgrade(version) {
    return new Promise((resolve, reject) => {
      let settled = false;
      const finish = (fn, arg) => {
        if (settled) return;
        settled = true;
        try {
          clearTimeout(tid);
        } catch (_) {}
        fn(arg);
      };
      const tid = setTimeout(() => {
        try {
          console.warn(
            "[v71] IndexedDB 升级打开超时（8s，疑似被其它连接 blocked）。" +
              "请关闭其它打开本卡的标签页 / 硬刷新页面后重试。",
          );
        } catch (_) {}
        finish(reject, new Error("IndexedDB 打开超时（疑似 blocked）"));
      }, 8000);
      let request;
      try {
        request = indexedDB.open(DB_NAME, version);
      } catch (e) {
        finish(reject, e);
        return;
      }
      request.onupgradeneeded = (event) => {
        try {
          this._createStores(
            event.target.result,
            event.target.transaction,
            event.oldVersion,
          );
        } catch (_) {}
      };
      request.onblocked = () => {
        try {
          console.warn(
            "[v71] IndexedDB 升级被阻塞（onblocked）：有其它标签页/iframe 占用旧版本库，等待释放或超时。",
          );
        } catch (_) {}
      };
      request.onsuccess = (event) => {
        const db = event.target.result;
        this._bindVersionChange(db);
        finish(resolve, db);
      };
      request.onerror = (event) =>
        finish(
          reject,
          new Error(
            "IndexedDB 打开失败: " +
              (event.target.error && event.target.error.name),
          ),
        );
    });
  }

  async _ensureDB() {
    if (!this.db) await this.init();
  }

  // -- 头像 CRUD --

  async add(charId, name, imageBlob, metadata = {}) {
    await this._ensureDB();
    const key = buildAvatarKey(charId, name);
    const existing = await this.get(charId, name);
    if (existing)
      throw new Error(
        `角色名 "${name}" 已存在，请使用 update() 或换一个角色名`,
      );
    const record = {
      alias: key,
      imageBlob,
      sourceUrl: metadata.sourceUrl || null,
      mimeType: imageBlob
        ? imageBlob.type || "image/jpeg"
        : metadata.mimeType || "image/webp",
      fileName: metadata.fileName || `${name.trim().toLowerCase()}.jpg`,
      fileSize: imageBlob ? imageBlob.size : 0,
      width: metadata.width || 0,
      height: metadata.height || 0,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    return this._put(STORE_AVATARS, record);
  }

  async get(charId, name) {
    await this._ensureDB();
    const key = buildAvatarKey(charId, name);
    return this._getByKey(STORE_AVATARS, key);
  }

  async getBlobUrl(charId, name) {
    const key = buildAvatarKey(charId, name);
    if (this._blobUrlCache.has(key)) return this._blobUrlCache.get(key);
    const record = await this.get(charId, name);
    if (!record || !record.imageBlob) return null;
    const url = URL.createObjectURL(record.imageBlob);
    this._blobUrlCache.set(key, url);
    return url;
  }

  async update(charId, name, imageBlob, metadata = {}) {
    await this._ensureDB();
    const key = buildAvatarKey(charId, name);
    const existing = await this.get(charId, name);
    if (!existing) throw new Error(`角色名 "${name}" 不存在`);
    this._revokeCachedUrl(key);
    const record = {
      ...existing,
      imageBlob,
      sourceUrl:
        metadata.sourceUrl !== undefined
          ? metadata.sourceUrl
          : existing.sourceUrl || null,
      mimeType: imageBlob.type || existing.mimeType,
      fileName: metadata.fileName || existing.fileName,
      fileSize: imageBlob.size,
      width: metadata.width || existing.width,
      height: metadata.height || existing.height,
      updatedAt: Date.now(),
    };
    return this._put(STORE_AVATARS, record);
  }

  async rename(charId, oldName, newName) {
    await this._ensureDB();
    const oldKey = buildAvatarKey(charId, oldName);
    const newKey = buildAvatarKey(charId, newName);
    if (oldKey === newKey) return;
    if (await this.get(charId, newName))
      throw new Error(`角色名 "${newName}" 已被占用`);
    const record = await this.get(charId, oldName);
    if (!record) throw new Error(`角色名 "${oldName}" 不存在`);
    this._revokeCachedUrl(oldKey);
    const newRecord = { ...record, alias: newKey, updatedAt: Date.now() };
    await new Promise((resolve, reject) => {
      const tx = this.db.transaction(STORE_AVATARS, "readwrite");
      const store = tx.objectStore(STORE_AVATARS);
      const del = store.delete(oldKey);
      del.onsuccess = () => {
        const add = store.put(newRecord);
        add.onsuccess = () => resolve();
        add.onerror = () => reject(new Error(`重命名写入失败`));
      };
      del.onerror = () => reject(new Error(`重命名删除失败`));
    });
    // [V12·2026-05-31 改名同步修复] rename 必须同步迁移情绪差分头像，
    //   否则改名后 mood_avatars 仍挂旧 alias，气泡查找新名 miss → 永远兜底主头像。
    //   把 STORE_MOOD_AVATARS 里 alias===oldName 的所有条目重建 id + alias 到 newName。
    await this._renameMoodAvatars(charId, oldName, newName);
  }

  async _renameMoodAvatars(charId, oldName, newName) {
    const moodAvatars = await this.listMoodAvatars(charId, oldName);
    if (!moodAvatars || moodAvatars.length === 0) return;
    const safeCharId = String(charId || GLOBAL_CHAR_ID);
    const tx = this.db.transaction(STORE_MOOD_AVATARS, "readwrite");
    const store = tx.objectStore(STORE_MOOD_AVATARS);
    for (const ma of moodAvatars) {
      // 旧缓存 URL 失效
      const oldCacheKey = "mood_" + ma.id;
      if (this._blobUrlCache.has(oldCacheKey)) {
        URL.revokeObjectURL(this._blobUrlCache.get(oldCacheKey));
        this._blobUrlCache.delete(oldCacheKey);
      }
      // 新 key（buildMoodAvatarKey 会处理冗余前缀剥离）
      const newId = buildMoodAvatarKey(safeCharId, newName, ma.moodId);
      const newRec = {
        ...ma,
        id: newId,
        charId: safeCharId,
        alias: newName.trim().toLowerCase(),
        updatedAt: Date.now(),
      };
      store.delete(ma.id);
      store.put(newRec);
    }
    return new Promise((resolve, reject) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(new Error(`情绪差分改名失败`));
    });
  }

  async delete(charId, name) {
    await this._ensureDB();
    const key = buildAvatarKey(charId, name);
    this._revokeCachedUrl(key);
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(STORE_AVATARS, "readwrite");
      const req = tx.objectStore(STORE_AVATARS).delete(key);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(new Error(`删除失败`));
    });
  }

  async list(charId) {
    await this._ensureDB();
    const safeCharId = String(charId || GLOBAL_CHAR_ID);
    const prefix = safeCharId + CHAR_ID_SEPARATOR;
    const range = IDBKeyRange.bound(prefix, prefix + "\uffff", false, false);
    return new Promise((resolve, reject) => {
      const req = this.db
        .transaction(STORE_AVATARS, "readonly")
        .objectStore(STORE_AVATARS)
        .getAll(range);
      req.onsuccess = () => {
        resolve(
          req.result.map((r) => ({
            alias: r.alias,
            displayName: extractDisplayName(r.alias, safeCharId),
            mimeType: r.mimeType,
            fileName: r.fileName,
            fileSize: r.fileSize,
            width: r.width,
            height: r.height,
            createdAt: r.createdAt,
            updatedAt: r.updatedAt,
          })),
        );
      };
      req.onerror = () => reject(new Error(`列表查询失败`));
    });
  }

  async getStats(charId) {
    await this._ensureDB();
    const prefix = String(charId || GLOBAL_CHAR_ID) + CHAR_ID_SEPARATOR;
    const range = IDBKeyRange.bound(prefix, prefix + "\uffff", false, false);
    return new Promise((resolve, reject) => {
      const req = this.db
        .transaction(STORE_AVATARS, "readonly")
        .objectStore(STORE_AVATARS)
        .getAll(range);
      req.onsuccess = () => {
        const records = req.result;
        resolve({
          count: records.length,
          totalSize: records.reduce((s, r) => s + (r.fileSize || 0), 0),
        });
      };
      req.onerror = () => reject(new Error(`统计查询失败`));
    });
  }

  // -- 情绪差分头像 CRUD --

  async addMoodAvatar(charId, name, moodId, imageBlob, metadata = {}) {
    await this._ensureDB();
    const id = buildMoodAvatarKey(charId, name, moodId);
    const safeName = name.trim().toLowerCase();
    const safeCharId = String(charId || GLOBAL_CHAR_ID);
    // [V12·2026-05-31 头像key修复] moodId 字段同样剥离冗余 `{name}__` 前缀，
    //   保证 id 与 moodId 字段一致（避免再次导出时 round-trip 又双名）。
    let normMoodId = String(moodId == null ? "" : moodId);
    const _dupPrefix = safeName + CHAR_ID_SEPARATOR;
    if (normMoodId.indexOf(_dupPrefix) === 0) {
      normMoodId = normMoodId.slice(_dupPrefix.length);
    }
    const record = {
      id,
      charId: safeCharId,
      alias: safeName,
      moodId: normMoodId,
      imageBlob,
      mimeType: imageBlob
        ? imageBlob.type || "image/jpeg"
        : metadata.mimeType || "image/webp",
      fileName: metadata.fileName || `${safeName}-${normMoodId}.jpg`,
      fileSize: imageBlob ? imageBlob.size : 0,
      width: metadata.width || 0,
      height: metadata.height || 0,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    return this._put(STORE_MOOD_AVATARS, record);
  }

  async getMoodAvatar(charId, name, moodId) {
    await this._ensureDB();
    const id = buildMoodAvatarKey(charId, name, moodId);
    return this._getByKey(STORE_MOOD_AVATARS, id);
  }

  async getMoodAvatarBlobUrl(charId, name, moodId) {
    const cacheKey = "mood_" + buildMoodAvatarKey(charId, name, moodId);
    if (this._blobUrlCache.has(cacheKey))
      return this._blobUrlCache.get(cacheKey);
    const record = await this.getMoodAvatar(charId, name, moodId);
    if (!record || !record.imageBlob) return null;
    const url = URL.createObjectURL(record.imageBlob);
    this._blobUrlCache.set(cacheKey, url);
    return url;
  }

  async listMoodAvatars(charId, name) {
    await this._ensureDB();
    const safeName = name.trim().toLowerCase();
    const safeCharId = String(charId || GLOBAL_CHAR_ID);
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(STORE_MOOD_AVATARS, "readonly");
      const index = tx.objectStore(STORE_MOOD_AVATARS).index("charId");
      const req = index.getAll(IDBKeyRange.only(safeCharId));
      req.onsuccess = () => {
        resolve(req.result.filter((r) => r.alias === safeName));
      };
      req.onerror = () => reject(new Error(`情绪差分列表查询失败`));
    });
  }

  async deleteMoodAvatar(charId, name, moodId) {
    await this._ensureDB();
    const id = buildMoodAvatarKey(charId, name, moodId);
    const cacheKey = "mood_" + id;
    if (this._blobUrlCache.has(cacheKey)) {
      URL.revokeObjectURL(this._blobUrlCache.get(cacheKey));
      this._blobUrlCache.delete(cacheKey);
    }
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction(STORE_MOOD_AVATARS, "readwrite");
      const req = tx.objectStore(STORE_MOOD_AVATARS).delete(id);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(new Error(`情绪差分删除失败`));
    });
  }

  async deleteAllMoodAvatars(charId, name) {
    await this._ensureDB();
    const moodAvatars = await this.listMoodAvatars(charId, name);
    const tx = this.db.transaction(STORE_MOOD_AVATARS, "readwrite");
    const store = tx.objectStore(STORE_MOOD_AVATARS);
    for (const ma of moodAvatars) {
      store.delete(ma.id);
      const cacheKey = "mood_" + ma.id;
      if (this._blobUrlCache.has(cacheKey)) {
        URL.revokeObjectURL(this._blobUrlCache.get(cacheKey));
        this._blobUrlCache.delete(cacheKey);
      }
    }
    return new Promise((resolve, reject) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(new Error(`情绪差分批量删除失败`));
    });
  }

  // -- 本地字体 CRUD --

  _buildLocalFontId(family) {
