      const req = this.db
        .transaction(STORE_CONFIG, "readonly")
        .objectStore(STORE_CONFIG)
        .getAll();
      req.onsuccess = () => {
        const config = {};
        req.result.forEach((r) => {
          config[r.key] = r.value;
        });
        resolve(config);
