    $("#bam-val-narration-border-radius").textContent =
      `${settings.style_narrationBorderRadius}px`;
    $("#bam-range-thought-suffix-gap").value = settings.style_thoughtSuffixGap;
    $("#bam-val-thought-suffix-gap").textContent =
      `${settings.style_thoughtSuffixGap}px`;
    $("#bam-range-thought-suffix-offset-y").value =
      settings.style_thoughtSuffixOffsetY;
    $("#bam-val-thought-suffix-offset-y").textContent =
      `${settings.style_thoughtSuffixOffsetY}px`;
    // v7.0
    if ($("#bam-range-narration-text-indent")) {
      $("#bam-range-narration-text-indent").value =
        settings.style_narrationTextIndent;
      $("#bam-val-narration-text-indent").textContent =
        `${settings.style_narrationTextIndent}em`;
    }
    if ($("#bam-range-narration-line-height")) {
      $("#bam-range-narration-line-height").value =
        settings.style_narrationLineHeight;
