        settings.style_imageCompressEnabled !== "false";
    }
    if ($("#bam-range-compress-quality")) {
      $("#bam-range-compress-quality").value =
        settings.style_imageCompressQuality;
      $("#bam-val-compress-quality").textContent =
        `${Number(settings.style_imageCompressQuality).toFixed(2)}`;
    }
    $("#bam-font-url-input").value = settings.style_fontConfigUrl || "";

    doc.querySelectorAll('input[name="bam-color-mode"]').forEach((radio) => {
