  }

  // [V13.2·2026-06-01 手机端注入修复] 注入与 DB init 解耦：
  //   旧逻辑把首次注入挂在 init().then() 里，手机端 IDB blocked/超时 → init 走 .catch
  //   → 首次注入完全不执行（提示词管理器看不到格式规则）。
  //   现在：先无条件注入（buildInjectionPrompt 内部已容错，DB 读不到就用 DEFAULT 常量），
  //   再后台跑 init() 加载头像库；init 成功后再注入一次以应用玩家自定义的 format_rule。
  applyInjection(avatarDB).catch((err) =>
    console.warn("[BubbleDialogue] 首次注入失败:", err),
  );

  avatarDB
    .init()
    .then(() => {
      // DB 就绪后重注入一次，应用玩家在面板里自定义的格式规则/情绪配置
      invalidateInjectionCache();
      applyInjection(avatarDB);
    })
    .catch((err) => {
      console.warn(
        "[BubbleDialogue] DB 初始化失败（注入已用默认规则生效，不受影响）:",
        err,
      );
    });

  injectWandMenuItem();
  // v7.0: 定期重注入魔法棒按钮（酒馆菜单重建或脚本热重载时旧按钮事件会失效）
  setInterval(injectWandMenuItem, 5000);

  // 监听聊天切换事件，重新注入（injectPrompts 注入仅在当前聊天有效）
  try {
    if (typeof tavern_events !== "undefined" && tavern_events.CHAT_CHANGED) {
      eventOn(tavern_events.CHAT_CHANGED, () => {
        invalidateInjectionCache();
        applyInjection(avatarDB);
      });
    }
  } catch (e) {
    console.warn("[BubbleDialogue] 无法监听 CHAT_CHANGED 事件:", e);
