  function _injectCSS() {
    var doc = _yqGetMainDoc();
    var existing = doc.getElementById("yq-bubble-lite-style");
    var css = _buildCSS(_bridgeCfg || YQ_DEFAULTS);
    if (existing) {
      // 配置变更时更新现有样式(不重建)
      if (existing.textContent !== css) existing.textContent = css;
      return;
    }
    var style = doc.createElement("style");
    style.id = "yq-bubble-lite-style";
    style.textContent = css;
    (doc.head || doc.body || doc.documentElement).appendChild(style);
  }

  // -------- 大图查看 --------
  function _showZoom(src, alt) {
    var doc = _yqGetMainDoc();
    var old = doc.getElementById("yq-avatar-zoom");
    if (old) old.remove();
    var overlay = doc.createElement("div");
    overlay.id = "yq-avatar-zoom";
    overlay.className = "yq-avatar-zoom-overlay";
    var img = doc.createElement("img");
    img.src = src;
    img.alt = alt || "";
    overlay.appendChild(img);
    overlay.addEventListener("click", function () {
      overlay.remove();
    });
    doc.body.appendChild(overlay);
  }

  function _firstChar(name) {
    var t = String(name || "").trim();
    if (!t) return "?";
    var arr = Array.from(t);
    return arr[0] || "?";
  }

  function _renderThought(textEl) {
    if (!textEl || textEl.dataset.yqThoughtDone) return false;
    var html = textEl.innerHTML;
    if (html.indexOf("*") < 0) {
      textEl.dataset.yqThoughtDone = "1";
      return false;
    }
    var hasThought = false;
    var newHtml = html.replace(/\*([^*\n]+)\*/g, function (m, inner) {
      hasThought = true;
      return "<em>" + inner + "</em>";
    });
    if (newHtml !== html) textEl.innerHTML = newHtml;
    textEl.dataset.yqThoughtDone = "1";
    return hasThought;
  }

  function _hydrateBubble(bubble) {
