  function _hydrateAll() {
    var doc = _yqGetMainDoc();
    var els = doc.querySelectorAll(
      ".yq-bubble:not([data-yq-hydrated]), .custom-yq-bubble:not([data-yq-hydrated])",
    );
    for (var i = 0; i < els.length; i++) _hydrateBubble(els[i]);
  }

  // [V12·2026-05-31 问题3] 导入新头像后强制刷新：清 blob url 缓存 + 撤销旧 URL +
  //   去掉所有已渲染气泡的 hydrated 标记，重新 hydrate（已存在的气泡立即换新头像）。
  //   不刷新浏览器。
  function _refreshAvatars() {
    try {
      for (var k in _urlCache) {
        if (_urlCache.hasOwnProperty(k)) {
          try {
            URL.revokeObjectURL(_urlCache[k]);
          } catch (e) {}
          delete _urlCache[k];
        }
      }
    } catch (e) {}
    try {
      var doc = _yqGetMainDoc();
      var els = doc.querySelectorAll(".yq-bubble, .custom-yq-bubble");
      for (var i = 0; i < els.length; i++) {
        var b = els[i];
        delete b.dataset.yqHydrated;
        b.removeAttribute("data-yq-hydrated");
        var img = b.querySelector(
          ".yq-bubble-avatar, .custom-yq-bubble-avatar",
        );
        if (
          img &&
          img.tagName === "IMG" &&
          !img.getAttribute("data-lazy-mood")
        ) {
          img.setAttribute("data-lazy-mood", b.getAttribute("data-mood") || "");
        }
      }
    } catch (e) {}
    _hydrateAll();
  }

  // -------- v7.1 配置变更监听 --------
  // v7.1 没有 config 变更事件,但点 "对话气泡" 面板 → 修改 → 保存后,我们可以:
  //   1. 监听 character_message_rendered/chat_changed 时顺便 reload(成本低)
  //   2. 提供 __yqBubbleLite.reloadConfig() 手动接口(用户保存后可点)
  function _reloadConfig() {
    return _loadBridgeConfig().then(function () {
      _injectCSS();
      // 清头像 url 缓存(blob URL 不变,但 hydration 标记重置 → 让所有气泡重 hydrate 一次会改样式)
      // 实际上 CSS 是基于 class 的,改 style 元素就能立刻生效,无需重 hydrate
      return _bridgeCfg;
    });
  }

  function _bindEvents() {
    try {
      var es =
        window.parent.eventSource ||
        window.parent.SillyTavern?.getContext()?.eventSource;
      var et =
        window.parent.event_types ||
        window.parent.SillyTavern?.getContext()?.event_types;
      if (!es || !et) return false;

      var renderEvt =
        et.CHARACTER_MESSAGE_RENDERED || "character_message_rendered";
      var userEvt = et.USER_MESSAGE_RENDERED || "user_message_rendered";
      var chatEvt = et.CHAT_CHANGED || "chat_changed";

      [renderEvt, userEvt, chatEvt].forEach(function (ev) {
        try {
          es.on(ev, function () {
            setTimeout(_hydrateAll, 50);
          });
        } catch (e) {}

        // [V12·2026-05-31 问题1] 流式闪烁修复：跟踪生成态。
        //   流式中 ST 每个 token 重写 mes_text innerHTML → 已 hydrate 的气泡被推倒重建 →
        //   observer 反复 re-hydrate → 头像反复加载 = 闪烁。
        //   对策：生成中把 observer debounce 拉长（_genDebounce），减少重 hydrate 频率；
        //   生成结束后做一次确定性 hydrate（此时 DOM 稳定，不再闪）。
        try {
          var genStart = et.GENERATION_STARTED || "generation_started";
          var genEnd = et.GENERATION_ENDED || "generation_ended";
          var genStop = et.GENERATION_STOPPED || "generation_stopped";
          es.on(genStart, function () {
            _isGenerating = true;
          });
          [genEnd, genStop].forEach(function (gev) {
            try {
              es.on(gev, function () {
                _isGenerating = false;
                // 生成结束 DOM 稳定，做确定性 hydrate（延迟让最后一次 ST 重写落定）
                setTimeout(_hydrateAll, 120);
              });
            } catch (e) {}
          });
        } catch (e) {}
      });
      // [V12] 切聊天时重建名字索引（新聊天可能有新角色）
      try {
        es.on(chatEvt, function () {
          _buildNameIndex();
        });
      } catch (e) {}
      return true;
    } catch (e) {
      return false;
    }
  }

  // [V12·2026-05-30 问题4] 常驻流式增量 hydrate observer。
  //   原来 MutationObserver 只在事件绑定失败时作 fallback；现改为常驻，
  //   让流式生成过程中新出现的 .yq-bubble 即时打头像+颜色（不必等整条消息渲染完）。
  //   _hydrateBubble 幂等（data-yqHydrated 去重）+ 成形守卫，重复扫描安全。
  //   debounce 80ms 合并流式高频 DOM 变化；只在有新增节点时触发。
  var _streamObserver = null;
  var _isGenerating = false;
  function _startStreamObserver() {
    if (_streamObserver) return;
    try {
      var doc = _yqGetMainDoc();
      var target = doc.body || doc.documentElement;
      if (!target) return;
      _streamObserver = new MutationObserver(function (mutations) {
        // 仅在确有 childList 新增时调度，避免纯属性变化空转
        var hasAdded = false;
